#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Reader (MCP3008 CH0)\n");
    printf("Sampling every 1 second. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Error reading moisture level\n");
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            if (timeinfo != NULL) {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                printf("[%s] Moisture Level: %d\n", timestamp, moisture_level);
            } else {
                printf("[timestamp error] Moisture Level: %d\n", moisture_level);
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

