#include <errno.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x01
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_CMODE_CONT 0x0000
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE | ADS1115_CONFIG_CMODE_CONT)
#define ADS1115_REG_CONFIG_VAL (ADS1115_CONFIG_DEFAULT << 15)
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 100
#define BUZZER_DURATION_MS 2000
#define TEMP_THRESHOLD_C 60.0
#define LOG_FILE_NAME "fire_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void log_temperature(double temp) {
    char buf[64];
    snprintf(buf, sizeof(buf), "Temperature: %.2f C", temp);
    log_event(buf);
}

static void log_fire_event(void) {
    log_event("Fire detected!");
}

static int read_flame_sensor(void) {
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    gpioDelay(10000);
    int val = gpioRead(FLAME_SENSOR_GPIO);
    if (val < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    int val2 = gpioRead(FLAME_SENSOR_GPIO);
    if (val2 < 0) {
        fprintf(stderr, "Failed to read GPIO %d after debounce\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return (val == val2) ? 1 : 0;
}

static int read_heat_sensor(double *temp) {
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C handle invalid\n");
        return -1;
    }
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_DEFAULT >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_DEFAULT & 0xFF;
    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write ADS1115 config: %s\n", strerror(errno));
        return -1;
