            fprintf(stderr, "Warning: ADC value at extreme (%d) - sensor may be absent\n",
                    adc_value);
        }

        float current = calculate_current(adc_value);
        if (current < 0.0f) {
            fprintf(stderr, "Error calculating current\n");
        } else {
            if (log_current(current) < 0) {
                fprintf(stderr, "Error logging current\n");
            }
            if (control_fan(current) < 0) {
                fprintf(stderr, "Error controlling fan\n");
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

