#define I2C_BUS 1
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

/*
 * Calibration parameters (example values - replace with your sensor's calibration data)
 * Resistance at 0 ppm CO (in ohms)
 * Slope of the logarithmic curve (log(CO) = slope * log(R) + intercept)
 */
#define ZERO_CO_RESISTANCE 1000.0f
#define SLOPE 0.01f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Reads the raw 16-bit ADC value from the MICS-4514 via I2C.
 * Returns 0 on success, -1 on failure.
 */
static int read_raw_sensor_data(int handle, int16_t *raw_value) {
    char buffer[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadDevice(handle, buffer, 2);
        if (result == 2) {
            *raw_value = (int16_t)((buffer[0] << 8) | buffer[1]);
            return 0;
        }
        fprintf(stderr, "Warning: I2C read attempt %d failed (returned %d)\n", attempt + 1, result);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000); /* 100 ms backoff before retry */
        }
    }
    return -1;
}

/*
 * Converts the raw sensor value to a CO concentration in ppm.
 * Uses a logarithmic curve: ppm = exp(SLOPE * log(R) + INTERCEPT)
 * where R is the sensor resistance.
 */
static float calculate_ppm(int16_t raw_value) {
    float resistance = (float)raw_value;
    float ppm = expf(SLOPE * logf(resistance) + INTERCEPT);
    return ppm;
}

/*
 * Logs the CO concentration to a file.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f ppm\n", timestamp, ppm);
    fclose(fp);
    return 0;
}

