    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection to the MICS-4514 */
    i2c_handle = i2cOpen(I2C_BUS, 0x74, 0); /* ADS1115 default address 0x74 */
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: Failed to set SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: Failed to set SIGTERM handler");
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw_value = 0;

        if (read_raw_sensor_data(i2c_handle, &raw_value) != 0) {
            fprintf(stderr, "Error: Failed to read sensor data after %d retries. Sensor may be disconnected or bus error.\n", MAX_RETRIES);
