            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, 0x74, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to re-open I2C device. Exiting.\n");
                break;
            }
            continue;
        }

        float ppm = calculate_ppm(raw_value);

        if (log_data(ppm) != 0) {
            fprintf(stderr, "Warning: Failed to log data.\n");
        }

        printf("CO concentration: %.2f ppm\n", ppm);

        /* Sleep for the sample interval, checking running flag every second */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    /* Clean up resources */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nCO sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

