#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define LOG_FILE "flame_data.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_flame_sensor(void) {
    int level = gpioRead(FLAME_SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return (level == 1) ? 1 : 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01  start bit
     *   tx[1] = (0x08 | channel) << 4  SGL/DIFF=1, D2 D1 D0 = channel
     *   tx[2] = 0x00  padding
     * Result: 10-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static int log_data(int flame_present, int adc_value, const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for appending\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, flame_present, adc_value) < 0) {
        fprintf(stderr, "Error: writing to %s failed\n", filename);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed on %s\n", filename);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for flame sensor pin %d\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_present = read_flame_sensor();
        if (flame_present < 0) {
            fprintf(stderr, "Error: flame sensor read failed, skipping sample\n");
        } else {
            int adc_value = read_mcp3008(0);
            if (adc_value < 0) {
                fprintf(stderr, "Error: MCP3008 read failed, skipping sample\n");
            } else {
                if (log_data(flame_present, adc_value, LOG_FILE) != 0) {
                    fprintf(stderr, "Error: failed to log data\n");
                } else {
                    printf("Flame: %d, ADC: %d\n", flame_present, adc_value);
                }
            }
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

