#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define CO_THRESHOLD 25.0f
#define LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint16_t *co_value, uint16_t *no2_value) {
    char buffer[4];
    int bytes_read = i2cReadDevice(handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error: I2C read failed (expected 4 bytes, got %d)\n", bytes_read);
        return -1;
    }
    *co_value = ((uint16_t)(buffer[0] & 0xFF) << 8) | (uint8_t)buffer[1];
    *no2_value = ((uint16_t)(buffer[2] & 0xFF) << 8) | (uint8_t)buffer[3];
    return 0;
}

static float convert_to_ppm(uint16_t raw_value) {
    return (float)raw_value * 0.0001f;
}

static int log_data(float co_ppm, const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f ppm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

static int log_alert(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening alert log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO exceeds threshold!\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t raw_co = 0, raw_no2 = 0;
        if (read_sensor_data(i2c_handle, &raw_co, &raw_no2) == 0) {
            float co_ppm = convert_to_ppm(raw_co);
            printf("CO: %.2f ppm\n", co_ppm);
            if (co_ppm >= CO_THRESHOLD) {
                printf("Alert: CO exceeds threshold!\n");
                if (log_alert(ALERT_LOG_FILE) != 0) {
                    fprintf(stderr, "Warning: failed to log alert\n");
                }
            }
            if (log_data(co_ppm, LOG_FILE) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

