/*
 * IMP23ABSU dual-channel sound pressure level logger for Raspberry Pi 4.
 *
 * Wiring (BCM numbering):
 *   IMP23ABSU OUT1 -> GPIO2  (I2C SDA)
 *   IMP23ABSU OUT2 -> GPIO3  (I2C SCL)
 *   IMP23ABSU VDD  -> 3.3 V
 *   IMP23ABSU GND  -> GND
 *
 * The IMP23ABSU analog output is a 12-bit left-justified 10-bit
 * (0..1023) digital value.  A 12-bit left-justified value in 10 bits
 * is equivalent to a 12-bit signed value in 10 bits, which is
 * 127 + (12-12) * (value / 1023) = 127 + (12-12) * (value / 1023) = 127 + (value / 1023)
 * = 127 + 0.0009765625 * value.  We round to the nearest integer.
 *
 * Build:  gcc -O2 -Wall -o audio_logger audio_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

#define I2C_BUS        1
#define SAMPLE_US      100000   /* 100 ms */
#define LOG_FILE       "audio_log.txt"
#define ERROR_VALUE    (-999.0f)

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                        */
/* ------------------------------------------------------------------ */

/*
 * Read a single byte from an I2C slave address.
 * Returns 0..255 on success, or -1 on error.
 */
static int i2c_read_byte(int handle, uint8_t addr)
{
    int v = i2cReadByteData(handle, addr);
    if (v < 0)
        fprintf(stderr, "i2cReadByteData(addr=0x%02X) failed: %s\n",
                addr, pigpio_error(v));
    return v;
}

/*
 * Write a single byte to an I2C slave address.
 * Returns 0 on success, or -1 on error.
 */
static int i2c_write_byte(int handle, uint8_t addr, uint8_t val)
{
    int rc = i2cWriteByteData(handle, addr, val);
    if (rc < 0)
        fprintf(stderr, "i2cWriteByteData(addr=0x%02X, val=0x%02X) failed: %s\n",
                addr, val, pigpio_error(rc));
    return rc;
}

/*
 * Read a 10-bit signed value from an I2C slave address.
 * Returns 0..1023 on success, or -1 on error.
 */
static int i2c_read_10bit(int handle, uint8_t addr)
{
    int lo = i2c_read_byte(handle, addr);
    if (lo < 0)
        return -1;

    int hi = i2c_read_byte(handle, addr);
    if (hi < 0)
        return -1;

    return (lo << 4) | (hi & 0x0F);
}

/* ------------------------------------------------------------------ */
/* Microphone driver                                                 */
/* ------------------------------------------------------------------ */

/*
 * Read a 10-bit signed value from the left channel of an IMP23ABSU
 * microphone connected to GPIO2 (I2C SDA) and GPIO3 (I2C SCL).
 * Returns 0..1023 on success, or -1 on error.
 */
static int read_microphone(int handle)
{
    int v = i2c_read_10bit(handle, 0x00);
    if (v < 0)
        return -1;
    return v;
}

/*
 * Compute the sound pressure level in dB relative to 0 dB SPL.
 * IMP23ABSU: 10-bit left-justified 10-bit value -> 127 + 0.0009765625 * value.
 * Round to nearest integer.
 */
static float calculate_level(int raw)
{
    float level = 127.0f + 0.0009765625f * (float)raw;
    return (int)level;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_data(float level1, float level2, const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, level1, level2);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle1 = i2cOpen(I2C_BUS, 0x00, 0);
    if (handle1 < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x00) failed: %s\n",
                I2C_BUS, pigpio_error(handle1));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int handle2 = i2cOpen(I2C_BUS, 0x01, 0);
    if (handle2 < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x01) failed: %s\n",
                I2C_BUS, pigpio_error(handle2));
        i2cClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio logging started.  Press Ctrl+C to stop.\n");

    while (g_running) {
        int raw1 = read_microphone(handle1);
        int raw2 = read_microphone(handle2);

        float level1 = ERROR_VALUE;
        float level2 = ERROR_VALUE;

        if (raw1 >= 0)
            level1 = calculate_level(raw1);
        if (raw2 >= 0)
            level2 = calculate_level(raw2);

        log_data(level1, level2, LOG_FILE);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

