/* Global flag for signal handling */
static volatile sig_atomic_t running = 1;

/* Signal handler for SIGINT (Ctrl+C) */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a single-ended sample from the MCP3008 */
static int read_adc(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * tx[0] = 0x01 (start bit)
     * tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     * tx[2] = 0x00 (don't care)
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* Compute the RMS of a vector of samples */
static double calculate_rms(const int *samples, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return sqrt(sum_sq / num_samples);
}

/* Log data to a CSV file */
static int log_data(const char *filename, double mic1_rms, double mic2_rms) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening file for logging");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms) < 0) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }

    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Configure MCP3008 chip select pins */
    if (gpioSetMode(CS0_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(CS1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set CS pins as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(CS0_PIN, 1);
    gpioWrite(CS1_PIN, 1);

    /* Open SPI channel */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio event detection started. Press Ctrl+C to exit.\n");

    int samples1[WINDOW_SIZE];
    int samples2[WINDOW_SIZE];
    int sample_index1 = 0, sample_index2 = 0;
    int led_on = 0;
    int error_flag = 0;

    while (running) {
        int adc1 = read_adc(spi_handle, ADC_CHANNEL_1);
        int adc2 = read_adc(spi_handle, ADC_CHANNEL_2);

        if (adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            error_flag = 1;
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        samples1[sample_index1] = adc1;
        samples2[sample_index2] = adc2;
        sample_index1 = (sample_index1 + 1) % WINDOW_SIZE;
        sample_index2 = (sample_index2 + 1) % WINDOW_SIZE;

        double rms1 = calculate_rms(samples1, WINDOW_SIZE);
        double rms2 = calculate_rms(samples2, WINDOW_SIZE);

        if (log_data("audio_events.csv", rms1, rms2) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        if (rms1 > RMS_THRESHOLD || rms2 > RMS_THRESHOLD) {
            if (!led_on) {
                gpioWrite(LED_PIN, 1);
                led_on = 1;
                printf("RMS threshold exceeded! LED ON\n");
            }
        } else {
            if (led_on) {
                gpioWrite(LED_PIN, 0);
                led_on = 0;
                printf("RMS below threshold. LED OFF\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();

    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

