/*
 * Raspberry Pi 4 Model B – MLX91204 Hall effect current sensor monitor
 *
 * Hardware:
 *   - ADS1115 ADC on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *   - MLX91204 Hall sensor output wired to ADS1115 A0
 *   - Warning LED on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -li2c
 *
 * Run:
 *   sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48

#define ADS1115_REG_CONV  0x00
#define ADS1115_REG_CFG   0x01

/*
 * Config word (16-bit) for ADS1115:
 *   Bit 15    OS       = 1  (start single conversion)
 *   Bits14:12 MUX     = 100 (AIN0 single-ended)
 *   Bits11:9  PGA      = 001 (±4.096 V)
 *   Bit  8    MODE     = 1  (single-shot)
 *   Bits7:5   DR       = 100 (128 SPS)
 *   Bit  4    COMP_MODE= 0
 *   Bit  3    COMP_POL = 0
 *   Bit  2    COMP_LAT = 0
 *   Bit  1    COMP_QUE = 11 (disable comparator)
 *   Bit  0    COMP_LAT_QUE = 0
 * -> 0xC183
 */
#define ADS1115_CFG_BASE  0xC183

#define LED_PIN          17
#define BUFFER_SIZE      100
#define SAMPLE_RATE_HZ   10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define CURRENT_THRESHOLD 50.0f

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  i2c_write_reg16(int fd, uint8_t reg, uint16_t val);
static int  i2c_read_reg16(int fd, uint8_t reg, uint16_t *out);
static int  ads1115_init(int fd);
static int  ads1115_read_channel(int fd, uint16_t *raw_out);
static float raw_to_current(uint16_t raw);
static void  buffer_add(float current, float *buf, int *idx, int *cap);
static float buffer_average(const float *buf, int cap);
static void  log_data(float current, float avg);
static void  cleanup(void);
static void  sigint_handler(int sig);

/* ----------------------------- I2C helpers ------------------------------- */

/*
 * Write a 16-bit value to an ADS1115 register (16-bit address, 16-bit data).
 * Uses the raw I2C block-write interface (i2c_smbus_write_byte_data).
 */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(reg=0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register (16-bit address, 16-bit data).
 * Uses i2c_smbus_read_byte_data to read the low byte, then i2c_smbus_read_byte_data
 * again to read the high byte.
 */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16(reg=0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16(reg=0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ----------------------------- ADS1115 init ------------------------------ */
static int ads1115_init(int fd)
{
    uint16_t cfg;

    if (i2c_write_reg16(fd, ADS1115_REG_CFG, ADS1115_CFG_BASE) < 0)
        return -1;

    /* Verify configuration was accepted by reading back the config register. */
    if (i2c_read_reg16(fd, ADS1115_REG_CFG, &cfg) < 0)
        return -1;

    if (cfg != ADS1115_CFG_BASE) {
        fprintf(stderr, "ADS1115 config mismatch: got 0x%04X, expected 0x%04X\n",
                cfg, ADS1115_CFG_BASE);
        return -1;
    }

    return 0;
}

/* ----------------------------- ADS1115 read ------------------------------ */
static int ads1115_read_channel(int fd, uint16_t *raw_out)
{
    uint16_t cfg;
    uint16_t conv;

    if (i2c_write_reg16(fd, ADS1115_REG_CFG, ADS1115_CFG_BASE) < 0)
        return -1;

    /* Wait for the conversion to complete (~8 ms at 128 SPS). */
    usleep(10000);

    if (i2c_read_reg16(fd, ADS1115_REG_CONV, &conv) < 0)
        return -1;

    *raw_out = conv;
    return 0;
}

/* ----------------------------- Conversion -------------------------------- */
static float raw_to_current(uint16_t raw)
{
    /*
     * MLX91204: 4 mA / LSB.
     * ADS1115: ±4.096 V PGA -> 1 bit = 125 µV.
     *
     * raw = (raw / 125) * 4 mA = (raw * 0.004) / 0.0125
     */
    return (float)raw * 0.004f / 0.0125f;
}

/* ----------------------------- Circular buffer --------------------------- */
static void buffer_add(float current, float *buf, int *idx, int *cap)
{
    buf[*idx] = current;
    *idx = (*idx + 1) % BUFFER_SIZE;
    if (*cap < BUFFER_SIZE)
        *cap++;
}

static float buffer_average(const float *buf, int cap)
{
    if (cap == 0)
        return 0.0f;

    float sum = 0.0f;
    for (int i = 0; i < cap; i++)
        sum += buf[i];
    return sum / (float)cap;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(float current, float avg)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s  I2C: %u  ADC: %u  Current: %.2f A  Avg: %.2f A\n",
            ts, (unsigned)current, (unsigned)avg, current, avg);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put ADS1115 into standby mode before closing. */
        (void)i2c_write_reg16(g_i2c_fd, ADS1115_REG_CFG, 0x0000);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ----------------------------- Signal handler ----------------------------- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    float current_buffer[BUFFER_SIZE];
    int   cur_idx = 0;
    int   cur_cap = 0;
    bool  led_on  = false;

    /* Open log file first so we can write a header even if I2C fails. */
    g_log_file = fopen("current_monitor.log", "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Write a header row. */
    fprintf(g_log_file, "--- MLX91204 current monitor session start ---\n");
    fflush(g_log_file);

    /* Open I2C bus. */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115. */
    if (ads1115_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring MLX91204 current via ADS1115 on %s (addr 0x%02X)...\n",
           I2C_BUS, ADS1115_ADDR);
    printf("Sampling at %d Hz, threshold = %.1f A. Press Ctrl+C to exit.\n",
           SAMPLE_RATE_HZ, CURRENT_THRESHOLD);

    /* Main sampling loop. */
    while (g_running) {
        uint16_t raw;

        if (ads1115_read_channel(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read error – continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float current = raw_to_current(raw);

        buffer_add(current, current_buffer, &cur_idx, &cur_cap);
        float avg = buffer_average(current_buffer, cur_cap);

        log_data(current, avg);

        if (avg > CURRENT_THRESHOLD) {
            if (!led_on) {
                if (gpioWrite(LED_PIN, 1) == 0) {
                    led_on = true;
                    printf("WARNING: current %.2f A exceeds %.1f A threshold!\n",
                           current, CURRENT_THRESHOLD);
                } else {
                    fprintf(stderr, "Failed to turn on LED: %s\n", strerror(errno));
                }
            }
        } else {
            if (led_on) {
                if (gpioWrite(LED_PIN, 0) == 0) {
                    led_on = false;
                    printf("Current %.2f A below %.1f A threshold.\n",
                           current, CURRENT_THRESHOLD);
                } else {
                    fprintf(stderr, "Failed to turn off LED: %s\n", strerror(errno));
                }
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

