/*
 * TCS34725 color sensor logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TCS34725 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   TCS34725 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   TCS34725 VDD -> 3.3 V
 *   TCS34725 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tcs34725_log tcs34725_log.c -ltcs34725
 *
 * Run:
 *   ./tcs34725_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <tcs34725.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "color_log.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MAX_CONSEC_ERR 3

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(reg=0x%02X, val=0x%02X): write failed "
                        "(got %zd bytes, errno=%d: %s)\n",
                reg, value, n, errno, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8(reg=0x%02X): write reg failed "
                        "(got %zd bytes, errno=%d: %s)\n",
                reg, n, errno, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8(reg=0x%02X): read failed "
                        "(got %zd bytes, errno=%d: %s)\n",
                reg, n, errno, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* TCS34725 driver helper                                               */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, 0x00, &id) != 0) {
        fprintf(stderr, "TCS34725: cannot read ID register (sensor absent or bus error)\n");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "TCS34725: unexpected ID 0x%02X (expected 0x44)\n", id);
        return -1;
    }

    /* Power-on / reset */
    if (i2c_write_reg8(fd, 0x80, 0x01) != 0) return -1;
    usleep(3000);  /* 3 ms power-on delay */

    /* AFE / RGBC integration time */
    if (i2c_write_reg8(fd, 0x14, 0x07) != 0) return -1;
    if (i2c_write_reg8(fd, 0x15, 0x07) != 0) return -1;
    if (i2c_write_reg8(fd, 0x16, 0x07) != 0) return -1;

    /* RGBC integration time */
    if (i2c_write_reg8(fd, 0x18, 0x07) != 0) return -1;

    /* Clear CDC */
    if (i2c_write_reg8(fd, 0x19, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, 0x1B, 0x00) != 0) return -1;

    /* Red RDC */
    if (i2c_write_reg8(fd, 0x1C, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, 0x1E, 0x00) != 0) return -1;

    /* Green GDC */
    if (i2c_write_reg8(fd, 0x20, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, 0x22, 0x00) != 0) return -1;

    /* Blue BDC */
    if (i2c_write_reg8(fd, 0x24, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, 0x26, 0x00) != 0) return -1;

    /* Start continuous RGBC conversion */
    if (i2c_write_reg8(fd, 0x27, 0x01) != 0) return -1;

    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red,
                              uint16_t *green, uint16_t *blue)
{
    uint8_t data[8];
    if (i2c_read_reg8(fd, 0x24, &data[0]) != 0) return -1;
    if (i2c_read_reg8(fd, 0x25, &data[1]) != 0) return -1;
    if (i2c_read_reg8(fd, 0x26, &data[2]) != 0) return -1;
    if (i2c_read_reg8(fd, 0x27, &data[3]) != 0) return -1;
    if (i2c_read_reg8(fd, 0x28, &data[4]) != 0) return -1;
    if (i2c_read_reg8(fd, 0x29, &data[5]) != 0) return -1;
    if (i2c_read_reg8(fd, 0x2A, &data[6]) != 0) return -1;
    if (i2c_read_reg8(fd, 0x2B, &data[7]) != 0) return -1;

    *clear = ((uint16_t)data[0] << 8) | data[1];
    *red   = ((uint16_t)data[2] << 8) | data[3];
    *green = ((uint16_t)data[4] << 8) | data[5];
    *blue  = ((uint16_t)data[6] << 8) | data[7];
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t clear, uint16_t red,
                     uint16_t green, uint16_t blue)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u,%u,%u\n",
                timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void tcs34725_cleanup(int fd)
{
    /* Best-effort: power-down the sensor */
    if (fd >= 0) {
        i2c_write_reg8(fd, 0x80, 0x00);
        close(fd);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int consecutive_errors = 0;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the TCS34725 slave address */
    if (ioctl(fd, I2C_SLAVE, 0x19) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x19): %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (tcs34725_init(fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Open log file (append mode) */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        tcs34725_cleanup(fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,clear,red,green,blue\n");
        fflush(fp);
    }

    printf("TCS34725 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t clear, red, green, blue;

        if (tcs34725_read_data(fd, &clear, &red, &green, &blue) == 0) {
            if (log_data(fp, clear, red, green, blue) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                consecutive_errors = 0;
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C read error (consecutive=%d)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        }

        /* Sleep SAMPLE_PERIOD seconds, interruptible by signals */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    /* Cleanup */
    if (fp) {
        fflush(fp);
        fclose(fp);
    }
    tcs34725_cleanup(fd);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

