#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define MCP3008_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define OVER_CURRENT_THRESHOLD 10.0f
#define LOG_FILE_NAME "current_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define SPI_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_spi(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    g_spi_fd = fd;
    return 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        int ret = ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret >= 0) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, SPI_RETRIES, strerror(errno));
        usleep(10000);
    }

    fprintf(stderr, "SPI transfer failed after %d retries\n", SPI_RETRIES);
    return -1;
}

static float adc_to_amps(int adc_value)
{
    /*
     * MLX91211 is a ratiometric Hall-effect sensor.
     * The analog output is proportional to the current.
     *
     * The MCP3008 is configured for single-ended mode.
     * The reference voltage is 3.3 V (VDD).
     *
     * For a 10-bit ADC:
     *   0 V -> 0 A
     *   3.3 V -> 1023 A
     *
     * The ratiometric transfer function is:
     *   current (A) = (adc_value / 1023.0f) * 3.3V
     *
     * We scale the ADC reading to the full-scale current range
     * so that the output is in the expected range.
     */
    const float full_scale_current = 3.3f;
    const float adc_max = 1023.0f;
    return ((float)adc_value / adc_max) * full_scale_current;
}

static int log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%.3f\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

static int check_over_current(float current)
{
    return (current > OVER_CURRENT_THRESHOLD) ? 1 : 0;
}

static int control_motor(int enable)
{
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, enable) < 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n",
                MOTOR_SHUTDOWN_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() < 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n",
                MOTOR_SHUTDOWN_PIN, strerror(errno));
        cleanup();
        return 1;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); /* motor disabled at startup */

    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Current (A)\n");
        fflush(g_log_fp);
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, skipping sample\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_amps(adc_value);

        if (log_current(current) < 0) {
            fprintf(stderr, "Logging failed, continuing\n");
        }

        if (check_over_current(current)) {
            printf("Over-current detected! Current: %.3f A\n", current);
            if (control_motor(0) < 0) {
                fprintf(stderr, "Failed to disable motor\n");
            }
            sleep(1);
            if (control_motor(1) < 0) {
                fprintf(stderr, "Failed to re-enable motor\n");
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

