    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%.3f\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

static int check_over_current(float current)
{
    return (current > OVER_CURRENT_THRESHOLD) ? 1 : 0;
}

static int control_motor(int enable)
{
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, enable) < 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n",
                MOTOR_SHUTDOWN_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() < 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n",
                MOTOR_SHUTDOWN_PIN, strerror(errno));
        cleanup();
        return 1;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); /* motor disabled at startup */

    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Current (A)\n");
        fflush(g_log_fp);
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, skipping sample\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_amps(adc_value);

        if (log_current(current) < 0) {
            fprintf(stderr, "Logging failed, continuing\n");
        }

        if (check_over_current(current)) {
            printf("Over-current detected! Current: %.3f A\n", current);
            if (control_motor(0) < 0) {
                fprintf(stderr, "Failed to disable motor\n");
            }
            sleep(1);
            if (control_motor(1) < 0) {
                fprintf(stderr, "Failed to re-enable motor\n");
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

