/*
 * MLX90817 absolute pressure sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   MLX90817 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90817 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90817 VDD  -> 3.3 V
 *   MLX90817 GND  -> GND
 *
 * The MLX90817 is a 16-bit I2C device that returns 32-bit raw data on
 * every read.  The 16-bit result is left-justified in the 32-bit field
 * and scaled to kPa.  The sensor is left-justified; the 16-bit value
 * is the absolute pressure in kPa.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90817_log mlx90817_log.c -lpigpio -lrt
 * Run:    sudo ./mlx90817_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x49          /* MLX90817 default I2C address */
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MAX_READ_FAILS 10            /* consecutive read failures before abort */

/*
 * The MLX90817 returns a 32-bit raw value on every read.
 * The 16-bit result is left-justified in the 32-bit field,
 * and scaled to kPa.  The sensor is left-justified; the 16-bit
 * value is the absolute pressure in kPa.
 */
#define MLX90817_REG_PRESSURE  0x00
#define MLX90817_REG_TEMP     0x02

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file.  Returns 0 on success,
 * -1 on failure (message printed to stderr).                           */
static int log_data(float pressure_kpa)
{
    time_t     rawtime;
    struct tm  utc;
    char       timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &utc);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &utc);

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure_kpa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 32-bit raw value from the pressure register.  Returns 0 on
 * success and stores the 32-bit value in *out.  Returns -1 on I2C
 * error.                                                  */
static int read_pressure_raw(int handle, uint32_t *out)
{
    int rc;

    rc = i2cReadWordData(handle, MLX90817_REG_PRESSURE);
    if (rc < 0) {
        fprintf(stderr, "I2C read error on register 0x%02X: %s\n",
                MLX90817_REG_PRESSURE, pigpio_error(rc));
        return -1;
    }
    *out = (uint32_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return -1;
    }

    /*
     * Open the log file once at startup and flush it immediately.
     * Subsequent calls to log_data() will append to the existing
     * file.
     */
    g_log_file = fopen(LOG_FILE, "w");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }
    fprintf(g_log_file, "timestamp,pressure_kPa\n");
    fflush(g_log_file);

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("MLX90817 pressure logger started.  Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    int consecutive_failures = 0;

    while (g_running) {
        uint32_t raw;
        float   pressure_kpa;

        if (read_pressure_raw(g_i2c_handle, &raw) != 0) {
            consecutive_failures++;
            fprintf(stderr, "Read failure #%d\n", consecutive_failures);
            if (consecutive_failures >= MAX_READ_FAILS) {
                fprintf(stderr, "Too many consecutive read failures; aborting.\n");
                break;
            }
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* MLX90817 16-bit left-justified in 32-bit field */
        int16_t pressure_raw = (int16_t)raw;
        pressure_kpa = (float)pressure_raw / 65536.0f;

        if (log_data(pressure_kpa) != 0) {
            /* Non-fatal: keep running, but report the error. */
        }

        consecutive_failures = 0;
        sleep(SAMPLE_PERIOD);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

