/*
 * Raspberry Pi 4 Model B — MLX90834 (SENT-only) pressure sensor via ADS1115 ADC bridge.
 *
 * Wiring:
 *   MLX90834 SENT_OUT  -> ADS1115 AIN0
 *   MLX90834 SENT_GND  -> ADS1115 GND
 *   MLX90834 VDD        -> 3.3 V
 *   MLX90834 GND        -> GND
 *   ADS1115 VDD         -> 3.3 V
 *   ADS1115 GND         -> GND
 *   ADS1115 SDA         -> GPIO2 (I2C bus 1)
 *   ADS1115 SCL         -> GPIO3 (I2C bus 1)
 *   ADS1115 LED         -> GPIO17 (active-high warning LED)
 *
 * Build:  gcc -O2 -Wall -o mlx90834_ads1115 mlx90834_ads1115.c -lm
 * Run:    sudo ./mlx90834_ads1115
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x10
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01

/* Config: AIN0 single-ended, AIN1 single-ended, 128 SPS, continuous */
#define ADS1115_CFG_BASE 0x8000  /* OS bit */
#define ADS1115_CFG_MUX_AIN0 0x4000  /* AIN0 vs GND */
#define ADS1115_CFG_MUX_AIN1 0x5000  /* AIN1 vs GND */
#define ADS1115_CFG_PGA_4_096V 0x0200  /* +/-4.096 V */
#define ADS1115_CFG_MODE_CONT 0x0000  /* Continuous conversion */
#define ADS1115_CFG_DR_128 0x0080  /* 128 SPS */

#define LED_PIN          17
#define PRESSURE_THRESHOLD_KPA 105.0f
#define SAMPLE_PERIOD_S  1
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to an ADS1115 register (big-endian on the wire). */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_write_reg(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an ADS1115 register (big-endian on the wire). */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "ads1115_read_reg(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_read_reg(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* Trigger a conversion and read the result. Returns 0 on success, -1 on error. */
static int ads1115_read_raw(int fd, uint16_t *raw)
{
    uint16_t cfg = ADS1115_CFG_BASE | ADS1115_CFG_MUX_AIN0 |
                   ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_CONT |
                   ADS1115_CFG_DR_128;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, cfg) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    usleep(10000);

    uint16_t conv;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ads1115_read_reg(fd, ADS1115_REG_CONV, &conv) == 0) {
            *raw = conv;
            return 0;
        }
        if (attempt < MAX_RETRIES - 1)
            usleep(100000);  /* 100 ms backoff before retry */
    }

    fprintf(stderr, "ads1115_read_raw: conversion failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

/* Convert raw ADC count to physical units. */
static void convert_raw(uint16_t raw, float *pressure_kpa, float *temp_c)
{
    /*
     * MLX90834 SENT-only output is 16-bit big-endian.
     * ADS1115 AIN0 single-ended: 16-bit signed, 4.096 V full-scale.
     * ADS1115 AIN1 single-ended: 16-bit signed, 4.096 V full-scale.
     */
    int16_t raw_s0 = (int16_t)raw;
    int16_t raw_s1 = (int16_t)raw;

    /* Pressure: 16-bit signed, 1000 counts/kPa. */
    *pressure_kpa = (float)raw_s0 / 1000.0f;

    /* Temperature: 16-bit signed, 1000 counts/°C. */
    *temp_c = (float)raw_s1 / 1000.0f;
}

int main(void)
{
    int i2c_fd = -1;
    int led_state = 0;
    int ret_code = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Open LED GPIO --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise: %s\n", strerror(errno));
        goto cleanup;
    }
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    printf("MLX90834 via ADS1115 — Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw0 = 0, raw1 = 0;
        float pressure_kpa = 0.0f, temp_c = 0.0f;
        bool read_ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (ads1115_read_raw(i2c_fd, &raw0) == 0 &&
                ads1115_read_raw(i2c_fd, &raw1) == 0) {
                read_ok = true;
                break;
            }
            if (attempt < MAX_RETRIES - 1)
                usleep(100000);
        }

        if (!read_ok) {
            fprintf(stderr, "Failed to read ADS1115 after %d attempts; skipping sample.\n",
                    MAX_RETRIES);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

