#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8
#define ADC_CHANNEL     0
#define THRESHOLD_PPM   1000
#define LOG_FILE        "methane_log.txt"
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read one sample from the MCP3008 on the given channel (0-7).
 * Returns 0-1023 on success, -1 on error.
 * Uses the Linux spidev ioctl interface directly (no spidev driver).
 */
static int read_mcp3008(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     * Byte 0: start bit (0x01)
     * Byte 1: SGL/DIFF=1 + D2 D1 D0 channel, shifted left 4
     * Byte 2: don't care (clocks out low 2 bits of result)
     */
    unsigned char tx[3] = {
        0x01,
        (unsigned char)(0x80 | (channel << 4)),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(const char *filename, int ppm)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %d ppm\n", ts, ppm) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void check_threshold(int ppm)
{
    if (ppm > THRESHOLD_PPM) {
        fprintf(stderr, "LEAK DETECTED! Methane concentration: %d ppm\n", ppm);
    }
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device directly (no spidev driver) */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device '%s': %s\n",
                SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    if (ioctl(g_spi_fd, SPI_IOC_RD_MODE, &mode) < 0) {
        fprintf(stderr, "Warning: SPI mode read failed: %s\n", strerror(errno));
    }
    if (ioctl(g_spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Warning: SPI bits per word read failed: %s\n", strerror(errno));
    }
    if (ioctl(g_spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Warning: SPI max speed read failed: %s\n", strerror(errno));
    }

    printf("Monitoring methane concentration (MCP3008 ch%d) every %d s.\n",
           ADC_CHANNEL, SAMPLE_PERIOD_S);
    printf("Threshold: %d ppm. Press Ctrl+C to exit.\n", THRESHOLD_PPM);

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read error; continuing.\n");
        } else {
            int ppm = (int)(((float)adc_value / 1023.0f) * 1000.0f);
            check_threshold(ppm);

            if (log_data(LOG_FILE, ppm) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    /* Graceful cleanup */
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

