    return 0;
}

static float convert_to_pressure(int16_t raw_value)
{
    /*
     * MLX90830 analog output is linearly related to pressure.
     * Sensitivity = 0.0001 kPa per LSB, offset = 0, scale = 100 kPa.
     *
     * Note: The MLX90830 datasheet specifies a 0-100 kPa output range.
     *       The ADS1115 is configured for ±4.096 V, which maps to 16-bit
