    if (now == (time_t)-1) {
        fprintf(stderr, "Error: Failed to get current time.\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: Failed to convert time to local time.\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
    }

    return 0;
}

int main(void)
{
    int consecutive_errors = 0;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register SIGINT handler.\n");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90830 Pressure Sensor Reader\n");
    printf("Logging to %s at %d Hz. Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_RATE_HZ);

    while (!terminate) {
        int16_t raw_value = 0;

        if (read_ads1115(&raw_value) != 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: ADC read failed (consecutive: %d).\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Error: Max consecutive errors reached. Aborting.\n");
                break;
            }
