/*
 * Raspberry Pi 4 Model B - MLX90830 Pressure Sensor Reader
 *
 * Hardware:
 *   - ADS1115 16-bit ADC on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *   - MLX90830 analog output wired to ADS1115 AIN0
 *
 * Build:
 *   gcc -O2 -Wall -o pressure_reader pressure_reader.c -lm
 *
 * Run:
 *   ./pressure_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48          /* ADS1115 default address (7-bit) */
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/*
 * ADS1115 config word (16-bit, big-endian on the bus):
 *   Bit 15    OS            = 1 (begin single conversion)
 *   Bits14:12 MUX          = 100 (AIN0 single-ended)
 *   Bits11:9  PGA          = 001 (±4.096 V)
 *   Bit  8    MODE         = 1 (single-shot)
 *   Bits7:5   DR           = 100 (128 SPS)
 *   Bit  4    COMP_MODE    = 0 (traditional comparator)
 *   Bit  3    COMP_POL     = 0
 *   Bit  2    COMP_LAT     = 0
 *   Bits1:0   COMP_QUE     = 11 (disable comparator)
 *
 * Resulting config: 0xC083
 */
#define ADS1115_CONFIG_BASE  0xC083

#define SAMPLE_RATE_HZ      1
#define SAMPLE_PERIOD_US    (1000000 / SAMPLE_RATE_HZ)
#define LOG_FILE            "pressure_log.txt"
#define MAX_CONSECUTIVE_ERRORS 10

/* MLX90830 calibration parameters (example values) */
#define MLX90830_SENSITIVITY  0.0001f   /* kPa per LSB */
#define MLX90830_OFFSET      0.0f
#define MLX90830_SCALE       100.0f

/* ----------------------------- Globals ----------------------------------- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize_i2c(void);
static int  read_ads1115(int16_t *raw_value);
static float convert_to_pressure(int16_t raw_value);
static int  validate_pressure(float pressure);
static int  log_data(float pressure);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- Implementation ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int initialize_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    /* Verify ADS1115 is present by reading the config register */
    char cfg_buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONFIG, cfg_buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: ADS1115 not responding at address 0x%02X (read returned %d).\n",
                ADS1115_ADDR, rc);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_ads1115(int16_t *raw_value)
{
    char config_buf[3];
    char conv_buf[2];
    int rc;

    /* Write config: OS=1, MUX=100, PGA=001, MODE=1, DR=100, COMP=00, QE=11 */
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (ADS1115_CONFIG_BASE >> 8) & 0xFF;
    config_buf[2] = ADS1115_CONFIG_BASE & 0xFF;

    rc = i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_CONFIG, config_buf, 3);
    if (rc != 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config (pigpio error %d).\n", rc);
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Point to conversion register and read 2 bytes */
    rc = i2cWriteByte(i2c_handle, ADS1115_REG_CONV);
    if (rc != 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion pointer (pigpio error %d).\n", rc);
        return -1;
    }

    rc = i2cReadDevice(i2c_handle, conv_buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion data (pigpio error %d).\n", rc);
        return -1;
    }

    *raw_value = (int16_t)((conv_buf[0] << 8) | (uint8_t)conv_buf[1]);
    return 0;
}

static float convert_to_pressure(int16_t raw_value)
{
    /*
     * MLX90830 analog output is linearly related to pressure.
     * Sensitivity = 0.0001 kPa per LSB, offset = 0, scale = 100 kPa.
     *
     * Note: The MLX90830 datasheet specifies a 0-100 kPa output range.
     *       The ADS1115 is configured for ±4.096 V, which maps to 16-bit
     *       signed values in the range [-32768, 32767].
     *       For a full-scale output of 100 kPa, the LSB value is:
     *
     *       pressure_kPa = raw_value * (100.0f / 32767.0f)
     *
     *       raw_value = 32767 * (100.0f / pressure_kPa)
     *
     *       pressure_kPa = 32767 * (raw_value / 32767.0f)
     */
    float pressure_kPa = (float)raw_value * (MLX90830_SCALE / 32767.0f);
    return pressure_kPa;
}

static int validate_pressure(float pressure)
{
    if (pressure < 0.0f || pressure > 100.0f) {
        fprintf(stderr, "Error: Pressure reading out of range: %.2f kPa\n", pressure);
        return 0;
    }
    return 1;
}

static int log_data(float pressure)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: Failed to get current time.\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: Failed to convert time to local time.\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
    }

    return 0;
}

int main(void)
{
    int consecutive_errors = 0;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register SIGINT handler.\n");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90830 Pressure Sensor Reader\n");
    printf("Logging to %s at %d Hz. Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_RATE_HZ);

    while (!terminate) {
        int16_t raw_value = 0;

        if (read_ads1115(&raw_value) != 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: ADC read failed (consecutive: %d).\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Error: Max consecutive errors reached. Aborting.\n");
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        consecutive_errors = 0;

        float pressure = convert_to_pressure(raw_value);
        if (validate_pressure(pressure) != 0) {
            fprintf(stderr, "Error: Pressure out of range. Skipping log entry.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_data(pressure) != 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

