#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_BODY "Humidity level exceeded threshold!"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x00, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float process_humidity(int raw_humidity) {
    if (raw_humidity < 0) return -1.0f;
    float RH = (125.0f - (10.0f * raw_humidity)) / 10.0f;
    if (RH < 0.0f) RH = 0.0f;
    if (RH > 100.0f) RH = 100.0f;
    return RH;
}

static float process_temperature(int raw_temperature) {
    if (raw_temperature < 0) return -1.0f;
    float T = (raw_temperature * 10.0f) / 65536.0f;
    if (T < -40.0f) T = -40.0f;
    if (T > 125.0f) T = 125.0f;
    return T;
}

static void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Failed to open log file");
            return;
        }
    }

    fprintf(log_fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_fp);
}

static void send_email_alert(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char command[512];
    int len = snprintf(command, sizeof(command),
        "echo \"Subject: %s\n\nHumidity level exceeded threshold!\nHumidity: %.2f%%\" | ssmtp %s",
        EMAIL_SUBJECT, humidity, EMAIL_RECIPIENT);

    if (len < 0 || (size_t)len >= sizeof(command)) {
        fprintf(stderr, "Command buffer too small\n");
        return;
    }

    int ret = system(command);
    if (ret == -1) {
        perror("Failed to execute ssmtp");
    } else if (WIFEXITED(ret) && WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "ssmtp exited with status %d\n", WEXITSTATUS(ret));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (init_spi() < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_humidity = read_mcp3208(0);
        int raw_temperature = read_mcp3208(1);

        if (raw_humidity < 0 || raw_temperature < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            sleep(5);
            continue;
        }

        float humidity = process_humidity(raw_humidity);
        float temperature = process_temperature(raw_temperature);

        if (humidity < 0.0f) {
            fprintf(stderr, "Error processing humidity data.\n");
        }

        log_data(humidity, temperature);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        sleep(5);
    }

    printf("\nShutting down...\n");

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }

    gpioTerminate();

    return 0;
}

