#define MIN_TEMP        -40.0f
#define MAX_TEMP        125.0f
#define ADC_MAX         1023.0f

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_ce_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_init(void) {
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    g_ce_line = gpiod_chip_get_line(g_chip, 8);
    if (!g_ce_line) {
        fprintf(stderr, "Error getting GPIO line 8: %s\n", strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_ce_line, "mcp3208_ce", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line 8 as output: %s\n", strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_ce_line = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

