        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_ce_line) {
        gpiod_line_release(g_ce_line);
        g_ce_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

