    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(g_spi_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "timestamp,temperature_celsius\n");
        fflush(g_log_fp);
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3208(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            sleep(1);
            continue;
        }

        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            sleep(1);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);

        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
        } else {
            if (log_temperature(temperature) < 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        }

        sleep(SAMPLE_HZ);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

