    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008_channel(int fd, uint8_t channel, uint16_t *out_value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value.
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    uint16_t value = ((rx[1] & 0x03) << 8) | rx[2];
    *out_value = value;
    return 0;
}

static int log_data(FILE *fp, uint16_t x, uint16_t y, uint16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%u,%u,%u\n", timestamp, x, y, z) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(fp);
    return 0;
}

static int log_impact(FILE *fp)
{
    if (fprintf(fp, "IMPACT DETECTED\n") < 0) {
        perror("fprintf (impact)");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen("impact_log.txt", "a");
    if (!g_log_file) {
        perror("fopen(impact_log.txt)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    printf("ADXL335 impact detection started. Logging to impact_log.txt. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t x = 0, y = 0, z = 0;
        int x_ok = 1, y_ok = 1, z_ok = 1;

        if (read_mcp3008_channel(g_spi_fd, 0, &x) < 0) {
            x_ok = 0;
        }
        if (read_mcp3008_channel(g_spi_fd, 1, &y) < 0) {
            y_ok = 0;
        }
        if (read_mcp3008_channel(g_spi_fd, 2, &z) < 0) {
            z_ok = 0;
        }

        if (!x_ok || !y_ok || !z_ok) {
            fprintf(stderr, "Error: one or more ADC reads failed (x=%d y=%d z=%d)\n",
                    x, y, z);
            if (g_log_file) {
                fprintf(g_log_file, "ERROR: ADC read failure\n");
                fflush(g_log_file);
            }
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_data(g_log_file, x, y, z) < 0) {
            fprintf(stderr, "Error: failed to log data\n");
        }

        if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
            if (log_impact(g_log_file) < 0) {
                fprintf(stderr, "Error: failed to log impact\n");
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    return EXIT_SUCCESS;
}

