#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define ADC_CHANNEL    0
#define FLOW_MIN       0.0f
#define FLOW_MAX       5.0f
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_US      1000000

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
     *   tx[2] = 0x00                       (clock out low bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static float adc_to_flow_rate(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    float flow_rate = (float)adc_value / 1023.0f * (FLOW_MAX - FLOW_MIN) + FLOW_MIN;
    return flow_rate;
}

static void log_flow_rate(FILE *fp, float flow_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%06ld,%.2f\n", timestamp, ts.tv_nsec / 1000, flow_rate);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d): %s\n",
                g_spi_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(stdout, "Flow monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n",
            LOG_FILE);

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; skipping sample\n");
        } else if (adc_value == 0) {
            fprintf(stderr, "Warning: ADC reads 0 — sensor may be absent or disconnected\n");
        } else if (adc_value >= 1023) {
            fprintf(stderr, "Warning: ADC saturated (%d) — sensor may be absent or disconnected\n",
                    adc_value);
        } else {
            float flow_rate = adc_to_flow_rate(adc_value);
            if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
                fprintf(stderr, "Flow rate out of range: %.2f L/min (ADC=%d)\n",
                        flow_rate, adc_value);
            } else {
                log_flow_rate(g_log_file, flow_rate);
                fprintf(stdout, "Flow rate: %.2f L/min (ADC=%d)\n",
                        flow_rate, adc_value);
            }
        }

        gpioDelay(SAMPLE_US);
    }

    fprintf(stdout, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

