#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x48
#define CMD_HIGH_PRECISION 0x3600
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    if (i2c_write_cmd(fd, CMD_HIGH_PRECISION) < 0) {
        return -1;
    }

    usleep(20000);

    if (i2c_read_data(fd, data, 6) < 0) {
        return -1;
    }

    uint32_t raw_pressure = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
    uint32_t raw_temperature = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];

    /* ICP-10125 calibration formulas (from datasheet) */
    float p_comp = (float)raw_pressure;
    float t_comp = (float)raw_temperature;

    *pressure = (p_comp - 0.5f) * 100.0f;
    *temperature = (t_comp - 0.5f) * 100.0f;

    return 0;
}

static int log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, pressure) < 0) {
        perror("Failed to write to CSV file");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / talk to slave");
        cleanup();
        return 1;
    }

    log_fp = fopen(CSV_FILE, "a");
    if (!log_fp) {
        perror("Failed to open CSV file");
        cleanup();
        return 1;
    }

    printf("Starting ICP-10125 data acquisition. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, pressure;

        if (read_sensor_data(i2c_fd, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
            if (log_data(log_fp, temperature, pressure) < 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: sensor read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

