#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <stdint.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define NUM_CHANNELS 2
#define NUM_SAMPLES 1000
#define GAIN_MIN 1
#define GAIN_MAX 10
#define GAIN_STEP 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(*fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(*fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(*fd);
        return -1;
    }

    return 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(int argc, char *argv[]) {
    int spi_fd = -1;
    int gain_values[NUM_CHANNELS];
    int i, j;
    int *channel_map[NUM_CHANNELS];
    int *gain_values_map[NUM_CHANNELS];
    int num_channels = NUM_CHANNELS;
    int num_gains = NUM_CHANNELS;

    for (i = 0; i < num_channels; i++) {
        channel_map[i] = &gain_values[i];
        gain_values_map[i] = &gain_values[i];
    }

