        gain_values[i] = GAIN_MIN;
    }

    if (spi_init(&spi_fd) != 0) {
        return EXIT_FAILURE;
    }

    for (i = 0; i < argc; i++) {
        if (i > 0 && i < argc && strcmp(argv[i], "-g") == 0) {
            if (i + 1 < argc) {
                for (j = 1; j < argc; j++) {
                    int val = atoi(argv[j]);
                    if (val >= GAIN_MIN && val <= GAIN_MAX) {
                        gain_values[i / num_channels] = val;
                    } else {
                        fprintf(stderr, "Invalid gain value: %s\n", argv[j]);
                        return EXIT_FAILURE;
                    }
                }
            } else {
                fprintf(stderr, "Usage: %s [-g gain1 gain2 ...]\n", argv[0]);
                return EXIT_FAILURE;
            }
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Sampling audio from %d channels with gains:\n", num_channels);
    for (i = 0; i < num_channels; i++) {
        printf("  Channel %d: gain = %d\n", i, gain_values[i]);
    }
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int *current_gain = gain_values_map[0];
        int *current_channel = channel_map[0];

        for (i = 0; i < num_channels; i++) {
            int channel = *current_channel;
            int gain = *current_gain;

            if (spi_fd < 0) {
                fprintf(stderr, "SPI device not initialized.\n");
                return EXIT_FAILURE;
            }

            for (j = 0; j < NUM_SAMPLES; j++) {
                int sample = read_mcp3008(spi_fd, channel);
                if (sample < 0) {
                    fprintf(stderr, "Error reading channel %d at sample %d\n", channel, j);
                    return EXIT_FAILURE;
                }

                // Apply noise cancellation (simple average)
                *current_gain = (gain + 1) / 2;
                *current_channel = &(*current_gain);

                // Apply gain
                sample *= gain;

                printf("%d,%d\n", sample, *current_channel);
            }
        }
    }

    printf("\nExiting...\n");
    close(spi_fd);
    return EXIT_SUCCESS;
}

