#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define BUZZER_GPIO 18
#define FLAME_THRESHOLD 100
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ambient_temperature(float *temperature) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open ambient_temp.txt: %s\n", strerror(errno));
        *temperature = 25.0f;
        return -1;
    }
    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Warning: cannot read ambient_temp.txt: %s\n", strerror(errno));
        fclose(fp);
        *temperature = 25.0f;
        return -1;
    }
    fclose(fp);
    char *endptr;
    *temperature = strtof(line, &endptr);
    if (*endptr != '\0' && *endptr != '\n' && *endptr != '\r') {
        fprintf(stderr, "Warning: invalid temperature data in ambient_temp.txt\n");
        *temperature = 25.0f;
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float compensate_voltage(int raw_adc, float ambient_temp) {
    float voltage = (float)raw_adc * 3.3f / 1023.0f;
    float compensated_voltage = voltage * (ambient_temp / 25.0f);
    return compensated_voltage;
}

static int log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s,%d,%.2f,%.2f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, flame_detected);
        fflush(log_file);
        return 0;
    }
    fprintf(stderr, "Error: log file not open\n");
    return -1;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
