#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/types.h>
#include <sys/wait.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_CAL 0
#define DEFAULT_MAX_CAL 100
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "msmtprc"

#define SPI_SPEED_HZ 500000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0

#define LOG_FILE "plant_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_spi_channel = DEFAULT_SPI_CHANNEL;
static int g_adc_channel = DEFAULT_ADC_CHANNEL;
static int g_min_cal = DEFAULT_MIN_CAL;
static int g_max_cal = DEFAULT_MAX_CAL;
static int g_moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
static int g_logging_interval = DEFAULT_LOGGING_INTERVAL;
static char g_recipient_email[256] = DEFAULT_RECIPIENT_EMAIL;
static char g_msmtp_config[256] = DEFAULT_MSMTP_CONFIG;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(int channel, int speed_hz, int bits, int mode) {
    char spi_device[32];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d", channel);

    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", spi_device, strerror(errno));
        return -1;
    }

    unsigned int mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    unsigned int speed_val = speed_hz;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    unsigned int bits_val = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value, int min_cal, int max_cal) {
    if (max_cal <= min_cal) {
        fprintf(stderr, "Invalid calibration range: min_cal=%d, max_cal=%d\n", min_cal, max_cal);
        return -1.0f;
    }
    if (max_cal == min_cal) {
        return 0.0f;
    }
    return ((float)(adc_value - min_cal) / (float)(max_cal - min_cal)) * 100.0f;
}

static int log_data(const char *filename, float moisture_percentage) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int send_email_alert(const char *recipient_email, float moisture_percentage) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "echo \"Subject: Plant Moisture Alert\\n\\nPlant moisture is below threshold: %.2f%%\\n\" | msmtp -a default %s",
        moisture_percentage, recipient_email);

    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error formatting email command\n");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing msmtp: %s\n", strerror(errno));
        return -1;
    } else if (status != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", status);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:C:m:M:t:i:e:h")) != -1) {
        switch (opt) {
            case 'c':
                g_spi_channel = atoi(optarg);
                break;
            case 'C':
                g_adc_channel = atoi(optarg);
                break;
            case 'm':
                g_min_cal = atoi(optarg);
                break;
            case 'M':
                g_max_cal = atoi(optarg);
                break;
            case 't':
                g_moisture_threshold = atoi(optarg);
                break;
            case 'i':
                g_logging_interval = atoi(optarg);
                break;
            case 'e':
                strncpy(g_recipient_email, optarg, sizeof(g_recipient_email) - 1);
                g_recipient_email[sizeof(g_recipient_email) - 1] = '\0';
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-C adc_channel] [-m min_cal] [-M max_cal] [-t moisture_threshold] [-i logging_interval] [-e recipient_email] [-h]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (g_min_cal >= g_max_cal) {
        fprintf(stderr, "Error: min_cal must be less than max_cal\n");
        return EXIT_FAILURE;
    }

    if (g_logging_interval <= 0) {
        fprintf(stderr, "Error: logging_interval must be greater than 0\n");
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init(g_spi_channel, SPI_SPEED_HZ, SPI_BITS_PER_WORD, SPI_MODE);
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Plant monitoring started. Logging to %s every %d seconds.\n", LOG_FILE, g_logging_interval);
    printf("Threshold: %.2f%% | ADC: %d | Min: %d | Max: %d | Recipient: %s\n",
           g_moisture_threshold, g_adc_channel, g_min_cal, g_max_cal, g_recipient_email);

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_fd, g_adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", g_logging_interval);
            sleep(g_logging_interval);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value, g_min_cal, g_max_cal);
        if (moisture_percentage < 0.0f) {
            fprintf(stderr, "Error calculating moisture percentage, retrying in %d seconds...\n", g_logging_interval);
            sleep(g_logging_interval);
            continue;
        }

        if (log_data(LOG_FILE, moisture_percentage) < 0) {
            fprintf(stderr, "Error logging data, continuing...\n");
        }

        if (moisture_percentage < g_moisture_threshold) {
            printf("Moisture below threshold (%.2f%% < %.2f%%)! Sending email alert...\n",
                   moisture_percentage, g_moisture_threshold);
            if (send_email_alert(g_recipient_email, moisture_percentage) < 0) {
                fprintf(stderr, "Error sending email alert, continuing...\n");
            }
        }

        sleep(g_logging_interval);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

