    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, ADC: %d, Moisture: %.2f%%\n",
                timestamp, adc_value, moisture) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

