    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Interval: %d s\n", interval);
    printf("Logging to: %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Sensor read error; skipping sample\n");
        } else {
            float moisture = calculate_moisture_percentage(adc_value);
            if (moisture < 0.0f) {
                fprintf(stderr, "Invalid ADC value %d; skipping sample\n", adc_value);
            } else {
                if (log_data(adc_value, moisture) != 0) {
                    fprintf(stderr, "Logging failed; continuing\n");
                }
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < interval * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

