#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define VREF 3.3f
#define MAX_ADC_VALUE 1023
#define MIN_ADC_VALUE 0
#define SAMPLE_INTERVAL_SEC 1
#define MAX_CONSECUTIVE_ERRORS 10

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * tx[0] = 0x01 (start bit)
     * tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     * tx[2] = 0x00 (don't care)
     * Result: 10-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

static float convert_to_pressure(int adc_value) {
    /*
     * MLX90823: 0 V -> 0 kPa, 3.3 V -> 1000 kPa.
     * Linear interpolation between these two points.
     */
    if (adc_value <= MIN_ADC_VALUE) {
        return 0.0f;
    }
    if (adc_value >= MAX_ADC_VALUE) {
        return 1000.0f;
    }

    float voltage = (float)adc_value / (float)MAX_ADC_VALUE * VREF;
    float pressure = (voltage - 0.0f) / (VREF - 0.0f) * 1000.0f;
    return pressure;
}

static void log_data(float pressure) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s - Pressure: %.2f kPa\n", timestamp, pressure);
    fflush(stdout);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "SPI read error (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive SPI errors. Aborting.\n");
                break;
            }
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        consecutive_errors = 0;

        float pressure = convert_to_pressure(adc_value);

        /* Sensor-absent detection: voltage stuck at 0 V or 3.3 V */
        if (pressure < 0.0f || pressure > 1000.0f) {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        log_data(pressure);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

