        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Reader (MCP3008 CH0)\n");
    printf("SPI: %s, Mode: %d, Bits: %d, Speed: %u Hz\n",
           SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int adc_value = read_mcp3008(fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n",
                    SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float moisture = calculate_moisture_percentage(adc_value);
        printf("Moisture: %.2f%%\n", moisture);
        fflush(stdout);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return EXIT_SUCCESS;
}

