#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 on bus 0 */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define PUMP_GPIO        17         /* BCM 17 */
#define LOW_THRESHOLD    300
#define HIGH_THRESHOLD   600
#define SAMPLE_INTERVAL  5          /* seconds */
#define BUFFER_SIZE      20
#define TIMER_ID         0          /* pigpio timer 0 */

/* ----------------------------- Data Structures --------------------------- */
typedef struct {
    time_t timestamp;
    int    moisture;
    int    pump_state;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static CircularBuffer g_buffer;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_gpio(void);
static int  init_spi(void);
static int  read_mcp3008(int channel, int *out_value);
static int  control_pump(int state);
static void add_to_buffer(CircularBuffer *buf, time_t ts, int moisture, int pump_state);
static void print_buffer(const CircularBuffer *buf);
static void timer_callback(void *user_data);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- Implementation ----------------------------- */

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PUMP_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(PUMP_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise pump GPIO %d low.\n", PUMP_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int init_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        return -1;
    }
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                 (start bit)
 *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                 (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2].
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d (must be 0-7).\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", ret);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

static int control_pump(int state)
{
    if (gpioWrite(PUMP_GPIO, state) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed.\n", PUMP_GPIO, state);
        return -1;
    }
    return 0;
}

static void add_to_buffer(CircularBuffer *buf, time_t ts, int moisture, int pump_state)
{
    buf->data[buf->head].timestamp = ts;
    buf->data[buf->head].moisture  = moisture;
    buf->data[buf->head].pump_state = pump_state;

    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) {
        buf->count++;
    }
}

static void print_buffer(const CircularBuffer *buf)
{
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts_str[32];
        struct tm tm_info;
        localtime_r(&buf->data[idx].timestamp, &tm_info);
        strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Moisture: %d, Pump: %s\n",
               ts_str, buf->data[idx].moisture,
               buf->data[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log ---\n\n");
}

static void timer_callback(void *user_data)
{
    (void)user_data;

    int moisture = -1;
    int pump_state = -1;

    if (read_mcp3008(0, &moisture) != 0) {
        fprintf(stderr, "Warning: SPI read failed, skipping sample.\n");
        return;
    }

    if (moisture < LOW_THRESHOLD && pump_state == 0) {
        if (control_pump(1) == 0) {
            pump_state = 1;
            printf("Pump ON (moisture %d < %d)\n", moisture, LOW_THRESHOLD);
        }
    } else if (moisture > HIGH_THRESHOLD && pump_state == 1) {
        if (control_pump(0) == 0) {
            pump_state = 0;
            printf("Pump OFF (moisture %d > %d)\n", moisture, HIGH_THRESHOLD);
        }
    }

    add_to_buffer(&g_buffer, time(NULL), moisture, pump_state);
    print_buffer(&g_buffer);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    control_pump(0);
    gpioTerminate();
}

int main(void)
{
    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    memset(&g_buffer, 0, sizeof(g_buffer));

    if (gpioSetTimerFuncEx(TIMER_ID, SAMPLE_INTERVAL, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

