        strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Moisture: %d, Pump: %s\n",
               ts_str, buf->data[idx].moisture,
               buf->data[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log ---\n\n");
}

static void timer_callback(void *user_data)
{
    (void)user_data;

    int moisture = -1;
    int pump_state = -1;

    if (read_mcp3008(0, &moisture) != 0) {
        fprintf(stderr, "Warning: SPI read failed, skipping sample.\n");
        return;
    }

    if (moisture < LOW_THRESHOLD && pump_state == 0) {
        if (control_pump(1) == 0) {
            pump_state = 1;
            printf("Pump ON (moisture %d < %d)\n", moisture, LOW_THRESHOLD);
        }
    } else if (moisture > HIGH_THRESHOLD && pump_state == 1) {
        if (control_pump(0) == 0) {
            pump_state = 0;
            printf("Pump OFF (moisture %d > %d)\n", moisture, HIGH_THRESHOLD);
        }
    }

    add_to_buffer(&g_buffer, time(NULL), moisture, pump_state);
    print_buffer(&g_buffer);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    control_pump(0);
    gpioTerminate();
}

int main(void)
{
    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    memset(&g_buffer, 0, sizeof(g_buffer));

    if (gpioSetTimerFuncEx(TIMER_ID, SAMPLE_INTERVAL, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

