/*
 * door_lock_v2.c — Raspberry Pi 5 (64-bit Bookworm)
 *
 * Monitors a GP2Y0A21YK0F Sharp IR distance sensor via an ADS1115 ADC
 * on /dev/i2c-1, energizes a 5 V relay on GPIO17 for 3 s when the
 * distance falls below a calibrated threshold, and logs the event to
 * /var/log/door_events.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock_v2 door_lock_v2.c
 * Run:    sudo ./door_lock_v2   (needs /dev/i2c-1 access)
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/stat.h>
#include <sys/types.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x10
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01

/* Config: A0=1 (ADC0 single-ended), 4.096 V, single-shot, 128 SPS */
#define ADS1115_CFG_BASE 0x8483

#define RELAY_GPIO      17
#define REED_GPIO       27
#define LOG_FILE        "/var/log/door_events.log"
#define CALIB_SAMPLES   10
#define CALIB_DELAY_MS  50
#define RELAY_PULSE_MS  3000
#define POLL_DELAY_MS   200

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *event)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_event: fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm;
        localtime_r(&ts.tv_sec, &tm);
        char tbuf[32];
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000L, event);
    } else {
        fprintf(fp, "%ld.%03ld: %s\n", ts.tv_sec, ts.tv_nsec / 1000000L, event);
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "log_event: fclose: %s\n", strerror(errno));
}

/*
 * Write a 16-bit value to an ADS1115 register.
 * Returns 0 on success, -1 on error.
 */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_write_reg: write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "ads1115_read_reg: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_read_reg: read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on the ADS1115 channel 0 (A0).
 * Returns 0 on success, -1 on error.
 */
static int ads1115_read_adc(int fd, uint16_t *adc_out)
{
    uint16_t cfg = ADS1115_CFG_BASE;
    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, cfg) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS, use 10 ms) */
    struct timespec ts = { 0, 10000000L };
    nanosleep(&ts, NULL);

    uint16_t raw;
    if (ads1115_read_reg(fd, ADS1115_REG_CONV, &raw) != 0)
        return -1;

    *adc_out = raw;
    return 0;
}

/*
 * Calibrate the ADS1115 by averaging CALIB_SAMPLES baseline readings.
 * Returns 0 on success, -1 on error.
 */
static int calibrate_ads1115(int fd, uint16_t *baseline)
{
    int ok = 0;
    for (int i = 0; i < CALIB_SAMPLES && g_running; i++) {
        uint16_t val;
        if (ads1115_read_adc(fd, &val) != 0)
            return -1;
        *baseline = (*baseline + val) / (CALIB_SAMPLES + 1);
        usleep(CALIB_DELAY_MS * 1000);
