    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(RELAY_GPIO): %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_GPIO, 0): %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure reed sensor GPIO */
    if (gpioSetMode(REED_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(REED_GPIO): %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(REED_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(REED_GPIO): %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    struct stat st;
    if (stat(LOG_FILE, &st) != 0) {
        if (errno != ENOENT) {
            fprintf(stderr, "stat(%s): %s\n", LOG_FILE, strerror(errno));
            close(i2c_fd);
            return EXIT_FAILURE;
        }
        if (mkdir(LOG_FILE, 0755) != 0 && errno != EEXIST) {
