    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Calibrate ADS1115 */
    uint16_t baseline = 0;
    if (calibrate_ads1115(i2c_fd, &baseline) != 0) {
        fprintf(stderr, "ADS1115 calibration failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    printf("ADS1115 calibrated: baseline = %u\n", baseline);

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(RELAY_GPIO): %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_GPIO, 0): %s\n", strerror(errno));
        close(i2c_fd);
