            fprintf(stderr, "ADC read failed; continuing.\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        /* GP2Y0A21YK0F: distance = (adc / 1024) * 1000 cm */
        double distance_cm = (adc / 1024.0) * 1000.0;
        double distance_m = distance_cm / 100.0;

        printf("Distance: %.2f m\n", distance_m);

        if (distance_m < 0.5) {
            printf("Distance below threshold (%.2f < 0.5) — energizing relay.\n",
                   distance_m);

