#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define NUM_SENSORS 3
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "soil_moisture_log.csv"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_open(int *fd_out) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    unsigned char bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int spi_read_adc(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(FILE *fp, int s1, int s2, int s3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, s1, s2, s3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int spi_fd = -1;
    FILE *fp = NULL;
    int sensor_values[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_open(&spi_fd) < 0) {
        return EXIT_FAILURE;
    }

    fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup_spi;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size < 0) {
        fprintf(stderr, "Error getting log file size: %s\n", strerror(errno));
        goto cleanup_fp;
    }

    if (file_size == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
            goto cleanup_fp;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Error flushing header: %s\n", strerror(errno));
            goto cleanup_fp;
        }
    }

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = spi_read_adc(spi_fd, i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                sensor_values[i] = -1;
            }
        }

        if (log_data(fp, sensor_values[0], sensor_values[1], sensor_values[2]) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup_fp:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
        }
    }

cleanup_spi:
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return ret;
}

