        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int spi_fd = -1;
    FILE *fp = NULL;
    int sensor_values[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_open(&spi_fd) < 0) {
        return EXIT_FAILURE;
    }

    fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup_spi;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size < 0) {
        fprintf(stderr, "Error getting log file size: %s\n", strerror(errno));
        goto cleanup_fp;
    }

    if (file_size == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
            goto cleanup_fp;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Error flushing header: %s\n", strerror(errno));
            goto cleanup_fp;
        }
    }

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = spi_read_adc(spi_fd, i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                sensor_values[i] = -1;
            }
        }

        if (log_data(fp, sensor_values[0], sensor_values[1], sensor_values[2]) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup_fp:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
        }
    }

cleanup_spi:
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return ret;
}

