#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define DEFAULT_THRESHOLD 30
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define PUMP_GPIO 18
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define VREF 3.3
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3

static int threshold = DEFAULT_THRESHOLD;
static int pump_duration = DEFAULT_PUMP_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    }
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Invalid ADC channel requested");
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
                log_message("ADC value out of range");
                return -1;
            }
            return adc_value;
        }
        log_message("SPI transfer failed, retrying...");
        gpioDelay(100000);
    }
    log_message("SPI transfer failed after retries");
    return -1;
}

static float calculate_moisture_level(int adc_value) {
    if (adc_value < 0) return -1.0f;
    float voltage = (float)adc_value * VREF / (float)ADC_MAX_VALUE;
    return (voltage / VREF) * 100.0f;
}

static void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump %s", state ? "ON" : "OFF");
    log_message(msg);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                if (threshold < 0 || threshold > 100) {
                    fprintf(stderr, "Threshold must be 0-100\n");
                    return -1;
                }
                break;
            case 'd':
                pump_duration = atoi(optarg);
                if (pump_duration <= 0) {
                    fprintf(stderr, "Pump duration must be positive\n");
                    return -1;
                }
                break;
            case 's':
                sleep_interval = atoi(optarg);
                if (sleep_interval <= 0) {
                    fprintf(stderr, "Sleep interval must be positive\n");
                    return -1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (parse_arguments(argc, argv) != 0) return 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            log_message("ADC read failed, skipping cycle");
            sleep(sleep_interval);
            continue;
        }

        float moisture_level = calculate_moisture_level(adc_value);
        if (moisture_level < 0) {
            log_message("Moisture level calculation failed");
            sleep(sleep_interval);
            continue;
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture level: %.2f%% (ADC: %d)", moisture_level, adc_value);
        log_message(msg);

        if (moisture_level < threshold) {
            control_pump(1);
            log_message("Pump activated");
            gpioDelay(pump_duration * 1000000);
            control_pump(0);
            log_message("Pump deactivated");
        }

        sleep(sleep_interval);
    }

    log_message("Irrigation system stopped");
    cleanup();
    return 0;
}

