#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_CONV_REG     0x00
#define ADS1115_CONFIG_REG   0x01

/*
 * Config word:
 *   Bit 15    OS       = 1  (start single conversion)
 *   Bits14:12 MUX     = 100 (AIN0 single-ended)
 *   Bits11:9  PGA      = 001 (±4.096 V)
 *   Bit  8    MODE     = 1  (single-shot)
 *   Bits7:5   DR       = 100 (128 SPS)
 *   Bit  4    COMP_MODE= 0
 *   Bit  3    COMP_POL = 0
 *   Bit  2    COMP_LAT = 0
 *   Bit  1    COMP_QUE = 10 (disable comparator)
 *   Bit  0    COMP_LAT = 0
 * => 0x8483
 */
#define ADS1115_CONFIG_VALUE 0x8483

#define GPIO_SHUTDOWN       27
#define GAUSS_THRESHOLD     500.0f
#define SAMPLE_PERIOD_US    1000000  /* 1 Hz */
#define BUFFER_SIZE         100
#define VOLTAGE_MAX         3.3f
#define ADC_MAX             32767.0f

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  ads1115_init(void);
static int  ads1115_read_channel(int handle, int16_t *out);
static float voltage_to_gauss(int16_t raw);
static void add_to_buffer(float *buffer, int *index, float value);
static float calculate_rolling_average(float *buffer, int size, int index);
static void shutdown_motor(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- ADS1115 helpers --------------------------- */

static int ads1115_init(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed: %d", g_i2c_handle);
        return -1;
    }

    /* Write config word to start a single-shot conversion on AIN0 */
    char cfg[3];
    cfg[0] = ADS1115_CONFIG_REG;
    cfg[1] = (ADS1115_CONFIG_VALUE >> 8) & 0xFF;
    cfg[2] = ADS1115_CONFIG_VALUE & 0xFF;
    if (i2cWriteDevice(g_i2c_handle, cfg, 3) < 0) {
        syslog(LOG_ERR, "ADS1115 config write failed");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    syslog(LOG_INFO, "ADS1115 initialized on I2C bus %d, addr 0x%02X",
           I2C_BUS, ADS1115_ADDR);
    return 0;
}

static int ads1115_read_channel(int handle, int16_t *out)
{
    char reg = ADS1115_CONV_REG;
    char buf[2];

    /* Point to the conversion register */
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "ADS1115 reg-select failed");
        return -1;
    }

    /* Read 2 bytes of conversion data */
    if (i2cReadDevice(handle, buf, 2) != 2) {
        syslog(LOG_ERR, "ADS1115 conversion read failed");
        return -1;
    }

    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float voltage_to_gauss(int16_t raw)
{
    float v = (float)raw * (VOLTAGE_MAX / ADC_MAX);
    if (v < 0.0f)   v = 0.0f;
    if (v > VOLTAGE_MAX) v = VOLTAGE_MAX;
    return v * 1000.0f;  /* Gauss per volt */
}

/* ----------------------------- Buffer ----------------------------------- */

static float buffer[BUFFER_SIZE];
static int   buffer_index = 0;

static void add_to_buffer(float *buffer, int *index, float value)
{
    buffer[*index] = value;
    *index = (*index + 1) % BUFFER_SIZE;
}

static float calculate_rolling_average(float *buffer, int size, int index)
{
    float sum = 0.0f;
    for (int i = 0; i < size; i++)
        sum += buffer[i];
    return sum / (float)size;
}

/* ----------------------------- Shutdown ----------------------------------- */

static void shutdown_motor(void)
{
    if (gpioWrite(GPIO_SHUTDOWN, 1) < 0)
        syslog(LOG_ERR, "Failed to set GPIO %d HIGH", GPIO_SHUTDOWN);
}

/* ----------------------------- Signal / cleanup --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
    closelog();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(%d) failed", GPIO_SHUTDOWN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);

    if (ads1115_init() != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Monitoring started (threshold %.1f Gauss)", GAUSS_THRESHOLD);

    while (g_running) {
        int16_t raw;
        if (ads1115_read_channel(g_i2c_handle, &raw) == 0) {
            float voltage = (float)raw * (VOLTAGE_MAX / ADC_MAX);
            float gauss   = voltage_to_gauss(raw);

            add_to_buffer(buffer, &buffer_index, gauss);
            float avg = calculate_rolling_average(buffer, BUFFER_SIZE, buffer_index);

            syslog(LOG_INFO,
                   "Raw: %d, Voltage: %.3f V, Gauss: %.2f, Avg: %.2f",
                   raw, voltage, gauss, avg);

            if (avg > GAUSS_THRESHOLD) {
                syslog(LOG_WARNING, "Threshold exceeded: %.2f Gauss", avg);
                shutdown_motor();
            }
        } else {
            syslog(LOG_WARNING, "ADC read failed, skipping sample");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

