#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define MCP3008_CHANNEL 0
#define VREF           3.3f
#define ADC_MAX        1023
#define SAMPLE_PERIOD  1.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success and stores the 10-bit value in *out;
 * returns -1 on SPI transfer failure.
 */
static int read_mcp3008(int channel, int *out) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    if (out == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 live in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }

    *out = adc_value;
    return 0;
}

static void map_rainfall_intensity(int adc_value, int *intensity) {
    if (adc_value < 0) {
        *intensity = 0;
    } else if (adc_value > ADC_MAX) {
        *intensity = 100;
    } else {
        float voltage = (float)adc_value / (float)ADC_MAX * VREF;
        if (voltage < 0.0f) voltage = 0.0f;
        if (voltage > VREF) voltage = VREF;
        *intensity = (int)(voltage / 0.01f * 100.0f);
    }
}

static void log_rainfall_data(int adc_value, int intensity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - ADC: %d, Rainfall Intensity: %d\n", timestamp, adc_value, intensity);
    fflush(stdout);
}

