    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, speed %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rainfall monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int adc_value = 0;
        if (read_mcp3008(MCP3008_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Failed to read MCP3008 channel %d; retrying next cycle.\n",
                    MCP3008_CHANNEL);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        int intensity = 0;
        map_rainfall_intensity(adc_value, &intensity);
        log_rainfall_data(adc_value, intensity);

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

