/*
 * Raspberry Pi 4 Model B - Honeywell SS49E Hall-effect sensor monitor
 *
 * Hardware:
 *   - ADS1115 ADC on I2C bus 1 (address 0x48)
 *   - Honeywell SS49E on AIN0 (single-ended)
 *   - LED on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o hall_monitor hall_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./hall_monitor [-t threshold_gauss]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48

#define LED_GPIO             17

#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define BLINK_ON_US          50000    /* 50 ms on  */
#define BLINK_OFF_US         50000    /* 50 ms off */
#define BLINK_TOTAL_US       1000000  /* 1 s total  */

#define ADC_PGA_4_096V       4.096f
#define ADC_MAX_COUNT        32767.0f
#define ADC_REF_VOLTAGE      4.096f

#define DEFAULT_THRESHOLD    100.0f

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  ads1115_init(void);
static int  ads1115_read_channel0(int16_t *out);
static float adc_to_gauss(int16_t raw);
static void blink_led(int gpio, int duration_us);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 init ------------------------------ */
static int ads1115_init(void)
{
    /*
     * ADS1115 register addresses (16-bit, big-endian on the bus).
     * The ADS1115 is configured via the ADS1115_REG_CONV register
     * (0x00) and the ADS1115_REG_CONFIG register (0x01).
     */
    uint16_t config_word = 0x8000 |  /* Bit 15: write bit */
                            0x4000 |  /* Bit 14: OS=1 (start) */
                            0x0400  /* Bits 11-9: MUX=100 (AIN0 single-ended) */
                            0x0200  /* Bits 8-6: PGA=001 (4.096 V) */
                            0x0100  /* Bits 5-3: MODE=1 (single-shot) */
                            0x0080  /* Bit 7: DR=100 (128 SPS) */
                            0x0003  /* Bits 2-0: COMP_QUE=100 (disable comparator) */

    if (i2cWriteWordData(g_i2c_handle, ADS1115_REG_CONFIG, config_word) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register\n");
        return -1;
    }

    /*
     * Wait for the first conversion to complete (~8 ms at 128 SPS).
     * We poll the OS bit (bit 15) until it reads 1.
     */
    int waited = 0;
    while (i2cReadWordData(g_i2c_handle, ADS1115_REG_CONFIG) != 0x8000) {
        if (++waited > 100) {
            fprintf(stderr, "Error: ADS1115 conversion timeout\n");
            return -1;
        }
        gpioDelay(1000); /* 1 ms */
    }

    return 0;
}

/* ----------------------------- Read channel 0 ----------------------------- */
static int ads1115_read_channel0(int16_t *out)
{
    /*
     * Read the conversion register (0x00) and shift out the two MSBs
     * (bits 15-14) and the two LSBs (bits 11-0).
     */
    int hi = i2cReadWordData(g_i2c_handle, ADS1115_REG_CONV);
    if (hi < 0) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion register\n");
        return -1;
    }

    int lo = i2cReadWordData(g_i2c_handle, ADS1115_REG_CONV + 1);
    if (lo < 0) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion register (low)\n");
        return -1;
    }

    *out = (int16_t)((hi >> 8) | (lo & 0xFF));
    return 0;
}

/* ----------------------------- ADC to Gauss ----------------------------- */
static float adc_to_gauss(int16_t raw)
{
    /*
     * ADS1115 PGA gain 4.096 V -> 1 bit = 125 µV.
     * Raw count = (raw / 32767.0) * 4.096 V.
     * Magnetic field = (raw / 32767.0) * 4.096 V / 1.25 µV/Gauss.
     */
    return ((float)raw / 32767.0f) * ADC_REF_VOLTAGE / 1.25f;
}

/* ----------------------------- LED blink --------------------------------- */
static void blink_led(int gpio, int duration_us)
{
    gpioWrite(gpio, 1);
    gpioDelay(duration_us);
    gpioWrite(gpio, 0);
    gpioDelay(duration_us);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        threshold = strtof(argv[1], NULL);
        if (threshold <= 0.0f) {
            fprintf(stderr, "Warning: invalid threshold '%s', using default %.2f Gauss\n",
                    argv[1], DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (err=%d)\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init() < 0) {
        fprintf(stderr, "Error: ADS1115 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring Honeywell SS49E via ADS1115 on I2C bus %d, addr 0x%02X\n",
           I2C_BUS, ADS1115_ADDR);
    printf("Threshold: %.2f Gauss | LED: GPIO%d | Sample: %d ms\n",
           threshold, LED_GPIO, SAMPLE_PERIOD_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_channel0(&raw) < 0) {
            fprintf(stderr, "Warning: ADC read failed, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = adc_to_gauss(raw);
        printf("Field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("*** THRESHOLD EXCEEDED ***\n");
            blink_led(LED_GPIO, BLINK_TOTAL_US);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

