/*
 * Soil Moisture Monitor with Hysteresis Pump Control
 * Board:  Raspberry Pi 4 Model B
 * SPI:    MCP3008 on SPI0 (CE0=GPIO8, physical pin 24), 1 MHz
 * ADC:    MCP3008 channel 0
 * Relay:  GPIO17 (active-high, BCM)
 * MQTT:   Publishes moisture every 60 s to soil_moisture, subscribes
 *          pump_control to receive pump_on/pump_off commands.
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c \
 *          -lvpi -lmosquitto -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <mcp3008.h>
#include <mosquitto.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL        0          /* MCP3008 on CE0 (GPIO8)              */
#define SPI_SPEED          1000000    /* 1 MHz                             */
#define SPI_FLAGS          0          /* Mode 0, active-low CE              */
#define ADC_CHANNEL        0          /* MCP3008 single-ended channel 0     */
#define PUMP_GPIO          17         /* BCM pin for relay control           */
#define PUMP_ON_THRESHOLD  30.0f      /* moisture < 30 % -> pump ON          */
#define PUMP_OFF_THRESHOLD 35.0f      /* moisture > 35 % -> pump OFF         */
#define MQTT_BROKER        "localhost"
#define MQTT_PORT          1883
#define MQTT_TOPIC_PUB     "soil_moisture"
#define MQTT_TOPIC_SUB     "pump_control"
#define MQTT_KEEPALIVE_SEC 60
#define SAMPLE_INTERVAL_S  60
#define MAX_RETRIES        3

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static struct mosquitto *g_mosq = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void cleanup(void);
static int  read_mcp3008(int handle, int channel, uint16_t *out);
static float adc_to_moisture(uint16_t adc);
static int  set_pump(int gpio, int state);
static int  publish_moisture(float moisture);
static int  subscribe_to_pump(const char *topic, int client_id);
static void on_message(struct mosquitto *m, void *userdata,
                         const struct mosquitto_message *message);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        mcp3008_close(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
    closelog();
}

/* ----------------------------- MCP3008 read ------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low 8 bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int read_mcp3008(int handle, int channel, uint16_t *out)
{
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid ADC channel %d", channel);
        return -1;
    }
    if (out == NULL) {
        syslog(LOG_ERR, "read_mcp3008: null output pointer");
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (mcp3008_transfer(handle, &tr) < 0) {
        syslog(LOG_ERR, "mcp3008_transfer failed: %s", strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)rx[2];
    return 0;
}

/* ----------------------------- Moisture -> % ------------------------------ */
static float adc_to_moisture(uint16_t adc)
{
    if (adc == 0) return 100.0f;
    if (adc > 1023) adc = 1023;
    return 100.0f - ((float)adc / 1023.0f) * 100.0f;
}

/* ----------------------------- Pump control ------------------------------- */
static int set_pump(int gpio, int state)
{
    if (gpio_write(gpio, state) < 0) {
        syslog(LOG_ERR, "gpio_write(%d, %d) failed: %s", gpio, state, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Pump set to %s", state ? "ON" : "OFF");
    return 0;
}

/* ----------------------------- MQTT publish -------------------------------- */
static int publish_moisture(float moisture)
{
    char payload[64];
    int len = snprintf(payload, sizeof(payload), "%.2f", moisture);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        syslog(LOG_ERR, "MQTT payload formatting failed");
        return -1;
    }

    if (mosquitto_publish(g_mosq, NULL, MQTT_TOPIC_PUB, len, payload, 0, false) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- MQTT subscribe ----------------------------- */
static int subscribe_to_pump(const char *topic, int client_id)
{
    int rc = mosquitto_subscribe(g_mosq, NULL, topic, client_id);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT subscribe failed: %s", mosquitto_strerror(rc));
        return -1;
    }
    syslog(LOG_INFO, "Subscribed to %s (client %d)", topic, client_id);
    return 0;
}

/* ----------------------------- MQTT message callback ----------------------- */
static void on_message(struct mosquitto *m, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)m;
    (void)userdata;

    if (message->payloadlen > 0) {
        syslog(LOG_INFO, "Received MQTT message: %s", message->payload);
    }
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize MCP3008 */
    g_spi_handle = mcp3008_open(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        syslog(LOG_ERR, "Failed to open MCP3008: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize MQTT */
    mosquitto_lib_init();
    g_mosq = mosquitto_new(NULL, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", strerror(errno));
        mcp3008_close(g_spi_handle);
        g_spi_handle = -1;
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_message_callback_set(g_mosq, on_message);
    mosquitto_connect_callback_set(g_mosq, NULL);
    mosquitto_reconnect_delay_set(g_mosq, 5);

    int rc = mosquitto_connect(g_mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE_SEC);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    if (subscribe_to_pump(MQTT_TOPIC_SUB, 1) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (g_running) {
        uint16_t adc = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_mcp3008(g_spi_handle, ADC_CHANNEL, &adc) == 0) {
                ok = 1;
                break;
            }
            syslog(LOG_WARNING, "ADC read attempt %d/%d failed", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                sleep(1);
            }
        }

        if (!ok) {
            syslog(LOG_ERR, "ADC read failed after %d attempts; skipping cycle", MAX_RETRIES);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float moisture = adc_to_moisture(adc);

        if (publish_moisture(moisture) != 0) {
            syslog(LOG_ERR, "Failed to publish moisture reading");
        }

        if (moisture < PUMP_ON_THRESHOLD && !set_pump(PUMP_GPIO, 1) == 0) {
            syslog(LOG_ERR, "Failed to activate pump");
        } else if (moisture > PUMP_OFF_THRESHOLD && set_pump(PUMP_GPIO, 0) == 0) {
            syslog(LOG_INFO, "Pump deactivated (moisture above threshold)");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    /* Graceful shutdown */
    syslog(LOG_INFO, "Shutting down...");
    set_pump(PUMP_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

