        }

        float voltage = ((float)raw / 1023.0f) * VREF;

        printf("Raw: %u  Voltage: %.3f V\n", raw, voltage);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

