#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define VREF 3.3
#define NUM_CHANNELS 3
#define SAMPLE_INTERVAL_SEC 5

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * tx[0] = 0x01  (start bit)
     * tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     * tx[2] = 0x00  (don't care, clocks out low 2 bits)
     * Result: 10-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0f) * VREF;
}

static int log_data(float voltages[NUM_CHANNELS]) {
    FILE *fp = fopen("sensor_data.csv", "a");
    if (!fp) {
        perror("Error: Failed to open sensor_data.csv");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error: localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, voltages[0], voltages[1], voltages[2]);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGINT) failed");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGTERM) failed");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float voltages[NUM_CHANNELS];

    while (!terminate) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc = read_mcp3008(i);
            if (adc < 0) {
                fprintf(stderr, "Error: Failed to read channel %d\n", i);
                terminate = 1;
                break;
            }
            voltages[i] = adc_to_voltage(adc);
        }

        if (terminate) {
            break;
        }

        if (log_data(voltages) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
            terminate = 1;
            break;
        }

        printf("Logged: %.3f, %.3f, %.3f\n", voltages[0], voltages[1], voltages[2]);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL_SEC && !terminate; s++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

