    set_motor(MOTOR_1_GPIO, 0);
    set_motor(MOTOR_2_GPIO, 0);

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

