    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_1_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_1_GPIO, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_2_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_1_GPIO, 1000) < 0 ||
        gpioSetPWMrange(MOTOR_2_GPIO, 1000) < 0) {
        fprintf(stderr, "Error setting PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Vibration detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int noise_level = read_adc(0);
        if (noise_level < 0) {
            fprintf(stderr, "Error reading noise level, skipping iteration\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        int motor1_on = (noise_level > NOISE_THRESHOLD) ? 1 : 0;
        int motor2_on = (noise_level > NOISE_THRESHOLD) ? 1 : 0;

        set_motor(MOTOR_1_GPIO, motor1_on);
        set_motor(MOTOR_2_GPIO, motor2_on);

        if (noise_level > NOISE_THRESHOLD) {
            log_event("Vibration detected");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

