    if (i2c_write_byte(fd, BH1750_CMD_CONT_HIGH_REP) < 0)
        return -1;
    usleep(BH1750_CONV_MS * 1000);
    if (i2c_read_word(fd, (uint16_t *)buf) < 0)
        return -1;
    *light_level = (float)buf[0] + (float)buf[1] / 10.0f;
    return 0;
}

static int read_mcp3008(int fd, int channel, int *value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int read_sound_level(int channel, int *value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_data(FILE *fp, int sound_level, float light_level, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (error_code == 0) {
        fprintf(fp, "%s,%d,%.2f,0\n", timestamp, sound_level, light_level);
    } else {
        fprintf(fp, "%s,%d,%.2f,%d\n", timestamp, sound_level, light_level, error_code);
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open /dev/spidev0.0");
        close(i2c_fd);
        return 1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    fprintf(log_fp, "timestamp,sound_level_db,light_level_lux,error_code\n");
    fflush(log_fp);

    while (running) {
        int sound_level = -1;
        int light_level = -1.0f;
        int error_code = 0;

        if (read_sound_level(0, &sound_level) < 0) {
            error_code = 1;
        }
        if (read_bh1750(i2c_fd, &light_level) < 0) {
            error_code = 2;
        }

        log_data(log_fp, sound_level, light_level, error_code);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

