/*
 * Raspberry Pi 4 Model B – Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0), 1 MHz, mode 0
 *   - VH400 analog output wired to MCP3008 channel 0
 *   - Relay-driven water pump on BCM GPIO 17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lrt
 *   sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 on SPI0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */

#define PUMP_GPIO      17         /* BCM pin for relay-driven pump */
#define MOISTURE_THRESHOLD 30.0f  /* % – activate pump below this */
#define SAMPLE_INTERVAL_S  60     /* seconds between readings */
#define MAX_RETRIES      3

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Forward declarations ------------------------ */
static int  read_mcp3008(int channel, int *out_value);
static float convert_to_moisture_percentage(int adc_value);
static void control_pump(float moisture_percentage);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI bus --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pump GPIO %d.\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);   /* pump off at startup */

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started.\n");
    printf("  SPI: channel %d, %d Hz, mode 0\n", SPI_CHANNEL, SPI_SPEED);
    printf("  ADC: MCP3008 ch %d, %d-bit resolution\n", ADC_CHANNEL, 10);
    printf("  Pump: BCM GPIO %d (active-high)\n", PUMP_GPIO);
    printf("  Threshold: %.1f%%\n", MOISTURE_THRESHOLD);
    printf("  Sampling every %d s. Press Ctrl+C to exit.\n\n", SAMPLE_INTERVAL_S);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = 0;
        bool read_ok = false;

        /* Retry loop for transient SPI failures */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_mcp3008(ADC_CHANNEL, &adc_value) == 0) {
                read_ok = true;
                break;
            }
            fprintf(stderr, "Warning: MCP3008 read attempt %d/%d failed.\n",
                    attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(100000);  /* 100 ms backoff */
        }

        if (!read_ok) {
            fprintf(stderr, "Error: MCP3008 read failed after %d attempts. "
                            "Skipping sample.\n", MAX_RETRIES);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float moisture_percentage = convert_to_moisture_percentage(adc_value);

        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        printf("[%s] ADC=%4d  Moisture=%.2f%%  Pump=%s\n",
               ts, adc_value, moisture_percentage,
               (moisture_percentage < MOISTURE_THRESHOLD) ? "ON" : "OFF");

        control_pump(moisture_percentage);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; ++s)
            sleep(1);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- SPI read helper ------------------------------ */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d.\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        fprintf(stderr, "Error: read_mcp3008 called with NULL output pointer.\n");
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out low 8 bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", bytes);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

/* --------------------------- Moisture conversion -------------------------- */
static float convert_to_moisture_percentage(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX_VALUE) adc_value = ADC_MAX_VALUE;

    /*
     * VH400 output is 0 V (dry) to ~3.0 V (wet).
     * Linear mapping: moisture_pct = (adc_value / ADC_MAX_VALUE) * 100.0
     */
    return ((float)adc_value / (float)ADC_MAX_VALUE) * 100.0f;
}

/* --------------------------- Pump control --------------------------------- */
static void control_pump(float moisture_percentage)
{
    int target = (moisture_percentage < MOISTURE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(PUMP_GPIO, target) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed for pump GPIO %d.\n", PUMP_GPIO);
    }
}

/* --------------------------- Signal handler -------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Cleanup --------------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is off */
    if (g_spi_handle >= 0) {
        gpioWrite(PUMP_GPIO, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

