#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Configuration */
#define SPI_CHANNEL      0
#define SPI_SPEED        1000000  /* 1 MHz */
#define SPI_FLAGS        0        /* Mode 0, active-low CE */
#define VALVE_GPIO       17
#define PWM_FREQUENCY    100      /* Hz */
#define PWM_RANGE        100      /* 0-100 = 0-100 % */
#define SAMPLE_COUNT     3
#define LOG_INTERVAL_S   5
#define LOG_FILE         "irrigation.log"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup happens   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 on the given single-ended channel   */
/* Returns 0-1023 on success, -1 on error.                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel)
     *   Byte 2: 0x00                       (don't care, clocks out low bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the low 2 bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Compute the average of SAMPLE_COUNT raw ADC readings.              */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int compute_average(int *samples, int count)
{
    if (count <= 0 || samples == NULL) {
        return -1;
    }
    int sum = 0;
    for (int i = 0; i < count; i++) {
        if (samples[i] < 0) {
            return -1;
        }
        sum += samples[i];
    }
    return sum / count;
}

/* ------------------------------------------------------------------ */
/* Set the ASCO RedHat 8210 series proportional valve.                 */
/* pwmDuty is 0-100 (0 = off, 100 = full-speed).                       */
/* ------------------------------------------------------------------ */
static int set_valve_position(int pwm_duty)
{
    if (gpioPWM(VALVE_GPIO, pwm_duty) != 0) {
        fprintf(stderr, "gpioPWM failed for duty %d\n", pwm_duty);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading to the irrigation.log file.                           */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int *adc_values, int count,
                     int avg, int valve_position)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(fp, "%s, ADC1=%d, ADC2=%d, ADC3=%d, Avg=%d, Valve=%d%%\n",
            ts, adc_values[0], adc_values[1], adc_values[2], avg, valve_position);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure valve is off before terminating pigpio */
    gpioPWM(VALVE_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI device: channel 0, 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure valve GPIO for PWM output */
    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Initial gpioPWM failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    int adc_values[SAMPLE_COUNT];
    int consecutive_errors = 0;

    printf("Irrigation controller started. Logging to %s every %d s.\n",
           LOG_FILE, LOG_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int read_ok = 1;

        for (int i = 0; i < SAMPLE_COUNT && read_ok; i++) {
            int val = read_mcp3008(i);
            if (val < 0) {
                read_ok = 0;
                consecutive_errors++;
            } else {
                adc_values[i] = val;
                consecutive_errors = 0;
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Error: %d consecutive SPI read failures — "
                            "aborting.\n", consecutive_errors);
            break;
        }

        consecutive_errors = 0;

        int avg = compute_average(adc_values, SAMPLE_COUNT);
        if (avg < 0) {
            fprintf(stderr, "Error computing average.\n");
            break;
        }

        int valve_position = 0;
        if (avg > 500) {
            valve_position = 100;
        } else if (avg < 200) {
            valve_position = 0;
        }
        if (set_valve_position(valve_position) != 0) {
            fprintf(stderr, "Warning: failed to set valve position.\n");
        }

        log_data(g_log_file, adc_values, SAMPLE_COUNT, avg, valve_position);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < LOG_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

