/*
 * Theremin-like instrument using HC-SR04 ultrasonic sensor, MCP3008 ADC, and PWM on Raspberry Pi Zero W.
 *
 * Wiring:
 *   HC-SR04 Trig -> GPIO23 (BCM)
 *   HC-SR04 Echo -> GPIO24 (BCM)
 *   MCP3008 VDD  -> 3.3V, VREF -> 3.3V, AGND/DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Photoresistor (LDR)
 *
 * Build: gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define TRIG_PIN      23
#define ECHO_PIN      24
#define PWM_PIN       18
#define PWM_FREQ      1000
#define PWM_DUTY      128   /* 50% of 255 */
#define SPEED_OF_SOUND 34300.0
#define ADC_CHANNEL   0
#define ADC_RESOLUTION 1024
#define MAX_DISTANCE  400.0
#define MIN_DISTANCE  2.0
#define SAMPLE_DELAY_US 50000
#define SPI_DEVICE     "/dev/spidev0.0"
#define CONFIG_FILE    "theremin_config.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_pwm_fd = -1;
static int g_pwm_enabled = 0;

/* Calibration data */
static float g_distance_offset = 0.0;
static float g_distance_scale  = 1.0;
static float g_volume_offset   = 0.0;
static float g_volume_scale    = 1.0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read 10-bit value from MCP3008 single-ended channel (0-7). Returns -1 on error. */
static int read_mcp3008(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  -> single-ended + channel
     * Byte 2: 0x00 (don't care)
     * Response: bits 9-8 in lower 2 bits of rx[1], bits 7-0 in rx[2]
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE failed");
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

/* Read distance from HC-SR04. Returns -1.0 on timeout or error. */
static float read_distance(void)
{
    /* Ensure trigger is low */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Failed to write TRIG_PIN\n");
        return -1.0;
    }
    gpioDelay(2);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIG_PIN, 1) < 0) {
        fprintf(stderr, "Failed to write TRIG_PIN high\n");
        return -1.0;
    }
    gpioDelay(10);
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Failed to write TRIG_PIN low\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout ~100 ms) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > 100000) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout ~100 ms) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > 100000) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    float distance = (pulse_width * SPEED_OF_SOUND) / 2.0f;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0;
    }

    return distance;
}

/* Map distance to frequency (0..1000 Hz) */
static float map_distance_to_frequency(float distance)
{
    if (distance < 0.0f) distance = 0.0f;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    return (distance / MAX_DISTANCE) * 1000.0f;
}

/* Map volume to duty cycle (0..255) */
static float map_volume_to_duty(float volume)
{
    if (volume < 0.0f) volume = 0.0f;
    if (volume > 1.0f) volume = 1.0f;
    return (volume / 1.0f) * PWM_DUTY;
}

/* Write calibration data to file */
static int save_calibration(const char *filename)
{
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        perror("fopen for save");
        return -1;
    }
    fprintf(fp, "distance_offset=%.2f, distance_scale=%.2f, volume_offset=%.2f, volume_scale=%.2f\n",
            g_distance_offset, g_distance_scale, g_volume_offset, g_volume_scale);
    fclose(fp);
    return 0;
}

/* Load calibration data from file */
static int load_calibration(const char *filename)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open %s for load: %s\n", filename, strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *eq = strchr(line, '=');
        if (!eq) continue;
        *eq = '\0';
        char *key = line;
        char *val = eq + 1;
        while (*key == ' ' || *key == '\t') key++;
        while (*val == ' ' || *val == '\t') val++;
        if (strcmp(key, "distance_offset") == 0) {
            g_distance_offset = strtof(val, NULL);
        } else if (strcmp(key, "distance_scale") == 0) {
            g_distance_scale = strtof(val, NULL);
        } else if (strcmp(key, "volume_offset") == 0) {
            g_volume_offset = strtof(val, NULL);
        } else if (strcmp(key, "volume_scale") == 0) {
            g_volume_scale = strtof(val, NULL);
        }
    }
    fclose(fp);
    return 0;
}

/* Initialize PWM and SPI */
static int init_pwm(void)
{
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin mode\n");
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return -1;
    }
    if (gpioSetPWMrange(PWM_PIN, 255) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return -1;
    }
    if (gpioPWM(PWM_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        return -1;
    }
    g_pwm_enabled = 1;
    return 0;
}

static int init_spi(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_pwm_enabled) {
        gpioPWM(PWM_PIN, 0);
        g_pwm_enabled = 0;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_pwm_fd >= 0) {
        close(g_pwm_fd);
        g_pwm_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize PWM */
    if (init_pwm() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Load calibration */
    if (load_calibration(CONFIG_FILE) < 0) {
        fprintf(stderr, "No calibration file found; using defaults\n");
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance();
        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read error; using last valid values\n");
            distance = g_distance_offset + (distance - g_distance_offset) * g_distance_scale;
        }

        float frequency = map_distance_to_frequency(distance);
        float duty = map_volume_to_duty(distance);

        if (gpioPWM(PWM_PIN, (int)duty) < 0) {
            fprintf(stderr, "gpioPWM failed\n");
        }

        printf("Distance: %.2f cm, Frequency: %.2f Hz, Duty: %d\n",
               distance, frequency, (int)duty);

