            adc_value = read_mcp3008(spi_handle, MCP3008_CHANNEL);
            if (adc_value >= 0) {
                read_ok = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "SPI read attempt %d/%d failed\n", retries, MAX_RETRIES);
                    gpioDelay(RETRY_DELAY_US);
                }
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Failed to read ADC value after %d attempts. Skipping sample.\n", MAX_RETRIES);
        } else if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC reading at rail (%d). Sensor may be absent or disconnected.\n", adc_value);
        } else {
            int alcohol_detected = classify_alcohol_level(adc_value);
            if (log_alcohol_level(g_log_fp, alcohol_detected, adc_value) != 0) {
                fprintf(stderr, "Failed to log alcohol level.\n");
            }
        }

        if (g_running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    printf("\nShutting down gracefully...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

