#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOTOR1_ENABLE 18
#define MOTOR2_ENABLE 24
#define MOTOR1_DIRECTION 23
#define MOTOR2_DIRECTION 25
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1
#define HOLD_TIME 2
#define PAUSE_TIME 5
#define LOOP_DELAY 0.1

static volatile int running = 1;
static int spi_handle = -1;

void cleanup(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

void set_motor_speed(int motor, int speed) {
    if (speed < 0) speed = 0;
    if (speed > 100) speed = 100;
    int enable = (motor == 1) ? MOTOR1_ENABLE : MOTOR2_ENABLE;
    int dir = (motor == 1) ? MOTOR1_DIRECTION : MOTOR2_DIRECTION;
    gpioWrite(dir, (speed > 0) ? 1 : 0);
    gpioPWM(enable, speed);
}

void accelerate(int speed) {
    for (int i = 0; i <= speed && running; i++) {
        set_motor_speed(1, i);
        set_motor_speed(2, i);
        time_sleep(LOOP_DELAY);
    }
}

void decelerate(int speed) {
    for (int i = speed; i >= 0 && running; i--) {
        set_motor_speed(1, i);
        set_motor_speed(2, i);
        time_sleep(LOOP_DELAY);
    }
}

void reverse_motors(int speed) {
    set_motor_speed(1, -speed);
    set_motor_speed(2, -speed);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);
    while (running) {
        int p1 = read_mcp3008(POT1_CHANNEL);
        int p2 = read_mcp3008(POT2_CHANNEL);
        if (p1 < 0 || p2 < 0) {
            fprintf(stderr, "Potentiometer read error, skipping cycle\n");
            time_sleep(LOOP_DELAY);
            continue;
        }
        int speed1 = (int)(((float)p1 / 1023.0) * 100.0);
        int speed2 = (int)(((float)p2 / 1023.0) * 100.0);
        printf("Pot1: %d, Pot2: %d, Speed1: %d, Speed2: %d\n", p1, p2, speed1, speed2);
        accelerate(speed1);
        time_sleep(HOLD_TIME);
        decelerate(speed1);
        time_sleep(PAUSE_TIME);
        reverse_motors(speed2);
        time_sleep(PAUSE_TIME);
    }
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

