        time_sleep(HOLD_TIME);
        decelerate(speed1);
        time_sleep(PAUSE_TIME);
        reverse_motors(speed2);
        time_sleep(PAUSE_TIME);
    }
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
