#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_PIN 17
#define NOISE_THRESHOLD 500
#define DEBOUNCE_DELAY_US 10000
#define SAMPLE_DELAY_US 100000
#define CALIBRATION_DURATION_S 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * tx[0] = 0x01 (start bit)
     * tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     * tx[2] = 0x00 (don't care)
     * Result: 10-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int calibrate_noise_level(void) {
    int samples = 0;
    int sum = 0;
    int valid = 0;

    printf("Calibrating noise level for %d seconds...\n", CALIBRATION_DURATION_S);
    for (int i = 0; i < CALIBRATION_DURATION_S * 10 && running; i++) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error reading sample during calibration\n");
            return -1;
        }
        sum += sample;
        valid++;
        gpioDelay(SAMPLE_DELAY_US);
    }

    if (valid == 0) {
        fprintf(stderr, "No valid samples during calibration\n");
        return -1;
    }

    int avg = sum / valid;
    printf("Calibration complete. Average noise level: %d\n", avg);
    return avg;
}

