        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioWrite(LED_PIN, 0);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int noise_level = calibrate_noise_level();
    if (noise_level < 0) {
        fprintf(stderr, "Calibration failed\n");
        gpioWrite(LED_PIN, 0);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring sound levels. Press Ctrl+C to exit.\n");

    while (running) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error reading sample\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (sample > noise_level) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(LED_PIN) == 1) {
                gpioWrite(LED_PIN, 0);
            }
        } else {
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

