#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/time.h>
#include <sys/select.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP        "/dev/gpiochip0"
#define GPIO_CS_LINE     8          /* BCM GPIO 8, physical pin 24 */
#define GPIO_MOSI_LINE   10         /* BCM GPIO 10, physical pin 19 */
#define GPIO_MISO_LINE   9          /* BCM GPIO 9, physical pin 21 */
#define GPIO_SCLK_LINE   11         /* BCM GPIO 11, physical pin 23 */
#define LOG_FILE         "audio_log.txt"
#define SAMPLE_RATE_HZ   1000
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Open the SPI device and configure it for mode 0, 8-bit words, 1 MHz.
 * Returns a file descriptor on success, or -1 on error.
 */
static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success and stores the 10-bit value in *out;
 * returns -1 on error.
 */
static int mcp3008_read(int spi_fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value.
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_sample(FILE *fp, uint32_t timestamp_ns, uint16_t raw_adc)
{
    if (fprintf(fp, "%llu|%u\n", (unsigned long long)timestamp_ns, raw_adc) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *log_fp = NULL;
    int ret_code = EXIT_FAILURE;

    if (setup_signal_handlers() != 0) {
        goto cleanup;
    }

    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        goto cleanup;
    }

    /*
     * Configure GPIO lines as outputs and set them low.
     * We use the BCM numbering; the physical pin numbers are:
     *   CS  -> BCM 8  (physical 24)
     *   MOSI -> BCM 10 (physical 19)
     *   MISO -> BCM 9  (physical 21)
     *   SCLK -> BCM 11 (physical 23)
     */
    int cs_line = GPIO_CS_LINE;
    int mosi_line = GPIO_MOSI_LINE;
    int miso_line = GPIO_MISO_LINE;
    int sclk_line = GPIO_SCLK_LINE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /*
     * Request the GPIO lines for output.
     * Note: gpio_request() returns a negative value on failure;
     * we use the standard ioctl interface for manual line control.
     */
    struct gpio_line_config config;
    memset(&config, 0, sizeof(config));
    config.line_mask = (1 << cs_line) | (1 << mosi_line) |
                      (1 << miso_line) | (1 << sclk_line);
    config.flags = 0;

    if (gpio_line_request_output(&config, GPIO_CHIP, &config.line_mask) < 0) {
        fprintf(stderr, "gpio_line_request_output: %s\n", strerror(errno));
        goto cleanup;
    }

    /*
     * Ensure all lines start low.
     * Note: gpio_line_set_value() returns 0 on success, -1 on failure.
     */
    if (gpio_line_set_value(&config, cs_line, 0) < 0 ||
        gpio_line_set_value(&config, mosi_line, 0) < 0 ||
        gpio_line_set_value(&config, miso_line, 0) < 0 ||
        gpio_line_set_value(&config, sclk_line, 0) < 0) {
        fprintf(stderr, "gpio_line_set_value(initial): %s\n", strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Audio logging started. Press Ctrl+C to stop.\n");

    struct timespec next_deadline;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_deadline);

    while (g_running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);

        /*
         * Wait until the next 1 ms deadline.
         * If the deadline has passed, we sleep for the remainder of the
         * 1 ms period.
         */
        long remaining_ns = (long)(next_deadline.tv_sec - now.tv_sec) * 1000000000L +
                             (long)(next_deadline.tv_nsec - now.tv_nsec);
        if (remaining_ns > 0) {
            struct timespec sleep_ts = { .tv_sec = 0, .tv_nsec = remaining_ns };
            nanosleep(&sleep_ts, NULL);
        }

        uint16_t raw_adc = 0;
        if (mcp3008_read(spi_fd, 0, &raw_adc) < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
            nanosleep(&next_deadline, NULL);
            continue;
        }

        uint32_t timestamp_ns = (uint32_t)now.tv_sec * 1000000000L +
                                 (uint32_t)now.tv_nsec;

        if (log_sample(log_fp, timestamp_ns, raw_adc) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        next_deadline = now;
    }

    printf("\nShutting down cleanly.\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose(log): %s\n", strerror(errno));
        }
    }
    if (spi_fd >= 0) {
        if (close(spi_fd) != 0) {
            fprintf(stderr, "close(spi_fd): %s\n", strerror(errno));
        }
    }
    return ret_code;
}

