    int ret_code = EXIT_FAILURE;

    if (setup_signal_handlers() != 0) {
        goto cleanup;
    }

    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        goto cleanup;
    }

    /*
     * Configure GPIO lines as outputs and set them low.
     * We use the BCM numbering; the physical pin numbers are:
     *   CS  -> BCM 8  (physical 24)
     *   MOSI -> BCM 10 (physical 19)
     *   MISO -> BCM 9  (physical 21)
     *   SCLK -> BCM 11 (physical 23)
     */
    int cs_line = GPIO_CS_LINE;
    int mosi_line = GPIO_MOSI_LINE;
    int miso_line = GPIO_MISO_LINE;
    int sclk_line = GPIO_SCLK_LINE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /*
     * Request the GPIO lines for output.
     * Note: gpio_request() returns a negative value on failure;
     * we use the standard ioctl interface for manual line control.
     */
    struct gpio_line_config config;
    memset(&config, 0, sizeof(config));
    config.line_mask = (1 << cs_line) | (1 << mosi_line) |
                      (1 << miso_line) | (1 << sclk_line);
    config.flags = 0;

    if (gpio_line_request_output(&config, GPIO_CHIP, &config.line_mask) < 0) {
        fprintf(stderr, "gpio_line_request_output: %s\n", strerror(errno));
        goto cleanup;
    }

    /*
     * Ensure all lines start low.
     * Note: gpio_line_set_value() returns 0 on success, -1 on failure.
     */
    if (gpio_line_set_value(&config, cs_line, 0) < 0 ||
        gpio_line_set_value(&config, mosi_line, 0) < 0 ||
        gpio_line_set_value(&config, miso_line, 0) < 0 ||
        gpio_line_set_value(&config, sclk_line, 0) < 0) {
        fprintf(stderr, "gpio_line_set_value(initial): %s\n", strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Audio logging started. Press Ctrl+C to stop.\n");

    struct timespec next_deadline;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_deadline);

    while (g_running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);

        /*
         * Wait until the next 1 ms deadline.
         * If the deadline has passed, we sleep for the remainder of the
         * 1 ms period.
         */
        long remaining_ns = (long)(next_deadline.tv_sec - now.tv_sec) * 1000000000L +
                             (long)(next_deadline.tv_nsec - now.tv_nsec);
        if (remaining_ns > 0) {
            struct timespec sleep_ts = { .tv_sec = 0, .tv_nsec = remaining_ns };
            nanosleep(&sleep_ts, NULL);
        }

        uint16_t raw_adc = 0;
        if (mcp3008_read(spi_fd, 0, &raw_adc) < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
            nanosleep(&next_deadline, NULL);
            continue;
        }

        uint32_t timestamp_ns = (uint32_t)now.tv_sec * 1000000000L +
                                 (uint32_t)now.tv_nsec;

        if (log_sample(log_fp, timestamp_ns, raw_adc) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        next_deadline = now;
    }

    printf("\nShutting down cleanly.\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose(log): %s\n", strerror(errno));
        }
    }
    if (spi_fd >= 0) {
        if (close(spi_fd) != 0) {
            fprintf(stderr, "close(spi_fd): %s\n", strerror(errno));
        }
    }
    return ret_code;
}

