/*
 * ADXL335 + MCP3008 SPI accelerometer reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO,  Pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI,  Pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,   Pin 24)
 *   MCP3008 CH0  -> ADXL335 X-out
 *   MCP3008 CH1  -> ADXL335 Y-out
 *   MCP3008 CH2  -> ADXL335 Z-out
 *
 * Build:  gcc -O2 -Wall -o accel_mcp3008 accel_mcp3008.c -lpigpio -lrt
 * Run:    sudo ./accel_mcp3008
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNELS   3          /* CH0=X, CH1=Y, CH2=Z */
#define ADC_RESOLUTION 1024       /* 10-bit */

#define SAMPLE_PERIOD_US 100000   /* 100 ms -> 10 Hz */

/* ADXL335 full-scale range -> 1 g = 3.3 V / 1024 = 0.0032 g/LSB */
#define G_PER_LSB       0.0032f

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MCP3008 read ------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer, SPI mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | ch) << 4          (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
}

/* ----------------------------- Kalman filter ----------------------------- */
/*
 * Kalman filter state:
 *   state[0] = x_est   (g)
 *   state[1] = P_est    (covariance)
 *   state[2] = Q_est    (process noise)
 *   state[3] = R_est    (measurement noise)
 *
 * Prediction step:  state[0] += Q_est * dt
 * Update step:    state[0] += R_est * (measured - state[0])
 *                 P_est += -R_est * P_est
 */
static void kalman_update(float *state, float dt, float measured)
{
    float K = state[1] / (state[1] + state[3]);
    state[0] += K * (measured - state[0]);
    state[1] -= K * state[1];
    state[2] -= dt * K * state[2];
    state[3] -= dt * K * state[3];
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel=%d, speed=%d, flags=%d): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 + MCP3008 SPI reader started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float x_est = 0.0f, P_est = 0.0f, Q_est = 0.0f, R_est = 0.0f;
        float measured_x = -1.0f, measured_y = -1.0f, measured_z = -1.0f;

        for (int ch = 0; ch < ADC_CHANNELS; ch++) {
            int raw = mcp3008_read(ch);
            if (raw < 0) {
                fprintf(stderr, "ADC channel %d read failed; skipping sample\n", ch);
                continue;
            }

            /* Convert 10-bit to g */
            float g = (float)raw * G_PER_LSB;

            /* Kalman filter for X */
            kalman_update(&x_est, 0.01f, g);
            measured_x = g;

            /* Kalman filter for Y */
            kalman_update(&y_est, 0.01f, (float)raw * G_PER_LSB);
            measured_y = (float)raw * G_PER_LSB;

            /* Kalman filter for Z */
            kalman_update(&z_est, 0.01f, (float)raw * G_PER_LSB);
            measured_z = (float)raw * G_PER_LSB;
        }

        printf("X: %7.3f g  Y: %7.3f g  Z: %7.3f g\n", x_est, y_est, z_est);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

