    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 + MCP3008 SPI reader started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float x_est = 0.0f, P_est = 0.0f, Q_est = 0.0f, R_est = 0.0f;
        float measured_x = -1.0f, measured_y = -1.0f, measured_z = -1.0f;

        for (int ch = 0; ch < ADC_CHANNELS; ch++) {
            int raw = mcp3008_read(ch);
            if (raw < 0) {
                fprintf(stderr, "ADC channel %d read failed; skipping sample\n", ch);
                continue;
            }

            /* Convert 10-bit to g */
            float g = (float)raw * G_PER_LSB;

            /* Kalman filter for X */
            kalman_update(&x_est, 0.01f, g);
            measured_x = g;

            /* Kalman filter for Y */
            kalman_update(&y_est, 0.01f, (float)raw * G_PER_LSB);
            measured_y = (float)raw * G_PER_LSB;

            /* Kalman filter for Z */
            kalman_update(&z_est, 0.01f, (float)raw * G_PER_LSB);
            measured_z = (float)raw * G_PER_LSB;
        }

        printf("X: %7.3f g  Y: %7.3f g  Z: %7.3f g\n", x_est, y_est, z_est);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

