#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define VREF 3.3
#define ADC_MAX 1000.0
#define ADC_MIN 0.0
#define MIN_MGT 100.0
#define MAX_MGT 100.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Convert a digital Hall-effect sensor reading to millitesla.
 *
 * DRV5055VA: 3.3 V output drives the gate of the internal MOSFET.
 * When the gate is driven HIGH the MOSFET conducts, the current
 * through the Hall element is limited, and the output voltage is
 * ~3.3 V.  When the gate is driven LOW the MOSFET is off, the
 * current through the element is high, and the output voltage is
 * ~0.0 V.
 *
 * The Hall element's magnetic field is proportional to the
 * current through it.  We map the digital state (HIGH = 3.3 V,
 * LOW = 0.0 V) to a linear scale of millitesla.
 */
static double read_sensor(int gpio_pin) {
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n",
                gpio_pin, strerror(errno));
        return -1.0;
    }
    double voltage = (double)level * VREF;
    double mT = (voltage - ADC_MIN) / (ADC_MAX - ADC_MIN) * 1000.0;
    return mT;
}

static int log_data(double mT1, double mT2, double mT3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", mT1, mT2, mT3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void check_out_of_range(double mT) {
    if (mT < MIN_MGT - 1.0 || mT > MAX_MGT + 1.0) {
        fprintf(stderr,
                "Warning: sensor on GPIO %d output out of range [%.0f, %.0f] mT\n",
                SENSOR1_PIN, MIN_MGT, MAX_MGT);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR3_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        double mT1 = read_sensor(SENSOR1_PIN);
        double mT2 = read_sensor(SENSOR2_PIN);
        double mT3 = read_sensor(SENSOR3_PIN);

        check_out_of_range(mT1);
        check_out_of_range(mT2);
        check_out_of_range(mT3);

        if (log_data(mT1, mT2, mT3) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

