#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   tx[2] = 0x00  (don't care, clocks out low 2 bits)
     * Result: 10-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits)
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0) return -1.0f;
    return ((float)adc_value / 1023.0f) * 100.0f;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
            tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec, message);
    fclose(fp);
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error installing SIGTERM handler");
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Configure pump GPIO as output and ensure it starts OFF */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialise pump GPIO %d to LOW\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }

    /* Open SPI channel (CE0 on Raspberry Pi 4) */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioWrite(PUMP_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    log_event("Program started: Soil moisture monitoring started");

    while (program_running) {
        int adc_value = read_mcp3008(spi_handle, 0);
        if (adc_value < 0) {
            log_event("Error: Failed to read ADC value");
        } else {
            float moisture = calculate_moisture_percentage(adc_value);
            char message[128];

            if (moisture < MOISTURE_THRESHOLD) {
                if (gpioWrite(PUMP_GPIO, 1) == 0) {
                    snprintf(message, sizeof(message),
                             "Moisture low (%.1f%%). Pump ON.", moisture);
                    log_event(message);
                } else {
                    log_event("Error: Failed to turn pump ON");
                }
            } else {
                if (gpioWrite(PUMP_GPIO, 0) == 0) {
                    snprintf(message, sizeof(message),
                             "Moisture OK (%.1f%%). Pump OFF.", moisture);
                    log_event(message);
                } else {
                    log_event("Error: Failed to turn pump OFF");
                }
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    /* Clean shutdown: ensure pump is OFF */
    gpioWrite(PUMP_GPIO, 0);
    log_event("Program terminated: Pump turned OFF");

    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

