    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        goto cleanup;
    }

    printf("Starting MCP3008 data logging to %s. Press Ctrl+C to stop.\n", CSV_FILE);

    while (running) {
        int values[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            values[i] = read_mcp3008(spi_fd, i);
            if (values[i] < 0) {
