#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mqtt_client.h>

#define MQTT_BROKER_ADDRESS "mqtt.eclipseprojects.io"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_KEEP_ALIVE_INTERVAL 60
#define MQTT_RECONNECT_BACKOFF_BASE 1
#define MQTT_RECONNECT_BACKOFF_MAX 60
#define LED_GPIO 17

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t led_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static int parse_json(const char *json, int *led_state) {
    char *endptr;
    long val = strtol(json, &endptr, 10);
    if (endptr == json || *endptr != '\0') {
        return -1;
    }
    *led_state = (int)(val == 0 ? 0 : 1);
    return 0;
}

static void on_connect(struct mqtt_client *client, void *userdata) {
    (void)client;
    (void)userdata;
    printf("Connected to MQTT broker.\n");
}

static void on_disconnect(struct mqtt_client *client, void *userdata) {
    (void)client;
    (void)userdata;
    printf("Disconnected from MQTT broker.\n");
}

static void on_message(struct mqtt_client *client, void *userdata, const char *topic, const char *payload, int payload_len) {
    (void)client;
    (void)userdata;
    if (payload_len > 0) {
        char *payload_str = malloc(payload_len + 1);
        if (payload_str == NULL) {
            log_error("Failed to allocate memory for payload string");
            return;
        }
        memcpy(payload_str, payload, payload_len);
        payload_str[payload_len] = '\0';

        int led_state;
        if (parse_json(payload_str, &led_state) == 0) {
            led_state = led_state;
            printf("Received LED state: %s\n", led_state ? "ON" : "OFF");
        } else {
            log_error("Invalid JSON payload received");
        }

        free(payload_str);
    }
}

int main(void) {
    struct mqtt_client client;
    int rc;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    if (mqtt_client_new(&client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_CLIENT_ID, MQTT_CLIENT_KEEP_ALIVE_INTERVAL, NULL) != 0) {
        fprintf(stderr, "Failed to create MQTT client\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mqtt_client_connect_callback_set(&client, "rpi_led_control", on_connect, NULL) != 0) {
        fprintf(stderr, "Failed to set connect callback\n");
        mqtt_client_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mqtt_client_disconnect_callback_set(&client, "rpi_led_control", on_disconnect, NULL) != 0) {
        fprintf(stderr, "Failed to set disconnect callback\n");
        mqtt_client_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mqtt_client_message_callback_set(&client, "rpi_led_control", on_message, NULL) != 0) {
        fprintf(stderr, "Failed to set message callback\n");
        mqtt_client_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        mqtt_client_destroy(&client);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to install signal handlers");
        gpioTerminate();
        mqtt_client_destroy(&client);
        return EXIT_FAILURE;
    }

    printf("LED control program started. Press Ctrl+C to exit.\n");

    while (running) {
        rc = mqtt_client_connect(client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_CLIENT_ID, MQTT_CLIENT_KEEP_ALIVE_INTERVAL);
        if (rc != 0) {
            log_error("Failed to connect to MQTT broker");
            sleep(MQTT_RECONNECT_BACKOFF_BASE);
            if (running) {
                mqtt_client_reconnect(client);
            }
            continue;
        }

        rc = mqtt_client_subscribe(client, MQTT_TOPIC, 0);
        if (rc != 0) {
            log_error("Failed to subscribe to topic");
            sleep(MQTT_RECONNECT_BACKOFF_BASE);
            if (running) {
                mqtt_client_unsubscribe(client, MQTT_TOPIC);
            }
            continue;
        }

        rc = mqtt_client_start(client);
        if (rc != 0) {
            log_error("Failed to start MQTT client");
            sleep(MQTT_RECONNECT_BACKOFF_BASE);
            if (running) {
                mqtt_client_unsubscribe(client, MQTT_TOPIC);
            }
            continue;
        }

        while (running) {
            rc = mqtt_client_wait(client, 1000);
            if (rc != 0) {
                log_error("MQTT wait error");
                break;
            }

            rc = mqtt_client_read(client, NULL, NULL, NULL);
            if (rc != 0) {
                log_error("MQTT read error");
                break;
            }

            if (rc > 0) {
                int led_state;
                if (parse_json(NULL, &led_state) == 0) {
                    led_state = led_state;
                    gpioWrite(LED_GPIO, led_state);
                } else {
                    log_error("Failed to parse JSON payload");
                }
            }
        }

        if (running) {
            sleep(MQTT_RECONNECT_BACKOFF_BASE);
        }
    }

    printf("Shutting down...\n");
    gpioWrite(LED_GPIO, 0);
    mqtt_client_disconnect(client);
    mqtt_client_destroy(&client);
    gpioTerminate();

    return EXIT_SUCCESS;
}

