#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18
#define POLL_DELAY_US 100000  /* 100 ms */
#define ALARM_DURATION_US 1000000 /* 1 s */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed. "
                        "Is the pigpio daemon running? Try: sudo pigpiod\n");
        return EXIT_FAILURE;
    }

    /* Configure sound sensor pin as input */
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alarm LED pin as output */
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure alarm LED is off at start */
    if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW\n", ALARM_LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpioRead(SOUND_SENSOR_PIN);

        if (sound_level < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d\n", SOUND_SENSOR_PIN);
            break;
        }

        if (sound_level == 0) {
            /* Sound detected (DO pin LOW) */
            printf("Sound detected!\n");
            if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn on alarm LED\n");
                break;
            }
            gpioDelay(ALARM_DURATION_US);
            if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn off alarm LED\n");
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean up: turn off LED and terminate pigpio */
    gpioWrite(ALARM_LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

