    if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW\n", ALARM_LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpioRead(SOUND_SENSOR_PIN);

        if (sound_level < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d\n", SOUND_SENSOR_PIN);
            break;
        }

        if (sound_level == 0) {
            /* Sound detected (DO pin LOW) */
            printf("Sound detected!\n");
            if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn on alarm LED\n");
                break;
            }
            gpioDelay(ALARM_DURATION_US);
            if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn off alarm LED\n");
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean up: turn off LED and terminate pigpio */
    gpioWrite(ALARM_LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

