#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/file.h>
#include <sys/stat.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define CONSUMER_LABEL "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int log_event(const char *message) {
    int fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd < 0) {
        perror("Error opening log file");
        return -1;
    }

    struct stat st;
    if (fstat(fd, &st) < 0) {
        perror("Error fstat'ing log file");
        close(fd);
        return -1;
    }

    if (st.st_size == 0) {
        if (chmod(LOG_FILE, 0644) < 0) {
            perror("Error setting log file permissions");
            close(fd);
            return -1;
        }
    }

    if (dprintf(fd, "%s\n", message) < 0) {
        perror("Error writing to log file");
        close(fd);
        return -1;
    }

    if (close(fd) < 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    struct timespec ts = {0, 100000000}; /* 100 ms timeout */
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error setting SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error setting SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("Error getting GPIO line");
        goto cleanup_chip;
    }

    if (gpiod_line_request_falling_edge_events(line, CONSUMER_LABEL) < 0) {
        perror("Error requesting falling edge events on GPIO line");
        goto cleanup_chip;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        int rv = gpiod_line_event_wait(line, &ts);
        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Error waiting for GPIO event");
            break;
        }
        if (rv == 0) {
            continue;
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Error reading GPIO event");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            char message[256];
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            if (tm_info) {
                strftime(message, sizeof(message),
                         "Vibration detected! Shutdown command issued at %Y-%m-%d %H:%M:%S",
                         tm_info);
            } else {
                snprintf(message, sizeof(message),
                         "Vibration detected! Shutdown command issued");
            }

            printf("%s\n", message);
            if (log_event(message) < 0) {
                fprintf(stderr, "Warning: failed to log event.\n");
            }

            if (system("sudo shutdown -h now") < 0) {
                perror("Error executing shutdown command");
            } else {
                printf("Shutdown command executed successfully.\n");
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup_chip:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Vibration monitoring stopped.\n");
    return ret;
}

