/*
 * BMP280 Barometric Pressure/Temperature Sensor Logger
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (SDA=GPIO2/pin 3, SCL=GPIO3/pin 5)
 * Log:    altitude_log.txt
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_logger bmp280_logger.c -lpigpio -lrt
 * Run:    sudo ./bmp280_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP280 register addresses ---- */
#define BMP280_REG_CHIP_ID       0xD0
#define BMP280_REG_RESET         0xE0
#define BMP280_REG_CTRL_MEAS     0xF4
#define BMP280_REG_CONFIG        0xF5
#define BMP280_REG_PRESS_MSB     0xF7
#define BMP280_REG_TEMP_MSB      0xFA
#define BMP280_REG_CALIB_00      0x88
#define BMP280_REG_CALIB_25      0xE1

/* ---- Calibration coefficients ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(handle, reg) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    return i2cWriteByteData(handle, reg, value) < 0 ? -1 : 0;
}

/* ------------------------------------------------------------------ */
/* BMP280 helpers                                                      */
/* ------------------------------------------------------------------ */
static int bmp280_read_calibration(int handle, bmp280_calib_t *cal)
{
    uint8_t buf[26];
    if (i2c_read_reg(handle, BMP280_REG_CALIB_00, buf, sizeof(buf)) != 0)
        return -1;

    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int bmp280_init(int handle, bmp280_calib_t *cal)
{
    uint8_t chip_id;
    if (i2c_read_reg(handle, BMP280_REG_CHIP_ID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error: cannot read chip ID (I2C bus error or sensor absent).\n");
        return -1;
    }
    if (chip_id != 0x60) {
        fprintf(stderr, "Error: unexpected chip ID 0x%02X (expected 0x60).\n", chip_id);
        return -1;
    }

    if (i2c_write_reg(handle, BMP280_REG_RESET, 0xB6) != 0) {
        fprintf(stderr, "Error: failed to reset BMP280.\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms reset settling */

    if (bmp280_read_calibration(handle, cal) != 0) {
        fprintf(stderr, "Error: failed to read calibration data.\n");
        return -1;
    }

    /*
     * Config: t_sb=500ms (0x05<<5=0x20), filter off (0x00<<2=0x00),
     * spi3w_en=0, spi3r_en=0, spi3d=0 (0x00<<1=0x00).
     */
    if (i2c_write_reg(handle, BMP280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write config register.\n");
        return -1;
    }

    /* ctrl_meas: osrs_t=x1 (0x01<<5=0x08), osrs_p=x1 (0x01<<2=0x04),
     * mode=normal (0x03<<2=0x0C), t_sb=500ms (0x05<<5=0x08).
     */
    if (i2c_write_reg(handle, BMP280_REG_CTRL_MEAS, 0x25) != 0) {
        fprintf(stderr, "Error: failed to write ctrl_meas register.\n");
        return -1;
    }

    return 0;
}

static int bmp280_read_raw(int handle, int32_t *raw_t, int32_t *raw_p)
{
    uint8_t buf[6];
    if (i2c_read_reg(handle, BMP280_REG_PRESS_MSB, buf, 6) != 0)
        return -1;

    *raw_p = (int32_t)((uint32_t)buf[0] << 12 | (uint32_t)buf[1] << 4 | (uint32_t)buf[2] >> 4);
    *raw_t = (int32_t)((uint32_t)buf[3] << 12 | (uint32_t)buf[4] << 4 | (uint32_t)buf[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_t, const bmp280_calib_t *cal, int32_t *t_fine)
{
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)cal->dig_T1)) * ((raw_t >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

static double bmp280_compensate_press(int32_t raw_p, const bmp280_calib_t *cal, int32_t t_fine)
{
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) + ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0)
        return 0.0;
    p = 1048576 - raw_p;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (double)p / 256.0;
}

static double bmp280_calc_altitude(double pressure_pa)
{
    return 44330.0 * (1.0 - pow(pressure_pa / 101325.0, 0.1903));
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_altitude(FILE *fp, double altitude)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, altitude);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    bmp280_calib_t cal;
    int32_t raw_t, raw_p, t_fine;
    double pressure_pa, altitude;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, 0, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bmp280_init(g_i2c_handle, &cal) != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("altitude_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening altitude_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP280 logger started. Logging to altitude_log.txt every 5 s. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (bmp280_read_raw(g_i2c_handle, &raw_t, &raw_p) == 0) {
            int32_t t_fine;
            double temp_c = bmp280_compensate_temp(raw_t, &cal, &t_fine);
            double press_pa = bmp280_compensate_press(raw_p, &cal, t_fine);
            altitude = bmp280_calc_altitude(press_pa);
            log_altitude(g_log_file, altitude);
            printf("Temperature: %.2f C, Pressure: %.2f Pa, Altitude: %.2f m\n",
                   temp_c, press_pa, altitude);
        } else {
            fprintf(stderr, "Warning: failed to read sensor data.\n");
        }
        sleep(5);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

