#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL_SEC 5
#define MCP3008_CHANNEL 0

static int spi_handle = -1;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * tx[0] = 0x01 (start bit)
     * tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     * tx[2] = 0x00 (don't care)
     * Result: 10-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static float convert_to_celsius(int adc_value) {
    return (float)adc_value * 0.01;
}

static void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void log_to_file(float temperature) {
    FILE *fp = fopen("temp_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temp_log.dat for writing\n");
        return;
    }

    size_t written = fwrite(&temperature, sizeof(float), 1, fp);
    if (written != 1) {
        fprintf(stderr, "Error: Could not write all %d float values to file\n", BUFFER_SIZE);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: Error closing temp_log.dat\n");
    }
}

static void print_buffer(void) {
    printf("Temperature Buffer Contents:\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%d] %.2f °C\n", i, temperature_buffer[idx]);
    }
    printf("  (Oldest value at index %d, newest at index %d)\n",
           buffer_index, (buffer_index - buffer_count + BUFFER_SIZE - 1) % BUFFER_SIZE);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not install signal handlers\n");
    }

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read MCP3008 channel %d\n", MCP3008_CHANNEL);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float temperature = convert_to_celsius(adc_value);
        add_to_buffer(temperature);
        log_to_file(temperature);
        print_buffer();

        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nTemperature logging stopped.\n");
    return EXIT_SUCCESS;
}

