    }
    return 0;
}

static int i2c_read_word(int fd, unsigned short *word) {
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *word = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_light_level(int fd) {
    unsigned char buf[2];
    if (i2c_read_word(fd, &buf[0]) < 0) {
        return -1;
    }
    if (i2c_read_word(fd, &buf[1]) < 0) {
        return -1;
    }
    unsigned short raw = (buf[0] << 8) | buf[1];
    return (int)raw;
}

static int read_sound_level(int spi_fd) {
    unsigned char tx_buf[3] = {0x01, (0x08 | MCP3008_CHANNEL) << 4, 0x00};
    unsigned char rx_buf[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

static int log_data(const char *filename, int light_level, int sound_level) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s, Light: %d, Sound: %d\n", timestamp, light_level, sound_level) < 0) {
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI bus");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &(unsigned int){0}) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &(unsigned int){0}) < 0) {
        perror("ioctl SPI_IOC_RD_MODE");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(unsigned int){1000000}) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &(unsigned int){1000000}) < 0) {
        perror("ioctl SPI_IOC_RD_MAX_SPEED_HZ");
        goto cleanup;
    }

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int light_level = read_light_level(i2c_fd);
        if (light_level < 0) {
            fprintf(stderr, "Error reading light level from BH1750.\n");
        } else {
            int sound_level = read_sound_level(spi_fd);
            if (sound_level < 0) {
                fprintf(stderr, "Error reading sound level from MCP3008.\n");
            } else {
                if (log_data(LOG_FILE, light_level, sound_level) < 0) {
                    fprintf(stderr, "Error logging data.\n");
                } else {
                    printf("Light: %d lux, Sound: %d\n", light_level, sound_level);
                }
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    printf("Environmental monitoring stopped.\n");
    return EXIT_SUCCESS;
}

