#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static int log_event(const char *timestamp, int pin, int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, pin, state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void)
{
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return value;
}

static void print_alarm(int pin, int state)
{
    if (state == 1) {
        printf("ALARM: Flame detected on GPIO %d\n", pin);
        fflush(stdout);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_PIN);
    fflush(stdout);

    while (program_running) {
        int value = read_flame_sensor();
        if (value < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        time_t rawtime;
        time(&rawtime);
        struct tm *timeinfo = localtime(&rawtime);
        char timestamp[32];
        if (timeinfo != NULL) {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        } else {
            snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
        }

        if (log_event(timestamp, FLAME_SENSOR_PIN, value) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        print_alarm(FLAME_SENSOR_PIN, value);

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

