#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP4725_ADDR 0x24
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, tx, rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
            return adc_value;
        }
        fprintf(stderr, "Warning: SPI transfer failed (attempt %d/%d), ret=%d\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(10000);
    }
    return -1;
}

static float adc_to_celsius(int adc_value) {
    return (float)adc_value * 100.0f / 1023.0f - 50.0f;
}

static int write_mcp4725(int voltage) {
    if (voltage < 0.0f) {
        fprintf(stderr, "Error: Invalid DAC voltage %f\n", voltage);
        return -1;
    }

    char tx[3] = { 0x00, (char)((voltage * 1023.0f) / 3.3f) << 8, 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, tx, rx, 3);
        if (ret == 3) {
            return 0;
        }
        fprintf(stderr, "Warning: SPI write failed (attempt %d/%d), ret=%d\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(10000);
    }
    return -1;
}

static void log_data(int adc_value, float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ADC: %d, Temperature: %.2f C, DAC Voltage: %.2f V\n",
            timestamp, adc_value, temperature, voltage);
    fflush(log_file);
    printf("%s, ADC: %d, Temperature: %.2f C, DAC Voltage: %.2f V\n",
           timestamp, adc_value, temperature, voltage);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read MCP3008 after %d retries\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);
        float voltage = (temperature + 50.0f) / 100.0f * 3.3f;

        if (write_mcp4725(voltage) < 0) {
            fprintf(stderr, "Error: Failed to write MCP4725 after %d retries\n", MAX_RETRIES);
        }

        log_data(adc_value, temperature, voltage);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

