#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* BCM GPIO pin numbers for the four Songle SRD-05VDC-SL relays */
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

/* Debounce delay in microseconds (100 ms) */
#define DEBOUNCE_US 100000

/* Activation duration for each relay in milliseconds */
#define ACTIVATION_MS 1000

/* Delay between relays in milliseconds */
#define RELAY_DELAY_MS 1000

/* Global flag for graceful shutdown */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup happens   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Activate a relay (active-high module) — returns 0 on success, -1 on error */
/* ------------------------------------------------------------------ */
static int activate_relay(int pin)
{
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, 1) failed\n", pin);
        return -1;
    }
    gpioDelay(DEBOUNCE_US);

    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, 0) failed\n", pin);
        return -1;
    }
    gpioDelay(DEBOUNCE_US);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Deactivate a relay (active-high module) — returns 0 on success, -1 on error */
/* ------------------------------------------------------------------ */
static int deactivate_relay(int pin)
{
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, 0) failed\n", pin);
        return -1;
    }
    gpioDelay(DEBOUNCE_US);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Activate all four relays in sequence, then deactivate them all    */
/* ------------------------------------------------------------------ */
static int activate_and_deactivate_all(void)
{
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (activate_relay(pins[i]) != 0)
            return -1;
        gpioDelay(ACTIVATION_MS * 1000);
        if (deactivate_relay(pins[i]) != 0)
            return -1;
        gpioDelay(RELAY_DELAY_MS * 1000);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup: deactivate all relays and release all GPIO lines          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Safety: deactivate all relays first */
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));
    for (int i = 0; i < num_pins; i++) {
        gpioWrite(pins[i], 0);
    }

    /* Release all GPIO lines */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pins as outputs */
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    /* Ensure all relays start deactivated (LOW for active-high) */
    for (int i = 0; i < 4; i++) {
        gpioWrite(RELAY1_PIN + i, 0);
        gpioWrite(RELAY2_PIN + i, 0);
        gpioWrite(RELAY3_PIN + i, 0);
        gpioWrite(RELAY4_PIN + i, 0);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Songle SRD-05VDC-SL light sequencer started. Press Ctrl+C to stop.\n");

    /* Main loop: activate and deactivate relays sequentially */
    while (g_running) {
        if (activate_and_deactivate_all() != 0) {
            fprintf(stderr, "Error: relay sequence failed, exiting\n");
            break;
        }
    }

    /* Graceful cleanup */
    cleanup();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

