#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* MCP3008 on SPI channel 0 (CE0)        */
#define SPI_SPEED        1000000    /* 1 MHz SPI clock                       */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                 */
#define RAIN_THRESHOLD   5          /* Rain level threshold (0-1023)        */
#define MOTOR_FORWARD_SEC 3         /* Motor forward for 3 seconds          */
#define MOTOR_REVERSE_SEC 3         /* Motor reverse for 3 seconds          */
#define MOTOR_IN1_PIN    17         /* BCM 17 -> L298N IN1                  */
#define MOTOR_IN2_PIN    18         /* BCM 18 -> L298N IN2                  */
#define MOTOR_ENA_PIN    27         /* BCM 27 -> L298N ENA                  */
#define PWM_DUTY         150        /* 0-255 duty cycle for L298N ENA      */
#define LOG_FILE         "rain_log.txt"
#define POLL_INTERVAL_US 1000000    /* 1 second between readings            */

/* ----------------------------- Globals ---------------------------------- */
static int  spi_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t program_running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel);
static void set_motor(int forward, int reverse);
static void log_data(int rain_level);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- Implementation ----------------------------- */

/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0-1023 on success, or -1 on error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
