#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADC_GPIO 26
#define LED_GPIO 16
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int gpio) {
    int count = 0;
    for (int i = 0; i < 100; i++) {
        if (gpioSetMode(gpio, PI_INPUT) < 0) return -1;
        gpioDelay(1000);
        count = (count << 1) | (gpioRead(gpio) & 1);
        gpioDelay(1000);
    }
    return count;
}

static int detect_clap(int *prev_count, int *curr_count) {
    if (*prev_count == 0) return 0;
    int diff = *curr_count - *prev_count;
    if (diff < 0) diff = -diff;
    return (diff > 100);
}

static void trigger_led(int gpio, int duration_ms) {
    if (gpioWrite(gpio, 1) < 0) {
        fprintf(stderr, "Error: failed to turn on LED\n");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(gpio, 0) < 0) {
        fprintf(stderr, "Error: failed to turn off LED\n");
    }
}

static void log_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ADC_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ADC GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set LED GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize LED state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to register signal handler\n");
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int prev_count = 0;
    int curr_count;

    printf("Clap detection system started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        curr_count = read_adc(ADC_GPIO);
        if (curr_count < 0) {
            fprintf(stderr, "Error: ADC read failed\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (detect_clap(&prev_count, &curr_count)) {
            if (prev_count == 0) {
                log_event();
            } else {
                gpioDelay(DEBOUNCE_MS * 1000);
                if (!running) break;
                if (detect_clap(&prev_count, &curr_count)) {
                    log_event();
                    trigger_led(LED_GPIO, LED_ON_MS);
                }
            }
        }

        prev_count = curr_count;
        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

