#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS         8
#define SPI_MODE         0
#define ADC_CHANNEL      0
#define SAMPLE_PERIOD_US 500000U
#define LOG_FILE         "magnetic_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success (value stored in *out), -1 on error.
 */
static int read_mcp3008(int spi_fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result:
     *   rx[1] bits 1:0  -> MSB of 10-bit result
     *   rx[2]          -> LSB of 10-bit result
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static double raw_to_b_mt(uint16_t raw)
{
    /*
     * DRV5055-A1: 100 mT full-scale output.
     * 1 bit = 1/100 mT.
     * For a 10-bit ADC, 100 mT = 1000000 mT.
     * raw * 1000000.0 / 1024.0  -> mT
     * raw * 1000000.0 / 1024.0  -> mT
     */
    return (double)raw * 1000000.0 / 1024.0;
}

static int log_data(FILE *fp, double b_mt)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%ld,%.2f\n", (long)now, b_mt) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *log_fp = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    /*
     * Open the SPI device.
     * spidev supports mode 0, 1, and 2, but we set mode 0 explicitly.
     */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("DRV5055-A1 logging started. Sampling every 500 ms. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw = 0;
        if (read_mcp3008(spi_fd, ADC_CHANNEL, &raw) != 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
        } else {
            double b_mt = raw_to_b_mt(raw);
            if (log_data(log_fp, b_mt) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("B_mt: %.2f mT\n", b_mt);
            }
        }

        /*
         * Sleep 500 ms.  Use usleep for portability across Linux kernels.
         * If interrupted by a signal, g_running is already 0.
         */
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
        }
    }
    if (spi_fd >= 0) {
        if (close(spi_fd) != 0) {
            fprintf(stderr, "close(spi) failed: %s\n", strerror(errno));
        }
    }
    return rc;
}

