    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Magnetic Field: %.2f mT\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, magnetic_field);
    } else {
        fprintf(fp, "Timestamp error, Magnetic Field: %.2f mT\n", magnetic_field);
    }

    fclose(fp);
}

static void control_led(float magnetic_field) {
    int level = (magnetic_field > FIELD_THRESHOLD) ? 1 : 0;
    if (gpioWrite(LED_PIN, level) != 0) {
        fprintf(stderr, "Warning: failed to write LED pin\n");
    }
}

