    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (raw_value < 0) {
        fprintf(fp, "%s,ERROR\n", timestamp);
    } else {
        fprintf(fp, "%s,%d\n", timestamp, raw_value);
    }

    fclose(fp);
}

