#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/stat.v.h>

#define PIR_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_MS 50
#define CAPTURE_DIR "/home/pi/security_cam"
#define FILENAME_MAX_LEN 256
#define TIMESTAMP_MAX_LEN 32

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    g_running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) {
            return 0;
        }
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat('%s') failed: %s", path, strerror(errno));
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "mkdir('%s') failed: %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        /* Child process */
        char *const argv[] = {
            "libcamera-still",
            "-o", (char *)filename,
            "--immediate",
            NULL
        };
        execvp("libcamera-still", argv);
        syslog(LOG_ERR, "execvp(libcamera-still) failed: %s", strerror(errno));
        _exit(127);
    }
    /* Parent process */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            continue;
        }
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured: %s", filename);
        return 0;
    }
    syslog(LOG_ERR, "libcamera-still failed (status=%d)", WEXITSTATUS(status));
    return -1;
}

static void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
    fprintf(stderr, "%s\n", message);
}

int main(void) {
    openlog("security_camera", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(CAPTURE_DIR) != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_INPUT) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started (GPIO%d, %s)", PIR_GPIO, CAPTURE_DIR);

    while (g_running) {
        int pir_value = gpioRead(PIR_GPIO);
        if (pir_value < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed", PIR_GPIO);
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_value == 1) {
            syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);

            /* Debounce: wait, then re-read to confirm */
            usleep(DEBOUNCE_DELAY_MS * 1000);
            int confirmed = gpioRead(PIR_GPIO);
            if (confirmed < 0) {
                syslog(LOG_ERR, "gpioRead(debounce) failed");
                continue;
            }
            if (confirmed == 1) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[TIMESTAMP_MAX_LEN];
                char filename[FILENAME_MAX_LEN];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                if (timeinfo == NULL) {
                    syslog(LOG_ERR, "localtime() failed");
                    continue;
                }
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
                snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", CAPTURE_DIR, timestamp);

                if (capture_image(filename) == 0) {
                    log_event("Image captured successfully.");
                } else {
                    log_event("Failed to capture image.");
                }
            } else {
                syslog(LOG_WARNING, "Motion debounced (GPIO%d) — re-read failed", PIR_GPIO);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Security camera shutting down.");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

