static int capture_frame(int fd, uint8_t *buffer, size_t *length) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }
    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queueing buffer: %s\n", strerror(errno));
        return -1;
    }
    *length = buf.bytesused;
    memcpy(buffer, buffer, *length);
    return 0;
}

static int log_timestamp(FILE *fp, const uint8_t *frame) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
