        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        struct timeval tv;
        tv.tv_sec = POLL_TIMEOUT_SEC;
        tv.tv_usec = 0;
        int ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error during select(): %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            continue;
        }
        if (capture_frame(fd, buffer, &(*length)) < 0) {
            fprintf(stderr, "Error capturing frame\n");
            break;
        }
        if (log_timestamp(fp, buffer) < 0) {
            fprintf(stderr, "Error logging timestamp\n");
            break;
        }
    }
    printf("\nShutting down...\n");
    munmap(buffer, MAX_FRAME_SIZE);
    fclose(fp);
    close(fd);
    printf("Exiting.\n");
    return 0;
}

