#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>

#define VIDEO_DEVICE "/dev/video0"
#define UDP_PORT 5000
#define MAX_PAYLOAD 65000
#define NUM_FRAMES 4
#define FRAME_SIZE (NUM_FRAMES * 1920 * 1080 * 2)
#define FRAME_BYTES (FRAME_SIZE / NUM_FRAMES)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_video_capture(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    *fd = open(VIDEO_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Error opening video device");
        return -1;
    }

    if (ioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", VIDEO_DEVICE);
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1920;
    fmt.fmt.pix.height = 1080;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_FRAMES;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(*fd);
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    for (i = 0; i < NUM_FRAMES; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(*fd);
            return -1;
        }

        if (buf.length < FRAME_BYTES) {
            fprintf(stderr, "Error: Buffer %d too small (%d bytes)\n", i, buf.length);
            close(*fd);
            return -1;
        }

        if (ioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queueing buffer");
            close(*fd);
            return -1;
        }
    }

    for (i = 0; i < NUM_FRAMES; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(*fd, VIDIOC_DRM_SET_BUFFER, &buf) < 0) {
            perror("Error setting buffer");
            close(*fd);
            return -1;
        }
    }

    *fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK);
    if (*fd < 0) {
        perror("Error reopening video device");
        close(*fd);
        return -1;
    }

    return 0;
}

static int setup_udp_socket(int *sock) {
    *sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (*sock < 0) {
        perror("Error creating socket");
        return -1;
    }
    return 0;
}

static int setup_network(int video_fd, int udp_sock) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_PORT);

    if (inet_pton(AF_INET, "192.168.1.100", &addr.sin_addr) <= 0) {
        perror("Error converting IP address");
        return -1;
    }

    if (connect(udp_sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error connecting to UDP socket");
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, unsigned char *buffer, int *buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (copy_to_buffer(buffer, buffer, buf.bytesused) < 0) {
        perror("Error copying buffer");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queueing buffer");
        return -1;
    }

    return 0;
}

static int fragment_frame(unsigned char *frame, int frame_size, int *fragments, int *num_fragments, unsigned char **fragments_out) {
    int fragment_size = 0;
    int remaining = frame_size;
    int fragment_index = 0;

    for (int i = 0; i < num_fragments; i++) {
        if (remaining <= MAX_PAYLOAD) {
            *fragments[i] = (unsigned char *)malloc(remaining);
            if (!*fragments[i]) {
                perror("Error allocating memory for fragment");
                return -1;
            }
            memcpy(*fragments[i], frame + fragment_size, remaining);
            break;
        }

        *fragments[i] = (unsigned char *)malloc(MAX_PAYLOAD);
        if (!*fragments[i]) {
            perror("Error allocating memory for fragment");
            return -1;
        }

        memcpy(*fragments[i], frame + fragment_size, MAX_PAYLOAD);
        fragment_size = MAX_PAYLOAD;
        remaining -= MAX_PAYLOAD;
        fragment_index++;
    }

    if (remaining > 0) {
        *fragments[num_fragments - 1] = (unsigned char *)malloc(remaining);
        if (!*fragments[num_fragments - 1]) {
            perror("Error allocating memory for last fragment");
            return -1;
        }
        memcpy(*fragments[num_fragments - 1], frame + fragment_size, remaining);
    }

    *num_fragments = num_fragments + fragment_index;
    return 0;
}

static int send_udp_packet(int udp_sock, int fragment_index, int total_fragments, int payload_size) {
    unsigned char *packet;
    unsigned char header[40];
    int header_size;

    header_size = 40;
    packet = (unsigned char *)malloc(header_size);
    if (!packet) {
        perror("Error allocating memory for header");
        return -1;
    }

    header[0] = (total_fragments & 0xFF) << 8;
    header[1] = (total_fragments >> 8) & 0xFF;
    header[2] = fragment_index & 0xFF;
    header[3] = (fragment_index >> 8) & 0xFF;

    memcpy(packet, header, header_size);

    memcpy(packet + header_size, frame, payload_size);

    if (sendto(udp_sock, packet, header_size + payload_size, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP packet");
        free(packet);
        return -1;
    }

    free(packet);
    return 0;
}

static void copy_to_buffer(unsigned char *src, unsigned char *dst, int size) {
    memcpy(dst, src, size);
}

int main(int argc, char *argv[]) {
    int video_fd = -1;
    int udp_sock = -1;
    int frame_index = 0;
    int frame_bytes = FRAME_BYTES;
    int num_fragments = 0;
    int total_fragments = 0;
    unsigned char *frame = (unsigned char *)malloc(FRAME_BYTES);
    unsigned char *fragments[NUM_FRAMES];
    unsigned char *packet;
    struct v4l2_buffer buf;
    int ret;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    if (setup_video_capture(&video_fd) < 0) {
        return 1;
    }

    if (setup_udp_socket(&udp_sock) < 0) {
        close(video_fd);
        return 1;
    }

    if (setup_network(video_fd, udp_sock) < 0) {
        close(video_fd);
        close(udp_sock);
        return 1;
    }

    printf("Video streaming started. Press Ctrl+C to stop.\n");

    while (running) {
        ret = capture_frame(video_fd, frame, &frame_bytes);
        if (ret < 0) {
            fprintf(stderr, "Error capturing frame\n");
            break;
        }

        if (num_fragments == 0) {
            num_fragments = 1;
            total_fragments = 1;
            frame_index = 0;
        } else {
            total_fragments++;
        }

        if (total_fragments >= NUM_FRAMES) {
            if (frame_index == 0) {
                frame_index = 1;
            } else {
                frame_index = 0;
            }

            if (num_fragments == 0) {
                num_fragments = 1;
                frame = (unsigned char *)malloc(FRAME_BYTES);
                if (!frame) {
                    perror("Error allocating memory for frame");
                    break;
                }
            }

            if (frame_index < NUM_FRAMES) {
                if (fragment_frame(frame, frame_bytes, fragments, &num_fragments, &total_fragments) < 0) {
                    fprintf(stderr, "Error fragmenting frame\n");
                    break;
                }
            } else {
                if (send_udp_packet(udp_sock, 0, total_fragments, frame_bytes) < 0) {
                    fprintf(stderr, "Error sending UDP packet\n");
                    break;
                }
            }

            frame_index = 0;
            total_fragments = 0;
            num_fragments = 0;
        }
    }

    printf("Shutting down...\n");

    if (video_fd >= 0) {
        ioctl(video_fd, VIDIOC_QBUF, &buf);
        close(video_fd);
    }

    if (udp_sock >= 0) {
        close(udp_sock);
    }

    if (frame) {
        free(frame);
    }

    return 0;
}

