#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define OUTPUT_FILE "image.jpg"
#define NUM_BUFFERS 4
#define WIDTH 192

static volatile sig_atomic_t g_stop = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd == -1) {
        perror("open");
        return -1;
    }
    return fd;
}

static int query_capabilities(int fd) {
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }
    return 0;
}

static int set_pixel_format(int fd, enum v4l2_fmtimg fmt, int width, int height) {
    struct v4l2_fmtdesc fmt_desc;
    memset(&fmt_desc, 0, sizeof(fmt_desc));
    fmt_desc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt_desc.fmt.pix.width = width;
    fmt_desc.fmt.pix.height = height;
    fmt_desc.fmt.pix.pixelformat = fmt;
    fmt_desc.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt_desc) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    return 0;
}

static int request_buffers(int fd, struct v4l2_buffer *buffers, int n_buffers) {
    memset(buffers, 0, (size_t)n_buffers * sizeof(struct v4l2_buffer));
    buffers[0].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buffers[0].memory = V4L2_MEMORY_MMAP;
    buffers[0].index = 0;
    if (ioctl(fd, VIDIOC_REQBUFS, &buffers[0]) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }
    if (buffers[0].count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }
    for (int i = 1; i < n_buffers; i++) {
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;
        buffers[i].index = i;
        if (ioctl(fd, VIDIOC_QBUF, &buffers[i]) == -1) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }
    return 0;
}

static int start_streaming(int fd) {
    if (ioctl(fd, VIDIOC_STREAMON, V4L2_STREAM_CAPTURE) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int stop_streaming(int fd) {
    if (ioctl(fd, VIDIOC_STREAMOFF, V4L2_STREAM_CAPTURE) == -1) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

static int dequeue_frame(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_DQBUF, buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }
    return 0;
}

static int write_raw_jpeg(const unsigned char *data, int size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }
    size_t written = fwrite(data, 1, size, fp);
    if (written != size) {
        perror("fwrite");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) == EOF) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    if (install_signal_handlers() == -1) {
        return EXIT_FAILURE;
    }

    int fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (query_capabilities(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (set_pixel_format(fd, V4L2_PIX_FMT_MJPEG, WIDTH, HEIGHT) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buffers[NUM_BUFFERS];
    if (request_buffers(fd, buffers, NUM_BUFFERS) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (start_streaming(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    unsigned char *jpeg_data = NULL;
    int ret = -1;

    while (!g_stop) {
        struct v4l2_buffer buf;
        if (dequeue_frame(fd, &buf) == -1) {
            if (g_stop) {
                break;
            }
            fprintf(stderr, "Error dequeuing frame\n");
            goto cleanup;
        }

        if (buf.index >= NUM_BUFFERS) {
            fprintf(stderr, "Invalid buffer index\n");
            goto cleanup;
        }

        jpeg_data = (unsigned char *)mmap(NULL, buf.bytesused, PROT_READ, MAP_SHARED, fd, buf.m.offset);
        if (jpeg_data == MAP_FAILED) {
            perror("mmap");
            goto cleanup;
        }

        if (buf.bytesused > 0) {
            if (write_raw_jpeg(jpeg_data, buf.bytesused, OUTPUT_FILE) == -1) {
                fprintf(stderr, "Error writing image to file\n");
                goto cleanup;
            }
        }

        munmap(jpeg_data, buf.bytesused);
        jpeg_data = NULL;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (stop_streaming(fd) == -1) {
        fprintf(stderr, "Warning: failed to stop streaming during cleanup\n");
    }
    if (jpeg_data != NULL) {
        munmap(jpeg_data, buf.bytesused);
    }
    if (close(fd) == -1) {
        perror("close");
    }
    return ret;
}

