#define SERVO_MIN_DUTY 50
#define SERVO_MAX_DUTY 100
#define SERVO_MID_DUTY 75
#define SERVO_RANGE   100
#define SERVO_MIN_POS 25
#define SERVO_MAX_POS 125

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Map a duty value (0–100) to a pulse width in microseconds.
 * Returns 0 on success, -1 on invalid input.
 */
static int duty_to_pulse_us(int duty)
{
    if (duty < 0)   duty = 0;
    if (duty > 100) duty = 100;
    return (int)((float)duty / 100.0f * (float)PWM_PERIOD_US);
}

/*
 * Set the given GPIO as a hardware PWM output.
 * Returns 0 on success, -1 on failure.
 */
static int set_pwm_output(unsigned gpio)
{
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%u) failed\n", gpio);
        return -1;
    }
    if (gpioSetPWMfrequency(gpio, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%u) failed\n", gpio);
        return -1;
    }
    if (gpioPWM(gpio, 0) < 0) {
        fprintf(stderr, "gpioPWM(%u, 0) failed\n", gpio);
        return -1;
    }
    return 0;
}

/*
 * Set the given GPIO to a software PWM output.
 * Returns 0 on success, -1 on failure.
 */
static int set_pwm_output_software(unsigned gpio)
{
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%u, PI_OUTPUT) failed\n", gpio);
        return -1;
    }
    if (gpioPWM(gpio, 0) < 0) {
        fprintf(stderr, "gpioPWM(%u, 0) failed\n", gpio);
        return -1;
    }
    return 0;
}

/*
 * Set the given GPIO to a software PWM output with the given duty.
 * Returns 0 on success, -1 on failure.
 */
static int set_pwm_output_software_duty(unsigned gpio, int duty)
{
    if (duty < 0)   duty = 0;
    if (duty > 100) duty = 100;

    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "gpioPWM(%u, %d) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

/*
 * Initialize a servo to the given position (0–100).
 * Returns 0 on success, -1 on failure.
 */
static int init_servo(unsigned gpio, int position)
{
    if (position < 0)   position = 0;
    if (position > 100) position = 100;

    if (set_pwm_output_software_duty(gpio, position) < 0)
        return -1;

    /* Allow the servo to settle at the new position. */
    gpioDelay(500000);  /* 0.5 s */
    return 0;
}

/*
 * Move the given axis by the given step (±5).
 * Returns 0 on success, -1 on failure.
 */
static int move_axis(unsigned gpio, int step)
{
    int duty = SERVO_MID_DUTY;
    if (step > 0)
        duty += step;
    else
        duty -= step;

    if (duty < SERVO_MIN_DUTY)   duty = SERVO_MIN_DUTY;
    if (duty > SERVO_MAX_DUTY)   duty = SERVO_MAX_DUTY;

    if (init_servo(gpio, duty) < 0)
        return -1;

    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIOs as outputs --- */
    if (set_pwm_output(PAN_GPIO) < 0 ||
        set_pwm_output(TILT_GPIO) < 0 ||
        set_pwm_output(TILT_UP_GPIO) < 0 ||
        set_pwm_output(TILT_DOWN_GPIO) < 0 ||
        set_pwm_output(PAN_LEFT_GPIO) < 0 ||
        set_pwm_output(PAN_RIGHT_GPIO) < 0) {
        fprintf(stderr, "Failed to configure GPIOs as outputs\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize servos to mid-position --- */
    if (init_servo(PAN_GPIO, SERVO_MID_DUTY) < 0 ||
        init_servo(TILT_GPIO, SERVO_MID_DUTY) < 0) {
        fprintf(stderr, "Failed to initialize servos\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt mount ready. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int pan_step = 0;
        int tilt_step = 0;
        int left_step  = 0;
        int right_step = 0;

        /* Pan servo: left/right buttons */
        if (gpioRead(PAN_LEFT_GPIO) == 0) {
            pan_step = -5;
        } else if (gpioRead(PAN_RIGHT_GPIO) == 0) {
            pan_step = 5;
        }

        /* Tilt servo: up/down buttons */
        if (gpioRead(TILT_UP_GPIO) == 0) {
            tilt_step = -5;
        } else if (gpioRead(TILT_DOWN_GPIO) == 0) {
            tilt_step = 5;
        }

        /* Clamp servo positions to [25, 125] */
        if (pan_step > 0)   pan_step = 125;
        else if (pan_step < -125) pan_step = -125;
        if (tilt_step > 0)  tilt_step = 125;
        else if (tilt_step < -125) tilt_step = -125;

        /* Move servos */
        if (move_axis(PAN_GPIO, pan_step) < 0) {
            fprintf(stderr, "Failed to move pan servo\n");
        }
        if (move_axis(TILT_GPIO, tilt_step) < 0) {
            fprintf(stderr, "Failed to move tilt servo\n");
        }

        /* Print current positions for debugging */
        printf("Pan: %d  Tilt: %d\n",
               (int)SERVO_MID_DUTY + pan_step,
               (int)SERVO_MID_DUTY + tilt_step);

        gpioDelay(50000);  /* 50 ms poll interval */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioPWM(PAN_GPIO, 0);
    gpioPWM(TILT_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

