#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define NUM_BUFFERS 1
#define JPEG_QUALITY 75
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT)
#define FRAME_TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int open_camera(int *fd) {
    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }
    return 0;
}

static int configure_camera(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    for (i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        if (buf.length < IMAGE_SIZE) {
            fprintf(stderr, "Buffer %d too small: %u bytes\n", i, buf.length);
            return -1;
        }
    }

    return 0;
}

static int capture_frame(int fd, unsigned char *buffer, size_t buffer_size) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = FRAME_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    memcpy(buffer, buf.data, buf.bytesused);
    return 0;
}

static int convert_to_rgb(unsigned char *yuyv_buffer, unsigned char *rgb_buffer, size_t buffer_size) {
    int i, j, k;
    for (i = 0; i < buffer_size; i += 4) {
        for (j = 0; j < IMAGE_HEIGHT; j++) {
            for (k = 0; k < IMAGE_WIDTH; k++) {
                int y = yuyv_buffer[i + 2 * j * 2];
                int u = yuyv_buffer[i + 1 + 2 * j * 2];
                int v = yuyv_buffer[i + 3 + 2 * j * 2];

                int r = (y + v) >> 2;
                int g = y - v;
                int b = y + u;

                rgb_buffer[i + 3 * j * 3 + k * 3 + 0] = (r * 299) >> 16;
                rgb_buffer[i + 3 * j * 3 + k * 3 + 1] = (g * 596) >> 16;
                rgb_buffer[i + 3 * j * 3 + k * 3 + 2] = (b * 255) >> 16;
            }
        }
    }
    return 0;
}

static int encode_jpeg(const unsigned char *rgb_buffer, int width, int height, const char *filename, int quality) {
    FILE *fp = NULL;
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    unsigned char *dest = NULL;
    size_t dest_size = 0;
    int row_stride = (width * 3) * height;

    fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_stdio_dest(&cinfo, fp);
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    dest = (unsigned char *)malloc(width * height * 3 / 8);
    if (dest == NULL) {
        fprintf(stderr, "Error allocating memory for JPEG: %s\n", strerror(errno));
        jpeg_destroy_compress(&cinfo);
        fclose(fp);
        return -1;
    }

    size_t row_bytes = width * 3;
    size_t total_size = width * height * 3 / 8;

    for (int row = 0; row < height; row++) {
        if (stop_flag) break;
        memcpy(dest + row * width * 3, rgb_buffer + row * width * 3, row_bytes);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    fclose(fp);

    if (dest != NULL) {
        dest_size = total_size;
    }

    free(dest);
    return 0;
}

int main(void) {
    int fd = -1;
    unsigned char *yuyv_buffer = NULL;
    unsigned char *rgb_buffer = NULL;
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;
    int ret = EXIT_FAILURE;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (open_camera(&fd) != 0) {
        goto cleanup;
    }

    if (configure_camera(fd) != 0) {
        goto cleanup;
    }

    yuyv_buffer = (unsigned char *)malloc(IMAGE_SIZE);
    rgb_buffer = (unsigned char *)malloc(IMAGE_SIZE);
    if (yuyv_buffer == NULL || rgb_buffer == NULL) {
        fprintf(stderr, "Error allocating memory for buffers\n");
        goto cleanup;
    }

    if (stop_flag) goto cleanup;

    printf("Capturing image...\n");

    while (!stop_flag) {
        if (capture_frame(fd, yuyv_buffer, IMAGE_SIZE) == 0) {
            printf("Frame captured successfully\n");
            break;
        }
        if (stop_flag) break;

        if (stop_flag) break;
    }

    if (stop_flag) break;

    if (convert_to_rgb(yuyv_buffer, rgb_buffer, IMAGE_SIZE) != 0) {
        fprintf(stderr, "Error converting YUYV to RGB\n");
        goto cleanup;
    }

    if (stop_flag) break;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    if (encode_jpeg(rgb_buffer, IMAGE_WIDTH, IMAGE_HEIGHT, filename, JPEG_QUALITY) != 0) {
        fprintf(stderr, "Error encoding JPEG\n");
        goto cleanup;
    }

    printf("Image saved as %s\n", filename);
    ret = EXIT_SUCCESS;

cleanup:
    if (yuyv_buffer != NULL) free(yuyv_buffer);
    if (rgb_buffer != NULL) free(rgb_buffer);
    if (fd >= 0) close(fd);
    return ret;
}

