#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <jansson.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 2000
#define POLL_INTERVAL_US 100000
#define IMAGE_QUALITY 85
#define MAX_FILENAME_LENGTH 256
#define MAX_PAYLOAD_LENGTH 1024
#define MAX_PATH_LENGTH 512

static volatile sig_atomic_t g_running = 1;
static int g_http_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "raspistack capture --quality %d --filename %s --timeout 1000 --nopreview",
             IMAGE_QUALITY, filename);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspistack capture: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspistack capture exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "raspistack capture killed by signal %d\n", WTERMSIG(status));
        return -1;
    }
    return 0;
}

static int upload_file(const char *filename, const char *payload) {
    char command[512];
    snprintf(command, sizeof(command),
             "curl -X POST -F 'file=@%s' -F 'payload=%s' http://%s:%s/upload",
             filename, payload,
             (const char *)strchr(argv[1], ':') + 1,
             argv[2]);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing curl: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "curl exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "curl killed by signal %d\n", WTERMSIG(status));
        return -1;
    }
    return 0;
}

static int format_json(const char *filename, int motion, int gpio, json_t *root) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    json_t *file_obj = json_object();
    if (!json_object_set_new(file_obj, "filename", json_string(filename))) {
        fprintf(stderr, "Error setting filename in JSON\n");
        return -1;
    }
    json_t *timestamp_obj = json_object();
    if (!json_object_set_new(timestamp_obj, "timestamp", json_string(timestamp))) {
        fprintf(stderr, "Error setting timestamp in JSON\n");
        json_decref(file_obj);
        return -1;
    }
    json_t *motion_obj = json_object();
    if (!json_object_set_new(motion_obj, "motion", json_int(motion))) {
        fprintf(stderr, "Error setting motion in JSON\n");
        json_decref(file_obj);
        json_decref(timestamp_obj);
        return -1;
    }
    json_t *gpio_obj = json_object();
    if (!json_object_set_new(gpio_obj, "gpio", json_int(gpio))) {
        fprintf(stderr, "Error setting GPIO in JSON\n");
        json_decref(file_obj);
        json_decref(timestamp_obj);
        json_decref(motion_obj);
        return -1;
    }
    json_t *payload_obj = json_object();
    if (!json_object_set_new(payload_obj, "payload", json_string(filename))) {
        fprintf(stderr, "Error setting payload in JSON\n");
        json_decref(file_obj);
        json_decref(timestamp_obj);
        json_decref(motion_obj);
        json_decref(gpio_obj);
        return -1;
    }
    json_t *root_obj = json_object();
    if (!json_object_set_new(root_obj, "root", payload_obj)) {
        fprintf(stderr, "Error setting root in JSON\n");
        json_decref(file_obj);
        json_decref(timestamp_obj);
        json_decref(motion_obj);
        json_decref(gpio_obj);
        json_decref(payload_obj);
        return -1;
    }
    return json_dumps(root_obj, JSON_INDENT(4));
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <IP> <port> <pigpio_init_timeout_ms>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *ip = argv[1];
    const char *port = argv[2];
    int pigpio_init_ms = atoi(argv[3]);

    if (pigpio_init_ms <= 0) {
        fprintf(stderr, "Invalid pigpio initialization timeout. Using default 1000 ms.\n");
        pigpio_init_ms = 1000;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise(pigpio_init_ms) < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_http_initialized = 1;

    if (ensure_directory("motion_captures") != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    json_t *root = json_object();
    if (!root) {
        fprintf(stderr, "Failed to allocate JSON object\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (g_running) {
        int motion = 0;
        if (gpioRead(PIR_GPIO) == 1) {
            motion = 1;
            gpioDelay(DEBOUNCE_MS * 1000);
            if (gpioRead(PIR_GPIO) == 1) {
                motion = 1;
            }
        }

        if (motion) {
            time_t now = time(NULL);
            struct tm tm_info;
            char timestamp[32];
            localtime_r(&now, &tm_info);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

            char filename[MAX_FILENAME_LENGTH];
            snprintf(filename, sizeof(filename), "motion_captures/%s.jpg", timestamp);

            if (capture_image(filename) == 0) {
                char payload[MAX_PAYLOAD_LENGTH];
                if (format_json(filename, motion, PIR_GPIO, root) == 0) {
                    if (upload_file(filename, payload) == 0) {
                        printf("Motion detected on GPIO %d, captured %s, uploaded %s\n",
                               PIR_GPIO, filename, payload);
                    } else {
                        fprintf(stderr, "Error uploading file: %s\n", payload);
                    }
                } else {
                    fprintf(stderr, "Error formatting JSON\n");
                }
            } else {
                fprintf(stderr, "Error capturing image\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    if (g_http_initialized) {
        json_decref(root);
        g_http_initialized = 0;
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

