#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define WIDTH  1920
#define HEIGHT 1280
#define CHANNELS 3
#define BYTES_PER_PIXEL 4
#define FRAME_SIZE (WIDTH * HEIGHT * CHANNELS * BYTES_PER_PIXEL)
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define FILENAME "cropped.yuv"
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo) {
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int yuv_to_rgb(const unsigned char *yuyv, unsigned char *rgb, int width, int height, int channels) {
    for (int i = 0; i < width * height * channels; i += 4) {
        int y = yuyv[i];
        int u = yuyv[i + 1];
        int v = yuyv[i + 2];
        int r = yuyv[i + 3];
        int g = yuyv[i + 4];
        int b = yuyv[i + 5];
        rgb[i] = (unsigned char)(0x00 + (r - (u + v)) * 0x80);
        rgb[i + 1] = (unsigned char)(0x00 + (g - (u + v)) * 0x80);
        rgb[i + 2] = (unsigned char)(0x00 + (b - (u + v)) * 0x80);
        rgb[i + 3] = y;
    }
    return 0;
}

static int crop_yuv(const unsigned char *yuyv, unsigned char *rgb, int width, int height, int crop_width, int crop_height) {
    if (crop_width > width || crop_height > height) {
        fprintf(stderr, "Error: crop dimensions %dx%d exceed image %dx%d\n", crop_width, crop_height, width, height);
        return -1;
    }
    if (crop_width == 0 || crop_height == 0) {
        fprintf(stderr, "Error: crop dimensions must be positive\n");
        return -1;
    }
    if (crop_width < width || crop_height < height) {
        fprintf(stderr, "Error: crop dimensions must be >= image dimensions\n");
        return -1;
    }
    for (int i = 0; i < width * height * CHANNELS; i += 4) {
        int src_x = i / 4;
        int src_y = (i / 4) / width;
        int dst_x = src_x;
        int dst_y = src_y;
        if (dst_x < 0 || dst_x >= crop_width || dst_y < 0 || dst_y >= crop_height) {
            continue;
        }
        int src_y_end = (src_y / width) * width;
        int src_x_end = (src_x / crop_width) * crop_width;
        if (src_x_end >= width) src_x_end = width - 1;
        if (src_y_end >= height) src_y_end = height - 1;
        int src_y_start = src_y_end - (src_y_end < src_y);
        int src_x_start = src_x_end - (src_x_end < src_x);
        if (src_y_start < 0 || src_y_start >= src_y_end) src_y_start = src_y_end;
        if (src_x_start < 0 || src_x_start >= src_x_end) src_x_start = src_x_end;
        for (int c = 0; c < CHANNELS; c++) {
            rgb[i + c] = yuyv[src_y_start + c * 4];
        }
    }
    return 0;
}

static int write_yuv_to_file(const unsigned char *yuv, int width, int height, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    size_t written = fwrite(yuv, 1, FRAME_SIZE, fp);
    if (written != FRAME_SIZE) {
        fprintf(stderr, "Error: wrote %zu bytes, expected %d\n", written, FRAME_SIZE);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("open /dev/video0");
        return EXIT_FAILURE;
    }
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: device does not support streaming I/O\n");
        close(fd);
        return EXIT_FAILURE;
    }
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }
    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT) {
        fprintf(stderr, "Error: device did not accept requested format\n");
        close(fd);
        return EXIT_FAILURE;
    }
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        close(fd);
        return EXIT_FAILURE;
    }
    buf.length = FRAME_SIZE;
    buf.bytesconsumed = 0;
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        close(fd);
        return EXIT_FAILURE;
    }
    struct v4l2_buffer outbuf;
    memset(&outbuf, 0, sizeof(outbuf));
    outbuf.type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
    outbuf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_STREAMON, &outbuf) < 0) {
        perror("VIDIOC_STREAMON");
        close(fd);
        return EXIT_FAILURE;
    }
    unsigned char *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (!buffer) {
        perror("mmap");
        close(fd);
        return EXIT_FAILURE;
    }
    struct timeval tv;
    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;
    int ret = select(fd + 1, NULL, NULL, NULL, &tv);
    if (ret < 0) {
        perror("select");
        close(fd);
        munmap(buffer, buf.length);
        return EXIT_FAILURE;
    }
    if (ret == 0) {
        fprintf(stderr, "Error: select timeout\n");
        close(fd);
        munmap(buffer, buf.length);
        return EXIT_FAILURE;
    }
    if (g_stop) {
        fprintf(stderr, "Interrupted by signal\n");
        close(fd);
        munmap(buffer, buf.length);
        return EXIT_FAILURE;
    }
    if (ioctl(fd, VIDIOC_DQBUF, &outbuf) < 0) {
        perror("VIDIOC_DQBUF");
        close(fd);
        munmap(buffer, buf.length);
        return EXIT_FAILURE;
    }
    if (crop_yuv(buffer, buffer, WIDTH, HEIGHT, CROP_WIDTH, CROP_HEIGHT) != 0) {
        fprintf(stderr, "Error: crop failed\n");
        close(fd);
        munmap(buffer, buf.length);
        return EXIT_FAILURE;
    }
    if (yuv_to_rgb(buffer, buffer, WIDTH, HEIGHT, CHANNELS) != 0) {
        fprintf(stderr, "Error: yuv_to_rgb failed\n");
        close(fd);
        munmap(buffer, buf.length);
        return EXIT_FAILURE;
    }
    if (write_yuv_to_file(buffer, WIDTH, HEIGHT, FILENAME) != 0) {
        fprintf(stderr, "Error: write_yuv_to_file failed\n");
        close(fd);
        munmap(buffer, buf.length);
        return EXIT_FAILURE;
    }
    close(fd);
    munmap(buffer, buf.length);
    printf("Captured and cropped YUYV frame, saved to %s\n", FILENAME);
    return EXIT_SUCCESS;
}

