/*
 * arrow_servo.c — Raspberry Pi 4 Model B
 *
 * Reads arrow keys and 'q' on stdin, drives two SG90 servos on the
 * hardware PWM bus (GPIO17 = pan, GPIO18 = tilt) at 50 Hz.
 *
 * Build:  gcc -O2 -Wall -Wextra -o arrow_servo arrow_servo.c -lpigpio -lrt
 * Run:    sudo ./arrow_servo
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  17
#define TILT_SERVO_PIN 18
#define PWM_FREQUENCY  50          /* Hz — typical for SG90 */
#define PWM_RANGE      255         /* duty-cycle resolution */
#define STEP_DEG       5
#define DELAY_MS       100         /* delay between commands */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_sigint_handler(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                        */
/* ------------------------------------------------------------------ */
static int set_servo_angle(int pin, int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;

    if (angle < 0) {
        fprintf(stderr, "Error: angle %d out of range (0-180)\n", angle);
        return -1;
    }

    int duty = (int)(((float)angle / 180.0f) * (float)PWM_RANGE);
    if (gpioServo(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioServo(pin=%d, duty=%d) failed\n",
                pin, duty);
        return -1;
    }
    return 0;
}

static int move_servo(int pin, int target_angle, int step_size)
{
    int current = gpioRead(pin);
    if (current < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed\n", pin);
        return -1;
    }

    if (current == target_angle) {
        return 0;
    }

    for (int i = 0; i < 10 && g_running; i++) {
        if (set_servo_angle(pin, target_angle) < 0)
            return -1;
        gpioDelay(DELAY_MS * 1000);
        current = gpioRead(pin);
        if (current < 0)
            return -1;
        if (current == target_angle)
            return 0;
    }

    fprintf(stderr, "Error: target angle %d reached after %d steps\n",
            target_angle, i + 1);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM on both servos and terminate the driver library. */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_sigint_handler() != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Start both servos at the neutral 90-degree position. */
    if (set_servo_angle(PAN_SERVO_PIN, 90) < 0 ||
        set_servo_angle(TILT_SERVO_PIN, 90) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Servo control ready.  Arrow keys + 'q' to exit.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            if (feof(stdin)) {
                fprintf(stderr, "Error: stdin closed unexpectedly\n");
                break;
            }
            continue;
        }

        switch (c) {
        case 'q':
            break;
        case '+':  case '-': case '*': case '/':
            /*
             * Pan servo:  arrow-up  ->  +5   ->  95
             * arrow-down -> -5   ->  85
             * arrow-star -> *5   -> 105
             * arrow-slash -> /5   -> 115
             */
            if (move_servo(PAN_SERVO_PIN, 95, STEP_DEG) < 0)
                break;
            break;
        case '=':  case '-': case '*': case '/':
            if (move_servo(TILT_SERVO_PIN, 95, STEP_DEG) < 0)
                break;
            break;
        case '+': case '-': case '*': case '/':
            if (move_servo(PAN_SERVO_PIN, 85, STEP_DEG) < 0)
                break;
            break;
        case '=': case '-': case '*': case '/':
            if (move_servo(TILT_SERVO_PIN, 85, STEP_DEG) < 0)
                break;
            break;
        case '+': case '-': case '*': case '/':
            if (move_servo(PAN_SERVO_PIN, 75, STEP_DEG) < 0)
                break;
            break;
        case '=': case '-': case '*': case '/':
            if (move_servo(TILT_SERVO_PIN, 75, STEP_DEG) < 0)
                break;
            break;
        case '+': case '-': case '*': case '/':
            if (move_servo(PAN_SERVO_PIN, 65, STEP_DEG) < 0)
                break;
            break;
        case '=': case '-': case '*': case '/':
            if (move_servo(TILT_SERVO_PIN, 65, STEP_DEG) < 0)
                break;
            break;
        case '+': case '-': case '*': case '/':
            if (move_servo(PAN_SERVO_PIN, 55, STEP_DEG) < 0)
                break;
            break;
        case '=': case '-': case '*': case '/':
            if (move_servo(TILT_SERVO_PIN, 55, STEP_DEG) < 0)
                break;
            break;
        case '+': case '-': case '*': case '/':
            if (move_servo(PAN_SERVO_PIN, 45, STEP_DEG) < 0)
                break;
            break;
        case '=': case '-': case '*': case '/':
            if (move_servo(TILT_SERVO_PIN, 45, STEP_DEG) < 0)
                break;
            break;
        case '+': case '-': case '*': case '/':
            if (move_servo(PAN_SERVO_PIN, 35, STEP_DEG) < 0)
                break;
            break;
        case '=': case '-': case '*': case '/':
            if (move_servo(TILT_SERVO_PIN, 35, STEP_DEG) < 0)
                break;
            break;
        case '+': case '-': case '*': case '/':
            if (move_servo(PAN_SERVO_PIN, 25, STEP_DEG) < 0)
                break;
            break;
        case '=': case '-': case '*': case '/':
            if (move_servo(TILT_SERVO_PIN, 25, STEP_DEG) < 0)
                break;
            break;
        case '+': case '-': case '*': case '/':
            if (move_servo(PAN_SERVO_PIN, 15, STEP_DEG) < 0)
                break;
            break;
        case '=': case '-': case '*': case '/':
            if (move_servo(TILT_SERVO_PIN, 15, STEP_DEG) < 0)
                break;
            break;
        case '+': case '-': case '*': case '/':
            if (move_servo(PAN_SERVO_PIN, 5, STEP_DEG) < 0)
                break;
            break;
        case '=': case '-': case '*': case '/':
            if (move_servo(TILT_SERVO_PIN, 5, STEP_DEG) < 0)
                break;
            break;
        case '+': case '-': case '*': case '/':
            if (move_servo(PAN_SERVO_PIN, 0, STEP_DEG) < 0)
                break;
            break;
        case '=': case '-': case '*': case '/':
            if (move_servo(TILT_SERVO_PIN, 0, STEP_DEG) < 0)
                break;
            break;
        default:
            fprintf(stderr, "Error: invalid key '%c'\n", c);
            break;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

