static int read_cpu_usage(float *cpu_usage) {
    FILE *fp = fopen(CPU_USAGE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_USAGE_FILE, strerror(errno));
        return -1.0f;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", CPU_USAGE_FILE, strerror(errno));
        fclose(fp);
        return -1.0f;
    }
    fclose(fp);

    char *p = strstr(line, "cpu");
    if (!p) {
        fprintf(stderr, "CPU usage not found in %s\n", CPU_USAGE_FILE);
        return -1.0f;
    }

    char *endptr;
    long user = strtol(p + 1, &endptr, 10);
    if (*endptr != '\0' || endptr == p + 1) {
        fprintf(stderr, "Invalid CPU usage format\n");
        return -1.0f;
    }

    *cpu_usage = (float)user / 1000.0f;
    return 0.0f;
}

static int read_cpu_temperature(float *temp) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1.0f;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", TEMP_FILE, strerror(errno));
        fclose(fp);
        return -1.0f;
    }
    fclose(fp);

    char *p = strstr(line, "temp");
    if (!p) {
        fprintf(stderr, "Temperature not found in %s\n", TEMP_FILE);
        return -1.0f;
    }

    char *endptr;
    long temp_raw = strtol(p + 1, &endptr, 10);
    if (*endptr != '\0' || endptr == p + 1) {
        fprintf(stderr, "Invalid temperature format\n");
        return -1.0f;
    }

    *temp = (float)temp_raw / 1000.0f;
    return 0.0f;
}

