    if (gpioWrite(g_i2c_fd, enable) < 0) {
        log_err("gpioWrite(I2C enable) failed");
        return;
    }
    if (gpioWrite(g_i2c_fd, 0) < 0) {
        log_err("gpioWrite(I2C low) failed");
        return;
    }
}

