/*
 * Raspberry Pi 4 Model B – Anemometer + Wind Vane + LCD
 *
 * Anemometer:  pulse on GPIO17 (BCM), interrupt on rising edge
 * Wind Vane:  MCP3008 ADC on SPI0/CE0, channel 0, 1 MHz, mode 0
 * LCD:      16x2 via PCF8574 on I2C bus 1, 500 ms update
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o anemometer anemometer.c -lpigpio -lrt -lm
 *
 * Run:
 *   sudo ./anemometer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define ANEMOMETER_GPIO      17
#define SPI_DEVICE           "/dev/spidev0.0"
#define I2C_DEVICE           "/dev/i2c-1"

#define SPI_SPEED_HZ         1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD    8
#define SPI_MODE             0

#define I2C_BUS              1
#define LCD_WIDTH            16
#define LCD_CHR              1
#define LCD_CMD              0
#define LCD_BACKLIGHT        1
#define LCD_ENABLE           0x04
#define LCD_RS               0x01
#define LCD_RW               0x02
#define LCD_BL               0x08

#define SAMPLE_WINDOW_MS     500
#define POLL_DELAY_US        10000   /* 10 ms */
#define LOOP_DELAY_US        500000  /* 500 ms */

/* MCP3008 single-ended channel 0 */
#define MCP3008_CHANNEL      0

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_i2c_fd = -1;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static void log_msg(const char *msg);
static void log_err(const char *msg);
static void log_warn(const char *msg);
static int  spi_open(void);
static void spi_close(void);
static int  i2c_open(void);
static void i2c_close(void);
static int  read_mcp3008(int channel);
static void lcd_write_byte(uint8_t val);
static void lcd_send_nibble(uint8_t nibble);
static void lcd_send_command(uint8_t cmd);
static void lcd_send_data(uint8_t data);
static void lcd_init(void);
static void lcd_clear(void);
static void lcd_set_cursor(int row, int col);
static void lcd_print(const char *str);
static void lcd_update(void);
static void update_lcd(float wind_speed, int wind_direction);
static void anemometer_callback(int gpio, int level, uint32_t tick, void *userdata);
static void anemometer_init(void);
static void anemometer_read_pulse_count(int *count);
static void anemometer_stop(void);

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_err("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_err("sigaction(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        log_err("gpioInitialise() failed");
        return EXIT_FAILURE;
    }

    /* --- SPI init (bit-bang via /dev/spidev) --- */
    g_spi_fd = spi_open();
    if (g_spi_fd < 0) {
        log_err("spi_open() failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- I2C init (bit-bang via /dev/i2c) --- */
    g_i2c_fd = i2c_open();
    if (g_i2c_fd < 0) {
        log_err("i2c_open() failed");
        spi_close();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Anemometer init --- */
    anemometer_init();

    /* --- Anemometer callback (rising edge) --- */
    if (gpioSetAlertFuncEx(ANEMOMETER_GPIO, anemometer_callback, NULL) != 0) {
        log_err("gpioSetAlertFuncEx(ANEMOMETER_GPIO) failed");
        spi_close();
        i2c_close();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_msg("Anemometer monitoring started (GPIO17, SPI0 CE0, 1 MHz, mode 0)");
    log_msg("Wind vane: MCP3008 channel 0 on SPI0 CE0, 1 MHz, mode 0");
    log_msg("LCD: 16x2 via PCF8574 on I2C bus 1, 500 ms update");

    /* --- Main loop --- */
    while (g_running) {
        int pulse_count = 0;
        anemometer_read_pulse_count(&pulse_count);

        /* --- Wind direction --- */
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            log_err("MCP3008 read failed (sensor absent or bus error)");
            /* Continue running; next iteration will retry */
        } else if (adc_value == 0 || adc_value == 1023) {
            log_warn("ADC reading at rail – sensor absent or wiring fault");
        } else {
            /* Convert 10-bit ADC to wind direction (0–359 degrees) */
            int direction = (int)(((float)adc_value / 1023.0f) * 360.0f);
            if (direction < 0)   direction += 360;
            if (direction >= 360) direction -= 360;
            update_lcd(0.0f, (int)direction);
        }

        /* --- Wind speed --- */
        float wind_speed = 0.0f;
        if (pulse_count > 0) {
            float time_window_s = SAMPLE_WINDOW_MS / 1000.0f;
            float pulses_per_s = (float)pulse_count / time_window_s;
            wind_speed = (pulses_per_s > 0.0f) ? (pulses_per_s * 60.0f) : 0.0f;
        }

        /* --- LCD update --- */
        update_lcd(wind_speed, (int)adc_value);

        /* --- Sleep (interruptible) --- */
        if (g_running) {
            gpioDelay(LOOP_DELAY_US);
        }
    }

    /* --- Graceful shutdown --- */
    log_msg("Shutting down...");
    anemometer_stop();
    spi_close();
    i2c_close();
    gpioTerminate();
    return EXIT_SUCCESS;
}

/* ----------------------------- Helpers ------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_msg(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    fprintf(stderr, "[%s] %s\n", ts, msg);
}

static void log_err(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    fprintf(stderr, "[%s] ERROR: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

static void log_warn(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    fprintf(stderr, "[%s] WARN: %s\n", ts, msg);
}

/* ----------------------------- SPI helpers -------------------------------- */

static int spi_open(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        log_err("open(SPI_DEVICE) failed");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        log_err("ioctl(SPI_IOC_WR_MODE) failed");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        log_err("ioctl(SPI_IOC_WR_BITS_PER_WORD) failed");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        log_err("ioctl(SPI_IOC_WR_MAX_SPEED_HZ) failed");
        close(fd);
        return -1;
    }

    return fd;
}

static void spi_close(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ----------------------------- I2C helpers -------------------------------- */

static int i2c_open(void)
{
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        log_err("open(I2C_DEVICE) failed");
        return -1;
    }
    return fd;
}

static void i2c_close(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ----------------------------- MCP3008 read -------------------------------- */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (don't care)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        log_err("Invalid MCP3008 channel");
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        log_err("ioctl(SPI_IOC_MESSAGE) failed");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ----------------------------- LCD helpers -------------------------------- */

static void lcd_write_byte(uint8_t val)
{
    lcd_send_nibble(val >> 4);
    lcd_send_nibble(val & 0x0F);
}

static void lcd_send_command(uint8_t cmd)
{
    lcd_write_byte(cmd);
    gpioDelay(2000); /* 2 ms */
}

static void lcd_send_data(uint8_t data)
{
    lcd_send_nibble(data >> 4);
    lcd_send_nibble(data & 0x0F);
}

static void lcd_send_nibble(uint8_t nibble)
{
    uint8_t hi = nibble | LCD_BACKLIGHT;
    uint8_t lo = nibble | LCD_BL;
    uint8_t enable = LCD_ENABLE;

    if (gpioWrite(ANEMOMETER_GPIO, hi) < 0) {
        log_err("gpioWrite(high) failed");
        return;
    }
    if (gpioWrite(ANEMOMETER_GPIO, lo) < 0) {
        log_err("gpioWrite(low) failed");
        return;
    }
    if (gpioWrite(g_i2c_fd, enable) < 0) {
        log_err("gpioWrite(I2C enable) failed");
        return;
    }
    if (gpioWrite(g_i2c_fd, 0) < 0) {
        log_err("gpioWrite(I2C low) failed");
        return;
    }
}

static void lcd_send_command(uint8_t cmd)
{
    lcd_send_nibble(cmd >> 4);
    lcd_send_nibble(cmd & 0x0F);
}

static void lcd_send_data(uint8_t data)
{
    lcd_send_nibble(data >> 4);
    lcd_send_nibble(data & 0x0F);
}

