#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

/* Common-anode LED matrix: row anodes -> GPIO 17, 18, 27, 22, 23, 24, 25, 4 */
static const int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
/* Column cathodes -> GPIO 5, 6, 12, 13, 19, 16, 26, 20 */
static const int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(int pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int safe_set_output(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int safe_set_input(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int safe_write(int pin, int level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        safe_set_output(row_pins[i]);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        safe_set_output(col_pins[i]);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        if (safe_set_output(row_pins[i]) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (safe_set_output(col_pins[i]) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    /* Initialize all row pins LOW (common anode off) */
    for (int i = 0; i < NUM_ROWS; i++) {
        if (safe_write(row_pins[i], 0) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }
    /* Initialize all column pins HIGH (cathode off) */
    for (int i = 0; i < NUM_COLS; i++) {
        if (safe_write(col_pins[i], 1) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Wave animation: left-to-right */
    int wave_x = 0;
    int wave_y = 0;
    int wave_dir = 1;

    while (running) {
        for (int i = 0; i < NUM_ROWS; i++) {
            if (safe_write(row_pins[i], wave_dir) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            if (safe_write(col_pins[wave_x], 0) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            if (safe_write(col_pins[wave_x + 1], 1) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
        }
        wave_x = (wave_x + wave_dir + NUM_COLS) % NUM_COLS;
        if (wave_dir == 1) {
            wave_y = (wave_y + 1) % NUM_ROWS;
        } else {
            wave_y = (wave_y - 1 + NUM_ROWS) % NUM_ROWS;
        }
        usleep(SCAN_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

