static int clear_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (safe_write(row_pins[i], 1) != 0) return -1;
        if (safe_write(col_pins[i], 1) != 0) return -1;
    }
    return 0;
}

static int draw_line(int x, int y, int length, int direction) {
    if (length < 0) length = -length;
    if (direction == 0) {
        for (int i = 0; i < length; i++) {
            if (safe_write(col_pins[x], 0) != 0) return -1;
            if (safe_write(row_pins[y], 1) != 0) return -1;
        }
    } else {
        for (int i = 0; i < length; i++) {
            if (safe_write(col_pins[x], 1) != 0) return -1;
            if (safe_write(row_pins[y], 0) != 0) return -1;
        }
    }
    return 0;
}

static int draw_square(int x, int y, int size) {
    if (size > NUM_COLS) size = NUM_COLS;
    for (int i = 0; i < size; i++) {
        if (draw_line(x + i, y, 1, 0) != 0) return -1;
    }
    for (int i = 0; i < size; i++) {
        if (draw_line(x + i, y + size - 1 - i, 1, 1) != 0) return -1;
    }
    for (int i = 0; i < size; i++) {
        if (draw_line(x + size - 1 - i, y + size - 1 - i, 1, 0) != 0) return -1;
    }
    for (int i = 0; i < size; i++) {
        if (draw_line(x + size - 1 - i, y + i, 1, 1) != 0) return -1;
    }
    return 0;
}

static int draw_wave(void) {
    /* Wave pattern: rows alternate HIGH/LOW, columns sweep from left to right */
    for (int y = 0; y < NUM_ROWS; y++) {
        if (safe_write(row_pins[y], 1) != 0) return -1;
    }
    for (int x = 0; x < NUM_COLS; x++) {
        if (draw_line(x, 0, NUM_COLS, 0) != 0) return -1;
        if (draw_line(x, NUM_ROWS - 1, NUM_COLS, 1) != 0) return -1;
    }
    for (int y = 0; y < NUM_ROWS; y++) {
        if (safe_write(row_pins[y], 0) != 0) return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        if (safe_set_mode(row_pins[i], PI_OUTPUT) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (safe_set_mode(col_pins[i], PI_OUTPUT) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (safe_set_pull(col_pins[0], PI_PUD_UP) != 0) {
