    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (clear_matrix() != 0) break;
        if (draw_wave() != 0) break;
        gpioDelay(DELAY_MS * 1000);
    }

    /* Clean shutdown: turn off all LEDs */
    for (int i = 0; i < NUM_ROWS; i++) {
        safe_write(row_pins[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        safe_write(col_pins[i], 1);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

