/*
 * VL53L3CX multi-target distance reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L3CX SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   VL53L3CX SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   VL53L3CX VDD -> 3.3 V (pin 1)
 *   VL53L3CX GND -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -o vl53l3cx_reader vl53l3cx_reader.c
 * Run:    sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L3CX_ADDR  0x58          /* default SA0 = 0 */

/* VL53L3CX register addresses (16-bit, big-endian on the bus) */
#define REG_MODEL_ID          0x000
#define REG_SOFT_RESET        0x010
#define REG_SYSTEM_START      0x016
#define REG_SYSTEM_RANGE_START 0x018
#define REG_RESULT_RANGE_STATUS 0x086
#define REG_RESULT_DISTANCE_LSB 0x096
#define REG_RESULT_DISTANCE_MSB 0x097
#define REG_RESULT_TARGET_COUNT 0x084

#define MAX_TARGETS  16
#define POLL_MS      100

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *out)
{
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
