/*
 * Write an ISO-8601 UTC timestamp into buf (size >= 25).
 * Returns 0 on success, -1 on failure.
 */
static int get_iso8601_timestamp(char *buf, size_t size)
{
    time_t rawtime;
    struct tm utc;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (gmtime_r(&rawtime, &utc) == NULL)
        return -1;

    if (strftime(buf, size, "%Y-%m-%dT%H:%M:%SZ", &utc) == 0)
        return -1;

    return 0;
}

/*
 * Append a detection entry to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_detection(const char *timestamp)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s Object detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Blink the LED for LED_BLINK_US microseconds.
 * Returns 0 on success, -1 on failure.
 */
static int blink_led(void)
{
    if (gpioWrite(LED_PIN, 1) < 0) {
        fprintf(stderr, "Error setting LED pin HIGH: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(LED_BLINK_US);
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error setting LED pin LOW: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pin as input */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting sensor pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing LED pin state: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    int prev_state = gpioRead(SENSOR_PIN);
    if (prev_state < 0) {
        fprintf(stderr, "Error reading initial sensor state: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error reading sensor pin: %s\n", strerror(errno));
            break;
        }

        /* Detect falling edge: HIGH -> LOW */
        if (prev_state == 1 && current_state == 0) {
            char timestamp[32];
            if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) == 0) {
                if (log_detection(timestamp) == 0) {
                    printf("Detection logged: %s\n", timestamp);
                } else {
                    fprintf(stderr, "Failed to log detection.\n");
                }
                blink_led();
            } else {
                fprintf(stderr, "Failed to generate timestamp.\n");
            }
        }

        prev_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean up */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

