#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define APDS9960_ADDR 0x5C
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define POLL_INTERVAL_US 100000

/* APDS9960 register addresses */
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x01
#define APDS9960_CONTROL 0x0F
#define APDS9960_ID 0x12
#define APDS9960_STATUS 0x13
#define APDS9960_CDATA0 0x14
#define APDS9960_CDATA1 0x15
#define APDS9960_CDATA2 0x16
#define APDS9960_CDATA3 0x17
#define APDS9960_RDATA0 0x18
#define APDS9960_RDATA1 0x19
#define APDS9960_RDATA2 0x1A
#define APDS9960_RDATA3 0x1B
#define APDS9960_GDATA0 0x1C
#define APDS9960_GDATA1 0x1D
#define APDS9960_GDATA2 0x1E
#define APDS9960_GDATA3 0x1F
#define APDS9960_BDATA0 0x20
#define APDS9960_BDATA1 0x21
#define APDS9960_BDATA2 0x22
#define APDS9960_BDATA3 0x23

#define APDS9960_ENABLE_PON 0x01
#define APDS9960_ENABLE_AEN 0x02
#define APDS9960_ENABLE_AD_PS1 0x04
#define APDS9960_ENABLE_AD_PS2 0x08
#define APDS9960_ENABLE_AD_PS3 0x10
#define APDS9960_ENABLE_AD_PS4 0x20
#define APDS9960_ENABLE_AD_PS5 0x40
#define APDS9960_ENABLE_AD_PS6 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: reg=0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: reg=0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) {
        fprintf(stderr, "I2C read failed: reg=0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int apds9960_init(void) {
    uint8_t id;
    if (i2c_read_reg(APDS9960_ID, &id) != 0) {
        fprintf(stderr, "Cannot read APDS9960 ID register\n");
        return -1;
    }
    if (id != 0x63) {
        fprintf(stderr, "Unexpected APDS9960 ID: 0x%02X (expected 0x63)\n", id);
        return -1;
    }

    if (i2c_write_reg(APDS9960_ENABLE, APDS9960_ENABLE_PON) != 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(APDS9960_ATIME, 0x07) != 0) return -1;
    if (i2c_write_reg(APDS9960_CONTROL, 0x00) != 0) return -1;
    if (i2c_write_reg(APDS9960_ENABLE, APDS9960_ENABLE_PON | APDS9960_ENABLE_AEN) != 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int apds9960_read_proximity(uint16_t *proximity) {
    uint8_t status;
    if (i2c_read_reg(APDS9960_STATUS, &status) != 0) return -1;
    if ((status & 0x03) != 0x03) {
        fprintf(stderr, "Proximity timeout: status=0x%02X\n", status);
        return -1;
    }

    uint8_t c0, c1, c2, c3, r0, r1, r2, r3, g0, g1, g2, g3, b0, b1, b2, b3;
    if (i2c_read_reg(APDS9960_CDATA0, &c0) != 0) return -1;
    if (i2c_read_reg(APDS9960_CDATA1, &c1) != 0) return -1;
    if (i2c_read_reg(APDS9960_CDATA2, &c2) != 0) return -1;
    if (i2c_read_reg(APDS9960_CDATA3, &c3) != 0) return -1;
    if (i2c_read_reg(APDS9960_RDATA0, &r0) != 0) return -1;
    if (i2c_read_reg(APDS9960_RDATA1, &r1) != 0) return -1;
    if (i2c_read_reg(APDS9960_RDATA2, &r2) != 0) return -1;
    if (i2c_read_reg(APDS9960_RDATA3, &r3) != 0) return -1;
    if (i2c_read_reg(APDS9960_GDATA0, &g0) != 0) return -1;
    if (i2c_read_reg(APDS9960_GDATA1, &g1) != 0) return -1;
    if (i2c_read_reg(APDS9960_GDATA2, &g2) != 0) return -1;
    if (i2c_read_reg(APDS9960_GDATA3, &g3) != 0) return -1;
    if (i2c_read_reg(APDS9960_BDATA0, &b0) != 0) return -1;
    if (i2c_read_reg(APDS9960_BDATA1, &b1) != 0) return -1;
    if (i2c_read_reg(APDS9960_BDATA2, &b2) != 0) return -1;
    if (i2c_read_reg(APDS9960_BDATA3, &b3) != 0) return -1;

    *proximity = ((uint16_t)r3 << 12) | ((uint16_t)r2 << 8) | (uint16_t)r1;
    *proximity &= 0xFFFC;

    *proximity = ((uint16_t)g3 << 12) | ((uint16_t)g2 << 8) | (uint16_t)g1;
    *proximity &= 0xFFFC;

    *proximity = ((uint16_t)g0 << 12) | ((uint16_t)g1 << 8) | (uint16_t)g2;
    *proximity &= 0xFFFC;

    *proximity = ((uint16_t)b3 << 12) | ((uint16_t)b2 << 8) | (uint16_t)b1;
    *proximity &= 0xFFFC;

    return 0;
}

static void log_data(uint16_t r, uint16_t g, uint16_t b, uint16_t p) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, r, g, b, p);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2c_write_reg(APDS9960_ENABLE, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, APDS9960_ADDR);
        gpioTerminate();
        return 1;
    }

    if (apds9960_init() != 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
        fflush(log_file);
    }

    printf("APDS9960 proximity logger started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t proximity;
        if (apds9960_read_proximity(&proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data((uint16_t)r, (uint16_t)g, (uint16_t)b, proximity);
            }
        } else {
            fprintf(stderr, "Failed to read proximity. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus. Exiting.\n");
                break;
            }
            if (apds9960_init() != 0) {
                fprintf(stderr, "APDS9960 re-initialisation failed. Exiting.\n");
                break;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

