/*
 * VL53L0X Time-of-Flight distance logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L0X SDA -> GPIO 2 (I2C1 SDA)
 *   VL53L0X SCL -> GPIO 3 (I2C1 SCL)
 *   VL53L0X VDD -> 3.3 V
 *   VL53L0X GND -> GND
 *   VL53L0X AUX_CLK -> GPIO 11 (I2C1 SCL)
 *   VL53L0X AUX_SDI -> GPIO 9  (I2C1 SDA)
 *   VL53L0X AUX_SCL -> GPIO 10 (I2C1 SCLK)
 *   VL53L0X AUX_VDD -> 3.3 V
 *   VL53L0X AUX_GND -> GND
 *   VL53L0X TRIG -> GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o vl53l0x_logger vl53l0x_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L0X_ADDR   0x60
#define TRIGGER_PIN    17

/* VL53L0X register addresses */
#define REG_SOFT_RESET          0x0003
#define REG_SYSTEM_MODE_START  0x0000
#define REG_RESULT_INTERRUPT_STATUS 0x0014
#define REG_RESULT_RANGE_STATUS 0x0016
#define REG_RESULT_DISTANCE     0x0096

#define EXPECTED_VL53L0X_ID     0xEA
#define EXPECTED_SOFT_RESET_VAL 0x00
#define EXPECTED_SYSTEM_MODE_START_VAL 0x01

#define LOG_FILE "distance_log.txt"
#define POLL_TIMEOUT_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register (big-endian on the wire) */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t val)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (val >> 8) & 0xFF;
    buf[3] = val & 0xFF;
    if (write(fd, buf, 4) != 4) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register (big-endian on the wire) */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t reg_buf[2];
    uint8_t data[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* Trigger a single measurement and wait for completion */
static int trigger_and_wait(int fd)
{
    /* Start a single measurement */
    if (i2c_write_reg16(fd, REG_SYSTEM_MODE_START, EXPECTED_SYSTEM_MODE_START_VAL) < 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS for completion (bit 0 = new data ready) */
    uint16_t status = 0;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_reg16(fd, REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        usleep(1000);
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for VL53L0X measurement completion\n");
        return -1;
    }

    /* Read the distance result */
    uint16_t distance = 0;
    if (i2c_read_reg16(fd, REG_RESULT_DISTANCE, &distance) < 0)
        return -1;

    /* Clear the interrupt by writing the mode start value again */
    if (i2c_write_reg16(fd, REG_SYSTEM_MODE_START, EXPECTED_SYSTEM_MODE_START_VAL) < 0)
        return -1;

    return distance;
}

static int log_distance(FILE *fp, int distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L0X_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    uint16_t id = 0;
    if (i2c_read_reg16(g_i2c_fd, REG_SOFT_RESET, &id) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X (device absent or bus error)\n", VL53L0X_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (id != EXPECTED_VL53L0X_ID) {
        fprintf(stderr, "Unexpected VL53L0X ID: 0x%02X (expected 0x%02X)\n", id, EXPECTED_VL53L0X_ID);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, pull-up, and drive low */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", TRIGGER_PIN, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);
    gpioWrite(TRIGGER_PIN, 0);
    usleep(10000); /* 10 ms settle */

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("VL53L0X distance logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int distance = trigger_and_wait(g_i2c_fd);
        if (distance >= 0) {
            if (log_distance(g_log_fp, distance) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Measurement failed; continuing.\n");
        }
        usleep(500000); /* 500 ms between measurements */
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
    }
    if (g_i2c_fd >= 0) {
        i2c_write_reg16(g_i2c_fd, REG_SYSTEM_MODE_START, 0x00);
        close(g_i2c_fd);
    }
    return EXIT_SUCCESS;
}

