    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L0X_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    uint16_t id = 0;
    if (i2c_read_reg16(g_i2c_fd, REG_SOFT_RESET, &id) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X (device absent or bus error)\n", VL53L0X_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (id != EXPECTED_VL53L0X_ID) {
        fprintf(stderr, "Unexpected VL53L0X ID: 0x%02X (expected 0x%02X)\n", id, EXPECTED_VL53L0X_ID);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, pull-up, and drive low */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", TRIGGER_PIN, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);
    gpioWrite(TRIGGER_PIN, 0);
    usleep(10000); /* 10 ms settle */

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("VL53L0X distance logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int distance = trigger_and_wait(g_i2c_fd);
        if (distance >= 0) {
            if (log_distance(g_log_fp, distance) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Measurement failed; continuing.\n");
        }
        usleep(500000); /* 500 ms between measurements */
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
    }
    if (g_i2c_fd >= 0) {
        i2c_write_reg16(g_i2c_fd, REG_SYSTEM_MODE_START, 0x00);
        close(g_i2c_fd);
    }
    return EXIT_SUCCESS;
}

