#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define CH101_ADDR     0x49
#define TRIGGER_MS     50
#define SAMPLE_MS      200
#define LOG_FILE       "distance_log.txt"
#define MAX_TIMESTAMP  32

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Trigger the CH101 sensor and wait for the measurement to complete.
 * Returns 0 on success, -1 on I2C error.
 */
static int trigger_and_wait(int handle)
{
    if (i2cWriteByte(handle, 0x00) < 0) {
        fprintf(stderr, "Error: failed to trigger CH101 (write 0x00).\n");
        return -1;
    }

    /* Wait for the sensor to complete the measurement. */
    gpioDelay(TRIGGER_MS * 1000);

    /* Read the 16-bit result (big-endian). */
    char buf[2] = {0, 0};
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: failed to read CH101 result (got %d bytes).\n", n);
        return -1;
    }

    return 0;
}

/*
 * Read the distance from the CH101 sensor.
 * Returns distance in mm on success, -1 on I2C error.
 */
static int read_distance(int handle)
{
    if (trigger_and_wait(handle) < 0)
        return -1;

    /* Read the 16-bit result (big-endian). */
    char buf[2] = {0, 0};
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: failed to read CH101 result (got %d bytes).\n", n);
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

/*
 * Format the current time as "YYYY-MM-DD HH:MM:SS" into the given buffer.
 * Returns 0 on success, -1 on buffer overflow.
 */
static int format_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }
    return 0;
}

/*
 * Append a distance reading to the log file.
 * Returns 0 on success, -1 on file error.
 */
static int log_distance(FILE *fp, const char *timestamp, int distance)
{
    if (fprintf(fp, "%s, %d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void)
{
    int i2c_handle = -1;
    FILE *log_file = NULL;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus to the CH101. */
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d).\n", i2c_handle);
        goto cleanup_gpio;
    }

    /* Open the log file in append mode. */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        goto cleanup_i2c;
    }

    printf("Starting CH101 distance measurements on I2C bus %d, address 0x%02X.\n",
           I2C_BUS, CH101_ADDR);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        char timestamp[MAX_TIMESTAMP];

        if (format_timestamp(timestamp, sizeof(timestamp)) < 0) {
            /* Non-fatal: continue sampling. */
            gpioDelay(SAMPLE_MS * 1000);
            continue;
        }

        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            if (log_distance(log_file, timestamp, distance) < 0) {
                /* Non-fatal: continue sampling. */
            }
        } else {
            /* Non-fatal: skip this sample. */
        }

        gpioDelay(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);

cleanup_gpio:
    if (log_file != NULL)
        fclose(log_file);
    if (gpioInitialise() >= 0)
        gpioTerminate();

    return rc;
}

