#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int log_data(int sensor1_value, int sensor2_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_value, sensor2_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring sensors on GPIO %d and %d. Press Ctrl+C to exit.\n", SENSOR_1_PIN, SENSOR_2_PIN);

    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value >= 0 && sensor2_value >= 0) {
            if (log_data(sensor1_value, sensor2_value) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor values\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

