/*
 * Raspberry Pi Zero W - ICU-20201 Ultrasonic Distance Sensor
 *
 * Reads distance from an ICU-20201 ultrasonic Time-of-Flight sensor via I2C
 * (bus 1, address 0x28) and controls an LED on GPIO 17 based on a 20 cm
 * threshold.  Logs timestamped readings to distance_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o icu20201_dist icu20201_dist.c -lpigpio -lrt
 * Run:    sudo ./icu20201_dist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x28          /* ICU-20201 default I2C address */
#define GPIO_LED             17            /* BCM 17 - physical pin 11 */
#define DISTANCE_THRESHOLD   20.0f         /* cm */
#define SAMPLE_PERIOD_US     100000        /* 100 ms */
#define LOG_FILE             "distance_log.txt"
#define MAX_DISTANCE_CM      400.0f        /* ICU-20201 max range ~400 cm */

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_DEVICE_CONFIG    0x00
#define REG_DISTANCE_MSB    0x01
#define REG_DISTANCE_LSB    0x02

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static int  g_gpio_ready = 0;

/* --------------------------- Forward declarations ------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_distance(float *distance_cm);
static void control_led(float distance_cm);
static int  log_data(float distance_cm);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C ------------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }

    /*
     * Software reset (write 0x01 to REG_DEVICE_CONFIG).
     * The ICU-20201 auto-clocks the sensor and then returns a 0x0000
     * device configuration after the reset.
     */
    if (i2cWriteByteData(g_i2c_handle, REG_DEVICE_CONFIG, 0x01) < 0) {
        fprintf(stderr, "[ERROR] I2C write (reset) failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle after reset */

    /*
     * Read the device configuration register to confirm the sensor is
     * present and operating.  A value of 0x0000 indicates a valid,
     * unconfigured device.
     */
    int cfg = i2cReadByteData(g_i2c_handle, REG_DEVICE_CONFIG);
    if (cfg < 0) {
        fprintf(stderr, "[ERROR] I2C read (device config) failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    if (cfg != 0x0000) {
        fprintf(stderr, "[WARN] I2C device config readback = 0x%04X (expected 0x0000)\n", cfg);
    }

    return 0;
}

/* ------------------------------- GPIO ------------------------------------ */
static int init_gpio(void)
{
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_LED);
        return -1;
    }
    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed\n", GPIO_LED);
        return -1;
    }
    g_gpio_ready = 1;
    return 0;
}

/* ------------------------------- Distance --------------------------------- */
static int read_distance(float *distance_cm)
{
    if (g_i2c_handle < 0) {
        return -1;
    }

    /*
     * Read 2 bytes from REG_DISTANCE_MSB (0x01).
     * The ICU-20201 returns the distance in 16-bit big-endian format.
     */
    char buf[2];
    int n = i2cReadI2CBlockData(g_i2c_handle, REG_DISTANCE_MSB, buf, 2);
    if (n != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(distance) returned %d: %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *distance_cm = (float)raw / 10.0f;

    /* Sanity-check the result */
    if (*distance_cm < 0.0f || *distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "[WARN] Distance out of range: %.2f cm\n", *distance_cm);
        return -1;
    }

    return 0;
}

/* ------------------------------- LED -------------------------------------- */
static void control_led(float distance_cm)
{
    int level = (distance_cm < DISTANCE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(GPIO_LED, level) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed\n", GPIO_LED, level);
    }
}

/* ------------------------------- Logging ---------------------------------- */
static int log_data(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance_cm);
    fclose(fp);
    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_gpio_ready) {
        gpioWrite(GPIO_LED, 0);
        g_gpio_ready = 0;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }
    g_gpio_ready = 1;

    if (init_i2c() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance monitor started.  Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance_cm;

        if (read_distance(&distance_cm) == 0) {
