#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x54
#define CMD_FRAME_LEN  4
#define RESP_LEN       15
#define DIST_REG       11
#define DIST_MASK      0x0FFF
#define THRESHOLD_MM   1000
#define SAMPLE_DELAY_MS 100
#define CYCLE_DELAY_MS 100
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_resp(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    uint8_t cmd[CMD_FRAME_LEN] = {0x01, 0x02, 0x03, 0x04};
    uint8_t resp[RESP_LEN];

    if (i2c_write_cmd(fd, cmd, CMD_FRAME_LEN) < 0)
        return -1;

    usleep(10000);

    if (i2c_read_resp(fd, resp, RESP_LEN) < 0)
        return -1;

    if (resp[0] != 0x01) {
        fprintf(stderr, "Sensor not responding (header mismatch: 0x%02X)\n", resp[0]);
        return -1;
    }

    uint16_t raw = ((uint16_t)resp[1] << 8) | resp[2];
    *distance_mm = (raw & DIST_MASK) >> 2;
    return 0;
}

static void log_intrusion(int distance_mm) {
    FILE *fp = fopen("intrusion_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Intrusion detected! Distance: %d mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    } else {
        fprintf(fp, "Timestamp error - Intrusion detected! Distance: %d mm\n", distance_mm);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("I2C initialized on %s at address 0x%02X.\n", I2C_BUS, SENSOR_ADDR);

    while (g_running) {
        int sum = 0;
        int valid = 0;

        for (int i = 0; i < 10 && g_running; i++) {
            int distance;
            if (read_distance(fd, &distance) == 0) {
                sum += distance;
                valid++;
            } else {
                fprintf(stderr, "Read failed, retrying...\n");
            }
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        if (valid > 0) {
            int avg = sum / valid;
            if (avg < THRESHOLD_MM) {
                log_intrusion(avg);
                printf("Intrusion detected! Average distance: %d mm\n", avg);
            }
        } else {
            fprintf(stderr, "No valid readings in this cycle.\n");
        }
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return 0;
}

