#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L0X I2C address (7-bit) */
#define VL53L0X_ADDR 0x60

/* VL53L0X register addresses */
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L0X_REG_SYSTEM_MODE_START       0x0000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0014
#define VL53L0X_REG_RESULT_RANGE_STATUS     0x0016
#define VL53L0X_REG_RESULT_DISTANCE         0x0096

/* Expected model ID for VL53L0X */
#define VL53L0X_MODEL_ID 0xEA

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit register address followed by a 16-bit value */
static int vl53l0x_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register address */
static int vl53l0x_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* Initialize the VL53L0X sensor */
static int vl53l0x_init(int handle) {
    uint16_t model_id = 0;

    /* Read and verify the model ID */
    if (vl53l0x_read_reg16(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID register: %s\n", strerror(errno));
        return -1;
    }

    if (model_id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Error: Invalid model ID (0x%04X). Expected 0x%04X. "
                        "Sensor not present or wrong device.\n", model_id, VL53L0X_MODEL_ID);
        return -1;
    }

    /* Start continuous ranging mode */
    if (vl53l0x_write_reg16(handle, VL53L0X_REG_SYSTEM_MODE_START, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to start ranging mode: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

