/*
 * Si1182 Proximity Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2  (I2C1 SDA, pin 3)
 *   Si1182 SCL  -> GPIO3  (I2C1 SCL, pin 5)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * The Si1182 is a 16-bit I2C device, so a 16-bit read is expected.
 *
 * Build:  gcc -O2 -Wall -o si1182_prox si1182_prox.c -lpigpio -lrt
 * Run:    sudo ./si1182_prox
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1182 constants ---- */
#define I2C_BUS        1
#define SI1182_ADDR    0x5A          /* 0x5A is the default 7-bit address */

/*
 * Si1182 register map (16-bit addresses, big-endian on the bus).
 * The Si1182 is a 16-bit device, so a read of a 16-bit register returns
 * the two bytes in the order they were written.
 */
#define REG_PART_ID     0x00
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE   0x08
#define REG_PS_LED21    0x0F
#define REG_PS1_DATA0   0x10
#define REG_PS1_DATA1   0x11

#define EXPECTED_PART_ID 0x82

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a Si1182 register.
 *
 * Si1182 expects a 16-bit buffer: [reg_addr, data_hi, data_lo].
 * pigpio's i2cWriteDevice sends the data as [data_hi, data_lo], so we
 * swap the bytes before writing.
 */
static int si1182_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)reg;
    buf[1] = (uint8_t)(value >> 8);   /* Si1182 expects MSB first */
    buf[2] = (uint8_t)(value & 0xFF);

    if (i2cWriteDevice(handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: i2cWriteDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a Si1182 register.
 *
 * Send the register address, then read two bytes back.
 */
static int si1182_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "Error: i2cWriteDevice (reg select) failed for reg 0x%02X\n", reg);
        return -1;
    }

    uint8_t buf[2];
    if (i2cReadDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice failed for reg 0x%02X\n", reg);
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1182: verify part ID, write HW_KEY, set measurement
 * rate, and configure the PS1 LED current.
 */
static int si1182_init(int handle)
{
    uint16_t part_id = 0;

    /* Verify the sensor is present by reading the PART_ID register.
     * A NACK (0xFFFF) indicates the sensor is not responding at this
     * address. */
    if (si1182_read_reg16(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Si1182 not responding on I2C bus %d (addr 0x%02X).\n",
                I2C_BUS, SI1182_ADDR);
        return -1;
    }

    if (part_id == 0xFFFF) {
        fprintf(stderr, "Error: Si1182 not found (PART_ID=0xFFFF).\n");
        return -1;
    }

    if (si1182_write_reg16(handle, REG_HW_KEY, 0x17) != 0)
        return -1;

    /* Set measurement rate to 100 ms (0x0A). */
    if (si1182_write_reg16(handle, REG_MEAS_RATE, 0x0A) != 0)
        return -1;

    /* Configure PS1 LED current (LED1). */
    if (si1182_write_reg16(handle, REG_PS_LED21, 0x0F) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 16-bit proximity data from the Si1182.
 *
 * The Si1182 returns a 16-bit value in a single I2C transaction.
 * pigpio's i2cReadDevice sends the register address, then reads two
 * bytes back.  The Si1182 is a 16-bit device, so the two bytes
 * returned are the two data bytes in the order they were written.
 */
static int si1182_read_proximity(int handle, uint16_t *prox)
{
    uint8_t buf[2];

    if (i2cWriteDevice(handle, (char *)&REG_PS1_DATA0, 1) != 1) {
        fprintf(stderr, "Error: i2cWriteDevice (prox reg select) failed\n");
        return -1;
    }

    if (i2cReadDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice (prox data) failed\n");
        return -1;
    }

    *prox = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for clean shutdown on Ctrl+C. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the Si1182 sensor. */
    if (si1182_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: Si1182 initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity sensor reader started.\n");
    printf("Bus %d, address 0x%02X, logging every 500 ms.\n", I2C_BUS, SI1182_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop. */
    while (g_running) {
        uint16_t prox = 0;

        if (si1182_read_proximity(g_i2c_handle, &prox) == 0) {
            printf("Proximity: %u\n", prox);
        } else {
            fprintf(stderr, "Warning: failed to read proximity data.\n");
        }

        /* Sleep 500 ms (500,000 µs). */
        gpioDelay(500000);
    }

    /* Clean shutdown. */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

