 *
 * Wiring:
 *   MLX75030 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX75030 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX75030 VDD  -> 3.3 V
 *   MLX75030 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75030 mlx75030.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x75
#define SAMPLE_PERIOD_NS 500000000LL  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Open the I2C bus and set the slave address.
 * Returns a valid file descriptor on success, or -1 on error.
 */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Write a 16-bit big-endian value to a register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian value from a register.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "write(reg select 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "read(reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    int fd = i2c_open(I2C_BUS, MLX75030_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    /*
     * Probe: try a read of the device-specific register address.
     * If the sensor is not present here we print a diagnostic and exit.
     */
    uint16_t probe = 0;
    if (i2c_read_reg16(fd, 0x00, &probe) != 0) {
        fprintf(stderr, "MLX75030 not responding at 0x%02X on %s\n",
                MLX75030_ADDR, I2C_BUS);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX75030 detected at 0x%02X on %s\n", MLX75030_ADDR, I2C_BUS);
    printf("Reading distance every 500 ms (Ctrl-C to quit)...\n");

    while (g_running) {
        uint16_t distance = 0;
        if (i2c_read_reg16(fd, 0x00, &distance) != 0) {
            /*
             * Non-fatal: continue to the next cycle.
             * A transient I2C bus error may recover.
             */
            continue;
        }

        printf("Distance: %u mm\n", distance);
        fflush(stdout);

        struct timespec ts = { 0, SAMPLE_PERIOD_NS };
        nanosleep(&ts, NULL);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

