/*
 * HC-SR04 Ultrasonic Distance Measurement (Raspberry Pi 3 Model B+)
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5V (Pin 2)
 *   HC-SR04 GND  -> GND (Pin 6)
 *   HC-SR04 TRIG -> GPIO17 (Pin 11)
 *   HC-SR04 ECHO -> GPIO18 (Pin 12) via 1kΩ resistor (Pin 13)
 *
 * The Pi GPIO is 3.3V tolerant; the HC-SR04 operates at 5V. A 1kΩ resistor
 * is placed between the echo pin and the Pi's 3.3V rail to drop the voltage
 * to a safe 3.3V level.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000   /* 200 ms */
#define READ_INTERVAL_S  1
#define MAX_PULSE_US     38000    /* HC-SR04 max range timeout (~38000 µs) */
#define MIN_PULSE_US     0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio's gpioDelay() is a busy-wait that blocks for the given microseconds.
 * On the Pi 3 Model B+ the 32-bit microsecond counter wraps every ~71.6 min.
 * We use a 32-bit unsigned counter that wraps correctly.
 */
static uint32_t safe_delay_us(uint32_t us)
{
    uint32_t start = gpioTick();
    while (gpioTick() - start < (uint32_t)us) {
        /* spin */
    }
    return (uint32_t)us;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

int main(void)
{
    char ts[32];

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        fprintf(stderr, "       Is the pigpio daemon running?  sudo killall pigpiod\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin LOW.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main measurement loop --- */
    while (g_running) {
        /* --- Issue 10 µs trigger pulse --- */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set trigger HIGH.\n");
            break;
        }
        safe_delay_us(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set trigger LOW.\n");
            break;
        }

        /* --- Wait for echo rising edge (timeout) --- */
        uint32_t start_tick = gpioTick();
        bool got_rising = false;

        while (g_running) {
            uint32_t now = gpioTick();
            if (now - start_tick > ECHO_TIMEOUT_US) {
                got_rising = true;
                break;
            }
            if (gpioRead(ECHO_PIN) == 1) {
                got_rising = true;
                break;
            }
            safe_delay_us(10);
        }

        if (!got_rising) {
            fprintf(stderr, "Warning: echo rising-edge timeout (sensor absent or not responding).\n");
            goto next_cycle;
        }

        /* --- Record echo pin level (rising edge = start of pulse) --- */
        uint32_t echo_start = gpioTick();

        /* --- Wait for echo falling edge (timeout) --- */
        while (g_running) {
            uint32_t now = gpioTick();
            if (now - echo_start > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Warning: echo falling-edge timeout (data stuck high).\n");
                goto next_cycle;
            }
            if (gpioRead(ECHO_PIN) == 0) {
                break;
            }
            safe_delay_us(10);
        }

        if (!got_rising) {
            goto next_cycle;
        }

        /* --- Measure pulse duration --- */
        uint32_t pulse_us = gpioTick() - echo_start;

        /* --- Validate pulse width --- */
        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: invalid pulse duration (%u µs) - possible sensor fault.\n", pulse_us);
            goto next_cycle;
        }

        /* --- Convert to distance (speed of sound ≈ 343 m/s) --- */
        /* distance = (pulse_us * 343) / 2 / 1e6  (round trip) */
        double distance = (double)pulse_us * 0.0343 / 2.0 / 1000.0;

        get_timestamp(ts, sizeof(ts));
        printf("[%s] Distance: %.2f cm\n", ts, distance);
        fflush(stdout);

    next_cycle:
        /* Sleep for the remainder of the 1-second interval */
        uint32_t remaining = READ_INTERVAL_S * 1000000;
        if (remaining > ECHO_TIMEOUT_US) {
            remaining = ECHO_TIMEOUT_US;
        }
        safe_delay_us(remaining);
    }

    /* --- Graceful shutdown --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

