/*
 * Raspberry Pi 3 Model B+ - IWR1443 mmWave Radar Range Profile Monitor
 *
 * Reads range profile data from the TI IWR1443 over UART (/dev/serial0),
 * decodes the 8-byte magic word header, and analyzes the 128-byte data
 * payload (64 little-endian 16-bit distance bins).
 *
 * On detection of a target within 1.0 m, logs an ISO-8601 timestamp and
 * distance to intrusion_log.csv and activates an alert LED on GPIO 17.
 *
 * Build: gcc -O2 -Wall -o radar_monitor radar_monitor.c -lpigpio -lrt
 * Run:   sudo ./radar_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE      "/dev/serial0"
#define UART_BAUD_RATE   115200
#define GPIO_LED         17
#define TARGET_THRESHOLD 1.0f
#define LOG_FILE         "intrusion_log.csv"
#define MAGIC_WORD_LEN   8
#define DATA_PAYLOAD_LEN 128
#define MAX_FRAME_SIZE   4096
#define POLL_DELAY_US    100000

/* TI mmWave SDK 1.x frame layout (8-byte magic word + 128-byte payload) */
#define MMWAVE_MAGIC_WORD_0  0x01
#define MMWAVE_MAGIC_WORD_1  0x02
