#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x54
#define GPIO_ALERT 17
#define DISTANCE_THRESHOLD 10.0f
#define LOG_FILE "distance_log.txt"
#define POLL_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance(float *distance) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", bytes_read);
        return -1;
    }
    unsigned int raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *distance = (float)raw / 10.0f;
    return 0;
}

static int log_distance(float distance) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting time\n");
        return -1;
    }
    struct tm *tstruct = localtime(&now);
    if (tstruct == NULL) {
        fprintf(stderr, "Error converting time\n");
        return -1;
    }
    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }
    if (fprintf(log_file, "%s,%.2f\n", buf, distance) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_ALERT, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_ALERT);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_ALERT, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting distance monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float distance;
        if (read_distance(&distance) == 0) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Error logging distance\n");
            }
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(GPIO_ALERT, 1);
                printf("Alert: Distance %.2f cm below threshold\n", distance);
            } else {
                gpioWrite(GPIO_ALERT, 0);
            }
        } else {
