#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x49
#define LOG_FILE "distance_log.csv"
#define POLL_DELAY_US 100000
#define MAX_DISTANCE_MM 1200
#define STOP_DISTANCE_MM 300
#define APPROACH_DISTANCE_MM 600
#define SLOW_DISTANCE_MM 1200

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    /*
     * The VL53L1X driver expects a 16-byte block read from register 0x0000
     * to be followed by a 16-byte block read from register 0x0010.
     * We use i2cReadDevice to read the 32-byte block and parse the 16-byte
     * measurement payload.
     */
    char buf[32];

    /*
     * Read 32 bytes from register 0x0000 (measurement command register).
     * The first byte is the command byte (0x00 for start measurement).
     */
    if (i2cReadDevice(i2c_handle, buf, 32) != 32) {
        fprintf(stderr, "Failed to read measurement command register: %s\n",
                strerror(errno));
        return -1;
    }

    /*
     * The 32-byte block contains:
     *   Byte 0: command byte (0x00)
     *   Byte 1: measurement mode (0x00)
     *   Byte 2: measurement range (0x00)
     *   Byte 3: measurement mode (0x00)
     *   Byte 4: measurement range (0x00)
     *   Byte 5: measurement mode (0x00)
     *   Byte 6: measurement range (0x00)
     *   Byte 7: measurement mode (0x00)
     *   Byte 8: measurement range (0x00)
     *   Byte 9: measurement mode (0x00)
     *   Byte 10: measurement range (0x00)
     *   Byte 11: measurement mode (0x00)
     *   Byte 12: measurement range (0x00)
     *   Byte 13: measurement mode (0x00)
     *   Byte 14: measurement range (0x00)
     *   Byte 15: measurement mode (0x00)
     *   Byte 16: measurement range (0x00)
     *   Byte 17: measurement mode (0x00)
     *   Byte 18: measurement range (0x00)
     *   Byte 19: measurement mode (0x00)
     *   Byte 20: measurement range (0x00)
     *   Byte 21: measurement mode (0x00)
     *   Byte 22: measurement range (0x00)
     *   Byte 23: measurement mode (0x00)
     *   Byte 24: measurement range (0x00)
     *   Byte 25: measurement mode (0x00)
     *   Byte 26: measurement range (0x00)
     *   Byte 27: measurement mode (0x00)
     *   Byte 28: measurement range (0x00)
     *   Byte 29: measurement mode (0x00)
     *   Byte 30: measurement range (0x00)
     *   Byte 31: measurement mode (0x00)
     *   Byte 32: measurement range (0x00)
     */
    if (i2cReadDevice(i2c_handle, buf, 32) != 32) {
        fprintf(stderr, "Failed to read measurement command register: %s\n",
                strerror(errno));
        return -1;
    }

    /*
     * The 16-byte measurement payload starts at byte 8 (skip first 8 bytes).
     * The payload contains:
     *   Byte 0: status byte (0x00 = no error)
     *   Byte 1: distance MSB
     *   Byte 2: distance LSB
     *   Byte 3: distance X MSB
     *   Byte 4: distance X LSB
     *   Byte 5: distance Z MSB
     *   Byte 6: distance Z LSB
     */
    uint16_t status = (uint16_t)buf[8];
    if (status != 0x00) {
        fprintf(stderr, "Sensor error: status = 0x%04X\n", status);
        return -1;
    }

    uint16_t distance_mm = ((uint16_t)buf[10] << 8) | (uint16_t)buf[11];
    return 0;
}

static int read_distance(void) {
    if (init_sensor() != 0) {
        return -1;
    }
    return 0;
}

static int log_distance(int distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void print_guidance(int distance_mm) {
    if (distance_mm < STOP_DISTANCE_MM) {
        printf("STOP\n");
    } else if (distance_mm < APPROACH_DISTANCE_MM) {
        printf("APPROACH\n");
    } else if (distance_mm < SLOW_DISTANCE_MM) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if the file is newly created (size == 0). */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "timestamp,distance_mm\n") < 0) {
            fprintf(stderr, "Failed to write header to log file: %s\n",
                    strerror(errno));
            cleanup();
            return 1;
        }
        fflush(log_file);
    }

    printf("Parking Assistance System started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Logging error, continuing...\n");
        }

        print_guidance(distance);

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

