    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void print_guidance(int distance_mm) {
    if (distance_mm < STOP_DISTANCE_MM) {
        printf("STOP\n");
    } else if (distance_mm < APPROACH_DISTANCE_MM) {
        printf("APPROACH\n");
    } else if (distance_mm < SLOW_DISTANCE_MM) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if the file is newly created (size == 0). */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "timestamp,distance_mm\n") < 0) {
            fprintf(stderr, "Failed to write header to log file: %s\n",
                    strerror(errno));
            cleanup();
            return 1;
        }
        fflush(log_file);
    }

    printf("Parking Assistance System started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Logging error, continuing...\n");
        }

        print_guidance(distance);

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

