#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* CH201 I2C address (7-bit) */
#define CH201_ADDR 0x49

/* CH201 register addresses */
#define CH201_REG_CONFIG 0x00
#define CH201_REG_DISTANCE 0x01

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 18

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Blink half-cycle delay in microseconds (100 Hz) */
#define BLINK_DELAY_US 10000

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* I2C helpers with retry                                              */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X), attempt %d/%d: rc=%d\n",
                reg, value, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *out = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "I2C read failed (reg 0x%02X), attempt %d/%d: rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* CH201 driver                                                         */
/* ------------------------------------------------------------------ */
static int ch201_init(int handle)
{
    /*
     * Config register (0x00):
     *   Bit 0  : Mode = 1 (continuous measurement)
     *   Bits 1-2 : Range = 00 (default)
     *   Bits 3-4 : Resolution = 00 (default)
     *   Bit 5  : ALS enable = 0 (disable ALS)
     *   Bit 6  : ALS auto-trigger = 0
     *   Bit 7  : ALS auto-trigger = 0
     *   Bit 8  : ALS auto-trigger = 0
     *   Bit 9  : ALS auto-trigger = 0
     *   Bit 10 : ALS auto-trigger = 0
     *   Bit 11 : ALS auto-trigger = 0
     *   Bit 12 : ALS auto-trigger = 0
     *   Bit 13 : ALS auto-trigger = 0
     *   Bit 14 : ALS auto-trigger = 0
     *   Bit 15 : ALS auto-trigger = 0
     *   Bit 16 : ALS auto-trigger = 0
     *   Bit 17 : ALS auto-trigger = 0
     *   Bit 18 : ALS auto-trigger = 0
     *   Bit 19 : ALS auto-trigger = 0
     *   Bit 20 : ALS auto-trigger = 0
     *   Bit 21 : ALS auto-trigger = 0
     *   Bit 22 : ALS auto-trigger = 0
     *   Bit 23 : ALS auto-trigger = 0
     *   Bit 24 : ALS auto-trigger = 0
     *   Bit 25 : ALS auto-trigger = 0
     *   Bit 26 : ALS auto-trigger = 0
     *   Bit 27 : ALS auto-trigger = 0
     *   Bit 28 : ALS auto-trigger = 0
     *   Bit 29 : ALS auto-trigger = 0
     *   Bit 30 : ALS auto-trigger = 0
     *   Bit 31 : ALS auto-trigger = 0
     *
     * The CH201 is a continuous-measurement sensor; the default config
     * enables measurement and sets a default range of 4 m.  We keep the
     * default resolution and disable ALS so that the sensor is in
     * continuous-measurement mode.
     */
    if (i2c_write_reg8(handle, CH201_REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Failed to write CH201 config register\n");
        return -1;
    }
    return 0;
}

static int ch201_read_distance(int handle, uint16_t *distance)
{
    uint8_t buf[2];
    if (i2c_read_reg8(handle, CH201_REG_DISTANCE, &buf[0]) != 0) {
        fprintf(stderr, "Failed to read CH201 distance register\n");
        return -1;
    }
    *distance = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                          */
/* ------------------------------------------------------------------ */
static void led_set(int pin, int on)
{
    if (gpioWrite(pin, on ? 1 : 0) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", pin, on);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    led_set(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: rc=%d\n",
                I2C_BUS, CH201_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize CH201 sensor */
    if (ch201_init(i2c_handle) != 0) {
        fprintf(stderr, "CH201 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    led_set(LED_PIN, 0);

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance reader started.  LED on GPIO %d.  Ctrl+C to exit.\n", LED_PIN);

    while (!terminate) {
        uint16_t distance = 0;
        if (ch201_read_distance(i2c_handle, &distance) == 0) {
            /*
             * Blink LED once per sample.  Each half-cycle is 500 ms
             * (2 half-cycles * 250 ms), so the LED is on for half the
             * time and off for the other half.  This gives a smooth
             * blink that tracks the distance.
             */
            led_set(LED_PIN, 1);
            gpioDelay(BLINK_DELAY_US);
            led_set(LED_PIN, 0);
            gpioDelay(BLINK_DELAY_US);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Timestamp */
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        /* Log distance and blink frequency */
        printf("%s  Distance: %u mm  LED: %d Hz\n", ts, distance,
               (BLINK_DELAY_US / 1000000) / 2);
        fflush(stdout);

        gpioDelay(100000); /* 100 ms between samples */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

