        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_out) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(fd, CMD_START_MEAS) < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(MEAS_DELAY_MS * 1000);

        uint8_t buf[2];
        if (i2c_read_bytes(fd, buf, 2) < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *distance_out = (int)raw;
        return 0;
    }
    return -1;
}

static void log_data(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fflush(fp);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open distance_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,distance_cm\n");
        fflush(log_file);
    }

    printf("MLX75030 distance logger started. Press Ctrl+C to stop.\n");

    while (running) {
        int distance;
        if (read_distance(i2c_fd, &distance) < 0) {
            fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
        } else {
            log_data(log_file, distance);
            printf("Distance: %d cm\n", distance);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

