        return -1;
    }
    return 0;
}

/* ----------------------------- Read distance ----------------------------- */
/*
 * The MLX75030 ToF module exposes a register-mapped interface.  We
 * assume a 16-bit register address (big-endian) and a 16-bit data
 * register (big-endian).  The exact register addresses depend on the
 * specific firmware revision and configuration, but a typical
 * sequence might read a 16-bit status register and a 16-bit distance
 * register.
