                          (uint16_t)(uint8_t)data_buf[1];
            *distance_out = (float)raw;
            return 0;
        }

        fprintf(stderr, "[WARN] i2cReadDevice (distance) attempt %d/%d: rc=%d\n",
                attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US);
    }

