    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] MLX75030 reader started.  Bus=%d  Addr=0x%02X  Period=%d ms\n",
           I2C_BUS, I2C_ADDR, SAMPLE_PERIOD_US / 1000);
    printf("[INFO] Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        float distance;

        rc = read_distance(&distance);
        if (rc == 0) {
            /* --- Timestamp --- */
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            struct tm tm_info;
            localtime_r(&ts.tv_sec, &tm_info);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

            /* --- Print --- */
            printf("%s.%03ld  Distance: %.2f cm\n",
                   timestamp, ts.tv_nsec / 1000000L, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; continuing.\n");
        }

        /* --- Wait remainder of the 100 ms period --- */
        gpioDelay(SAMPLE_PERIOD_US - MEASURE_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
