/*
 * Raspberry Pi 4 Model B - VL53L1X Time-of-Flight Sensor with Buzzer Alert
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO 2 (I2C1 SDA)
 *   VL53L1X SCL -> GPIO 3 (I2C1 SCL)
 *   VL53L1X VDD -> 3.3V
 *   VL53L1X GND -> GND
 *   Buzzer +    -> GPIO 22 (BCM)
 *   Buzzer -    -> GND
 *
 * Build: gcc -Wall -o vl53l1x_buzzer vl53l1x_buzzer.c -lpigpio -lrt
 * Run:   sudo ./vl53l1x_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L1X I2C address (7-bit) */
#define VL53L1X_ADDR 0x60

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0014
#define VL53L1X_REG_RESULT_DISTANCE_MSB    0x0096
#define VL53L1X_REG_RESULT_DISTANCE_LSB    0x0097

/* Buzzer GPIO pin (BCM numbering) */
#define BUZZER_PIN 22

/* Distance threshold in millimeters */
#define DISTANCE_THRESHOLD 100

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Global flag for graceful shutdown */
static volatile sig_atomic_t running = 1;

/* Signal handler for SIGINT (Ctrl+C) */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a single byte to a VL53L1X register */
static int vl53l1x_write_reg(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a single byte from a VL53L1X register */
static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian value from a VL53L1X register */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

/* Initialize the VL53L1X sensor */
static int vl53l1x_init(int handle) {
    /* Soft reset */
    if (vl53l1x_write_reg(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for reset to complete */

    /* Start continuous ranging mode */
    if (vl53l1x_write_reg(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging mode.\n");
        return -1;
    }

    return 0;
}

/* Read distance from the VL53L1X sensor */
static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status;
    uint16_t distance_raw;

    /* Check if new data is available */
    if (vl53l1x_read_reg(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }

    /* Clear the range status register before reading */
    if (vl53l1x_write_reg(handle, VL53L1X_REG_RESULT_RANGE_STATUS, status) < 0) {
        fprintf(stderr, "Error: Failed to clear range status register.\n");
        return -1;
    }

    /* Read distance (16-bit little-endian) */
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE_MSB, &distance_raw) < 0) {
        fprintf(stderr, "Error: Failed to read distance register.\n");
        return -1;
    }

    *distance = distance_raw;
    return 0;
}

int main(void) {
    int i2c_handle = -1;
    int ret = EXIT_FAILURE;

    /* Register signal handler for SIGINT */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        goto cleanup_gpio;
    }

    /* Initialize VL53L1X sensor */
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        goto cleanup_i2c;
    }

    /* Set buzzer pin as output and ensure it is off */
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    printf("VL53L1X distance sensor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        uint16_t distance;

        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_PIN, 1);
                printf("Distance below threshold! Buzzer ON.\n");
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read distance. Skipping iteration.\n");
        }

        gpioDelay(500000); /* 500 ms delay */
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

cleanup_gpio:
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    return ret;
}

