        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_PIN, 1);
                printf("Distance below threshold! Buzzer ON.\n");
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read distance. Skipping iteration.\n");
        }

        gpioDelay(500000); /* 500 ms delay */
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

cleanup_gpio:
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    return ret;
}

