#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define MIN_DISTANCE 2.0f
#define MAX_DISTANCE 400.0f
#define MIN_ANGLE    2
#define MAX_ANGLE    90

#define TIMEOUT_US   50000   /* 50 ms max echo wait */
#define LOOP_DELAY_US 200000 /* 200 ms between readings */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Map a distance in cm to a servo angle in degrees.
 * Returns -1.0f on invalid input.
 */
static float distance_to_angle(float distance)
{
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0f;
    }
    return (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) *
           (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
}

/*
 * Issue a 10 µs trigger pulse on the HC-SR04.
 * Returns 0 on success, -1 on failure.
 */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1;
    }
    return 0;
}

/*
 * Read the echo pulse width in microseconds.
 * Returns -1.0f on timeout or read error.
 */
static float read_echo_pulse(void)
{
    uint32_t start_tick, end_tick, elapsed;

    /* Wait for echo to go high */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo to go low */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    elapsed = end_tick - start_tick;
    return (float)elapsed / 1000.0f;
}

/*
 * Log a distance reading with a timestamp to sensor_data.log.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(float distance)
{
    FILE *fp = fopen("sensor_data.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fclose(fp);
    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error installing SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) initial low failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure servo starts in centre position */
    if (gpioServo(SERVO_PIN, 1500) < 0) {
        fprintf(stderr, "Error: gpioServo(initial) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Error: trigger_sensor failed\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float pulse_us = read_echo_pulse();
        if (pulse_us < 0.0f) {
            fprintf(stderr, "Error: echo read timeout\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float distance = pulse_us * 0.0343f; /* speed of sound in cm/µs */

        float angle = distance_to_angle(distance);
        if (angle < 0.0f) {
            fprintf(stderr, "Error: distance out of range (%.2f cm)\n", distance);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (gpioServo(SERVO_PIN, (int)angle) < 0) {
            fprintf(stderr, "Error: gpioServo failed\n");
        }

        if (log_data(distance) != 0) {
            fprintf(stderr, "Warning: failed to log data\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    gpioServo(SERVO_PIN, 0); /* stop servo PWM */
    gpioWrite(TRIGGER_PIN, 0); /* ensure trigger is low */
    gpioTerminate();

    printf("Parking assist system stopped.\n");
    return EXIT_SUCCESS;
}

