/*
 * VL53L1X distance sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Buzzer +    -> GPIO23 (BCM)
 *   Buzzer -    -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_buzzer vl53l1x_buzzer.c -lpthread -lrt
 *
 * Run:
 *   sudo ./vl53l1x_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <fcntl.h>
#include <mqueue.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/time.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L1X_ADDR   0x60
#define BUZZER_PIN     23
#define DISTANCE_MM    100
#define POLL_MS        50
#define MAX_DISTANCE   400

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0014
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_RESULT_PEAK_SIGNAL_RATE 0x0089

/* VL53L1X command register */
#define VL53L1X_REG_SYSTEM_COMMAND         0x0001

/* VL53L1X command opcodes */
#define VL53L1X_CMD_START_SINGLE_MEASURE   0x01
#define VL53L1X_CMD_STOP_MEASUREMENT       0x0F
#define VL53L1X_CMD_SOFT_RESET             0x01

/* Message queue name */
#define MQUEUE_NAME "vl53l1x_mq"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static mqd_t g_mqd = (mqd_t)-1;
static pthread_mutex_t g_mq_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *value)
{
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value)
{
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                        */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int fd)
{
    uint8_t id;
    if (i2c_read_reg8(fd, 0x010F, &id) < 0) {
        fprintf(stderr, "Cannot read device ID (sensor absent or bus error)\n");
        return -1;
    }
    if (id != 0xEA) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0xEA)\n", id);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, 0x01) < 0)
        return -1;
    usleep(10000); /* 10 ms */
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    usleep(10000); /* 10 ms */

    /* Start single measurement mode */
    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_MODE_START,
                        VL53L1X_CMD_START_SINGLE_MEASURE) < 0)
        return -1;

    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status;
    uint16_t dist;

    /* Poll for data-ready (bit 0 of RESULT_RANGE_STATUS) */
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg8(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        usleep(1000);
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "VL53L1X measurement timeout\n");
        return -1;
    }

    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, &dist) < 0)
        return -1;

    /* Clear the interrupt by writing 0x01 to the command register */
    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_COMMAND, 0x01) < 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Message queue helper                                                 */
/* ------------------------------------------------------------------ */
static int mq_send(mqd_t mq, const char *msg)
{
    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = 1;
    attr.mq_msgsize = strlen(msg);
    attr.mq_curmsgs = 0;

    if (mq_send(mq, &attr, msg) < 0) {
        fprintf(stderr, "mq_send failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                VL53L1X_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Create message queue */
    g_mqd = mq_open(MQUEUE_NAME, O_CREAT | O_RDWR, 0666, 0);
    if (g_mqd == (mqd_t)-1) {
        fprintf(stderr, "mq_open failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(g_i2c_fd, &distance) < 0) {
            fprintf(stderr, "Read failed; continuing.\n");
        } else {
            char msg[64];
            snprintf(msg, sizeof(msg), "%u", distance);

            pthread_mutex_lock(&g_mq_mutex);
            mq_send(g_mqd, msg);
            pthread_mutex_unlock(&g_mq_mutex);

            if (distance < DISTANCE_MM) {
                if (gpioWrite(BUZZER_PIN, 1) < 0)
                    fprintf(stderr, "Warning: failed to activate buzzer\n");
            } else {
                if (gpioWrite(BUZZER_PIN, 0) < 0)
                    fprintf(stderr, "Warning: failed to deactivate buzzer\n");
            }
        }

        usleep(POLL_MS * 1000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    pthread_mutex_lock(&g_mq_mutex);
    if (g_mqd != (mqd_t)-1) {
        mq_close(g_mqd);
        g_mqd = (mqd_t)-1;
    }
    pthread_mutex_unlock(&g_mq_mutex);
    pthread_mutex_destroy(&g_mq_mutex);
    close(g_i2c_fd);

    return EXIT_SUCCESS;
}

