/*
 * Parking sensor using HC-SR04 ultrasonic sensor on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5V (Pin 2)
 *   HC-SR04 GND  -> GND (Pin 6)
 *   HC-SR04 TRIG -> GPIO17 (Pin 11)
 *   HC-SR04 ECHO -> GPIO27 (Pin 13)
 *   Buzzer +     -> GPIO22 (Pin 15)
 *   Buzzer -     -> GND (Pin 14)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o parking_sensor parking_sensor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND_CM_PER_US 0.0343f
#define TRIGGER_PULSE_US         10
#define ECHO_TIMEOUT_US         30000   /* 30 ms max echo wait */
#define LOOP_DELAY_US          100000  /* 100 ms between readings */
#define BUZZER_THRESHOLD_CM    30.0f
#define MIN_VALID_CM           2.0f
#define MAX_VALID_CM           400.0f

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Interrupt callback (runs in pigpio thread)                          */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        static uint32_t start_tick = 0;
        start_tick = tick;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        static uint32_t end_tick = 0;
        if (start_tick != 0) {
            end_tick = tick;
            uint32_t diff = end_tick - start_tick;   /* correct 32-bit wrap */
            uint32_t pulse_us = end_tick - start_tick;
            float distance_cm = (float)pulse_us * SPEED_OF_SOUND_CM_PER_US;

            if (distance_cm < MIN_VALID_CM || distance_cm > MAX_VALID_CM) {
                fprintf(stderr,
                        "Warning: invalid distance reading %.2f cm (out of range)\n",
                        distance_cm);
                return;
            }

            printf("Distance: %.2f cm\n", distance_cm);
            fflush(stdout);
        }
        start_tick = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure buzzer is off */
    if (gpioInitialise() >= 0) {
        gpioWrite(BUZZER_PIN, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set BUZZER_PIN %d as output\n", BUZZER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);
    gpioDelay(10000);  /* 10 ms settle */

    /* Register interrupt callback for echo line */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: cannot register interrupt on ECHO_PIN %d\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking sensor running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        /* Reset echo state for next reading */
        static uint32_t echo_start_tick = 0;
        echo_start_tick = 0;

        /* Trigger a 10 µs HIGH pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN HIGH\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN LOW\n");
            break;
        }

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (g_running) {
            if (gpioTick() - wait_start > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);  /* poll every 100 µs */
        }

        /* Check for timeout (sensor absent or no object) */
        if (echo_start_tick == 0) {
            fprintf(stderr, "Warning: echo timeout - no object detected or sensor absent\n");
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Read distance from callback (already computed in callback) */
        float distance_cm = (float)echo_start_tick * SPEED_OF_SOUND_CM_PER_US;

        /* Activate buzzer if distance < threshold */
        if (distance_cm < BUZZER_THRESHOLD_CM) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }

        /* Wait before next reading */
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(BUZZER_PIN, 0);
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

