/*
 * Gate controller for Raspberry Pi Zero W
 * Sensor : VL53L1X time-of-flight (I2C bus 1, 0x19)
 * Actuator: SG90 servo on GPIO18 (hardware PWM)
 *
 * Build: gcc -O2 -Wall -o gate gate.c -lpigpio -lrt
 * Run  : sudo ./gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define VL53L1X_ADDR         0x19
#define SERVO_PIN            18
#define DISTANCE_THRESHOLD   20   /* cm */
#define LOG_FILE             "gate_log.txt"
#define MAX_RETRIES          3
#define RETRY_DELAY_US       100000

/* ---- VL53L1X register map ---- */
#define VL53L1X_SOFT_RESET   0x0000
#define VL53L1X_SYSTEM_START 0x0001
#define VL53L1X_RESULT_RANGE 0x0089
#define VL53L1X_RESULT_RANGE_STATUS 0x008A
#define VL53L1X_RESULT_RANGE_VAL     0x008C
#define VL53L1X_RESULT_RANGE_INT_STATUS 0x008B

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

/* ---- Forward declarations ---- */
static void signal_handler(int sig);
static void log_event(const char *msg);
static int  i2c_write_reg16(int handle, uint16_t reg, uint8_t val);
static int  i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance);
static void control_gate(int distance);
static void remote_control(int handle);

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamped logging to file                                        */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s: %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register on the VL53L1X                             */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t val)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    return i2cWriteDevice(handle, buf, 3);
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes starting at a 16-bit register                       */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0)
        return -1;

    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L1X sensor                                    */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Software reset */
    if (i2c_write_reg16(handle, VL53L1X_SOFT_RESET, 0x00) != 0) {
        log_event("VL53L1X: software reset write failed");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Wait for sensor to boot (max ~100 ms) */
    for (int i = 0; i < 20; i++) {
        uint8_t status;
        if (i2c_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, &status, 1) != 0) {
            log_event("VL53L1X: range status read failed");
            return -1;
        }
        if ((status & 0x01) == 0)
            break;
        gpioDelay(2000); /* 2 ms */
    }
    if (status & 0x01) {
        log_event("VL53L1X: sensor not ready after boot");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_START, 0x01) != 0) {
        log_event("VL53L1X: start ranging failed");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit distance from the VL53L1X                           */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t buf[2];
    if (i2c_read_reg16(handle, VL53L1X_RESULT_RANGE_VAL, buf, 2) != 0) {
        log_event("VL53L1X: distance read failed");
        return -1;
    }
    *distance = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Control the gate based on distance                                 */
/* ------------------------------------------------------------------ */
static void control_gate(int distance)
{
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(SERVO_PIN, 1000); /* full speed right (open) */
        log_event("Gate: opening");
    } else {
        gpioWrite(SERVO_PIN, 500);  /* stop */
        log_event("Gate: closing");
    }
}

/* ------------------------------------------------------------------ */
/* Remote control via the VL53L1X v2 callback API                       */
/* ------------------------------------------------------------------ */
static void remote_control(int handle)
{
    /* Force open */
    if (i2c_write_reg16(handle, 0x00, 0x01) != 0) {
        log_event("Remote: force_open failed");
        return;
    }
    gpioDelay(100000); /* 100 ms */
    log_event("Remote: gate opened");

    /* Force close */
    if (i2c_write_reg16(handle, 0x00, 0x02) != 0) {
        log_event("Remote: force_close failed");
        return;
    }
    gpioDelay(100000); /* 100 ms */
    log_event("Remote: gate closed");
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C open failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure servo pin */
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 1000); /* 1 kHz */
    gpioPWM(SERVO_PIN, 0);

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open log file %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("System started");

    /* Main loop */
    while (g_running) {
        uint16_t distance = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
                ok = 1;
