/*
 * HC-SR04 Ultrasonic Distance Measurement (Raspberry Pi 4 Model B)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM, physical pin 16)
 *   HC-SR04 ECHO -> GPIO24 (BCM, physical pin 18)
 *   HC-SR04 VCC  -> 5 V (external supply recommended)
 *   HC-SR04 GND  -> GND
 *
 * The ECHO line is 5 V; use a logic-level converter or divide the
 * signal down to 3.3 V for the Pi's 3.3 V tolerance.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse              */
#define SAMPLE_PERIOD_US 200000      /* 200 µs between samples           */
#define ECHO_TIMEOUT_US  60000       /* 60 ms max echo wait              */
#define MIN_PULSE_US     100         /* reject noise < 100 µs             */
#define MAX_PULSE_US     30000       /* reject timeout / no object      */

#define LOG_FILE         "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                      */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_rise_tick = 0;
static volatile uint32_t g_fall_tick = 0;
static volatile bool     g_echo_seen = false;
static volatile bool     g_echo_valid = false;
static volatile bool     g_running   = true;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* Echo callback (runs in pigpio callback thread)                      */
/* ------------------------------------------------------------------ */

static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        g_rise_tick = tick;
        g_echo_seen = true;
    } else if (level == 0) {
        g_fall_tick = tick;
        g_echo_seen = true;
        g_echo_valid = true;
    }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

static void log_distance(FILE *fp, float distance)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s, %.2f\n", ts, distance);
    fflush(fp);
    printf("%s, %.2f\n", ts, distance);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(FILE *fp)
{
    if (fp) {
        fclose(fp);
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: cannot set pull-down on ECHO_PIN %d.\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: cannot initialise TRIGGER_PIN %d LOW.\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN %d.\n",
                ECHO_PIN);
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error registering signal handler");
        cleanup(fp);
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, log=%s\n", TRIGGER_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset state for this sample */
        g_echo_seen = false;
        g_echo_valid = false;
        g_running = true;

        /* Generate trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Warning: TRIGGER_PIN write failed.\n");
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Warning: TRIGGER_PIN write failed.\n");
        }

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (!g_echo_seen && g_running) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                fprintf(stderr,
                        "Warning: echo timeout - no echo received within %u µs.\n",
                        ECHO_TIMEOUT_US);
                g_running = false;
                break;
            }
            gpioDelay(100);  /* poll every 100 µs */
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_valid) {
            fprintf(stderr, "Warning: no valid echo received.\n");
            continue;
        }

        /* Compute pulse width (32-bit tick wraparound handled) */
        uint32_t pulse_us = g_fall_tick - g_rise_tick;
        if (pulse_us < MIN_PULSE_US) {
            fprintf(stderr, "Warning: pulse width %.0f µs too short (noise).\n",
                    pulse_us);
            continue;
        }
        if (pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: pulse width %.0f µs too long (timeout).\n",
                    pulse_us);
            continue;
        }

        /* distance = (pulse_us * speed_of_sound) / 2  (µs / 34300) */
        float distance = (float)pulse_us * 0.01715f;
        log_distance(fp, distance);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    cleanup(fp);
    return EXIT_SUCCESS;
}

