/*
 * Smart Parking Gate Controller for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VL53L1X Time-of-Flight sensor on I2C bus 1 (GPIO2/SDA, GPIO3/SCL)
 *   - Servo motor on GPIO18 (hardware PWM)
 *   - Shutdown line on GPIO23 (BCM)
 *   - Interrupt line on GPIO24 (BCM)
 *
 * Behavior:
 *   - Opens the gate when an object is detected within 50 cm.
 *   - Closes the gate when the object is more than 60 cm away.
 *   - Logs gate state and distance to parking_log.txt.
 *   - Handles SIGINT/SIGTERM for clean shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/serio.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L1X_ADDR   0x5C
#define SHUTDOWN_PIN   23
#define INTERRUPT_PIN  24
#define SERVO_PIN      18

#define DISTANCE_OPEN  50.0f
#define DISTANCE_CLOSE 60.0f

#define LOG_FILE "parking_log.txt"

/* VL53L1X Registers */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START        0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS  0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

#define VL53L1X_MODEL_ID_EXPECTED 0xEA

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *value) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select) for 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select) for 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

static int vl53l1x_init(int fd) {
    uint8_t model_id = 0;
    if (i2c_read_reg8(fd, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Failed to read VL53L1X model ID.\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Unexpected VL53L1X model ID: 0x%02X (expected 0x%02X).\n", model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }
    printf("VL53L1X detected, model ID: 0x%02X\n", model_id);

    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    usleep(10000);

    return 0;
}

static int vl53l1x_start_measurement(int fd) {
    return i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x01);
}

static int vl53l1x_stop_measurement(int fd) {
    return i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
}

static int vl53l1x_read_distance(int fd, float *distance) {
    uint16_t status = 0;
    uint16_t dist = 0;

    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status) < 0) return -1;
    if (status & 0x01) {
        if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, &dist) < 0) return -1;
        *distance = (float)dist;
        if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) return -1;
        usleep(10000);
        return 0;
    }
    return -1;
}

static void log_data(float distance, int gate_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(g_log_fp, "%s, Gate: %d, Distance: %.2f cm\n", timestamp, gate_state, distance);
    fflush(g_log_fp);
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        vl53l1x_stop_measurement(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L1X_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (vl53l1x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        cleanup();
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    if (gpioSetAlertFunc(INTERRUPT_PIN, interrupt_callback) < 0) {
        fprintf(stderr, "Failed to set interrupt callback: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Smart Parking Gate Controller started. Press Ctrl+C to exit.\n");

    int gate_state = 0;
    int last_distance = -1;

    while (g_running) {
        float distance = 0.0f;
        if (vl53l1x_read_distance(g_i2c_fd, &distance) < 0) {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
            usleep(100000);
            continue;
        }

        if (distance > 0.0f && distance < DISTANCE_OPEN) {
            gate_state = 1;
            printf("Object detected! Opening gate.\n");
            if (gpioWrite(SERVO_PIN, 1) < 0) {
                fprintf(stderr, "Failed to set servo high: %s\n", strerror(errno));
            }
            log_data(distance, gate_state);
        } else if (distance > 0.0f && distance > DISTANCE_CLOSE) {
            gate_state = 0;
            printf("Object detected! Closing gate.\n");
            if (gpioWrite(SERVO_PIN, 0) < 0) {
                fprintf(stderr, "Failed to set servo low: %s\n", strerror(errno));
            }
            log_data(distance, gate_state);
        }

        if (gate_state == 1 && distance > DISTANCE_CLOSE) {
            gate_state = 0;
            printf("Object moved away. Closing gate.\n");
            if (gpioWrite(SERVO_PIN, 0) < 0) {
                fprintf(stderr, "Failed to set servo low: %s\n", strerror(errno));
            }
        } else if (gate_state == 0 && distance < DISTANCE_OPEN) {
            gate_state = 1;
            printf("Object moved away. Opening gate.\n");
            if (gpioWrite(SERVO_PIN, 1) < 0) {
                fprintf(stderr, "Failed to set servo high: %s\n", strerror(errno));
            }
            log_data(distance, gate_state);
        }

        last_distance = distance;
        usleep(100000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

static void interrupt_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        float distance = 0.0f;
        if (vl53l1x_read_distance(g_i2c_fd, &distance) < 0) {
            return;
        }
        printf("Interrupt received! Distance: %.2f cm\n", distance);
        log_data(distance, 1);
    }
}

