            if (gpioWrite(SERVO_PIN, 0) < 0) {
                fprintf(stderr, "Failed to set servo low: %s\n", strerror(errno));
            }
        } else if (gate_state == 0 && distance < DISTANCE_OPEN) {
            gate_state = 1;
            printf("Object moved away. Opening gate.\n");
            if (gpioWrite(SERVO_PIN, 1) < 0) {
                fprintf(stderr, "Failed to set servo high: %s\n", strerror(errno));
            }
            log_data(distance, gate_state);
        }

        last_distance = distance;
        usleep(100000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

static void interrupt_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        float distance = 0.0f;
        if (vl53l1x_read_distance(g_i2c_fd, &distance) < 0) {
            return;
        }
        printf("Interrupt received! Distance: %.2f cm\n", distance);
        log_data(distance, 1);
    }
}

