/*
 * VL53L1X Gate Controller for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Gate Control:
 *     GPIO18 (BCM) -> Gate motor control (HIGH = open, LOW = close)
 *     GPIO19 (BCM) -> Gate motor control (LOW = open, HIGH = close)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gate_controller gate_controller.c -lpigpio -lrt
 *   sudo ./gate_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L1X I2C address (7-bit) ---- */
#define VL53L1X_ADDR 0x60

/* ---- VL53L1X register addresses ---- */
#define VL53L1X_REG_SOFT_RESET              0x0000
#define VL53L1X_REG_SYSTEM_MODE_START      0x0001
#define VL53L1X_REG_SYSTEM_THRESH_HIGH     0x0002
#define VL53L1X_REG_SYSTEM_THRESH_LOW      0x0003
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG    0x0004
#define VL53L1X_REG_SYSTEM_INTERMEAS_PERIOD 0x0005
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0006
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0007
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0008
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0009
#define VL53L1X_REG_RESULT_DISTANCE_MSB    0x0012
#define VL53L1X_REG_RESULT_DISTANCE_LSB    0x0013

/* ---- GPIO pin definitions ---- */
#define GPIO_GATE_OPEN 18
#define GPIO_GATE_CLOSE 19

/* ---- Application constants ---- */
#define POLL_INTERVAL_US 500000          /* 500 ms */
#define MAX_DISTANCE_MM  200             /* 20 cm */
#define LOG_FILE_NAME    "gate_events.log"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/*  Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  I2C helpers (16-bit register access via pigpio)                    */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;

    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/*  VL53L1X driver functions                                             */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L1X soft reset write failed.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Clear any pending interrupt */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X interrupt clear failed.\n");
        return -1;
    }

    /* Set timing budget: 100 ms (0x0000000A) */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x0000000A) < 0) {
        fprintf(stderr, "Error: VL53L1X range config write failed.\n");
        return -1;
    }

    /* Set inter-measurement period: 100 ms (0x0000000A) */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEAS_PERIOD, 0x0000000A) < 0) {
        fprintf(stderr, "Error: VL53L1X inter-measurement period write failed.\n");
        return -1;
    }

    /* Set interrupt configuration: 1 ranging cycle (0x00000001) */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x00000001) < 0) {
        fprintf(stderr, "Error: VL53L1X interrupt config write failed.\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_start_ranging(int handle)
{
    /* Set mode to ranging (0x01) */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X ranging mode start failed.\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status;
    uint8_t msb, lsb;

    /* Check for new data */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0) {
        fprintf(stderr, "Error: VL53L1X interrupt status read failed.\n");
        return -1;
    }
    if (!(status & 0x01)) {
        return 1; /* No new data yet */
    }

    /* Read 16-bit distance */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE_MSB, &msb, 1) < 0) {
        fprintf(stderr, "Error: VL53L1X distance MSB read failed.\n");
        return -1;
    }
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE_LSB, &lsb, 1) < 0) {
        fprintf(stderr, "Error: VL53L1X distance LSB read failed.\n");
        return -1;
    }

    *distance_mm = ((uint16_t)msb << 8) | lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
/*  GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_set_mode(int handle, int pin, int mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, %d) failed.\n", pin, mode);
        return -1;
    }
    return 0;
}

static int gpio_write(int handle, int pin, int value)
{
    if (gpioWrite(pin, value) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed.\n", pin, value);
        return -1;
    }
    return 0;
}

static int gpio_set_output(int handle, int pin)
{
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", pin);
        return -1;
    }
    if (gpioWrite(handle, pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed (initial LOW).\n", pin);
        return -1;
    }
    return 0;
}

static int gpio_set_input(int handle, int pin)
{
    if (gpioSetMode(pin, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event_type)
{
    time_t rawtime;
    struct tm utc;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &utc);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &utc);

    fprintf(g_log_file, "%s - %s\n", timestamp, event_type);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/*  Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(GPIO_GATE_OPEN, 0);
    gpioWrite(GPIO_GATE_CLOSE, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*  Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VL53L1X address */
    g_i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(1, 0x%02X) failed: %d\n", VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpio_set_mode(g_i2c_handle, GPIO_GATE_OPEN, PI_OUTPUT) < 0 ||
        gpio_set_mode(g_i2c_handle, GPIO_GATE_CLOSE, PI_OUTPUT) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    gpio_set_output(g_i2c_handle, GPIO_GATE_OPEN);
    gpio_set_output(g_i2c_handle, GPIO_GATE_CLOSE);

    /* Open log file */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s'.\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate controller started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t distance;
        int status;

        status = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (status == 0) {
            printf("Distance: %u mm\n", distance);

            if (distance < MAX_DISTANCE_MM) {
                if (gpio_write(g_i2c_handle, GPIO_GATE_OPEN, 1) < 0) {
                    fprintf(stderr, "Error: gpioWrite(%d, 1) failed.\n", GPIO_GATE_OPEN);
                } else {
                    log_event("Gate Opened");
                }
            } else {
                if (gpio_write(g_i2c_handle, GPIO_GATE_CLOSE, 1) < 0) {
                    fprintf(stderr, "Error: gpioWrite(%d, 1) failed.\n", GPIO_GATE_CLOSE);
                } else {
                    log_event("Gate Closed");
                }
            }
        } else if (status < 0) {
            fprintf(stderr, "Error: VL53L1X read failed.\n");
            log_event("VL53L1X Read Error");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

