/*
 * Raspberry Pi 4 Model B — VL53L1X ToF sensor + DC motor controller
 *
 * I2C bus 1  (GPIO2 = SDA, GPIO3 = SCL)
 * Motor: GPIO17 (forward) + GPIO18 (backward)
 * Thresholds: < 100 mm → forward, > 300 mm → backward, else stop
 *
 * Build: gcc -O2 -Wall -o vl53l1x_motor vl53l1x_motor.c -lpigpio -lrt
 * Run:   sudo ./vl53l1x_motor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin / I2C definitions ---- */
#define I2C_BUS          1
#define I2C_ADDR         0x50          /* VL53L1X default 7-bit address */
#define MOTOR_FORWARD    17
#define MOTOR_BACKWARD   18
#define THRESHOLD_LOW    100          /* mm  — run forward below this */
#define THRESHOLD_HIGH   300          /* mm  — run backward above this */
#define POLL_TIMEOUT_MS  1000         /* max wait for data-ready */
#define MAX_RETRIES      3

/* ---- VL53L1X register addresses ---- */
#define VL53L1X_SOFT_RESET      0x0000
#define VL53L1X_SYSTEM_START    0x0001
#define VL53L1X_RESULT_STATUS   0x0089
#define VL53L1X_RESULT_DISTANCE 0x0096

/* ---- Globals for ISR / cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_motor_state = 0;   /* 0 = stopped, 1 = forward, 2 = backward */

/* ------------------------------------------------------------------ */
/* ISR: called on every rising edge of GPIO24                        */
/* ------------------------------------------------------------------ */
static void distance_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;

    if (level != 1) return;                       /* only rising edges */

    uint8_t status;
    if (i2cReadI2CBlockData(g_i2c_handle, VL53L1X_RESULT_STATUS,
                            (char *)&status, 1) != 1) {
        fprintf(stderr, "ISR: I2C read of status failed\n");
        return;
    }

    if (!(status & 0x01)) {                       /* data-ready bit */
        return;
    }

    uint16_t distance;
    if (i2cReadI2CBlockData(g_i2c_handle, VL53L1X_RESULT_DISTANCE,
                            (char *)&distance, 2) != 2) {
        fprintf(stderr, "ISR: I2C read of distance failed\n");
        return;
    }

    int distance_mm = (int)distance;

    if (distance_mm < THRESHOLD_LOW) {
        g_motor_state = 1;
        printf("Distance: %d mm  →  Motor: forward\n", distance_mm);
    } else if (distance_mm > THRESHOLD_HIGH) {
        g_motor_state = 2;
        printf("Distance: %d mm  →  Motor: backward\n", distance_mm);
    } else {
        g_motor_state = 0;
        printf("Distance: %d mm  →  Motor: stopped\n", distance_mm);
    }

    if (gpioWrite(MOTOR_FORWARD, g_motor_state) != 0)
        fprintf(stderr, "ISR: gpioWrite(forward) failed\n");
    if (gpioWrite(MOTOR_BACKWARD, g_motor_state) != 0)
        fprintf(stderr, "ISR: gpioWrite(backward) failed\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call multiple times                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver — retry failed transactions with exponential backoff */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg(uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(g_i2c_handle, buf, 3) == 3)
            return 0;
        fprintf(stderr, "VL53L1X write(reg=0x%04X) attempt %d/%d failed\n",
                reg, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(1000000 * (1 << attempt));  /* 100 ms, 200 ms, 400 ms */
    }
    return -1;
}

static int vl53l1x_read_reg(uint16_t reg, uint8_t *value)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(g_i2c_handle, reg_buf, 2) == 2) {
            if (i2cReadI2CBlockData(g_i2c_handle, reg_buf[1], value, 1) == 1)
                return 0;
        }
        fprintf(stderr, "VL53L1X read(reg=0x%04X) attempt %d/%d failed\n",
                reg, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(1000000 * (1 << attempt));
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Soft reset + start measurement                                    */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(void)
{
    if (vl53l1x_write_reg(VL53L1X_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(1000);                       /* 1 ms settle */

    if (vl53l1x_write_reg(VL53L1X_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "VL53L1X start measurement failed\n");
        return -1;
    }
    gpioDelay(1000);                       /* 1 ms for first conversion */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance (mm) with retry                                    */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(uint16_t *distance_mm)
{
    uint8_t status;
    int attempts = 0;

    /* Poll status register until data-ready bit is set */
    do {
        if (vl53l1x_read_reg(VL53L1X_RESULT_STATUS, &status) != 0)
            return -1;
        if (++attempts > POLL_TIMEOUT_MS) {
            fprintf(stderr, "VL53L1X data-ready timeout\n");
            return -1;
        }
        gpioDelay(1000);
    } while (!(status & 0x01));

    if (!(status & 0x01)) {
        fprintf(stderr, "VL53L1X data-ready timeout\n");
        return -1;
    }

    uint16_t raw;
    if (vl53l1x_read_reg(VL53L1X_RESULT_DISTANCE, &raw) != 0)
        return -1;

    *distance_mm = (int)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(MOTOR_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed — sensor may be absent\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- ISR registration ---- */
    if (gpioSetISRFuncEx(24, RISING_EDGE, 0, distance_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on GPIO24\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitor running.  Thresholds: < %d mm → fwd, > %d mm → rev\n",
           THRESHOLD_LOW, THRESHOLD_HIGH);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t distance;
        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %u mm  →  Motor: %s\n",
                   (unsigned)distance,
                   g_motor_state == 1 ? "forward" :
                   g_motor_state == 2 ? "backward" : "stopped");
        } else {
            fprintf(stderr, "Distance read failed — stopping motor\n");
            g_motor_state = 0;
        }
        gpioDelay(100000);  /* 100 ms */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

