/*
 * HC-SR04 Ultrasonic Distance Measurement (Interrupt-Driven)
 * Board:  Raspberry Pi Zero W
 * Trigger: GPIO17 (BCM)
 * Echo:   GPIO18 (BCM) via 1k/2k divider to 3.3V
 * Library: pigpio (modern API, no wiringPi)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define LOG_FILE         "distance_log.txt"
#define SAMPLE_PERIOD_US 1000000   /* 1 second */
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000     /* 30 ms max echo wait */
#define MIN_VALID_US     58        /* ~1 cm  (HC-SR04 spec) */
#define MAX_VALID_US     25000     /* ~4 m  (HC-SR04 spec) */

/* ------------------------------------------------------------------ */
/* Shared state between ISR and main thread                           */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_echo_valid = false;
static volatile bool     g_running    = true;

/* ------------------------------------------------------------------ */
/* ISR callback (runs in pigpio thread)                                */
/* ------------------------------------------------------------------ */

static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_seen  = true;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        if (g_echo_seen) {
            g_end_tick = tick;
            g_echo_valid = true;
            g_echo_seen  = false;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

static void cleanup_gpio(void)
{
    /* Disable ISR and let pigpio terminate the thread */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
}

static void log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f m\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, initial value LOW */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise TRIGGER_PIN state\n");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    /* Configure echo pin as input */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    /*
     * Enable pigpio alert callback on the echo pin so we can capture
     * the rising and falling edges without blocking the main loop.
     * gpioSetAlertFuncEx returns 0 on success.
     */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on ECHO_PIN\n");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Log: %s\n",
           TRIGGER_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Reset state for this sample */
        g_echo_seen  = false;
        g_echo_valid = false;
        g_start_tick = 0;
        g_end_tick   = 0;

        /* Generate 10 µs trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN HIGH\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN LOW\n");
            break;
        }

        /* Wait for echo with timeout */
        uint32_t waited = 0;
        while (!g_echo_valid && waited < ECHO_TIMEOUT_US) {
            gpioDelay(100);   /* 100 µs granularity */
            waited += 100;
        }

        if (!g_running)
            break;

        if (!g_echo_valid) {
            fprintf(stderr, "Timeout: no echo received within %d µs\n",
                    ECHO_TIMEOUT_US);
            continue;
        }

        /* Validate pulse width */
        if (g_start_tick == 0 || g_end_tick == 0) {
            fprintf(stderr, "Invalid tick values (start=0, end=0)\n");
            continue;
        }
        uint32_t pulse_us = g_end_tick - g_start_tick;

        /* Convert to distance (HC-SR04: distance = (pulse_us * 34300 cm/s) / 2) */
        float distance = (float)pulse_us * 0.01715f;

        /* Sanity check: reject readings outside the sensor's operational range */
        if (distance < MIN_VALID_US || distance > MAX_VALID_US) {
            fprintf(stderr, "Distance out of range: %.2f µs (valid: %.0f–%.0f µs)\n",
                    distance, MIN_VALID_US, MAX_VALID_US);
            continue;
        }

        log_distance(distance);
        printf("Distance: %.2f m\n", distance);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

