#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x50
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_INTERVAL_US 100000
#define LOG_FILE "gate_log.txt"

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_MODE 0x0001
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0002
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0009
#define VL53L1X_REG_RESULT_DISTANCE 0x0016
#define VL53L1X_REG_RESULT_PEAK_SIGNAL_RATE 0x0017

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int write_reg16(uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        return -1;
    }
    return 0;
}

static int read_reg16(uint16_t reg, uint8_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, reg_buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int init_vl53l1x(void) {
    /* Soft reset */
    if (write_reg16(VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Set system mode to ranging (0x01) */
    if (write_reg16(VL53L1X_REG_SYSTEM_MODE, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set system mode.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupt */
    if (write_reg16(VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to clear interrupt.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    return 0;
}

static int read_distance_cm(float *distance_cm) {
    uint8_t status = 0;
    uint8_t distance_raw = 0;

    /* Check if new data is available */
    if (read_reg16(VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }

    if ((status & 0x01) == 0) {
        /* No new data yet */
        return 1;
    }

    /* Read distance (16-bit, big-endian) */
    if (read_reg16(VL53L1X_REG_RESULT_DISTANCE, &distance_raw) != 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }

    /* Convert to centimetres (1 LSB = 0.1 cm) */
    *distance_cm = (float)distance_raw * 0.1f;

    /* Clear interrupt to allow next measurement */
    if (write_reg16(VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt.\n");
    }

    return 0;
}

static void control_gate(float distance_cm) {
    int current_state = gpioRead(GATE_GPIO);
    int new_state = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;

    if (new_state != current_state) {
        if (gpioWrite(GATE_GPIO, new_state) != 0) {
            fprintf(stderr, "Error: Failed to write to GPIO24.\n");
        } else {
            printf("Gate %s\n", new_state ? "OPEN" : "CLOSED");
        }
    }
}

static void log_event(const char *event, float distance_cm, int gate_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s - Distance: %.2f cm, Gate: %s\n",
                timestamp, event, distance_cm, gate_state ? "OPEN" : "CLOSED");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float distance_cm = 0.0f;
    int gate_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); /* Ensure gate starts closed */

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int ret = read_distance_cm(&distance_cm);
        if (ret == 0) {
            control_gate(distance_cm);
            log_event("Distance measurement", distance_cm, gate_state);
        } else if (ret < 0) {
            fprintf(stderr, "Error: I2C read failed.\n");
            log_event("I2C read error", -1.0f, gate_state);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

