#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <pthread.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x27
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"
#define PROXIMITY_REG 0x00
#define THRESHOLD_REG 0x01
#define INTERRUPT_ENABLE_REG 0x02
#define INTERRUPT_STATUS_REG 0x03
#define PROXIMITY_DATA_REG 0x04
#define PROXIMITY_DATA_LEN 2
#define I2C_BUS 1

static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_proximity_event(int proximity, int threshold) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s, Proximity: %d, Threshold: %d, Status: ", timestamp, proximity, threshold);
        if (proximity > threshold) {
            fprintf(log_file, "ALERT\n");
        } else {
            fprintf(log_file, "SAFE\n");
        }
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

static int write_reg(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, pigpio_error(result));
        return -1;
    }
    return 0;
}

static int read_reg(int handle, int reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, pigpio_error(result));
        return -1;
    }
    return result;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n", I2C_BUS, i2c_address, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", GPIO_PIN);
        return -1;
    }
    if (gpioSetAlertFunc(GPIO_PIN, alert_callback) != 0) {
        fprintf(stderr, "Error setting alert callback on GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

static void alert_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level == 1) {
        int proximity = read_reg(i2c_handle, PROXIMITY_REG);
        if (proximity < 0) {
            fprintf(stderr, "Error reading proximity data\n");
            return;
        }
        log_proximity_event(proximity, threshold);
    }
}

static int init_sensor(void) {
    if (write_reg(i2c_handle, THRESHOLD_REG, threshold) < 0) {
        fprintf(stderr, "Error setting threshold\n");
        return -1;
    }
    if (write_reg(i2c_handle, INTERRUPT_ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error enabling interrupt\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = (int)strtol(optarg, NULL, 0);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity monitoring started. Threshold: %d, I2C addr: 0x%02X\n", threshold, i2c_address);

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

