        fprintf(stderr, "Error setting alert callback on GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

static void alert_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level == 1) {
        int proximity = read_reg(i2c_handle, PROXIMITY_REG);
        if (proximity < 0) {
            fprintf(stderr, "Error reading proximity data\n");
            return;
        }
        log_proximity_event(proximity, threshold);
    }
}

static int init_sensor(void) {
    if (write_reg(i2c_handle, THRESHOLD_REG, threshold) < 0) {
        fprintf(stderr, "Error setting threshold\n");
        return -1;
    }
    if (write_reg(i2c_handle, INTERRUPT_ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error enabling interrupt\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = (int)strtol(optarg, NULL, 0);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity monitoring started. Threshold: %d, I2C addr: 0x%02X\n", threshold, i2c_address);

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

