/*
 * theremin_hc_sr04.c — Raspberry Pi Zero W
 *
 * Reads an HC-SR04 ultrasonic sensor and drives an 8-ohm speaker as a
 * theremin-like instrument.  The PWM0 hardware-timed PWM on GPIO18 (BCM)
 * generates audio tones whose pitch is mapped to the measured distance.
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5 V (pin 2)
 *   HC-SR04 GND  -> GND  (pin 6)
 *   HC-SR04 TRIG -> GPIO23 (pin 16, BCM 23)
 *   HC-SR04 ECHO -> GPIO24 (pin 17, BCM 24)
 *   Speaker      -> GPIO18 (pin 12, BCM 18)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin_hc_sr04 theremin_hc_sr04.c \
 *       -lpigpio -lrt
 *
 * Run:
 *   sudo ./theremin_hc_sr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIG_PIN      23
#define ECHO_PIN      24
#define PWM_PIN       18

/* ---- Sensor / timing constants ---- */
#define TRIG_PULSE_US  10          /* HC-SR04 trigger pulse width            */
#define ECHO_TIMEOUT_US 200000     /* 200 ms echo timeout (max round-trip)  */
#define MIN_DISTANCE_CM 2.0f       /* HC-SR04 minimum measurable distance    */
#define MAX_DISTANCE_CM 200.0f     /* HC-SR04 maximum measurable distance    */
#define MIN_FREQUENCY_HZ 200.0f    /* Minimum frequency (2 cm)              */
#define MAX_FREQUENCY_HZ 2000.0f   /* Maximum frequency (200 cm)             */
#define PWM_DUTY_50     50          /* 50% duty cycle for PWM                */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_ready = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*
 * Read distance from the HC-SR04.
 *
 * Returns:
 *   >= 0  : distance in cm
 *  -1.0   : timeout (no echo received within ECHO_TIMEOUT_US)
 *  -2.0  : out of range (distance < MIN_DISTANCE_CM or > MAX_DISTANCE_CM)
 */
static float read_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIG_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIG_PULSE_US);
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout (no object detected)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout (stuck high)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff * 0.0343f; /* speed of sound = 343 m/s */

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Error: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -2.0f;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
static float calculate_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM)
        return MIN_FREQUENCY_HZ;
    if (distance > MAX_DISTANCE_CM)
        return MAX_FREQUENCY_HZ;

    /* Logarithmic mapping: 2 cm -> 200 Hz, 200 cm -> 2000 Hz */
    return MIN_FREQUENCY_HZ +
           (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) *
           (1.0f - (distance - MIN_DISTANCE_CM) /
                   (MAX_DISTANCE_CM - MIN_DISTANCE_CM));
}

/* ------------------------------------------------------------------ */
static void set_pwm_frequency(int frequency_hz)
{
    if (frequency_hz < 0.0f)
        frequency_hz = 0.0f;
    if (frequency_hz > 10000.0f)
        frequency_hz = 10000.0f;

    int pwm_freq = (int)(frequency_hz + 0.5f);
    if (pwm_freq < 0)
        pwm_freq = 0;
    if (pwm_freq > 10000)
        pwm_freq = 10000;

    if (gpioSetPWMfrequency(PWM_PIN, pwm_freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", pwm_freq);
        return;
    }
    if (gpioPWM(PWM_PIN, PWM_DUTY_50) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", PWM_PIN, PWM_DUTY_50);
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_pigpio_ready) {
        gpioPWM(PWM_PIN, 0);
        gpioWrite(TRIG_PIN, 0);
        gpioTerminate();
        g_pigpio_ready = 0;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_ready = 1;

    /* Configure GPIO modes */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIG, OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM, OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) initial low failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with PWM off */
    if (gpioPWM(PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM(PWM, 0) initial failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 Theremin running.  Press Ctrl+C to exit.\n");
    printf("TRIG=GPIO%d  ECHO=GPIO%d  PWM=GPIO%d  (50%% duty cycle)\n",
           TRIG_PIN, ECHO_PIN, PWM_PIN);

    while (g_running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            /* Timeout or out-of-range — preserve previous frequency */
            set_pwm_frequency(g_last_frequency);
        } else {
            float frequency = calculate_frequency(distance);
            set_pwm_frequency(frequency);
            g_last_frequency = frequency;
        }

        gpioDelay(50000); /* 50 ms loop delay */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

