code:
/*
 * Theremin-like instrument using an HC-SR04 ultrasonic sensor and a piezo buzzer.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: HC-SR04 (HC = 40 kHz, 20 cm max range)
 * Buzzer:  piezo buzzer on GPIO18 (BCM) via driver library PWM0
 *          Trigger: GPIO23 (BCM), Echo: GPIO24 (BCM), pull-down
 *
 * Build:  gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define MIN_DISTANCE_CM  5.0f
#define MAX_DISTANCE_CM  50.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define ECHO_TIMEOUT_US  100000   /* 100 ms max echo wait */
#define LOOP_DELAY_US    10000    /* 10 ms between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Measure distance in centimetres from the HC-SR04.                 */
/* Returns -1.0 on timeout or sensor error.                          */
/* ------------------------------------------------------------------ */
static float measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }
    gpioDelay(2);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0f;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    float distance = (float)pulse_width / 58.0f;  /* 34 312 58 = 34 000 us / 58 = 60 cm */
    return distance;
}

/* ------------------------------------------------------------------ */
/* Map distance (cm) to frequency (Hz).                               */
/* ------------------------------------------------------------------ */
static int distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    return (int)(MIN_FREQUENCY_HZ +
                 (distance - MIN_DISTANCE_CM) *
                 (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM));
}

/* ------------------------------------------------------------------ */
/* Generate a continuous tone on the buzzer using pigpio's frequency   */
/* API.  Note: pigpio's PWM0 is not directly usable for continuous     */
/* tones; this uses the frequency-mapped PWM channel 0.                 */
/* ------------------------------------------------------------------ */
static void generate_tone(int frequency)
{
    if (frequency <= 0) {
        gpioPWM(BUZZER_PIN, 0);
        return;
    }

    /* Map frequency to duty cycle (50 % of 500 Hz range) */
    int duty = (frequency * 500) / 100;
    if (duty > 500) duty = 500;
    if (duty < 0)   duty = 0;

    gpioPWM(BUZZER_PIN, duty);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — stop PWM and terminate pigpio.                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

