        return -1.0f;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    start_tick = gpioTick();
    do {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read echo pin\n");
            return -1.0f;
        }
        if (level == 1)
            break;
    } while ((gpioTick() - start_tick) < TIMEOUT_US);
    if (level != 1) {
        fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
        return -1.0f;
