        return -1.0f;
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * 0.0343f / 2.0f; /* cm */

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0f;
    }
    return distance;
