#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"
#define MAX_DISTANCE 5000
#define MIN_DISTANCE 200
#define READ_DELAY_US 100000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    /*
     * ICU-20201 SPI command sequence (32-bit, MSB first):
     *   Byte 0: 0x01  (Start bit)
     *   Byte 1: 0x80  (Read mode, 1 byte)
     *   Byte 2: 0x00  (Dummy, clocks out data)
     *   Byte 3: 0x00  (Dummy, clocks out data)
     *   Byte 4: 0x00  (Dummy, clocks out data)
     *   Byte 5: 0x00  (Dummy, clocks out data)
     *   Byte 6: 0x00  (Dummy, clocks out data)
     *   Byte 7: 0x00  (Dummy, clocks out data)
     *   Byte 8: 0x00  (Dummy, clocks out data)
     *   Byte 9: 0x00  (Dummy, clocks out data)
     *   Byte 10: 0x00  (Dummy, clocks out data)
     *   Byte 11: 0x00  (Dummy, clocks out data)
     *   Byte 12: 0x00  (Dummy, clocks out data)
     *   Byte 13: 0x00  (Dummy, clocks out data)
     *   Byte 14: 0x00  (Dummy, clocks out data)
     *   Byte 15: 0x00  (Dummy, clocks out data)
     *   Byte 16: 0x00  (Dummy, clocks out data)
     *   Byte 17: 0x00  (Dummy, clocks out data)
     *   Byte 18: 0x00  (Dummy, clocks out data)
     *   Byte 19: 0x00  (Dummy, clocks out data)
     *   Byte 20: 0x00  (Dummy, clocks out data)
     *   Byte 21: 0x00  (Dummy, clocks out data)
     *   Byte 22: 0x00  (Dummy, clocks out data)
     *   Byte 23: 0x00  (Dummy, clocks out data)
     *   Byte 24: 0x00  (Dummy, clocks out data)
     *   Byte 25: 0x00  (Dummy, clocks out data)
     *   Byte 26: 0x00  (Dummy, clocks out data)
     *   Byte 27: 0x00  (Dummy, clocks out data)
     *   Byte 28: 0x00  (Dummy, clocks out data)
     *   Byte 29: 0x00  (Dummy, clocks out data)
     *   Byte 30: 0x00  (Dummy, clocks out data)
     *   Byte 31: 0x00  (Dummy, clocks out data)
     *
     * The ICU-20201 returns a 16-bit distance value in the upper 12 bits of
     * the 32-bit response.  The lower 10 bits are reserved and are not
     * transmitted back in the response.
     */
    unsigned char tx_buf[32];
    unsigned char rx_buf[32];
    memset(tx_buf, 0x01, 1);
    memset(rx_buf, 0x00, 31);
    memset(rx_buf + 1, 0x80, 1);
    memset(rx_buf + 2, 0x00, 28);
    memset(rx_buf + 30, 0x00, 2);
    memset(rx_buf + 29, 0x00, 1);
    memset(rx_buf + 28, 0x00, 1);
    memset(rx_buf + 27, 0x00, 1);
    memset(rx_buf + 26, 0x00, 1);
    memset(rx_buf + 25, 0x00, 1);
    memset(rx_buf + 24, 0x00, 1);
    memset(rx_buf + 23, 0x00, 1);
    memset(rx_buf + 22, 0x00, 1);
    memset(rx_buf + 21, 0x00, 1);
    memset(rx_buf + 20, 0x00, 1);
    memset(rx_buf + 19, 0x00, 1);
    memset(rx_buf + 18, 0x00, 1);
    memset(rx_buf + 17, 0x00, 1);
    memset(rx_buf + 16, 0x00, 1);
    memset(rx_buf + 15, 0x00, 1);
    memset(rx_buf + 14, 0x00, 1);
    memset(rx_buf + 13, 0x00, 1);
    memset(rx_buf + 12, 0x00, 1);
    memset(rx_buf + 11, 0x00, 1);
    memset(rx_buf + 10, 0x00, 1);
    memset(rx_buf + 9, 0x00, 1);
    memset(rx_buf + 8, 0x00, 1);
    memset(rx_buf + 7, 0x00, 1);
    memset(rx_buf + 6, 0x00, 1);
    memset(rx_buf + 5, 0x00, 1);
    memset(rx_buf + 4, 0x00, 1);
    memset(rx_buf + 3, 0x00, 1);
    memset(rx_buf + 2, 0x00, 1);
    memset(rx_buf + 1, 0x00, 1);
    memset(rx_buf, 0x00, 31);

    if (spiXfer(spi_handle, tx_buf, rx_buf, 32) != 32) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    /*
     * The ICU-20201 returns a 16-bit distance value in the upper 12 bits of
     * the 32-bit response.  The lower 10 bits are reserved and are not
     * transmitted back in the response.
     */
    int distance = ((rx_buf[2] & 0x0F) << 8) | rx_buf[3];
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: Distance out of range: %d mm\n", distance);
        return -1;
    }
    return 0;
}

static int read_distance(void) {
    if (init_sensor() != 0) {
        return -1;
    }
    return 0;
}

static int log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set CS pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(CS_PIN, 1);

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

