#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* Si1182-A-GM I2C address (7-bit) */
#define SI1182_I2C_ADDR 0x49

/* Si1182-A-GM register addresses */
#define SI1182_REG_PART_ID      0x00
#define SI1182_REG_HW_KEY       0x07
#define SI1182_REG_MEAS_RATE0   0x08
#define SI1182_REG_MEAS_RATE1   0x09
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_ALS_VIS_DATA1 0x23
#define SI1182_REG_PS1_DATA0    0x24
#define SI1182_REG_PS1_DATA1    0x25

/* Expected part ID for Si1182-A-GM */
#define SI1182_PART_ID_EXPECTED 0x82

/* Measurement rate: 0x00 = 100ms, 0x01 = 250ms, 0x02 = 500ms, 0x03 = 1s */
#define SI1182_MEAS_RATE_100MS 0x00
#define SI1182_MEAS_RATE_250MS 0x01
#define SI1182_MEAS_RATE_500MS 0x02
#define SI1182_MEAS_RATE_1S     0x03

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_si1182(int fd)
{
    uint8_t part_id = 0;

    /* Read part ID to verify sensor is present */
    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read Si1182 part ID (sensor absent or bus error).\n");
        return -1;
    }

    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected part ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    /* Write HW_KEY (0x07) to enable the device */
    if (i2c_write_reg8(fd, SI1182_REG_HW_KEY, 0x00) < 0)
        return -1;

    /* Set measurement rate to 100 ms */
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE0, SI1182_MEAS_RATE_100MS) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE1, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read sensor data                                                    */
/* ------------------------------------------------------------------ */
static int read_si1182_data(int fd, uint16_t *lux, uint16_t *prox)
{
    uint8_t vis_lo = 0, vis_hi = 0, ps1_lo = 0, ps1_hi = 0;

    if (i2c_read_reg8(fd, SI1182_REG_ALS_VIS_DATA0, &vis_lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, SI1182_REG_ALS_VIS_DATA1, &vis_hi) < 0)
        return -1;
    if (i2c_read_reg8(fd, SI1182_REG_PS1_DATA0,  &ps1_lo)  < 0)
        return -1;
    if (i2c_read_reg8(fd, SI1182_REG_PS1_DATA1,  &ps1_hi)  < 0)
        return -1;

    *lux = (uint16_t)((vis_hi << 8) | vis_lo);
    *prox = (uint16_t)((ps1_hi << 8) | ps1_lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(buf + strlen(buf), len - strlen(buf), ".%03ld",
             ts.tv_nsec / 1000000);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const char *ts, uint16_t lux, uint16_t prox)
{
    fprintf(fp, "%s,%u,%u\n", ts, lux, prox);
    fflush(fp);
    printf("%s,%u,%u\n", ts, lux, prox);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    char ts[32];
    uint16_t lux = 0, prox = 0;

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_si1182(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,lux,proximity\n");
        fflush(g_log_fp);
    }

    printf("Si1182 initialized. Logging to %s every 100 ms. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        if (read_si1182_data(g_i2c_fd, &lux, &prox) == 0) {
            get_timestamp(ts, sizeof(ts));
            log_data(g_log_fp, ts, lux, prox);
        } else {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

