#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define DISTANCE_THRESHOLD_CM 20.0
#define TRIGGER_PULSE_US       10
#define SAMPLE_INTERVAL_S      1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * pigpio callback: fires on every edge of ECHO_PIN.
 * pigpio guarantees the callback runs in a dedicated thread, so we
 * use a simple timestamp counter and serialise reads/writes.
 */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_seen  = 0;

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_seen  = 0;
    } else if (level == 0 && g_start_tick != 0) {
        g_end_tick = tick;
        g_echo_seen = 1;
    }
}

static double measure_distance(void) {
    g_echo_seen = 0;
    g_start_tick = 0;
    g_end_tick   = 0;

    /* Issue 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge */
    uint32_t waited = 0;
    while (!g_echo_seen && running) {
        if (g_start_tick != 0) {
            waited += 1;
            if (waited >= 1000) { /* 1 ms timeout */
                fprintf(stderr, "Error: echo start timeout\n");
                return -1.0;
            }
        }
        gpioDelay(1);
    }
    if (!running) return -1.0;

    /* Wait for echo falling edge */
    waited = 0;
    while (!g_echo_seen && running) {
        if (g_end_tick != 0) {
            waited += 1;
            if (waited >= 1000) { /* 1 ms timeout */
                fprintf(stderr, "Error: echo end timeout\n");
                return -1.0;
            }
        }
        gpioDelay(1);
    }
    if (!running) return -1.0;

    uint32_t pulse_us = g_end_tick - g_start_tick;
    /* distance = (pulse_us * speed_of_sound) / 2 */
    return (double)pulse_us * 0.0343 / 2.0;
}

int main(void) {
    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(BUZZER, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register echo callback */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");
    printf("Threshold: %.1f cm | Sample interval: %d s\n",
           DISTANCE_THRESHOLD_CM, SAMPLE_INTERVAL_S);

    while (running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: measurement failed, skipping cycle\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < DISTANCE_THRESHOLD_CM) {
                if (gpioWrite(BUZZER_PIN, 1) < 0) {
                    fprintf(stderr, "Error: gpioWrite(BUZZER, 1) failed\n");
                }
            } else {
                if (gpioWrite(BUZZER_PIN, 0) < 0) {
                    fprintf(stderr, "Error: gpioWrite(BUZZER, 0) failed\n");
                }
            }
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown */
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

