/*
 * Parking Assist System for Raspberry Pi Zero W
 * Sensor: HC-SR04 ultrasonic (trigger=GPIO4, echo=GPIO17)
 * Motor: SG90 servo (PWM=GPIO18)
 *
 * Build: gcc -O2 -Wall -o parking_assist parking_assist.c -lrt -lpigpio -lrt
 * Run:   sudo ./parking_assist
 */
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      4
#define ECHO_PIN         17
#define SERVO_PIN        18

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MAX_DISTANCE_CM         400.0
#define MIN_DISTANCE_CM         2.0
#define SERVO_MIN_US            500
#define SERVO_MAX_US            2500
#define SERVO_NEUTRAL_US        1500
#define LOOP_DELAY_US           100000
#define ECHO_TIMEOUT_US         30000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm using the HC-SR04.
 * Returns -1.0 on timeout or sensor error.
 */
static double measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }

    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t deadline  = gpioTick() + ECHO_TIMEOUT_US;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double pulse_us = (double)(end_tick - start_tick);
    double distance = (pulse_us * SPEED_OF_SOUND_CM_PER_S) / 2.0 / 1000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance);
        return -1.0;
    }
    return distance;
}

static int set_servo_angle(int angle)
{
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_us = SERVO_MIN_US +
                   (int)((double)angle / 180.0 * (double)(SERVO_MAX_US - SERVO_MIN_US));

    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d us\n", pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Error: sensor read failed, retrying...\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle = (int)((distance / MAX_DISTANCE_CM) * 180.0);
        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Error: servo set failed\n");
        }

        printf("Distance: %.2f cm  |  Servo: %d degrees\n", distance, angle);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

