/*
 * VL53L1X time-of-flight gate controller for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Servo gate -> GPIO18 (BCM, hardware PWM-capable) via appropriate driver
 *
 * Build:
 *   gcc -O2 -Wall -o gate_controller gate_controller.c -lpigpio -lrt
 *   sudo ./gate_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L1X constants (verified against ST datasheet) ---- */
#define VL53L1X_DEFAULT_ADDR 0x49
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD1 0x008A

#define EXPECTED_MODEL_ID 0xEA

/* ---- GPIO constants ---- */
#define SERVO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000000

/* ---- Application constants ---- */
#define LOG_FILE "gate_log.txt"
#define DISTANCE_THRESHOLD_OPEN 250
#define DISTANCE_THRESHOLD_CLOSE 200
#define OPEN_PULSE_WIDTH_US 1000
#define CLOSE_PULSE_WIDTH_US 2000
#define HYSTERESIS_US 10000
#define POLL_DELAY_US 100000

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;

    if (i2cReadDevice(handle, (char *)value, 1) != 1)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X initialization                                               */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    if (i2c_read_reg8(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        return -1;
    }

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

