     * Timing budget: 100 ms (0x0014) for ranging.
     * The default timing budget is 0x0014, which is the minimum.
     */
    if (i2c_write_reg8(handle, 0x0014, 0x0014) < 0) {
        fprintf(stderr, "Error: failed to set timing budget.\n");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance (mm) from VL53L1X                                       */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t lo = 0, hi = 0;

    if (i2c_read_reg8(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &lo) < 0)
        return -1;
    if (i2c_read_reg8(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD1, &hi) < 0)
        return -1;

    *distance = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Servo control with hysteresis                                          */
/* ------------------------------------------------------------------ */
static void set_servo_pulse(int gpio, int open_or_close, int *pulse_width)
{
    if (open_or_close == 1) {
        *pulse_width = OPEN_PULSE_WIDTH_US;
    } else if (open_or_close == 0) {
        *pulse_width = CLOSE_PULSE_WIDTH_US;
    } else {
        *pulse_width = *pulse_width; /* no change */
    }

    if (gpioPWM(gpio, *pulse_width) < 0) {
        fprintf(stderr, "Warning: gpioPWM failed for GPIO %d.\n", gpio);
    }
}

/* ------------------------------------------------------------------ */
/* Log gate events                                                      */
/* ------------------------------------------------------------------ */
static void log_gate_event(int open_or_close)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s - Gate %s\n", timestamp, open_or_close ? "OPENED" : "CLOSED");
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int distance;
    int pulse_width = 0;
    int open_or_close = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VL53L1X default address */
    g_i2c_handle = i2cOpen(1, VL53L1X_DEFAULT_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure servo pin for hardware PWM */
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_PIN, PWM_RANGE);

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed.\n");
    }

    printf("Gate controller started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (vl53l1x_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "Error: I2C read failed.\n");
            /* Brief pause before retrying to avoid log flooding */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Hysteresis gate control */
        if (distance > DISTANCE_THRESHOLD_OPEN && open_or_close == 0) {
            set_servo_pulse(SERVO_PIN, 1, &pulse_width);
            open_or_close = 1;
            pulse_width = OPEN_PULSE_WIDTH_US;
        } else if (distance < DISTANCE_THRESHOLD_CLOSE && open_or_close == 1) {
            set_servo_pulse(SERVO_PIN, 0, &pulse_width);
            open_or_close = 0;
            pulse_width = CLOSE_PULSE_WIDTH_US;
        }

        /* Smooth transition between pulse widths */
        if (open_or_close) {
            pulse_width = (pulse_width + HYSTERESIS_US) % PWM_RANGE;
        } else {
            pulse_width = (pulse_width - HYSTERESIS_US + PWM_RANGE) % PWM_RANGE;
        }

        log_gate_event(open_or_close);
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

