    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin %d as output.\n", SERVO_PIN);
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        return -1;
    }
    if (gpioWrite(SERVO_PIN, SERVO_INIT_US) < 0) {
        fprintf(stderr, "Error: failed to initialise servo pin initial state.\n");
        return -1;
    }

    return 0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    trigger_sensor();

    start_tick = gpioTick();
    timeout_tick = start_tick;

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout_tick = start_tick;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double pulse_us = (double)(end_tick - start_tick);
    double distance = (pulse_us * SPEED_OF_SOUND_CM_PER_US) / 2.0;

    return distance;
}

static int map_distance_to_angle(double distance)
{
    if (distance < MIN_DISTANCE_CM) {
        return MIN_ANGLE_DEG;
    }
    if (distance > MAX_DISTANCE_CM) {
        return MAX_ANGLE_DEG;
    }

    double ratio = (distance - MIN_DISTANCE_CM) /
                   (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return (int)(MIN_ANGLE_DEG + ratio * (MAX_ANGLE_DEG - MIN_ANGLE_DEG));
}

static int set_servo_angle(int angle)
{
    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        fprintf(stderr, "Error: invalid servo angle %d (must be %d-%d).\n",
                angle, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        return -1;
    }

    int pulse_us = SERVO_MIN_US +
                   (int)((double)angle / (double)(MAX_ANGLE_DEG - MIN_ANGLE_DEG) *
                         (SERVO_MAX_US - SERVO_MIN_US));

    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d.\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    gpioServo(SERVO_PIN, SERVO_INIT_US);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: sensor timeout or read error.\n");
            distance = -1.0;
        }

        int angle = map_distance_to_angle(distance);

        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Warning: failed to set servo angle.\n");
        }

        printf("Distance: %.2f cm  ->  Angle: %d\n", distance, angle);

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

