#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_SCALE  0x1C
#define MPU6050_GYRO_SCALE   0x1B

#define ACCEL_SCALE_2G      0.000061f
#define GYRO_SCALE_250DPS   0.00875f

#define SAMPLE_PERIOD_US    100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register. Returns 0 on success.    */
static int mpu_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    return i2cWriteDevice(handle, buf, 2);
}

/* ------------------------------------------------------------------ */
/* Read N bytes starting at an 8-bit register. Returns 0 on success.  */
static int mpu_read_burst(int handle, uint8_t reg, uint8_t *dst, uint8_t len)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0)
        return -1;
    if (i2cReadDevice(handle, (char *)dst, len) != (int)len)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the MPU-6050 is present. Returns 0 on success, -1 on error. */
static int mpu_verify(int handle)
{
    int who = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPU-6050: standby, then configure accel/gyro.        */
static int mpu_init(int handle)
{
    /* Standby (clear SLEEP bit) */
    if (mpu_write_reg(handle, MPU6050_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000);  /* 100 ms settle */

    /* Accel config: +/- 2g, 16384 LSB/s */
    if (mpu_write_reg(handle, MPU6050_ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write ACCEL_CONFIG\n");
        return -1;
    }

    /* Gyro config: +/- 250 dps, 16384 LSB/s */
    if (mpu_write_reg(handle, MPU6050_GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG\n");
        return -1;
    }

    /* Scale factors */
    if (mpu_write_reg(handle, MPU6050_ACCEL_SCALE, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write ACCEL_SCALE\n");
        return -1;
    }
    if (mpu_write_reg(handle, MPU6050_GYRO_SCALE, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write GYRO_SCALE\n");
        return -1;
    }

    return 0;
