        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Init sensor --- */
    if (mpu_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 ready. Sampling every 100 ms. Press Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        int16_t ax, ay, az, temp, gx, gy, gz;

        if (mpu_read_data(g_i2c_handle, &ax, &ay, &az, &temp, &gx, &gy, &gz) == 0) {
