            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read temperature (°C) and humidity (%RH) from SHT40                 */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_sht40(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2];
    uint8_t buf[6];
    int rc;

    /* Send measurement command (big-endian, MSB first) */
    cmd[0] = (uint8_t)((CMD_MEASURE_HR >> 8) & 0xFF);
    cmd[1] = (uint8_t)(CMD_MEASURE_HR & 0xFF);

    rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (rc=%d)\n", rc);
        return -1;
    }

    /* Datasheet: conversion takes ~10 ms for high repeatability */
    gpioDelay(MEASURE_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    rc = i2cReadDevice(handle, (char *)buf, 6);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (rc=%d)\n", rc);
        return -1;
    }
    if (rc != 6) {
        fprintf(stderr, "[ERROR] Short read: got %d bytes, expected 6\n", rc);
        return -1;
    }

    /* Validate CRCs */
    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    /* Convert raw values */
    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float temperature, humidity;

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers -------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SHT40 reader started. Bus=1, Addr=0x%02X, Sample=%ds\n",
           SHT40_ADDR, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        if (read_sht40(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "[WARN] Read failed; re-opening I2C bus...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(1000000);  /* 1 s back-off before retry */
            if (g_i2c_handle < 0) {
                fprintf(stderr, "[FATAL] Re-open failed; exiting.\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

