/*
 * STS30-DIS Temperature Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   STS30-DIS SDA -> GPIO2 (I2C1 SDA)
 *   STS30-DIS SCL -> GPIO3 (I2C1 SCL)
 *   STS30-DIS VDD -> 3.3 V
 *   STS30-DIS GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sts30_logger sts30_logger.c
 *
 * Run:
 *   ./sts30_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS30_ADDR     0x30
#define LOG_FILE       "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/*
 * STS30-DIS commands (16-bit, big-endian on the wire).
 * The first byte is the command byte, the second byte is the
 * number of data bytes following the command.
 */
#define CMD_READ_TEMP_MSB  0x00
#define CMD_READ_TEMP_LSB  0x01
#define CMD_READ_TEMP_NO_MSB 0x02
#define CMD_READ_TEMP_NO_LSB 0x03
#define CMD_READ_TEMP_NO_MSB_LSB 0x04
#define CMD_READ_TEMP_NO_MSB_LSB_MSB 0x05
#define CMD_READ_TEMP_NO_MSB_LSB_LSB 0x06
#define CMD_READ_TEMP_NO_MSB_LSB_MSB_LSB 0x07
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB 0x08
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_MSB 0x09
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_MSB 0x0A
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_LSB_MSB 0x0B
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_LSB_LSB_MSB 0x0C
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_LSB_LSB_LSB_MSB 0x0D
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_LSB_LSB_LSB_LSB_MSB 0x0E
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_MSB 0x0F
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_MSB 0x10
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_MSB 0x11
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_MSB 0x12
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_MSB 0x13
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_MSB 0x14
#define CMD_READ_TEMP_NO_MSB_LSB_LSB_MSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_LSB_MSB 0x15

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening error log: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[timestamp error] %s\n", msg);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* STS30-DIS temperature read                                           */
/* ------------------------------------------------------------------ */
static int sts30_read_temperature(int fd, float *temperature)
{
    uint8_t cmd = CMD_READ_TEMP_MSB;
    uint8_t data[4];

    /*
     * The STS30-DIS returns 24-bit data in the MSB byte of the
     * response, followed by 8 LSB bytes.  The 24-bit value is
     * left-justified in 32 bits, so the actual temperature is
     * in the lower 24 bits.
     */
    if (i2c_write_cmd(fd, cmd) < 0) {
        log_error("I2C write failed (command byte)");
        return -1;
    }

    /*
     * The STS30-DIS has a 1 ms conversion time after the read
     * command.  We wait 2 ms to be safe.
     */
    usleep(2000);

    if (i2c_read_bytes(fd, data, 4) < 0) {
        log_error("I2C read failed (data bytes)");
        return -1;
    }

    uint32_t raw = ((uint32_t)data[0] << 16) |
                   ((uint32_t)data[1] << 8)  |
                   ((uint32_t)data[2]);

    /*
     * The 24-bit value is in the lower 24 bits of the 32-bit
     * result.  Shift right 8 to get the integer value, then
     * divide by 100 to get the temperature in degrees Celsius.
     */
    int32_t temp_int = (int32_t)raw >> 8;
    *temperature = (float)temp_int / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    /* Acquire the STS30-DIS device */
    if (ioctl(g_i2c_fd, I2C_SLAVE, STS30_ADDR) < 0) {
        log_error("Failed to acquire I2C bus address");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /*
     * Verify the sensor is present by reading the device ID
     * register (0x0000).  The STS30-DIS returns 0x0000 on
     * success.
     */
    uint8_t id_buf[2];
    if (i2c_read_bytes(g_i2c_fd, id_buf, 2) < 0) {
        log_error("STS30-DIS not detected on I2C bus");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /*
     * The STS30-DIS device ID is 0x0000.  If the sensor is
     * absent or the bus is not connected, the read will fail.
     */
    if (id_buf[0] != 0x00 || id_buf[1] != 0x00) {
        log_error("STS30-DIS device ID mismatch (0x0000 expected)");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("STS30-DIS detected on %s (addr 0x%02X).\n", I2C_BUS, STS30_ADDR);
    printf("Logging to %s every %d seconds.  Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    /* Main sampling loop */
    while (g_running) {
        float temperature;
        if (sts30_read_temperature(g_i2c_fd, &temperature) == 0) {
            /*
             * Build a timestamped entry.  The STS30-DIS is
             * temperature-only, so the log entry is just the
             * temperature value.
             */
            time_t t = time(NULL);
            struct tm tm;
            if (localtime_r(&t, &tm)) {
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
                fprintf(LOG_FILE, "%s, %.2f\n", ts, temperature);
                printf("%s, %.2f\n", ts, temperature);
            } else {
                fprintf(LOG_FILE, "[timestamp error], %.2f\n", temperature);
                printf("[timestamp error], %.2f\n", temperature);
            }
            fflush(LOG_FILE);
        } else {
            log_error("STS30-DIS read failed; skipping sample");
        }

        /*
         * Sleep in 1-second increments so that SIGINT is
         * detected promptly.  If sleep returns early due to
         * a signal, the remaining time is slept.
         */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

