#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x39
#define LOG_FILE "pressure_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MEAS_DELAY_US 1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_sdp810(void) {
    uint8_t cmd[2] = {0x2E, 0x00};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write init command to SDP810: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_sdp810(float *pressure, float *temperature) {
    uint8_t cmd[2] = {0x36, 0x00};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send measurement command to SDP810: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    uint8_t buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9-byte data frame from SDP810: %s\n", strerror(errno));
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2] ||
        crc8(&buf[3], 2) != buf[5] ||
        crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on SDP810 data frame\n");
        return -1;
    }

    int16_t dp_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t temp_raw = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t dp_sf = (int16_t)((buf[6] << 8) | buf[7]);

    if (dp_sf == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0) from SDP810\n");
        return -1;
    }

    *pressure = (float)dp_raw / (float)dp_sf;
    *temperature = (float)temp_raw / 100.0f;
    return 0;
}

static int log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, SDP810_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_sdp810() != 0) {
        fprintf(stderr, "Error: SDP810 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SDP810 initialized. Logging to %s every 1 second. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        float pressure, temperature;
        if (read_sdp810(&pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            } else {
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, will retry next cycle\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

