#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7015_ADDR 0x44
#define LOG_FILE "sensor_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_TIMEOUT_MS 20

/* Si7015 command bits: No Hold Master mode, temperature (0x00) or humidity (0x01) */
#define SI7015_CMD_TEMP_NOHOLD 0x00
#define SI7015_CMD_HUM_NOHOLD 0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n",
                I2C_BUS, SI7015_ADDR, g_i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_si7015(uint8_t cmd, uint16_t *raw_out) {
    char buf[2];

    if (i2cWriteByte(g_i2c_handle, cmd) < 0) {
        fprintf(stderr, "Error: I2C write command 0x%02X failed (pigpio error %d).\n", cmd, g_i2c_handle);
        return -1;
    }

    /* Wait for the measurement to be ready (No Hold Master mode: ~5.5 ms typ, ~20 ms max) */
    int elapsed = 0;
    while (elapsed < MEASUREMENT_TIMEOUT_MS) {
        int bytes = i2cReadDevice(g_i2c_handle, buf, 2);
        if (bytes == 2) {
            *raw_out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        gpioDelay(1000); /* 1 ms */
        elapsed++;
    }

    fprintf(stderr, "Error: Measurement timeout for command 0x%02X (pigpio error %d).\n", cmd, g_i2c_handle);
    return -1;
}

static int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
    }

    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw_temp = 0, raw_hum = 0;
        float temperature = 0.0f, humidity = 0.0f;
        int temp_ok = 0, hum_ok = 0;

        if (read_si7015(SI7015_CMD_TEMP_NOHOLD, &raw_temp) == 0) {
            temperature = (float)raw_temp / 16383.0f * 165.0f - 40.0f;
            temp_ok = 1;
        }

        if (read_si7015(SI7015_CMD_HUM_NOHOLD, &raw_hum) == 0) {
            humidity = (float)raw_hum / 16383.0f * 100.0f;
            hum_ok = 1;
        }

        if (temp_ok && hum_ok) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: Logging failed for this sample.\n");
            }
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Warning: Sensor read failed for this sample.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

