    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    printf("SDP800 sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure, temperature;
        if (read_sdp800(fd, &pressure, &temperature) == 0) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

