#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STS30_ADDR 0x30
#define MEASUREMENT_CMD_HIGH_REP 0x3400
#define CONVERSION_DELAY_US 15000
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;
static FILE *error_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", STS30_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    uint8_t cmd[2] = { (MEASUREMENT_CMD_HIGH_REP >> 8) & 0xFF, MEASUREMENT_CMD_HIGH_REP & 0xFF };
    uint8_t buf[3];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(error_fp, "%ld: I2C write failed\n", time(NULL));
        fflush(error_fp);
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        fprintf(error_fp, "%ld: I2C read failed\n", time(NULL));
        fflush(error_fp);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(error_fp, "%ld: CRC mismatch on temperature data\n", time(NULL));
        fflush(error_fp);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temperature = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static int log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(error_fp, "%ld: localtime_r failed\n", time(NULL));
        fflush(error_fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(log_fp, "%s, %.2f\n", timestamp, temperature) < 0) {
        fprintf(error_fp, "%ld: Failed to write to log file\n", time(NULL));
        fflush(error_fp);
        return -1;
    }
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (error_fp) {
        fclose(error_fp);
        error_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    error_fp = fopen(ERROR_LOG_FILE, "a");
    if (!error_fp) {
        perror("Failed to open error log file");
        cleanup();
        return 1;
    }

    printf("STS30-DIS temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        gpioDelay(5000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

