#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x24
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_DELAY_US 1000000  /* 1 second */

/* SDP800 continuous measurement command (16-bit, big-endian) */
#define SDP800_CMD_CONTINUOUS 0x0000

/* CRC-8 polynomial for Sensirion sensors: x^8 + x^5 + x^4 + 1 (0x31) */
#define CRC8_POLY 0x31

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no reflect */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Write a 16-bit command to the SDP800.
 * Returns 0 on success, -1 on error.
 */
static int sdp800_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

/*
 * Read exactly `len` bytes from the SDP800.
 * Returns 0 on success, -1 on error.
 */
static int sdp800_read(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            perror("I2C read failed");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/*
 * Trigger a continuous measurement and wait for the first conversion.
 * Returns 0 on success, -1 on error.
 */
static int sdp800_start_continuous(int fd)
{
    if (sdp800_write_cmd(fd, SDP800_CMD_CONTINUOUS) < 0)
        return -1;

    /* Datasheet: first measurement is available after ~1 ms */
    usleep(1000);
    return 0;
}

/*
 * Read and validate a 6-byte response frame.
 * Returns 0 on success, -1 on error.
 */
static int sdp800_read_response(int fd, float *pressure, float *temperature)
{
    uint8_t buf[6];

    if (sdp800_read(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* Validate CRCs */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    /* Raw values: big-endian, signed 16-bit */
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure;
    *temperature = (float)raw_temp;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus " I2C_BUS);
        return EXIT_FAILURE;
    }

    /* Acquire the SDP800 slave address */
    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    /* Start continuous measurement */
    if (sdp800_start_continuous(fd) < 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        goto cleanup;
    }

    /* Open log file */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        goto cleanup;
    }

    printf("SDP800 monitoring started. Logging to %s\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        float pressure, temperature;

        if (sdp800_read_response(fd, &pressure, &temperature) == 0) {
            log_data(fp, pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read error; continuing\n");
        }

        /* Sleep 1 second between samples */
        usleep(SAMPLE_DELAY_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL)
        fclose(fp);
    if (fd >= 0)
        close(fd);

    if (rc == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return rc;
}

