#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x2F
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_SEC 5
#define MEASUREMENT_PERIOD_SEC 1
#define MEASUREMENT_DELAY_SEC 1
#define MAX_RETRIES 3

/* SCD40 commands (16-bit, big-endian on the bus) */
#define CMD_START_PERIODIC_MEASUREMENT 0x0000
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0001
#define CMD_READ_MEASUREMENT_DATA 0x0002

/* Data block: 9 bytes: 6 data words + 3 CRC words */
#define DATA_BLOCK_LEN 9

/* CRC-8 parameters per SCD40 datasheet */
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion style)                                               */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLYNOMIAL);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the SCD40                                 */
/* ------------------------------------------------------------------ */
static int scd40_write_command(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X (rc=%d)\n",
                cmd, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the SCD40                             */
/* ------------------------------------------------------------------ */
static int scd40_read_data(int handle, uint8_t *buf, size_t len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadDevice failed (rc=%d)\n", rc);
        return -1;
    }
    if ((size_t)rc != len) {
        fprintf(stderr, "Error: short read (%d of %zu bytes)\n", rc, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement block and verify CRCs                    */
/* ------------------------------------------------------------------ */
static int scd40_read_measurement(int handle, uint16_t *co2,
                                  float *temperature, float *humidity)
{
    uint8_t data[DATA_BLOCK_LEN];
    int rc = scd40_read_data(handle, data, DATA_BLOCK_LEN);
    if (rc != 0)
        return -1;

    /* Verify CRC for each 2-byte word */
    for (int i = 0; i < 6; i++) {
        if (crc8(&data[i * 2], 2) != data[i * 2 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t temp_raw = ((uint16_t)data[2] << 8) | data[3];
    uint16_t hum_raw  = ((uint16_t)data[4] << 8) | data[5];

    *co2    = co2_raw;
    *temperature = (float)temp_raw / 100.0f;
    *humidity = (float)hum_raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a CSV line to the log file                                    */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t co2, float temperature, float humidity)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, co2, temperature, humidity) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd40_write_command(g_i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d) - check wiring/address\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    /* ---- start periodic measurement ---- */
    if (scd40_write_command(g_i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- wait for first measurement to be ready ---- */
    time_t start_time = time(NULL);
    if (start_time == (time_t)-1) {
        fprintf(stderr, "Error: time() failed in start_measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(stderr, "SCD40 started periodic measurement. Waiting %d s...\n",
            MEASUREMENT_PERIOD_SEC);
    sleep(MEASUREMENT_PERIOD_SEC);

    /* ---- main loop ---- */
    while (g_running) {
        uint16_t co2 = 0;
        float temperature = 0.0f;
        float humidity = 0.0f;
        int ready = 0;

        /* Poll data-ready flag (bit 0 of status word) */
        for (int i = 0; i < MAX_RETRIES && g_running; i++) {
            if (scd40_read_measurement(g_i2c_handle, &co2,
                                       &temperature, &humidity) == 0) {
                ready = 1;
                break;
            }
            if (i < MAX_RETRIES - 1) {
                gpioDelay(100000); /* 100 ms */
            }
        }

        if (!ready) {
            fprintf(stderr, "Warning: measurement not ready after %d retries\n",
                    MAX_RETRIES);
            gpioDelay(POLL_INTERVAL_SEC * 1000000);
            continue;
        }

        if (log_data(g_log_file, co2, temperature, humidity) != 0) {
            fprintf(stderr, "Warning: log write failed\n");
        }

        /* Sleep for the remainder of the poll interval */
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "Error: time() failed in main loop\n");
            break;
        }
        time_t elapsed = now - start_time;
        if (elapsed < 0) {
            /* Should not happen on a real clock, but handle gracefully */
            elapsed += 24 * 3600;
        }
        if (elapsed < POLL_INTERVAL_SEC) {
            gpioDelay(POLL_INTERVAL_SEC * 1000000);
        } else {
            /* Full interval elapsed - reset start time */
            start_time = now;
        }
    }

    /* ---- graceful shutdown ---- */
    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

