#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define POLL_INTERVAL_SEC 5
#define TIMEOUT_US 50000
#define TEMP_MIN -40.0f
#define TEMP_MAX 150.0f
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature from TMP05 via a busy-wait PWM-style measurement.
 * Returns 0 on success and stores temperature in *out_temp.
 * Returns -1 on timeout or read error.
 */
static int read_temperature(float *out_temp) {
    uint32_t start_tick, end_tick, elapsed;
    int level;

    /*
     * Wait for the sensor to drive the line low (start of a measurement).
     * gpioTick() returns microseconds since pigpio init.
     */
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            return -1;
        }
    }

    /*
     * Wait for the sensor to drive the line high (end of measurement).
     * gpioTick() returns microseconds since pigpio init.
     */
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            return -1;
        }
    }
    end_tick = gpioTick();

    /*
     * Compute high-pulse width in microseconds.
     * gpioTick() returns microseconds since pigpio init.
     */
    elapsed = end_tick - start_tick;

    /*
     * TMP05 PWM-style output: high pulse width is proportional to
     * temperature.  Convert to seconds and convert to Celsius.
     */
    float high_us = (float)elapsed;
    if (high_us == 0.0f) {
        return -1;
    }
    float temp_s = high_us / 1000000.0f;
    *out_temp = temp_s * 100.0f;
    return 0;
}

static void log_temperature(float temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (g_log_file) {
        fprintf(g_log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void log_malfunction(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (g_log_file) {
        fprintf(g_log_file, "%s, SENSOR MALFUNCTION\n", timestamp);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open. Malfunction logged to stderr.\n");
    }
}

int main(void) {
    float temperature;
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pin as input */
    gpioSetMode(GPIO_PIN, PI_INPUT);

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not register SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not register SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("TMP05 temperature logger started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        int rc = read_temperature(&temperature);

        if (rc == 0) {
            consecutive_errors = 0;
            log_temperature(temperature);

            if (temperature >= TEMP_MIN && temperature <= TEMP_MAX) {
                printf("Temperature: %.2f C\n", temperature);
            } else {
                fprintf(stderr, "Warning: Temperature %.2f C out of valid range [%.0f, %.0f].\n",
                        temperature, TEMP_MIN, TEMP_MAX);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error: Temperature read failed (code %d).\n", rc);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_malfunction();
                consecutive_errors = 0;
            }
        }

        /* Sleep for POLL_INTERVAL_SEC seconds, checking g_running every second */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

