#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x24
#define CSV_FILENAME "airflow.csv"
#define SAMPLE_INTERVAL_US 1000000
#define CONVERSION_TIME_US 45000

/* SDP810 continuous measurement command (16-bit, big-endian) */
#define SDP810_CONTINUOUS_CMD 0x0000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 calculation as used by Sensirion (poly 0x31, init 0xFF)      */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame from the SDP810                  */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = { (uint8_t)(SDP810_CONTINUOUS_CMD >> 8),
                       (uint8_t)(SDP810_CONTINUOUS_CMD & 0xFF) };
    uint8_t buf[9];
    int16_t raw_pressure, raw_temperature;
    int16_t scale_factor;
    int ret;

    /* Send continuous measurement command */
    ret = i2cWriteDevice(handle, (char *)cmd, 2);
    if (ret != 0) {
        fprintf(stderr, "I2C write failed (ret=%d)\n", ret);
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONVERSION_TIME_US);

    /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(2)+crc */
    ret = i2cReadDevice(handle, (char *)buf, 9);
    if (ret != 9) {
        fprintf(stderr, "I2C read failed (ret=%d, expected 9)\n", ret);
        return -1;
    }

    /* Validate CRCs for each 2-byte data word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Scale factor CRC mismatch\n");
        return -1;
    }

    /* Assemble raw values (big-endian) */
    raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    scale_factor    = (int16_t)((buf[6] << 8) | buf[7]);

    /* Convert to physical units (per SDP810 datasheet) */
    *pressure    = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one CSV row with a timestamp                                   */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    }
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    float pressure, temperature;
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the SDP810 address */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(CSV_FILENAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", CSV_FILENAME);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_pa,temperature_c\n");
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810 airflow monitor started. Logging to '%s'. Press Ctrl+C to stop.\n",
           CSV_FILENAME);

    /* Main sampling loop */
    while (g_running) {
        if (read_sdp810(g_i2c_handle, &pressure, &temperature) == 0) {
            log_data(g_log_file, pressure, temperature);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Sensor read error (consecutive=%d)\n",
                    consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors — aborting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

