/*
 * SHT35-DIS-B temperature/humidity logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   SHT35 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SHT35 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SHT35 VDD  -> 3.3 V
 *   SHT35 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht35_logger sht35_logger.c
 * Run:    ./sht35_logger   (requires rdev/i2c-dev access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT35_ADDR     0x10
#define LOG_FILE       "environment.csv"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MEAS_DELAY_US  15000      /* 15 ms measurement wait */

/* Single-shot, high repeatability, clock-stretching disabled */
#define CMD_MEAS_HIGHREP 0x2C

/* SHT35 single-shot result: T(°C) MSB, T(°C) LSB, T(°C) FFR,
 * RH(%%) MSB, RH(%%) LSB, RH(%%) FFR, CRC8 */
#define RESULT_LEN  6

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_write_cmd(0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "i2c_read_data: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "i2c_read_data: short read (%zd of %zu bytes)\n",
                n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a+");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }

    /* Check if file is empty so we can write a header */
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell(%s): %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (pos == 0) {
        if (ftruncate(fileno(fp), 0) == -1) {
            fprintf(stderr, "ftruncate(%s): %s\n", path, strerror(errno));
            fclose(fp);
            return -1;
        }
    }

    /* Write header if file is empty */
    if (pos == 0)
        fprintf(fp, "timestamp,temperature_c,humidity_rh\n");

    return 0;
}

static int log_write(const char *path, const char *ts, float temp, float rh)
{
    FILE *fp = fopen(path, "a+");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }

    /* Write header if file is empty */
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell(%s): %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (pos == 0) {
        if (ftruncate(fileno(fp), 0) == -1) {
            fprintf(stderr, "ftruncate(%s): %s\n", path, strerror(errno));
            fclose(fp);
            return -1;
        }
    }

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, rh);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                       */
/* ------------------------------------------------------------------ */
static int sht35_read(int fd, float *temp, float *rh)
{
    uint8_t data[RESULT_LEN];

    if (i2c_write_cmd(fd, CMD_MEAS_HIGHREP) != 0)
        return -1;

    usleep(MEAS_DELAY_US);

    if (i2c_read_data(fd, data, RESULT_LEN) != 0)
        return -1;

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh   = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Sensirion driver library may have a shutdown call here */
    /* For safety, we also close the I2C bus */
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the SHT35 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                SHT35_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install CSV header if file does not exist */
    if (log_open(LOG_FILE) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp = 0.0f, rh = 0.0f;

        if (sht35_read(g_i2c_fd, &temp, &rh) == 0) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

            if (log_write(LOG_FILE, ts, temp, rh) != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
            else
                printf("%s  T=%.2f C  RH=%.2f %%\n", ts, temp, rh);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

