#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_PERIOD_S 5

/* Si7021 commands */
#define CMD_RESET       0x00
#define CMD_MEASURE_T   0x11
#define CMD_MEASURE_RH  0x12

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as per Si7021 datasheet */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *out)
{
    uint8_t buf[3];

    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    /* Poll until data is ready or timeout */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        usleep(1000);
        if (i2c_read_bytes(fd, buf, 3) < 0)
            return -1;
        if (crc8(buf, 2) == buf[2])
            break;
        if (i == POLL_TIMEOUT_MS - 1) {
            fprintf(stderr, "Sensor timeout waiting for measurement\n");
            return -1;
        }
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out = raw;
    return 0;
}

static int read_temperature(int fd, float *temp_c)
{
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_T, &raw) < 0)
        return -1;
    *temp_c = (float)raw / 16.0f;
    return 0;
}

static int read_humidity(int fd, float *rh_pct)
{
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_RH, &raw) < 0)
        return -1;
    *rh_pct = (float)raw / 16383.0f;
    return 0;
}

static int log_data(float temp_c, float rh_pct)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
    fclose(fp);
    return 0;
}

static void log_error(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    } else {
        fprintf(fp, "ERROR,UNKNOWN\n");
    }
    fclose(fp);
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    /* Reset sensor to ensure a known state */
    if (i2c_write_cmd(g_i2c_fd, CMD_RESET) < 0) {
        fprintf(stderr, "Sensor reset failed; continuing anyway\n");
    }
    usleep(20000); /* 20 ms reset settling time */

    while (g_running) {
        float temp_c, rh_pct;

        if (read_temperature(g_i2c_fd, &temp_c) < 0) {
            fprintf(stderr, "Temperature read failed; resetting sensor\n");
            if (i2c_write_cmd(g_i2c_fd, CMD_RESET) < 0)
                fprintf(stderr, "Reset write failed\n");
            else
                usleep(20000);
            continue;
        }

        if (read_humidity(g_i2c_fd, &rh_pct) < 0) {
            fprintf(stderr, "Humidity read failed; resetting sensor\n");
            if (i2c_write_cmd(g_i2c_fd, CMD_RESET) < 0)
                fprintf(stderr, "Reset write failed\n");
            else
                usleep(20000);
            continue;
        }

        if (log_data(temp_c, rh_pct) < 0)
            fprintf(stderr, "Logging failed\n");

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, rh_pct);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    cleanup();
    return 0;
}

