/*
 * Raspberry Pi 3 Model B+ - Honeywell Zephyr HAFBLF0100A2AX5 differential pressure sensor
 *
 * Reads differential pressure over I2C, computes flow rate, and drives a PWM fan on GPIO18.
 * Logs pressure to flow_log.txt every 100 ms.
 *
 * Wiring:
 *   Sensor SDA -> GPIO2 (I2C bus 1)
 *   Sensor SCL -> GPIO3 (I2C bus 1)
 *   Fan PWM    -> GPIO18 (hardware PWM0)
 *
 * Build: gcc -O2 -Wall -o flow_monitor flow_monitor.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x49          /* HAFBLF0100A2AX5 default I2C address */
#define FAN_GPIO             18            /* BCM 18 - hardware PWM0 */
#define PWM_FREQUENCY        25000         /* 25 kHz */
#define PWM_RANGE            1024          /* 10-bit resolution */
#define SAMPLE_INTERVAL_US   100000        /* 100 ms */
#define LOG_FILE             "flow_log.txt"
#define MAX_CONSECUTIVE_ERRS 10

/* Honeywell HAFBLF0100A2AX5 differential pressure register (16-bit, big-endian) */
#define REG_PRESSURE_MSB     0x00
#define REG_PRESSURE_LSB     0x01

/* ----------------------------- Globals ----------------------------------- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize_i2c(void);
static int  read_pressure(float *pressure_out);
static float calculate_flow_rate(float pressure);
static void set_fan_speed(float flow_rate);
static void log_data(float pressure);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- Implementation ----------------------------- */

static int initialize_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_out)
{
    uint8_t buf[2];
    int rc;

    /* Read 2 bytes from the pressure register */
    rc = i2cReadI2CBlockData(i2c_handle, REG_PRESSURE_MSB, (char *)buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed (rc=%d): %s\n",
                rc, rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }

    /* Honeywell sensors send MSB first */
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];

    /* Convert to Pa (example conversion; consult datasheet for scaling) */
    *pressure_out = (float)raw * 0.001f;   /* 0.001 Pa per LSB */
    return 0;
}

static float calculate_flow_rate(float pressure)
{
    /*
     * Honeywell HAFBLF0100A2AX5 differential pressure output is
     * proportional to flow rate.  The exact transfer function is
     * proprietary, but a common linear approximation is:
     *
     *   flow_rate_Pa/s = slope * pressure_Pa + intercept
     *
     *  Slope and intercept are calibrated per application.  The
     *  following is a placeholder linear model.  Replace with the
     *  datasheet-derived transfer function for your specific sensor.
     */
    const float slope = 0.0001f;
    const float intercept = 0.0f;
    return slope * pressure + intercept;
}

static void set_fan_speed(float flow_rate)
{
    /*
     * Honeywell HAFBLF0100A2AX5 typically requires a PWM signal
     * with a duty cycle proportional to flow rate.  The exact
     * mapping depends on the specific drive circuit.  This
     * example maps a flow rate in Pa/s to a 0-1024 duty cycle
     * (10-bit resolution).
     */
    int duty_cycle = (int)(flow_rate * 1024.0f);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(FAN_GPIO, duty_cycle);
}

static void log_data(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(log_file, "%s,%.4f\n", ts, pressure) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush log failed\n");
    }
}

static void cleanup(void)
{
    /* Turn off the fan first for safety */
    gpioPWM(FAN_GPIO, 0);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("[ERROR] fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO for hardware PWM */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode failed for GPIO%d\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitoring started.  Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (!terminate) {
        float pressure;

        if (read_pressure(&pressure) == 0) {
            consecutive_errors = 0;
            log_data(pressure);
            set_fan_speed(calculate_flow_rate(pressure));
        } else {
            consecutive_errors++;
            fprintf(stderr, "[WARN] Pressure read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRS) {
                fprintf(stderr, "[ERROR] Too many consecutive I2C failures; aborting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

