#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

/* LPS33HW I2C address (SA0 tied to GND) */
#define LPS33HW_ADDR 0x19

/* LPS33HW register addresses */
#define LPS33HW_REG_PRESS_XL 0x00
#define LPS33HW_REG_PRESS_L  0x01
#define LPS33HW_REG_PRESS_H  0x02
#define LPS33HW_REG_TEMP_XL  0x03
#define LPS33HW_REG_TEMP_L  0x04
#define LPS33HW_REG_TEMP_H  0x05
#define LPS33HW_REG_CTRL_REG 0x2A
#define LPS33HW_REG_WHO_AM_I  0x0F

/* Expected WHO_AM_I value for LPS33HW */
#define LPS33HW_WHO_AM_I_VAL 0x33

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a timestamped message to stderr and the log file */
static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime_r(&now, NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "[%s] ERROR: %s (errno: %d - %s)\n",
            timestamp, message, errno, strerror(errno));

    if (log_file) {
        fprintf(log_file, "[%s] ERROR: %s (errno: %d - %s)\n",
                timestamp, message, errno, strerror(errno));
        fflush(log_file);
    }
}

/* Read a 16-bit little-endian word from an LPS33HW register */
static int read_word(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* Read pressure in hPa and temperature in °C from LPS33HW */
static int read_sensor_data(int handle, float *pressure, float *temperature) {
    int16_t raw_pressure, raw_temperature;

    if (read_word(handle, LPS33HW_REG_PRESS_XL, &raw_pressure) != 0) {
        log_error("Failed to read pressure data");
        return -1;
    }

    if (read_word(handle, LPS33HW_REG_TEMP_XL, &raw_temperature) != 0) {
        log_error("Failed to read temperature data");
        return -1;
    }

    /* LPS33HW pressure: 14-bit value in bits 15:4, left-justified in 16-bit field */
    uint16_t pressure_raw = (uint16_t)(raw_pressure << 4);
    /* LPS33HW temperature: 12-bit value in bits 15:4, left-justified in 16-bit field */
    uint16_t temp_raw = (uint16_t)(raw_temperature << 4);

    /* Convert raw 14-bit pressure to hPa */
    pressure_raw >>= 4;
    *pressure = (float)pressure_raw / 100.0f;

    /* Convert raw 12-bit temperature to °C */
    temp_raw >>= 4;
    *temperature = (float)temp_raw / 100.0f;

    return 0;
}

/* Cleanup all resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 (SDA/SCL on GPIO 2/3) */
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n",
                LPS33HW_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(i2c_handle, LPS33HW_REG_WHO_AM_I);
    if (who_am_i < 0) {
        log_error("Failed to read WHO_AM_I register");
        cleanup();
        return EXIT_FAILURE;
    }
    if (who_am_i != LPS33HW_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LPS33HW_WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure: standby mode, 100 Hz ODR, normal mode */
    if (i2cWriteByteData(i2c_handle, LPS33HW_REG_CTRL_REG, 0x00) != 0) {
        log_error("Failed to configure LPS33HW");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_error("Failed to register SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LPS33HW environmental data logger started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        float pressure, temperature;

        if (read_sensor_data(i2c_handle, &pressure, &temperature) == 0) {
            time_t now = time(NULL);
            struct tm *t = localtime_r(&now, NULL);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

            fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
                    timestamp, pressure, temperature);
            fflush(log_file);

            printf("%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
                   timestamp, pressure, temperature);
        } else {
            log_error("Sensor read failed; will retry next cycle");
        }

        sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

