/*
 * Raspberry Pi Zero W – STLM75 temperature monitor
 *
 * Reads temperature from an STLM75 on the I2C bus once per second,
 * stores each reading in a 10-element circular buffer, and computes
 * a running average.  The average is used to drive an LED on GPIO17
 * so that it is ON when the average temperature exceeds 28.0 °C,
 * and OFF otherwise.
 *
 * Build:  gcc -O2 -Wall -Wextra -o stlm75_monitor stlm75_monitor.c -lpigpio -lrt
 * Run:    sudo ./stlm75_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define I2C_ADDR            0x38          /* STLM75 default I2C address       */
#define GPIO_LED            17            /* BCM 17 – LED output              */
#define BUFFER_SIZE         10
#define TEMP_THRESHOLD      28.0f         /* °C – LED ON threshold           */
#define SAMPLE_PERIOD_US    1000000       /* 1 s between samples             */
#define MAX_READ_ERRORS     10            /* max consecutive I2C failures    */

/* ----------------------------- Data structures ----------------------------- */
typedef struct {
    float  buffer[BUFFER_SIZE];
    int    head;
    int    count;
} CircularBuffer;

/* ----------------------------- Globals ------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;

/* ----------------------------- Prototypes --------------------------------- */
static void  signal_handler(int sig);
static void  cleanup(void);
static int   init_i2c(void);
static int   read_temperature(float *out);
static void  add_to_buffer(CircularBuffer *cb, float temp);
static float  calculate_average(const CircularBuffer *cb);
static void  control_led(float avg_temp);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ----------------------------- I2C init ----------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        return -1;
    }
    return 0;
}

/* ----------------------------- Read temperature --------------------------- */
/*
 * STLM75 temperature register (0x00):
 *   16-bit big-endian, 1 °C resolution.
 *   Returns 0 on success, -1 on failure.
 */
static int read_temperature(float *out)
{
    if (out == NULL)
        return -1;

    char buf[2] = {0, 0};
    int  n = i2cReadDevice(g_i2c_handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2): %s\n",
                n, pigpio_error(n));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *out = (float)raw / 1000.0f;   /* °C */
    return 0;
}

/* ----------------------------- Circular buffer --------------------------- */
static void add_to_buffer(CircularBuffer *cb, float temp)
{
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

/* ----------------------------- Average ----------------------------------- */
static float calculate_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;

    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ----------------------------- LED control -------------------------------- */
static void control_led(float avg_temp)
{
    int level = (avg_temp > TEMP_THRESHOLD) ? 1 : 0;
    if (gpioWrite(GPIO_LED, level) < 0)
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", GPIO_LED);
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C init --- */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* --- Circular buffer --- */
    CircularBuffer tb = { {0.0f} };
    tb.head = 0;
    tb.count = 0;

    /* --- Signals --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("STLM75 monitor started.  I2C bus %d, addr 0x%02X, LED BCM %d\n",
           I2C_BUS, I2C_ADDR, GPIO_LED);
    printf("Threshold: %.1f °C.  Press Ctrl+C to exit.\n", TEMP_THRESHOLD);

    /* --- Main loop --- */
    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            add_to_buffer(&tb, temp);
            float avg = calculate_average(&tb);
            control_led(avg);
            printf("T=%.2f °C  avg=%.2f °C  LED=%s\n",
                   temp, avg, (avg > TEMP_THRESHOLD) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Warning: temperature read failed; skipping cycle\n");
        }

        /* Sleep 1 s, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);   /* 100 ms × 10 = 1 s */
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

