/*
 * SDP32 differential pressure reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c -lpigpio -lrt
 * Run:    sudo ./sdp32_reader [interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_I2C_ADDR 0x2C          /* SDP32 default I2C address (ADDR pin low) */
#define SDP32_REG_MEAS 0x00         /* Start measurement register */
#define SDP32_REG_DATA 0x01         /* Pressure, temperature, scale-factor data */
#define SDP32_REG_CFG 0x02         /* Configuration register */
#define SDP32_REG_ID 0x03          /* Sensor ID register */

#define SDP32_ID_EXPECTED 0x32      /* SDP32 identification word */

#define DEFAULT_INTERVAL_MS 1000
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame from the SDP32                    */
/* Returns 0 on success, -1 on I2C error, -2 on sensor absent         */
/* ------------------------------------------------------------------ */
static int read_sdp32(int handle, float *pressure, float *temperature,
                      float *scale_factor)
{
    uint8_t data[9];
    int rc;

    /*
     * Trigger a single measurement by writing 0x00 to the measurement
     * register.  The SDP32 then returns the 9-byte data frame on the
     * next read.
     */
    rc = i2cWriteByte(handle, SDP32_REG_MEAS);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %d\n",
                SDP32_REG_MEAS, rc);
        return -1;
    }

    /*
     * Wait for the measurement to be ready (max ~15 ms for 125 Pa).
     * If the sensor is absent or the bus is stuck, the read will fail.
     */
    gpioDelay(20000); /* 20 ms */

    rc = i2cReadDevice(handle, (char *)data, 9);
    if (rc != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: expected 9 bytes, got %d\n",
                rc);
        return -1;
    }

    /* Verify CRC for each 2-byte word */
    if (sdp_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -2;
    }
    if (sdp_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -2;
    }
    if (sdp_crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "[ERROR] Scale-factor CRC mismatch\n");
        return -2;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);
    int16_t raw_scale    = (int16_t)((data[6] << 8) | data[7]);

    *pressure    = (float)raw_pressure / 100.0f;   /* ±125 Pa range */
    *temperature = (float)raw_temp / 100.0f;
    *scale_factor = (float)raw_scale;

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val < 0 || val > 1000000) {
            fprintf(stderr, "[ERROR] Invalid interval '%s'. Using default %d ms.\n",
                    argv[1], DEFAULT_INTERVAL_MS);
            interval_ms = DEFAULT_INTERVAL_MS;
        } else {
            interval_ms = (int)val;
        }
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 (SDP32 uses the Pi's I2C bus 1) */
    g_i2c_handle = i2cOpen(1, SDP32_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(1, 0x%02X) failed: %d\n",
                SDP32_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    int id_retries = 0;
    int id_ok = 0;
    while (id_retries < MAX_RETRIES && !id_ok) {
        uint8_t id_buf[3];
        int rc = i2cReadI2CBlockData(g_i2c_handle, SDP32_REG_ID, (char *)id_buf, 3);
        if (rc == 3) {
            uint8_t expected[3] = { SDP32_ID_EXPECTED, 0, 0 };
            if (memcmp(id_buf, expected, 3) == 0) {
                id_ok = 1;
            }
        } else {
            fprintf(stderr, "[WARN] I2C read of sensor ID failed (rc=%d), retry %d/%d\n",
                    rc, id_retries + 1, MAX_RETRIES);
            id_retries++;
            gpioDelay(100000); /* 100 ms */
        }
    }
    if (!id_ok) {
        fprintf(stderr, "[ERROR] SDP32 not detected on I2C bus 1 at 0x%02X after %d retries\n",
                SDP32_I2C_ADDR, MAX_RETRIES);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("[INFO] SDP32 detected (ID 0x%02X)\n", SDP32_ID_EXPECTED);

    /* Configure: set measurement range to ±125 Pa (default) */
    uint8_t cfg_buf[2];
    cfg_buf[0] = SDP32_REG_CFG;
    cfg_buf[1] = 0x00;   /* range ±125 Pa, no averaging */
    int cfg_rc = i2cWriteI2CBlockData(g_i2c_handle, cfg_buf[0], (char *)&cfg_buf[1], 1);
    if (cfg_rc < 0) {
        fprintf(stderr, "[WARN] cfgWrite failed: %d\n", cfg_rc);
    }

    /* Main sampling loop */
    while (g_running) {
        float pressure, temperature, scale_factor;
        int rc = read_sdp32(g_i2c_handle, &pressure, &temperature, &scale_factor);

        if (rc == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("[%s] Pressure: %.2f Pa, Temperature: %.2f °C, Scale: %.2f\n",
                   ts, pressure, temperature, scale_factor);
            fflush(stdout);
        } else if (rc == -2) {
            fprintf(stderr, "[ERROR] Sensor absent or bus error – check wiring and power.\n");
        } else {
            fprintf(stderr, "[ERROR] Read failed (code %d) – sensor may be disconnected.\n", rc);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < MAX_RETRIES && g_running; i++) {
            gpioDelay(interval_ms * 1000); /* pigpio microseconds */
        }
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

