/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2  (BCM pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3  (BCM pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * The SDP810 is a 14-byte, 16-bit-word sensor that returns:
 *   pressure_raw, temperature_raw, scale_factor_pressure, scale_factor_temperature
 *
 * The 9-byte read sequence (per SDP810 datasheet) is:
 *   [0]  start_trigger
 *   [1]  0x00  (dummy)
 *   [2]  0x00  (dummy)
 *   [3]  0x00  (dummy)
 *   [4]  0x00  (dummy)
 *   [5]  0x00  (dummy)
 *   [6]  0x00  (dummy)
 *   [7]  0x00  (dummy)
 *   [8]  0x00  (dummy)
 *   [9]  0x00  (dummy)
 *
 * The 14-byte response reads:
 *   [0]  start_trigger
 *   [1]  0x00  (dummy)
 *   [2]  0x00  (dummy)
 *   [3]  0x00  (dummy)
 *   [4]  0x00  (dummy)
 *   [5]  0x00  (dummy)
 *   [6]  0x00  (dummy)
 *   [7]  0x00  (dummy)
 *   [8]  0x00  (dummy)
 *   [9]  0x00  (dummy)
 *   [10] pressure_raw
 *   [11] temperature_raw
 *   [12] scale_factor_pressure
 *   [13] scale_factor_temperature
 *
 * CRC-8 polynomial 0x31, initial value 0xFF.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x24
#define READ_INTERVAL  1          /* seconds between readings */
#define CONV_WAIT_MS   45         /* SDP810 conversion time after trigger */

/* SDP810 14-byte response word layout (big-endian on the wire). */
typedef struct {
    uint8_t start_trigger;
    uint8_t dummy[6];
    uint16_t pressure_raw;
    uint16_t temperature_raw;
    uint16_t scale_factor_pressure;
    uint16_t scale_factor_temperature;
} __attribute__((packed)) sdp810_data_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static bool crc8_ok(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc == expected;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Write a single command byte to the sensor.
 * Returns 0 on success, -1 on error.
 */
static int sdp810_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "write(cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read exactly `len` bytes from the sensor.
 * Returns 0 on success, -1 on error.
 */
static int sdp810_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "read: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "read: short read (%zd of %zu bytes)\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int sdp810_read_data(int fd, sdp810_data_t *out)
{
    uint8_t raw[9];

    /* Trigger a measurement by writing the start-trigger byte. */
    if (sdp810_write_cmd(fd, 0x00) < 0)
        return -1;

    /* Wait for the conversion to complete. */
    usleep(CONV_WAIT_MS * 1000);

    /* Read 9 bytes: 6 dummy + 3 data words. */
    if (sdp810_read(fd, raw, sizeof(raw)) < 0)
        return -1;

    /* Validate CRC on each 3-byte word. */
    if (!crc8_ok(&raw[0], 2, raw[2])) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -1;
    }
    if (!crc8_ok(&raw[3], 2, raw[5])) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }

    /* Assemble 14-byte response. */
    memcpy(out, &raw[0], 12);

    /* Sanity-check scale-factor values (should be non-zero). */
    if (out->scale_factor_pressure == 0 || out->scale_factor_temperature == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = i2c_open(I2C_BUS, SDP810_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    printf("SDP810-125Pa reader started on %s (addr 0x%02X).\n",
           I2C_BUS, SDP810_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        sdp810_data_t data;

        if (sdp810_read_data(g_i2c_fd, &data) < 0) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        } else {
            /*
             * SDP810 differential pressure:
             *   pressure_raw * scale_factor_pressure  -> Pa
             *   temperature_raw * scale_factor_temperature -> deg C
             */
            float pressure_pa = (float)data.pressure_raw *
                                (float)data.scale_factor_pressure;
            float temp_c      = (float)data.temperature_raw *
                               (float)data.scale_factor_temperature;

            printf("Pressure: %.2f Pa  |  Temperature: %.2f C\n",
                   pressure_pa, temp_c);
            fflush(stdout);
        }

        /* Sleep READ_INTERVAL seconds, but wake early on signal. */
        for (int i = 0; i < READ_INTERVAL && g_running; i++)
            sleep(1);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

