    if (n < 0) {
        fprintf(stderr, "read: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "read: short read (%zd of %zu bytes)\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int sdp810_read_data(int fd, sdp810_data_t *out)
{
    uint8_t raw[9];

    /* Trigger a measurement by writing the start-trigger byte. */
    if (sdp810_write_cmd(fd, 0x00) < 0)
        return -1;

    /* Wait for the conversion to complete. */
    usleep(CONV_WAIT_MS * 1000);

    /* Read 9 bytes: 6 dummy + 3 data words. */
    if (sdp810_read(fd, raw, sizeof(raw)) < 0)
        return -1;

    /* Validate CRC on each 3-byte word. */
    if (!crc8_ok(&raw[0], 2, raw[2])) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -1;
    }
    if (!crc8_ok(&raw[3], 2, raw[5])) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }

    /* Assemble 14-byte response. */
    memcpy(out, &raw[0], 12);

    /* Sanity-check scale-factor values (should be non-zero). */
    if (out->scale_factor_pressure == 0 || out->scale_factor_temperature == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = i2c_open(I2C_BUS, SDP810_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    printf("SDP810-125Pa reader started on %s (addr 0x%02X).\n",
           I2C_BUS, SDP810_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        sdp810_data_t data;

        if (sdp810_read_data(g_i2c_fd, &data) < 0) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        } else {
            /*
             * SDP810 differential pressure:
             *   pressure_raw * scale_factor_pressure  -> Pa
             *   temperature_raw * scale_factor_temperature -> deg C
             */
            float pressure_pa = (float)data.pressure_raw *
                                (float)data.scale_factor_pressure;
            float temp_c      = (float)data.temperature_raw *
                               (float)data.scale_factor_temperature;

            printf("Pressure: %.2f Pa  |  Temperature: %.2f C\n",
                   pressure_pa, temp_c);
            fflush(stdout);
        }

        /* Sleep READ_INTERVAL seconds, but wake early on signal. */
        for (int i = 0; i < READ_INTERVAL && g_running; i++)
            sleep(1);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

