/*
 * Si7051 Temperature Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si7051 SDA -> GPIO2 (Pin 3, BCM)
 *   Si7051 SCL -> GPIO3 (Pin 5, BCM)
 *   Si7051 VDD -> 3.3V
 *   Si7051 GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o si7051_reader si7051_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7051_ADDR    0x49
#define TEMP_REG       0x00
#define MEAS_REG       0x14
#define MEAS_DELAY_MS  10
#define POLL_INTERVAL  5
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp_c)
{
    uint8_t cmd = MEAS_REG;
    uint8_t data[2];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_byte(fd, cmd) < 0) {
            fprintf(stderr, "Measurement request failed (attempt %d)\n", attempt + 1);
            usleep(100000);
            continue;
        }

        usleep(MEAS_DELAY_MS * 1000);

        if (i2c_read_bytes(fd, data, 2) < 0) {
            fprintf(stderr, "Measurement data read failed (attempt %d)\n", attempt + 1);
            usleep(100000);
            continue;
        }

        uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
        raw >>= 4;

        *temp_c = (175.72f * raw / 65536.0f) - 46.85f;
        return 0;
    }

    fprintf(stderr, "Failed to read temperature after %d attempts.\n", MAX_RETRIES);
    return -1;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7051_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI7051_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Si7051 reader started on %s (addr 0x%02X). Press Ctrl+C to exit.\n",
           I2C_BUS, SI7051_ADDR);

    while (g_running) {
        float temp_c;

        if (read_temperature(fd, &temp_c) == 0) {
            printf("Temperature: %.2f °C\n", temp_c);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    close(fd);
    return EXIT_SUCCESS;
}

