/*
 * MLX90833 absolute pressure reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MLX90833 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90833 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90833 VDD  -> 3.3 V
 *   MLX90833 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90833_reader mlx90833_reader.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90833_ADDR  0x49
#define MLX90833_REG_PRESSURE 0x00
#define SAMPLE_PERIOD_MS  500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read one byte back */
    uint8_t val;
    ssize_t n = read(fd, &val, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (got %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    *out = val;
    return 0;
}

static int read_pressure(int fd, float *pressure_out)
{
    uint8_t raw;
    if (i2c_read_byte(fd, MLX90833_REG_PRESSURE, &raw) != 0)
        return -1;

    /*
     * MLX90833 pressure output is 14-bit left-justified in 16 bits.
     * The 14-bit value is in bits [15:4] of the 16-bit result.
     */
    uint16_t raw16 = ((uint16_t)raw << 8) | (raw & 0xFF);
    uint16_t pressure_raw = raw16 >> 4;

    /* Sign-extend the 14-bit value */
    if (pressure_raw & 0x0800)
        pressure_raw |= 0xF000;

    *pressure_out = (float)pressure_raw;
    return 0;
}

static void log_pressure(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s  Pressure: %.2f Pa\n", ts, pressure);
    fflush(stdout);
}

int main(void)
{
