#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x54
#define MEASURE_CMD    0x2E0A
#define MEASURE_DELAY_US 7000
#define LOOP_DELAY_US  5000000
#define DEFAULT_TEMP   25.0f
#define DEFAULT_PRESS  101325.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

static int i2c_write_cmd(int handle, uint16_t cmd)
{
    char buf[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    int rc = i2cWriteDevice(handle, buf, 2);
    if (rc < 0)
        fprintf(stderr, "I2C write failed (rc=%d)\n", rc);
    return rc;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc < 0)
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
    return rc;
}

static int read_sensor_data(int handle, float *temperature, float *pressure)
{
    uint8_t data[6];
    int rc = i2c_read_bytes(handle, data, 6);
    if (rc < 0)
        return -1;
    if (rc != 6)
        return -2;

    uint16_t raw_temp = (uint16_t)((data[1] << 8) | data[0]);
    uint16_t raw_press = (uint16_t)((data[3] << 8) | data[2]);

    *temperature = DEFAULT_TEMP + ((float)raw_temp / 65535.0f) * 100.0f;
    *pressure    = DEFAULT_PRESS + ((float)raw_press / 65535.0f) * 100.0f;
    return 0;
}

static void print_sensor_data(float temperature, float pressure)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temperature, pressure);
    fflush(stdout);
}

int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (i2c_write_cmd(g_i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Sensor not responding or bus error\n");
            break;
        }

        gpioDelay(MEASURE_DELAY_US);

        float temperature, pressure;
        int rc = read_sensor_data(g_i2c_handle, &temperature, &pressure);
        if (rc == 0) {
            print_sensor_data(temperature, pressure);
        } else if (rc == -2) {
            fprintf(stderr, "Sensor returned all-zero data (sensor absent or bus error)\n");
        } else {
            fprintf(stderr, "Sensor read error (rc=%d)\n", rc);
        }

        if (g_running)
            gpioDelay(LOOP_DELAY_US);
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

