/*
 * HVAC Airflow Monitor using Sensirion SDP800-500Pa differential pressure sensor
 * Board: Raspberry Pi 3 Model B+
 * Wiring: SDA -> GPIO2 (BCM), SCL -> GPIO3 (BCM), VDD -> 3.3V, GND -> GND
 * Build: gcc -Wall -o airflow airflow.c -lpigpio -lrt
 * Run:   sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  1000000  /* microseconds (1 second) */
#define MEASURE_DELAY  45000    /* microseconds (45 ms) */
