/* Sensor operations                                                    */
/* ------------------------------------------------------------------ */
static int sensor_start_measurement(int handle)
{
    return i2c_write_byte(handle, REG_MEAS_START, 0x01);
}

static int sensor_read_data(int handle, uint8_t *data)
{
    return i2c_read_block(handle, REG_DATA_START, data, 9);
}

static int sensor_stop_measurement(int handle)
{
    return i2c_write_byte(handle, REG_MEAS_START, 0x00);
}

/* ------------------------------------------------------------------ */
/* Data validation                                                    */
/* ------------------------------------------------------------------ */
static int validate_pressure(const uint8_t *data)
{
    if (crc8(data, 2) != data[2])
        return -1;
    return 0;
}

static int validate_temperature(const uint8_t *data)
{
    if (crc8(data + 3, 2) != data[5])
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("[LOG] fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("[LOG] localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
    return 0;
}

