                    if (validate_pressure(data) == 0 &&
                        validate_temperature(data + 3) == 0) {
                        float pressure = (float)((data[0] << 8) | data[1]) / 100.0f;
                        float temperature = (float)((data[3] << 8) | data[4]) / 100.0f;

                        if (log_data(LOG_FILE, pressure, temperature) == 0) {
                            printf("[DATA] Pressure: %.2f Pa, Temperature: %.2f C\n",
                                   pressure, temperature);
                        } else {
