#define LOG_FILE "pressure_log.csv"
#define PRESSURE_MIN 200.0f
#define PRESSURE_MAX 250.0f
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int open_i2c_handle(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure) {
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *pressure = (float)raw / 100.0f;
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed: %s\n",
                attempt + 1, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000);
        }
    }
    return -1;
}

static int log_data(float pressure) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (open_i2c_handle() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Error flushing header: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
    }

    while (!terminate) {
        float pressure;
        if (read_pressure(&pressure) == 0) {
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Error logging data, continuing...\n");
            }
            if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
                fprintf(stderr, "Warning: Pressure %.2f kPa outside safe range [%.0f, %.0f]\n",
                        pressure, PRESSURE_MIN, PRESSURE_MAX);
            }
        } else {
            fprintf(stderr, "Error reading pressure after %d retries, re-opening I2C...\n", MAX_RETRIES);
            if (open_i2c_handle() != 0) {
                fprintf(stderr, "Failed to re-open I2C, exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

