#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x44
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576  /* 1 MB */
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 40000  /* 40 ms */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_data(const char *timestamp, float temperature, float humidity) {
    int file_size = 0;
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Error opening log file");
        return -1;
    }

    struct stat st;
    if (fstat(fd, &st) == 0) {
        file_size = st.st_size;
    }

    if (file_size > LOG_FILE_SIZE_LIMIT) {
        if (ftruncate(fd, LOG_FILE_SIZE_LIMIT) < 0) {
            perror("Error truncating log file");
            close(fd);
            return -1;
        }
    }

    if (fprintf(fd, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        perror("Error writing to log file");
        close(fd);
        return -1;
    }

    if (fclose(fd) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

static int read_hih6130(float *temperature, float *humidity) {
    char buf[8];
    int result;

    /* Trigger measurement by writing 0x00 to the sensor */
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", pigpio_error(result));
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    /* Read 8 bytes: status (2), temperature (2), humidity (2), CRC (2) */
    result = i2cReadDevice(i2c_handle, buf, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading sensor data: %s\n", pigpio_error(result));
        return -1;
    }

    /* Validate status bits (bits 0-1 of byte 0) */
    if ((buf[0] & 0x03) != 0x03) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", buf[0]);
        return -1;
    }

    /* Convert raw values to physical units */
    unsigned int raw_temperature = ((unsigned char)buf[2] << 8) | (unsigned char)buf[3];
    unsigned int raw_humidity = ((unsigned char)buf[4] << 8) | (unsigned char)buf[5];

    *temperature = -45.0f + 175.0f * (float)raw_temperature / 65535.0f;
    *humidity = 100.0f * (float)raw_humidity / 65535.0f;

    return 0;
}

int main(void) {
    float temperature, humidity;
    char timestamp[32];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    printf("Starting environmental data logging. Press Ctrl+C to exit.\n");

    while (running) {
        if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Error getting timestamp\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (read_hih6130(&temperature, &humidity) == 0) {
            if (log_data(timestamp, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            } else {
                printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                       timestamp, temperature, humidity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

