/*
 * MLX90824 SENT Brake Pressure Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MLX90824 SENT TX  -> GPIO4  (BCM 4, physical pin 7)
 *   MLX90824 SENT GND -> GND
 *   MLX90824 SENT VCC -> 3.3 V
 *
 * SENT protocol:
 *   - 36 µs to 813 µs ticks (3.072 kHz to 7.56 kHz)
 *   - 56-tick sync pulse
 *   - Status nibble (2 ticks)
 *   - 3 data nibbles (each 12 ticks)
 *   - Checksum nibble (2 ticks)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90824_logger mlx90824_logger.c
 *
 * Run:
 *   ./mlx90824_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

#define SENT_GPIO          4
#define LOG_FILE           "pressure_log.txt"
#define SYNC_MIN_TICKS     56
#define SYNC_MAX_TICKS     813
#define STATUS_MIN_TICKS   36
#define STATUS_MAX_TICKS   813
#define DATA_MIN_TICKS     12
#define DATA_MAX_TICKS     271
#define READ_TIMEOUT_US    1000000   /* 1 s timeout for a complete frame */
#define POLL_DELAY_US      1000      /* 1 ms poll interval */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SENT frame parsing                                                    */
/* ------------------------------------------------------------------ */

/*
 * Read exactly `num_ticks` ticks from the SENT line.
 * Returns 0 on success, -1 on timeout or read error.
 */
static int read_ticks(int gpio, uint32_t *out_ticks, uint32_t num_ticks)
{
    uint32_t start = gpioTick();
    while (g_running) {
        if (gpioTick() - start > (uint32_t)(READ_TIMEOUT_US * 1000)) {
            return -1;
        }
        int level = gpioRead(SENT_GPIO);
        if (level < 0) {
            return -1;
        }
        if (level == 1) {
            *out_ticks = gpioTick();
            break;
        }
        if (num_ticks > 0) {
            *out_ticks = gpioTick();
            num_ticks--;
        }
    }
    return 0;
}

/*
 * Parse a complete SENT frame.
 * Returns 0 on success, -1 on timeout or bus error.
 */
static int parse_sent_frame(uint32_t *ticks, int *status,
                            uint32_t *data_nibbles[3], uint32_t *checksum)
{
    /*
     * Sync pulse: 56 ticks (3.072 kHz).
     * If the first 56 ticks are not received, the sensor is absent.
     */
    if (ticks[0] < SYNC_MIN_TICKS || ticks[0] > SYNC_MAX_TICKS) {
        return -1;
    }

    /* Status nibble: 2 ticks */
    *status = ticks[1];

    /* Data nibbles: 3 × 12 ticks each */
    for (int i = 0; i < 3; i++) {
        if (ticks[2 + i * 2] < DATA_MIN_TICKS || ticks[2 + i * 2] > DATA_MAX_TICKS) {
            return -1;
        }
        *data_nibbles[i] = ticks[2 + i * 2];
    }

    /* Checksum nibble: 2 ticks */
    *checksum = ticks[5];

    /*
     * SENT checksum: parity of the 6 nibbles (status + 3 data + checksum).
     * The parity nibble is the XOR of the 5 nibbles.
     */
    uint8_t parity = (uint8_t)(*status ^ *data_nibbles[0] ^
                          *data_nibbles[1] ^ *data_nibbles[2] ^
                          *checksum);
    if (parity != *data_nibbles[3]) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_pressure(float pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
