#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x19
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_ID 0x01
#define TMP117_ID 0x52
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char reg = (char)TMP117_REG_TEMP;
    char data[2];
    int result;

    result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw_temp = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (float)raw_temp / 16.0f;
    return 0;
}

static int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    if (flock(fileno(log_file), LOCK_EX) == -1) {
        perror("flock");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f\n", buf, temperature) < 0) {
        perror("fprintf");
        flock(fileno(log_file), LOCK_UN);
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("fflush");
        flock(fileno(log_file), LOCK_UN);
        return -1;
    }

    if (flock(fileno(log_file), LOCK_UN) == -1) {
        perror("flock unlock");
        return -1;
    }

    return 0;
}

static int verify_sensor(void) {
    char reg = (char)TMP117_REG_ID;
    char id_buf[1];
    int result;

    result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to register address: %s\n", strerror(errno));
        return -1;
    }

    result = i2cReadDevice(i2c_handle, id_buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        return -1;
    }

    if ((uint8_t)id_buf[0] != TMP117_ID) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x%02X, got 0x%02X\n", TMP117_ID, (uint8_t)id_buf[0]);
        return -1;
    }

    printf("TMP117 verified (ID: 0x%02X)\n", (uint8_t)id_buf[0]);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (verify_sensor() != 0) {
        fprintf(stderr, "TMP117 sensor verification failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Greenhouse temperature monitoring started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            } else {
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

