#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x19
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define LOG_FILE "temperature_log.dat"
#define SAMPLE_INTERVAL_SEC 5

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, TMP117_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    int raw = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", raw);
        return -1;
    }
    int16_t signed_raw = (int16_t)raw;
    *temperature = (float)signed_raw * 0.02 - 273.15;
    return 0;
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static int write_buffer_to_file(CircularBuffer *cb, FILE *fp) {
    int start = (cb->count == BUFFER_SIZE) ? cb->head : 0;
    for (int i = 0; i < cb->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        if (fwrite(&cb->buffer[idx], sizeof(float), 1, fp) != 1) {
            fprintf(stderr, "Error writing to log file\n");
            return -1;
        }
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    CircularBuffer temp_buffer = {0};
    temp_buffer.head = 0;
    temp_buffer.count = 0;

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(&temp_buffer, temperature);
        } else {
            fprintf(stderr, "Temperature read failed, skipping sample\n");
        }
        time_sleep(SAMPLE_INTERVAL_SEC);
    }

    fprintf(stderr, "Shutting down...\n");
    if (write_buffer_to_file(&temp_buffer, log_file) != 0) {
        fprintf(stderr, "Error writing buffer to file\n");
    }
    cleanup();
    return EXIT_SUCCESS;
}

