/*
 * SHTC3 temperature & humidity logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SHTC3 VDD  -> Pi 3.3 V (Pin 1)
 *   SHTC3 GND  -> Pi GND  (Pin 6)
 *   SHTC3 SDA  -> Pi GPIO2 / Pin 3 (I2C bus 1)
 *   SHTC3 SCL  -> Pi GPIO3 / Pin 5 (I2C bus 1)
 *
 * Build:  gcc -O2 -Wall -o shtc3_logger shtc3_logger.c -lm
 * Run:    ./shtc3_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHTC3_ADDR     0x29
#define LOG_FILE       "shtc3_environment.log"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define CONV_DELAY_US  15000      /* 15 ms — SHTC3 needs >= 12.4 ms */

/* SHTC3 command bytes */
#define CMD_READ_TEMP_RH  0x2A
#define CMD_READ_TEMP_RH_NO_CRC 0x2A
#define CMD_READ_TEMP_RH_WITH_CRC 0x2A

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity from SHTC3                            */
/* Returns 0 on success, -1 on I/O error, -2 on CRC mismatch,          */
/* -3 on out-of-range value.                                         */
/* ------------------------------------------------------------------ */
static int read_shtc3(float *temperature, float *humidity)
{
    uint8_t cmd = CMD_READ_TEMP_RH;
    uint8_t data[6];

    /* Send read command */
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[SHTC3] I2C write failed\n");
        return -1;
    }

    /* Wait for conversion (datasheet: typ 12.4 ms) */
    gpioDelay(CONV_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "[SHTC3] I2C read failed\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (shtc3_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[SHTC3] Temperature CRC mismatch\n");
        return -2;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (shtc3_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[SHTC3] Humidity CRC mismatch\n");
        return -2;
    }

    /* Convert raw values */
    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t rh_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)rh_raw / 65535.0f;

    /* Sanity-check ranges */
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "[SHTC3] Temperature out of range: %.2f C\n", *temperature);
        return -3;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "[SHTC3] Humidity out of range: %.2f %%\n", *humidity);
        return -3;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading to file                                                 */
/* ------------------------------------------------------------------ */
static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[LOG] fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("[LOG] localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[INIT] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[INIT] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
