        fprintf(stderr, "Error reading rotational speed data: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_speed = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    *rotational_speed = (float)raw_speed / 100.0f;

    return 0;
}

