#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x19
#define TMP117_REG_TEMP 0x00
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    int raw = i2cReadWordData(handle, TMP117_REG_TEMP);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %s\n", strerror(errno));
        return -1;
    }

    /* TMP117: 12-bit left-justified, two's complement */
    int16_t signed_raw = (int16_t)(raw & 0xFFF);
    signed_raw >>= 5;

    /* Sign-extend from 12 bits to 16 bits */
    if (signed_raw & 0x0800) {
        signed_raw |= 0xF000;
    }

    *temperature = (float)signed_raw * 0.0625f;
    return 0;
}

static int log_temperature(const char *filename, float temperature) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int initialize_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, TMP117_ADDR, strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    if (initialize_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TMP117 temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(LOG_FILE, temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            } else {
                printf("Temperature: %.2f C\n", temperature);
            }
        } else {
            fprintf(stderr, "Error reading temperature. Re-initializing I2C...\n");
            for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
                if (initialize_i2c() == 0) {
                    break;
                }
                fprintf(stderr, "I2C re-initialization attempt %d/%d failed.\n", attempt, MAX_RETRIES);
                gpioDelay(100000); /* 100 ms backoff */
            }
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-initialize I2C after %d attempts. Exiting.\n", MAX_RETRIES);
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

