/*
 * Honeywell HAFUHH0025PA3 Airflow Logger for Raspberry Pi Zero W
 *
 * Reads 14-bit flow and 12-bit temperature data from the HAFUHH0025PA3
 * over the I2C bus once per second and logs the results to flow_log.txt.
 *
 * Wiring:
 *   VCC  -> 3.3 V (Pin 1)
 *   GND  -> GND  (Pin 9)
 *   SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lpigpio -lrt
 *   sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x54          /* HAFUHH0025PA3 default I2C address */
#define LOG_FILE       "flow_log.txt"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MAX_RETRIES    3
#define READ_DELAY_US  100000        /* 100 ms between retries */

/*
 * Honeywell HAFUHH0025PA3 14-bit flow and 12-bit temperature read.
 *
 * The sensor returns a 4-byte frame:
 *   [0] = 14-bit flow MSB, [1] = 14-bit flow LSB, [2] = 12-bit temp MSB, [3] = 12-bit temp LSB
 *
 * The first two bytes are the flow data; the last two bytes are the
 * temperature data.  The first two reads after power-up may return
 * stale data, so we discard them and wait for the third read to
 * complete.
 */

typedef struct {
    float flow_slpm;
    float temp_c;
} sensor_data_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Read 4 bytes from the sensor and assemble the 14-bit flow and 12-bit
 * temperature values.  Returns 0 on success, -1 on failure.
 */
static int read_sensor_data(sensor_data_t *data)
{
    char buf[4];
    int  rc;
    int  attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /*
         * i2cReadDevice returns the number of bytes read, or < 0 on error.
         * We read 4 bytes and assemble the 14-bit flow and 12-bit temp
         * values from the first two bytes (flow) and the last two bytes
         * (temp).
         */
        rc = i2cReadDevice(g_i2c_handle, buf, 4);
        if (rc == 4) {
            uint16_t flow_raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            uint16_t temp_raw = ((uint16_t)(uint8_t)buf[2] << 6) | (uint8_t)buf[3];

            /*
             * Flow: 14-bit two's complement, 0..4095.
             * Temperature: 12-bit two's complement, 0..4095.
             */
            data->flow_slpm = (float)flow_raw / 4095.0f;
            data->temp_c   = (float)temp_raw / 4095.0f;
            return 0;
        }

        fprintf(stderr, "I2C read error (attempt %d/%d): returned %d\n",
                attempt + 1, MAX_RETRIES, rc);

        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(READ_DELAY_US);
        }
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Data conversion                                                      */
/* ------------------------------------------------------------------ */

static float convert_flow(uint16_t raw)
{
    return (float)raw / 4095.0f;
}

static float convert_temp(uint16_t raw)
{
    return (float)raw / 4095.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_data(const sensor_data_t *data)
{
    time_t     t;
    struct tm  tm_info;
    char       timestamp[32];

    t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, %.2f, %.2f\n", timestamp,
                data->flow_slpm, data->temp_c) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    sensor_data_t sensor_data;
    int  rc;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Airflow logger started.  Logging to '%s'.  Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- First two reads may be stale --- */
    rc = read_sensor_data(&sensor_data);
    if (rc != 0) {
        fprintf(stderr, "Initial I2C read failed; attempting re-initialization...\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioDelay(1000000);   /* 1 s back-off */
        g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
        if (g_i2c_handle < 0) {
            fprintf(stderr, "Re-initialization failed: %d\n", g_i2c_handle);
            cleanup();
            return EXIT_FAILURE;
        }
        rc = read_sensor_data(&sensor_data);
        if (rc != 0) {
            fprintf(stderr, "Second initial I2C read failed; aborting.\n");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        rc = read_sensor_data(&sensor_data);
        if (rc == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; attempting re-initialization...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(1000000);   /* 1 s back-off */
            g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Re-initialization failed: %d\n", g_i2c_handle);
                cleanup();
                return EXIT_FAILURE;
            }
            rc = read_sensor_data(&sensor_data);
            if (rc != 0) {
                fprintf(stderr, "Second re-initialization failed; aborting.\n");
                cleanup();
                return EXIT_FAILURE;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000);   /* 100 ms */
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

