#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define DHT11_TIMEOUT_US 1000
#define DHT11_START_LOW_US 18000
#define DHT11_START_HIGH_US 10
#define DHT11_BIT_LOW_US 50
#define DHT11_BIT_HIGH_US 26
#define DHT11_BIT_ZERO_US 28
#define DHT11_BIT_ONE_US 70
#define DHT11_BIT_THRESHOLD_US 50
#define DHT11_MAX_RETRIES 10
#define DHT11_MAX_READINGS 10
#define DHT11_READINGS_FILE "dht11_readings.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(const char *message) {
    if (!g_log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(g_log_file, "%s: %s\n", ts, message);
    fflush(g_log_file);
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(g_log_file, "%s: ERROR: %s\n", ts, message);
    fflush(g_log_file);
}

static int dht11_read_data(unsigned char *data) {
    int i;
    int bit_idx = 0;
    int bit_val = 0;
    int last_state = PI_HIGH;
    int timeout = 0;

    /* --- Start signal --- */
    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT11_GPIO, PI_LOW) < 0) return -1;
    gpioDelay(DHT11_START_LOW_US);
    if (gpioWrite(DHT11_GPIO, PI_HIGH) < 0) return -1;
    gpioDelay(DHT11_START_HIGH_US);

    /* Release line: sensor should respond with a low pulse */
    if (gpioSetMode(DHT11_GPIO, PI_INPUT) < 0) return -1;
    gpioDelay(DHT11_TIMEOUT_US);
    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) return -1;
    gpioWrite(DHT11_GPIO, PI_HIGH);
    gpioDelay(DHT11_TIMEOUT_US);

    /* --- Wait for sensor response: low pulse ~80 us --- */
    timeout = 0;
    while (gpioRead(DHT11_GPIO) == PI_HIGH) {
        if (++timeout > DHT11_TIMEOUT_US) return -1;
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(DHT11_GPIO) == PI_LOW) {
        if (++timeout > DHT11_TIMEOUT_US) return -1;
        gpioDelay(1);
    }

    /* --- Read 40 data bits --- */
    for (i = 0; i < 40; i++) {
        /* Wait for low-to-high transition (start of bit) */
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == PI_LOW) {
            if (++timeout > DHT11_TIMEOUT_US) return -1;
            gpioDelay(1);
        }
        /* Measure high-pulse width: ~50 us for '0', ~26-28 us for '1' */
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == PI_HIGH) {
            if (++timeout > DHT11_TIMEOUT_US) return -1;
            gpioDelay(1);
        }
        if (timeout > DHT11_BIT_THRESHOLD_US) {
            bit_val = 1;
        } else {
            bit_val = 0;
        }

        /* Store bit in array */
        data[bit_idx] = bit_val;
        bit_idx++;

        /* Reset for next bit */
        if (bit_idx == 8) {
            bit_idx = 0;
            timeout = 0;
        } else {
            timeout = 0;
        }
    }

    /* --- Checksum --- */
    int checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) {
        return -2;
    }

    return 0;
}

static int dht11_read_sensor(unsigned char *data) {
    int status;
    for (int attempt = 0; attempt < DHT11_MAX_RETRIES; attempt++) {
        status = dht11_read_data(data);
        if (status == 0) {
            return 0;
        }
        if (status == -1) {
            log_error("DHT11: Timeout waiting for sensor response");
        } else if (status == -2) {
            log_error("DHT11: Checksum mismatch");
        }
        gpioDelay(100000); /* 100 ms between retries */
    }
    return -3;
}

static int dht11_write_data(const unsigned char *data) {
    int status;
    for (int attempt = 0; attempt < DHT11_MAX_RETRIES; attempt++) {
        status = gpioWrite(DHT11_GPIO, PI_HIGH);
        if (status < 0) {
            log_error("DHT11: Failed to write high to GPIO");
        }
        gpioDelay(10000); /* 10 ms */
        status = gpioWrite(DHT11_GPIO, PI_LOW);
        if (status < 0) {
            log_error("DHT11: Failed to write low to GPIO");
        }
        gpioDelay(10000); /* 10 ms */
        return status;
    }
    return -4;
}

static int dht11_log_reading(const unsigned char *data) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (data == NULL) {
        log_error("DHT11: NULL data passed to log_reading");
        return -1;
    }

    /* Humidity: byte 0, decimal part (bits 0-1) */
    int humidity = (data[0] << 8) | data[1];
    /* Temperature: byte 2, integer part (bits 0-15) */
    int temperature = (data[2] << 8) | data[3];

    /* Convert raw values to physical units */
    float humidity_percent = humidity / 10.0f;
    float temperature_c = temperature / 10.0f;

    if (humidity_percent < 0.0f || humidity_percent > 100.0f) {
        log_error("DHT11: Humidity value out of range");
        return -1;
    }
    if (temperature_c < -40.0f || temperature_c > 80.0f) {
        log_error("DHT11: Temperature value out of range");
        return -1;
    }

    if (fprintf(g_log_file, "%s, Humidity: %.1f%%, Temperature: %.1fC\n",
                ts, humidity_percent, temperature_c) < 0) {
        log_error("DHT11: Failed to write to log file");
        return -1;
    }
    fflush(g_log_file);
    return 0;
