/*
 * SHT31-D temperature & humidity logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SHT31-D SDA  -> GPIO2  (BCM, physical pin 3)
 *   SHT31-D SCL  -> GPIO3  (BCM, physical pin 5)
 *   SHT31-D VDD  -> 3.3 V
 *   SHT31-D GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht31d_logger sht31d_logger.c -lpigpio -lrt
 * Run:    sudo ./sht31d_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT31_ADDR     0x2D          /* ADDR pin tied to GND (0x2D) or VDD (0x30) */
#define LOG_FILE       "sht31d_data.log"
#define SAMPLE_PERIOD  5             /* seconds between samples */
#define MEAS_DELAY_US  15000         /* 15 ms measurement conversion time */
#define MAX_RETRIES    3

/* SHT31-D measurement command: continuous-conversion, clock stretching,
 * then a dummy read to trigger a new conversion. */
static const uint8_t CMD_MEASURE[2] = { 0x2C, 0x00 };

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) per SHT31 datasheet */
/* ------------------------------------------------------------------ */
static uint8_t sht31_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read temperature (°C) and humidity (%RH) from the SHT31-D.
 * Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int read_sht31d(int handle, float *temperature, float *humidity)
{
    uint8_t buf[6];

    /* Issue the continuous-conversion measurement command. */
    if (i2cWriteDevice(handle, (char *)CMD_MEASURE, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write failed (cmd 0x2C00).\n");
        return -1;
    }

    /* Wait for the conversion to complete. */
    gpioDelay(MEAS_DELAY_US);

    /*
     * After the conversion is ready, a dummy read returns the
     * previous measurement (temperature, humidity, CRC).  A real
     * SHT31-D driver would issue a read-temperature command, but
     * this program uses a dummy read to trigger a new conversion.
     */
    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] I2C read failed (expected 6 bytes).\n");
        return -1;
    }

    /* Validate CRCs. */
    if (sht31_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch (got 0x%02X, expected 0x%02X).\n",
                buf[2], sht31_crc8(&buf[0], 2));
        return -1;
    }
    if (sht31_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch (got 0x%02X, expected 0x%02X).\n",
                buf[5], sht31_crc8(&buf[3], 2));
        return -1;
    }

    /* Assemble the 16-bit signed values. */
    int16_t t_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t h_raw = (int16_t)((buf[3] << 8) | buf[4]);

    *temperature = (float)t_raw / 10.0f;
    *humidity    = (float)h_raw / 10.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file.                       */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed.\n");
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "[ERROR] strftime failed.\n");
        return;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed.\n");
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[WARN] fflush failed on log file.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open ---------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X).\n",
                I2C_BUS, SHT31_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file open ------------------------------------------------ */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'.\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without signals.\n");
    }

    printf("SHT31-D logger started.  Logging to '%s' every %d s.  Press Ctrl-C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sht31d(g_i2c_handle, &temperature, &humidity) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "[WARN] SHT31-D read attempt %d/%d failed.\n",
                    attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(100000);  /* 100 ms backoff before retry */
        }

        if (ok) {
            log_data(g_log_file, temperature, humidity);
            printf("T=%.2f C  H=%.2f %%RH  ->  %s\n",
                   temperature, humidity, LOG_FILE);
        } else {
            fprintf(stderr, "[ERROR] SHT31-D read failed after %d attempts. "
                            "Logging skipped.\n", MAX_RETRIES);
            if (g_log_file != NULL)
                fprintf(g_log_file, "[ERROR] SHT31-D read failed after %d attempts.\n",
                        MAX_RETRIES);
            fflush(g_log_file);
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int s = 0; s < SAMPLE_PERIOD * 10 && g_running; s++)
            gpioDelay(100000);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

