#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

/* MLX90824: 16-bit pressure (big-endian) + 16-bit temperature (big-endian) */
#define PRESSURE_REG 0x00
#define TEMP_REG 0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(stderr, "%s ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
    if (g_log_file) {
        fprintf(g_log_file, "%s ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
        fflush(g_log_file);
    }
}

static int read_pressure(int handle, float *pressure) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure = (float)raw;
    return 0;
}

static int read_temperature(int handle, float *temp) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (rc != 2) {
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temp = (float)raw;
    return 0;
}

static int log_data(FILE *fp, float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (fprintf(fp, "%s, %.2f, %.2f\n", ts, pressure, temperature) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to install signal handlers");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        log_error("Failed to open log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90824 pressure logger started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_pressure(g_i2c_handle, &pressure) != 0) {
            log_error("Failed to read pressure data");
        } else if (read_temperature(g_i2c_handle, &temperature) != 0) {
            log_error("Failed to read temperature data");
        } else {
            if (log_data(g_log_file, pressure, temperature) != 0) {
                log_error("Failed to write to log file");
            } else {
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

