    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        log_error("Failed to open log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90824 pressure logger started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_pressure(g_i2c_handle, &pressure) != 0) {
            log_error("Failed to read pressure data");
        } else if (read_temperature(g_i2c_handle, &temperature) != 0) {
            log_error("Failed to read temperature data");
        } else {
            if (log_data(g_log_file, pressure, temperature) != 0) {
                log_error("Failed to write to log file");
            } else {
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

