#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75B_ADDR     0x32
#define LM75B_TEMP_MSB 0x00
#define LM75B_TEMP_LSB 0x01
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW   26.0f
#define BUFFER_SIZE      60
#define SAMPLE_PERIOD_US 1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LM75B_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75B_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_temperature(float *temperature) {
    uint8_t cmd = LM75B_TEMP_MSB;
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temperature = (float)raw * 0.02f - 273.15f;
    return 0;
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float calculate_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static void control_fan(float average_temp) {
    static bool fan_on = false;
    if (average_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON (avg %.2f C)\n", average_temp);
        } else {
            fprintf(stderr, "Error turning fan ON: %s\n", strerror(errno));
        }
    } else if (average_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (avg %.2f C)\n", average_temp);
        } else {
            fprintf(stderr, "Error turning fan OFF: %s\n", strerror(errno));
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handlers: %s\n", strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    CircularBuffer temp_buffer = {0};
    float temperature;
    int consecutive_errors = 0;

    while (g_running) {
        if (read_temperature(&temperature) == 0) {
            consecutive_errors = 0;
            add_to_buffer(&temp_buffer, temperature);
            float avg = calculate_average(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, avg);
            control_fan(avg);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading temperature (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors, aborting.\n");
                break;
            }
        }
        usleep(SAMPLE_PERIOD_US);
    }

    gpioWrite(FAN_GPIO, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

