#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP810_ADDR    0x49
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  1.0
#define MEAS_DELAY_US  45000
#define PRESSURE_WARN  5.0f
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, SDP810_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sdp810(float *pressure, float *temperature)
{
    uint8_t cmd[2] = {0x36, 0x81};
    uint8_t buf[9];
    int rc;

    /* Issue measurement command (differential pressure, no averaging) */
    rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: %d\n", rc);
        return -1;
    }

    /* SDP810 needs ~45 ms after issuing the command */
    gpioDelay(MEAS_DELAY_US);

    /* Read 9 bytes: 3 words × (2 data + 1 CRC) */
    rc = i2cReadDevice(g_i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "I2C read error: expected 9 bytes, got %d\n", rc);
        return -1;
    }

    /* Validate CRC for each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (sensirion_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temp / 100.0f;
    return 0;
}

static void log_data(float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(g_log_fp);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# timestamp,pressure_Pa,temperature_C\n");
    fflush(g_log_fp);

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sdp810(&pressure, &temperature) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            gpioDelay(100000);
        }

        if (success) {
            log_data(pressure, temperature);
            if (pressure > PRESSURE_WARN) {
                fprintf(stderr, "WARNING: Pressure %.2f Pa exceeds warning threshold %.2f Pa\n",
                        pressure, PRESSURE_WARN);
            }
        } else {
            fprintf(stderr, "Failed to read sensor after %d attempts\n", MAX_RETRIES);
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        double remaining = SAMPLE_PERIOD;
        while (remaining > 0.0 && g_running) {
            double s = (remaining > 0.1) ? 0.1 : remaining;
            gpioDelay((uint32_t)(s * 1000000.0));
            remaining -= s;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

