#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x19
#define REG_TEMP_H     0x00
#define REG_TEMP_L     0x01
#define GPIO_LED       17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_DELAY_US  1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_temperature(float *temp_out)
{
    uint8_t reg = REG_TEMP_H;
    uint8_t buf[2];

    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_out = (float)raw / 16.0f;
    return 0;
}

static void control_led(float temp)
{
    static bool led_on = false;
    if (temp > TEMP_HIGH && !led_on) {
        if (gpioWrite(GPIO_LED, 1) == 0) {
            led_on = true;
            printf("LED ON (temp=%.2f C)\n", temp);
        } else {
            fprintf(stderr, "Error setting GPIO%d high: %s\n",
                    GPIO_LED, strerror(errno));
        }
    } else if (temp < TEMP_LOW && led_on) {
        if (gpioWrite(GPIO_LED, 0) == 0) {
            led_on = false;
            printf("LED OFF (temp=%.2f C)\n", temp);
        } else {
            fprintf(stderr, "Error setting GPIO%d low: %s\n",
                    GPIO_LED, strerror(errno));
        }
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("STTS2004 temperature monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            printf("Temperature: %.2f C\n", temp);
            control_led(temp);
        } else {
            fprintf(stderr, "Failed to read temperature. Exiting.\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            gpioWrite(GPIO_LED, 0);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nExiting cleanly.\n");
    close(g_i2c_fd);
    g_i2c_fd = -1;
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

