#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x49
#define LOG_FILE       "environment.log"
#define SAMPLE_INTERVAL 60
#define MAX_RETRIES    3
#define MEAS_DELAY_US  20000

/* Si7021 command codes (no-hold variants) */
#define CMD_MEASURE_RH_NO_HOLD  0x28
#define CMD_MEASURE_TEMP_NO_HOLD 0x2A
#define CMD_READ_RH_PREV_TEMP  0x34
#define CMD_READ_TEMP_PREV_RH 0x36

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0)
        fprintf(stderr, "i2cWriteByte(0x%02X) failed: %s\n", cmd, pigpio_error(rc));
    return rc;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != len)
        fprintf(stderr, "i2cReadDevice failed: expected %d, got %d\n", len, rc);
    return rc;
}

static int read_measurement(int handle, uint8_t cmd, float *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(handle, cmd) < 0) {
            fprintf(stderr, "Attempt %d: write cmd 0x%02X failed\n", attempt + 1, cmd);
            gpioDelay(10000);
            continue;
        }
        gpioDelay(MEAS_DELAY_US);

        uint8_t buf[2];
        if (i2c_read_bytes(handle, buf, 2) < 0) {
            fprintf(stderr, "Attempt %d: read failed\n", attempt + 1);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *out = (float)raw;
        return 0;
    }
    return -1;
}

static int read_temperature(int handle, float *temp)
{
    return read_measurement(handle, CMD_MEASURE_TEMP_NO_HOLD, temp);
}

static int read_humidity(int handle, float *hum)
{
    return read_measurement(handle, CMD_MEASURE_RH_NO_HOLD, hum);
}

static int read_temperature_from_previous_rh(int handle, float *temp, float *rh)
{
    uint8_t cmd = CMD_READ_TEMP_PREV_RH;
    uint8_t buf[3];

    if (i2c_write_cmd(handle, cmd) < 0)
        return -1;
    gpioDelay(MEAS_DELAY_US);

    if (i2c_read_bytes(handle, buf, 3) < 0)
        return -1;

    uint16_t rh_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[2] << 8) | buf[3];

    *rh = (float)rh_raw;
    *temp = (float)temp_raw / 10.0f;
    return 0;
}

static int read_temperature_from_previous_temp(int handle, float *temp, float *rh)
{
    uint8_t cmd = CMD_READ_RH_PREV_TEMP;
    uint8_t buf[3];

    if (i2c_write_cmd(handle, cmd) < 0)
        return -1;
    gpioDelay(MEAS_DELAY_US);

    if (i2c_read_bytes(handle, buf, 3) < 0)
        return -1;

    uint16_t rh_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[2] << 8) | buf[3];

    *rh = (float)rh_raw;
    *temp = (float)temp_raw / 10.0f;
    return 0;
}

static int verify_sensor(int handle)
{
    uint8_t id;
    if (i2c_read_bytes(handle, (uint8_t *)&id, 1) < 0) {
        fprintf(stderr, "Cannot read sensor ID (sensor absent or bus error)\n");
        return -1;
    }
    if (id != 0x54) {
        fprintf(stderr, "Unexpected sensor ID 0x%02X (expected 0x54)\n", id);
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float temp, float hum)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fflush(fp);
    printf("%s,%.2f,%.2f\n", ts, temp, hum);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "Sensor verification failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp, hum;
        int rc;

        rc = read_temperature(g_i2c_handle, &temp);
        if (rc == 0) {
            rc = read_humidity(g_i2c_handle, &hum);
            if (rc == 0)
                log_data(g_log_file, temp, hum);
            else
                fprintf(stderr, "Humidity read failed\n");
        } else if (rc < 0) {
            fprintf(stderr, "Temperature read failed\n");
        }

