#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS40_ADDR     0x24
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_PERIOD  5
#define CONVERSION_MS  10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Sensirion CRC-8 polynomial: x^8 + x^5 + x^4 + 1 (0x31), init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_sts40(int fd, float *temp_c)
{
    uint8_t data[3];
    ssize_t n = read(fd, data, sizeof(data));
    if (n != (ssize_t)sizeof(data)) {
        fprintf(stderr, "read: expected 3 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    if (sensirion_crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                sensirion_crc8(data, 2), data[2]);
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temp_c = -45.0f + 175.0f * (float)raw / 65535.0f;
    return 0;
}

static void log_reading(FILE *fp, float temp_c)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, temp_c);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = i2c_open(I2C_BUS, STS40_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp_c;
        if (read_sts40(fd, &temp_c) == 0) {
            log_reading(fp, temp_c);
            printf("%s  %.2f C\n", LOG_FILE, temp_c);
        } else {
            fprintf(stderr, "STS40 read failed; will retry next cycle.\n");
        }
        /* Sleep in 100 ms chunks so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100000);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

