        }
        /* Sleep in 100 ms chunks so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100000);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

