#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x49
#define SCD40_CMD_START_PERIODIC 0x368F
#define SCD40_CMD_STOP_PERIODIC 0x3695
#define SCD40_CMD_READ_MEASUREMENT 0x368A
#define SCD40_REG_CO2_MSB 0x00
#define SCD40_REG_TEMP_MSB 0x01
#define SCD40_REG_HUM_MSB 0x02
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_DIR "/var/log/scd40_error.log"
#define CSV_FILE_PATH LOG_DIR "scd40_data.csv"
#define CSV_FILE_PATH_FINAL LOG_DIR "scd40_data_final.csv"
#define SAMPLE_INTERVAL_SEC 5
#define STARTUP_DELAY_SEC 1
#define MAX_RETRIES 3

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static circular_buffer_t buffer;
static pthread_t logging_thread;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        FILE *fp = fopen(CSV_FILE_PATH, "a");
        if (fp == NULL) {
            perror("Error opening CSV file");
            sleep(60);
            continue;
        }
        fseek(fp, 0, SEEK_END);
        long file_size = ftell(fp);
        if (file_size == 0) {
            fprintf(fp, "Timestamp,CO2,Temperature,Humidity\n");
        }
        rewind(fp);
        sensor_data_t record;
        while (running) {
            if (buffer.count > 0) {
                record = buffer.data[buffer.tail];
                buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
                if (buffer.count < BUFFER_SIZE) {
                    buffer.count++;
                }
            } else {
                break;
            }
            if (pthread_mutex_lock(&buffer.mutex) != 0) {
                perror("Mutex lock failed");
                break;
            }
            time_t now = time(NULL);
            char timestamp_str[32];
            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp_str, record.co2, record.temperature, record.humidity);
            fflush(fp);
            pthread_mutex_unlock(&buffer.mutex);
        }
        fclose(fp);
        sleep(60);
    }
    return NULL;
}

static int scd40_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing command 0x%04X: %d\n", cmd, result);
        return -1;
    }
    return 0;
}

static int scd40_read_measurement(uint16_t *co2, uint16_t *temp, uint16_t *hum) {
    uint8_t buf[8];
    int result = i2cReadI2CBlockData(i2c_handle, SCD40_REG_CO2_MSB, (char *)buf, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading measurement data: %d\n", result);
        return -1;
    }
    *co2 = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = ((uint16_t)buf[2] << 8) | buf[3];
    *hum = ((uint16_t)buf[4] << 8) | buf[5];
    return 0;
}

static int scd40_start_periodic(void) {
    if (scd40_write_command(SCD40_CMD_START_PERIODIC) != 0) {
        return -1;
    }
    gpioDelay(100000);
    return 0;
}

static int scd40_stop_periodic(void) {
    if (scd40_write_command(SCD40_CMD_STOP_PERIODIC) != 0) {
        return -1;
    }
    gpioDelay(100000);
    return 0;
}

static int scd40_read_measurement_with_crc(uint16_t *co2, uint16_t *temp, uint16_t *hum) {
    uint8_t buf[8];
    int result = i2cReadI2CBlockData(i2c_handle, SCD40_REG_CO2_MSB, (char *)buf, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading measurement data: %d\n", result);
        return -1;
    }
    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5] || crc8(buf + 6, 2) != buf[7]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }
    *co2 = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = ((uint16_t)buf[2] << 8) | buf[3];
    *hum = ((uint16_t)buf[4] << 8) | buf[5];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd40_stop_periodic();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    pthread_join(logging_thread, NULL);
    pthread_mutex_destroy(&buffer.mutex);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    buffer_init(&buffer);
    if (scd40_start_periodic() != 0) {
        fprintf(stderr, "Error starting periodic measurement\n");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    struct timespec sleep_time = { .tv_sec = STARTUP_DELAY_SEC, .tv_nsec = 0 };
    while (running) {
        if (scd40_read_measurement_with_crc(&buffer.data[buffer.head].co2, &buffer.data[buffer.head].temp, &buffer.data[buffer.head].humidity) == 0) {
            buffer_add(&buffer, buffer.data[buffer.head]);
        }
        nanosleep(&sleep_time, NULL);
    }
    cleanup();
    return 0;
}

