#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x48
#define LED_PIN        17
#define PRESSURE_THRESHOLD_PA 95000.0f
#define POLL_DELAY_US  1000000
#define LED_ON_US      500000
#define LED_OFF_US     500000
#define LED_HALF_US    100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_gpio_line = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (uint8_t)((crc << 1) ^ 0x31);
            else            crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1;
        total += (int)n;
    }
    return 0;
}

static int read_icp10125(int fd, float *pressure_pa) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) != 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    *pressure_pa = (float)raw_pressure / 100.0f;
    return 0;
}

static void set_led(int on) {
    if (g_gpio_line >= 0) {
        gpioWrite(g_gpio_line, on ? 1 : 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_gpio_line = gpioGetGPIO(LED_PIN);
    if (g_gpio_line < 0) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", LED_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(g_gpio_line, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ICP10125_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("ICP-10125 pressure monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure_pa;
        if (read_icp10125(g_i2c_fd, &pressure_pa) == 0) {
            printf("Pressure: %.2f Pa\n", pressure_pa);

            if (pressure_pa < PRESSURE_THRESHOLD_PA) {
                printf("Pressure below threshold, switching to 5 Hz blinking.\n");
                set_led(1);
                gpioDelay(LED_HALF_US);
                set_led(0);
                gpioDelay(LED_HALF_US);
                set_led(1);
                gpioDelay(LED_HALF_US);
                set_led(0);
                gpioDelay(LED_HALF_US);
            } else {
                set_led(0);
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_gpio_line >= 0) gpioTerminate();
    return 0;
}

