#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x44
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 2

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_temperature(float *ambient_temp, float *object_temp) {
    char buf[6];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result == 6) {
            unsigned int raw_object = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
            unsigned int raw_ambient = ((unsigned char)buf[3] << 8) | (unsigned char)buf[4];
            *object_temp = -45.0 + 175.0 * (float)raw_object / 65535.0;
            *ambient_temp = -45.0 + 175.0 * (float)raw_ambient / 65535.0;
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d): %d\n", retries + 1, MAX_RETRIES, result);
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static int control_fan(float object_temp) {
    static int fan_on = 0;
    int new_state = fan_on;

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (object temp: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (object temp: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
    return new_state;
}

static void log_temperature(float ambient_temp, float object_temp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float ambient_temp, object_temp;

        if (read_temperature(&ambient_temp, &object_temp) == 0) {
            log_temperature(ambient_temp, object_temp);
            control_fan(object_temp);
        } else {
            fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nCleaning up...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

