#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x10
#define MEASURE_CMD 0x2C00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define MEASURE_DELAY_MS 10
#define HTTP_PORT 8080
#define HTTP_SERVER_IP "127.0.0.1"
#define HTTP_SERVER_PORT 8080
#define HTML_FILE "index.html"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int http_server_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF\n");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int read_sht40(int fd, float *temperature, float *humidity) {
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (i2c_write_cmd(fd, MEASURE_CMD) < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(MEASURE_DELAY_MS * 1000);

        uint8_t data[6];
        if (i2c_read_data(fd, data, 6) < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint16_t raw_temperature = (data[0] << 8) | data[1];
        uint16_t raw_humidity = (data[3] << 8) | data[4];

        *temperature = -45.0f + 175.0f * (float)raw_temperature / 65535.0f;
        *humidity = 100.0f * (float)raw_humidity / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }
    return -1;
}

static int send_http_response(int server_fd, float temperature, float humidity) {
    char buffer[256];
    int len = snprintf(buffer, sizeof(buffer),
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: text/html\r\n"
        "Connection: close\r\n"
        "\r\n"
        "<!DOCTYPE html><html><head><title>SHT40 Sensor</title>"
        "<meta charset=\"utf-8\">"
        "<script>"
        "var xhr = new XMLHttpRequest();"
        "xhr.open('GET', 'http://%s:%d%s', true);"
        "xhr.onload = function() { if (this.status == 200) document.body.innerHTML = "
        "  '<h1>Temperature: %.2f C, Humidity: %.2f %</h1>' + "
        "  + this.responseText; }"
        "xhr.send();"
        "</script></head><body>"
        "</body></html>",
        HTTP_SERVER_IP, HTTP_SERVER_PORT, HTML_FILE);

    if (len < 0) {
        fprintf(stderr, "Failed to generate HTML: %s\n", strerror(errno));
        return -1;
    }

    ssize_t sent = 0;
    while (sent < len) {
        ssize_t n = send(server_fd, buffer + sent, len - sent, 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "HTTP send failed: %s\n", strerror(errno));
            return -1;
        }
        sent += n;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SHT40_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int http_server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (http_server_fd < 0) {
        fprintf(stderr, "Failed to create HTTP server socket: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int reuse = 1;
    if (setsockopt(http_server_fd, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse)) < 0) {
        fprintf(stderr, "Failed to set SO_REUSEADDR: %s\n", strerror(errno));
        close(http_server_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(HTTP_SERVER_PORT);

    if (bind(http_server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to bind HTTP server: %s\n", strerror(errno));
        close(http_server_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (listen(http_server_fd, 3) < 0) {
        fprintf(stderr, "Failed to listen on HTTP server: %s\n", strerror(errno));
        close(http_server_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("HTTP server listening on port %d\n", HTTP_SERVER_PORT);

    while (running) {
        float temperature, humidity;
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

            if (send_http_response(http_server_fd, temperature, humidity) < 0) {
                fprintf(stderr, "Failed to send HTTP response\n");
            }
        } else {
            fprintf(stderr, "Failed to read SHT40 sensor after %d retries\n", RETRY_COUNT);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    if (http_server_fd >= 0) close(http_server_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return EXIT_SUCCESS;
}

