#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP102_ADDR    0x2E
#define TMP102_REG_TEMP 0x00
#define LOG_FILE       "temperature_log.csv"
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, float *temperature)
{
    int raw;
    int rc;

    rc = i2cReadWordData(handle, TMP102_REG_TEMP);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (rc=%d): %s\n", rc, strerror(errno));
        return -1;
    }
    raw = (int)rc;

    /* TMP102: 12-bit left-justified, 0.0625 °C LSB */
    int16_t temp_raw = (int16_t)(raw >> 4);
    *temperature = (float)temp_raw * 0.0625f;
    return 0;
}

static int log_temperature(const char *filename, float temperature)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, TMP102_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP102 temperature logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            if (log_temperature(LOG_FILE, temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            } else {
                printf("%s Temperature: %.2f °C\n", LOG_FILE, temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

