#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC2010_ADDR 0x49
#define I2C_BUS "/dev/i2c-1"
#define MEASUREMENT_CONFIG_REG 0x00
#define HDC2010_MEASUREMENT_CONFIG 0x01
#define HDC2010_TEMP_OUT_L 0x02
#define HDC2010_HUMIDITY_OUT_L 0x04
#define HDC2010_MEASUREMENT_CONFIG_VAL 0x01
#define MAX_RETRIES 3
#define POLL_TIMEOUT_MS 500
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int hdc2010_init(int fd) {
    if (i2c_write_reg8(fd, MEASUREMENT_CONFIG_REG, HDC2010_MEASUREMENT_CONFIG_VAL) < 0) {
        return -1;
    }
    return 0;
}

static int hdc2010_read_temperature(int fd, float *temperature) {
    uint8_t temp_raw;
    if (i2c_read_reg8(fd, HDC2010_TEMP_OUT_L, &temp_raw) < 0) {
        return -1;
    }
    uint16_t temp_data = (uint16_t)temp_raw;
    *temperature = (float)temp_data / 10.0f;
    return 0;
}

static int hdc2010_read_humidity(int fd, float *humidity) {
    uint8_t humidity_raw;
    if (i2c_read_reg8(fd, HDC2010_HUMIDITY_OUT_L, &humidity_raw) < 0) {
        return -1;
    }
    uint16_t humidity_data = (uint16_t)humidity_raw;
    *humidity = (float)humidity_data / 10.0f;
    return 0;
}

static int hdc2010_wait_measurement(int fd) {
    uint8_t config;
    int elapsed = 0;
    do {
        if (i2c_read_reg8(fd, MEASUREMENT_CONFIG_REG, &config) < 0) {
            return -1;
        }
        if (config & 0x01) {
            return 0;
        }
        usleep(1000);
        elapsed += 1000;
    } while (elapsed < POLL_TIMEOUT_MS);
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HDC2010_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (hdc2010_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize HDC2010 sensor.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("HDC2010 sensor initialized. Reading every %d seconds...\n", SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;
        int rc = -1;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (hdc2010_wait_measurement(g_i2c_fd) < 0) {
                fprintf(stderr, "I2C communication error during measurement wait (attempt %d/%d).\n", attempt + 1, MAX_RETRIES);
                usleep(100000);
                continue;
            }

            if (hdc2010_read_temperature(g_i2c_fd, &temperature) < 0) {
                fprintf(stderr, "Failed to read temperature (attempt %d/%d).\n", attempt + 1, MAX_RETRIES);
                usleep(100000);
                continue;
            }

            if (hdc2010_read_humidity(g_i2c_fd, &humidity) < 0) {
                fprintf(stderr, "Failed to read humidity (attempt %d/%d).\n", attempt + 1, MAX_RETRIES);
                usleep(100000);
                continue;
            }

            rc = 0;
            break;
        }

        if (rc == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d attempts.\n", MAX_RETRIES);
        }

        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return EXIT_SUCCESS;
}

