 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800_reader sdp800_reader.c -lpigpio -lrt
 * Run:    sudo ./sdp800_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x24          /* SDP800-500Pa default I2C address */
#define READ_INTERVAL  500000        /* 500 ms in microseconds */
#define MEAS_DELAY_US  45000         /* 45 ms measurement conversion time */

/*
 * SDP800-500Pa measurement frame (12 bytes, 6 data bytes + 6 CRC bytes).
 * Byte 0: pressure CRC (always 0x00)
 * Byte 1: pressure data (12-bit, 2 MSBs are the differential pressure)
 * Byte 2: temperature CRC (always 0x00)
 * Byte 3: temperature data (12-bit, 2 MSBs are the temperature)
 */
typedef struct {
    uint16_t pressure;          /* 12-bit differential pressure, signed */
    uint16_t temperature;       /* 12-bit temperature, signed */
} sensor_data_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static bool crc8_check(const uint8_t *data, uint8_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one measurement frame from the SDP800                         */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_sdp800(sensor_data_t *data)
{
    uint8_t buf[6];
    int rc;

    /*
     * Issue a read-measurement command (0x00) to trigger a single
     * differential-pressure + temperature read.  The SDP800 returns
     * exactly 6 bytes: pressure(2) + CRC, temperature(2) + CRC,
     * then two padding bytes.
     */
    rc = i2cWriteByte(g_i2c_handle, 0x00);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x00) failed: %d\n", rc);
        return -1;
    }

    /*
     * Wait for the conversion to complete.  The SDP800 needs up to
     * 45 ms for a 12-bit measurement.  We poll with a 100 us delay
     * and a 1000 us timeout to avoid busy-waiting.
     */
    uint32_t waited = 0;
    while (waited < 1000000) {
        gpioDelay(100);
        waited += 100;
        if (waited >= 1000000) {
            fprintf(stderr, "[ERROR] SDP800 conversion timeout\n");
            return -1;
        }
    }

    /*
     * Read 6 bytes.  The first two bytes are the 12-bit differential
     * pressure, the next two are the 12-bit temperature, and the
     * final two are padding.
     */
    rc = i2cReadDevice(g_i2c_handle, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 6)\n", rc);
        return -1;
    }

    /* Validate CRCs */
    if (!crc8_check(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (!crc8_check(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    /*
     * Assemble the 12-bit values.  The two MSBs of the pressure byte
     * and the two MSBs of the temperature byte are the differential
     * pressure and temperature, respectively.
     */
    data->pressure = ((uint16_t)(buf[0] & 0xFF) << 8) | (buf[1] & 0xFF);
    data->temperature = ((uint16_t)(buf[3] & 0xFF) << 8) | (buf[4] & 0xFF);

    /*
     * Sign-extend the 12-bit value to a 16-bit signed integer.
     * The SDP800 returns the two MSBs of the 12-bit result in the
     * two most-significant bytes of the 16-bit data word.
     */
    if (data->pressure & 0x0800)
        data->pressure |= 0xF000;
    if (data->temperature & 0x0800)
        data->temperature |= 0xF000;

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    sensor_data_t sensor_data;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the SDP800 address */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SDP800_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP800-500Pa reader started.  Press Ctrl+C to exit.\n");
    printf("I2C bus %d, address 0x%02X, sampling every %d ms.\n",
           I2C_BUS, SDP800_ADDR, READ_INTERVAL / 1000);

    /* Main sampling loop */
    while (g_running) {
        if (read_sdp800(&sensor_data) == 0) {
            printf("Pressure: %6u Pa  |  Temperature: %6u C\n",
                   sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "[WARN] Read failed; continuing.\n");
        }
        gpioDelay(READ_INTERVAL);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

