}

/* ------------------------------------------------------------------ */
/* Read 16-bit big-endian value from MAX6675 register                 */
/* ------------------------------------------------------------------ */
static int max6675_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(handle, tx, rx, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write 16-bit big-endian value to MAX6675 register                  */
/* ------------------------------------------------------------------ */
static int max6675_write_reg(int handle, uint8_t reg, uint16_t val)
{
    char tx[2] = { (char)(reg & 0x7F), (char)(val & 0xFF) };
    char rx[2] = { 0, 0 };

    if (spiXfer(handle, tx, rx, 2) != 2)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read thermocouple temperature (°C)                                 */
/* ------------------------------------------------------------------ */
static float read_thermocouple_temp(int handle)
{
    uint16_t raw;
    if (max6675_read_reg(handle, MAX6675_TEMP_REG, &raw) != 0) {
        fprintf(stderr, "SPI read error on thermocouple register\n");
        return -273.15f;
    }

    /* 10-bit left-justified: bits 15..12 = temperature, bits 11..0 = unused */
    int16_t temp_raw = (int16_t)(raw >> 4);
    return (float)temp_raw * 0.25f;
}

/* ------------------------------------------------------------------ */
/* PID control                                                          */
/* ------------------------------------------------------------------ */
static float pid_control(float current_temp, float target_temp,
                          float *integral, float *prev_error,
                          float dt)
{
    float error = target_temp - current_temp;
    *integral += error * dt;
    float derivative = (error - *prev_error) / dt;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    return output;
}

/* ------------------------------------------------------------------ */
/* Load target temperature profile from file                           */
/* ------------------------------------------------------------------ */
static int load_profile(const char *filename, float *target_temps,
                       int *target_times, int n_points)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open profile file '%s'\n", filename);
        return -1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp)) {
        char *endptr;
        float t = strtof(line, &endptr);
        if (endptr == line) {
            fprintf(stderr, "Invalid profile line: '%s'\n", line);
            fclose(fp);
            return -1;
        }
        target_temps[count] = t;
        target_times[count] = (int)t;
        count++;
    }
    fclose(fp);

    if (count < n_points) {
        fprintf(stderr, "Profile file has fewer points than requested (%d/%d)\n",
                count, n_points);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log temperature reading to CSV file                                */
/* ------------------------------------------------------------------ */
static int log_temperature(float temp)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, temp) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure SSR GPIO */
    if (gpioSetMode(SSR_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SSR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SSR_GPIO, 0);

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Load profile */
    float target_temps[10];
    int target_times[10];
    if (load_profile(PROFILE_FILE, target_temps, target_times, 10) != 0) {
        fprintf(stderr, "Failed to load profile. Using default target 25°C.\n");
        target_temps[0] = 25.0f;
        target_times[0] = 10;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "timestamp,temperature_c\n");

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* PID state */
    float integral = 0.0f, prev_error = 0.0f;
    float target_temp = target_temps[0];
    int target_time = target_times[0];

    printf("Reflow oven started. Target: %.1f°C at %d s\n", target_temp, target_time);

    while (g_running) {
        float temp = read_thermocouple_temp(g_spi_handle);

        if (temp < -273.0f) {
            fprintf(stderr, "Sensor read error — skipping cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float pid_out = pid_control(temp, target_temp, &integral, &prev_error,
                                     1.0f / 1000.0f);

        /* Clamp output to [0, 1] */
        if (pid_out < 0.0f) pid_out = 0.0f;
        if (pid_out > 1.0f) pid_out = 1.0f;

        int duty = (int)(pid_out * 1000000.0f);
        if (duty < 0) duty = 0;
        if (duty > 1000000) duty = 1000000;

        gpioWrite(SSR_GPIO, duty > 500000 ? 1 : 0);

        if (log_temperature(temp) != 0) {
            fprintf(stderr, "Logging failed — continuing\n");
        }

        /* Update target time */
        target_time += 1;
        if (target_time >= target_time) {
            target_time = 10;
        }

        printf("Temp: %.2f°C  PID: %.4f  Target: %d s\n", temp, pid_out, target_time);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

