#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <linux/w1_spi.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/wait.h>

#define HEATER_PIN 17
#define PWM_PIN 18
#define LOG_FILE "greenhouse.log"
#define TEMP_SENSOR_PIN 4
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PWM_DUTY_STEP 100
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int pwm_duty_cycle = 0;
static int pwm_enabled = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/bus/w1/devices/28-000000000000/w1_slave");
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';
    close(fd);

    if (bytes_read < 2) {
        fprintf(stderr, "Error: Insufficient data from %s\n", path);
        return -1;
    }

    uint8_t *data = (uint8_t *)buffer;
    if (data[0] != '1' || data[1] != '2') {
        fprintf(stderr, "Error: Invalid CRC on %s\n", path);
        return -1;
    }

    uint16_t raw_temperature = ((uint16_t)data[2] << 8) | data[3];
    *temperature = (float)raw_temperature / 1000.0f;
    return 0;
}

static float pid_calculate(float setpoint, float actual_temperature, float *integral, float *previous_error, float kp, float ki, float kd) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

static void set_heater(int on) {
    if (pwm_enabled) {
        pwm_duty_cycle = on ? PWM_RANGE : 0;
        if (ioctl(PWM_PIN, PWM_F_SET, &pwm_duty_cycle) < 0) {
            fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
        }
    }
    if (on) {
        if (gpioWrite(HEATER_PIN, 1) < 0) {
            fprintf(stderr, "Error enabling heater relay: %s\n", strerror(errno));
        }
    } else {
        if (gpioWrite(HEATER_PIN, 0) < 0) {
            fprintf(stderr, "Error disabling heater relay: %s\n", strerror(errno));
        }
    }
}

static void log_data(float average_temperature, float setpoint, float pid_output, int pwm_duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Average Temperature: %.2f, Setpoint: %.2f, PID Output: %.2f, PWM Duty Cycle: %d\n",
            timestamp, average_temperature, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file);
}

static void cleanup(void) {
    if (pwm_enabled) {
        pwm_duty_cycle = 0;
        pwm_enabled = 0;
        if (ioctl(PWM_PIN, PWM_F_SET, &pwm_duty_cycle) < 0) {
            fprintf(stderr, "Warning: Failed to disable PWM: %s\n", strerror(errno));
        }
    }
    set_heater(0);
    if (pwm_enabled) {
        pwm_enabled = 0;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (pwm_duty_cycle >= 0) {
        if (close(pwm_duty_cycle) < 0) {
            fprintf(stderr, "Warning: Failed to close PWM duty cycle file descriptor: %s\n", strerror(errno));
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    float setpoint = atof(argv[1]);
    float kp = atof(argv[2]);
    float ki = atof(argv[3]);
    float kd = atof(argv[4]);

    if (kp <= 0 || ki <= 0 || kd <= 0) {
        fprintf(stderr, "Error: Gain values must be positive.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetMode(HEATER_PIN, PI_OUTPUT) < 0 || gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO modes: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error setting PWM frequency: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    pwm_duty_cycle = 0;
    pwm_enabled = 1;

    float integral = 0.0f, previous_error = 0.0f;

    while (running) {
        float temperature = 0.0f;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && !read_ok) {
            if (read_temperature(&temperature) == 0) {
                read_ok = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Retrying temperature read (%d/%d)...\n", retries, MAX_RETRIES);
                    sleep(1);
                }
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Error: Failed to read temperature after %d retries.\n", MAX_RETRIES);
            log_data(0.0f, setpoint, 0.0f, 0);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float pid_output = pid_calculate(setpoint, temperature, &integral, &previous_error, kp, ki, kd);
        int pwm_duty_cycle_value = (int)pid_output;

        if (pwm_duty_cycle_value < 0) {
            pwm_duty_cycle_value = 0;
        } else if (pwm_duty_cycle_value > PWM_RANGE) {
            pwm_duty_cycle_value = PWM_RANGE;
        }

        pwm_duty_cycle = pwm_duty_cycle_value;
        set_heater(1);
        log_data(temperature, setpoint, pid_output, pwm_duty_cycle);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

