#define AHT20_ADDR     0x48
#define AHT20_CMD_MSB  0x2E
#define AHT20_CMD_LSB  0x00
#define AHT20_MEAS_MS  80
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_HIGH   60.0f
#define HUMIDITY_LOW    55.0f
#define POLL_INTERVAL_S 5
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_gpio_ready = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int aht20_trigger_and_read(int fd, float *humidity_out) {
    uint8_t cmd[2] = { AHT20_CMD_MSB, AHT20_CMD_LSB };
    uint8_t data[6];
