#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_ADDR 0xD0
#define BMP280_CHIP_ID_VAL 0x55
#define BMP280_RESET_ADDR 0xE0
#define BMP280_RESET_VAL 0xB6
#define BMP280_CTRL_MEAS_ADDR 0xF4
#define BMP280_CONFIG_ADDR 0xF5
#define BMP280_PRESS_MSB_ADDR 0xF7
#define BMP280_TEMP_MSB_ADDR 0xFA
#define BMP280_CALIB_ADDR 0x88
#define BMP280_CALIB_LEN 24
#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_SEC 2
#define CONVERSION_DELAY_US 10000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_calibration_data(int handle) {
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2cReadI2CBlockData(handle, BMP280_CALIB_ADDR, (char *)buf, BMP280_CALIB_LEN) != BMP280_CALIB_LEN) {
        return -1;
    }
    calib.dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    calib.dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    calib.dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    calib.dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    calib.dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T, bmp280_calib_data *c) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)c->dig_T1 << 1))) * ((int32_t)c->dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)c->dig_T1)) * ((adc_T >> 4) - ((int32_t)c->dig_T1))) >> 12) * ((int32_t)c->dig_T3)) >> 14;
    return var1 + var2;
}

static uint32_t compensate_pressure(int32_t adc_P, bmp280_calib_data *c) {
    int32_t var1, var2;
    uint32_t p;
    var1 = (compensate_temperature(adc_P, c) >> 1) - 64000;
    var2 = ((var1 >> 2) * (var1 >> 2)) >> 11;
    var2 = (var2 * (int32_t)c->dig_P6) >> 2;
    var2 = var2 + ((var1 * (int32_t)c->dig_P5) << 1);
    var2 = (var2 >> 2) + ((int32_t)c->dig_P4 << 16);
    var1 = (((var1 * var1) >> 13) * (int32_t)c->dig_P3) >> 12;
    var1 = (var1 * (int32_t)c->dig_P2) >> 14;
    var1 = (var1 * (int32_t)c->dig_P1) >> 15;
    if (var1 == 0) {
        return 0;
    }
    p = (((uint32_t)(1048576 - adc_P) << 12) - (var2 >> 12)) * 3125;
    p = (p / (uint32_t)var1) << 1;
    var1 = ((int32_t)c->dig_P9 * (int32_t)(p >> 3) * (int32_t)(p >> 3)) >> 13;
    var2 = ((int32_t)(p >> 2) * (int32_t)c->dig_P8) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + (int32_t)c->dig_P7) >> 4));
    return p;
}

static int read_bmp280(int handle, float *pressure) {
    uint8_t buf[6];
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cWriteByteData(handle, BMP280_CTRL_MEAS_ADDR, 0x27);
        if (status < 0) {
            retries--;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(CONVERSION_DELAY_US);

        status = i2cReadI2CBlockData(handle, BMP280_PRESS_MSB_ADDR, (char *)buf, 6);
        if (status == 6) {
            int32_t raw_pressure = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
            int32_t raw_temp = (buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);
            int32_t adc_T = compensate_temperature(raw_temp, &calib);
            uint32_t adc_P = compensate_pressure(raw_pressure, &calib);
            *pressure = (float)adc_P / 256.0;
            return 0;
        }
        retries--;
        gpioDelay(100000);
    }
    return -1;
}

static void log_pressure_data(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int chip_id = i2cReadByteData(i2c_handle, BMP280_CHIP_ID_ADDR);
    if (chip_id != BMP280_CHIP_ID_VAL) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_RESET_ADDR, BMP280_RESET_VAL) < 0) {
        fprintf(stderr, "Error resetting BMP280\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(2000);

    if (read_calibration_data(i2c_handle) < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure;
    while (!terminate) {
        if (read_bmp280(i2c_handle, &pressure) == 0) {
            if (pressure > PRESSURE_HIGH_THRESHOLD || pressure < PRESSURE_LOW_THRESHOLD) {
                log_pressure_data(pressure);
            }
        } else {
            fprintf(stderr, "Error reading pressure data\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

