            int32_t adc_T = compensate_temperature(raw_temp, &calib);
            uint32_t adc_P = compensate_pressure(raw_pressure, &calib);
            *pressure = (float)adc_P / 256.0;
            return 0;
        }
        retries--;
        gpioDelay(100000);
    }
    return -1;
}

static void log_pressure_data(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int chip_id = i2cReadByteData(i2c_handle, BMP280_CHIP_ID_ADDR);
    if (chip_id != BMP280_CHIP_ID_VAL) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_RESET_ADDR, BMP280_RESET_VAL) < 0) {
        fprintf(stderr, "Error resetting BMP280\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(2000);

    if (read_calibration_data(i2c_handle) < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure;
    while (!terminate) {
        if (read_bmp280(i2c_handle, &pressure) == 0) {
            if (pressure > PRESSURE_HIGH_THRESHOLD || pressure < PRESSURE_LOW_THRESHOLD) {
                log_pressure_data(pressure);
            }
        } else {
            fprintf(stderr, "Error reading pressure data\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

