/*
 * Raspberry Pi 4B - TMP117 (TMP117) + AHT20 (AHT20) + PIR (GPIO17) logger
 *
 * Wiring:
 *   TMP117 SDA -> GPIO2  (I2C bus 1)
 *   TMP117 SCL -> GPIO3  (I2C bus 1)
 *   TMP117 VDD -> 3.3 V
 *   TMP117 GND -> GND
 *   AHT20 SDA -> GPIO2  (I2C bus 1)
 *   AHT20 SCL -> GPIO3  (I2C bus 1)
 *   AHT20 VDD -> 3.3 V
 *   AHT20 GND -> GND
 *   PIR IN    -> GPIO17 (gpiochip4 line 17)
 *
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x49
#define PIR_GPIO_LINE  17
#define LOG_FILE_NAME  "sensor_data.csv"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature from TMP117.
 * Returns 0 on success, -1 on failure.
 */
static int read_tmp117(int fd, float *temperature)
{
    unsigned char reg = 0x00;
    unsigned char data[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "TMP117: write reg failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (read(fd, data, 2) != 2) {
            fprintf(stderr, "TMP117: read data failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        int16_t raw = (int16_t)((data[0] << 8) | data[1]);
        *temperature = (175.0f * raw / 65536.0f) - 46.85f;
        return 0;
    }

    fprintf(stderr, "TMP117: failed after %d retries\n", MAX_RETRIES);
    return -1;
}

/*
 * Read humidity from AHT20.
 * Returns 0 on success, -1 on failure.
 */
static int read_aht20(int fd, float *humidity)
{
    unsigned char reg = 0x00;
    unsigned char data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "AHT20: write reg failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (read(fd, data, 3) != 3) {
            fprintf(stderr, "AHT20: read data failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        int32_t raw = ((int32_t)data[0] << 16) | ((int32_t)data[1] << 8) | data[2];
        *humidity = (125.0f * raw / 65536.0f) - 6.0f;
        if (*humidity < 0.0f)   *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;
        return 0;
    }

    fprintf(stderr, "AHT20: failed after %d retries\n", MAX_RETRIES);
    return -1;
}

/*
 * Read PIR sensor state.
 * Returns 0 on success, -1 on failure.
 */
static int read_pir(struct gpiod_line *line, int *state)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "PIR: gpiod_line_get_value failed: %s\n", strerror(errno));
        return -1;
    }
    *state = val;
    return 0;
}

/*
 * Log data to a CSV file.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(const char *filename, float temperature, float humidity, int motion_detected)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);
    fclose(fp);
    return 0;
}

int main(void)
{
    int tmp117_fd = -1, aht20_fd = -1, pir_line = -1;
    int ret_code = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C devices */
    tmp117_fd = open(I2C_BUS, O_RDWR);
    if (tmp117_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(tmp117_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
        goto cleanup;
    }

    aht20_fd = open(I2C_BUS, O_RDWR);
    if (aht20_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(aht20_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open GPIO chip and request PIR line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "pir_logger") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                PIR_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Check if sensors are present */
    int tmp117_present = (tmp117_fd >= 0);
    int aht20_present = (aht20_fd >= 0);

    if (!tmp117_present && !aht20_present) {
        fprintf(stderr, "No TMP117 or AHT20 sensor found. Logging to empty file.\n");
    } else {
        printf("TMP117 and AHT20 sensors found. Logging to %s\n", LOG_FILE_NAME);
    }

    /* Create log file at midnight */
    time_t now = time(NULL);
    struct tm tm_now;
    localtime_r(&now, &tm_now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_now);

    char log_path[128];
    snprintf(log_path, sizeof(log_path), "%s_%s.csv", LOG_FILE_NAME, timestamp);

    if (access(log_path, F_OK) != 0) {
        if (mkdir(log_path, 0755) != 0) {
            fprintf(stderr, "Failed to create log file '%s': %s\n", log_path, strerror(errno));
            goto cleanup;
        }
    }

    /* Main loop */
    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int motion_detected = 0;

        if (read_tmp117(tmp117_fd, &temperature) != 0) {
            fprintf(stderr, "TMP117 read failed; skipping sample\n");
        } else if (read_aht20(aht20_fd, &humidity) != 0) {
            fprintf(stderr, "AHT20 read failed; skipping sample\n");
        } else {
            if (read_pir(pir_line, &motion_detected) != 0) {
                fprintf(stderr, "PIR read failed; skipping sample\n");
            } else {
                if (log_data(log_path, temperature, humidity, motion_detected) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                } else {
                    printf("%s  T=%.2f C  H=%.2f %%  M=%d\n",
                           timestamp, temperature, humidity, motion_detected);
                }
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++) {
            usleep(100 * 1000);
        }
    }

    ret_code = EXIT_SUCCESS;

cleanup:
    if (pir_line >= 0) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (tmp117_fd >= 0) {
        close(tmp117_fd);
    }
    if (aht20_fd >= 0) {
        close(aht20_fd);
    }
    return ret_code;
}

