#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int load_cpu_percent(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error: cannot read /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *p = strstr(line, "cpu");
    if (!p) {
        fprintf(stderr, "Error: /proc/stat does not contain cpu line\n");
        return -1;
    }

    char *end;
    long user = strtol(p + 1, &end, 10);
    char *p2 = strstr(line, "system");
    if (!p2) {
        fprintf(stderr, "Error: /proc/stat does not contain system line\n");
        return -1;
    }
    long system = strtol(p2 + 1, &end, 10);
    char *p3 = strstr(line, "idle");
    if (!p3) {
        fprintf(stderr, "Error: /proc/stat does not contain idle line\n");
        return -1;
    }
    long idle = strtol(p3 + 1, &end, 10);

    long total = user + system + idle;
    if (total <= 0) {
        fprintf(stderr, "Error: total CPU usage is zero\n");
        return -1;
    }

    long user_pct = (user * 100) / total;
    long system_pct = (system * 100) / total;
    long idle_pct = (idle * 100) / total;

    long cpu_pct = user_pct + system_pct - idle_pct;
    if (cpu_pct < 0) cpu_pct = 0;
    if (cpu_pct > 100) cpu_pct = 100;

    return (int)cpu_pct;
}

static void set_led_color(int r, int g, int b)
{
    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BLUE_PIN,  PWM_RANGE - b);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: cannot install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: cannot install SIGTERM handler: %s\n", strerror(errno));
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: cannot set PWM range\n");
        gpioTerminate();
        return 1;
    }

    set_led_color(0, 0, 0);

    int last_cpu = -1;

    while (g_running) {
        int cpu = load_cpu_percent();
        if (cpu < 0) {
            gpioTerminate();
            return 1;
        }

        if (cpu != last_cpu) {
            int r, g, b;
            if (cpu <= 50) {
                r = 0; g = PWM_RANGE; b = 0;
            } else if (cpu <= 100) {
                r = 0; g = PWM_RANGE; b = PWM_RANGE - (PWM_RANGE - r);
            } else {
                r = PWM_RANGE; g = 0; b = 0;
            }
            set_led_color(r, g, b);
            last_cpu = cpu;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_led_color(0, 0, 0);
    gpioTerminate();
    return 0;
}

