#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define FAN_GPIO          18          /* BCM 18 – hardware PWM0 */
#define SPI_CHANNEL       0           /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED         500000      /* 500 kHz – MAX31855 max is 1 MHz */
#define SPI_FLAGS         0           /* Mode 0, active-low CE */
#define PWM_FREQUENCY     1000        /* 1 kHz – typical for 4-wire PC fans */
#define PWM_RANGE         255         /* 8-bit resolution */
#define BUFFER_SIZE       20
#define SAMPLE_PERIOD_US  1000000     /* 1 second */
#define MAX_CONSECUTIVE_ERRORS 10

/* ----------------------------- Data structures ----------------------------- */
typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty_cycle;
} DataPoint;

typedef struct {
    DataPoint data[BUFFER_SIZE];
    int      head;
    int      count;
} CircularBuffer;

/* ----------------------------- Globals ------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static CircularBuffer g_buffer;

/* ----------------------------- Prototypes --------------------------------- */
static int  init_spi(void);
static int  read_max31855(float *temperature);
static int  compute_duty_cycle(float temperature);
static void update_fan(int duty_cycle);
static void add_to_buffer(CircularBuffer *buf, time_t ts, float temp, int duty);
static void signal_handler(int sig);
static void print_buffer(const CircularBuffer *buf);

/* ----------------------------- SPI / MAX31855 ----------------------------- */
static int init_spi(void)
{
    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio code %d)\n", handle);
        return -1;
    }
    return handle;
}

/*
 * Read a MAX31855 thermocouple amplifier over SPI.
 * Returns 0 on success and stores temperature in *temperature.
 * Returns -1 on any SPI transfer error.
 */
static int read_max31855(float *temperature)
{
    if (temperature == NULL) {
        fprintf(stderr, "Error: NULL temperature pointer\n");
        return -1;
    }

    /*
     * MAX31855 SPI protocol (3-byte transfer, MSB-first):
     *   Byte 0: 0x00  (don't care)
     *   Byte 1: 0x01  (start bit)
     *   Byte 2: 0x00  (don't care) + 12-bit thermocouple data + fault flag
     */
    char tx[3] = { 0x00, 0x01, 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS), tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3)\n", ret);
        return -1;
    }

    /*
     * 12-bit thermocouple data is in the low 4 bits of rx[1] and all 8 bits
     * of rx[2].  rx[1] is the low 2 bits (bits 7:6) and rx[2] is the full 8 bits.
     */
    uint16_t raw = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)(uint8_t)rx[2];

    /*
     * Fault flag is the 4th bit of rx[1] (bits 5:4) and the 8th bit of
     * rx[2] (bits 7:0).  If either is set, a fault occurred.
     */
    if (raw & 0x0004) {
        fprintf(stderr, "Warning: MAX31855 fault detected (raw=0x%04X)\n", raw);
        return -1;
    }

    /*
     * Thermocouple temperature: bits 11:4, signed 12-bit.
     * Sign-extend from 12 bits to 16 bits.
     */
    int16_t temp_raw = (int16_t)(raw >> 4);
    if (temp_raw & 0x0800) {
        temp_raw |= 0xF000;
    }
    *temperature = (float)temp_raw * 0.25f;
    return 0;
}

/* ----------------------------- Fan curve ------------------------------- */
static int compute_duty_cycle(float temperature)
{
    if (temperature < 25.0f) {
        return 0;
    }
    if (temperature < 40.0f) {
        return (int)((temperature - 25.0f) / 15.0f * 128.0f);
    }
    if (temperature < 60.0f) {
        return 128 + (int)((temperature - 40.0f) / 20.0f * 128.0f);
    }
    return 255;
}

/* ----------------------------- Fan control ------------------------------- */
static void update_fan(int duty_cycle)
{
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for duty %d\n", duty_cycle);
    }
}

/* ----------------------------- Circular buffer --------------------------- */
static void add_to_buffer(CircularBuffer *buf, time_t ts, float temp, int duty)
{
    buf->data[buf->head].timestamp  = ts;
    buf->data[buf->head].temperature = temp;
    buf->data[buf->head].duty_cycle = duty;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) {
        buf->count++;
    }
}

static void print_buffer(const CircularBuffer *buf)
{
    printf("\n--- Circular buffer contents (%d entries) ---\n", buf->count);
    int start = (buf->count < BUFFER_SIZE) ? 0 : buf->head;
    for (int i = 0; i < buf->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts_str[32];
        struct tm tm_info;
        localtime_r(&buf->data[idx].timestamp, &tm_info);
        strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Temp: %.2f C  Duty: %d\n",
               ts_str, buf->data[idx].temperature, buf->data[idx].duty_cycle);
    }
    printf("-----------------------------------------------\n");
}

/* ----------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    int spi_handle = init_spi();
    if (spi_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO for hardware PWM */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    update_fan(0);  /* start with fan off */

    /* Initialize circular buffer */
    g_buffer.head  = 0;
    g_buffer.count = 0;

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Fan control started.  SPI ch%d @ %d kHz, PWM GPIO %d @ %d Hz, "
           "buffer %d entries.  Press Ctrl+C to exit.\n",
           SPI_CHANNEL, SPI_SPEED, FAN_GPIO, PWM_FREQUENCY, BUFFER_SIZE);

    int consecutive_errors = 0;

    while (g_running) {
        float temperature;
        int duty_cycle;

        if (read_max31855(&temperature) != 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: MAX31855 read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Fatal: too many MAX31855 errors, aborting.\n");
                break;
            }
            update_fan(0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        duty_cycle = compute_duty_cycle(temperature);
        update_fan(duty_cycle);

        time_t now = time(NULL);
        add_to_buffer(&g_buffer, now, temperature, duty_cycle);

        printf("T=%.2f C  Duty=%d  (buffer %d entries)\n",
               temperature, duty_cycle, g_buffer.count);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ----------------------------- Cleanup ------------------------------- */
    update_fan(0);
    spiClose(spi_handle);
    gpioTerminate();

    print_buffer(&g_buffer);
    printf("Fan control stopped.\n");
    return EXIT_SUCCESS;
}

