#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL_SEC 5

#define MAX31865_RTD_STATUS_REG 0x00
#define MAX31865_RTD_DATA_REG 0x01
#define MAX31865_RTD_CONFIG_REG 0x02

#define RTD_FAULT_BIT 0x01
#define RTD_BUSY_BIT 0x02

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    if (value == NULL) {
        return -1;
    }

    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI read to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    *value = rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI write to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return 0;
}

static int read_rtd_temperature(float *temperature) {
    uint8_t status = 0;
    uint8_t rtd_data = 0;

    if (spi_read_register(MAX31865_RTD_STATUS_REG, &status) < 0) {
        return -1;
    }

    if (status & RTD_BUSY_BIT) {
        return 1;
    }

    if (status & RTD_FAULT_BIT) {
        fprintf(stderr, "RTD fault detected (status=0x%02X)\n", status);
        return -1;
    }

    if (spi_read_register(MAX31865_RTD_DATA_REG, &rtd_data) < 0) {
        return -1;
    }

    uint32_t rtd_value = ((uint32_t)rtd_data << 16) | ((uint32_t)rtd_data << 8) | rtd_data;
    rtd_value &= 0x7FFFFFFF;

    *temperature = callendar_van_duzen(rtd_value);
    return 0;
}

static float callendar_van_duzen(uint32_t rtd_value) {
    const float A = 0.00390883;
    const float B = -0.0000005775;
    const float C = 0.00000000000000000123456789;

    float r0 = 3.90883;
    float t = (rtd_value - r0) / (r0 * (1.0f + B * rtd_value));
    t = t * (1.0f + A * rtd_value);
    t = t * (1.0f + C * rtd_value);
    return t;
}

static void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_fp, "%s,%.2f\n", timestamp, temperature);
    fflush(log_fp);
}

static void cleanup(void) {
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "Timestamp,Temperature\n");
        fflush(log_fp);
    }

    printf("Starting RTD temperature logging. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature = 0.0f;
        int ret = read_rtd_temperature(&temperature);

        if (ret == 0) {
            log_temperature(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else if (ret < 0) {
            fprintf(stderr, "Error reading RTD temperature.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

