/*
 * BMP180 Pressure Monitor with Alert System
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: BMP180 at I2C address 0x54 (7-bit)
 * Alert:  GPIO24 (active-high)
 *
 * Build:  gcc -O2 -Wall -o bmp180_monitor bmp180_monitor.c -lpigpio -lrt
 * Run:    sudo ./bmp180_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BMP180_ADDR          0x54          /* BMP180 default 7-bit address */
#define BMP180_REG_CONTROL   0xF4          /* ODR=1Hz, mode=temp+press */
#define BMP180_REG_MSB       0xF6          /* result MSB */
#define BMP180_REG_LSB       0xF7          /* result LSB */
#define BMP180_REG_XLSB      0xF8          /* result XLSB */
#define BMP180_REG_CAL_AC1   0xAA          /* AC1 auto-increment */
#define BMP180_CAL_LEN       22            /* 22 bytes: AC1..D1 */
#define BMP180_CMD_TEMP      0x2E          /* temp measurement */
#define BMP180_CMD_PRESSURE  0x34          /* pressure measurement */
#define BMP180_OSS           0
#define BMP180_REF_PRESSURE  25.0          /* Pa */
#define BMP180_REF_TEMP      25.0          /* °C */
#define BMP180_SPOUT_DELAY   1000          /* 1 ms */
#define SAMPLE_PERIOD_US     50000         /* 50 ms */
#define BUFFER_SIZE          60            /* 60 s */
#define ALERT_THRESHOLD      5.0           /* hPa */
#define ALERT_GPIO           24
#define TIMER_ID             0

/* ----------------------------- Globals ----------------------------------- */
static int      i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* ----------------------------- Types ------------------------------------- */
typedef struct {
    time_t timestamp;
    double  pressure;
} PressureSample;

typedef struct {
    PressureSample buffer[BUFFER_SIZE];
    int          head;
    int          count;
} CircularBuffer;

/* ----------------------------- Prototypes -------------------------------- */
static int  bmp180_read_calibration(int h, int16_t *ac1, int16_t *ac2,
                                    int16_t *ac3, uint16_t *ac4,
                                    uint16_t *ac5, uint16_t *ac6,
                                    int16_t *b1, int16_t *b2,
                                    int16_t *mb, int16_t *mc,
                                    int16_t *md);
static int  bmp180_read_raw(int h, int32_t *ut, int32_t *up);
static int  bmp180_read_pressure(int h, int32_t *pressure);
static double calculate_rolling_average(const CircularBuffer *cb);
static void  trigger_alert(double avg_pressure);
static void  signal_handler(int sig);
static void  cleanup(void);

/* ----------------------------- BMP180 helpers ----------------------------- */

/*
 * Read 22 calibration bytes starting at 0xAA (auto-increment).
 * Returns 0 on success, -1 on I2C failure.
 */
static int bmp180_read_calibration(int h, int16_t *ac1, int16_t *ac2,
                                    int16_t *ac3, uint16_t *ac4,
                                    uint16_t *ac5, uint16_t *ac6,
                                    int16_t *b1, int16_t *b2,
                                    int16_t *mb, int16_t *mc,
                                    int16_t *md)
{
    uint8_t buf[22];
    if (i2cReadI2CBlockData(h, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "[BMP180] I2C read calibration failed\n");
        return -1;
    }
    *ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    *ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    *ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    *ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    *ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    *ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    *b1  = (int16_t)((buf[12] << 8) | buf[13]);
    *b2  = (int16_t)((buf[14] << 8) | buf[15]);
    *mb  = (int16_t)((buf[16] << 8) | buf[17]);
    *mc  = (int16_t)((buf[18] << 8) | buf[19]);
    *md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

/*
 * Trigger a temperature measurement (no OSS).
 */
static int bmp180_read_raw(int h, int32_t *ut)
{
    if (i2cWriteByteData(h, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "[BMP180] temperature command failed\n");
        return -1;
    }
    gpioDelay(BMP180_SPOUT_DELAY);
    uint8_t buf[2];
    if (i2cReadI2CBlockData(h, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "[BMP180] temperature read failed\n");
        return -1;
    }
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Trigger a pressure measurement (OSS=0).
 */
static int bmp180_read_pressure(int h, int32_t *pressure)
{
    if (i2cWriteByteData(h, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE) < 0) {
        fprintf(stderr, "[BMP180] pressure command failed\n");
        return -1;
    }
    gpioDelay(BMP180_SPOUT_DELAY);
    uint8_t buf[3];
    if (i2cReadI2CBlockData(h, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "[BMP180] pressure read failed\n");
        return -1;
    }
    *pressure = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    *pressure >>= (8 - BMP180_OSS);
    return 0;
}

/* ----------------------------- Circular buffer ----------------------------- */
static void circular_buffer_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void circular_buffer_add(CircularBuffer *cb, time_t ts, double pressure)
{
    cb->buffer[cb->head].timestamp  = ts;
    cb->buffer[cb->head].pressure  = pressure;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static double calculate_rolling_average(const CircularBuffer *cb)
{
    if (cb->count == 0) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i].pressure;
    return sum / (double)cb->count;
}

/* ----------------------------- Alert / timer ----------------------------- */
static void trigger_alert(double avg_pressure)
{
    if (avg_pressure > 0.0) {
        fprintf(stderr,
                "[ALERT] Pressure deviation: %.2f hPa (avg %.2f hPa)\n",
                avg_pressure, avg_pressure);
        if (gpioWrite(ALERT_GPIO, 1) < 0)
            fprintf(stderr, "[ALERT] Failed to set GPIO %d HIGH\n", ALERT_GPIO);
    }
}

static void trigger_timer(void)
{
    if (i2c_handle < 0) return;
    int32_t ut, up;
    if (bmp180_read_raw(i2c_handle, &ut) < 0) return;
    int32_t pressure;
    if (bmp180_read_pressure(i2c_handle, &pressure) < 0) return;
    double pressure_hpa = (double)pressure / 100.0;
    circular_buffer_add(&buffer, time(NULL), pressure_hpa);
    double avg = calculate_rolling_average(&buffer);
    trigger_alert(avg);
}

/* ----------------------------- Signal / cleanup ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioSetMode(ALERT_GPIO, PI_INPUT);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- alert GPIO ---- */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    /* ---- timer 0 (50 ms) ---- */
    if (gpioSetTimerFuncEx(TIMER_ID, 50, trigger_timer, NULL) < 0) {
        fprintf(stderr, "Failed to set timer %d\n", TIMER_ID);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, BMP180_ADDR, i2c_handle);
        gpioSetTimerFuncEx(TIMER_ID, 50, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- calibration ---- */
    int16_t ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md;
    if (bmp180_read_calibration(i2c_handle, &ac1, &ac2, &ac3, &ac4,
                               &ac5, &ac6, &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "BMP180 calibration read failed; sensor may be absent\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
