/*
 * BMP180 Pressure Sensor Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   BMP180 SDA -> GPIO2 (I2C1 SDA)
 *   BMP180 SCL -> GPIO3 (I2C1 SCL)
 *   BMP180 VCC -> 3.3V
 *   BMP180 GND -> GND
 *
 * Build: gcc -o bmp180_logger bmp180_logger.c -lpigpio -lrt
 * Run:   sudo ./bmp180_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x54
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define BMP180_OSS 0
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE 0x34

#define LOG_FILE "bmp180_log.txt"
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data from BMP180.\n");
        return -1;
    }

    ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);

    if (ac1 == 0 || ac1 == 0xFFFF || ac6 == 0 || ac6 == 0xFFFF) {
        fprintf(stderr, "Error: Invalid calibration data (sensor absent or bus error).\n");
        return -1;
    }

    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "Error: Failed to write temperature command to BMP180.\n");
        return -1;
    }
    gpioDelay(5000);

    uint8_t buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read raw temperature data from BMP180.\n");
        return -1;
    }

    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE + (BMP180_OSS << 6)) < 0) {
        fprintf(stderr, "Error: Failed to write pressure command to BMP180.\n");
        return -1;
    }
    gpioDelay(2000 + (3000 << BMP180_OSS));

    uint8_t buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read raw pressure data from BMP180.\n");
        return -1;
    }

    *up = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    return 0;
}

static int calculate_temperature(int32_t ut, float *temp) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    *temp = ((b5 + 8) >> 4) / 10.0f;
    return 0;
}

static int calculate_pressure(int32_t up, int32_t ut, float *press) {
    int32_t b6 = ut - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)ac1 * 4 + x3) << BMP180_OSS) + 2;
    b3 >>= 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    *press = (float)p;
    return 0;
}

static void log_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
    fflush(log_file);
}

static void timer_callback(void *userdata) {
    (void)userdata;

    int32_t ut, up;
    float temperature, pressure;

    if (read_raw_temperature(&ut) < 0) {
        fprintf(stderr, "Error: Failed to read raw temperature data.\n");
        return;
    }

    if (read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Error: Failed to read raw pressure data.\n");
        return;
    }

    if (calculate_temperature(ut, &temperature) < 0) {
        fprintf(stderr, "Error: Failed to calculate temperature.\n");
        return;
    }

    if (calculate_pressure(up, ut, &pressure) < 0) {
        fprintf(stderr, "Error: Failed to calculate pressure.\n");
        return;
    }

    log_data(temperature, pressure);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", BMP180_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration_data() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set up timer interrupt.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BMP180 logger started. Logging to %s every %d ms. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL_US / 1000);

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");

    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, NULL, NULL);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

