#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <math.h>

#define FAN_GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define LOG_FILE "fan_log.txt"
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;
static int log_fd = -1;
static int pwm_fd = -1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli / 1000;
}

static int map_temperature_to_duty_cycle(int temperature) {
    if (temperature < 40) {
        return 0;
    } else if (temperature > 70) {
        return PWM_RANGE;
    } else {
        return (int)(((float)(temperature - 40) / (70 - 40)) * PWM_RANGE);
    }
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (ioctl(pwm_fd, GPIO_PWM_SET_DUTYCYCLE, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(int temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fd < 0) {
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd < 0) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    if (write(log_fd, "%s, Temperature: %d, Duty Cycle: %d\n", timestamp, temperature, duty_cycle) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (pwm_fd >= 0) {
        set_fan_speed(0);
        close(pwm_fd);
        pwm_fd = -1;
    }
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        return 1;
    }

    pwm_fd = open("/sys/class/pwm/pwmchip0/export", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Error exporting PWM: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(pwm_fd, PWM_CHIP_REQUEST_OUTPUT, 0) < 0) {
        fprintf(stderr, "Error requesting PWM output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0/period", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Error opening PWM period file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (write(pwm_fd, "1000000", 8) < 0) {
        fprintf(stderr, "Error setting PWM period: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", O_WRONLY); pwm_fd < 0) {
        fprintf(stderr, "Error opening PWM duty cycle file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0/enable", O_WRONLY); pwm_fd < 0) {
        fprintf(stderr, "Error opening PWM enable file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (set_fan_speed(0) < 0) {
        cleanup();
        return 1;
    }

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int duty_cycle = map_temperature_to_duty_cycle(temperature);
        if (set_fan_speed(duty_cycle) < 0) {
            fprintf(stderr, "Error setting fan speed, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (log_data(temperature, duty_cycle) < 0) {
            fprintf(stderr, "Error logging data, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

