#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75_ADDR      0x32
#define LM75_REG_TEMP  0x00
#define ALERT_GPIO      18
#define BUFFER_SIZE     60
#define TEMP_THRESHOLD  28.0f
#define SAMPLE_PERIOD_S 1

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
    pthread_mutex_t mutex;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_alert_gpio = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, LM75_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    g_alert_gpio = gpioGetGPIO(ALERT_GPIO);
    if (g_alert_gpio < 0) {
        fprintf(stderr, "Error getting GPIO %d: %s\n",
                ALERT_GPIO, strerror(errno));
        return -1;
    }
    if (gpioSetMode(g_alert_gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n",
                ALERT_GPIO, strerror(errno));
        return -1;
    }
    if (gpioWrite(g_alert_gpio, 0) < 0) {
        fprintf(stderr, "Error initializing GPIO %d to LOW: %s\n",
                ALERT_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature)
{
    int raw;
    int rc;

    rc = i2cWriteByte(g_i2c_fd, LM75_REG_TEMP);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg select): %s\n", strerror(errno));
        return -1;
    }

    rc = i2cReadWordData(g_i2c_fd, LM75_REG_TEMP);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    if (rc == 0) {
        fprintf(stderr, "I2C read returned 0 (sensor absent or bus error)\n");
        return -1;
    }

    raw = (int)rc;
    *temperature = (float)raw / 16.0f;
    return 0;
}

static void add_to_buffer(CircularBuffer *cb, float value)
{
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

static float calculate_average(const CircularBuffer *cb)
{
    if (cb->count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / (float)cb->count;
}

static void *alert_thread(void *arg)
{
    (void)arg;
    while (g_running) {
        float avg_temp = 0.0f;
        pthread_mutex_lock(&g_running->mutex);
        avg_temp = calculate_average(&g_running->buffer);
        pthread_mutex_unlock(&g_running->mutex);

        if (avg_temp > TEMP_THRESHOLD) {
            if (gpioWrite(g_alert_gpio, 1) < 0) {
                fprintf(stderr, "Error turning on alert LED: %s\n",
                        strerror(errno));
            }
        } else {
            if (gpioWrite(g_alert_gpio, 0) < 0) {
                fprintf(stderr, "Error turning off alert LED: %s\n",
                        strerror(errno));
            }
        }
    }
    return NULL;
}

int main(void)
{
    CircularBuffer cb = {0};
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }

    pthread_t alert_tid;
    if (pthread_create(&alert_tid, NULL, alert_thread, NULL) != 0) {
        fprintf(stderr, "Error creating alert thread: %s\n", strerror(errno));
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(&cb, temperature);
            float avg = calculate_average(&cb);
            printf("Temperature: %.2f C, Average: %.2f C\n",
                   temperature, avg);
        } else {
            fprintf(stderr, "Failed to read temperature. Re-initializing I2C.\n");
            i2cClose(g_i2c_fd);
            g_i2c_fd = -1;
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
            }
        }
        sleep(SAMPLE_PERIOD_S);
    }

    pthread_join(alert_tid, NULL);
    pthread_mutex_destroy(&cb.mutex);
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
    }
    if (g_alert_gpio >= 0) {
        gpioWrite(g_alert_gpio, 0);
