        if (read_raw_temperature(fd, &raw_temp) < 0) {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            sleep(1);
            continue;
        }
        if (read_raw_pressure(fd, &raw_pressure) < 0) {
            fprintf(stderr, "Error reading pressure: %s\n", strerror(errno));
            sleep(1);
            continue;
        }
        int16_t t_fine;
        int16_t temp = calculate_temperature(raw_temp, &t_fine);
        int16_t p;
        if (calculate_pressure(raw_pressure, t_fine, &p) < 0) {
            fprintf(stderr, "Error calculating pressure: %s\n", strerror(errno));
            sleep(1);
            continue;
        }
        float temp_c = (float)temp;
        float pressure_hpa = (float)p / 100.0f;
        if (check_breach(temp_c, pressure_hpa)) {
            if (log_breach(temp_c, pressure_hpa) < 0) {
                fprintf(stderr, "Error logging breach\n");
