#define BMP180_REG_CAL_P4 0xD3
#define BMP180_REG_CAL_P5 0xD5
#define BMP180_REG_CAL_P6 0xD7
#define BMP180_REG_CAL_P7 0xD9
#define BMP180_REG_CAL_P8 0xDB
#define BMP180_REG_CAL_P9 0xDD
#define BMP180_REG_CAL_OSR 0xF5
#define BMP180_REG_CAL_ID 0xD0
#define BMP180_CAL_SIZE 22

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE 0x34

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t data_logging_enabled = 0;
static volatile sig_atomic_t last_interrupt_state = 1;
static volatile uint32_t last_interrupt_tick = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;
static int32_t b5;

static int i2c_read_reg(uint8_t reg, uint8_t *buf, uint32_t len) {
    if (write(i2c_fd, &reg, 1) != 1) return -1;
    if (read(i2c_fd, buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration_data() {
    uint8_t buf[BMP180_CAL_SIZE];
    if (i2c_read_reg(BMP180_REG_CAL_AC1, buf, BMP180_CAL_SIZE) < 0) return -1;
    ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    if (i2c_write_reg(BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2c_read_reg(BMP180_REG_MSB, buf, 2) < 0) return -1;
    *raw_temp = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    if (i2c_write_reg(BMP180_REG_CONTROL, BMP180_CMD_PRESSURE) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[3];
    if (i2c_read_reg(BMP180_REG_MSB, buf, 3) < 0) return -1;
    *raw_pressure = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    b5 = x1 + x2;
    return b5;
}

static int32_t compute_pressure(int32_t up, int32_t ut) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 2) + 2) / 4;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 2);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_data(int32_t pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, %.2f\n", timestamp, (double)pressure / 100.0);
    fflush(log_file);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    uint32_t elapsed = tick - last_interrupt_tick;
    if (elapsed < 200000) return;
    last_interrupt_tick = tick;
    if (level == 0 && last_interrupt_state != 0) {
        data_logging_enabled = !data_logging_enabled;
        printf("Data logging %s\n", data_logging_enabled ? "enabled" : "disabled");
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup() {
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    uint8_t id;
    if (i2c_read_reg(BMP180_REG_CAL_ID, &id, 1) < 0 || id != 0x55) {
        fprintf(stderr, "BMP180 not detected (ID=0x%02X)\n", id);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(27, PI_INPUT);
    gpioSetPullUpDown(27, PI_PUD_UP);
    if (gpioSetISRFuncEx(27, FALLING_EDGE, 0, interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("BMP180 data logger started. Press Ctrl+C to exit.\n");
    while (running) {
        if (data_logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) < 0 || read_raw_pressure(&up) < 0) {
                fprintf(stderr, "I2C read error\n");
            } else {
                int32_t b5 = compute_b5(ut);
                int32_t pressure = compute_pressure(up, ut);
                log_data(pressure);
            }
        }
        sleep(2);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

code:
/*
 * Raspberry Pi 3 Model B+ – MAX31855 thermocouple reader + PI heater controller
 *
 * Wiring:
 *   MAX31855 VIN  -> 3V3 (pin 1)
 *   MAX31855 GND  -> GND (pin 6)
 *   MAX31855 CLK  -> GPIO11 (SCLK, pin 23)
 *   MAX31854 CS   -> GPIO8  (CE0,  pin 24)
 *   MAX31854 DO   -> GPIO9  (MISO,  pin 21)
 *   MAX31854 SI   -> GPIO10 (MOSI,  pin 19)
 *   Heater relay  -> GPIO17 (IN1, pin 11)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o heater_control heater_control.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0  (GPIO8) */
#define SPI_SPEED      2000000    /* 2 MHz  */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define HEATER_GPIO    17         /* PWM output for solid-state relay */
#define PWM_RANGE      1000       /* 0..1000 -> 0.00..100.0% duty */
#define PWM_FREQ       1000       /* 1 kHz */
#define PWM_DUTY_MAX   8000       /* 80 % */

#define TARGET_TEMP    25.0f      /* Target temperature in °C */
#define LOG_FILE       "heater_log.csv"
#define SAMPLE_PERIOD  1.0        /* seconds */

/* MAX31855 fault codes */
#define MAX31855_FAULT_NONE  0x0000
#define MAX31855_FAULT_OPEN  0x0001
#define MAX31855_FAULT_SHORT 0x0002
#define MAX31855_FAULT_GND   0x0004
#define MAX31855_FAULT_VCC   0x0008

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  spi_read_max31855(int handle, float *temp_c, uint16_t *fault);
static int  calculate_duty_cycle(float temp_c, float target, uint16_t fault);
static void log_data(float temp_c, int duty_pct, const char *err_msg);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI read ---------------------------------- */
/*
 * MAX31855 SPI protocol (32-bit read, 8-bit return):
 *   Byte 0: 0x00  (don't care)
 *   Byte 1: 0x01  (read thermocouple temp)
 *   Byte 2: 0x00  (don't care)
 *   Byte 3: 0x00  (don't care)
 *   Byte 4: 0x00  (don't care)
 *   Byte 5: 0x00  (don't care)
 *   Byte 6: 0x00  (don't care)
 *   Byte 7: 0x00  (don't care)
 *
 * Response:
 *   Byte 1  = [CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC]
 *   Byte 2  = [CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC]
 *   Byte 3  = [CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC]
 *   Byte 4  = [CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC]
 *   Byte 5  = [CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC]
 *   Byte 6  = [CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC]
 *   Byte 7  = [CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC]
 *   Byte 8  = [CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC]
 *   Byte 9  = [CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC][CC]
 *   Byte 10 = fault code (0..31)
 *
 * 16-bit thermocouple temp in °C is in bits 15..4 of byte 8.
 */
static int spi_read_max31855(int handle, float *temp_c, uint16_t *fault)
{
    char tx[8] = {0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    char rx[8] = {0};

    if (handle < 0) {
        fprintf(stderr, "spi_read_max31855: invalid SPI handle\n");
        return -1;
    }

    int ret = spiXfer(handle, tx, rx, 8);
    if (ret != 8) {
        fprintf(stderr, "spi_read_max31855: SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[2];
    *fault = (raw & 0x07) | (raw >> 24);

    if (*fault != MAX31855_FAULT_NONE) {
        fprintf(stderr, "spi_read_max31855: MAX31855 fault code 0x%04X\n", *fault);
        return -1;
    }

    /* Thermocouple temperature: bits 15..4 of byte 8 */
    int16_t temp_raw = (int16_t)((raw >> 4) & 0x0FFF);
    *temp_c = (float)temp_raw * 0.25f;
    return 0;
}

/* ----------------------------- Duty-cycle calculation --------------------- */
static int calculate_duty_cycle(float temp_c, float target, uint16_t fault)
{
    float error = target - temp_c;
    int duty;

    if (fault & MAX31855_FAULT_OPEN) {
        fprintf(stderr, "calculate_duty_cycle: fault open circuit – heater OFF\n");
        duty = 0;
    } else if (fault & MAX31855_FAULT_SHORT) {
        fprintf(stderr, "calculate_duty_cycle: fault short to GND – heater OFF\n");
        duty = 0;
    } else if (fault & MAX31855_FAULT_GND) {
        fprintf(stderr, "calculate_duty_cycle: fault short to VCC – heater OFF\n");
        duty = 0;
    } else if (fault & MAX31855_FAULT_VCC) {
        fprintf(stderr, "calculate_duty_cycle: fault open to VCC – heater OFF\n");
        duty = 0;
    } else {
        duty = (int)(error * 1000.0f);
        if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
        if (duty < 0) duty = 0;
    }

    return duty;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(float temp_c, int duty_pct, const char *err_msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "1970-01-01 00:00:00", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    if (err_msg != NULL) {
        fprintf(g_log, "%s,ERROR,%s\n", ts, err_msg);
    } else {
        fprintf(g_log, "%s,%.2f,%d\n", ts, temp_c, duty_pct);
    }
    fflush(g_log);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Heater GPIO setup */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for HEATER_GPIO\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ);
    gpioPWM(HEATER_GPIO, 0);

    /* SPI open */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Log file */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen log");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log, "# timestamp,temperature_c,duty_cycle_pct,error_msg\n");
    fflush(g_log);

    printf("Heater control started. Target=%.1f°C, PWM=%d%%, log=%s\n",
           TARGET_TEMP, PWM_DUTY_MAX, LOG_FILE);

    while (g_running) {
        float temp_c = 0.0f;
        uint16_t fault = 0;

        if (spi_read_max31855(g_spi_handle, &temp_c, &fault) != 0) {
            fprintf(stderr, "SPI read failed – heater OFF\n");
            gpioPWM(HEATER_GPIO, 0);
            log_data(0.0f, 0, "SPI_READ_ERROR");
        } else {
            int duty = calculate_duty_cycle(temp_c, TARGET_TEMP, fault);
            gpioPWM(HEATER_GPIO, duty);
            log_data(temp_c, duty, NULL);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

