#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define PWM_RANGE  255
#define POLL_US    500000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int set_led_color(int r, int g, int b)
{
    if (gpioPWM(RED_PIN,  PWM_RANGE - b)  != 0) { fprintf(stderr, "gpioPWM(RED_PIN) failed\n"); return -1; }
    if (gpioPWM(GREEN_PIN, PWM_RANGE - g) != 0) { fprintf(stderr, "gpioPWM(GREEN_PIN) failed\n"); return -1; }
    if (gpioPWM(BLUE_PIN,  PWM_RANGE - r) != 0) { fprintf(stderr, "gpioPWM(BLUE_PIN) failed\n"); return -1; }
    return 0;
}

static int read_cpu_temp(float *temp_m_c)
{
    FILE *fp = fopen("cpu_temp.txt", "r");
    if (!fp) {
        fprintf(stderr, "fopen(cpu_temp.txt): %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "fgets: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr;
    long millideg = strtol(line, &endptr, 10);
    if (*endptr != '\0' || endptr == line) {
        fprintf(stderr, "Invalid temperature data: %s\n", line);
        return -1;
    }
    *temp_m_c = (float)millideg / 1000.0f;
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,  PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(RED_PIN,  PWM_RANGE) != 0 ||
        gpioPWM(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioPWM(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "gpioPWM init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        gpioPWM(RED_PIN,  PWM_RANGE);
        gpioPWM(GREEN_PIN, PWM_RANGE);
        gpioPWM(BLUE_PIN,  PWM_RANGE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp_m_c;
        if (read_cpu_temp(&temp_m_c) != 0) {
            fprintf(stderr, "Temperature read failed; skipping update\n");
        } else {
            int r, g, b;
            if (temp_m_c < 40000.0f) { r = g = b = 0; }
            else if (temp_m_c < 60000.0f) { r = 255; g = 0; b = 0; }
            else { r = g = 0; b = 255; }

            if (set_led_color(r, g, b) != 0) {
                fprintf(stderr, "LED write failed; continuing\n");
            }

            printf("Temp: %6.2f m°C  R:%3d G:%3d B:%3d\n",
                   temp_m_c, r, g, b);
            fflush(stdout);
        }
        gpioDelay(POLL_US);
    }

    /* Graceful shutdown: turn off all channels and release pigpio */
    gpioPWM(RED_PIN,  PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
    gpioTerminate();
    return EXIT_SUCCESS;
}

