#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define DHT22_TIMEOUT_US 100000
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_BIT_THRESHOLD 50
#define DHT22_BIT_LOW_US 50
#define DHT22_BIT_HIGH_US 50
#define DHT22_BIT_SETTLE_US 10

static volatile sig_atomic_t running = 1;
static int sockfd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void cleanup() {
    if (sockfd != -1) {
        close(sockfd);
        sockfd = -1;
    }
    gpioTerminate();
}

int read_dht22(float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_index = 0;
    int last_state = 1;
    int i;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(DHT22_START_LOW_US);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(DHT22_START_HIGH_US);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == last_state) {
        gpioDelay(1);
        timeout += 1;
        if (timeout > DHT22_TIMEOUT_US) {
            fprintf(stderr, "DHT22: Timeout waiting for response low.\n");
            return -1;
        }
    }
    timeout = 0;
    while (gpioRead(DHT22_GPIO) == last_state) {
        gpioDelay(1);
        timeout += 1;
        if (timeout > DHT22_TIMEOUT_US) {
            fprintf(stderr, "DHT22: Timeout waiting for response high.\n");
            return -1;
        }
    }
    last_state = 0;

    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == last_state) {
            gpioDelay(1);
            timeout += 1;
            if (timeout > DHT22_TIMEOUT_US) {
                fprintf(stderr, "DHT22: Timeout waiting for bit %d.\n", i);
                return -1;
            }
        }
        last_state = 1;

        if (i >= 4) {
            data[bit_index / 8] <<= 1;
            if (i % 2 == 0) {
                data[bit_index / 8] |= 1;
            }
            bit_index++;
        }

        if (bit_index == 8) {
            if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
                fprintf(stderr, "DHT22: Checksum error.\n");
                return -1;
            }
            bit_index = 0;
        }

        gpioDelay(DHT22_BIT_SETTLE_US);
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

int post_data(float temperature, float humidity) {
    char json_string[256];
    int retry_count = 0;

    while (retry_count < MAX_RETRIES) {
        snprintf(json_string, sizeof(json_string),
                 "{\"temperature\": %.1f, \"humidity\": %.1f}",
                 temperature, humidity);

        struct sockaddr_in server_addr;
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) {
            perror("socket");
            retry_count++;
            continue;
        }

        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(80);
        if (inet_pton(AF_INET, "yourserver.com", &server_addr.sin_addr) <= 0) {
            perror("inet_pton");
            close(sockfd);
            retry_count++;
            continue;
        }

        if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            perror("connect");
            close(sockfd);
            retry_count++;
            continue;
        }

        if (send(sockfd, json_string, strlen(json_string), 0) < 0) {
            perror("send");
            close(sockfd);
            retry_count++;
            continue;
        }

        close(sockfd);
        sockfd = -1;
        return 0;
    }

    fprintf(stderr, "Failed to post data after %d retries.\n", MAX_RETRIES);
    return -1;
}

int main() {
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    while (running) {
        if (read_dht22(&temperature, &humidity) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
            if (post_data(temperature, humidity) != 0) {
                fprintf(stderr, "Failed to post data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor.\n");
        }
        sleep(5);
    }

    cleanup();
    return 0;
}

