#include <pigpio.h>

#define BMP180_ADDR 0x54
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define BMP180_OSS 3
#define BMP180_CONV_DELAY_US 26000
#define DEBOUNCE_US 200000
#define LOG_INTERVAL_S 2
#define LOG_FILE "pressure_log.txt"
#define BUTTON_GPIO 4

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static int i2c_handle = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;
    if (diff >= DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
    last_tick = tick;
}

static int read_calibration(void) {
    ac1 = (int16_t)((int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1) & 0xFF);
    ac2 = (int16_t)((int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2) & 0xFF);
    ac3 = (int16_t)((int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3) & 0xFF);
    ac4 = (uint16_t)((uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4) & 0xFF);
    ac5 = (uint16_t)((uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5) & 0xFF);
    ac6 = (uint16_t)((uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6) & 0xFF);
    b1 = (int16_t)((int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1) & 0xFF);
    b2 = (int16_t)((int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2) & 0xFF);
    mb = (int16_t)((int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB) & 0xFF);
    mc = (int16_t)((int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC) & 0xFF);
    md = (int16_t)((int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD) & 0xFF);
    if (ac1 == 0 || ac1 == -1 || ac2 == 0 || ac2 == -1 || ac3 == 0 || ac3 == -1) {
        fprintf(stderr, "BMP180 calibration data invalid\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) return -1;
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) return -1;
    gpioDelay(BMP180_CONV_DELAY_US);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5(ut);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p / 100.0;
}

static int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed\n");
        gpioTerminate();
        return 1;
    }
    if (read_calibration() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "ISR setup failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    printf("BMP180 logging ready. Press button on GPIO4 to toggle logging.\n");
    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) == 0 && read_raw_pressure(&up) == 0) {
                float pressure = compute_pressure(up, ut);
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "log_pressure failed\n");
                }
            } else {
                fprintf(stderr, "sensor read error\n");
            }
        }
        sleep(LOG_INTERVAL_S);
    }
    i2cClose(i2c_handle);
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

