#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 2000
#define LOOP_DELAY_S 10
#define MAX_RESPONSE_LEN 256
#define MAX_POST_LEN 512
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 20
#define DHT22_TIMEOUT_US 1000

static volatile sig_atomic_t running = 1;
static char *api_url = "http://your-the-library.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_msg(int priority, const char *msg) {
    syslog(priority, "%s", msg);
}

static int read_dht22(int gpio, float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    uint32_t tick;
    int bit_idx = 0;
    int last_state = 1;
    int timeout = 0;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(DHT22_START_LOW_US);
    gpioWrite(gpio, 1);
    gpioDelay(DHT22_START_HIGH_US);
    gpioSetMode(gpio, PI_INPUT);

    for (int i = 0; i < 40; i++) {
        tick = gpioTick();
        while (gpioRead(gpio) == last_state) {
            if (tick - last_state > DHT22_TIMEOUT_US) {
                log_msg(LOG_ERR, "DHT22 timeout waiting for response start");
                return -1;
            }
            gpioDelay(1);
        }
        last_state = gpioRead(gpio);

        if (i >= 4) {
            data[bit_idx / 8] <<= 1;
            if (i % 2 == 0) {
                data[bit_idx / 8] |= 1;
            }
            bit_idx++;
            if (bit_idx == 5) {
                break;
            }
        }
    }

    if (bit_idx < 40) {
        log_msg(LOG_ERR, "DHT22 incomplete data read");
        return -1;
    }

    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        log_msg(LOG_ERR, "DHT22 checksum mismatch");
        return -1;
    }

    *humidity = ((float)data[0] + (float)data[1] + (float)data[2]) / 10.0f;
    *temperature = ((float)data[3] + (float)data[4]) / 10.0f;
    return 0;
}

static int post_data(const char *url, const char *json_str) {
    char request[MAX_POST_LEN];
    int ret;

    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             url, url, strlen(json_str), json_str);

    ret = system(request);
    if (ret == -1) {
        log_msg(LOG_ERR, "system() failed to execute curl");
        return -1;
    }
    if (ret != 0) {
        log_msg(LOG_ERR, "curl returned non-zero exit code");
        return -1;
    }

    char *resp = system("curl -s -m 10 -o /dev/null -w \"http_code=%http_code\" http://%s/api/humidity");
    if (!resp) {
        log_msg(LOG_ERR, "curl returned NULL");
        return -1;
    }

    int http_code = 0;
    if (sscanf(resp, "http_code=%d", &http_code) == 1) {
        if (http_code < 200 || http_code >= 300) {
            log_msg(LOG_ERR, "HTTP error: %d", http_code);
            return -1;
        }
    } else {
        log_msg(LOG_ERR, "HTTP parse error");
        return -1;
    }

    free(resp);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val < 0 || val > 65535) {
            fprintf(stderr, "Invalid URL format. Using default: %s\n", api_url);
            return 1;
        }
        api_url = argv[1];
    }

    openlog("dht22_logger", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_msg(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    log_msg(LOG_INFO, "DHT22 logger started");

    while (running) {
        float humidity = 0.0f, temperature = 0.0f;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_dht22(DHT22_GPIO, &humidity, &temperature) == 0) {
                success = 1;
                break;
            }
            log_msg(LOG_WARNING, "DHT22 read failed, retrying...");
            sleep(RETRY_DELAY_MS / 1000);
        }

        if (success) {
            char json_str[MAX_RESPONSE_LEN];
            snprintf(json_str, sizeof(json_str),
                     "{\"humidity\": %.2f, \"temperature\": %.2f}", humidity, temperature);

            char *json_copy = strdup(json_str);
            if (!json_copy) {
                log_msg(LOG_ERR, "strdup failed");
                continue;
            }

            int retry_count = 0;
            int post_success = 0;
            while (retry_count < MAX_RETRIES && running) {
                if (post_data(api_url, json_copy) == 0) {
                    post_success = 1;
                    break;
                }
                retry_count++;
                sleep(1);
            }

            free(json_copy);

            if (post_success) {
                log_msg(LOG_INFO, "Data posted successfully");
            } else {
                log_msg(LOG_ERR, "Failed to post data after %d retries", MAX_RETRIES);
            }
        } else {
            log_msg(LOG_ERR, "Failed to read DHT22 after %d attempts", MAX_RETRIES);
        }

        for (int i = 0; i < LOOP_DELAY_S && running; i++) {
            sleep(1);
        }
    }

    log_msg(LOG_INFO, "Shutting down");
    gpioTerminate();
    closelog();
    return 0;
}

