#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5
#define TEMP_MIN 45.0
#define TEMP_MAX 65.0
#define TEMP_MIN_OFF 45.0
#define TEMP_MIN_1 55.0
#define TEMP_MIN_2 65.0
#define TEMP_MAX_3 65.0
#define MAX_FAN_STATE 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temp_out) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    int temp_raw;
    if (fscanf(fp, "%d", &temp_raw) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp_out = (float)temp_raw / 1000.0;
    return 0;
}

static int read_fan_state(int *state_out) {
    FILE *fp = fopen(FAN_STATE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }
    int fan_state;
    if (fscanf(fp, "%d", &fan_state) != 1) {
        fprintf(stderr, "Error reading fan state from %s\n", FAN_STATE_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *state_out = fan_state;
    return 0;
}

static int set_fan_speed(int state) {
    FILE *fp = fopen(FAN_STATE_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for write: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state to %s: %s\n", FAN_STATE_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int log_fan_speed(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s for append: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s - Fan state: %d\n", timestamp, state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int determine_fan_speed(float temperature) {
    if (temperature < TEMP_MIN_OFF) {
        return 0;
    } else if (temperature < TEMP_MIN_1) {
        return 1;
    } else if (temperature < TEMP_MIN_2) {
        return 2;
    } else if (temperature < TEMP_MAX_3) {
        return MAX_FAN_STATE;
    } else {
        return MAX_FAN_STATE;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int current_fan_state = 0;
    int previous_fan_state = 0;
    int fan_speed = 0;

    while (running) {
        float temperature;
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Temperature read failed, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int new_fan_state = determine_fan_speed(temperature);

        if (new_fan_state != current_fan_state) {
            if (set_fan_speed(new_fan_state) == 0) {
                if (new_fan_state > previous_fan_state) {
                    if (log_fan_speed(new_fan_state) != 0) {
                        fprintf(stderr, "Failed to log fan speed change\n");
                    }
                } else {
                    if (log_fan_speed(new_fan_state) != 0) {
                        fprintf(stderr, "Failed to log fan speed change\n");
                    }
                }
                previous_fan_state = new_fan_state;
                fan_speed = new_fan_state;
            } else {
                fprintf(stderr, "Failed to set fan speed\n");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (set_fan_speed(0) != 0) {
        fprintf(stderr, "Failed to set fan to off on shutdown\n");
    }

    if (log_fan_speed(0) != 0) {
        fprintf(stderr, "Failed to log shutdown fan state\n");
    }

    printf("Fan control program terminated gracefully.\n");
    return 0;
}

