#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define TARGET_TEMP 50.0
#define LOG_FILE "heater_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_TEMP 100.0
#define MIN_TEMP -50.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define ALPHA 0.5
#define MAX_PWM 100

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double integral = 0.0;
static double previous_error = 0.0;
static double last_valid_temp = 0.0;
static int heater_on = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (heater_on) {
        gpioPWM(HEATER_GPIO, 0);
        heater_on = 0;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

static int read_max31855(double *temperature) {
    if (spi_handle < 0) return -1;

    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed: returned %d\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000004) {
            fprintf(stderr, "MAX31855 fault: Open circuit\n");
        } else if (raw & 0x00000002) {
            fprintf(stderr, "MAX31855 fault: Short to GND\n");
        } else if (raw & 0x00000001) {
            fprintf(stderr, "MAX31855 fault: Short to VCC\n");
        } else {
            fprintf(stderr, "MAX31855 fault: Unknown\n");
        }
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    if (thermocouple_raw & 0x0800) {
        thermocouple_raw |= 0xF000;
    }
    *temperature = (double)thermocouple_raw * 0.25;
    return 0;
}

static double pid_control(double setpoint, double actual_temp) {
    double error = setpoint - actual_temp;
    integral += error * ALPHA;
    if (integral > 100.0) integral = 100.0;
    if (integral < 0.0) integral = 0.0;
    double derivative = (error - previous_error) / ALPHA;
    double output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    return output;
}

static void log_data(double temp, double pwm, double pid_out) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, pwm, pid_out);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double current_temp = 0.0;
    int first_sample = 1;

    while (running) {
        if (read_max31855(&current_temp) != 0) {
            fprintf(stderr, "Sensor read error, disabling heater\n");
            heater_on = 0;
            break;
        }

        if (first_sample) {
            if (current_temp < MIN_TEMP) {
                fprintf(stderr, "Temperature below min, setting to min\n");
                current_temp = MIN_TEMP;
            } else if (current_temp > MAX_TEMP) {
                fprintf(stderr, "Temperature above max, setting to max\n");
                current_temp = MAX_TEMP;
            }
            first_sample = 0;
        }

        double pid_output = pid_control(TARGET_TEMP, current_temp);

        if (current_temp > MAX_TEMP) {
            fprintf(stderr, "Temperature %.2f exceeds max, disabling heater\n", current_temp);
            current_temp = MAX_TEMP;
            heater_on = 0;
        } else if (current_temp < MIN_TEMP) {
            fprintf(stderr, "Temperature %.2f below min, disabling heater\n", current_temp);
            current_temp = MIN_TEMP;
            heater_on = 0;
        }

        int pwm_value = (int)(pid_output * PWM_RANGE / 100.0);
        if (pwm_value < 0) pwm_value = 0;
        if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;

        if (gpioPWM(HEATER_GPIO, pwm_value) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", HEATER_GPIO);
            break;
        }

        log_data(current_temp, pwm_value, pid_output);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

