#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float temperature, int duty_percent) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_percent) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

static int set_fan_speed(float temperature) {
    if (temperature < 40.0f) {
        return 0;
    } else if (temperature >= 70.0f) {
        return 100;
    } else {
        float fraction = (temperature - 40.0f) / (70.0f - 40.0f);
        return (int)(fraction * 100.0f);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, 100) != 0) {
        fprintf(stderr, "Failed to set PWM range to 100\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM duty cycle to 0\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Cooling system started. Logging to %s every %d seconds.\n", LOG_FILE, POLL_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float temperature = -200.0f;
        if (gpioRead(FAN_GPIO) == 0) {
            temperature = -100.0f;
        }

        int duty_percent = set_fan_speed(temperature);

        if (gpioPWM(FAN_GPIO, duty_percent) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty_percent);
        }

        if (log_data(temperature, duty_percent) != 0) {
            fprintf(stderr, "Logging failed for this reading.\n");
        }

        printf("Temperature: %.2f°C, Duty Cycle: %d%%\n", temperature, duty_percent);

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to turn off fan during shutdown\n");
    }

    gpioTerminate();
    printf("Cooling system stopped.\n");
    return EXIT_SUCCESS;
}

