#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_1_ADDR 0x20
#define SENSOR_2_ADDR 0x21
#define LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as per Sensirion SLF3S-1300F datasheet */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buf[3];
    int result;
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadDevice(handle, (char *)buf, 3);
        if (result == 3) {
            if (crc8(buf, 2) == buf[2]) {
                uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
                *flow_rate = (float)raw / 1000.0f;
                return 0;
            }
        }
        fprintf(stderr, "I2C read attempt %d failed (got %d bytes)\n", attempt + 1, result);
        gpioDelay(10000); /* 10 ms backoff before retry */
    }
    return -1;
}

static int log_flow_data(float flow1, float flow2) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];
    FILE *fp;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main(void) {
    int handle1 = -1, handle2 = -1;
    float flow1, flow2;
    int rc1, rc2;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    handle1 = i2cOpen(I2C_BUS, SENSOR_1_ADDR, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1 (addr 0x%02X): %d\n", SENSOR_1_ADDR, handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    handle2 = i2cOpen(I2C_BUS, SENSOR_2_ADDR, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2 (addr 0x%02X): %d\n", SENSOR_2_ADDR, handle2);
        i2cClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        rc1 = read_flow_rate(handle1, &flow1);
        rc2 = read_flow_rate(handle2, &flow2);

        if (rc1 == 0 && rc2 == 0) {
            if (log_flow_data(flow1, flow2) != 0) {
                fprintf(stderr, "Failed to log flow data\n");
            }
        } else {
            fprintf(stderr, "Sensor 1 read failed (rc=%d), Sensor 2 read failed (rc=%d)\n", rc1, rc2);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

