/*
 * Magnetic Rotary Encoder Monitor for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - Two TMAG5110A1 Hall-Effect latch sensors (magnetic rotary encoder)
 *     - Channel A -> GPIO17 (physical pin 11)
 *     - Channel B -> GPIO18 (physical pin 12)
 *
 * Wiring:
 *   - VCC -> 3.3V (Pin 1)
 *   - GND -> GND  (Pin 9)
 *   - AOUT -> GPIO17 (Pin 11)
 *   - BOUT -> GPIO18 (Pin 12)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o encoder_monitor encoder_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./encoder_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define GPIO_AOUT 17
#define GPIO_BOUT 18

#define LOG_FILE "encoder_log.txt"

#define PULSES_PER_REVOLUTION 360.0
#define SAMPLE_DELAY_US 10000   /* 10 ms between samples */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Helpers ----------------------------------- */

/*
 * Read the current state of the two Hall-Effect sensors.
 * Returns:
 *   0  - valid quadrature state
 *   -1  - invalid state (e.g., both inputs low)
