#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LED_GPIO       17
#define IR_THRESHOLD   2000
#define LOG_FILE       "adpd144ri_log.txt"
#define SAMPLE_US      100000

/* ADPD144RI register addresses (from datasheet) */
#define REG_RED_DATA   0x00
#define REG_IR_DATA    0x02
#define REG_CONFIG     0x03

/* Config register bits (example values) */
#define CONFIG_GAIN    0x01
#define CONFIG_MODE    0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", I2C_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    gpioWrite(LED_GPIO, 0);
    return 0;
}

static int init_log(void) {
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,red,ir\n");
        fflush(g_log_fp);
    }
    return 0;
}

static int configure_sensor(void) {
    /* Set gain and mode (example values) */
    if (i2c_write_reg8(g_i2c_fd, REG_CONFIG, CONFIG_GAIN) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_CONFIG, CONFIG_MODE) < 0) return -1;
    return 0;
}

static int read_sensor_data(uint16_t *red, uint16_t *ir) {
    uint8_t red_val, ir_val;
    if (i2c_read_reg8(g_i2c_fd, REG_RED_DATA, &red_val) < 0) return -1;
    if (i2c_read_reg8(g_i2c_fd, REG_IR_DATA, &ir_val) < 0) return -1;
    *red = (uint16_t)red_val;
    *ir = (uint16_t)ir_val;
    return 0;
}

static void log_data(uint16_t red, uint16_t ir) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_fp, "%s,%u,%u\n", ts, red, ir);
    fflush(g_log_fp);
}

static void control_led(uint16_t ir) {
    gpioWrite(LED_GPIO, (ir > IR_THRESHOLD) ? 1 : 0);
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    if (init_log() < 0) {
        cleanup();
        return 1;
    }

    if (configure_sensor() < 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return 1;
    }

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t red, ir;
        if (read_sensor_data(&red, &ir) == 0) {
            log_data(red, ir);
            control_led(ir);
            printf("Red: %u, IR: %u\n", red, ir);
        } else {
            fprintf(stderr, "Sensor read error, retrying...\n");
        }
        usleep(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

