#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/*
 * ISR: called from pigpio thread.
 * Counts rising edges on GPIO18 and updates the shared pulse counter.
 */
static void pulse_isr(int gpio, int level, uint32_t tick, void *user_data) {
