    running = 0;
}

/*
 * Calculate RPM from the number of pulses received over the sample interval.
 * Returns 0.0 when no pulses are detected (sensor absent or wiring fault).
 */
static float calculate_rpm(int pulses, int interval_us) {
    if (pulses == 0) {
