#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR 0x48
#define LED_GPIO       17
#define INFRARED_THRESHOLD 2000
#define SAMPLE_DELAY_US 100000
#define LOG_FILE       "adpd144ri_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_ir_value(int fd, uint8_t *ir_value) {
    return i2c_read_reg8(fd, 0x00, ir_value);
}

static int read_red_value(int fd, uint8_t *red_value) {
    return i2c_read_reg8(fd, 0x01, red_value);
}

static int log_data(FILE *fp, uint8_t ir_value, uint8_t red_value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%u,%u\n", timestamp, ir_value, red_value) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADPD144RI_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint8_t ir_value = 0;
        uint8_t red_value = 0;

        if (read_ir_value(g_i2c_fd, &ir_value) != 0 || read_red_value(g_i2c_fd, &red_value) != 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (log_data(g_log_fp, ir_value, red_value) != 0) {
            fprintf(stderr, "Logging error; continuing.\n");
        }

        if (ir_value > INFRARED_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

