#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x58
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_US      1000000  /* 1 s */
#define MAX_RETRIES    3

/* SLF3S-4000B: 16-bit two's-complement, MSB first */
#define SLF3S_MSB_SIZE 2
#define SLF3S_CRC_POLY  0x31
#define SLF3S_CRC_INIT  0xFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t slf3s_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SLF3S_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SLF3S_CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read flow rate from SLF3S-4000B                                      */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch          */
/* ------------------------------------------------------------------ */
static int read_flow_rate(int handle, float *flow_rate_uL_min)
{
    uint8_t buf[SLF3S_MSB_SIZE + 1];
    int  rc;

    /*
     * Write the register pointer: 0x00 (reset / read) or 0x01 (start / read).
     * The SLF3S-4000B is a slave-initiated device; pigpio's i2cWriteByte
     * sends a single byte to the slave, which then echoes the requested
     * register address + data back.  We use 0x00 to request the current
     * measurement.
     */
    rc = i2cWriteByte(handle, 0x00);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte (0x00) failed: %d\n", rc);
        return -1;
    }

    /*
     * The sensor returns 3 bytes: MSB, LSB, CRC.  The MSB is sent first
     * (pigpio writes the byte, the sensor echoes it back).  We read 3
     * bytes and validate the CRC.
     */
    rc = i2cReadDevice(handle, (char *)buf, SLF3S_MSB_SIZE + 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if (rc < SLF3S_MSB_SIZE + 1) {
        fprintf(stderr, "[ERROR] Short read: got %d bytes, expected %d\n",
                rc, SLF3S_MSB_SIZE + 1);
        return -1;
    }

    /* Validate CRC */
    if (slf3s_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch: calc=0x%02X recv=0x%02X\n",
                slf3s_crc8(buf, 2), buf[2]);
        return -2;
    }

    /* Assemble 16-bit two's-complement value */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate_uL_min = (float)raw / 1000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_flow_rate(FILE *fp, float flow_rate)
{
    time_t     t;
    struct tm  tm_info;
    char       ts[32];

    time(&t);
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, flow_rate) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float flow_rate;
    int  consecutive_failures = 0;

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open ---------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file ---------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: ", LOG_FILE);
        perror("");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SLF3S-4000B flow monitor started.  Logging to %s every 1 s.\n",
           LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        int rc = read_flow_rate(g_i2c_handle, &flow_rate);

        if (rc == 0) {
            consecutive_failures = 0;
            if (log_flow_rate(g_log_file, flow_rate) != 0) {
                fprintf(stderr, "[WARN] Logging failed for this sample\n");
            }
        } else if (rc == -1) {
            /* I2C error: attempt recovery on next iteration */
            consecutive_failures++;
            fprintf(stderr, "[WARN] I2C read failed (%d consecutive)\n",
                    consecutive_failures);
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "[FATAL] %d consecutive I2C failures; aborting.\n",
                        consecutive_failures);
                break;
            }
        } else {
            /* CRC mismatch: skip this sample */
            consecutive_failures++;
            fprintf(stderr, "[WARN] CRC mismatch (%d consecutive)\n",
                    consecutive_failures);
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "[FATAL] %d consecutive CRC failures; aborting.\n",
                        consecutive_failures);
                break;
            }
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

