#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5

/* MICS-VZ-89TE register addresses (from datasheet) */
#define REG_STATUS 0x00
#define REG_TVOC_MSB 0x01
#define REG_eCO2_MSB 0x02
#define REG_TVOC_LSB 0x03
#define REG_eCO2_LSB 0x04

#define STATUS_READY 0x01
#define STATUS_ERROR 0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *tvoc, uint16_t *eco2) {
    uint8_t status;
    if (i2c_read_reg8(handle, REG_STATUS, &status) != 0) {
        return -1;
    }
    if ((status & STATUS_READY) == 0) {
        fprintf(stderr, "Sensor not ready (status=0x%02X)\n", status);
        return -1;
    }
    uint8_t tvoco_msb, tvoco_lsb, eco2_msb, eco2_lsb;
    if (i2c_read_reg8(handle, REG_TVOC_MSB, &tvoco_msb) != 0) return -1;
    if (i2c_read_reg8(handle, REG_TVOC_LSB, &tvoco_lsb) != 0) return -1;
    if (i2c_read_reg8(handle, REG_eCO2_MSB, &eco2_msb) != 0) return -1;
    if (i2c_read_reg8(handle, REG_eCO2_LSB, &eco2_lsb) != 0) return -1;
    *tvoc = ((uint16_t)tvoco_msb << 8) | tvoco_lsb;
    *eco2 = ((uint16_t)eco2_msb << 8) | eco2_lsb;
    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    /* Simplified linear model; real implementation requires calibration */
    float tvoc_ppb = (float)tvoc;
    float eco2_ppm = (float)eco2;
    return 100.0f - 50.0f * (float)tvoc_ppb - 20.0f * (float)eco2_ppm;
}

static int log_data(FILE *fp, float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%.2f,%u,%u\n", ts, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
