#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TAMPER_SENSOR_PIN 17
#define POLL_INTERVAL_US 100000   /* 100 ms */
#define ALERT_THRESHOLD_S 5        /* 5 s continuous touch to trigger alert */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Returns 1 if the sensor is currently HIGH (touched), 0 if LOW (released),
 * and -1 on any pigpio error.
 */
static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, strerror(errno));
        return -1;
    }
    return level;
}

static void trigger_alert(void)
{
    printf("Intrusion alert: TTP223B tamper detected for >%d s\n", ALERT_THRESHOLD_S);
    fflush(stdout);
}

int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure the tamper sensor pin as input --- */
    if (gpioSetMode(TAMPER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", TAMPER_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Optional: enable internal pull-down so the line is defined when the
     * sensor is disconnected (TTP223B has an on-board pull-up; enable pull-down
     * to avoid floating when the sensor is absent). --- */
    if (gpioSetPullUpDown(TAMPER_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n", TAMPER_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tamper detection system started (GPIO %d).\n", TAMPER_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    struct timespec last_touch_time;
    int last_state = -1;   /* force initial comparison */

    while (g_running) {
        int sensor_value = read_sensor(TAMPER_SENSOR_PIN);
        if (sensor_value < 0) {
            /* Sensor read failed; exit loop to avoid spurious alerts. */
            break;
        }

        if (sensor_value == 1) {
            /* Touch detected (HIGH) */
            if (last_state == 0) {
                clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
            } else {
                /* Touch still active; check if threshold is exceeded */
                double elapsed = (double)(clock_gettime(CLOCK_MONOTONIC, NULL) -
                                     last_touch_time.tv_sec) +
                                 (double)(last_touch_time.tv_nsec -
                                         clock_gettime(CLOCK_MONOTONIC, NULL).tv_nsec) / 1e9;

                if (elapsed >= ALERT_THRESHOLD_S) {
                    trigger_alert();
                    last_touch_time = clock_gettime(CLOCK_MONOTONIC, NULL);
                }
            }
            last_state = 1;
        } else {
            /* Touch released (LOW) */
            if (last_state == 1) {
                last_touch_time = clock_gettime(CLOCK_MONOTONIC, NULL);
            }
            last_state = 0;
        }

        /* Sleep 100 ms; gpioDelay is interruptible by signals, so we check
         * g_running after each iteration. --- */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Cleanup --- */
    gpioTerminate();
    printf("\nTamper detection system stopped.\n");
    return EXIT_SUCCESS;
}

