/*
 * INMP441 I2S MEMS Microphone Capture via ALSA
 * Board: Raspberry Pi 4 Model B
 * Bus:  /dev/snd/pcmC0D0c  (I2S bus 0, channel 0, device 0)
 * GPIO: BCM 17 (GPIO17) - Left channel select
 * Output: audio_capture.pcm (16-bit PCM, 44100 Hz, 16-bit)
 *
 * Build: gcc -O2 -Wall -o audio_capture audio_capture.c -lasound
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>

#define ALSA_DEVICE      "/dev/snd/pcmC0D0c"
#define GPIO_CHIP        "/dev/gpiochip0"
#define GPIO_LINE        17
#define SAMPLE_RATE      44100
#define BITS_PER_SAMPLE  16
#define BUFFER_SIZE      4096
#define FILENAME         "audio_capture.pcm"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }
    return 0;
}

static int write_pcm_header(int fd)
{
    uint8_t header[40];
    int ret = 0;

    /* PCM header: 4 bytes RIFF, 4 bytes fmt, 4 bytes data */
    header[0] = 'P';
    header[1] = 'i';
    header[2] = 'x';
    header[3] = '8';

    uint16_t num_channels = 2;
    uint16_t sample_rate = SAMPLE_RATE;
    uint16_t byte_rate = SAMPLE_RATE * num_channels * BITS_PER_SAMPLE / 8;
    uint16_t block_align = num_channels * BITS_PER_SAMPLE / 8;
    uint16_t bits_per_sample = BITS_PER_SAMPLE;

    header[4] = (uint8_t)(byte_rate >> 24);
    header[5] = (uint8_t)(byte_rate >> 16);
    header[6] = (uint8_t)(byte_rate >> 8);
    header[7] = (uint8_t)(byte_rate);

    header[8] = (uint8_t)(block_align >> 24);
    header[9] = (uint8_t)(block_align >> 16);
    header[10] = (uint8_t)(block_align >> 8);
    header[11] = (uint8_t)(block_align);

    header[12] = (uint8_t)(bits_per_sample >> 24);
    header[13] = (uint8_t)(bits_per_sample >> 16);
    header[14] = (uint8_t)(bits_per_sample >> 8);
    header[15] = (uint8_t)(bits_per_sample);

    header[16] = 'f';
    header[17] = 'm';
    header[18] = 't';
    header[19] = 't';
    header[20] = 'i';
    header[21] = 'n';
    header[22] = 'g';
    header[23] = 't';
    header[24] = 'e';
    header[25] = 'r';
    header[26] = 's';
    header[27] = 't';
    header[28] = 'e';
    header[29] = 'r';
    header[30] = 's';
    header[31] = 's';

    if (write(fd, header, sizeof(header)) != (ssize_t)sizeof(header)) {
        perror("write PCM header");
        return -1;
    }
    return 0;
}

static int write_pcm_data(int fd, const uint8_t *data, int len)
{
    ssize_t written = 0;
    while (written < len) {
        ssize_t n = write(fd, data + written, len - written);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("write PCM data");
            return -1;
        }
        if (n == 0) break;
        written += n;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    if (install_signal_handler() == -1) {
        return EXIT_FAILURE;
    }

    /*
     * Open ALSA device for reading.
     * snd_pcm_open flags: 0 = read only, 0 = no mmap, 0 = no mmap_close.
     * We use the default device for channel 0.
     */
    fd = open(ALSA_DEVICE, O_RDONLY);
    if (fd == -1) {
        perror("open ALSA device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, SNDCTL_DSP_SETFMT, &((uint16_t){0})) == -1) {
        perror("SNDCTL_DSP_SETFMT");
        goto cleanup;
    }

    if (ioctl(fd, SNDCTL_DSP_CHANNEL_SELECT, &((uint8_t){GPIO_LINE} << 4)) == -1) {
        perror("SNDCTL_DSP_CHANNEL_SELECT");
        goto cleanup;
    }

    if (ioctl(fd, SNDCTL_DSP_SPEED_SET, &((uint16_t){SAMPLE_RATE})) == -1) {
        perror("SNDCTL_DSP_SPEED_SET");
        goto cleanup;
    }

    if (ioctl(fd, SNDCTL_DSP_CONTROL, &((uint16_t){0})) == -1) {
        perror("SNDCTL_DSP_CONTROL");
        goto cleanup;
    }

    if (write_pcm_header(fd) == -1) {
        goto cleanup;
    }

    uint8_t *pcm_data = malloc(BUFFER_SIZE);
    if (!pcm_data) {
        perror("malloc");
        goto cleanup;
    }

    printf("Capturing audio from INMP441 via ALSA. Press Ctrl+C to stop.\n");

    while (g_running) {
        ssize_t bytes_read = read(fd, pcm_data, BUFFER_SIZE);
        if (bytes_read == -1) {
            if (errno == EINTR) continue;
            perror("read ALSA");
            break;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "ALSA read returned 0 bytes (device disconnected?)\n");
            break;
        }

        /*
         * L/R channel select via GPIO17 (BCM).
         * INMP441 I2S output is active-low left channel select.
         * We toggle the line to switch between left and right.
         */
        int gpio_val = 0;
        if (ioctl(GPIO_CHIP, GPIO_SET_DIRECTION, &((uint8_t){GPIO_LINE})) == -1) {
            perror("GPIO_SET_DIRECTION");
            break;
        }
        if (ioctl(GPIO_CHIP, GPIO_SET_VALUE, &((uint8_t){gpio_val})) == -1) {
            perror("GPIO_SET_VALUE");
            break;
        }

        if (write_pcm_data(fd, pcm_data, bytes_read) == -1) {
            break;
        }

        gpio_val = !gpio_val;
        if (ioctl(GPIO_CHIP, GPIO_SET_VALUE, &((uint8_t){gpio_val})) == -1) {
            perror("GPIO_SET_VALUE");
            break;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd != -1) {
        if (write_pcm_header(fd) == -1) {
            perror("write PCM header (cleanup)");
        }
        if (close(fd) == -1) {
            perror("close ALSA device");
        }
    }

    free(pcm_data);
    return ret;
}

