#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PWM_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *event) {
    if (!log_file) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        return -1;
    }
    if (gpioSetMode(FAN_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan PWM pin mode\n");
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return -1;
    }
    if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM to 0\n");
        return -1;
    }
    return 0;
}

static int read_flame_sensor(void) {
    int val = gpioRead(FLAME_SENSOR_PIN);
    if (val < 0) {
        fprintf(stderr, "Failed to read flame sensor (gpioRead failed)\n");
        return -1;
    }
    if (val == 0) {
        return 1;
    }
    return 0;
}

static int control_fan(int state) {
    if (gpioPWM(FAN_PWM_PIN, state) != 0) {
        fprintf(stderr, "Failed to set fan PWM\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(FAN_PWM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            log_event("Sensor read error");
            gpioDelay(DEBOUNCE_DELAY_US);
            continue;
        }
        if (flame_detected == 1) {
            if (control_fan(1) != 0) {
                log_event("Failed to start fan");
            } else {
                log_event("Flame detected");
            }
            gpioDelay(DEBOUNCE_DELAY_US);
            if (control_fan(0) != 0) {
                log_event("Failed to stop fan");
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

