#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_MODE         0
#define SPI_BITS         8

#define GPIO_FRAME_TRIG  23
#define GPIO_DATA_READY 24

#define HEATMAP_SIZE    32768
#define FRAME_PERIOD_MS 100
#define LOG_FILE        "radar_heatmap.bin"
#define MAGIC_NUMBER     4144
#define TSTAMP_LEN      8

typedef struct {
    uint32_t start_freq;
    uint32_t end_freq;
    uint16_t chirps;
    uint16_t samples;
} radar_config_t;

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(spidev0.0) failed: %s\n", strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_init(void) {
    if (gpioSetMode(GPIO_FRAME_TRIG, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(FRAME_TRIG) failed\n");
        return -1;
    }
    if (gpioSetMode(GPIO_DATA_READY, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(DATA_READY) failed\n");
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_DATA_READY, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(DATA_READY) failed\n");
        return -1;
    }
    return 0;
}

static int log_open(void) {
    g_log_fp = fopen(LOG_FILE, "wb");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    uint8_t magic[4] = {0, 0, 0, 0};
    uint8_t tstamp[TSTAMP_LEN];
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(tstamp, TSTAMP_LEN, "%Y-%m-%d %H:%M:%S", &tm_info);

    memcpy(magic,  magic + 1, 3);
    memcpy(magic + 3, magic + 4, 1);
    memcpy(magic + 4,  magic + 1, 1);
    memcpy(magic + 5,  magic + 2, 1);
    memcpy(magic + 6,  magic + 3, 1);
    memcpy(magic + 7,  magic + 4, 1);
    memcpy(magic + 8,  magic + 5, 1);
    memcpy(magic + 9,  magic + 6, 1);
    memcpy(magic + 10, magic + 7, 1);
    memcpy(magic + 11, magic + 8, 1);
    memcpy(magic + 12, magic + 9, 1);
    memcpy(magic + 13, magic + 10, 1);
    memcpy(magic + 14, magic + 11, 1);
    memcpy(magic + 15, magic + 12, 1);
    memcpy(magic + 16, magic + 13, 1);
    memcpy(magic + 17, magic + 14, 1);
    memcpy(magic + 18, magic + 15, 1);
    memcpy(magic + 19, magic + 16, 1);
    memcpy(magic + 20, magic + 17, 1);
    memcpy(magic + 21, magic + 18, 1);
    memcpy(magic + 22, magic + 19, 1);
    memcpy(magic + 23, magic + 20, 1);
    memcpy(magic + 24, magic + 21, 1);
    memcpy(magic + 25, magic + 22, 1);
    memcpy(magic + 26, magic + 23, 1);
    memcpy(magic + 27, magic + 24, 1);
    memcpy(magic + 28, magic + 25, 1);
    memcpy(magic + 29, magic + 26, 1);
    memcpy(magic + 30, magic + 27, 1);
    memcpy(magic + 31, magic + 28, 1);

    memcpy(tstamp, tstamp + TSTAMP_LEN);

    if (fwrite(magic, 1, 32, g_log_fp) != 32) {
        fprintf(stderr, "fwrite(magic) failed: %s\n", strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        return -1;
    }
    if (fwrite(tstamp,  TSTAMP_LEN, 1, g_log_fp) != 1) {
        fprintf(stderr, "fwrite(tstamp) failed: %s\n", strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        return -1;
    }

    return 0;
}

static int log_write_frame(const uint8_t *frame, int frame_num) {
    if (!g_log_fp) {
        fprintf(stderr, "log_write_frame: log file not open\n");
        return -1;
    }

    uint8_t tstamp[TSTAMP_LEN];
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(tstamp, TSTAMP_LEN, "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fwrite(tstamp,  TSTAMP_LEN, 1, g_log_fp) != 1) {
        fprintf(stderr, "fwrite(tstamp) failed: %s\n", strerror(errno));
        return -1;
    }

    if (fwrite(frame, 1, HEATMAP_SIZE, g_log_fp) != HEATMAP_SIZE) {
        fprintf(stderr, "fwrite(frame) failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int log_read_frame(uint8_t *frame, int *frame_num) {
