    if (fd < 0) {
        fprintf(stderr, "open(spidev0.0) failed: %s\n", strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_init(void) {
    if (gpioSetMode(GPIO_FRAME_TRIG, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(FRAME_TRIG) failed\n");
        return -1;
    }
    if (gpioSetMode(GPIO_DATA_READY, PI_INPUT) < 0) {
