#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 20
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

/*
 * Returns a static ISO-8601 UTC timestamp string.
 * Format: 2024-05-23T14:30:00Z
 */
static const char *get_iso8601_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        return NULL;
    }

    if (strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        return NULL;
    }

    return buffer;
}

/*
 * Writes a single line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_flame_event(const char *timestamp, int flame_detected)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s, %s\n", timestamp,
                flame_detected ? "FLAME_DETECTED" : "FLAME_CLEAR") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int last_state = -1;  /* unknown initial state */
    int first_read = 1;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO20 as input */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read initial state */
    int current_state = gpioRead(FLAME_SENSOR_GPIO);
    if (current_state < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    last_state = current_state;
    first_read = 0;

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_GPIO);

    /* Main polling loop */
    while (program_running) {
        int current_state = gpioRead(FLAME_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", FLAME_SENSOR_GPIO);
            break;
        }

        /* Detect state change only on the second poll (first is initial) */
        if (first_read && current_state != last_state) {
            const char *timestamp = get_iso8601_timestamp();
            if (timestamp == NULL) {
                fprintf(stderr, "Failed to generate timestamp\n");
                break;
            }

            if (log_flame_event(timestamp, current_state) != 0) {
                fprintf(stderr, "Failed to log flame event\n");
                break;
            }

            printf("Flame event logged: %s, State: %s\n",
                   timestamp,
                   current_state ? "FLAME_DETECTED" : "FLAME_CLEAR");
        }

        last_state = current_state;
        first_read = 0;

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean up */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

