 * OPT3001 Ambient Light Sensor Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3001 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   OPT3001 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   OPT3001 VDD -> 3.3 V (pin 1)
 *   OPT3001 GND -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_logger light_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./light_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- OPT3001 I2C address (7-bit, default) ---- */
#define OPT3001_ADDR 0x49

/* ---- OPT3001 register addresses ---- */
#define REG_PART_ID       0x00
#define REG_CONFIG        0x01
#define REG_RESULT        0x02

/* ---- OPT3001 configuration register bits ---- */
#define CFG_CONT_MODE     0x01  /* Continuous conversion mode */
#define CFG_AUTO_RANGE    0x02  /* Full-scale range auto-increment */
#define CFG_1X           0x00   /* Full-scale range 1.0 */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an 8-bit-addressed register (pigpio's i2cWriteByteData sends MSB first) */
/* ------------------------------------------------------------------ */
static int reg_write16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);          /* MSB first */
    buf[2] = (char)((value >> 8) & 0xFF);  /* LSB second */

    if (i2cWriteDevice(handle, buf, 3) < 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an 8-bit-addressed register (pigpio's
 * i2cReadByteData returns the byte that was last written to the
 * register, so we must read the register address first, then the
 * data byte).
 * ------------------------------------------------------------------ */
static int reg_read16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };

    if (i2cWriteDevice(handle, reg_buf, 1) < 0) {
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the OPT3001: verify part ID, then configure for
 * continuous conversion mode with auto-range.
 * Returns 0 on success, -1 on failure.
 * ------------------------------------------------------------------ */
static int init_opt3001(int handle)
{
    uint16_t part_id = 0;

    if (reg_read16(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: failed to read OPT3001 PART_ID register.\n");
        return -1;
    }

    if (part_id != 0x3001) {
        fprintf(stderr, "Error: unexpected PART_ID 0x%04X (expected 0x3001).\n", part_id);
        return -1;
    }

    /* Clear any pending configuration bits before writing new settings */
    if (reg_write16(handle, REG_CONFIG, 0x0000) < 0) {
        fprintf(stderr, "Error: failed to clear OPT3001 config register.\n");
        return -1;
    }

    /* Continuous conversion mode */
    if (reg_write16(handle, REG_CONFIG, CFG_CONT_MODE) < 0) {
        fprintf(stderr, "Error: failed to set OPT3001 continuous conversion mode.\n");
        return -1;
    }

    /* Full-scale range auto-increment */
    if (reg_write16(handle, REG_CONFIG, CFG_AUTO_RANGE | CFG_1X) < 0) {
        fprintf(stderr, "Error: failed to set OPT3001 auto-range.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read lux value from the OPT3001.
 * Returns 0 on success and stores lux in *lux_out; -1 on error.
 * ------------------------------------------------------------------ */
static int read_lux(int handle, float *lux_out)
{
    uint16_t raw = 0;

    if (reg_read16(handle, REG_RESULT, &raw) < 0) {
        fprintf(stderr, "Error: failed to read OPT3001 result register.\n");
        return -1;
    }

    /*
     * OPT3001 conversion time is ~45 ms for 1.0 full-scale range.
     * We poll the result register with a 100 ms timeout to avoid
     * blocking the main loop while the sensor is busy.
     */
    int poll_count = 0;
    while (poll_count < 100) {
        if (reg_read16(handle, REG_RESULT, &raw) < 0) {
            return -1;
        }
        if (raw & 0x0001) {
            break;  /* conversion complete */
        }
        usleep(10000);  /* 10 ms */
        poll_count++;
    }

    if (poll_count >= 100) {
        fprintf(stderr, "Error: OPT3001 conversion timeout.\n");
        return -1;
    }

    /* Clear the conversion-in-progress bit before returning */
    if (reg_write16(handle, REG_CONFIG, raw & ~0x0001) < 0) {
        fprintf(stderr, "Error: failed to clear OPT3001 config register.\n");
        return -1;
    }

    *lux_out = (float)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped lux reading to light_data.txt.
 * Returns 0 on success, -1 on error.
 * ------------------------------------------------------------------ */
static int log_data(const char *filename, float lux)
{
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources on every exit path.
 * ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error registering SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the OPT3001 address */
    g_i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at address 0x%02X (pigpio error %d).\n",
                OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the sensor */
    if (init_opt3001(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: OPT3001 initialisation failed (sensor may be absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("OPT3001 initialised on I2C bus 1, address 0x%02X. Logging to light_data.txt every 100 ms.\n",
           OPT3001_ADDR);
    printf("Press Ctrl+C to stop.\n");

    /* Main acquisition loop */
    while (g_running) {
        float lux = 0.0f;

        if (read_lux(g_i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (log_data("light_data.txt", lux) < 0) {
                fprintf(stderr, "Warning: failed to log data to file.\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle.\n");
        }

        /* 100 ms delay between conversions */
        usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

