/*
 * flame_detect.c — Raspberry Pi 3 Model B+
 *
 * Reads a SainSmart IR Flame Detection Sensor Module over the GPIO bus.
 *
 * Wiring (BCM numbering):
 *   Sensor DOUT  -> GPIO17 (BCM, active-low)
 *   Sensor VCC   -> 3.3 V
 *   Sensor GND   -> GND
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 *
 * Run:
 *   ./flame_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_SENSOR_LINE  17          /* BCM GPIO17 — flame sensor DOUT */
#define POLL_INTERVAL_SEC  1           /* seconds between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Format current local time as YYYY-MM-DD HH:MM:SS                 */
/* ------------------------------------------------------------------ */
static int format_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        perror("time");
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log flame detection status to stdout                                */
/* ------------------------------------------------------------------ */
static void log_flame_status(int flame_detected)
{
    char ts[32];

    if (format_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        return;
    }
    printf("%s Flame Detected: %s\n", ts,
           flame_detected ? "YES" : "NO");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_request_config req_cfg;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg_p = NULL;
    int ret;

    /* ---- Install SIGINT handler for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open the default gpiochip (gpiochip0 on RPi 3B+) ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* ---- Configure the flame sensor line as input with pull-up ---- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        perror("gpiod_line_settings_new");
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    req_cfg_p = gpiod_request_config_new();
    if (req_cfg_p == NULL) {
        perror("gpiod_request_config_new");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg_p, "flame-sensor");

    /* ---- Request the line ---- */
    ret = gpiod_line_request(chip, FLAME_SENSOR_LINE, req_cfg_p, settings);
    if (ret < 0) {
        perror("gpiod_line_request");
        goto cleanup;
    }

    printf("Flame detection started on GPIO%d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_LINE);
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int val = gpiod_line_request_get_value(line);
        if (val < 0) {
            perror("gpiod_line_request_get_value");
            break;
        }

        /*
         * SainSmart module DOUT is active-low:
         *   0  => flame detected
         *   1  => no flame
         */
        log_flame_status(val == 0);

        /*
         * Sleep in 1-second increments so SIGINT is noticed promptly.
         * gpiod_line_request_set_value() is non-blocking on the line
         * itself, but we still sleep to avoid busy-waiting.
         */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (req_cfg_p != NULL) {
        gpiod_request_config_free(req_cfg_p);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

