#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27
#define POLL_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: could not register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: could not register SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", LEFT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", CENTER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", RIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int left = gpioRead(LEFT_PIN);
        int center = gpioRead(CENTER_PIN);
        int right = gpioRead(RIGHT_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: GPIO read failed (left=%d, center=%d, right=%d)\n",
                    left, center, right);
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        usleep(POLL_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

