#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo) > 0) {
            printf("[%s] ", buffer);
        }
    }
}

int main(void)
{
    int i;
    int values[NUM_CHANNELS];
    int rc;

    /* --- Install signal handler for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure all eight channel pins as inputs --- */
    for (i = 0; i < NUM_CHANNELS; i++) {
        rc = gpioSetMode(channel_pins[i], PI_INPUT);
        if (rc != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for BCM pin %d (code %d).\n",
                    channel_pins[i], rc);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Polling every %d ms. Press Ctrl+C to exit.\n", POLL_DELAY_US / 1000);

    /* --- Main polling loop --- */
    while (program_running) {
        rc = gpioRead(channel_pins[0], NULL);
        if (rc < 0) {
            fprintf(stderr, "Error: gpioRead failed for BCM pin %d (code %d).\n",
                    channel_pins[0], rc);
            break;
        }

        for (i = 0; i < NUM_CHANNELS; i++) {
            values[i] = (rc & (1 << i)) ? 1 : 0;
        }

        print_timestamp();
        printf("Channel %d: %d\n", i + 1, values[i]);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

