#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    int pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int values[NUM_CHANNELS];
        int rc = gpioReadArray(pins, values);
        if (rc != 0) {
            fprintf(stderr, "Error: gpioReadArray failed (rc=%d).\n", rc);
            break;
        }

        printf("[+%d ms]\n", SAMPLE_DELAY_US / 1000);
        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("  CH%d=%d", i + 1, values[i]);
            if (i < NUM_CHANNELS - 1) {
                printf(" ");
            }
        }
        printf("\n");
        fflush(stdout);

        usleep(SAMPLE_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

