/*
 * TMAG5110 Hall-Effect Latch Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   TMAG5110 OUT1 -> BCM GPIO4  (physical pin 7)
 *   TMAG5110 OUT2 -> BCM GPIO5  (physical pin 3)
 *   TMAG5110 VDD -> 3.3 V
 *   TMAG5110 GND -> GND
 *
 * The TMAG5110 OUT pins are open-drain; an unasserted output reads HIGH
 * and a magnet-detected assertion reads LOW.  External pull-up resistors
 * are required on the sensor OUT lines.
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lthe driver library -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <the/the.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 5
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct the_gpio_chip *chip = NULL;
    struct the_gpio_line *line1 = NULL, *line2 = NULL;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip (gpiochip0 on RPi 3B+) */
    chip = the_gpio_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("the_gpio_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* Get the two GPIO lines */
    line1 = the_gpio_chip_get_line(chip, SENSOR1_PIN);
    if (line1 == NULL) {
        perror("the_gpio_chip_get_line(4)");
        goto cleanup;
    }

    line2 = the_gpio_chip_get_line(chip, SENSOR2_PIN);
    if (line2 == NULL) {
        perror("the_gpio_chip_get_line(5)");
        goto cleanup;
    }

    /* Request both lines as inputs with internal pull-up (external pull-up
     * is required for the TMAG5110 open-drain outputs). */
    if (the_gpio_line_request_input_flags(line1, "tmag5110-s1",
            THE_GPIO_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("the_gpio_line_request_input_flags(4)");
        goto cleanup;
    }

    if (the_gpio_line_request_input_flags(line2, "tmag5110-s2",
            THE_GPIO_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("the_gpio_line_request_input_flags(5)");
        goto cleanup;
    }

    printf("TMAG5110 Hall-Effect Latch Reader started.\n");
    printf("  Sensor 1 OUT -> BCM GPIO%d\n", SENSOR1_PIN);
    printf("  Sensor 2 OUT -> BCM GPIO%d\n", SENSOR2_PIN);
    printf("  Poll interval : %d ms\n", POLL_INTERVAL_MS);
    printf("  Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        int v1 = the_gpio_line_get_value(line1);
        int v2 = the_gpio_line_get_value(line2);

        if (v1 < 0) {
            perror("the_gpio_line_get_value(4)");
            break;
        }
        if (v2 < 0) {
            perror("the_gpio_line_get_value(5)");
            break;
        }

        /*
         * TMAG5110 OUT is open-drain:
         *   0 -> magnet present (LOW)
         *   1 -> no magnet (HIGH)
         */
        if (v1 == 0)
            printf("Sensor 1: LOW (magnet detected)\n");
        else
            printf("Sensor 1: HIGH (no magnet)\n");

        if (v2 == 0)
            printf("Sensor 2: LOW (magnet detected)\n");
        else
            printf("Sensor 2: HIGH (no magnet)\n");

        fflush(stdout);

        /* Sleep in 100 ms slices so SIGINT is noticed promptly */
        for (int i = 0; i < 5 && g_running; i++)
            usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Release the lines and close the chip */
    if (line1 != NULL)
        the_gpio_line_release(line1);
    if (line2 != NULL)
        the_gpio_line_release(line2);
    if (chip != NULL)
        the_gpio_chip_close(chip);

    printf("\nClean shutdown complete.\n");
    return rc;
}

