#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 50000  /* 50 ms */

static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int read_touch_sensors(int gpio_pins[], int num_channels, int *values)
{
    for (int i = 0; i < num_channels; i++) {
        int v = gpioRead(gpio_pins[i]);
        if (v < 0) {
            fprintf(stderr, "Error: gpioRead failed on pin %d\n", gpio_pins[i]);
            return -1;
        }
        values[i] = v;
    }
    return 0;
}

static void print_csv_line(const int values[])
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s", timestamp);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf(",%d", values[i]);
    }
    printf("\n");
    fflush(stdout);
}

int main(void)
{
    int gpio_pins[NUM_CHANNELS];
    int values[NUM_CHANNELS];

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure each sensor pin as input with bias disabled */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpio_pins[i] = sensor_pins[i];
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", gpio_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(gpio_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", gpio_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 8-Channel Touch Sensor Reader\n");
    printf("Polling every %d ms. Press Ctrl+C to exit.\n", POLL_DELAY_US / 1000);
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        if (read_touch_sensors(gpio_pins, NUM_CHANNELS, values) == 0) {
            print_csv_line(values);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean up */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

