#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TILT_PIN 4
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown on Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure tilt pin as input with internal pull-up resistor */
    if (gpioSetMode(TILT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TILT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", TILT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Print startup banner */
    printf("Tilt sensor monitoring started on GPIO%d.\n", TILT_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_tilt_state = -1;  /* force initial print */

    while (g_running) {
        int tilt_state = gpioRead(TILT_PIN);

        if (tilt_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n",
                    TILT_PIN, tilt_state);
            break;
        }

        if (tilt_state != last_tilt_state) {
            if (tilt_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            last_tilt_state = tilt_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

