#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SI1145_ADDR 0x53
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_UV_INDEX0 0x24
#define SI1145_REG_COMMAND 0x30
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_VIS_AUTO 0x0E
#define SI1145_CMD_UV_FORCE 0x06
#define SI1145_PART_ID 0x45

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n", reg, value, strerror(errno));
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
    }
    return rc;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, expected %u, got %d): %s\n", reg, len, rc, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_si1145(int handle) {
    int part_id = read_reg(handle, SI1145_REG_PART_ID);
    if (part_id < 0) return -1;
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (write_reg(handle, SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (write_reg(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_reg(handle, SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;

    return 0;
}

static int read_uv_index(int handle) {
    if (write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_UV_FORCE) < 0) return -1;
    gpioDelay(10000);

    int uv_raw = read_reg(handle, SI1145_REG_UV_INDEX0);
    if (uv_raw < 0) return -1;

    return (int)(uv_raw >> 2);
}

static int read_als_visible(int handle) {
    if (write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_VIS_AUTO) < 0) return -1;
    gpioDelay(10000);

    uint8_t buf[2];
    if (read_block(handle, SI1145_REG_ALS_VIS_DATA0, buf, 2) < 0) return -1;

    return (int)((buf[1] << 8) | buf[0]);
}

static void log_data(FILE *fp, int uv_index, int als_visible) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d\n", ts, uv_index, als_visible);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int uv_index = read_uv_index(i2c_handle);
        int als_visible = read_als_visible(i2c_handle);

        if (uv_index < 0 || als_visible < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        printf("UV Index: %d, Ambient Light (Visible): %d\n", uv_index, als_visible);
        log_data(log_file, uv_index, als_visible);

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

