    log_file = fopen("uv_als_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int uv_index = read_uv_index(i2c_handle);
        int als_visible = read_als_visible(i2c_handle);

        if (uv_index < 0 || als_visible < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(1000000);
