#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x30
#define ALARM_GPIO      17
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define SAMPLE_PERIOD  1
#define START_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) return -1;
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_flow_rate(int fd, float *flow_out) {
    uint8_t cmd = 0x00;
    uint8_t data[4];

    if (i2c_write_cmd(fd, cmd) < 0) return -1;
    gpioDelay(START_DELAY_MS * 1000);

    if (i2c_read_data(fd, data, 4) < 0) return -1;

    if (crc8(data, 2) != data[2]) return -2;
    if (crc8(data + 3, 2) != data[5]) return -2;

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *flow_out = (float)raw / 1000.0f;
    return 0;
}

static void log_data(FILE *fp, float avg_flow) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_flow);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        cleanup();
        return 1;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = 0, ok2 = 0;

        if (read_flow_rate(i2c_fd, &flow1) == 0) {
            ok1 = 1;
        }
        if (read_flow_rate(i2c_fd, &flow2) == 0) {
            ok2 = 1;
        }

        if (ok1 && ok2) {
            float avg = (flow1 + flow2) / 2.0f;
            log_data(log_fp, avg);
            gpioWrite(ALARM_GPIO, (avg < FLOW_THRESHOLD) ? 1 : 0);
        } else {
            if (ok1) log_error(log_fp, "Sensor 1 read failed");
            if (ok2) log_error(log_fp, "Sensor 2 read failed");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

