#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    time_t timestamp;
    int value;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_to_buffer(time_t timestamp, int value) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].value = value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void dump_buffer(void) {
    printf("\n--- Circular Buffer Dump ---\n");
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&circular_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Timestamp: %s, Value: %d\n", time_str, time_str, circular_buffer[idx].value);
        }
    }
    printf("--- End of Buffer Dump ---\n\n");
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("Monitoring KY-033 obstacle sensor on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", SENSOR_PIN);
            break;
        }

        time_t current_time = time(NULL);
        add_to_buffer(current_time, sensor_value);

        if (sensor_value == 0) {
            printf("Alert: Obstacle detected at %s\n", ctime(&current_time));
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    dump_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

