#define ACTIVATE_US    1000000    /* 1 s  */

/* D7S register addresses (verified against datasheet) */
#define D7S_REG_MODE   0x00
#define D7S_REG_X_LSB  0x01
#define D7S_REG_X_MSB  0x02
#define D7S_REG_Y_LSB  0x03
#define D7S_REG_Y_MSB  0x04
#define D7S_REG_Z_LSB  0x05
#define D7S_REG_Z_MSB  0x06

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int d7s_init(int fd)
{
    /* Software reset */
    if (i2c_write_reg8(fd, D7S_REG_MODE, 0x00) < 0)
        return -1;
    usleep(10000);

    /* Set to standby mode (optional, but safe) */
    if (i2c_write_reg8(fd, D7S_REG_MODE, 0x00) < 0)
        return -1;
    usleep(10000);

    /* Switch to measurement mode */
    if (i2c_write_reg8(fd, D7S_REG_MODE, 0x01) < 0)
        return -1;
    usleep(10000);

    return 0;
}

static int d7s_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, D7S_REG_X_LSB, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_X_MSB, &hi) < 0) return -1;
    *x = (int16_t)((hi << 8) | lo);

    if (i2c_read_reg8(fd, D7S_REG_Y_LSB, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Y_MSB, &hi) < 0) return -1;
    *y = (int16_t)((hi << 8) | lo);

    if (i2c_read_reg8(fd, D7S_REG_Z_LSB, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Z_MSB, &hi) < 0) return -1;
    *z = (int16_t)((hi << 8) | lo);

    return 0;
}

static int csv_write_header(FILE *f)
