/*
 * Raspberry Pi 4 Model B – Dual KY-032 IR Obstacle Avoidance Monitor
 *
 * Wiring:
 *   KY-032 #1 OUT -> GPIO23 (BCM)
 *   KY-032 #2 OUT -> GPIO24 (BCM)
 *   LED anode     -> GPIO25 (BCM) via 220–330 Ω resistor to GND
 *
 * The KY-032 module has an active-LOW output:
 *   LOW  (0 V)  -> obstacle detected within ~10 cm
 *   HIGH (3.3 V) -> no obstacle or clear
 *
 * Build:  gcc -O2 -Wall -Wextra -o ir_monitor ir_monitor.c -lpigpio -lrt
 * Run:    sudo ./ir_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN      25

#define POLL_DELAY_US  100000          /* 100 ms  */
#define LED_ON_US      1000000         /* 1 s     */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        return -1;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n",
                LED_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup_gpio(void)
{
    /* Best-effort LED off before terminating */
    (void)gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("IR Obstacle Avoidance Monitor started.\n");
    printf("  Sensor 1 : GPIO%d\n", SENSOR_1_PIN);
    printf("  Sensor 2 : GPIO%d\n", SENSOR_2_PIN);
    printf("  LED     : GPIO%d\n", LED_PIN);
    printf("  Poll    : %d ms\n", POLL_DELAY_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    bool led_on = false;

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Warning: GPIO read error (s1=%d, s2=%d).\n",
                    s1, s2);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-032 is active-LOW: LOW (0) means obstacle detected */
        bool obstacle = (s1 == 0 || s2 == 0);

        if (obstacle && !led_on) {
            if (gpioWrite(LED_PIN, 1) == 0) {
                led_on = true;
                printf("  -> Obstacle detected – LED ON\n");
            } else {
                fprintf(stderr, "Error: failed to turn LED on.\n");
            }
        } else if (!obstacle && led_on) {
            if (gpioWrite(LED_PIN, 0) == 0) {
                led_on = false;
                printf("  -> No obstacle – LED OFF\n");
            } else {
                fprintf(stderr, "Error: failed to turn LED off.\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    printf("GPIO resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

