/*
 * TMAG5170-Q1 3D Hall-Effect Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TMAG5170 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   TMAG5170 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   TMAG5170 VDD  -> 3.3 V (pin 1)
 *   TMAG5170 GND  -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tmag5170_log tmag5170_log.c -lpigpio -lrt
 *   (must be run as root, or with appropriate I2C permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- TMAG5170 constants (from TI datasheet) ---- */
#define TMAG5170_I2C_ADDR 0x49

#define REG_X_MSB          0x00
#define REG_X_LSB          0x01
#define REG_Y_MSB          0x02
#define REG_Y_LSB          0x03
#define REG_Z_MSB          0x04
#define REG_Z_LSB          0x05
#define REG_CONFIG         0x06

#define CONFIG_CONT_MODE   0x00
#define CONFIG_50MT_RANGE  0x00
#define CONFIG_X_AXIS_EN   0x01
#define CONFIG_Y_AXIS_EN   0x02
#define CONFIG_Z_AXIS_EN   0x04

#define I2C_BUS            1
#define SAMPLE_PERIOD_US   100000  /* 100 ms */
#define LOG_FILE           "magnetic_log.csv"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register (big-endian on the bus).   */
static int reg_write16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);          /* MSB first */
    buf[2] = (char)((value >> 8) & 0xFF);  /* LSB second */

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%04X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register (big-endian on the bus). */
static int reg_read16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg-select 0x%02X) failed\n", reg);
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static int configure_sensor(int handle)
{
    /*
     * Config register (0x06):
     *   bit 0  = continuous conversion mode
     *   bit 1  = 50 mT full-scale range
     *   bits 2-5 = X, Y, Z axis enable (1 = enabled)
     *
     * 0x00 = 0000 0000 0000 0000  -> X_EN|Y_EN|Z_EN = 0
     *   -> X_AXIS_EN | Y_AXIS_EN | Z_AXIS_EN = 0
     *   -> 50 mT full-scale
     *   -> continuous mode
     */
    if (reg_write16(handle, REG_CONFIG, CONFIG_CONT_MODE) != 0)
        return -1;

    if (reg_write16(handle, REG_X_MSB, 0x0000) != 0)
        return -1;
    if (reg_write16(handle, REG_Y_MSB, 0x0000) != 0)
        return -1;
    if (reg_write16(handle, REG_Z_MSB, 0x0000) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetic_field(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t x_raw, y_raw, z_raw;

    if (reg_read16(handle, REG_X_MSB, &x_raw) != 0)
        return -1;
    if (reg_read16(handle, REG_Y_MSB, &y_raw) != 0)
        return -1;
    if (reg_read16(handle, REG_Z_MSB, &z_raw) != 0)
        return -1;

    *x = (int16_t)x_raw;
    *y = (int16_t)y_raw;
    *z = (int16_t)z_raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0)
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
    if (fflush(fp) != 0)
        fprintf(stderr, "[ERROR] fflush log file failed\n");
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* pigpio's gpioTerminate() is safe to call even if no handle was
       ever opened; it just cleans up the pigpio library. */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, TMAG5170_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, TMAG5170_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor configuration ---- */
    if (configure_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] TMAG5170 configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append; write header if newly created) ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Determine whether the file is empty so we can write a header. */
    long pos = ftell(g_log_file);
    if (pos < 0) {
        fprintf(stderr, "[WARN] ftell failed; treating as new file\n");
    }
    if (pos == 0) {
        if (fprintf(g_log_file, "timestamp,x,y,z\n") < 0) {
            fprintf(stderr, "[WARN] Cannot write CSV header\n");
        }
        if (fflush(g_log_file) != 0)
            fprintf(stderr, "[WARN] fflush header failed\n");
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("TMAG5170 logging started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_magnetic_field(g_i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "[WARN] I2C read error; skipping sample\n");
        } else {
            log_data(g_log_file, x, y, z);
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        }

        /* 100 ms sample period */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

