#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Timer callback — fires on every rising edge of the sensor pulse    */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level != 1) {
        return;  /* only count rising edges */
    }

    static uint32_t pulse_count = 0;
    pulse_count++;
}

/* ------------------------------------------------------------------ */
/* Helper: get current timestamp as a static string                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

/* ------------------------------------------------------------------ */
/* Helper: log a single line to the file and stdout                     */
/* ------------------------------------------------------------------ */
static void log_rpm(FILE *fp, const char *timestamp, int rpm)
{
    if (fp) {
        fprintf(fp, "%s %s\n", timestamp, rpm ? "revolutions per minute" : "0");
        fflush(fp);
    }
    printf("%s %s\n", timestamp, rpm ? "revolutions per minute" : "0");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — release all resources                                */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);  /* unregister callback */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pin ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback for rising-edge pulses ---- */
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register alert callback on GPIO %d\n",
                GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring MLX90217 Hall-effect sensor on GPIO %d. "
           "Logging to '%s'. Press Ctrl+C to exit.\n",
           GPIO_PIN, LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (running) {
        uint32_t pulse_count = 0;

        /*
         * gpioDelay is a busy-wait that blocks for the given microseconds.
         * On a Raspberry Pi 4 with pigpio the delay is typically very
         * accurate and responsive, but if the system is heavily loaded
         * it may not be strictly periodic.  For production work we would
         * use a hardware-timer or a software-delay library, but for this
         * example the 1-second window is acceptable.
         */
        gpioDelay(SAMPLE_INTERVAL_US);

        get_timestamp(timestamp, sizeof(timestamp));
        int rpm = (int)(pulse_count * 60.0 / SAMPLE_INTERVAL_US);

        log_rpm(log_file, timestamp, rpm);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

