code:
/*
 * MLX90217 Quadrature Hall-Effect Sensor Direction Detector
 * Board:  Raspberry Pi Zero W
 * Sensors: 2x Melexis MLX90217 (unipolar)
 * Wiring:
 *   Sensor A: GPIO17 (BCM)  -> A0
 *   Sensor B: GPIO27 (BCM)  -> A1
 *   (Use hardware pull-up resistors to provide the required 90° electrical
 *    offset; the MLX90217 outputs are open-collector-style and drive the
 *    line low when the magnet is present.)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90217_quad mlx90217_quad.c -lpigpio -lpthread
 * Run:    sudo ./mlx90217_quad
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27

/* ---- Timing / logging ---- */
#define LOG_FILE_NAME "rotation_log.txt"
#define POLL_DELAY_US 10000   /* 10 ms */
#define MAIN_LOOP_DELAY_US 100000 /* 100 ms */

/* ---- Application state ---- */
typedef struct {
    int sensor_a_state;   /* 0 = no magnet, 1 = magnet present */
    int sensor_b_state;   /* 0 = no magnet, 1 = magnet present */
    pthread_mutex_t state_mutex;
    FILE *log_file;
    volatile sig_atomic_t running;
} AppState;

/* ---- Quadrature state machine ---- */
typedef enum {
    STATE_NONE,
    STATE_A_RISING,
    STATE_B_RISING,
    STATE_A_FALLING,
    STATE_B_FALLING,
    STATE_NONE_INV
} QuadratureState;

static QuadratureState quadrature_state = STATE_NONE;

/* ---- Prototypes ---- */
static void sensor_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void sensor_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void log_rotation(int sensor_a_state, int sensor_b_state);
static void signal_handler(int sig);
static void cleanup(AppState *app);

/*
 * Interrupt service routines.
 * pigpio dispatches these on a dedicated thread, so we only write and
 * sleep here.  We use a per-sensor state machine so that the main
 * loop can deduce direction from the sequence of rising/falling edges.
 */
static void sensor_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        /* Rising edge on Sensor A */
        pthread_mutex_lock(&app->state_mutex);
        app->sensor_a_state = 1;
        pthread_mutex_unlock(&app->state_mutex);
    }
}

static void sensor_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        /* Rising edge on Sensor B */
        pthread_mutex_lock(&app->state_mutex);
        app->sensor_b_state = 1;
        pthread_mutex_unlock(&app->state_mutex);
    }
}

/*
 * Log a rotation event with millisecond precision.
 * Returns 0 on success, -1 on failure.
 */
static int log_rotation(int sensor_a_state, int sensor_b_state)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(app->log_file, "%s - Sensor A: %s, Sensor B: %s\n",
                timestamp,
                sensor_a_state ? "Clockwise" : "Counter-Clockwise",
                sensor_b_state ? "Clockwise" : "Counter-Clockwise") < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(app->log_file) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/*
 * Signal handler — set flag so the main loop can exit cleanly.
 */
static void signal_handler(int sig)
{
    (void)sig;
    app->running = 0;
}

/*
 * Release all resources.
 */
static void cleanup(AppState *app)
{
    if (app->log_file != NULL) {
        fflush(app->log_file);
        fclose(app->log_file);
        app->log_file = NULL;
    }
    gpioTerminate();
    pthread_mutex_destroy(&app->state_mutex);
}

int main(void)
{
    AppState app = {
        .sensor_a_state = 0,
        .sensor_b_state = 0,
        .log_file = NULL,
        .running = 1,
        .state_mutex = PTHREAD_MUTEX_INITIALIZER
    };

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs */
    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up resistors (MLX90217 outputs are open-collector) */
    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    app.log_file = fopen(LOG_FILE_NAME, "a");
    if (app.log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register interrupt handlers */
    if (gpioSetISRFuncEx(SENSOR_A_PIN, RISING_EDGE, 0,
                         sensor_a_isr, &app) != 0) {
        fprintf(stderr, "Failed to register ISR for GPIO%d\n", SENSOR_A_PIN);
        cleanup(&app);
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(SENSOR_B_PIN, RISING_EDGE, 0,
                         sensor_b_isr, &app) != 0) {
        fprintf(stderr, "Failed to register ISR for GPIO%d\n", SENSOR_B_PIN);
        cleanup(&app);
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup(&app);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup(&app);
        return EXIT_FAILURE;
    }

    printf("MLX90217 quadrature direction detector running. Press Ctrl+C to exit.\n");

    /* Main loop — deduce direction from quadrature state machine */
    while (app.running) {
        pthread_mutex_lock(&app.state_mutex);

        int current_a = app.sensor_a_state;
        int current_b = app.sensor_b_state;

        /* Sensor A rising edge -> magnet present */
        if (quadrature_state == STATE_A_RISING) {
            if (current_a == 1 && current_b == 0) {
                quadrature_state = STATE_B_RISING;
            } else if (current_a == 0 && current_b == 1) {
                quadrature_state = STATE_A_FALLING;
            }
        }

        /* Sensor B rising edge -> magnet present */
        if (quadrature_state == STATE_B_RISING) {
            if (current_a == 1 && current_b == 0) {
                quadrature_state = STATE_A_FALLING;
            } else if (current_a == 0 && current_b == 1) {
                quadrature_state = STATE_B_FALLING;
            }
        }

        /* Sensor A falling edge -> magnet absent */
        if (quadrature_state == STATE_A_FALLING) {
            if (current_a == 0 && current_b == 1) {
                quadrature_state = STATE_NONE;
            } else if (current_a == 1 && current_b == 0) {
                quadrature_state = STATE_NONE_INV;
            }
        }

        pthread_mutex_unlock(&app.state_mutex);

        if (quadrature_state == STATE_NONE_INV) {
            /* No magnet present — log a "no-rotation" event */
            log_rotation(current_a, current_b);
        } else if (quadrature_state == STATE_NONE) {
            /* No magnet present — log a "no-rotation" event */
            log_rotation(current_a, current_b);
        } else {
            /* Magnet present — log direction */
            log_rotation(current_a, current_b);
        }

        gpioDelay(MAIN_LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup(&app);
    return EXIT_SUCCESS;
}

