#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdbool.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN          18
#define POLL_DELAY_US    50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Ensure LED is off before releasing resources */
    if (gpioWrite(LED_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to turn off LED during cleanup");
    }
    gpioTerminate();
}

int main(void)
{
    openlog("touch_led_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set touch sensor pin %d as input", TOUCH_SENSOR_PIN);
        cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set LED pin %d as output", LED_PIN);
        cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise LED pin %d to LOW", LED_PIN);
        cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Touch sensor monitoring started (GPIO%d as input, GPIO%d as output)",
           TOUCH_SENSOR_PIN, LED_PIN);

    while (g_running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor pin %d", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_state == 1) {
            syslog(LOG_INFO, "Touch detected on GPIO%d", TOUCH_SENSOR_PIN);
            if (gpioWrite(LED_PIN, 1) != 0) {
                syslog(LOG_ERR, "Failed to turn on LED on GPIO%d", LED_PIN);
                break;
            }
        } else {
            if (gpioWrite(LED_PIN, 0) != 0) {
                syslog(LOG_ERR, "Failed to turn off LED on GPIO%d", LED_PIN);
                break;
            }
        }

        usleep(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down touch sensor monitoring");
    cleanup();
    closelog();
    return EXIT_SUCCESS;
}

