static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* TTP223B event loop (rising-edge detection)                         */
/* ------------------------------------------------------------------ */
static int setup_touch_event_loop(int *touch_state)
{
    int ret;

    /* Open the pigpio GPIO chip */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: gpioInitialise() failed (code %d)\n", ret);
        return -1;
    }

    /* Configure touch input */
    if (safe_set_mode(TOUCH_PIN, PI_INPUT) != 0)
        return -1;

    /* Configure LED output */
    if (safe_set_mode(LED_PIN, PI_OUTPUT) != 0)
        return -1;

    /* Ensure LED starts in the OFF state */
    if (safe_write(LED_PIN, 0) != 0)
        return -1;

    /*
     * Request a rising-edge event on the touch input line.
     * pigpio's gpioSetAlertFunc returns 0 on success and sets a
     * callback function that is executed on every edge transition.
     */
    ret = gpioSetAlertFunc(TOUCH_PIN, rising_edge_callback);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc(%d) failed (code %d)\n",
                TOUCH_PIN, ret);
        gpioTerminate();
        return -1;
    }

    *touch_state = 0;
    return 0;
}

/*
 * Callback for rising-edge events on the touch input line.
 * pigpio dispatches this callback on every edge transition.
 */
static void rising_edge_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;

    if (level == 1) {
        /* Rising edge detected */
        *touch_state = 1;
        gpioDelay(DEBOUNCE_US); /* debounce */
        *touch_state = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int touch_state = 0;
    int rc = EXIT_SUCCESS;

    if (install_signal_handlers() != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        return EXIT_FAILURE;
    }

    if (setup_touch_event_loop(&touch_state) != 0) {
        fprintf(stderr, "Error: touch event loop setup failed\n");
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Touch sensor application started. Press Ctrl+C to exit.\n");
    printf("Touching the sensor toggles the LED on GPIO%d.\n", LED_PIN);

    while (g_running) {
        if (touch_state) {
            touch_state = 0;
            if (safe_write(LED_PIN, !safe_read(LED_PIN)) != 0) {
                fprintf(stderr, "Error: failed to toggle LED\n");
                rc = EXIT_FAILURE;
                break;
            }
            printf("Touch detected — LED toggled to ON\n");
        }
        gpioDelay(10000); /* 10 ms poll interval */
    }

cleanup:
    /*
     * gpioSetAlertFunc() is automatically removed when the last
     * callback returns or the event loop exits.  If the callback
     * was not registered, gpioSetAlertFunc() returns 0 and the
     * callback is never called.  We explicitly release the line
     * to avoid any lingering callbacks.
     */
    gpioSetAlertFunc(TOUCH_PIN, NULL);
    gpioTerminate();

    if (rc == EXIT_SUCCESS)
        printf("Exiting cleanly.\n");

    return rc;
}

