#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define LED1_PIN    27
#define LED2_PIN    22
#define POLL_DELAY_US 50000   /* 50 ms */
#define BUFFER_SIZE 100

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} TouchEvent;

static TouchEvent touch_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    /* Turn off both LEDs */
    gpioWrite(LED1_PIN, 0);
    gpioWrite(LED2_PIN, 0);
    gpioTerminate();
}

static void log_touch_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }
    touch_buffer[buffer_index].sensor_pin = sensor_pin;
    touch_buffer[buffer_index].timestamp = now;
    touch_buffer[buffer_index].state = state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Touch Log ---\n");
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm tm_info;
        if (localtime_r(&touch_buffer[idx].timestamp, &tm_info) != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str) - 1);
            time_str[sizeof(time_str) - 1] = '\0';
        }
        printf("[%d] %s  Sensor: %d  State: %s\n",
               i, time_str, touch_buffer[idx].sensor_pin,
               touch_buffer[idx].state ? "TOUCHED" : "RELEASED");
    }
    printf("Overflow count: %d\n", buffer_count);
    printf("--- End of Log ---\n");
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pins as outputs */
    if (gpioSetMode(LED1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure LEDs start off */
    gpioWrite(LED1_PIN, 0);
    gpioWrite(LED2_PIN, 0);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("  Sensor 1: GPIO%d | LED1: GPIO%d\n", SENSOR1_PIN, LED1_PIN);
    printf("  Sensor 2: GPIO%d | LED2: GPIO%d\n", SENSOR2_PIN, LED2_PIN);
    printf("  Poll delay: %d ms\n", POLL_DELAY_US / 1000);
    printf("  Buffer size: %d\n", BUFFER_SIZE);
    fflush(stdout);

    int last_state1 = gpioRead(SENSOR1_PIN);
    int last_state2 = gpioRead(SENSOR2_PIN);
    if (last_state1 < 0 || last_state2 < 0) {
        fprintf(stderr, "Initial GPIO read failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (program_running) {
        int s1 = gpioRead(SENSOR1_PIN);
        int s2 = gpioRead(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "GPIO read error: %s\n", strerror(errno));
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Sensor 1 is active-high: 1 = touched */
        if (s1 != last_state1) {
            if (s1 == 1) {
                log_touch_event(SENSOR1_PIN, 1);
            } else {
                log_touch_event(SENSOR1_PIN, 0);
            }
            last_state1 = s1;
        }

        /* Sensor 2 is active-high: 1 = touched */
        if (s2 != last_state2) {
            if (s2 == 1) {
                gpioWrite(LED1_PIN, 1);
            } else {
                gpioWrite(LED1_PIN, 0);
            }
            last_state2 = s2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    print_buffer();
    cleanup();
    return EXIT_SUCCESS;
}

