    /* Cleanup */
    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();

    printf("Rain sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

