#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Si1182 Heart Rate / SpO2 logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   Si1182 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o si1182_log si1182_log.c -lpigpio -lrt
 * Run:    sudo ./si1182_log
 */

#define I2C_BUS        1
#define SI1182_ADDR    0x58          /* Si1182 default 7-bit I2C address */

/*
 * Si1182 register map (16-bit, big-endian on the bus).
 * The Si1182 is a 16-bit device; pigpio's i2cReadWordData / i2cWriteWordData
 * treat the 16-bit register as two consecutive 8-bit registers.
 */
#define REG_PART_ID     0x00
#define REG_HW_REV      0x01
#define REG_SEQ_ID      0x02
#define REG_INT_CFG     0x03
#define REG_IRQ_ENABLE  0x04
#define REG_IRQ_STATUS  0x05
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE0  0x08
#define REG_MEAS_RATE1  0x09
#define REG_PARAM_WR    0x17
#define REG_COMMAND     0x18
#define REG_RESPONSE    0x20
#define REG_HR_DATA     0x22
#define REG_SPO2_DATA   0x24

#define CMD_PARAM_SET   0x80
#define CMD_PARAM_QUERY 0x40
#define CMD_PARAM_RESET  0x01
#define CMD_PARAM_WRITE  0x02
#define CMD_PARAM_READ   0x04
#define CMD_PARAM_FORCE  0x08

#define PARAM_CHLIST    0x01
#define CHLIST_HR      0x01
#define CHLIST_SPO2    0x02

#define PARAM_MEAS_RATE 0x02
#define MEAS_RATE_100MS 0x00

#define PARAM_INT_CFG   0x03
#define INT_CFG_ADC_INT 0x01

#define PARAM_HW_KEY    0x07
#define HW_KEY_RESET   0x01

#define PARAM_IRQ_EN   0x04
#define IRQ_EN_ADC_INT 0x01

#define PARAM_IRQ_CLR  0x05
#define IRQ_CLR_ADC_INT 0x01

#define PARAM_HW_KEY_VAL 0x01
#define HW_KEY_RESET_VAL 0x01

#define PARAM_MEAS_CFG  0x08
#define MEAS_CFG_HR_SPO2 0x00

#define PARAM_INT_CFG_VAL 0x01
#define INT_CFG_ADC_INT_VAL 0x01

#define PARAM_IRQ_EN_VAL 0x01
#define IRQ_EN_ADC_INT_VAL 0x01

#define PARAM_IRQ_CLR_VAL 0x01
#define IRQ_CLR_ADC_INT_VAL 0x01

#define PARAM_MEAS_CFG_VAL 0x00
#define MEAS_CFG_HR_SPO2_VAL 0x00

#define RESP_OK 0x00
#define RESP_PARAM_ERR 0x01
#define RESP_MEAS_ERR 0x02
#define RESP_IRQ_ERR 0x03

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/*
 * Write a 16-bit command to the Si1182 command register.
 * The Si1182 expects the 16-bit command to be sent as two consecutive
 * 8-bit registers (low byte first).
 */
static int si1182_write_cmd(int handle, uint16_t cmd)
{
    char buf[2];
    buf[0] = (char)(cmd >> 8);
    buf[1] = (char)(cmd & 0xFF);

    int rc = i2cWriteDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice(cmd 0x%04X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/*
 * Write a 16-bit parameter to the Si1182 parameter register.
 * The Si1182 expects the 16-bit parameter to be sent as two consecutive
 * 8-bit registers (low byte first).
 */
static int si1182_write_param(int handle, uint16_t param, uint16_t value)
{
    char buf[4];
    buf[0] = (char)(param >> 8);
    buf[1] = (char)(param & 0xFF);
    buf[2] = (char)(value >> 8);
    buf[3] = (char)(value & 0xFF);

    int rc = i2cWriteDevice(handle, buf, 4);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice(param 0x%04X, val 0x%04X) failed: %d\n",
                param, value, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from the Si1182 response register.
 * The Si1182 expects the 16-bit response to be sent as two consecutive
 * 8-bit registers (low byte first).
 */
static int si1182_read_resp(int handle, uint16_t *out)
{
    char buf[2];
    int rc = i2cReadDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cReadDevice(resp) failed: %d\n", rc);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Read a 16-bit parameter from the Si1182 parameter register.
 * The Si1182 expects the 16-bit parameter to be sent as two consecutive
 * 8-bit registers (low byte first).
 */
static int si1182_read_param(int handle, uint16_t *out)
{
    char buf[2];
    int rc = i2cReadDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cReadDevice(param) failed: %d\n", rc);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Initialize the Si1182 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int si1182_init(int handle)
{
    uint16_t part_id, hw_rev;

    /* Verify part ID and hardware revision */
    if (si1182_read_resp(handle, &part_id) < 0)
        return -1;
    if (part_id != 0xEACC) {
        fprintf(stderr, "Unexpected PART_ID 0x%04X (expected 0xEACC)\n", part_id);
        return -1;
    }
    if (si1182_read_resp(handle, &hw_rev) < 0)
        return -1;
    if (hw_rev != 0x01) {
        fprintf(stderr, "Unexpected HW_REV 0x%02X (expected 0x01)\n", hw_rev);
        return -1;
    }

    /* Reset the Si1182 */
    if (si1182_write_cmd(handle, CMD_PARAM_RESET) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms reset settling time */

    /* Write HW_KEY to enable the device */
    if (si1182_write_cmd(handle, HW_KEY_RESET_VAL) < 0)
        return -1;

    /* Configure measurement rate */
    if (si1182_write_param(handle, PARAM_MEAS_CFG, MEAS_CFG_HR_SPO2_VAL) < 0)
        return -1;

    /* Configure interrupt: ADC interrupt on both HR and SpO2 */
    if (si1182_write_param(handle, PARAM_INT_CFG, PARAM_INT_CFG_VAL | INT_CFG_ADC_INT_VAL) < 0)
        return -1;

    /* Enable ADC interrupt */
    if (si1182_write_cmd(handle, PARAM_IRQ_EN | IRQ_EN_ADC_INT_VAL) < 0)
        return -1;

    /* Clear any pending interrupts */
    if (si1182_write_cmd(handle, PARAM_IRQ_CLR | IRQ_CLR_ADC_INT_VAL) < 0)
        return -1;

    return 0;
}

/*
 * Read heart rate and SpO2 data from the Si1182.
 * Returns 0 on success, -1 on failure.
 */
static int si1182_read_data(int handle, int *heart_rate, int *spo2)
{
    uint16_t hr_raw, spo2_raw;

    /* Trigger a single measurement */
    if (si1182_write_cmd(handle, MEAS_CFG_HR_SPO2_VAL) < 0)
        return -1;

    /* Poll the response register for measurement completion */
    for (int i = 0; i < 10; i++) {
        if (si1182_read_resp(handle, &hr_raw) < 0)
            return -1;
        if (hr_raw == RESP_OK)
            break;
        gpioDelay(10000); /* 10 ms */
    }
    if (hr_raw != RESP_OK) {
        fprintf(stderr, "Si1182 measurement timed out\n");
        return -1;
    }

    /* Read HR and SpO2 data */
    if (si1182_read_resp(handle, &hr_raw) < 0)
        return -1;
    *heart_rate = (int)hr_raw;

    if (si1182_read_resp(handle, &spo2_raw) < 0)
        return -1;
    *spo2 = (int)spo2_raw;

    return 0;
}

static void log_data(FILE *fp, int heart_rate, int spo2)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", ts, heart_rate, spo2);
    fflush(fp);
}

int main(void)
{
    int i2c_handle = -1;
    FILE *log_file = NULL;
    int ret_code = EXIT_FAILURE;

    if (install_sigint_handler() < 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1182_ADDR, i2c_handle);
        goto cleanup_gpio;
    }

    if (si1182_init(i2c_handle) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        goto cleanup_i2c;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open biometric_log.txt\n");
        goto cleanup_i2c;
    }

    printf("Si1182 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int heart_rate, spo2;

        if (si1182_read_data(i2c_handle, &heart_rate, &spo2) == 0) {
            log_data(log_file, heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read Si1182 data\n");
        }

        gpioDelay(1000000); /* 1 second */
    }

    printf("\nShutting down...\n");
    ret_code = EXIT_SUCCESS;

cleanup_i2c:
    if (log_file != NULL)
        fclose(log_file);
cleanup_gpio:
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();
    return ret_code;
}

