/*
 * Bridge Integrity Monitor — Raspberry Pi Zero W
 * Sensors : 2x Omron D7E-3 tilt sensors (digital, active-high)
 *   Sensor 1 -> GPIO17 (BCM)
 *   Sensor 2 -> GPIO18 (BCM)
 * Alarm   : active-high buzzer/LED on GPIO27 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bridge_monitor bridge_monitor.c -lpigpio -lrt
 * Run:    sudo ./bridge_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27

#define TILT_THRESHOLD_SEC 2.0
#define POLL_INTERVAL_US   100000   /* 100 ms */
#define LOG_FILE_NAME      "bridge_integrity.log"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_local);
}

static int log_event(FILE *fp, const char *event)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(fp, "%s,%s\n", ts, event) < 0) {
        perror("fprintf to log file");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush log file");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Alarm control                                                       */
/* ------------------------------------------------------------------ */
static int alarm_set(int level)
{
    if (gpioWrite(ALARM_PIN, level) < 0) {
        fprintf(stderr, "gpioWrite(ALARM, %d) failed\n", level);
        return -1;
    }
    return 0;
}

static int alarm_off(void)
{
    return alarm_set(0);
}

/* ------------------------------------------------------------------ */
/* Sensor reading                                                      */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed\n", pin);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure alarm is off regardless of current state */
    (void)alarm_off();

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ------------------------------------------ */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SENSOR1, PI_INPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SENSOR2, PI_INPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ALARM, PI_OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Internal pull-down resistors on sensor pins */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR1, PI_PUD_DOWN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR2, PI_PUD_DOWN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Alarm starts OFF */
    if (alarm_off() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file ---------------------------------------------------- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write a header only if the file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,event\n");
        fflush(g_log_fp);
    }

    /* --- Signals ----------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Bridge integrity monitoring started.\n");
    printf("  Sensor 1 : GPIO%d\n", SENSOR_1_PIN);
    printf("  Sensor 2 : GPIO%d\n", SENSOR_2_PIN);
    printf("  Alarm    : GPIO%d\n", ALARM_PIN);
    printf("  Log file : %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --------------------------------------------------- */
    int prev_s1 = read_sensor(SENSOR_1_PIN);
    int prev_s2 = read_sensor(SENSOR_2_PIN);
    if (prev_s1 < 0 || prev_s2 < 0) {
        fprintf(stderr, "Initial sensor read failed; aborting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error; aborting.\n");
            break;
        }

        /* Sensor 1 tilt-start event */
        if (s1 == 1 && prev_s1 == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            if (log_event(g_log_fp, "tilt_start") != 0) {
                fprintf(stderr, "Failed to log tilt_start event.\n");
            }
            printf("[%s] Tilt START on sensor 1\n", ts);
        }
        prev_s1 = s1;

        /* Sensor 2 tilt-start event */
        if (s2 == 1 && prev_s2 == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            if (log_event(g_log_fp, "tilt_start") != 0) {
                fprintf(stderr, "Failed to log tilt_start event.\n");
            }
            printf("[%s] Tilt START on sensor 2\n", ts);
        }
        prev_s2 = s2;

        /* Alarm condition: both sensors HIGH for TILT_THRESHOLD_SEC */
        if (s1 == 1 && s2 == 1) {
            double elapsed = 0.0;
            while (g_running && elapsed < TILT_THRESHOLD_SEC) {
                gpioDelay(POLL_INTERVAL_US);
                elapsed += (double)POLL_INTERVAL_US / 1e6;
            }
            if (elapsed >= TILT_THRESHOLD_SEC) {
                if (log_event(g_log_fp, "tilt_exceeded") != 0) {
                    fprintf(stderr, "Failed to log tilt_exceeded event.\n");
                }
                printf("[%s] Tilt EXCEEDED (both sensors HIGH)\n", ts);
                if (alarm_set(1) < 0) {
                    fprintf(stderr, "Failed to activate alarm.\n");
                }
            }
        }

        /* Alarm condition: both sensors HIGH for TILT_THRESHOLD_SEC */
        if (s1 == 1 && s2 == 1) {
            double elapsed = 0.0;
            while (g_running && elapsed < TILT_THRESHOLD_SEC) {
                gpioDelay(POLL_INTERVAL_US);
                elapsed += (double)POLL_INTERVAL_US / 1e6;
            }
            if (elapsed >= TILT_THRESHOLD_SEC) {
                if (log_event(g_log_fp, "tilt_end") != 0) {
                    fprintf(stderr, "Failed to log tilt_end event.\n");
                }
                printf("[%s] Tilt END (both sensors HIGH)\n", ts);
                if (alarm_set(0) < 0) {
                    fprintf(stderr, "Failed to deactivate alarm.\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

