/*
 * seismic.c — Raspberry Pi 3 Model B+
 *
 * Omron D7S-A0011 seismic sensor on I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL).
 * Polls every 100 ms, logs exceedances to seismic_events.log,
 * lights an alert LED on GPIO17 for 1 s per event.
 *
 * Build:  gcc -O2 -Wall -o seismic seismic.c -lthe driver library -lm -lrt
 * Run:    sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <the/the.h>

/* ---- Configuration ---- */
#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x30
#define LED_GPIO       17
#define THRESHOLD      500
#define POLL_MS        100
#define LED_ON_MS      1000
#define MAX_RETRIES    3
#define LOG_FILE       "seismic_events.log"

/* ---- D7S-A0011 register addresses ---- */
#define REG_CTRL1      0x00
#define REG_CTRL2      0x01
#define REG_STATUS     0x02
#define REG_X_OUT_L    0x04
#define REG_X_OUT_H    0x05
#define REG_Y_OUT_L    0x06
#define REG_Y_OUT_H    0x07
#define REG_Z_OUT_L    0x08
#define REG_Z_OUT_H    0x09

/* CTRL1: bit 0 = power-down; bit 1 = vibration measurement enable */
#define CTRL1_PD       0x01
#define CTRL1_VIB      0x02

/* CTRL2: bits 0-1 = vibration range (00 = ±2 g) */
#define CTRL2_RANGE_00 0x00

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_fp   = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a D7S register. Returns 0 on success, -1 on error. */
static int d7s_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a D7S register. Returns 0 on success, -1 on error. */
static int d7s_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C reg-select 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair. Returns 0 on success, -1 on error. */
static int d7s_read_reg16(int fd, uint8_t reg_l, uint16_t *out)
{
    uint8_t lo, hi;
    if (d7s_read_reg(fd, reg_l, &lo) < 0) return -1;
    if (d7s_read_reg(fd, reg_l + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the D7S: verify presence, clear PD bit, set range. */
static int d7s_init(int fd)
{
    uint8_t id;
    if (d7s_read_reg(fd, REG_CTRL1, &id) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", SENSOR_ADDR);
        return -1;
    }
    if (id != 0x01) {
        fprintf(stderr, "Unexpected sensor ID 0x%02X (expected 0x01)\n", id);
        return -1;
    }

    /* Clear power-down bit (bit 0) so the sensor is awake. */
    if (d7s_write_reg(fd, REG_CTRL1, 0x00) < 0) return -1;

    /* Set vibration range to ±2 g (bits 0-1 = 00). */
    if (d7s_write_reg(fd, REG_CTRL2, CTRL2_RANGE_00) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample (X, Y, Z) from the D7S. Returns 0 on success, -1 on error. */
static int d7s_read_sample(int fd, uint16_t *x, uint16_t *y, uint16_t *z)
{
    if (d7s_read_reg16(fd, REG_X_OUT_L, x) < 0) return -1;
    if (d7s_read_reg16(fd, REG_Y_OUT_L, y) < 0) return -1;
    if (d7s_read_reg16(fd, REG_Z_OUT_L, z) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute the Euclidean magnitude of a 3-component vector. */
static double calc_magnitude(const uint16_t *v)
{
    double x = (double)v[0];
    double y = (double)v[1];
    double z = (double)v[2];
    return sqrt(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, double magnitude)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Magnitude: %.2f\n", ts, magnitude);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void trigger_alert(int fd)
{
    if (gpioWrite(LED_GPIO, 1) < 0)
        fprintf(stderr, "Warning: failed to turn on LED: %s\n",
                strerror(errno));
    usleep(LED_ON_MS * 1000);
    if (gpioWrite(LED_GPIO, 0) < 0)
        fprintf(stderr, "Warning: failed to turn off LED: %s\n",
                strerror(errno));
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (d7s_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        fclose(g_log_fp);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Cannot set GPIO%d as output: %s\n",
                LED_GPIO, strerror(errno));
        fclose(g_log_fp);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    printf("Seismic monitoring started (threshold=%d). Ctrl+C to exit.\n",
           THRESHOLD);

    /* ---- Main polling loop ---- */
    while (g_running) {
        uint16_t x, y, z;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (d7s_read_sample(g_i2c_fd, &x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed.\n",
                    attempt + 1, MAX_RETRIES);
            usleep(10000);
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed after %d attempts; skipping cycle.\n",
                    MAX_RETRIES);
            usleep(POLL_MS * 1000);
            continue;
        }

        double mag = calc_magnitude(&x);
        if (mag > THRESHOLD) {
            printf("Earthquake! Magnitude: %.2f\n", mag);
            log_event(g_log_fp, mag);
            trigger_alert(g_i2c_fd);
        }

        usleep(POLL_MS * 1000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_log_fp)      fclose(g_log_fp);
    return EXIT_SUCCESS;
}

