#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define SENSOR_4_PIN 22
#define LED_PIN 18

#define POLL_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    int pins[4] = {SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN, SENSOR_4_PIN};
    int led_pin = LED_PIN;
    int sensor_values[4];
    int led_state = 0;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    for (int i = 0; i < 4; i++) {
        ret = gpioSetMode(pins[i], PI_INPUT);
        if (ret != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d (code %d).\n", pins[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure LED pin as output */
    ret = gpioSetMode(led_pin, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED pin %d (code %d).\n", led_pin, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED starts OFF */
    ret = gpioWrite(led_pin, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioWrite failed for LED pin %d (code %d).\n", led_pin, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection system started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (running) {
        for (int i = 0; i < 4; i++) {
            sensor_values[i] = gpioRead(pins[i]);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error: gpioRead failed for pin %d (code %d).\n", pins[i], sensor_values[i]);
                running = 0;
                break;
            }
        }

        /* Active-low sensors: 0 = object detected, 1 = no object */
        led_state = (sensor_values[0] || sensor_values[1] ||
                     sensor_values[2] || sensor_values[3]) ? 1 : 0;

        ret = gpioWrite(led_pin, led_state);
        if (ret != 0) {
            fprintf(stderr, "Error: gpioWrite failed for LED pin %d (code %d).\n", led_pin, ret);
            running = 0;
            break;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(led_pin, 0);
    gpioTerminate();
    printf("\nObstacle detection system stopped.\n");
    return EXIT_SUCCESS;
}

