static const char *sensor_ids[NUM_SENSORS] = {"KY026_2", "KY026_3", "KY026_4", "KY026_5", "KY026_6"};
static const char *log_path = LOG_FILE;

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r failed: %s", strerror(errno));
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime failed");
        return;
    }

    if (openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER) < 0) {
        syslog(LOG_ERR, "openlog failed: %s", strerror(errno));
        return;
    }

    if (log_event_fd = open(log_path, O_WRONLY | O_CREAT | O_APPEND, 0644) < 0) {
        syslog(LOG_ERR, "open(%s) failed: %s", log_path, strerror(errno));
        closelog();
        return;
    }

    if (fcntl(log_event_fd, F_SETLKW, 0) < 0) {
        syslog(LOG_ERR, "fcntl F_SETLKW failed: %s", strerror(errno));
        close(log_event_fd);
        closelog();
        return;
    }

    if (write(log_event_fd, message, strlen(message)) < 0) {
        syslog(LOG_ERR, "write to log failed: %s", strerror(errno));
    }

    if (fflush(log_event_fd) < 0) {
        syslog(LOG_ERR, "fflush failed: %s", strerror(errno));
    }

    if (close(log_event_fd) < 0) {
        syslog(LOG_ERR, "close log failed: %s", strerror(errno));
    }

    closelog();
}

static int acquire_line(struct gpiod_line **line)
{
    int ret = gpiod_line_request_input(*line, "flame_monitor");
    if (ret < 0) {
        syslog(LOG_ERR, "request_input failed for GPIO %u: %s", sensor_pins[sensor_id_to_index(sensor_pins, NUM_SENSORS, sensor_id)], strerror(errno));
        return -1;
    }
    *line = gpiod_line_get_line(*line);
    if (*line == NULL) {
        syslog(LOG_ERR, "get_line failed for GPIO %u: %s", sensor_pins[sensor_id_to_index(sensor_pins, NUM_SENSORS, sensor_id)], strerror(errno));
        gpiod_line_release(*line);
        return -1;
    }
    return 0;
}

static int read_line(struct gpiod_line *line, int *value)
{
    int ret = gpiod_line_get_value(line);
    if (ret < 0) {
        syslog(LOG_ERR, "get_value failed for GPIO %u: %s", sensor_pins[sensor_id_to_index(sensor_pins, NUM_SENSORS, sensor_id)], strerror(errno));
        return -1;
    }
    *value = ret;
    return 0;
}

static void cleanup_lines(struct gpiod_line **lines, int count)
{
    for (int i = 0; i < count; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
