    if (lines == NULL) {
        syslog(LOG_ERR, "malloc failed: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
    }

