            ", ".join(sensor_ids, sensor_ids + NUM_SENSORS));

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int current_value = -1;
            int last_value = -1;

            if (read_line(lines[i], &current_value) < 0) {
                syslog(LOG_ERR, "Failed to read sensor %s (GPIO %u).", sensor_ids[i], sensor_pins[i]);
                continue;
