            if (current_value == 0 && last_value == 1) {
                syslog(LOG_WARNING, "Flame detected on sensor %s (GPIO %u).", sensor_ids[i], sensor_pins[i]);
                log_event(sensor_ids[i] ? "Flame Detected" : "Flame Detected (debounce)");

                if (acquire_line(&lines[i]) < 0) {
                    syslog(LOG_ERR, "Failed to acquire line for sensor %s (GPIO %u) after debounce.", sensor_ids[i], sensor_pins[i]);
                } else {
                    int confirmed_value = -1;
                    int confirmed_last_value = -1;

                    if (read_line(lines[i], &confirmed_value) < 0) {
                        syslog(LOG_ERR, "Failed to read sensor %s (GPIO %u) after debounce.", sensor_ids[i], sensor_pins[i]);
                    } else if (confirmed_value == 0 && confirmed_last_value == 1) {
                        syslog(LOG_INFO, "Flame confirmed on sensor %s (GPIO %u).", sensor_ids[i], sensor_pins[i]);
                        log_event(sensor_ids[i] ? "Flame Detected" : "Flame Detected (confirmed)");
                    }
                }
            }

            last_value = current_value;
            usleep(POLL_INTERVAL_S * 1000000);
        }
    }

    syslog(LOG_INFO, "Flame monitoring stopped.");
    cleanup_lines(lines, NUM_SENSORS);
    free(lines);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

