/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring (TTP226 OUT0..OUT7 -> Raspberry Pi BCM GPIO):
 *   OUT0 -> GPIO5
 *   OUT1 -> GPIO6
 *   OUT2 -> GPIO13
 *   OUT3 -> GPIO19
 *   OUT4 -> GPIO26
 *   OUT5 -> GPIO12
 *   OUT6 -> GPIO16
 *   OUT7 -> GPIO20
 *
 * Build:  gcc -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

/* BCM pin numbers mapped to TTP226 OUT0..OUT7 */
static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[timestamp-error] %s\n", __TIME__);
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[timestamp-error] %s\n", __TIME__);
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[timestamp-error] %s\n", __TIME__);
        return;
    }
    printf("[%s] ", buf);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line_bulk prev_lines;
    int prev_values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /*
     * Build a bulk line request for all eight lines.
     * gpiod_line_bulk_init() pre-allocates the internal storage,
     * so we can safely add lines to it multiple times.
     */
    gpiod_line_bulk_init(&lines);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, touch_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /*
     * Request the lines as inputs.
     * gpiod_line_request_input() returns the line number on success,
     * or a negative error code on failure.
     */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int ret = gpiod_line_request_input(lines.lines, "ttp226-reader", NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /*
     * Read the initial state of all eight lines.
     * gpiod_line_request_input() does not immediately poll the line;
     * we must call gpiod_line_get_value() for each line individually.
     */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int val = gpiod_line_get_value(lines.lines[i]);
        if (val < 0) {
            fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_values[i] = val;
    }

    printf("TTP226 touch sensor reader started. Polling every %d ms.\n",
           POLL_INTERVAL_MS);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines.lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                        touch_pins[i], strerror(errno));
                goto cleanup;
            }

            /* Log only on state change */
            if (val != prev_values[i]) {
                print_timestamp();
                printf("Channel %d (BCM GPIO %u): %s\n",
                       i, touch_pins[i],
                       val ? "touch" : "released");
                fflush(stdout);
            }
            prev_values[i] = val;
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /*
     * gpiod_line_release() is safe to call even if the request was
     * not completed (e.g. if the program was terminated before
     * gpiod_line_request_input() returned).
     */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines.lines[i] != NULL) {
            gpiod_line_release(lines.lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

