    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line_bulk prev_lines;
    int prev_values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /*
     * Build a bulk line request for all eight lines.
     * gpiod_line_bulk_init() pre-allocates the internal storage,
     * so we can safely add lines to it multiple times.
     */
    gpiod_line_bulk_init(&lines);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, touch_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /*
     * Request the lines as inputs.
     * gpiod_line_request_input() returns the line number on success,
     * or a negative error code on failure.
     */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int ret = gpiod_line_request_input(lines.lines, "ttp226-reader", NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /*
     * Read the initial state of all eight lines.
     * gpiod_line_request_input() does not immediately poll the line;
     * we must call gpiod_line_get_value() for each line individually.
     */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int val = gpiod_line_get_value(lines.lines[i]);
        if (val < 0) {
            fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_values[i] = val;
    }

    printf("TTP226 touch sensor reader started. Polling every %d ms.\n",
           POLL_INTERVAL_MS);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines.lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                        touch_pins[i], strerror(errno));
                goto cleanup;
            }

            /* Log only on state change */
            if (val != prev_values[i]) {
                print_timestamp();
                printf("Channel %d (BCM GPIO %u): %s\n",
                       i, touch_pins[i],
                       val ? "touch" : "released");
                fflush(stdout);
            }
            prev_values[i] = val;
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /*
     * gpiod_line_release() is safe to call even if the request was
     * not completed (e.g. if the program was terminated before
     * gpiod_line_request_input() returned).
     */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines.lines[i] != NULL) {
            gpiod_line_release(lines.lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

