#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x49
#define VEML7700_REG_CONF 0x00
#define VEML7700_REG_ALS_DATA 0x04
#define VEML7700_CONF_DEFAULT 0x00
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_init(int handle) {
    if (i2cWriteByteData(handle, VEML7700_REG_CONF, VEML7700_CONF_DEFAULT) < 0) {
        fprintf(stderr, "Error: Failed to write VEML7700 configuration.\n");
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux_out) {
    int raw = i2cReadWordData(handle, VEML7700_REG_ALS_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error: I2C read failed (raw=%d).\n", raw);
        return -1;
    }
    uint16_t asl = (uint16_t)raw;
    *lux_out = (float)asl / 1.2f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < 100.0f) return 100;
    if (lux < 500.0f) return 75;
    if (lux < 1000.0f) return 50;
    return 25;
}

static int set_led_brightness(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for GPIO %d.\n", gpio);
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }
    if (fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n",
                timestamp, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: Failed to flush log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (error=%d).\n",
                I2C_BUS, VEML7700_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (veml7700_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VEML7700 sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Adaptive grow light system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (veml7700_read_lux(i2c_handle, &lux) != 0) {
            fprintf(stderr, "Error: Sensor read failed, retrying in 1 second.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        if (set_led_brightness(LED_GPIO, brightness) != 0) {
            fprintf(stderr, "Error: Failed to set LED brightness.\n");
        }

        if (log_data(log_file, lux, brightness, 0) != 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

