#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define POLL_DELAY_US 50000
#define LOG_FILE "touch_log.txt"

static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

static void control_led(int state) {
    if (gpioWrite(LED_PIN, state) != 0) {
        fprintf(stderr, "gpioWrite(LED_PIN=%d, %d) failed\n", LED_PIN, state);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LED_PIN=%d, PI_OUTPUT) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode(touch_pins[%d], PI_INPUT) failed\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "gpioSetPullUpDown(touch_pins[%d], PI_PUD_DOWN) failed\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    control_led(0);

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_state[NUM_CHANNELS] = {0};
    int first_read = 1;

    while (running) {
        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int level = gpioRead(touch_pins[i]);
            if (level < 0) {
                fprintf(stderr, "gpioRead(touch_pins[%d]) failed\n", touch_pins[i]);
                continue;
            }

            if (level != last_state[i]) {
                if (first_read || level == 1) {
                    any_touched = 1;
                }
                last_state[i] = level;
            }
        }

        if (any_touched) {
            for (int i = 0; i < NUM_CHANNELS; i++) {
                if (gpioWrite(LED_PIN, level) != 0) {
                    fprintf(stderr, "gpioWrite(LED_PIN=%d, %d) failed\n", LED_PIN, level);
                }
            }
            control_led(1);
        } else {
            control_led(0);
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "gpioWrite(LED_PIN=%d, 0) failed\n", LED_PIN);
            }
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (gpioDelay(POLL_DELAY_US) != 0) {
                perror("gpioDelay");
            }
        }
    }

    control_led(0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

