/*
 * OPT3001 ambient light sensor reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   OPT3001 SDA  -> GPIO2  (I2C1 SDA, pin 3)
 *   OPT3001 SCL  -> GPIO3  (I2C1 SCL, pin 5)
 *   OPT3001 VDD  -> 3.3 V
 *   OPT3001 GND  -> GND
 *
 * I2C bus 1 (/dev/i2c-1)
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_monitor light_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x49
#define LOG_FILE       "light_data.txt"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define CONFIG_DELAY   0.1        /* ms after writing config before first read */

/* OPT3001 register addresses (16-bit, big-endian on the bus) */
#define REG_RESULT     0x00
#define REG_CONFIG     0x01
#define REG_PART_ID    0x02

/* OPT3001 part ID */
#define OPT3001_PART_ID 0x3001

/* OPT3001 config register bits (16-bit, big-endian) */
#define CONFIG_GAIN_1X  0x0000
#define CONFIG_GAIN_4X  0x0100
#define CONFIG_GAIN_16X 0x0200
#define CONFIG_GAIN_64X 0x0300
#define CONFIG_MODE_CONT 0x0000
#define CONFIG_MODE_SINGLE 0x0100
#define CONFIG_MODE_TRIGGER 0x0200
#define CONFIG_TRIGGER_AUTO 0x0300
#define CONFIG_TRIGGER_MAN 0x0400
#define CONFIG_TRIGGER_EXT 0x0500
#define CONFIG_TRIGGER_INT 0x0600
#define CONFIG_TRIGGER_INT_EN 0x0700
#define CONFIG_TRIGGER_INT_MASK 0x0800
#define CONFIG_TRIGGER_INT_STATUS 0x0900
#define CONFIG_TRIGGER_INT_CLEAR 0x0A00
#define CONFIG_TRIGGER_INT_SET  0x0B00
#define CONFIG_TRIGGER_INT_EN_MASK 0x0F00
#define CONFIG_TRIGGER_INT_STATUS_MASK 0x0FFFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
    }
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value & 0xFF);          /* little-endian on bus */
    buf[2] = (uint8_t)((value >> 8) & 0xFF);  /* little-endian on bus */

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16(0x%02X): write reg failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16(0x%02X): read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* OPT3001 returns data in big-endian word order; swap bytes */
    *out = ((uint16_t)data[0] << 8) | (uint16_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* OPT3001 helpers                                                     */
/* ------------------------------------------------------------------ */
static int opt3001_write_config(int fd, uint16_t config)
{
    if (i2c_write_reg16(fd, REG_CONFIG, config) == -1)
        return -1;
    return 0;
}

static int opt3001_read_result(int fd, uint16_t *result)
{
    return i2c_read_reg16(fd, REG_RESULT, result);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd != -1) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handler();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd == -1) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) == -1) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                OPT3001_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    uint16_t part_id = 0;
    if (i2c_read_reg16(g_i2c_fd, REG_PART_ID, &part_id) == -1) {
        fprintf(stderr, "Cannot read OPT3001 PART_ID — sensor absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (part_id != OPT3001_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%04X (expected 0x%04X) — wrong sensor?\n",
                part_id, OPT3001_PART_ID);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("OPT3001 detected (PART_ID = 0x%04X)\n", part_id);

    /* Configure: gain 1X, continuous mode, no trigger */
    uint16_t config = CONFIG_GAIN_1X | CONFIG_MODE_CONT;
    if (opt3001_write_config(g_i2c_fd, config) == -1) {
        fprintf(stderr, "Failed to write OPT3001 config\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow configuration to take effect */
    usleep(CONFIG_DELAY * 1000);

    /* Main sampling loop */
    while (g_running) {
        uint16_t raw = 0;
        if (opt3001_read_result(g_i2c_fd, &raw) == -1) {
            fprintf(stderr, "Read failed — continuing after delay\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Convert big-endian result to little-endian host order */
        uint16_t lux = (uint16_t)(raw & 0xFFFF);

        /* Build timestamp */
        time_t now = time(NULL);
        struct tm tm_info;
        if (localtime_r(&now, &tm_info) == NULL) {
            fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
            sleep(SAMPLE_PERIOD);
            continue;
        }
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        /* Print to stdout */
        printf("%s, %u lux\n", ts, lux);
        fflush(stdout);

        /* Append to log file */
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        } else {
            if (fprintf(fp, "%s, %u\n", ts, lux) < 0) {
                fprintf(stderr, "fprintf to %s failed: %s\n", LOG_FILE, strerror(errno));
            }
            if (fclose(fp) != 0) {
                fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
            }
        }

        /* Wait remainder of the sample period */
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

