    if (value < 0) {
        fprintf(stderr, "Error: Failed to read flame sensor on pin %d\n", pin);
        return -1;
    }
    return value;
}

static int trigger_alert(int pin, int duration_us) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to set alert pin %d HIGH\n", pin);
        return -1;
    }

    gpioDelay(duration_us);

    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to set alert pin %d LOW\n", pin);
        return -1;
    }

    return 0;
}

int main(void) {
    FILE *log_file = NULL;
    int ret = EXIT_SUCCESS;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = read_flame_sensor(FLAME_SENSOR_PIN);

        if (flame_detected < 0) {
            fprintf(stderr, "Warning: Sensor read error, continuing...\n");
        } else if (flame_detected == 0) {
            printf("Flame detected!\n");
            if (log_event(log_file, flame_detected) != 0) {
                fprintf(stderr, "Warning: Failed to log event\n");
            }
            if (trigger_alert(ALERT_PIN, ALERT_DURATION_US) != 0) {
                fprintf(stderr, "Warning: Failed to trigger alert\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");

    if (fclose(log_file) != 0) {
        fprintf(stderr, "Warning: Error closing log file: %s\n", strerror(errno));
    }

    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();

    printf("Cleanup complete.\n");

    return ret;
}

