            fprintf(stderr, "gpioRead failed on GPIO%d: %s\n", TOUCH_PIN, strerror(errno));
            break;
        }

        if (first_read) {
            first_read = 0;
            if (log_event(log_fp, "Touch Released") != 0) {
                break;
            }
        } else {
            if (current_state != last_state) {
