#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x54
#define CMD_START_MEAS 0x3600
#define SAMPLE_PERIOD  1.0
#define MEAS_DELAY_US  2000
#define CSV_FILE       "cooling_log.csv"
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_csv_file  = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Write a 16-bit command to the sensor ---- */
static int sensor_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Read exactly n bytes from the sensor ---- */
static int sensor_read_bytes(int handle, uint8_t *buf, int n)
{
    int total = 0;
    while (total < n) {
        int r = i2cReadDevice(handle, (char *)buf + total, n - total);
        if (r < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (got %d of %d)\n",
                    total, n);
            return -1;
        }
        total += r;
    }
    return 0;
}

/* ---- Read one measurement: flow (16-bit signed) + CRC ---- */
static int read_flow_rate(int handle, float *flow_out, uint8_t *flags,
                         int *status)
{
    uint8_t buf[3];
    if (sensor_read_bytes(handle, buf, 3) != 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 100.0f;

    if (*flow_out < FLOW_MIN || *flow_out > FLOW_MAX) {
        *status = "INVALID";
        return -1;
    }
    *status = "OK";
    *flow_out = (float)raw / 100.0f;
    *flags    = 0;
    return 0;
}

/* ---- Log a CSV row ---- */
static void log_csv(FILE *fp, float flow, uint8_t flags, const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%s,0x%02X\n", ts, flow, status, flags);
    fflush(fp);
}

/* ---- Open CSV and write header if file is new ---- */
static int open_csv(void)
{
    int file_exists = (access(CSV_FILE, F_OK) == 0);
    g_csv_file = fopen(CSV_FILE, "a");
    if (!g_csv_file) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        return -1;
    }
    if (!file_exists) {
        fprintf(g_csv_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_csv_file);
    }
    return 0;
}

/* ---- Cleanup all resources ---- */
static void cleanup(void)
{
    if (g_csv_file) {
        fclose(g_csv_file);
        g_csv_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (open_csv() != 0) {
        cleanup();
        return 1;
    }

    printf("Monitoring SLF3S-1300F on I2C bus %d, addr 0x%02X. Press Ctrl+C to stop.\n",
           I2C_BUS, I2C_ADDR);

    while (g_running) {
        float flow = 0.0f;
        uint8_t flags = 0;
        int status = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_flow_rate(g_i2c_handle, &flow, &flags, &status) == 0) {
                log_csv(g_csv_file, flow, flags, status);
                printf("Flow: %.2f ml/min, Status: %s\n", flow, status);
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                sleep(0.1);
        }

        if (g_running)
            sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

