#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define TOUCH_PIN 23
#define LED_PIN  24
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_SEC 1

static volatile sig_atomic_t g_running = 1;
static int g_log_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_touch_event(FILE *fp, int led_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, Touch detected, LED %s\n", timestamp, led_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int ret = EXIT_FAILURE;
    int led_state = 0;
    int prev_touch = 0;
    int first_read = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch pin %d as input\n", TOUCH_PIN);
        goto cleanup_gpio;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        goto cleanup_gpio;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED pin %d to LOW\n", LED_PIN);
        goto cleanup_gpio;
    }

    g_log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (g_log_fd < 0) {
        fprintf(stderr, "Cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    printf("Touch lamp started. Touch GPIO%d to toggle LED on GPIO%d. Press Ctrl+C to exit.\n",
           TOUCH_PIN, LED_PIN);

    while (g_running) {
        fd_set readfds;
        struct timeval timeout;
        int rv;

        FD_ZERO(&readfds);
        FD_SET(STDIN_FILENO, &readfds);

        timeout.tv_sec = POLL_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        rv = select(STDIN_FILENO + 1, &readfds, NULL, NULL, &timeout);

        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }

        if (rv == 0) {
            continue;
        }

        if (first_read) {
            first_read = 0;
            continue;
        }

        int touch_value = gpioRead(TOUCH_PIN);
        if (touch_value < 0) {
            fprintf(stderr, "gpioRead failed on touch pin %d\n", TOUCH_PIN);
            continue;
        }

        if (touch_value == 1 && prev_touch == 0) {
            led_state = !led_state;
            if (gpioWrite(LED_PIN, led_state) != 0) {
                fprintf(stderr, "gpioWrite failed on LED pin %d\n", LED_PIN);
            } else {
                printf("Touch detected, LED %s\n", led_state ? "ON" : "OFF");
            }
            if (log_touch_event(g_log_fd, led_state) != 0) {
                fprintf(stderr, "Failed to log touch event\n");
            }
        }

        prev_touch = touch_value;
    }

    ret = EXIT_SUCCESS;

cleanup_gpio:
    if (g_log_fd >= 0) {
        if (close(g_log_fd) != 0) {
            fprintf(stderr, "close(log) failed: %s\n", strerror(errno));
        }
        g_log_fd = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return ret;
}

