/*
 * Flame detection safety system for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - Keyes KY-026 flame sensor  (digital output, active-low)
 *     DO  -> GPIO17 (BCM, physical pin 11)
 *   - Active buzzer             -> GPIO18 (BCM, physical pin 12)
 *
 * Behavior:
 *   Polls the flame sensor every 500 ms.  On a HIGH-to-LOW transition
 *   (flame detected) logs a timestamped entry to alert_log.txt and
 *   drives the buzzer HIGH for 2 s.  Only the transition is acted
 *   upon; no continuous action while the line stays LOW.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 *
 * Run:
 *   sudo ./flame_alert
 */

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN  17   /* BCM 17, physical pin 11 */
#define BUZZER_PIN        18   /* BCM 18, physical pin 12 */
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_S 2
#define BUZZER_STEP_MS    100
#define LOG_STEP_MS       100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a timestamped entry to the alert_log.txt file.
 * Returns 0 on success, -1 on failure (message printed to stderr).
 */
static int log_event(FILE *log_fp, const char *event)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_fp, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Get lines ---- */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (flame_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (buzzer_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request flame sensor line as input ---- */
    if (gpiod_line_request_input(flame_line, "flame_sensor") != 0) {
        fprintf(stderr, "gpiod_line_request_input(flame) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Request buzzer line as output, initial value LOW ---- */
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) != 0) {
        fprintf(stderr, "gpiod_line_request_output(buzzer) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("System started. Monitoring flame sensor on GPIO%d every %d ms.\n",
           FLAME_SENSOR_PIN, POLL_INTERVAL_MS);
    printf("Buzzer on GPIO%d for %d s on HIGH-to-LOW transition.\n",
           BUZZER_PIN, BUZZER_DURATION_S);
    printf("Press Ctrl+C to exit.\n");

    int last_state = 1;   /* assume no flame at startup (active-low) */

    while (g_running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value(flame) failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        int current_state = (val == 0) ? 0 : 1;

        /* Detect HIGH-to-LOW transition (flame detected) */
        if (current_state == 0 && last_state == 1) {
            printf("FLAME DETECTED!\n");

            if (log_event(log_fp, "FLAME DETECTED") != 0) {
                fprintf(stderr, "Failed to log event.\n");
            }

            if (gpiod_line_set_value(buzzer_line, 1) != 0) {
                fprintf(stderr, "gpiod_line_set_value(buzzer, HIGH) failed: %s\n",
                        strerror(errno));
                goto cleanup;
            }

            /*
             * Buzzer duration is paced at BUZZER_STEP_MS intervals so
             * we can respond promptly to shutdown signals.  Each step
             * is 100 ms, so the total buzzer run is 2 s (50 steps).
             */
            for (int i = 0; i < BUZZER_DURATION_S * 10 && g_running; i++) {
                usleep(BUZZER_STEP_MS * 1000);
            }

            if (gpiod_line_set_value(buzzer_line, 0) != 0) {
                fprintf(stderr, "gpiod_line_set_value(buzzer, LOW) failed: %s\n",
                        strerror(errno));
                goto cleanup;
            }
        }

        last_state = current_state;

        /*
         * Poll interval is paced at POLL_INTERVAL_MS intervals so
         * we can respond promptly to shutdown signals.  Each step
         * is 100 ms, so the total poll run is 500 ms.
         */
        for (int i = 0; i < POLL_INTERVAL_MS * 10 && g_running; i++) {
            usleep(LOG_STEP_MS * 1000);
        }
    }

    printf("\nSystem stopped.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure buzzer is off */
    if (buzzer_line != NULL) {
        if (gpiod_line_set_value(buzzer_line, 0) != 0) {
            fprintf(stderr, "Warning: failed to turn off buzzer during cleanup: %s\n",
                    strerror(errno));
        }
        gpiod_line_release(buzzer_line);
    }
    if (flame_line != NULL) {
        gpiod_line_release(flame_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    return ret;
}

