#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define DEBOUNCE_DELAY_US 200000  /* 200 ms */
#define POLL_DELAY_US 10000       /* 10 ms  */
#define LOG_FILE "touch_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_touch_sensor(void)
{
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d (rc=%d).\n", TOUCH_SENSOR_PIN, value);
        return -1;
    }
    return value;
}

static int toggle_led(void)
{
    int current = gpioRead(LED_PIN);
    if (current < 0) {
        fprintf(stderr, "Error: failed to read LED state on GPIO%d (rc=%d).\n", LED_PIN, current);
        return -1;
    }

    if (gpioWrite(LED_PIN, !current) != 0) {
        fprintf(stderr, "Error: failed to toggle LED state on GPIO%d.\n", LED_PIN);
        return -1;
    }
    return 0;
}

static int log_touch_event(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: gmtime_r failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    return 0;
}

static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* gpioWrite(LED_PIN, 0) is safe to call even if gpioTerminate() is not called */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_state = read_touch_sensor();
    if (last_state < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = read_touch_sensor();
        if (current_state < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        if (current_state == 1 && last_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (running) {
                if (toggle_led() != 0) {
                    cleanup();
                    return EXIT_FAILURE;
                }
                if (log_touch_event() != 0) {
                    cleanup();
                    return EXIT_FAILURE;
                }
            }
        }

        last_state = current_state;
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

