/*
 * TMAG5110A1 Hall-Effect Latch Monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO4  (BCM)
 *   Sensor 2 OUT -> GPIO17 (BCM)
 *   Sensor 3 OUT -> GPIO27 (BCM)
 *
 * The TMAG5110A1 latch outputs an open-drain signal:
 *   - Magnet present  -> OUT = logic LOW (active low)
 *   - Magnet absent   -> OUT = logic HIGH (active high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_monitor mag_monitor.c -lpigpio -lrt
 * Run:    sudo ./mag_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE    "magnet_log.txt"
#define POLL_US     100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, int sensor_id, int state)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s - Sensor %d: %s\n", ts, sensor_id,
                state ? "Magnet Present" : "Magnet Absent") < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    } else {
        fflush(fp);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int prev1 = -1, prev2 = -1, prev3 = -1;
    int s1, s2, s3;

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- configure sensor pins as inputs with pull-up ---------------- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR1_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR1_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR2_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR2_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR3_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR3_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- open log file ------------------------------------------------ */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring TMAG5110A1 latch sensors on GPIO%d, GPIO%d, GPIO%d.\n",
           SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop --------------------------------------------------- */
    while (g_running) {
        s1 = gpioRead(SENSOR1_PIN);
        s2 = gpioRead(SENSOR2_PIN);
        s3 = gpioRead(SENSOR3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d, s2=%d, s3=%d)\n",
                    s1, s2, s3);
            gpioDelay(POLL_US);
            continue;
        }

        /*
         * TMAG5110A1 latch:
         *   OUT = logic LOW  -> magnet present
         *   OUT = logic HIGH -> magnet absent
         *
         * We log only on a genuine state change.
         */
        if (s1 != prev1 || s2 != prev2 || s3 != prev3) {
            log_event(g_log, 1, s1);
            log_event(g_log, 2, s2);
            log_event(g_log, 3, s3);
            prev1 = s1;
            prev2 = s2;
            prev3 = s3;
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

