#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_log.txt"
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and resources are      */
/* released.  Safe to call from any level of the call stack.            */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped flame-detection line to the log file.          */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int log_flame_detection(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s: FLAME DETECTED\n", timestamp) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush of log file failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Print a flame-detection message to the console.                      */
/* ------------------------------------------------------------------ */
static void print_flame_detection(void)
{
    printf("FLAME DETECTED\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — release all resources.                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (gpioInitialise() >= 0) {  /* only if pigpio was initialised */
        gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
        gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open log file in append mode ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure flame sensor GPIO ---- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main polling loop ---- */
    int last_state = 1;  /* assume no flame at startup (HIGH) */

    while (g_running) {
        int current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d\n",
                    FLAME_SENSOR_GPIO);
            break;
        }

        /* Detect falling edge: HIGH -> LOW */
        if (current_state == 0 && last_state == 1) {
            print_flame_detection();
            if (log_flame_detection() != 0) {
                fprintf(stderr, "Warning: failed to log flame detection\n");
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

