    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure flame sensor GPIO ---- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main polling loop ---- */
    int last_state = 1;  /* assume no flame at startup (HIGH) */

    while (g_running) {
        int current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d\n",
                    FLAME_SENSOR_GPIO);
            break;
        }

        /* Detect falling edge: HIGH -> LOW */
        if (current_state == 0 && last_state == 1) {
            print_flame_detection();
            if (log_flame_detection() != 0) {
                fprintf(stderr, "Warning: failed to log flame detection\n");
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

