/*
 * touch_counter.c — Raspberry Pi Zero W
 *
 * Reads an 8-channel TTP226 capacitive touch sensor module on BCM pins
 * 5, 6, 7, 8, 9, 10, 11, 12 (OUT1–OUT8) via pigpio’s bulk/config API,
