#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define LOG_FILE     "touch_log.txt"
#define POLL_DELAY_US 10000   /* 10 ms */
#define STABILIZE_US  200000  /* 200 ms */

/* BCM pin numbers for the TTP226 OUT1–OUT8 */
static const int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};

/* BCM pin numbers for the binary counter outputs */
static const int counter_pins[8] = {17, 18, 19, 20, 21, 22, 23, 24};

/* Binary counter: bit 0 = GPIO 17, bit 7 = GPIO 24 */
static const int counter_bits[8] = {0, 1, 2, 3, 4, 5, 6, 7};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Write a single byte to a pigpio output pin.
 * Returns 0 on success, -1 on failure.
 */
static int write_output(int pin, int value)
{
    if (gpioWrite(pin, value) < 0) {
        fprintf(stderr, "gpioWrite(pin=%d, value=%d) failed: %s\n",
                pin, value, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a single sensor pin.
 * Returns 0 or 1 on success, -1 on failure.
 */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(pin=%d) failed: %s\n",
                pin, strerror(errno));
        return -1;
    }
    return v;
}

/*
 * Initialize a pigpio output pin as an output and set it low.
 * Returns 0 on success, -1 on failure.
 */
static int init_output(int pin)
{
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(pin=%d, OUTPUT) failed: %s\n",
                pin, strerror(errno));
        return -1;
    }
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "gpioWrite(pin=%d, 0) failed: %s\n",
                pin, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Configure a pigpio output pin as an output and set it low.
 * Returns 0 on success, -1 on failure.
 */
static int init_output_bulk(int pin, int mode, int value)
{
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "gpioSetMode(pin=%d, mode=%d) failed: %s\n",
                pin, mode, strerror(errno));
        return -1;
    }
    if (gpioWrite(pin, value) < 0) {
        fprintf(stderr, "gpioWrite(pin=%d, value=%d) failed: %s\n",
                pin, value, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Initialize all 8 output pins as outputs and set them all low.
 * Returns 0 on success, -1 on failure.
 */
static int init_all_outputs(void)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (init_output(counter_pins[i]) < 0)
            return -1;
    }
    return 0;
}

/*
 * Initialize the binary counter outputs.
 * Returns 0 on success, -1 on failure.
 */
static int init_counter(void)
{
    for (int i = 0; i < 8; i++) {
        if (init_output_bulk(counter_pins[i], PI_OUTPUT, 0) < 0)
            return -1;
    }
    return 0;
}

/*
 * Reset all output pins to 0.
 * Returns 0 on success, -1 on failure.
 */
static int reset_outputs(void)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioWrite(counter_pins[i], 0) < 0)
            return -1;
    }
    return 0;
}

/*
 * Log a touch event to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_touch_event(int channel, int counter_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n",
                timestamp, channel, counter_value) < 0) {
        fprintf(stderr, "fprintf() to log file failed: %s\n",
                strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter_value);
    return 0;
}

/*
 * Drive the binary counter one step forward.
 * Returns 0 on success, -1 on failure.
 */
static int drive_counter(void)
{
    for (int i = 0; i < 8; i++) {
        if (gpioWrite(counter_pins[i],
                    counter_bits[i] ? 1 : 0) < 0) {
            fprintf(stderr, "gpioWrite(counter_pins[%d], %d) failed: %s\n",
                    i, counter_bits[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

/*
 * Cleanup all acquired resources.
 */
static void cleanup(void)
{
    reset_outputs();
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize output pins */
    if (init_all_outputs() < 0) {
        fprintf(stderr, "Failed to initialize output pins.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize binary counter outputs */
    if (init_counter() < 0) {
        fprintf(stderr, "Failed to initialize binary counter outputs.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow sensor module to settle */
    gpioDelay(STABILIZE_US);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int prev_state = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int sensor_value = read_sensor(sensor_pins[i]);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor on channel %d.\n", i);
                continue;
            }

            /* TTP226 module idles at 0 V; a rising edge (3.3 V) indicates a touch */
            if (sensor_value == 1 && prev_state == 0) {
                int counter_value = (prev_state == 0) ? 0 : 255;
                if (drive_counter() < 0) {
                    fprintf(stderr, "Error driving counter.\n");
                }

                if (log_touch_event(i + 1, counter_value) < 0) {
                    fprintf(stderr, "Error logging touch event.\n");
                }
            }
            prev_state = sensor_value;
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

