#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LOG_FILE "tracking_log.csv"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Append a CSV row with timestamped sensor readings.
 * Returns 0 on success, -1 on failure (message printed to stderr).
 */
static int log_data(FILE *fp, int s1, int s2, int s3, int s4)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int pins[4] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    int sensor_pins[4] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed for pin %d\n", sensor_pins[i]);
            goto cleanup;
        }
    }

    /* --- Open log file in append mode --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* --- Write header if file is empty --- */
    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "fseek failed: %s\n", strerror(errno));
        goto cleanup;
    }
    long file_size = ftell(fp);
    if (file_size < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (file_size == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Failed to flush header: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Logging KY-033 sensor data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = gpioRead(SENSOR1_PIN);
        int s2 = gpioRead(SENSOR2_PIN);
        int s3 = gpioRead(SENSOR3_PIN);
        int s4 = gpioRead(SENSOR4_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0 || s4 < 0) {
            fprintf(stderr, "Error reading sensor GPIOs (s1=%d, s2=%d, s3=%d, s4=%d)\n",
                    s1, s2, s3, s4);
            /* Continue polling; transient read errors are not fatal */
        } else {
            if (log_data(fp, s1, s2, s3, s4) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
