        return -1;
    }

    return 0;
}

int main(void) {
    int ret = EXIT_FAILURE;
    int prev_state[2] = {1, 1};
    int current_state[2] = {1, 1};
    int last_state[2] = {1, 1};
    int debounce_count[2] = {0, 0};
    int debounce_time[2] = {0, 0};
    int debounce_start_time[2] = {0, 0};
    int last_poll_time[2] = {0, 0};
    int sensor_pins[2] = {SENSOR_1_GPIO, SENSOR_2_GPIO};
    int pins[2] = {SENSOR_1_GPIO, SENSOR_2_GPIO};
    int i;

