           SENSOR_1_GPIO, SENSOR_2_GPIO);

    while (running) {
        int s1_val, s2_val;

        s1_val = gpioRead(SENSOR_1_GPIO);
        s2_val = gpioRead(SENSOR_2_GPIO);

        if (s1_val < 0 || s2_val < 0) {
            fprintf(stderr, "Error reading GPIO%d (val=%d)\n", SENSOR_1_GPIO, s1_val);
            goto cleanup;
        }

        if (s1_val != prev_state[0] || s2_val != prev_state[1]) {
            if (s1_val == 0 && prev_state[0] == 1) {
                if (debounce_count[0] == 0 ||
                    (time_time - debounce_time[0]) > DEBOUNCE_MS) {
                    if (log_event(1) == 0) {
                        debounce_count[0]++;
