                    if (log_event(2) == 0) {
                        debounce_count[1]++;
                        debounce_time[1] = time_time;
                    }
                }
            }

            prev_state[0] = s1_val;
            prev_state[1] = s2_val;
        }

        last_state[0] = s1_val;
        last_state[1] = s2_val;
        last_poll_time[0] = time_time;
        last_poll_time[1] = time_time;

        gpioDelay(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }
    gpioTerminate();
    return ret;
}

