#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN     22
#define LOG_FILE    "obstacle_log.csv"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

static int set_led(int pin, int state)
{
    int rc = gpioWrite(pin, state);
    if (rc < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed: %s\n", pin, state, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, int s1, int s2, int led)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", SENSOR1_PIN);
        goto cleanup_gpio;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", SENSOR2_PIN);
        goto cleanup_gpio;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        goto cleanup_gpio;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        if (fprintf(log_file, "timestamp,sensor1,sensor2,led_state\n") < 0) {
            fprintf(stderr, "Error: cannot write CSV header: %s\n", strerror(errno));
            goto cleanup_log;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Error: cannot flush header: %s\n", strerror(errno));
            goto cleanup_log;
        }
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read error — turn LED off for safety and continue */
            if (set_led(LED_PIN, 0) != 0) {
                fprintf(stderr, "Warning: failed to turn LED off on sensor error\n");
            }
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Active-low sensors: 0 = obstacle detected, 1 = clear */
        int led_state = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (set_led(LED_PIN, led_state) != 0) {
            fprintf(stderr, "Warning: failed to set LED state\n");
        }

        if (log_data(log_file, s1, s2, led_state) != 0) {
            fprintf(stderr, "Warning: failed to log data\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    if (set_led(LED_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn LED off during shutdown\n");
    }

cleanup_log:
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

cleanup_gpio:
    gpioTerminate();
    return EXIT_SUCCESS;
}

