#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125
#define LED_ON_TIME_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void millisecond_sleep(unsigned int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Monitoring ICS-40180 analog microphone on GPIO%d. Press Ctrl+C to exit.\n", MIC_PIN);

    while (running) {
        int level = gpioRead(MIC_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", MIC_PIN);
            break;
        }

        if (level == 1) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

            printf("%s - Sound peak detected!\n", timestamp);

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn on LED on GPIO%d\n", LED_PIN);
                break;
            }

            millisecond_sleep(LED_ON_TIME_US);

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn off LED on GPIO%d\n", LED_PIN);
                break;
            }
        }

        millisecond_sleep(SAMPLE_PERIOD_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

