/*
 * Raspberry Pi 4 Model B - SunFounder 3-Way Tracing Sensor Reader
 *
 * Wiring (BCM numbering):
 *   Left sensor  -> GPIO17 (active-low, internal pull-up)
 *   Center sensor -> GPIO27 (active-low, internal pull-up)
 *   Right sensor  -> GPIO22 (active-low, internal pull-up)
 *
 * The sensor outputs are active-low: 0 = reflective surface detected,
 * 1 = no surface detected.
 *
 * Build: gcc -Wall -Wextra -O2 -o sensor_reader sensor_reader.c -lpigpio -lrt
 * Run:   sudo ./sensor_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define POLL_DELAY_US   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int pins[] = {LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void)
{
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("SunFounder 3-Way Tracing Sensor Reader\n");
    printf("Left: GPIO%d, Center: GPIO%d, Right: GPIO%d\n",
           LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int left_val = gpioRead(LEFT_SENSOR_PIN);
        int center_val = gpioRead(CENTER_SENSOR_PIN);
        int right_val  = gpioRead(RIGHT_SENSOR_PIN);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error: GPIO read failed (L=%d, C=%d, R=%d).\n",
                    left_val, center_val, right_val);
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        printf("Left: %s, Center: %s, Right: %s\n",
               left_val ? "ON" : "OFF",
               center_val ? "ON" : "OFF",
               right_val ? "ON" : "OFF");

        fflush(stdout);
        usleep(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

