code:
/*
 * Si1175 ALS Reader for Raspberry Pi 4 Model B
 *
 * Reads the visible ambient light (ALS) data from a Si1175 optical heart-rate
 * sensor over I2C bus 1 at 100 ms intervals.  The 16-bit raw value is
 * assembled from the LSB and MSB registers, and printed to the console.
 *
 * Wiring:
 *   Si1175 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   Si1175 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   Si1175 VDD  -> 3.3 V
 *   Si1175 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1175_als si1175_als.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1175_ADDR    0x5A
#define SI1175_REG_ALS_VIS_DATA0 0x00
#define SI1175_REG_ALS_VIS_DATA1 0x01
#define SAMPLE_PERIOD_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/*
 * Open the I2C bus and set the slave address.
 * Returns a file descriptor on success, or -1 on failure.
 */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read a single 8-bit register from the Si1175.
 * Returns 0 on success and stores the value in *out, or -1 on error.
 */
static int si1175_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/*
 * Read a 16-bit big-endian register pair from the Si1175.
 * Returns 0 on success and stores the value in *out, or -1 on error.
 */
static int si1175_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1175_read_reg8(fd, reg, &lo) < 0)
        return -1;
    if (si1175_read_reg8(fd, reg + 1, &hi) < 0)
        return -1;
    *out = ((uint16_t)hi << 8) | lo;
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handler() < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = i2c_open(I2C_BUS, SI1175_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    printf("Si1175 ALS reader started on %s (addr 0x%02X).\n",
           I2C_BUS, SI1175_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw;
        if (si1175_read_reg16(fd, SI1175_REG_ALS_VIS_DATA0, &raw) < 0) {
            fprintf(stderr, "ALS read failed; continuing.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        printf("ALS raw: 0x%04X\n", raw);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nExiting...\n");
    rc = EXIT_SUCCESS;

    if (fd >= 0)
        close(fd);

    return rc;
}

