        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor pull-up/pull-down to settle */
    gpioDelay(10000);  /* 10 ms */

    /* Main polling loop */
    while (g_running) {
        int left_val = gpioRead(LEFT_SENSOR_PIN);
        int middle_val = gpioRead(MIDDLE_SENSOR_PIN);
        int right_val = gpioRead(RIGHT_SENSOR_PIN);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            fprintf(stderr, "Error: gpioRead failed on one or more sensor pins.\n");
            break;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);
        fflush(stdout);

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    return EXIT_SUCCESS;
}

