/*
 * TTP226 8-channel capacitive touch sensor poll for Raspberry Pi 3 Model B+
 *
 * Wiring (TTP226 VCC -> 3.3V, GND -> GND, SIG -> BCM GPIOs):
 *   TP1 -> GPIO5
 *   TP2 -> GPIO6
 *   TP3 -> GPIO13
 *   TP4 -> GPIO19
 *   TP5 -> GPIO26
 *   TP6 -> GPIO12
 *   TP7 -> GPIO16
 *   TP8 -> GPIO20
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_poll touch_poll.c -lrt
 * Run:    ./touch_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 200000  /* 200 ms */

static const int touch_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        snprintf(buf, len, "[timestamp-error]");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    if (pos + 8 < len) {
        snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    printf("TTP226 touch sensor poll started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    int lines[NUM_CHANNELS];
    bool lines_requested[NUM_CHANNELS] = {false};

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = touch_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
            fprintf(stderr, "Warning: gpioSetPullUpDown failed for GPIO %d.\n", pin);
        }
        lines[i] = gpioRead(pin);
        if (lines[i] < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d.\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        lines_requested[i] = true;
    }

    printf("[");
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines_requested[i]) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            printf("%d:%s", i, ts);
        } else {
            printf("%d, ", i);
        }
    }
    printf("]\n");
    fflush(stdout);

    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (!lines_requested[i]) {
                continue;
            }

            int val = gpioRead(touch_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Error: gpioRead failed for GPIO %d (channel %d).\n",
                        touch_pins[i], i);
                goto cleanup;
            }

            char ts[32];
            get_timestamp(ts, sizeof(ts));
            printf("%s", val ? "CH" : "CH");
            if (val) {
                printf("%d", i + 1);
            } else {
                printf("0");
            }
            printf(" ");
            fflush(stdout);
        }
        printf("\n");
        fflush(stdout);

        gpioDelay(POLL_INTERVAL_US);
    }

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines_requested[i]) {
            gpioWrite(touch_pins[i], 0);
        }
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

