    if (gpioPWM(GREEN_PIN, g) < 0) {
        syslog(LOG_ERR, "Failed to set PWM on GREEN pin");
        return -1;
    }
    if (gpioPWM(BLUE_PIN, b) < 0) {
        syslog(LOG_ERR, "Failed to set PWM on BLUE pin");
        return -1;
    }
    return 0;
}

static int fade_led(uint8_t r1, uint8_t g1, uint8_t b1,
                    uint8_t r2, uint8_t g2, uint8_t b2,
                    int steps, int duration_sec)
{
    if (steps <= 0 || duration_sec <= 0) {
        syslog(LOG_ERR, "Invalid fade parameters");
        return -1;
    }

    float r_step = (float)(r2 - r1) / steps;
    float g_step = (float)(g2 - g1) / steps;
    float b_step = (float)(b2 - b1) / steps;

    for (int i = 0; i <= steps && g_running; i++) {
        float r = r1 + (float)i * r_step;
        float g = g1 + (float)i * g_step;
        float b = b1 + (float)i * b_step;

        if (r < 0) r = 0;
        if (r > 255) r = 255;
        if (g < 0) g = 0;
        if (g > 255) g = 255;
        if (b < 0) b = 0;
        if (b > 255) b = 255;

        if (set_led_color((uint8_t)r, (uint8_t)g, (uint8_t)b) != 0) {
            syslog(LOG_ERR, "Failed to set LED color during fade");
            return -1;
        }

        if (i < steps && g_running) {
            sleep(duration_sec / steps);
        }
    }
    return 0;
}

int main(void)
{
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != PWM_FREQUENCY ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != PWM_FREQUENCY ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != PWM_RANGE) {
        syslog(LOG_ERR, "Failed to set PWM range");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "RGB LED fade started. Press Ctrl+C to exit.");

    while (g_running) {
        uint8_t r1, g1, b1;
        uint8_t r2, g2, b2;

        if (generate_random_hue(&r1, &g1, &b1) != 0) {
            syslog(LOG_ERR, "Failed to generate random hue");
            break;
        }
        if (generate_random_hue(&r2, &g2, &b2) != 0) {
            syslog(LOG_ERR, "Failed to generate random hue");
            break;
        }

        if (fade_led(r1, g1, b1, r2, g2, b2, INTERPOLATION_STEPS,
                     INTERPOLATION_DURATION) != 0) {
            syslog(LOG_ERR, "Fade failed");
            break;
        }
    }

    syslog(LOG_INFO, "Shutting down RGB LED fade.");
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

