#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29
#define REG_ENABLE     0x80
#define REG_ATIME      0x01
#define REG_ID        0x12
#define REG_CDATAL     0x14
#define REG_CDATAH     0x15
#define REG_RDATAL     0x16
#define REG_RDATAH     0x17
#define REG_GDATAL     0x18
#define REG_GDATAH     0x19
#define REG_BDATAL     0x1A
#define REG_BDATAH     0x1B

#define LED_PIN        17
#define RED_THRESHOLD  200
#define POLL_DELAY_US  200000
#define INIT_DELAY_US  10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_gpio_ready = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, REG_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_ENABLE, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ATIME, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ENABLE, 0x02) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ENABLE, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ENABLE, 0x02) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ENABLE, 0x01) < 0) return -1;
    return 0;
}

static int tcs34725_read_c(int fd, uint16_t *c) {
    return i2c_read_reg16(fd, REG_CDATAL, c);
}

static int tcs34725_read_r(int fd, uint16_t *r) {
    return i2c_read_reg16(fd, REG_RDATAL, r);
}

static int tcs34725_read_g(int fd, uint16_t *g) {
    return i2c_read_reg16(fd, REG_GDATAL, g);
}

static int tcs34725_read_b(int fd, uint16_t *b) {
    return i2c_read_reg16(fd, REG_BDATAL, b);
}

static void cleanup(void) {
    if (g_gpio_ready) {
        gpioWrite(LED_PIN, 0);
        gpioSetMode(LED_PIN, PI_INPUT);
        g_gpio_ready = 0;
    }
    if (g_i2c_fd >= 0) {
        i2c_write_reg8(g_i2c_fd, REG_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_gpio_ready) {
        gpioTerminate();
        g_gpio_ready = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_gpio_ready = 1;

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", TCS34725_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    uint16_t r, g, b, c;
    int consecutive_errors = 0;

    while (g_running) {
        if (tcs34725_read_r(&r, &g, &b, &c) == 0) {
            consecutive_errors = 0;
            printf("R: %5u  G: %5u  B: %5u  C: %5u\n", r, g, b, c);
            if (r > RED_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Too many consecutive errors, re-initializing sensor...\n");
                i2c_write_reg8(g_i2c_fd, REG_ENABLE, 0x00);
                usleep(INIT_DELAY_US);
                if (tcs34725_init(g_i2c_fd) < 0) {
                    fprintf(stderr, "Re-init failed, exiting\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }
        usleep(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

