/*
 * BH1750 ambient light sensor -> 10-LED WS2812B strip brightness control
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensor: BH1750FVI on I2C bus 1 (address 0x49)
 * Strip:  10 WS2812B LEDs, data line tied to GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -o light_strip light_strip.c -lpigpio -lrt
 * Run:    sudo ./light_strip
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x49
#define BH1750_CMD_ON  0x10
#define BH1750_CMD_OFF 0x00
#define BH1750_CMD_MEAS 0x11
#define BH1750_CMD_RESET 0x80
#define BH1750_CMD_AUTO_ID 0xFE
#define BH1750_AUTO_ID_LEN  2
#define BH1750_MEAS_DELAY_US 180000   /* 180 ms */
#define BH1750_RESET_DELAY_US 2000    /* 2 ms  */
#define BH1750_CMD_DELAY_US  1000     /* 1 ms  */
#define NUM_LEDS          10
#define PWM_FREQ_HZ       1000000     /* 1 MHz */
#define PWM_RANGE         255
#define PWM_DUTY_MAX      255
#define PWM_DUTY_MIN      0
#define PWM_DUTY_STEP     1
#define SAMPLE_DELAY_US   100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* WS2812B timing helpers (no pigpio dependency)                       */
/* ------------------------------------------------------------------ */
static void ws2812b_send_byte(uint8_t byte)
{
    /*
     * WS2812B timing (10-LED strip, 1008000000 clock pulses per byte):
     *   1 x (0x00)  -> 0 us
     *   1 x (0x01)  -> 1 us
     *   1 x (0x02)  -> 1 us
     *   1 x (0x04)  -> 1 us
     *   1 x (0x08)  -> 1 us
     *   1 x (0x10)  -> 1 us
     *   1 x (0x20)  -> 1 us
     *   1 x (0x40)  -> 1 us
     *   1 x (0x80)  -> 1 us
     *   1 x (0xC0)  -> 1 us
     *   1 x (0xF0)  -> 1 us
     *   1 x (0xF8)  -> 1 us
     *   1 x (0xFC)  -> 1 us
     *   1 x (0xFF)  -> 1 us
     *
     * Byte order: 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF
     */
    uint8_t data[12];
    data[0] = 0xFF;
    data[1] = 0xFF;
    data[2] = 0xFF;
    data[3] = 0xFF;
    data[4] = 0xFF;
    data[5] = 0xFF;
    data[6] = 0xFF;
    data[7] = 0xFF;
    data[8] = 0xFF;
    data[9] = 0xFF;
    data[10] = 0xFF;
    data[11] = byte;

    for (int i = 0; i < 12; i++) {
        gpioWrite(18, (data[i] & 0x03) ? 1 : 0);
        gpioDelay(PWM_DUTY_STEP);
        gpioWrite(18, 0);
        gpioDelay(PWM_DUTY_STEP - PWM_DUTY_STEP);
    }
}

static void ws2812b_send_frame(const uint8_t *data, int len)
{
    for (int i = 0; i < len; i++)
        ws2222b_send_byte(data[i]);
}

/* ------------------------------------------------------------------ */
/* BH1750 helpers                                                      */
/* ------------------------------------------------------------------ */
static int bh1750_reset(void)
{
    if (i2cWriteByte(g_i2c_handle, BH1750_CMD_RESET) < 0)
        return -1;
    gpioDelay(BH1750_RESET_DELAY_US);
    return 0;
}

static int bh1750_auto_id(uint8_t *id)
{
    if (i2cWriteByte(g_i2c_handle, BH1750_CMD_AUTO_ID) < 0)
        return -1;
    gpioDelay(BH1750_CMD_DELAY_US);

    char buf[BH1750_AUTO_ID_LEN];
    if (i2cReadDevice(g_i2c_handle, buf, BH1750_AUTO_ID_LEN) != BH1750_AUTO_ID_LEN)
        return -1;

    for (int i = 0; i < BH1750_AUTO_ID_LEN; i++)
        id[i] = (uint8_t)buf[i];
    return 0;
}

static int bh1750_init(void)
{
    if (bh1750_reset() < 0) {
        fprintf(stderr, "BH1750 reset failed\n");
        return -1;
    }
    gpioDelay(BH1750_CMD_DELAY_US);

    if (i2cWriteByte(g_i2c_handle, BH1750_CMD_MEAS) < 0) {
        fprintf(stderr, "BH1750 measurement command failed\n");
        return -1;
    }
    gpioDelay(BH1750_MEAS_DELAY_US);

    uint8_t id[3];
    if (bh1750_auto_id(id) < 0) {
        fprintf(stderr, "BH1750 auto-ID failed\n");
        return -1;
    }
    if (id[0] != 0x55 || id[1] != 0xD9 || id[2] != 0x80) {
        fprintf(stderr, "Unexpected BH1750 auto-ID: 0x%02X 0x%02X 0x%02X\n",
                id[0], id[1], id[2]);
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(float *lux_out)
{
    if (i2cWriteByte(g_i2c_handle, BH1750_CMD_ON) < 0)
        return -1;
    gpioDelay(BH1750_CMD_DELAY_US);

    if (i2cWriteByte(g_i2c_handle, BH1750_CMD_MEAS) < 0)
        return -1;
    gpioDelay(BH1750_MEAS_DELAY_US);

    char buf[2];
    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2)
        return -1;

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED brightness mapping                                              */
/* ------------------------------------------------------------------ */
static float lux_to_brightness(float lux)
{
    if (lux < 0.0f)   lux = 0.0f;
    if (lux > 65535.0f) lux = 65535.0f;
    return (lux / 65535.0f) * 255.0f;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioPWM(18, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, BH1750_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bh1750_init() < 0) {
        fprintf(stderr, "BH1750 initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /*
     * WS2812B data line is driven by the pigpio hardware PWM/wave
     * driver on GPIO18 (BCM).  We use gpioPWM to control the
     * wave duty cycle, which in turn drives the WS2812B data line.
     *
     * Note: pigpio's gpioPWM is a software PWM that can be used to
     * drive a hardware-PWM-capable pin (e.g. 18) by setting the
     * wave period and duty cycle.  The WS2812B expects a precise
     * 1008000000 clock pulse sequence, but pigpio's gpioPWM is
     * sufficiently fast for this application.
     */
    if (gpioSetPWMfrequency(18, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(18, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(18, 0) < 0) {
        fprintf(stderr, "gpioPWM initialise failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t led_data[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++)
        led_data[i] = 0xFF;

    while (g_running) {
        float lux = 0.0f;
        if (bh1750_read_lux(&lux) < 0) {
            fprintf(stderr, "BH1750 read error; retrying in 1 s\n");
            gpioDelay(1000000);
            continue;
        }

        float brightness = lux_to_brightness(lux);
        ws2812b_send_frame(led_data, NUM_LEDS);
        gpioDelay(SAMPLE_DELAY_US);
    }

