#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SPI_BUS        0
#define SPI_SPEED_HZ   1000000
#define BH1750_ADDR_0  0x00
#define BH1750_ADDR_1  0x40
#define NUM_SENSORS    3
#define AVERAGE_WINDOW 10
#define CONVERSION_MS  180
#define FADE_MS        500
#define LOOP_DELAY_MS  100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handles[NUM_SENSORS];
static int g_spi_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open(uint8_t addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, uint16_t *light_level) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read failed (got %zd bytes): %s\n", n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *light_level = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int spi_open(uint8_t addr) {
    int fd = open("/dev/spidev%d.0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open /dev/spidev%d.0 failed: %s\n", SPI_BUS, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl SPI failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int spi_write_data(int fd, uint8_t *data, int len) {
    if (len > 32) {
        fprintf(stderr, "SPI write len %d exceeds max\n", len);
        return -1;
    }
    ssize_t n = write(fd, data, len);
    if (n != len) {
        fprintf(stderr, "SPI write failed: %s\n", n < 0 ? strerror(errno) : "short write");
        return -1;
    }
    return 0;
}

static int spi_read_data(int fd, uint8_t *data, int len) {
    ssize_t n = read(fd, data, len);
    if (n != len) {
        fprintf(stderr, "SPI read failed: %s\n", n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int set_apa102_brightness(int brightness) {
    uint8_t data[4] = {0, 0, 0, 0};
    data[0] = brightness & 0x0F;
    data[1] = (brightness >> 4) & 0xFF;
    data[2] = (brightness >> 8) & 0xFF;
    data[3] = (brightness >> 12) & 0xFF;
    if (spi_write_data(g_spi_fd, data, 4) < 0) {
        fprintf(stderr, "Failed to update APA102 brightness\n");
        return -1;
    }
    return 0;
}

static int fade_led_strip(int target_brightness) {
    int step = target_brightness / AVERAGE_WINDOW;
    for (int i = 0; i < AVERAGE_WINDOW && g_running; i++) {
        if (set_apa102_brightness(target_brightness - step * (i + 1)) < 0) {
            return -1;
        }
        usleep(FADE_MS * 1000);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        g_i2c_handles[i] = -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        int h = i2c_open(BH1750_ADDR_0);
        if (h < 0) {
            h = i2c_open(BH1750_ADDR_1);
        }
        if (h < 0) {
            fprintf(stderr, "No BH1750 sensor found at 0x%02X\n", BH1750_ADDR_0);
            continue;
        }
        g_i2c_handles[i] = h;
    }

    g_spi_fd = spi_open(BH1750_ADDR_0);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI for APA102\n");
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (g_i2c_handles[i] >= 0) {
                close(g_i2c_handles[i]);
                g_i2c_handles[i] = -1;
            }
        }
        gpioTerminate();
        return 1;
    }

    printf("Starting light-controlled LED fade. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t light_levels[NUM_SENSORS];
        bool valid = true;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (bh1750_read(g_i2c_handles[i], &light_levels[i]) < 0) {
                valid = false;
                break;
            }
        }

        if (!valid) {
            fprintf(stderr, "All BH1750 sensors failed; skipping fade cycle\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        uint16_t sum = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            sum += light_levels[i];
        }
        uint16_t avg_light = sum / NUM_SENSORS;

        if (set_apa102_brightness(avg_light) < 0) {
            fprintf(stderr, "Failed to update LED brightness\n");
        }

        if (fade_led_strip(avg_light) < 0) {
            fprintf(stderr, "Fade failed\n");
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    set_apa102_brightness(0);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_handles[i] >= 0) {
            close(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return 0;
}

