        usleep(FADE_MS * 1000);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        g_i2c_handles[i] = -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        int h = i2c_open(BH1750_ADDR_0);
        if (h < 0) {
            h = i2c_open(BH1750_ADDR_1);
        }
        if (h < 0) {
            fprintf(stderr, "No BH1750 sensor found at 0x%02X\n", BH1750_ADDR_0);
            continue;
        }
        g_i2c_handles[i] = h;
    }

    g_spi_fd = spi_open(BH1750_ADDR_0);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI for APA102\n");
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (g_i2c_handles[i] >= 0) {
                close(g_i2c_handles[i]);
                g_i2c_handles[i] = -1;
            }
        }
        gpioTerminate();
        return 1;
    }

    printf("Starting light-controlled LED fade. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t light_levels[NUM_SENSORS];
        bool valid = true;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (bh1750_read(g_i2c_handles[i], &light_levels[i]) < 0) {
                valid = false;
                break;
            }
        }

        if (!valid) {
            fprintf(stderr, "All BH1750 sensors failed; skipping fade cycle\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        uint16_t sum = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            sum += light_levels[i];
        }
        uint16_t avg_light = sum / NUM_SENSORS;

        if (set_apa102_brightness(avg_light) < 0) {
            fprintf(stderr, "Failed to update LED brightness\n");
        }

        if (fade_led_strip(avg_light) < 0) {
            fprintf(stderr, "Fade failed\n");
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    set_apa102_brightness(0);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_handles[i] >= 0) {
            close(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return 0;
}

