#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x49
#define VEML7700_REG_CONF 0x00
#define VEML7700_REG_ALS_DATA 0x04
#define LED_GPIO 18
#define BRIGHTNESS_THRESHOLD 10000
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int led_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_init(int fd) {
    if (i2c_write_reg8(fd, VEML7700_REG_CONF, 0x00) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int veml7700_read_lux(int fd, float *lux_out) {
    uint8_t als_data;
    int retries = 0;
    int delay_ms = RETRY_DELAY_MS;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg8(fd, VEML7700_REG_ALS_DATA, &als_data) == 0) {
            int16_t raw = (int16_t)als_data;
            *lux_out = (float)raw * 0.01f;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            usleep(delay_ms * 1000);
            delay_ms *= 2;
        }
    }
    return -1;
}

static void set_led_brightness(int brightness) {
    if (brightness > BRIGHTNESS_THRESHOLD) {
        brightness = BRIGHTNESS_THRESHOLD;
    }
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    for (int i = 0; i < 256; i++) {
        if (i < brightness) {
            if (led_state == 0) {
                led_state = 1;
                gpioWrite(LED_GPIO, 1);
            }
            gpioDelay(1000000 / 256);
        } else {
            if (led_state == 1) {
                led_state = 0;
                gpioWrite(LED_GPIO, 0);
            }
            gpioDelay(1000000 / 256);
        }
    }
}

static void gamma_correct(float lux, int *brightness) {
    if (lux <= 0.0f) {
        *brightness = 0;
        return;
    }
    float gamma = 2.0f;
    *brightness = (int)(powf(lux, gamma) * 255.0f);
    if (*brightness < 0) *brightness = 0;
    if (*brightness > 255) *brightness = 255;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (veml7700_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize VEML7700\n");
        close(i2c_fd);
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        close(i2c_fd);
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    while (running) {
        float lux;
        if (veml7700_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Failed to read lux after %d retries\n", MAX_RETRIES);
            continue;
        }

        int brightness;
        gamma_correct(lux, &brightness);

        set_led_brightness(brightness);
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        if (led_state == 0) {
            led_state = 1;
            gpioWrite(LED_GPIO, 1);
        } else {
            led_state = 0;
            gpioWrite(LED_GPIO, 0);
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    gpioWrite(LED_GPIO, 0);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

