#include <unistd.h>
#include <stdbool.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define NUM_SAMPLES 5
#define BLINK_DELAY_MS 500
#define LOOP_DELAY_MS 50
#define ERROR_DELAY_MS 100
#define ERROR_PATTERN_MS 200
#define ERROR_COUNT 3
#define ERROR_SHORT_MS 200
#define ERROR_LONG_MS 600

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", ts, msg);
}

static void error_output(const char *msg) {
    log_event(msg);
    gpioWrite(BUZZER_PIN, 1);
    gpioWrite(LED_PIN, 1);
    gpioDelay(ERROR_DELAY_MS * 1000);
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    log_event(msg);
    gpioTerminate();
    exit(1);
}

static void blink_led(int pin, int ms) {
    gpioWrite(pin, 1);
    gpioDelay(ms * 1000);
    gpioWrite(pin, 0);
    gpioDelay(ms * 1000);
}

static void error_output_pattern(void) {
    for (int i = 0; i < ERROR_COUNT; i++) {
        gpioWrite(BUZZER_PIN, 1);
        gpioWrite(LED_PIN, 1);
        blink_led(BUZZER_PIN, ERROR_SHORT_MS);
        blink_led(LED_PIN, ERROR_SHORT_MS);
        blink_led(BUZZER_PIN, ERROR_LONG_MS);
        blink_led(LED_PIN, ERROR_LONG_MS);
        gpioDelay(ERROR_PATTERN_MS * 1000);
    }
}

static void self_test(void) {
    log_event("Starting self-test...");
    for (int i = 0; i < NUM_SAMPLES; i++) {
        int val = gpioRead(FLAME_SENSOR_PIN);
        if (val < 0) {
            error_output("Failed to read flame sensor during self-test");
            return;
        }
        if (val == 0) {
            log_event("Flame detected on sample");
            gpioWrite(BUZZER_PIN, 1);
            gpioWrite(LED_PIN, 1);
            blink_led(BUZZER_PIN, BLINK_DELAY_MS);
            blink_led(LED_PIN, BLINK_DELAY_MS);
            gpioDelay(LOOP_DELAY_MS * 1000);
        }
    }
    if (NUM_SAMPLES == 0) {
        log_event("Self-test failed: no samples read");
        error_output("Self-test failed: no samples read");
        return;
    }
    if (NUM_SAMPLES == 1) {
        log_event("Self-test failed: flame detected on all samples");
        error_output("Self-test failed: flame detected on all samples");
        return;
    }
    log_event("Self-test passed");
}

