    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1;
    }
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        error_output("Failed to set flame sensor pin mode");
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        error_output("Failed to set buzzer pin mode");
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        error_output("Failed to set LED pin mode");
    }

    log_event("Program started");
    self_test();

    while (running) {
        int val = gpioRead(FLAME_SENSOR_PIN);
        if (val < 0) {
            error_output("Failed to read flame sensor");
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }
        if (val == 0) {
            log_event("Flame detected");
            gpioWrite(BUZZER_PIN, 1);
            gpioWrite(LED_PIN, 1);
            blink_led(BUZZER_PIN, BLINK_DELAY_MS);
            blink_led(LED_PIN, BLINK_DELAY_MS);
            gpioDelay(LOOP_DELAY_MS * 1000);
        } else {
            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);
        }
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    log_event("Program terminated");
    return 0;
}

