#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEG_A 0
#define SEG_B 1
#define SEG_C 1
#define SEG_D 1
#define SEG_E 2
#define SEG_F 2
#define SEG_G 2
#define SEG_DP 3

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

void cleanup(void) {
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_INPUT);
    gpioSetMode(LATCH_PIN, PI_INPUT);
    gpioTerminate();
}

void shift_out(int data) {
    for (int i = 7; i >= 0; i--) {
        int bit = (data >> i) & 1;
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1);
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1);
        gpioWrite(DATA_PIN, bit);
        gpioDelay(1);
    }
}

void display_digit(int digit) {
    shift_out(digit);
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1);
    gpioWrite(LATCH_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LATCH_PIN, PI_OUTPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int digit = 5;
    while (keep_running) {
        display_digit(digit);
        gpioDelay(500000);
        digit = !digit;
        if (!keep_running) break;
        display_digit(digit);
        gpioDelay(500000);
    }

    cleanup();
    return 0;
}

