#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define BLINK_PERIOD_SEC 2
#define POLL_TIMEOUT_SEC 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret;

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Get the LED line (GPIO17) */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the button line (GPIO18) */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Failed to get button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request button line as input with pull-up and falling-edge event detection */
    ret = gpiod_line_request_input_flags(button_line, "blink_button",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP |
                                          GPIOD_LINE_REQUEST_FLAG_EVENT_FALLING_EDGE);
    if (ret < 0) {
        perror("Failed to request button line as input with pull-up");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install SIGINT handler");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Press Ctrl+C to exit.\n");

    /* Main loop: blink LED with 2-second period, waiting for button press */
    while (running) {
        /* Wait for falling-edge event with 1-second timeout */
        ret = gpiod_line_event_wait(button_line, &(struct timespec){POLL_TIMEOUT_SEC, 0});
        if (ret < 0) {
            perror("Error waiting for button event");
            break;
        }
        if (ret == 0) {
            /* Timeout, no event — continue blinking */
            continue;
        }

        /* Event detected — read it to clear the flag */
        struct gpiod_line_event event;
        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            perror("Error reading button event");
            break;
        }

        /* Stop blinking and exit */
        gpiod_line_set_value(led_line, 0);
        printf("Button pressed!\n");
        break;
    }

    /* Clean up: turn off LED, release lines, close chip */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

