    while (running) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Failed to turn LED on\n");
            break;
        }
        printf("LED ON\n");
        fflush(stdout);
        time_sleep(ON_DELAY_MS / 1000.0);

        if (!running) break;

        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Failed to turn LED off\n");
            break;
        }
        printf("LED OFF\n");
        fflush(stdout);
        time_sleep(OFF_DELAY_MS / 1000.0);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

