#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <sys/time.h>
#include <sys/wait.h>
#include <gpiod.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_PERIOD_NS 10000000  /* 10 ms = 100 Hz */
#define PWM_STEP_NS 1000000     /* 1 ms per PWM step */
#define STEP_DELAY_NS 1000000  /* 1 ms */
#define CHANGE_INTERVAL_NS 1000000000LL  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int install_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    return 0;
}

static int install_signal_handler_sigterm(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ns(long ns) {
    struct timespec req = {
        .tv_sec  = ns / 1000000000L,
        .tv_nsec = ns % 1000000000L
    };
    while (nanosleep(&req, &req) == -1) {
        if (errno != EINTR) {
            perror("nanosleep");
            return;
        }
        /* Retry with remaining time */
        req.tv_sec  = ns / 1000000000L;
        req.tv_nsec = ns % 1000000000L;
    }
}

static void sleep_us(unsigned int us) {
    sleep_ns(us * 1000L);
}

static void sleep_ms(unsigned int ms) {
    sleep_ns(ms * 1000000L);
}

static void sleep_ms_ns(unsigned int ms) {
    sleep_ns(ms * 1000000L);
}

static int pwm_set_value(struct gpiod_line *line, int value) {
    if (value < 0) value = 0;
    if (value > 100) value = 100;
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: gpiod_line_set_value failed for line %d: %s\n",
                line->offset, strerror(errno));
        return -1;
    }
    return 0;
}

static void pwm_step(struct gpiod_line *r_line, struct gpiod_line *g_line,
                      struct gpiod_line *b_line, int r_val, int g_val, int b_val) {
    if (pwm_set_value(r_line, r_val) < 0) return;
    if (pwm_set_value(g_line, g_val) < 0) return;
    if (pwm_set_value(b_line, b_val) < 0) return;
}

static void pwm_pulse(struct gpiod_line *r_line, struct gpiod_line *g_line,
                      struct gpiod_line *b_line, int r_val, int g_val, int b_val,
                      long duration_ns) {
    long on_ns = duration_ns / 2;
    long off_ns = duration_ns / 2;
    pwm_step(r_line, g_line, b_line, r_val, g_val, b_val);
    sleep_ns(on_ns);
    pwm_step(r_line, g_line, b_line, 0, 0, 0);
    sleep_ns(off_ns);
}

static void change_colour(struct gpiod_line *r_line, struct gpiod_line *g_line,
                          struct gpiod_line *b_line, int *r_val, int *g_val,
                          int *b_val) {
    *r_val = rand() % 101;
    *g_val = rand() % 101;
    *b_val = rand() % 101;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *r_line = NULL, *g_line = NULL, *b_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handler() < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        return EXIT_FAILURE;
    }
    if (install_signal_handler_sigterm() < 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    r_line = gpiod_chip_get_line(chip, RED_PIN);
    g_line = gpiod_chip_get_line(chip, GREEN_PIN);
    b_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!r_line || !g_line || !b_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(r_line, "rgb-led", 0) < 0 ||
        gpiod_line_request_output(g_line, "rgb-led", 0) < 0 ||
        gpiod_line_request_output(b_line, "rgb-led", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int r_val, g_val, b_val;
        change_colour(r_line, g_line, b_line, &r_val, &g_val, &b_val);

        long next_change = 0;
        if (r_val == 0 && g_val == 0 && b_val == 0) {
            next_change = CHANGE_INTERVAL_NS;
        } else if (r_val == 100 && g_val == 100 && b_val == 100) {
            next_change = CHANGE_INTERVAL_NS;
        } else {
            next_change = 1000000000L;
        }

        if (next_change != 0) {
            pwm_pulse(r_line, g_line, b_line, r_val, g_val, b_val, next_change);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (r_line) gpiod_line_release(r_line);
    if (g_line) gpiod_line_release(g_line);
    if (b_line) gpiod_line_release(b_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

