#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C address (SA0 tied to GND) */
#define LSM303_ADDR 0x19

/* LSM303DLHC register addresses */
#define LSM303_CTRL_REG1 0x20
#define LSM303_CTRL_REG2 0x21
#define LSM303_CTRL_REG3 0x22
#define LSM303_CTRL_REG4 0x23
#define LSM303_CTRL_REG5 0x24
#define LSM303_CTRL_REG6 0x25
#define LSM303_OUT_X_L 0x28
#define LSM303_OUT_X_H 0x29
#define LSM303_OUT_Y_L 0x2A
#define LSM303_OUT_Y_H 0x2B
#define LSM303_OUT_Z_L 0x2C
#define LSM303_OUT_Z_H 0x2D

/* GPIO pin for impact interrupt (BCM numbering) */
#define IMPACT_GPIO 17

/* Default threshold in G */
#define DEFAULT_THRESHOLD 2.0f

/* Impact duration in microseconds (50 ms) */
#define IMPACT_DURATION_US 50000

/* Sampling interval in microseconds (10 Hz) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static float g_threshold = DEFAULT_THRESHOLD;

/* Function prototypes */
static int  init_i2c(void);
static int  init_lsm303(void);
static int  read_accelerometer(float *x, float *y, float *z);
static float calculate_magnitude(float x, float y, float z);
static void trigger_impact(void);
static void log_data(float x, float y, float z);
static void signal_handler(int sig);
static void cleanup(void);

int main(int argc, char *argv[])
{
    int opt;

    /* Parse command-line arguments */
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize LSM303DLHC */
    if (init_lsm303() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as output and ensure it starts LOW */
    gpioSetMode(IMPACT_GPIO, PI_OUTPUT);
    gpioWrite(IMPACT_GPIO, 0);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM303DLHC impact monitor started. Threshold: %.2f G\n", g_threshold);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        float x, y, z;

        if (read_accelerometer(&x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);
            if (magnitude > g_threshold) {
                trigger_impact();
                log_data(x, y, z);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read accelerometer data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* Initialize I2C communication on bus 1 */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle=%d)\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

/* Initialize LSM303DLHC accelerometer */
static int init_lsm303(void)
{
    /*
     * CTRL_REG1: 0x00 -> 0x00
     * CTRL_REG2: 0x00 -> 0x00
     * CTRL_REG3: 0x00 -> 0x00
     * CTRL_REG4: 0x00 -> 0x00
     * CTRL_REG5: 0x00 -> 0x00
     * CTRL_REG6: 0x00 -> 0x00
     *
     * Enable accelerometer, gyro, and SPI.
     */
    if (i2cWriteByteData(g_i2c_handle, LSM303_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(g_i2c_handle, LSM303_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG2\n");
        return -1;
    }
    if (i2cWriteByteData(g_i2c_handle, LSM303_CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG3\n");
        return -1;
    }
    if (i2cWriteByteData(g_i2c_handle, LSM303_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4\n");
        return -1;
    }
    if (i2cWriteByteData(g_i2c_handle, LSM303_CTRL_REG5, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG5\n");
        return -1;
    }
    if (i2cWriteByteData(g_i2c_handle, LSM303_CTRL_REG6, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG6\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer data from LSM303DLHC */
