static int  init_i2c(void);
static int  init_lsm303(void);
static int  read_accelerometer(float *x, float *y, float *z);
static float calculate_magnitude(float x, float y, float z);
static void trigger_impact(void);
static void log_data(float x, float y, float z);
static void signal_handler(int sig);
static void cleanup(void);

int main(int argc, char *argv[])
{
    int opt;

    /* Parse command-line arguments */
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
