#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x18
#define ALS_REG 0x00
#define RED_REG 0x02
#define GREEN_REG 0x04
#define BLUE_REG 0x06
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define SAMPLE_INTERVAL_MS 500
#define RETRY_DELAY_MS 100
#define LOG_FILE "color_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_adpd188bi(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[4];
    int rc;

    rc = i2cReadI2CBlockData(i2c_handle, ALS_REG, buf, 4);
    if (rc != 4) {
        fprintf(stderr, "I2C read error: expected 4 bytes, got %d\n", rc);
        return -1;
    }

    *als = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    *red  = ((uint16_t)(buf[2] & 0xFF) << 8) | (uint8_t)buf[3];
    *green = ((uint16_t)(buf[4] & 0xFF) << 8) | (uint8_t)buf[5];
    *blue  = ((uint16_t)(buf[6] & 0xFF) << 8) | (uint8_t)buf[7];

    return 0;
}

static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file);
}

static void control_led(uint16_t als) {
    int duty_cycle = 0;
    if (als > 1000) {
        duty_cycle = 255;
    } else if (als < 100) {
        duty_cycle = 0;
    }
    gpioPWM(LED_GPIO, duty_cycle);
}

int main(void) {
    uint16_t als, red, green, blue;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", ADPD188BI_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADPD188BI monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_adpd188bi(&als, &red, &green, &blue) == 0) {
            consecutive_errors = 0;
            log_data(als, red, green, blue);
            control_led(als);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading sensor data (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Too many consecutive errors, aborting.\n");
                break;
            }
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioPWM(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

