/*
 * Raspberry Pi Zero W – FXOS8700CQ 6-Axis Accelerometer/Magnetometer
 *
 * Wiring:
 *   FXOS8700 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   FXOS8700 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   FXOS8700 VDD  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o fxos8700_impact fxos8700_impact.c -lpigpio -lrt
 * Run:    sudo ./fxos8700_impact
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700CQ register map (verified against datasheet) ---- */
#define FXOS8700_REG_WHO_AM_I       0x0D
#define FXOS8700_REG_OUT_X_MSB      0x01
#define FXOS8700_REG_OUT_X_LSB      0x02
#define FXOS8700_REG_OUT_Y_MSB      0x03
#define FXOS8700_REG_OUT_Y_LSB      0x04
#define FXOS8700_REG_OUT_Z_MSB      0x05
#define FXOS8700_REG_OUT_Z_LSB      0x06
#define FXOS8700_REG_STATUS         0x0E
#define FXOS8700_REG_CTRL_REG1      0x2A
#define FXOS8700_REG_CTRL_REG2      0x2B
#define FXOS8700_REG_CTRL_REG3      0x2C
#define FXOS8700_REG_CTRL_REG4      0x2D
#define FXOS8700_REG_CTRL_REG5      0x2E
#define FXOS8700_REG_CTRL_REG6      0x2F
#define FXOS8700_REG_WHO_AM_I_VAL   0x77

#define I2C_BUS              1
#define SAMPLE_PERIOD_US     50000   /* 50 ms */
#define IMPACT_THRESHOLD     1.0f
#define LOG_FILE             "impact_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int fxos_write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
    }
    return rc;
}

static int fxos_read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                    */
/* ------------------------------------------------------------------ */
static int fxos_init(void)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (fxos_read_reg(FXOS8700_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "[ERROR] Cannot read WHO_AM_I – sensor absent or bus error.\n");
        return -1;
    }
    if (who_am_i != FXOS8700_REG_WHO_AM_I_VAL) {
        fprintf(stderr,
                "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who_am_i, FXOS8700_REG_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode */
