    if (i2c_read_burst(fd, GYRO_OUT_X_L, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;
    return 0;
}

static int calibrate_gyro(int fd, float *x_off, float *y_off, float *z_off) {
    int16_t raw_x, raw_y, raw_z;
    float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;
    int n = 0;
    uint8_t who_am_i;
    if (i2c_read_reg8(fd, GYRO_WHO_AM_I, &who_am_i) < 0) return -1;
    if (who_am_i != GYRO_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, GYRO_WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, GYRO_CTRL_REG1, 0x00) < 0) return -1;
    usleep(10000);
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(fd, &raw_x, &raw_y, &raw_z) < 0) return -1;
        x_sum += raw_x; y_sum += raw_y; z_sum += raw_z;
        usleep(1000);
    }
    *x_off = x_sum / CALIBRATION_SAMPLES;
    *y_off = y_sum / CALIBRATION_SAMPLES;
    *z_off = z_sum / CALIBRATION_SAMPLES;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(fp);
}

static void log_alert(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,ALERT,X=%.2f,Y=%.2f,Z=%.2f\n", ts, x, y, z);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, 0) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE): %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t who_am_i;
    if (i2c_read_reg8(g_i2c_fd, GYRO_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (i2c_write_reg8(g_i2c_fd, GYRO_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    usleep(10000);

    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;
    if (calibrate_gyro(g_i2c_fd, &x_off, &y_off, &z_off) < 0) {
        fprintf(stderr, "Calibration failed\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen("gyro_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(gyro_log.txt): %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(g_log_fp, "# timestamp,X,Y,Z\n");
    fflush(g_log_fp);

    while (g_running) {
        float x, y, z;
        if (read_gyro_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "read_gyro_data: %s\n", strerror(errno));
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        x -= x_off; y -= y_off; z -= z_off;
        log_data(g_log_fp, x, y, z);
        if (fabsf(x) > THRESHOLD_DPS || fabsf(y) > THRESHOLD_DPS || fabsf(z) > THRESHOLD_DPS) {
            log_alert(g_log_fp, x, y, z);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    return 0;
}

