/*
 * ADXL345 accelerometer reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   LED anode    -> GPIO17 (BCM, pin 11) via 330 Ω resistor -> GND
 *
 * Build:  gcc -O2 -Wall -o adxl345_log adxl345_log.c -lpigpio -lrt
 * Run:    sudo ./adxl345_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 register addresses ---- */
#define ADXL345_DEVID_AD   0x00
#define ADXL345_POWER_CTL  0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0     0x32
#define ADXL345_BW_RATE    0x2C

/* ---- Expected device ID ---- */
#define ADXL345_DEVID_EXPECTED 0x44

/* ---- Application constants ---- */
#define I2C_BUS              1
#define SAMPLE_PERIOD_US     100000   /* 100 ms -> 10 Hz */
#define LED_GPIO             17
#define THRESHOLD_G          2.0f
#define LOG_FILE             "accel_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an ADXL345 register. Returns 0 on success,
 * -1 on failure.
 */
static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an ADXL345 register. Returns 0 on success,
 * -1 on failure.
 */
static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian sample from two consecutive registers.
 * Returns 0 on success, -1 on failure.
 */
static int adxl345_read_sample(int handle, uint8_t reg, int16_t *out)
{
    uint8_t lo, hi;
    if (adxl345_read_reg(handle, reg, &lo) < 0)
        return -1;
    if (adxl345_read_reg(handle, reg + 1, &hi) < 0)
        return -1;
    *out = (int16_t)((uint16_t)lo | ((uint16_t)hi << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345: verify device ID, set full-resolution mode,
 * ±2 g range, 100 Hz data rate. Returns 0 on success, -1 on failure. */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (adxl345_read_reg(handle, ADXL345_DEVID_AD, &devid) < 0)
        return -1;
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "[ERROR] Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Power on */
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    /* Data format: full resolution, +/-2 g, no high-pass filter */
    if (adxl345_write_reg(handle, ADXL345_DATA_FORMAT, 0x08) < 0)
        return -1;

    /* Bandwidth rate: 100 Hz (0x0A) */
    if (adxl345_write_reg(handle, ADXL345_BW_RATE, 0x0A) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration in g units. Returns 0 on success, -1 on failure. */
static int adxl345_read_accel(int handle, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (adxl345_read_sample(handle, ADXL345_DATAX0, &raw_x) < 0)
        return -1;
    if (adxl345_read_sample(handle, ADXL345_DATAX0 + 2, &raw_y) < 0)
        return -1;
    if (adxl345_read_sample(handle, ADXL345_DATAX0 + 4, &raw_z) < 0)
        return -1;

    /* Full-resolution mode: 1 mg / LSB = 0.001 g / LSB */
    *x = (float)raw_x * 0.001f;
    *y = (float)raw_y * 0.001f;
    *z = (float)raw_z * 0.001f;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void control_led(float x, float y, float z)
{
    int level = (fabsf(x) > THRESHOLD_G ||
                 fabsf(y) > THRESHOLD_G ||
                 fabsf(z) > THRESHOLD_G) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) < 0)
        fprintf(stderr, "[WARN] gpioWrite(LED) failed\n");
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, 0x2F, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x2F) failed: %d\n",
                I2C_BUS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ADXL345 init ---- */
    if (adxl345_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s: %m\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 logging started.  Press Ctrl-C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float x, y, z;

        if (adxl345_read_accel(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
            control_led(x, y, z);
        } else {
            fprintf(stderr, "[WARN] I2C read failure; skipping sample\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

