#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x21

/* Accelerometer registers */
#define LSM303_ACCEL_CTRL_REG1 0x20
#define LSM303_ACCEL_OUT_X_L   0x28

/* Magnetometer registers */
#define LSM303_MAG_CTRL_REG1   0x20
#define LSM303_MAG_OUT_X_H     0x22

/* Global variables */
static int i2c_accel = -1;
static int i2c_mag   = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* Structure to hold sensor data */
typedef struct {
    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
} sensor_data_t;

/* Function prototypes */
static int init_i2c(void);
static int read_accel(sensor_data_t *data);
