static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fp != NULL) {
        fflush(g_fp);
        fclose(g_fp);
        g_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Transfer a 16-bit command word (MSB = 0) followed by a 16-bit data word.
 * Returns 0 on success, -1 on error.
 */
static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADIS16488A read                                                       */
/* ------------------------------------------------------------------ */
static int adis16488a_read_reg(uint8_t reg, uint16_t *out)
{
    uint8_t tx[3] = { 0x00, (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    /* ADIS16488A returns 16-bit data on the next transfer */
    uint8_t tx2[3] = { 0x00, 0x00, 0x00 };
    uint8_t rx2[3] = { 0 };

    if (spi_transfer(tx2, rx2, sizeof(tx2)) < 0)
        return -1;

    uint16_t value = ((uint16_t)rx2[1] << 8) | rx2[2];
    *out = value;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        perror("clock_gettime");
        snprintf(buf, len, "1970-01-01T00:00:00.000000");
        return;
    }
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_spi_fd = spi_init();
    if (g_spi_fd < 0)
        return EXIT_FAILURE;

    g_fp = fopen(CSV_FILENAME, "w");
    if (g_fp == NULL) {
        perror("fopen(" CSV_FILENAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(g_fp);

    while (g_running) {
        uint16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;
        uint16_t accel_x_raw, accel_y_raw, accel_z_raw;
        char ts[40];

        get_timestamp(ts, sizeof(ts));

        if (adis16488a_read_reg(REG_GYRO_XOUT_H, &gyro_x_raw) < 0) {
            fprintf(stderr, "%s: gyro read failed\n", ts);
            usleep(STALL_US);
            continue;
        }
        if (adis16488a_read_reg(REG_GYRO_YOUT_H, &gyro_y_raw) < 0) {
            fprintf(stderr, "%s: gyro read failed\n", ts);
            usleep(STALL_US);
            continue;
        }
        if (adis16488a_read_reg(REG_GYRO_ZOUT_H, &gyro_z_raw) < 0) {
            fprintf(stderr, "%s: gyro read failed\n", ts);
            usleep(STALL_US);
            continue;
        }
        if (adis16488a_read_reg(REG_ACCEL_XOUT_H, &accel_x_raw) < 0) {
            fprintf(stderr, "%s: accel read failed\n", ts);
            usleep(STALL_US);
            continue;
        }
        if (adis16488a_read_reg(REG_ACCEL_YOUT_H, &accel_y_raw) < 0) {
            fprintf(stderr, "%s: accel read failed\n", ts);
            usleep(STALL_US);
            continue;
        }
        if (adis16488a_read_reg(REG_ACCEL_ZOUT_H, &accel_z_raw) < 0) {
            fprintf(stderr, "%s: accel read failed\n", ts);
            usleep(STALL_US);
            continue;
        }

        float gyro_x = (float)gyro_x_raw * GYRO_SENSITIVITY;
        float gyro_y = (float)gyro_y_raw * GYRO_SENSITIVITY;
        float gyro_z = (float)gyro_z_raw * GYRO_SENSITIVITY;
        float accel_x = (float)accel_x_raw * ACCEL_SENSITIVITY;
        float accel_y = (float)accel_y_raw * ACCEL_SENSITIVITY;
        float accel_z = (float)accel_z_raw * ACCEL_SENSITIVITY;

        fprintf(g_fp, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
                ts, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        fflush(g_fp);

        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

