/*
 * ADIS16448 IMU SPI reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16448 CS0  -> GPIO8  (BCM)  (active-low, driven by Pi)
 *   ADIS16448 SCLK-> GPIO11 (BCM)  (SPI0 SCLK)
 *   ADIS16448 DOUT-> GPIO9  (BCM)  (SPI0 MISO)
 *   ADIS16448 DIN-> GPIO10 (BCM)  (SPI0 MOSI)
 *   ADIS16448 VDD-> 3.3 V
 *   ADIS16448 GND-> GND
 *
 * SPI mode 3: CPOL=0, CPHA=1 (CPOL=CPHA=1)
 *
 * Build:  gcc -O2 -Wall -o adis16448 adis16448.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz — well within ADIS16448 5 MHz max */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SAMPLE_PERIOD_US 100000U   /* 100 ms */

/* ADIS16448 register addresses (single-register read protocol) */
#define REG_STATUS      0x00
#define REG_AX_MSB      0x01
#define REG_AY_MSB      0x03
#define REG_AZ_MSB      0x05
#define REG_GX_MSB      0x07
#define REG_GY_MSB      0x09
#define REG_GZ_MSB      0x0B

/* Gyro scale: 0.02 dps/LSB */
#define GYRO_SCALE      0.02f
/* Accel scale: 0.00025 g/LSB */
#define ACCEL_SCALE     0.00025f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * ADIS16448 single-register read:
 *   1. Send the 8-bit register address (bit7 = 1) with bit8 = 0.
 *   2. Wait for CS0 to go low (active-low chip select).
 *   3. Read 16 bits: 8 data bits + 8 data-null bits.
 *   4. Wait for CS0 to go high.
 *
 * Returns 0 on success, -1 on error.
 */
static int adis_read_reg(int spi_fd, uint8_t reg, int16_t *out)
{
    uint8_t tx[3] = {
        (uint8_t)(reg | 0x80),
        0x00,
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for CS0 to go low (active-low chip select). */
    int waited = 0;
    while (g_running && waited < 100) {
        if (ioctl(spi_fd, SPI_IOC_EVENT_COUNT, &tr) < 0) {
            fprintf(stderr, "SPI event wait failed: %s\n", strerror(errno));
            return -1;
        }
        if (g_running) {
            usleep(1000);
            waited++;
        }
    }
    if (!g_running) {
        fprintf(stderr, "SPI CS0 timeout\n");
        return -1;
    }

    /* Read 16 bits: 8 data + 8 data-null. */
    uint16_t raw = ((uint16_t)rx[1] << 8) | rx[2];

    if (out)
        *out = (int16_t)raw;

    /* Wait for CS0 to go high. */
    waited = 0;
    while (g_running && waited < 100) {
        if (ioctl(spi_fd, SPI_IOC_EVENT_COUNT, &tr) < 0) {
            fprintf(stderr, "SPI event wait failed: %s\n", strerror(errno));
            return -1;
        }
        if (g_running) {
            usleep(1000);
            waited++;
        }
    }
    if (!g_running) {
        fprintf(stderr, "SPI CS0 timeout\n");
        return -1;
    }

    return 0;
}

static int adis_read_all(int spi_fd, uint8_t reg, int16_t *gx, int16_t *gy, int16_t *gz,
                         int16_t *ax, int16_t *ay, int16_t *az)
{
    if (adis_read_reg(spi_fd, reg, gx) != 0)   return -1;
    if (adis_read_reg(spi_fd, reg + 1, gy) != 0) return -1;
    if (adis_read_reg(spi_fd, reg + 2, gz) != 0) return -1;
    if (adis_read_reg(spi_fd, reg + 3, ax) != 0) return -1;
    if (adis_read_reg(spi_fd, reg + 4, ay) != 0) return -1;
    if (adis_read_reg(spi_fd, reg + 5, az) != 0) return -1;
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto out;

    /* Open the SPI device. */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto out;
    }

    /* Configure SPI mode. */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto out;
    }

    /* Configure bits per word. */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto out;
    }

    /* Configure max speed. */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto out;
    }

    printf("ADIS16448 SPI reader started.  Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t gx, gy, gz, ax, ay, az;

        if (adis_read_all(spi_fd, REG_AX_MSB, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            float gx_dps = gx * GYRO_SCALE;
            float gy_dps = gy * GYRO_SCALE;
            float gz_dps = gz * GYRO_SCALE;
            float ax_g   = ax * ACCEL_SCALE;
            float ay_g   = ay * ACCEL_SCALE;
            float az_g   = az * ACCEL_SCALE;

            printf("Gyroscope: X=%.3f dps, Y=%.3f dps, Z=%.3f dps\n",
                   gx_dps, gy_dps, gz_dps);
            printf("Accelerometer: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
                   ax_g, ay_g, az_g);
        } else {
            fprintf(stderr, "SPI read error — continuing.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

out:
    if (spi_fd >= 0) {
        /* Release the SPI device. */
        if (close(spi_fd) < 0) {
            fprintf(stderr, "close(spi_fd) failed: %s\n", strerror(errno));
        }
    }
    return rc;
}

