/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 * SPI channel 0 (CE0), 1 MHz, Mode 0
 * Reads gyroscope and accelerometer data every 100 ms.
 *
 * Build:  gcc -O2 -Wall -o imu imu.c -lpigpio -lrt
 * Run:    sudo ./imu
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* ---- ADIS16448 constants (from datasheet) ---- */
#define ADIS16448_REG_CMD       0x00
