        goto cleanup_gpio;
    }

    printf("ADIS16448 reader started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t ax, ay, az, gx, gy, gz;

        if (adis16448_read_reg(spi_handle, ADIS16448_REG_AX_OUT, &ax) != 0)
            goto next_loop;
        if (adis16448_read_reg(spi_handle, ADIS16448_REG_AY_OUT, &ay) != 0)
            goto next_loop;
        if (adis16448_read_reg(spi_handle, ADIS16448_REG_AZ_OUT, &az) != 0)
            goto next_loop;
        if (adis16448_read_reg(spi_handle, ADIS16448_REG_GX_OUT, &gx) != 0)
            goto next_loop;
        if (adis16448_read_reg(spi_handle, ADIS16448_REG_GY_OUT, &gy) != 0)
            goto next_loop;
        if (adis16448_read_reg(spi_handle, ADIS16448_REG_GZ_OUT, &gz) != 0)
            goto next_loop;

        float gx_deg = (float)gx * GYRO_SCALE;
