               gx_deg, gy_deg, gz_deg);
        printf("Accelerometer: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
               ax_g, ay_g, az_g);

    next_loop:
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    rc = EXIT_SUCCESS;

    /* --- Clean resource release --- */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
