/*
 * MPU-6886 6-axis IMU reader for Raspberry Pi 4 Model B
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL)
 * Sensitivity: 16-bit signed, 1/256 g/LSB, 1/256 dps/LSB
 * Build: gcc -O2 -Wall -o mpu6886 mpu6886.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6886_ADDR   0x68

/* MPU-6886 register addresses */
#define REG_SMPLRT_DIV   0x19
#define REG_PWR_MGMT_1   0x6B
#define REG_PWR_MGMT_2   0x6C
#define REG_GYRO_CONFIG  0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H  0x43

#define ACCEL_SENSITIVITY 1.0f   /* 1/256 g/LSB */
#define GYRO_SENSITIVITY  1.0f   /* 1/256 dps/LSB */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian register pair */
static int i2c_read_reg16_le(int fd, uint8_t reg, int16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* Initialize the MPU-6886: standby, then wake up */
static int init_mpu6886(int fd)
{
    uint8_t pwr_mgmt_1, pwr_mgmt_2;

    /* Standby mode */
    if (i2c_read_reg8(fd, REG_PWR_MGMT_1, &pwr_mgmt_1) < 0)
        return -1;
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;

    /* Wake up: set SLEEP bit in PWR_MGMT_2 */
    if (i2c_read_reg8(fd, REG_PWR_MGMT_2, &pwr_mgmt_2) < 0)
        return -1;
    pwr_mgmt_2 &= ~(1 << 6); /* SLEEP bit */
    if (i2c_write_reg8(fd, REG_PWR_MGMT_2, pwr_mgmt_2) < 0)
        return -1;

    /* Gyro: 1 kHz / 100 Hz = 10 ms / 10 ms = 1 kHz */
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, 0x00) < 0)
        return -1;

    /* Accel: 1 kHz / 100 Hz = 10 ms / 10 ms = 1 kHz */
    if (i2c_write_reg8(fd, REG_ACCEL_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

int main(void)
{
    int fd = -1;
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
    int retry_count = 3;
    bool read_ok = false;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6886 slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPU6886_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (init_mpu6886(fd) < 0) {
        fprintf(stderr, "MPU-6886 initialization failed (sensor absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6886 initialized. Reading every 50 ms. Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Read accelerometer data with retry */
        int accel_ok = 0;
        for (int attempt = 0; attempt < retry_count; attempt++) {
            if (i2c_read_reg16_le(fd, REG_ACCEL_XOUT_H, &accel_x) == 0 &&
                i2c_read_reg16_le(fd, REG_ACCEL_XOUT_H + 2, &accel_y) == 0 &&
                i2c_read_reg16_le(fd, REG_ACCEL_XOUT_H + 4, &accel_z) == 0) {
                accel_ok = 1;
                break;
            }
            usleep(1000); /* 1 ms backoff */
        }
        if (!accel_ok) {
            fprintf(stderr, "Failed to read accelerometer after %d attempts\n", retry_count);
            continue;
        }

        /* Read gyroscope data with retry */
        int gyro_ok = 0;
        for (int attempt = 0; attempt < retry_count; attempt++) {
            if (i2c_read_reg16_le(fd, REG_GYRO_XOUT_H, &gyro_x) == 0 &&
                i2c_read_reg16_le(fd, REG_GYRO_XOUT_H + 2, &gyro_y) == 0 &&
                i2c_read_reg16_le(fd, REG_GYRO_XOUT_H + 4, &gyro_z) == 0) {
                gyro_ok = 1;
                break;
            }
            usleep(1000);
        }
        if (!gyro_ok) {
            fprintf(stderr, "Failed to read gyroscope after %d attempts\n", retry_count);
            continue;
        }

        /* Print the data */
        printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        fflush(stdout);

        /* Wait 50 ms */
        usleep(50000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (fd >= 0)
        close(fd);
    return EXIT_SUCCESS;
}

