            continue;
        }

        /* Read gyroscope data with retry */
        int gyro_ok = 0;
        for (int attempt = 0; attempt < retry_count; attempt++) {
            if (i2c_read_reg16_le(fd, REG_GYRO_XOUT_H, &gyro_x) == 0 &&
                i2c_read_reg16_le(fd, REG_GYRO_XOUT_H + 2, &gyro_y) == 0 &&
                i2c_read_reg16_le(fd, REG_GYRO_XOUT_H + 4, &gyro_z) == 0) {
                gyro_ok = 1;
                break;
            }
            usleep(1000);
        }
        if (!gyro_ok) {
            fprintf(stderr, "Failed to read gyroscope after %d attempts\n", retry_count);
            continue;
        }

        /* Print the data */
        printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        fflush(stdout);

        /* Wait 50 ms */
        usleep(50000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (fd >= 0)
        close(fd);
    return EXIT_SUCCESS;
}

