/*
 * ADXL345 impact detector for Raspberry Pi Zero W
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (I2C bus 1)
 *   ADXL345 SCL -> GPIO3 (I2C bus 1)
 *   ADXL345 VDD -> 3.3 V
 *   ADXL345 GND -> GND
 *   LED anode   -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o impact_detector impact_detector.c -lpigpio -lrt
 *   sudo ./impact_detector
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants (datasheet rev 1.26) ---- */
#define ADXL345_ADDR             0x50
#define ADXL345_REG_DEVID        0x00
#define ADXL345_REG_BW_RATE      0x2C
#define ADXL345_REG_POWER_CTL    0x2D
#define ADXL345_REG_DATA_FORMAT  0x31
#define ADXL345_REG_DATAX0       0x32
#define ADXL345_REG_RESULT_X_MSB 0x33

#define ADXL345_DEVID_EXPECTED   0xE5
#define ADXL345_POWER_CTL_STANDBY 0x00
#define ADXL345_POWER_CTL_MEASURE 0x08
#define ADXL345_DATA_FORMAT_FULL_RES_2G 0x0B

/* ---- Application constants ---- */
#define I2C_BUS                 1
#define LED_GPIO                17
#define THRESHOLD_G             2.5f
#define POLL_DELAY_US           10000   /* 10 ms */
#define LED_ON_DURATION_US      500000  /* 500 ms */
#define LOG_FILE_NAME           "impact_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a byte from an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian sample from the ADXL345; returns 0 on success. */
static int adxl345_read_sample(int handle, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (i2cReadI2CBlockData(handle, reg, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C block read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = (int16_t)((uint16_t)buf[1] << 8 | buf[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345: verify device ID, set full-resolution mode,
 * then put it into standby so the user can configure the power-on
 * sequence. */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    if (adxl345_read_reg(handle, ADXL345_REG_DEVID, &devid) != 0)
        return -1;

    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "[ERROR] Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    if (adxl345_write_reg(handle, ADXL345_REG_DATA_FORMAT, ADXL345_DATA_FORMAT_FULL_RES_2G) != 0)
        return -1;

    if (adxl345_write_reg(handle, ADXL345_REG_POWER_CTL, ADXL345_POWER_CTL_STANDBY) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read and convert one full-resolution sample. Returns 0 on success. */
static int adxl345_read_sample_g(int handle, float *magnitude)
{
    int16_t raw;
    if (adxl345_read_sample(handle, ADXL345_REG_RESULT_X_MSB, &raw) != 0)
        return -1;

    /* Full-resolution mode: 1 mg / LSB, scale factor 256 for ±2 g range */
    *magnitude = (float)raw * 0.001f * 256.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_impact(FILE *fp, float magnitude, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Impact: %.2f g, X: %d, Y: %d, Z: %d\n",
            ts, magnitude, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (LED_GPIO >= 0) {
        gpioWrite(LED_GPIO, 0);
        gpioSetMode(LED_GPIO, PI_INPUT);
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ADXL345 init ---- */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- Log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s for appending\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 impact detector running. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float magnitude;
        int16_t x, y, z;

        if (adxl345_read_sample_g(g_i2c_handle, &magnitude) != 0) {
            fprintf(stderr, "[WARN] Sample read failed; retrying next cycle\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (magnitude > THRESHOLD_G) {
            printf("[IMPACT] %.2f g\n", magnitude);

            if (gpioWrite(LED_GPIO, 1) < 0)
                fprintf(stderr, "[WARN] gpioWrite(LED on) failed\n");
            gpioDelay(LED_ON_DURATION_US);
            if (gpioWrite(LED_GPIO, 0) < 0)
                fprintf(stderr, "[WARN] gpioWrite(LED off) failed\n");

            log_impact(g_log_file, magnitude, x, y, z);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

