#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ICM-20602 I2C address (SA0 tied to GND) */
#define ICM20602_ADDR 0x60

/* ICM-20602 register addresses */
#define ICM20602_REG_SMPLRT_DIV   0x01
#define ICM20602_REG_ACCEL_XOUT_H 0x2D
#define ICM20602_REG_GYRO_XOUT_H  0x33
#define ICM20602_REG_PWR_MGMT_1   0x6B

/* Burst read length for accelerometer and gyroscope data (6 bytes each) */
#define ICM20602_BURST_LEN 12

/* Sampling interval in microseconds (10 Hz) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Function to write a byte to an I2C register */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, result);
        return -1;
    }
    return 0;
}

/* Function to read a burst of bytes from an I2C register */
static int i2c_read_burst(int handle, uint8_t reg, uint8_t *data, int len) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "Error reading %d bytes from register 0x%02X: expected %d, got %d\n",
                len, reg, len, result);
        return -1;
    }
    return 0;
}

/* Function to initialize the ICM-20602 */
static int init_icm20602(int handle) {
    /* Wake up the device by clearing the sleep bit (bit 6) in PWR_MGMT_1 */
    if (i2c_write_byte(handle, ICM20602_REG_PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for power-up */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz, but we want 10 Hz) */
    if (i2c_write_byte(handle, ICM20602_REG_SMPLRT_DIV, 0x07) < 0) {
        return -1;
    }

    return 0;
}

/* Function to read accelerometer data */
static int read_accelerometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_read_burst(handle, ICM20602_REG_ACCEL_XOUT_H, data, ICM20602_BURST_LEN) < 0) {
        return -1;
    }
    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

/* Function to read gyroscope data */
static int read_gyroscope(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_read_burst(handle, ICM20602_REG_GYRO_XOUT_H, data, ICM20602_BURST_LEN) < 0) {
        return -1;
    }
    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

/* Function to log data to a CSV file */
static int log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az,
                    int16_t gx, int16_t gy, int16_t gz) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%d,%d,%d\n", timestamp, ax, ay, az, gx, gy, gz) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    int16_t ax, ay, az, gx, gy, gz;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at the ICM-20602 address */
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n", ICM20602_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize the ICM-20602 */
    if (init_icm20602(i2c_handle) < 0) {
        fprintf(stderr, "ICM-20602 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Open the log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Register the signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("Starting IMU data acquisition (10 Hz)...\n");

    /* Main loop */
    while (program_running) {
        if (read_accelerometer(i2c_handle, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
        }
        if (read_gyroscope(i2c_handle, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        if (log_data(log_file, ax, ay, az, gx, gy, gz) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

