/*
 * GY-45 MMA8451Q Impact Monitor for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MMA8451Q SDA -> GPIO2 (I2C1 SDA)
 *   MMA8451Q SCL -> GPIO3 (I2C1 SCL)
 *   MMA8451Q VDD -> 3.3 V
 *   MMA8451Q GND -> GND
 *   LED anode -> GPIO17 (BCM) via 330 Ω resistor -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o impact_monitor impact_monitor.c -lpigpio -lrt
 *   sudo ./impact_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define MMA8451Q_ADDR        0x49          /* GY-45 / MMA8451Q default I2C address */
#define LED_GPIO             17            /* BCM 17 */
#define ACCEL_THRESHOLD_G    2.0           /* 2.0 g impact threshold */
#define ACCEL_SCALE_G_PER_COUNT (1.0 / 1024.0)  /* ±2 g range: 1 g = 1024 counts */
#define POLL_DELAY_US        100000        /* 100 ms */
#define LED_ON_DELAY_US      500000        /* 500 ms */
#define LOG_FILE             "impact_log.txt"

/* MMA8451Q register addresses */
#define MMA8451Q_REG_ID       0x00
#define MMA8451Q_REG_OUT_X_MSB 0x01
#define MMA8451Q_REG_OUT_X_LSB 0x02
#define MMA8451Q_REG_OUT_Y_MSB 0x03
#define MMA8451Q_REG_OUT_Y_LSB 0x04
#define MMA8451Q_REG_OUT_Z_MSB 0x05
#define MMA8451Q_REG_OUT_Z_LSB 0x06
#define MMA8451Q_REG_CTRL_REG0 0x2A
#define MMA8451Q_REG_CTRL_REG1 0x2B

/* ----------------------------- Globals ----------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static void  signal_handler(int sig);
static int   init_i2c(void);
static int   verify_sensor(void);
static int   read_accel(int16_t *x, int16_t *y, int16_t *z);
static double calculate_magnitude(int16_t x, int16_t y, int16_t z);
static void  log_data(double magnitude);
static void  control_led(bool on);
static void  cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ----------------------------- I2C init ----------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). "
                        "Check wiring and that the GY-45 is present.\n",
                i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- Sensor verification ------------------------ */
static int verify_sensor(void)
{
    char id_buf[1];
    int  status;

    status = i2cReadI2CBlockData(i2c_handle, MMA8451Q_REG_ID, id_buf, 1);
    if (status < 0) {
        fprintf(stderr, "Error: I2C read of ID register failed (status=%d).\n",
                status);
        return -1;
    }
    if (status != 1) {
        fprintf(stderr, "Error: Unexpected byte count in ID register (got %d).\n",
                status);
        return -1;
    }

    /* MMA8451Q ID register value is 0x00 when powered on and in normal mode. */
    if ((uint8_t)id_buf[0] != 0x00) {
        fprintf(stderr, "Error: Unexpected ID value 0x%02X (expected 0x00).\n",
                (uint8_t)id_buf[0]);
        return -1;
    }

    printf("MMA8451Q verified (ID = 0x%02X).\n", (uint8_t)id_buf[0]);
    return 0;
}

/* ----------------------------- Read accelerometer ------------------------ */
static int read_accel(int16_t *x, int16_t *y, int16_t *z)
{
    char  buf[6];
    int   status;

    status = i2cReadI2CBlockData(i2c_handle, MMA8451Q_REG_OUT_X_MSB, buf, 6);
    if (status < 0) {
        fprintf(stderr, "Error: I2C read of accelerometer data failed (status=%d).\n",
                status);
        return -1;
    }
    if (status != 6) {
        fprintf(stderr, "Error: Short read of accelerometer data (got %d bytes).\n",
                status);
        return -1;
    }

    *x = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *y = (int16_t)(((uint8_t)buf[2] << 8) | (uint8_t)buf[3]);
    *z = (int16_t)(((uint8_t)buf[4] << 8) | (uint8_t)buf[5]);
    return 0;
}

/* ----------------------------- Magnitude ------------------------------- */
static double calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    return (double)sqrt((double)x * x + (double)y * y + (double)z * z);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(double magnitude)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f g\n", timestamp, magnitude);
    fflush(log_file);
}

/* ----------------------------- LED control ------------------------------- */
static void control_led(bool on)
{
    gpioWrite(LED_GPIO, on ? 1 : 0);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    int16_t  x, y, z;
    double   magnitude;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize I2C --- */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor identity --- */
    if (verify_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (running) {
        if (read_accel(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            if (magnitude > ACCEL_THRESHOLD_G) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                log_data(magnitude);
                control_led(true);
                gpioDelay(LED_ON_DELAY_US);
                control_led(false);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read accelerometer data.\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

