/*
 * ADXL345 Free-Fall Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C1 SDA, pin 3)
 *   ADXL345 SCL  -> GPIO3  (I2C1 SCL, pin 5)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   ADXL345 INT1 -> GPIO17 (physical pin 11, BCM 17)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall freefall.c -lpigpio -lrt
 *   sudo ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- ADXL345 register addresses ---- */
#define ADXL345_DEVID_AD     0x00
#define ADXL345_DEVID_MST    0x01
#define ADXL345_DEVID_X      0x02
#define ADXL345_DEVID_Y      0x03
#define ADXL345_DEVID_Z      0x04
#define ADXL345_POWER_CTL    0x2D
#define ADXL345_DATA_FORMAT  0x31
#define ADXL345_DATAX0       0x32
#define ADXL345_INT_ENABLE   0x2E
#define ADXL345_INT_MAP      0x2F
#define ADXL345_INT_SOURCE   0x30

/* ---- Application constants ---- */
#define I2C_BUS              "/dev/i2c-1"
#define ADXL345_ADDR         0x50
#define INT1_GPIO            17
#define LOG_FILE             "freefall_log.csv"
#define SAMPLE_PERIOD_US     10000   /* 10 ms -> 100 Hz */
#define POLL_TIMEOUT_MS      1000

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd   = -1;
static int  g_gpio_line = -1;
static FILE *g_log_fp   = NULL;

/* ------------------------------------------------------------------ */
/*  Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/*  ADXL345 initialization                                               */
/* ------------------------------------------------------------------ */
static int adxl345_init(int fd)
{
    uint8_t devid_ad = 0, devid_mst = 0, devid_x = 0, devid_y = 0, devid_z = 0;

    /* Read device ID registers to verify the sensor is present */
    if (i2c_read_reg(fd, ADXL345_DEVID_AD, &devid_ad) < 0) return -1;
    if (i2c_read_reg(fd, ADXL345_DEVID_MST, &devid_mst) < 0) return -1;
    if (i2c_read_reg(fd, ADXL345_DEVID_X, &devid_x) < 0) return -1;
    if (i2c_read_reg(fd, ADXL345_DEVID_Y, &devid_y) < 0) return -1;
    if (i2c_read_reg(fd, ADXL345_DEVID_Z, &devid_z) < 0) return -1;

    /* ADXL345 expected device ID: 0x60 (0x60 | 0x80 = 0x00) */
    if ((devid_ad & 0x80) || (devid_mst & 0x80) ||
        (devid_x & 0x80) || (devid_y & 0x80) || (devid_z & 0x80)) {
        fprintf(stderr, "ADXL345 device ID mismatch: "
                        "AD=0x%02X MST=0x%02X X=0x%02X Y=0x%02X Z=0x%02X\n",
                devid_ad, devid_mst, devid_x, devid_y, devid_z);
        return -1;
    }

    /* Standby mode before configuration */
    if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x00) < 0) return -1;

    /* Data format: full resolution, +/-2g, right-justified */
    if (i2c_write_reg(fd, ADXL345_DATA_FORMAT, 0x0B) < 0) return -1;

    /* Enable X, Y, Z axes */
    if (i2c_write_reg(fd, ADXL345_INT_ENABLE, 0x07) < 0) return -1;

    /* Map INT1 to X-axis low-power interrupt */
    if (i2c_write_reg(fd, ADXL345_INT_MAP, 0x01) < 0) return -1;

    /* Clear any pending interrupts */
    if (i2c_write_reg(fd, ADXL345_INT_SOURCE, 0x00) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/*  Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return -1;
    }

    /* Write header if file is empty */
    if (fseek(fp, 0, SEEK_END) == 0) {
        long sz = ftell(fp);
        if (sz == 0) {
            fprintf(fp, "Timestamp,X,Y,Z\n");
            fflush(fp);
        }
    }
    return 0;
}

static void log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    struct tm tm_info;
    char ts_str[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%d,%d,%d\n", ts_str, ts.tv_nsec / 1000000L,
            x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/*  Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADXL345_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ADXL345 init ---- */
    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    g_gpio_line = INT1_GPIO;
    if (gpioSetMode(g_gpio_line, PI_INPUT) < 0) {
        fprintf(stderr, "Cannot set GPIO%d as input: %s\n",
                g_gpio_line, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(g_gpio_line, PI_PUD_UP) < 0) {
        fprintf(stderr, "Cannot set pull-up on GPIO%d: %s\n",
                g_gpio_line, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable INT1 interrupt on rising edge */
    if (i2c_write_reg(g_i2c_fd, ADXL345_INT_MAP, 0x01) < 0) {
        fprintf(stderr, "Failed to enable INT1 interrupt\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    if (log_open(LOG_FILE) < 0) {
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        /*
         * Poll the INT1 status register (bit 0) to see if a free-fall
         * event has been captured.  The ADXL345 INT1 is active-high and
         * latches on a falling edge of the X-axis low-power interrupt.
         */
        uint8_t int_source = 0;
        int polls = 0;
        int ok = 0;

        while (polls < POLL_TIMEOUT_MS && g_running) {
            if (i2c_read_reg(g_i2c_fd, ADXL345_INT_SOURCE, &int_source) == 0) {
                if (int_source & 0x01) {
                    ok = 1;
                    break;
                }
            } else {
                polls++;
                if (polls >= POLL_TIMEOUT_MS) {
                    fprintf(stderr, "Timeout waiting for free-fall event\n");
                    break;
                }
                usleep(1000);
            }
        }

        if (ok) {
            int16_t x, y, z;
            if (i2c_read_reg(g_i2c_fd, ADXL345_DATAX0, &x) == 0 &&
                i2c_read_reg(g_i2c_fd, ADXL345_DATAX0 + 2, &y) == 0 &&
                i2c_read_reg(g_i2c_fd, ADXL345_DATAX0 + 4, &z) == 0) {

                log_sample(g_log_fp, x, y, z);
                printf("X=%d, Y=%d, Z=%d\n", x, y, z);
            } else {
                fprintf(stderr, "Failed to read acceleration data\n");
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    if (g_i2c_fd >= 0) {
        /* Put sensor in standby before closing */
        (void)i2c_write_reg(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(g_i2c_fd);
    }

    if (g_gpio_line >= 0) {
        gpioSetPullUpDown(g_gpio_line, PI_PUD_OFF);
        gpioSetMode(g_gpio_line, PI_INPUT);
        gpioSetAlertFunc(g_gpio_line, NULL);
    }

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

