    if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x00) < 0) return -1;

    /* Data format: full resolution, +/-2g, right-justified */
    if (i2c_write_reg(fd, ADXL345_DATA_FORMAT, 0x0B) < 0) return -1;

    /* Enable X, Y, Z axes */
    if (i2c_write_reg(fd, ADXL345_INT_ENABLE, 0x07) < 0) return -1;

    /* Map INT1 to X-axis low-power interrupt */
    if (i2c_write_reg(fd, ADXL345_INT_MAP, 0x01) < 0) return -1;

    /* Clear any pending interrupts */
    if (i2c_write_reg(fd, ADXL345_INT_SOURCE, 0x00) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/*  Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return -1;
    }

    /* Write header if file is empty */
    if (fseek(fp, 0, SEEK_END) == 0) {
        long sz = ftell(fp);
        if (sz == 0) {
            fprintf(fp, "Timestamp,X,Y,Z\n");
            fflush(fp);
        }
    }
    return 0;
}

static void log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    struct tm tm_info;
    char ts_str[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%d,%d,%d\n", ts_str, ts.tv_nsec / 1000000L,
            x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/*  Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADXL345_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ADXL345 init ---- */
    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    g_gpio_line = INT1_GPIO;
    if (gpioSetMode(g_gpio_line, PI_INPUT) < 0) {
        fprintf(stderr, "Cannot set GPIO%d as input: %s\n",
                g_gpio_line, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(g_gpio_line, PI_PUD_UP) < 0) {
        fprintf(stderr, "Cannot set pull-up on GPIO%d: %s\n",
                g_gpio_line, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable INT1 interrupt on rising edge */
    if (i2c_write_reg(g_i2c_fd, ADXL345_INT_MAP, 0x01) < 0) {
        fprintf(stderr, "Failed to enable INT1 interrupt\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    if (log_open(LOG_FILE) < 0) {
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        /*
         * Poll the INT1 status register (bit 0) to see if a free-fall
         * event has been captured.  The ADXL345 INT1 is active-high and
         * latches on a falling edge of the X-axis low-power interrupt.
         */
        uint8_t int_source = 0;
        int polls = 0;
        int ok = 0;

        while (polls < POLL_TIMEOUT_MS && g_running) {
            if (i2c_read_reg(g_i2c_fd, ADXL345_INT_SOURCE, &int_source) == 0) {
                if (int_source & 0x01) {
                    ok = 1;
                    break;
                }
            } else {
                polls++;
                if (polls >= POLL_TIMEOUT_MS) {
                    fprintf(stderr, "Timeout waiting for free-fall event\n");
                    break;
                }
                usleep(1000);
            }
        }

        if (ok) {
            int16_t x, y, z;
            if (i2c_read_reg(g_i2c_fd, ADXL345_DATAX0, &x) == 0 &&
                i2c_read_reg(g_i2c_fd, ADXL345_DATAX0 + 2, &y) == 0 &&
                i2c_read_reg(g_i2c_fd, ADXL345_DATAX0 + 4, &z) == 0) {

                log_sample(g_log_fp, x, y, z);
                printf("X=%d, Y=%d, Z=%d\n", x, y, z);
            } else {
                fprintf(stderr, "Failed to read acceleration data\n");
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    if (g_i2c_fd >= 0) {
        /* Put sensor in standby before closing */
        (void)i2c_write_reg(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(g_i2c_fd);
    }

    if (g_gpio_line >= 0) {
        gpioSetPullUpDown(g_gpio_line, PI_PUD_OFF);
        gpioSetMode(g_gpio_line, PI_INPUT);
        gpioSetAlertFunc(g_gpio_line, NULL);
    }

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

