/*
 * LSM6DSR IMU reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL)
 * Output data rate: 104 Hz
 * CSV log: motion_log.txt
 *
 * Build: gcc -O2 -Wall -o lsm6dsr_log lsm6dsr_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LSM6DSR_ADDR   0x58

/* LSM6DSR register addresses */
#define WHO_AM_I       0x0F
#define CTRL1_XL       0x10
#define CTRL2_G        0x11
#define OUTX_L_G       0x22
#define OUTX_L_XL      0x28

/* ±2g accelerometer range (FS_SEL = 0) */
#define ACCEL_RANGE_2G 0x00
/* ±250 dps gyroscope range (FS_SEL = 0) */
#define GYRO_RANGE_250 0x00

/* Fall detection thresholds (g) */
#define FALL_THRESHOLD_G 0.2f
#define IMPACT_THRESHOLD_G 2.5f
#define IMPACT_WINDOW_S  1.0f

/* Sensitivity for ±250 dps range: 1 LSB = 131.0 dps */
#define GYRO_SENSITIVITY_DPS 131.0f

/* Sensitivity for ±2g range: 1 LSB = 0.061 g */
#define ACCEL_SENSITIVITY_G 0.061f

#define LOG_FILE "motion_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor init                                                         */
/* ------------------------------------------------------------------ */
static int init_lsm6dsr(int fd)
{
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0)
        return -1;
    if (who_am_i != 0x63) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x63\n",
                who_am_i);
        return -1;
    }

    /* CTRL1_XL: enable accelerometer, normal mode, 104 Hz ODR */
    if (i2c_write_reg8(fd, CTRL1_XL, 0x80) < 0)
        return -1;

    /* CTRL2_G: enable gyroscope, normal mode, 104 Hz ODR */
    if (i2c_write_reg8(fd, CTRL2_G, 0x80) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw accelerometer and gyroscope data                         */
/* ------------------------------------------------------------------ */
static int read_lsm6dsr(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                        int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t xl_buf[6], g_buf[6];

    /* Read 6 bytes of accelerometer data (OUTX_L_XL through OUTZ_H_XL) */
    if (i2c_read_reg8(fd, OUTX_L_XL, (uint8_t *)&ax) < 0)
        return -1;
    if (i2c_read_reg8(fd, OUTX_L_XL + 1, (uint8_t *)&ay) < 0)
        return -1;
    if (i2c_read_reg8(fd, OUTX_L_XL + 2, (uint8_t *)&az) < 0)
        return -1;
    if (i2c_read_reg8(fd, OUTX_L_XL + 3, (uint8_t *)&gx) < 0)
        return -1;
    if (i2c_read_reg8(fd, OUTX_L_XL + 4, (uint8_t *)&gy) < 0)
        return -1;
    if (i2c_read_reg8(fd, OUTX_L_XL + 5, (uint8_t *)&gz) < 0)
        return -1;

    /* Read 6 bytes of gyroscope data (OUTX_L_G through OUTZ_H_G) */
    if (i2c_read_reg8(fd, OUTX_L_G, (uint8_t *)&gx) < 0)
        return -1;
    if (i2c_read_reg8(fd, OUTX_L_G + 1, (uint8_t *)&gy) < 0)
        return -1;
    if (i2c_read_reg8(fd, OUTX_L_G + 2, (uint8_t *)&gz) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Fall detection state machine                                          */
/* ------------------------------------------------------------------ */
typedef enum {
    STATE_IDLE,
    STATE_FREEFALL,
    STATE_IMPACT
} state_t;

static state_t state = STATE_IDLE;
static time_t freefall_start_time = 0;

static void fall_detection(int16_t ax, int16_t ay, int16_t az)
{
    float accel_magnitude = sqrtf(ax * ax + ay * ay + az * az);

    if (accel_magnitude < FALL_THRESHOLD_G) {
        if (state == STATE_IDLE) {
            state = STATE_FREEFALL;
            freefall_start_time = time(NULL);
            printf("Fall detected! Entering FREEFALL state.\n");
        }
    } else if (state == STATE_FREEFALL) {
        if (time(NULL) - freefall_start_time >= IMPACT_WINDOW_S) {
            state = STATE_IMPACT;
            printf("Impact detected! Entering IMPACT state.\n");
        }
    } else if (state == STATE_IMPACT) {
        /* No new impact within window; reset */
        state = STATE_FREEFALL;
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(int16_t ax, int16_t ay, int16_t az,
                      int16_t gx, int16_t gy, int16_t gz)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s,%d,%d,%d,%d,%d,%d\n",
                ts, ax, ay, az, gx, gy, gz);
    } else {
        fprintf(fp, "timestamp_error,%d,%d,%d,%d,%d,%d,%d\n",
                ax, ay, az, gx, gy, gz, time(NULL));
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus '%s': %s\n",
                I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM6DSR_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                LSM6DSR_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM6DSR initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialized. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_lsm6dsr(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "I2C read error; continuing.\n");
            usleep(10000);
            continue;
        }

        fall_detection(ax, ay, az);
        log_data(ax, ay, az, gx, gy, gz);

        usleep(10000); /* 10 ms -> 104 Hz */
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

