/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(int16_t ax, int16_t ay, int16_t az,
                      int16_t gx, int16_t gy, int16_t gz)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s,%d,%d,%d,%d,%d,%d\n",
                ts, ax, ay, az, gx, gy, gz);
    } else {
        fprintf(fp, "timestamp_error,%d,%d,%d,%d,%d,%d,%d\n",
                ax, ay, az, gx, gy, gz, time(NULL));
    }

