#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 register addresses */
#define ADIS16266_REG_WHO_AM_I   0x00
#define ADIS16266_REG_XGYRO_OUT  0x04
#define ADIS16266_REG_XGYRO_CMD  0x08
#define ADIS16266_REG_XGYRO_SCALE 0x0A

/* Expected WHO_AM_I value for ADIS16266 */
#define ADIS16266_WHO_AM_I_VAL   0x20

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0x03     /* Mode 3: CPOL=1, CPHA=1 */

/* Gyroscope scale factor (deg/sec/LSB) */
#define GYRO_SCALE  0.0305f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 10000

/* Global resources for signal handler cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single 16-bit register from the ADIS16266 via SPI            */
/* ------------------------------------------------------------------ */
static int adis16266_read_reg16(uint8_t reg, uint16_t *value)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single 16-bit register to the ADIS16266 via SPI             */
/* ------------------------------------------------------------------ */
static int adis16266_write_reg16(uint8_t reg, uint16_t value)
{
    char tx[2] = { (char)(reg & 0x7F), (char)(value & 0xFF) };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADIS16266 and verify WHO_AM_I                     */
/* ------------------------------------------------------------------ */
static int adis16266_init(void)
{
    uint16_t who_am_i = 0;

    if (adis16266_read_reg16(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who_am_i, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }

    /*
     * Command register 0x08: bit 7 = 1 (read), bits 6:4 = 000 (X axis),
     * bit 3 = 0 (no FIFO), bit 2 = 0 (no FIFO), bit 1 = 0 (no FIFO),
     * bit 0 = 0 (no FIFO).  ADIS16266_REG_XGYRO_CMD = 0x08.
     */
    if (adis16266_write_reg16(ADIS16266_REG_XGYRO_CMD, 0x08) != 0) {
        fprintf(stderr, "Failed to write X gyro command register\n");
        return -1;
    }

    /* Allow the first conversion to complete */
    gpioDelay(2000);  /* 2 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read angular rate from the X gyroscope and convert to degrees/sec  */
/* ------------------------------------------------------------------ */
static int read_gyro_rate(float *rate)
{
    uint16_t raw = 0;

    if (adis16266_read_reg16(ADIS16266_REG_XGYRO_OUT, &raw) != 0) {
        return -1;
    }

    *rate = (float)raw * GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the CSV log file                  */
/* ------------------------------------------------------------------ */
static int log_data(float rate)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.4f\n", timestamp, rate) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d, flags 0x%x)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADIS16266 */
    if (adis16266_init() != 0) {
        fprintf(stderr, "ADIS16266 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv for writing\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    if (fprintf(log_file, "timestamp,gyro_rate_deg_per_sec\n") < 0) {
        fprintf(stderr, "Failed to write CSV header\n");
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(log_file);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        float rate = 0.0f;

        if (read_gyro_rate(&rate) == 0) {
            if (log_data(rate) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Gyro read failed; continuing\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

