#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped flame-event line to the log file               */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_event(FILE *log_file, const char *event)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s – %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — closes the log file and terminates pigpio        */
/* ------------------------------------------------------------------ */
static void cleanup(FILE *log_file)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;
    int last_state = 1;  /* assume no flame at startup (pull-up HIGH) */
    FILE *log_file = NULL;

    /* ---- Install signal handlers for clean shutdown ---------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ----------------------------------------- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input with internal pull-up ---------- */
    ret = gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed (code %d)\n",
                FLAME_SENSOR_GPIO, ret);
        cleanup(log_file);
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed (code %d)\n",
                FLAME_SENSOR_GPIO, ret);
        cleanup(log_file);
        return EXIT_FAILURE;
    }

    /* ---- Open log file for appending -------------------------------- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup(log_file);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_GPIO);

    /* ---- Main polling loop ----------------------------------------- */
    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        if (sensor_value < 0) {
            fprintf(stderr, "gpioRead(%d) failed (code %d)\n",
                    FLAME_SENSOR_GPIO, sensor_value);
            /* Log the error so the program does not appear to crash */
            log_event(log_file, "ERROR: sensor read failed");
        } else {
            /* KY-026 DO is active-LOW: LOW = flame detected, HIGH = no flame */
            if (sensor_value == 0) {
                if (log_event(log_file, "Flame detected: YES") != 0) {
                    fprintf(stderr, "Failed to log flame event\n");
                }
                printf("FLAME DETECTED!\n");
            } else {
                if (log_event(log_file, "NO") != 0) {
                    fprintf(stderr, "Failed to log no-flame event\n");
                }
            }
        }

        /* Sleep 500 ms; gpioDelay is interruptible by signals */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Clean shutdown -------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup(log_file);
    return EXIT_SUCCESS;
}

