    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ----------------------------------------- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input with internal pull-up ---------- */
    ret = gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed (code %d)\n",
                FLAME_SENSOR_GPIO, ret);
        cleanup(log_file);
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed (code %d)\n",
                FLAME_SENSOR_GPIO, ret);
        cleanup(log_file);
        return EXIT_FAILURE;
    }

    /* ---- Open log file for appending -------------------------------- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup(log_file);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_GPIO);

    /* ---- Main polling loop ----------------------------------------- */
    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        if (sensor_value < 0) {
            fprintf(stderr, "gpioRead(%d) failed (code %d)\n",
                    FLAME_SENSOR_GPIO, sensor_value);
            /* Log the error so the program does not appear to crash */
            log_event(log_file, "ERROR: sensor read failed");
        } else {
            /* KY-026 DO is active-LOW: LOW = flame detected, HIGH = no flame */
            if (sensor_value == 0) {
                if (log_event(log_file, "Flame detected: YES") != 0) {
                    fprintf(stderr, "Failed to log flame event\n");
                }
                printf("FLAME DETECTED!\n");
            } else {
                if (log_event(log_file, "NO") != 0) {
                    fprintf(stderr, "Failed to log no-flame event\n");
                }
            }
        }

        /* Sleep 500 ms; gpioDelay is interruptible by signals */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Clean shutdown -------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup(log_file);
    return EXIT_SUCCESS;
}

