#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x49
#define D7S_REG_X      0x00
#define D7S_REG_Y      0x02
#define D7S_REG_Z      0x04
#define D7S_REG_STATUS 0x06
#define D7S_STATUS_ERR 0x01
#define SAMPLE_PERIOD_US 100000
#define LOG_FILE       "vibration_log.csv"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int read_d7s(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t status;
    if (i2c_read_reg8(fd, D7S_REG_STATUS, &status) != 0)
        return -1;
    if (status & D7S_STATUS_ERR) {
        fprintf(stderr, "D7S status error (0x%02X)\n", status);
        return -1;
    }
    if (i2c_read_reg8(fd, D7S_REG_X,  (uint8_t *)x) != 0)
        return -1;
    if (i2c_read_reg8(fd, D7S_REG_Y,  (uint8_t *)y) != 0)
        return -1;
    if (i2c_read_reg8(fd, D7S_REG_Z,  (uint8_t *)z) != 0)
        return -1;
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", D7S_ADDR, strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write header if file is empty */
    if (fseek(fp, 0, SEEK_END) == 0) {
        long sz = ftell(fp);
        if (sz == 0) {
            if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0 || fflush(fp) != 0) {
                fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
                goto cleanup;
            }
        }
    }

    printf("D7S vibration logger started. Logging to %s every 100 ms. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        int16_t x, y, z;
        if (read_d7s(fd, &x, &y, &z) == 0) {
            if (log_data(fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

