#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Read a Hall sensor with internal pull-up enabled.
 * Returns 0 or 1 on success, -1 on read error.
 */
static int read_hall_sensor(int gpio)
{
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, pigpio_error(value));
        return -1;
    }
    return value;
}

/*
 * Append a timestamped sensor reading to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_sensor_data(int sensor_number, int value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld, Sensor %d: %d\n", timestamp, ts.tv_nsec / 1000000, sensor_number, value);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor GPIO pins as inputs with internal pull-up resistors */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_hall_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_hall_sensor(SENSOR_2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values, continuing...\n");
        } else {
            if (log_sensor_data(1, sensor1_value) != 0) {
                fprintf(stderr, "Error logging sensor 1 data\n");
            }
            if (log_sensor_data(2, sensor2_value) != 0) {
                fprintf(stderr, "Error logging sensor 2 data\n");
            }

            if (sensor1_value == 1 && sensor2_value == 1) {
                printf("Conveyor HALTED! Both sensors read logic 1.\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nConveyor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

