/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/* Write a byte to an MMA8452Q register */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a byte from an MMA8452Q register */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian value from two consecutive registers */
static int i2c_read_reg16(int fd, uint8_t reg_l, int16_t *value) {
    uint8_t low, high;
    if (i2c_read_reg(fd, reg_l, &low) < 0) return -1;
    if (i2c_read_reg(fd, reg_l + 1, &high) < 0) return -1;
    *value = (int16_t)((high << 8) | low);
    return 0;
}

