static int initialize_mma8452q(int fd) {
    uint8_t who_am_i;
    if (i2c_read_reg(fd, MMA8452Q_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != MMA8452Q_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                MMA8452Q_WHO_AM_I_VAL, who_am_i);
        return -1;
