    printf("MMA8452Q detected (WHO_AM_I = 0x%02X).\n", who_am_i);

    /* Standby mode to allow configuration */
    if (i2c_write_reg(fd, MMA8452Q_CTRL_REG1, 0x00) < 0) return -1;
    usleep(1000);

    /* Data rate: 100 Hz (0x0A) */
    if (i2c_write_reg(fd, MMA8452Q_CTRL_REG2, 0x0A) < 0) return -1;
    usleep(1000);

