    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    /* Set I2C slave address */
    if (ioctl(i2c_fd, I2C_SLAVE, 0x19) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x19: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    /* Initialize sensor */
    if (initialize_mma8452q(i2c_fd) < 0) {
        fprintf(stderr, "MMA8452Q initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

