    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring tilt... Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            tilt = calculate_tilt(x, y);
            if (fabsf(tilt) > TILT_THRESHOLD) {
