#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LIS3MDL I2C address (SA0 tied to GND) */
#define LIS3MDL_ADDR 0x19

/* LIS3MDL register addresses */
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG4 0x23
#define LIS3MDL_CTRL_REG5 0x24
#define LIS3MDL_CTRL_REG6 0x25
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

/* ±4 gauss full-scale range: 0.146 mG per LSB */
#define MAG_SENSITIVITY 0.146f

/* Metal-detector alert threshold (mG) */
#define METAL_DETECTION_THRESHOLD 800.0f

/* Calibration constants (fixed offset, scale) */
static const float x_offset = 0.0f;
static const float y_offset = 0.0f;
static const float z_offset = 0.0f;
static const float x_scale = 1.0f;
static const float y_scale = 1.0f;
static const float z_scale = 1.0f;

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                LIS3MDL_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }

    /*
     * CTRL_REG1: ODR = 10 Hz (0x57), all axes enabled, normal mode
     * CTRL_REG4: Full-scale ±4 gauss (0x00)
     * CTRL_REG5: High-resolution mode disabled, normal mode
     * CTRL_REG6: Low-noise disabled, normal mode
     */
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG4: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG5, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG5: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG6, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG6: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read 6 bytes from LIS3MDL: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

static int calibrate_magnetometer(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    float x = ((float)raw_x - x_offset) * x_scale;
    float y = ((float)raw_y - y_offset) * y_scale;
    float z = ((float)raw_z - z_offset) * z_scale;

    return (int32_t)(x + y + z);
}

static int log_data(int32_t x, int32_t y, int32_t z) {
    if (log_file == NULL) {
        log_file = fopen("magnetic_log.txt", "w");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open magnetic_log.txt: %s\n", strerror(errno));
            return -1;
        }
        fprintf(log_file, "X,Y,Z\n");
    }

    fprintf(log_file, "%d,%d,%d\n", x, y, z);
    fflush(log_file);
    return 0;
}

static void check_metal_detection(int32_t x, int32_t y, int32_t z) {
    float magnitude = sqrtf((float)x * x + (float)y * y + (float)z * z);
    if (magnitude > METAL_DETECTION_THRESHOLD) {
        fprintf(stderr, "Metal detected! Magnitude: %.2f mG\n", magnitude);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    int retries = 3;
    int initialized = 0;

    while (retries > 0 && !initialized) {
        if (initialize_i2c() == 0) {
            initialized = 1;
            retries = 0;
        } else {
            fprintf(stderr, "I2C initialization failed. Retrying in 1 second...\n");
            sleep(1);
        }
    }

    if (!initialized) {
        fprintf(stderr, "I2C initialization failed after multiple retries. Exiting.\n");
        return 1;
    }

    printf("LIS3MDL initialized. Logging to magnetic_log.txt at 10 Hz. Press Ctrl+C to stop.\n");

    while (program_running) {
        int16_t raw_x, raw_y, raw_z;

        if (read_magnetometer_data(&raw_x, &raw_y, &raw_z) == 0) {
            int32_t calibrated_x = calibrate_magnetometer(raw_x, raw_y, raw_z);
            int32_t calibrated_y = calibrate_magnetometer(raw_y, raw_z, raw_x);
            int32_t calibrated_z = calibrate_magnetometer(raw_z, raw_x, raw_y);

            if (log_data(calibrated_x, calibrated_y, calibrated_z) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }

            check_metal_detection(calibrated_x, calibrated_y, calibrated_z);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying in 1 second...\n");
            sleep(1);
        }

        gpioDelay(100000); /* 100 ms -> 10 Hz */
    }

    printf("\nShutting down cleanly...\n");

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    gpioTerminate();

    return 0;
}

