/*
 * ADXL354B Vibration Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL354B VDD  -> 3.3 V (Pin 1)
 *   ADXL354B GND  -> GND  (Pin 9)
 *   ADXL354B SCL  -> GPIO3 / SPI0 SCLK (Pin 5)
 *   ADXL354B SDA  -> GPIO2 / SPI0 MISO (Pin 3)
 *   ADXL354B CS   -> GPIO8 / SPI0 CE0 (Pin 24)
 *
 * Build:
 *   gcc -O2 -Wall -o vibration_logger vibration_logger.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define LOG_FILE       "vibration_log.txt"
#define SAMPLE_PERIOD_US 100000   /* 100 ms */

#define RESET_VALUE    0x52        /* 0x52 = 0101 0010 — reset bit */
#define RESET_DELAY_US 1000        /* 1 ms */
#define POWER_STABLE_US 10000      /* 10 ms */
#define POWER_RUN_BIT  0x08        /* RUN bit in power-control register */
#define STABLE_BIT     0x04        /* STABLE bit in status register */

#define PARTID_EXPECTED 0x354

#define READ_LEN       3          /* 20-bit data + 1 null bit */

/* ------------------------------- Globals --------------------------------- */
static int  spi_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Function prototypes -------------------------- */
static void signal_handler(int sig);
static int  spi_read_register(uint8_t reg, uint8_t *value);
static int  spi_write_register(uint8_t reg, uint8_t value);
static int  adxl354b_reset(void);
static int  adxl354b_verify_partid(void);
static int  adxl354b_read_xyz(int16_t *x, int16_t *y, int16_t *z);
static void log_data(int16_t x, int16_t y, int16_t z);
static void cleanup(void);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Reset sensor and verify part ID --- */
    if (adxl354b_reset() != 0) {
        fprintf(stderr, "Error: ADXL354B reset failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (adxl354b_verify_partid() != 0) {
        fprintf(stderr, "Error: ADXL354B part ID verification failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL354B detected (PARTID=0x%02X). Logging to %s\n",
           PARTID_EXPECTED, LOG_FILE);

    /* --- Main sampling loop --- */
    while (!terminate) {
        int16_t x, y, z;

        if (adxl354b_read_xyz(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Warning: SPI read error — skipping sample.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------- SPI register helpers -------------------------- */
static int spi_read_register(uint8_t reg, uint8_t *value)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "Error: SPI read of register 0x%02X failed.\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value)
{
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "Error: SPI write to register 0x%02X failed.\n", reg);
        return -1;
    }
    return 0;
}

/* --------------------------- ADXL354B specifics ----------------------------- */
static int adxl354b_reset(void)
{
    uint8_t partid;

    if (spi_write_register(0x00, RESET_VALUE) != 0)
        return -1;

    gpioDelay(RESET_DELAY_US);

    if (spi_read_register(0x00, &partid) != 0)
        return -1;

    if (partid != PARTID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected PARTID (0x%02X, expected 0x%02X).\n",
                partid, PARTID_EXPECTED);
        return -1;
    }

    /* Clear RUN bit to enter standby before powering up */
    if (spi_write_register(0x02, 0x00) != 0)
        return -1;

    /* Wait for STABLE bit (10 ms) */
    for (int i = 0; i < 10; i++) {
        uint8_t status;
        if (spi_read_register(0x03, &status) != 0)
            return -1;
        if (status & STABLE_BIT)
            break;
        gpioDelay(POWER_STABLE_BIT_US);
    }

    if (status & STABLE_BIT) {
        fprintf(stderr, "Error: ADXL354B STABLE bit never set.\n");
        return -1;
    }

    /* Set RUN bit to start measurement */
    if (spi_write_register(0x02, POWER_RUN_BIT) != 0)
        return -1;

    gpioDelay(POWER_STABLE_BIT_US);
    return 0;
}

static int adxl354b_verify_partid(void)
{
    uint8_t partid;

    if (spi_read_register(0x00, &partid) != 0)
        return -1;

    if (partid != PARTID_EXPECTED) {
        fprintf(stderr, "Error: ADXL354B PARTID mismatch: got 0x%02X, expected 0x%02X.\n",
                partid, PARTID_EXPECTED);
        return -1;
    }
    return 0;
}

static int adxl354b_read_xyz(int16_t *x, int16_t *y, int16_t *z)
{
    char tx[READ_LEN] = { 0 };
    char rx[READ_LEN] = { 0 };

    /*
     * Read 3 bytes from the ADXL354B.
     * Byte 0: bit7=1 (read), bit6=1 (multi-byte), bits5-0 = 00000.
     * Byte 1: bit7=1 (read), bit6=0 (single-byte), bits5-0 = 00000.
     * Byte 2: bit7=1 (read), bit6=0 (single-byte), bits5-0 = 00000.
     */
    tx[0] = 0x80 | 0x01;
    tx[1] = 0x00;
    tx[2] = 0x00;

    if (spiXfer(spi_handle, tx, rx, READ_LEN) != READ_LEN) {
        fprintf(stderr, "Error: SPI read of XYZ data failed.\n");
        return -1;
    }

    /*
     * 20-bit signed data: bits 19..0 are the data, bit19 = 0 (sign).
     * rx[0] = upper 8 bits, rx[1] = lower 8 bits.
     */
    *x = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    *y = (int16_t)(((uint8_t)rx[2] << 8) | (uint8_t)rx[3]);
    *z = (int16_t)(((uint8_t)rx[4] << 8) | (uint8_t)rx[5]);

    return 0;
}

/* --------------------------- Logging -------------------------------------- */
static void log_data(int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

