#define SPI_BAUD 1000000 /* 1 MHz */
#define SPI_FLAGS 3      /* Mode 3: active-high CS, MSB first */

/* Sampling parameters */
#define SAMPLE_PERIOD_US 10000 /* 10 ms = 100 Hz */

/* Global resources for signal handler cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    exit(0);
}

/* Initialize the ADIS16362 IMU */
static int init_adis16362(void) {
    /*
     * ADIS16362 requires a 16-bit read protocol:
     *   Send address byte (MSB set) + dummy byte, then read data on the
     *   next 16-bit transfer.
     */
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    /* Configure gyroscope scaling factor */
    tx_buf[0] = (REG_XGYRO_CFG << 1) | 0x80; /* MSB set */
    tx_buf[1] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to write XGYRO_CFG\n");
        return -1;
    }

    /* Configure accelerometer scaling factor */
    tx_buf[0] = (REG_XACCEL_CFG << 1) | 0x80;
    tx_buf[1] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to write XACCEL_CFG\n");
        return -1;
    }

    /* Configure gyroscope output data rate */
    tx_buf[0] = (REG_XGYRO_LSB << 1) | 0x80;
    tx_buf[1] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to write XGYRO_LSB\n");
        return -1;
    }

    /* Configure accelerometer output data rate */
    tx_buf[0] = (REG_XACCEL_LSB << 1) | 0x80;
    tx_buf[1] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to write XACCEL_LSB\n");
        return -1;
    }

    return 0;
}

/* Read a 16-bit register from the ADIS16362 */
static int read_register(uint8_t reg, int16_t *value) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    tx_buf[0] = (reg << 1) | 0x80; /* MSB set */
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    *value = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    return 0;
}

/* Read gyroscope data */
static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    if (read_register(REG_XGYRO_OUT, x) != 0) return -1;
    if (read_register(REG_YGYRO_OUT, y) != 0) return -1;
    if (read_register(REG_ZGYRO_OUT, z) != 0) return -1;
    return 0;
}

/* Read accelerometer data */
static int read_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    if (read_register(REG_XACCEL_OUT, x) != 0) return -1;
    if (read_register(REG_YACCEL_OUT, y) != 0) return -1;
    if (read_register(REG_ZACCEL_OUT, z) != 0) return -1;
    return 0;
}

/* Log data to CSV file */
static int log_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z,
                    int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed\n");
        return -1;
    }

    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    if (fprintf(log_file, "%lld,%d,%d,%d,%d,%d,%d\n",
                timestamp_ns, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }

    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open SPI device */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize ADIS16362 */
    if (init_adis16362() != 0) {
        fprintf(stderr, "Error: ADIS16362 initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Open log file */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open imu_log.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Write CSV header */
    if (fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n") < 0) {
        fprintf(stderr, "Error: Failed to write CSV header\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    /* Main sampling loop */
    while (1) {
        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accel_x, accel_y, accel_z;

        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) != 0) {
            fprintf(stderr, "Warning: Gyroscope read failed, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (read_accel_data(&accel_x, &accel_y, &accel_z) != 0) {
            fprintf(stderr, "Warning: Accelerometer read failed, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) != 0) {
            fprintf(stderr, "Warning: Logging failed, skipping sample\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Unreachable, but for completeness: */
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

