#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define SENSOR_PIN 17
#define CHIP_NAME "gpiochip4"
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    int line = gpioOpen(CHIP_NAME, SENSOR_PIN, PI_PIN_OUTPUT);
    if (line < 0) {
        fprintf(stderr, "Error: gpioOpen failed for %s pin %d (rc=%d)\n",
                CHIP_NAME, SENSOR_PIN, line);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Self-parking sequence started");

    while (running) {
        int value = gpioRead(line);
        if (value < 0) {
            fprintf(stderr, "Error: gpioRead failed on line %d (rc=%d)\n",
                    line, value);
            break;
        }

        if (value == 0) {
            log_message("Self-parking sequence started");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(line, 0);
    gpioSetMode(line, PI_INPUT);
    gpioTerminate();

    log_message("Self-parking sequence completed");
    return EXIT_SUCCESS;
}

