/*
 * KY-032 IR Obstacle Avoidance Sensor Monitor
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: 2 x Keyes KY-032 on GPIO17 (physical pin 11) and GPIO27 (physical pin 13)
 * API:     pigpio bulk-read on a single line (line 0 = GPIO17, line 1 = GPIO27)
 *
 * Build:  gcc -Wall -Wextra -O2 -o ky032_monitor ky032_monitor.c -lpigpio -lrt
 * Run:    sudo ./ky032_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define POLL_INTERVAL_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Bulk-read: read 2 lines together via a single pigpio call.         */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int bulk_read_sensors(int line0, int line1, uint16_t *out)
{
    int rc = gpioBulkRead(line0, line1);
    if (rc < 0) {
        fprintf(stderr, "gpioBulkRead failed (line0=0x%02X, line1=0x%02X): %s\n",
                line0, line1, pigpio_error(rc));
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Interpret a 16-bit bulk read as active-low obstacle detection.       */
/* Returns 0 if obstacle detected (0), 1 if clear (1), -1 on error.     */
/* ------------------------------------------------------------------ */
static int interpret_sensor_data(uint16_t raw)
{
    /* KY-032 is active-low: 0 = obstacle detected, 1 = clear */
    return (raw & 0x0001) ? 0 : 1;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO lines as inputs --- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure lines start in a known state --- */
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_OFF);

    printf("KY-032 Obstacle Monitor started.\n");
    printf("  Sensor 1: GPIO%d\n  Sensor 2: GPIO%d\n", SENSOR_1_PIN, SENSOR_2_PIN);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_US / 1000);
    printf("  Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (g_running) {
        uint16_t raw;
        char ts[32];

        if (bulk_read_sensors(SENSOR_1_PIN, SENSOR_2_PIN, &raw) == 0) {
            int obstacle1 = interpret_sensor_data(raw);
            int obstacle2 = interpret_sensor_data(raw);

            get_timestamp(ts, sizeof(ts));
