/*
 * ADIS16266 Gyroscope SPI Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 VDD  -> 3.3V (Pin 1)
 *   ADIS16266 GND  -> GND  (Pin 9)
 *   ADIS16266 SCLK -> GPIO11 (Pin 23, SPI0 SCLK)
 *   ADIS16266 CS   -> GPIO8  (Pin 24, SPI0 CE0)
 *   ADIS16266 SDI  -> GPIO9  (Pin 21, SPI0 MISO)
 *   ADIS16266 SDO  -> GPIO10 (Pin 19, SPI0 MOSI)
 *
 * Build: gcc -O2 -Wall -o gyro_reader gyro_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8U
#define SPI_MODE        3U

#define READ_INTERVAL_US 100000U
#define SPI_RETRIES      3

/* ADIS16266 register addresses (16-bit, big-endian on the bus) */
#define REG_XGYRO_OUT   0x00
#define REG_YGYRO_OUT   0x02
#define REG_ZGYRO_OUT   0x04
#define REG_XGYRO_SCALE 0x08
#define REG_YGYRO_SCALE 0x0A
#define REG_ZGYRO_SCALE 0x0C

#define SCALE_FACTOR_DEG_PER_SEC 0.02f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int spi_init(int *spi_fd)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *spi_fd = fd;
    return 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) >= 0)
            return 0;
        usleep(1000U);
    }
    return -1;
}

static int read_register(int fd, uint16_t reg, float *value)
{
    uint8_t tx[3] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF),
        0x00
    };
    uint8_t rx[3] = {0};

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0)
        return -1;

    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];
    *value = (float)raw * SCALE_FACTOR_DEG_PER_SEC;
    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z)
{
    if (read_register(fd, REG_XGYRO_OUT, x) < 0)
        return -1;
    if (read_register(fd, REG_YGYRO_OUT, y) < 0)
        return -1;
    if (read_register(fd, REG_ZGYRO_OUT, z) < 0)
        return -1;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int spi_fd = -1;
    if (spi_init(&spi_fd) < 0)
        return EXIT_FAILURE;

    float x, y, z;
    while (g_running) {
        if (read_gyro_data(spi_fd, &x, &y, &z) == 0) {
            printf("X: %+.3f deg/sec, Y: %+.3f deg/sec, Z: %+.3f deg/sec\n", x, y, z);
            fflush(stdout);
        } else {
            fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        }
        usleep(READ_INTERVAL_US);
    }

    if (spi_fd >= 0)
        close(spi_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

