#define LSM6DSR_WHO_AM_I 0x00

/* Global I2C handle for signal handler cleanup */
static int g_i2c_handle = -1;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for clean shutdown on Ctrl+C                         */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register; returns 0 on success, -1 */
/* on failure.                                                      */
/* ------------------------------------------------------------------ */
static int write_reg8(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d): %s\n",
                value, reg, rc, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a burst of bytes starting at the given register; returns 0    */
/* on success, -1 on failure.                                         */
/* ------------------------------------------------------------------ */
static int read_burst(int handle, uint8_t reg, char *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading %u bytes from register 0x%02X (rc=%d): %s\n",
                len, reg, rc, strerror(errno));
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "Short read: expected %u bytes, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the LSM6DSR: verify WHO_AM_I, enable gyro and accel,      */
/* then verify the device is responding.                               */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int init_lsm6dsr(int handle)
{
    char buf[1];

    /* Verify device identity */
    if (read_burst(handle, WHO_AM_I, buf, 1) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        return -1;
    }
    if ((uint8_t)buf[0] != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                (uint8_t)buf[0], LSM6DSR_WHO_AM_I);
        return -1;
    }

    /* CTRL1_XL: enable accelerometer, 400 Hz ODR, normal mode */
    if (write_reg8(handle, CTRL1_XL, 0x40) != 0) {
        return -1;
    }

    /* CTRL2_G: enable gyroscope, 400 Hz ODR, normal mode */
    if (write_reg8(handle, CTRL2_G, 0x40) != 0) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer and gyroscope data; returns 0 on success, -1    */
/* on failure.                                                      */
/* ------------------------------------------------------------------ */
static int read_lsm6dsr(int handle,
                         int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buf[6];

    /* Burst read 6 bytes starting at OUTX_L_G (0x22) */
    if (read_burst(handle, OUTX_L_G, buf, 6) != 0) {
        return -1;
    }

    *gx = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    *gy = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    *gz = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);

    /* Burst read 6 bytes starting at OUTX_L_XL (0x28) */
    if (read_burst(handle, OUTX_L_XL, buf, 6) != 0) {
        return -1;
    }

    *ax = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    *ay = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    *az = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper: close I2C handle and terminate pigpio.             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;

    /* Register signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at LSM6DSR_ADDR */
    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X (rc=%d): %s\n",
                LSM6DSR_ADDR, g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize LSM6DSR */
    if (init_lsm6dsr(g_i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialized. Reading data every 100 ms (Ctrl+C to exit)\n");

    /* Main sampling loop */
    while (g_running) {
        if (read_lsm6dsr(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("%d,%d,%d,%d,%d,%d\n", ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read LSM6DSR data\n");
        }
        gpioDelay(100000); /* 100 ms in microseconds */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

