/*
 * ADXL345 Tilt Monitor for Raspberry Pi 5
 *
 * Reads acceleration data from an ADXL345 over I2C, evaluates the tilt
 * angle, and logs timestamped events to /var/log/tilt_events.log when the
 * tilt exceeds a threshold.
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   ADXL345 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   ADXL345 VDD -> 3.3 V
 *   ADXL345 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tilt_monitor tilt_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ADXL345 I2C address (ALT ADDRESS pin tied to GND) */
#define ADXL345_I2C_ADDR 0x2C

/* ADXL345 register addresses */
#define ADXL345_REG_DEVID_AD 0x00
#define ADXL345_REG_THRESH_ACT 0x28
#define ADXL345_REG_THRESH_ROT 0x29
#define ADXL345_REG_THRESH_TILT 0x2A
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C

/* Threshold for tilt angle (degrees) */
#define TILT_THRESHOLD 30.0f

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* I2C device path for Raspberry Pi 5 */
#define I2C_DEV "/dev/i2c-1"

/* Global flag for graceful shutdown */
static volatile sig_atomic_t g_running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an ADXL345 register */
static int adxl345_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an ADXL345 register */
static int adxl345_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian acceleration value */
static int adxl345_read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (write(fd, ADXL345_REG_DATAX0, 1) != 1) {
        fprintf(stderr, "Error selecting accelerometer data register: %s\n",
                strerror(errno));
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data: %s\n",
                strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* Initialize the ADXL345 sensor */
static int adxl345_init(int fd)
{
    uint8_t devid;

    /* Verify sensor identity */
    if (adxl345_read_reg(fd, ADXL345_REG_DEVID_AD, &devid) < 0)
        return -1;
    if (devid != 0x6B) {
        fprintf(stderr, "ADXL345 not detected (DEVID_AD=0x%02X, expected 0x6B)\n",
                devid);
        return -1;
    }

    /* Set data format: full resolution, +/-200g range, right-justified */
    if (adxl345_write_reg(fd, ADXL345_REG_DATA_FORMAT, 0x0B) < 0)
        return -1;

    /* Set sample rate to 100 Hz (0x0A) */
    if (adxl345_write_reg(fd, ADXL345_REG_BW_RATE, 0x0A) < 0)
        return -1;

    /* Set tilt threshold (degrees) */
    if (adxl345_write_reg(fd, ADXL345_REG_THRESH_TILT, 0x0F) < 0)
        return -1;

    /* Set roll and pitch thresholds (degrees) */
    if (adxl345_write_reg(fd, ADXL345_REG_THRESH_ROT, 0x0F) < 0)
        return -1;

    /* Set actuator threshold (counts) */
    if (adxl345_write_reg(fd, ADXL345_REG_THRESH_ACT, 0x0F) < 0)
        return -1;

    /* Enable measurement mode */
    if (adxl345_write_reg(fd, ADXL345_REG_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

/* Calculate the tilt angle in degrees from the X and Y accelerometer
 * readings.  Returns -1.0f on invalid input. */
static float calculate_tilt_angle(int16_t x, int16_t y)
{
    float angle_x = atan2f((float)x, (float)y) * 180.0f / (float)M_PI;
    float angle_y = atan2f((float)y, (float)x) * 180.0f / (float)M_PI;

    if (angle_x < 0.0f)
        angle_x += 360.0f;
    if (angle_y < 0.0f)
        angle_y += 360.0f;

    return fabsf(angle_x - angle_y);
}

/* Log a tilt event to the system log file */
static int log_tilt_event(const char *timestamp)
{
    FILE *fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%s\n", timestamp);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int16_t x, y, z;
    float tilt_angle;
    char timestamp[32];
    struct timespec ts;
    int ret;

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C device */
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set I2C slave address */
    if (ioctl(fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                ADXL345_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 sensor */
    if (adxl345_init(fd) < 0) {
        fprintf(stderr, "Error initializing ADXL345 sensor.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADXL345 tilt monitor started. Sampling every 100 ms.\n");
    printf("Threshold: %.1f degrees. Press Ctrl+C to exit.\n", TILT_THRESHOLD);

    /* Main sampling loop */
    while (g_running) {
        /* Read accelerometer data */
        if (adxl345_read_accel(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
            nanosleep(&(struct timespec){0, SAMPLE_INTERVAL_US}, NULL);
            continue;
        }

        /* Calculate tilt angle */
        tilt_angle = calculate_tilt_angle(x, y);

        /* Get current timestamp */
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            nanosleep(&(struct timespec){0, SAMPLE_INTERVAL_US}, NULL);
            continue;
        }

        /* Format timestamp */
        snprintf(timestamp, sizeof(timestamp), "%ld.%09ld",
                 ts.tv_sec, ts.tv_nsec);

        /* Log if tilt exceeds threshold */
        if (fabsf(tilt_angle) > TILT_THRESHOLD) {
            if (log_tilt_event(timestamp) < 0) {
                fprintf(stderr, "Error logging tilt event.\n");
            } else {
                printf("Tilt event logged: %s\n", timestamp);
            }
        }

        /* Wait for next sample */
        nanosleep(&(struct timespec){0, SAMPLE_INTERVAL_US}, NULL);
    }

    /* Clean resource release on exit */
    printf("\nShutting down...\n");
    if (fd >= 0) {
        /* Put sensor into standby mode */
        (void)adxl345_write_reg(fd, ADXL345_REG_POWER_CTL, 0x00);
        close(fd);
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

