#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define SAMPLE_INTERVAL_US 1000
#define WINDOW_SECONDS 5
#define MIN_READINGS_THRESHOLD 0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    return 0;
}

static int read_sound_sensor(void) {
    int value = gpioRead(SOUND_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", SOUND_SENSOR_PIN);
        return -1;
    }
    return value;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] ", buffer);
}

static void check_threshold(int high_count, int threshold) {
    if (high_count > threshold) {
