/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Two 12 V electromagnetic door locks driven via TIP120 relay modules.
 * Door A on GPIO17 (BCM), Door B on GPIO27 (BCM).
 *
 * Locks are energized (closed) when the GPIO is LOW; de-energized (unlocked)
 * when the GPIO is HIGH.  Each entry grants a 5 s unlock window.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define UNLOCK_SEC  5
#define LOG_FILE    "access_log.txt"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, code) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Code generation                                                    */
/* ------------------------------------------------------------------ */
static int generate_code(int *code)
{
    if (code == NULL)
        return -1;

    srand((unsigned int)time(NULL));
    *code = (rand() % 900000) + 100000;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static struct gpiod_chip *chip_open(void)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip)
        return chip;

    chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    if (chip)
        return chip;

    chip = gpiod_chip_open_by_number(4);
    if (chip)
        return chip;

    fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
    return NULL;
}

static int set_output(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "gpiod_line_set_value(%s, %d) failed: %s\n",
                gpiod_line_label(line), value, strerror(errno));
        return -1;
    }
    return 0;
}

static int unlock_door(struct gpiod_line *line)
{
    if (set_output(line, 1) < 0)
        return -1;
    return 0;
}

static int lock_door(struct gpiod_line *line)
{
    if (set_output(line, 0) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int door_a_pin = DOOR_A_PIN;
    int door_b_pin = DOOR_B_PIN;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int code = 0;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() < 0)
        goto cleanup;

    /* Open the GPIO chip that exposes BCM 17 and 27 on the Pi 4. */
    chip = chip_open();
    if (!chip)
        goto cleanup;

    line_a = gpiod_chip_get_line(chip, door_a_pin);
    if (!line_a) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                door_a_pin, strerror(errno));
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, door_b_pin);
    if (!line_b) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                door_b_pin, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (locked). */
    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        fprintf(stderr, "request_output(line %d) failed: %s\n",
                door_a_pin, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        fprintf(stderr, "request_output(line %d) failed: %s\n",
                door_b_pin, strerror(errno));
        goto cleanup;
    }

    printf("Door access system started.\n");
    printf("  Door A : GPIO%d\n", door_a_pin);
    printf("  Door B : GPIO%d\n", door_b_pin);
    printf("  Unlock: %d s\n", UNLOCK_SEC);
    printf("  Log    : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        printf("Enter code for Door A (6 digits): ");
        fflush(stdout);

        char buf[32];
        if (fgets(buf, sizeof(buf), stdin) == NULL) {
            if (feof(stdin))
                printf("\nEOF on stdin; exiting.\n");
            else
                fprintf(stderr, "fgets() failed: %s\n", strerror(errno));
            break;
        }

        /* Strip trailing newline / whitespace. */
        buf[strcspn(buf, "\r\n")] = '\0';

        if (sscanf(buf, "%d", &code) != 1) {
            printf("Invalid input; please enter a 6-digit code.\n");
            fflush(stdout);
            continue;
        }

        printf("Enter code for Door B (6 digits): ");
        fflush(stdout);

        char buf2[32];
        if (fgets(buf2, sizeof(buf2), stdin) == NULL) {
            if (feof(stdin))
                printf("\nEOF on stdin; exiting.\n");
            else
                fprintf(stderr, "fgets() failed: %s\n", strerror(errno));
            break;
        }

        if (sscanf(buf2, "%d", &code) != 1) {
            printf("Invalid input; please enter a 6-digit code.\n");
            fflush(stdout);
            continue;
        }

        if (code != 0) {
            printf("Code check failed.\n");
            fflush(stdout);
            continue;
        }

        printf("Access granted.\n");
        fflush(stdout);

        if (unlock_door(line_a) < 0) {
            fprintf(stderr, "Failed to unlock Door A.\n");
            goto cleanup;
        }
        if (unlock_door(line_b) < 0) {
            fprintf(stderr, "Failed to unlock Door B.\n");
            goto cleanup;
        }

        if (log_access(code) < 0) {
            fprintf(stderr, "Failed to log access event.\n");
            goto cleanup;
        }

        sleep(UNLOCK_SEC);

        if (lock_door(line_a) < 0) {
            fprintf(stderr, "Failed to lock Door A.\n");
            goto cleanup;
        }
        if (lock_door(line_b) < 0) {
            fprintf(stderr, "Failed to lock Door B.\n");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure doors are locked on exit. */
    if (line_a)
        gpiod_line_set_value(line_a, 0);
    if (line_b)
        gpiod_line_set_value(line_b, 0);

    if (chip)
        gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return ret;
}

