        buf[strcspn(buf, "\r\n")] = '\0';

        if (sscanf(buf, "%d", &code) != 1) {
            printf("Invalid input; please enter a 6-digit code.\n");
            fflush(stdout);
            continue;
        }

        printf("Enter code for Door B (6 digits): ");
        fflush(stdout);

        char buf2[32];
        if (fgets(buf2, sizeof(buf2), stdin) == NULL) {
            if (feof(stdin))
                printf("\nEOF on stdin; exiting.\n");
            else
                fprintf(stderr, "fgets() failed: %s\n", strerror(errno));
            break;
        }

        if (sscanf(buf2, "%d", &code) != 1) {
            printf("Invalid input; please enter a 6-digit code.\n");
            fflush(stdout);
            continue;
        }

        if (code != 0) {
            printf("Code check failed.\n");
            fflush(stdout);
            continue;
        }

        printf("Access granted.\n");
        fflush(stdout);

        if (unlock_door(line_a) < 0) {
            fprintf(stderr, "Failed to unlock Door A.\n");
            goto cleanup;
        }
        if (unlock_door(line_b) < 0) {
            fprintf(stderr, "Failed to unlock Door B.\n");
            goto cleanup;
        }

        if (log_access(code) < 0) {
            fprintf(stderr, "Failed to log access event.\n");
            goto cleanup;
        }

        sleep(UNLOCK_SEC);

        if (lock_door(line_a) < 0) {
            fprintf(stderr, "Failed to lock Door A.\n");
            goto cleanup;
        }
        if (lock_door(line_b) < 0) {
            fprintf(stderr, "Failed to lock Door B.\n");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure doors are locked on exit. */
    if (line_a)
        gpiod_line_set_value(line_a, 0);
    if (line_b)
        gpiod_line_set_value(line_b, 0);

    if (chip)
        gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return ret;
}

