                I2C_BUS, BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
