            gpioDelay(POLL_INTERVAL_US);
        }
    }

    printf("\nExiting gracefully...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

