/*
 * LSM303DLHC magnetometer reader with hardware PWM LED indicator.
 *
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (SDA1/SCL1), physical pins 2/3
 * Sensor: LSM303DLHC magnetometer (magnetometer module)
 * LED:    GPIO17 (BCM), hardware PWM
 *
 * Build:  gcc -O2 -Wall -o mag_led mag_led.c -lpigpio -lrt
 * Run:    sudo ./mag_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

/* ---- LSM303DLHC magnetometer register map (magnetometer module) ---- */
#define LSM303_REG_CTRL_REG1   0x20
#define LSM303_REG_CTRL_REG2   0x21
#define LSM303_REG_CTRL_REG3   0x22
#define LSM303_REG_OUT_X_L     0x28
#define LSM303_REG_OUT_X_H     0x29
#define LSM303_REG_OUT_Y_L     0x2A
#define LSM303_REG_OUT_Y_H     0x2B
#define LSM303_REG_OUT_Z_L     0x2C
#define LSM303_REG_OUT_Z_H     0x2D

/* ---- Application constants ---- */
#define I2C_BUS              1
#define I2C_ADDR             0x19          /* LSM303DLHC magnetometer address */
#define LED_GPIO             17            /* BCM 17 */
#define PWM_RANGE            1024          /* 0-1024 duty-cycle steps */
#define PWM_FREQ             1000          /* 1 kHz */
#define SAMPLE_PERIOD_US     100000        /* 100 ms */
#define LOG_FILE             "mag_led.log"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an 8-bit-addressed register.                 */
static int lsm303_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(val >> 8);
    buf[2] = (char)(val & 0xFF);
    if (i2cWriteDevice(fd, buf, 3) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an 8-bit-addressed register.                */
static int lsm303_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(fd, reg_buf, 1) != 0)
        return -1;
    char data[2];
    if (i2cReadDevice(fd, data, 2) != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the LSM303DLHC magnetometer.                             */
static int lsm303_init(int fd)
{
    /*
     * CTRL_REG1: 0x00  ODR = 0 (0 Hz)  -> magnetometer is in standby
     * CTRL_REG2: 0x00  ODR = 0 (0 Hz)  -> magnetometer is in standby
     * CTRL_REG3: 0x00  ODR = 0 (0 Hz)  -> magnetometer is in standby
     *
     * The magnetometer module is not a full LSM303DLHC; it is a
     * standalone magnetometer that exposes registers 0x28..0x2D.
     * We enable the magnetometer by writing 0x00 to CTRL_REG1.
     */
    if (lsm303_write_reg16(fd, LSM303_REG_CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the Z-axis magnetic field magnitude.                           */
static int lsm303_read_z_magnitude(int fd, int16_t *out)
{
    uint16_t raw;
    if (lsm303_read_reg16(fd, LSM303_REG_OUT_Z_L, &raw) != 0) {
        fprintf(stderr, "Error: I2C read failed (reg 0x2C)\n");
        return -1;
    }
    *out = (int16_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Map the Z-axis magnitude to a PWM duty cycle (0-1024).             */
static int mag_to_pwm(int16_t mag)
{
    if (mag < 0)   mag = 0;
    if (mag > 32767) mag = 32767;
    return (int)(((double)mag / 32767.0) * PWM_RANGE);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped line to the log file.                           */
static void log_line(const char *msg)
{
    if (!g_log_fp)
        return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_fp, "[%s] %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (lsm303_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Error: LSM303DLHC initialisation failed\n");
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed\n", LED_GPIO);
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", LED_GPIO);
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", LED_GPIO);
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioPWM(LED_GPIO, 0);   /* start with LED off */

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioPWM(LED_GPIO, 0);
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_line("Program started");

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_line("Program started");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t mag;
        if (lsm303_read_z_magnitude(g_i2c_fd, &mag) != 0) {
            log_line("I2C read error, skipping sample");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int pwm = mag_to_pwm(mag);
        gpioPWM(LED_GPIO, pwm);

        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Z-axis: %d, PWM: %d", mag, pwm);
        log_line(msg);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    log_line("Shutting down");
    gpioPWM(LED_GPIO, 0);
    if (g_i2c_fd >= 0)
        i2cClose(g_i2c_fd);
    if (g_log_fp)
        fclose(g_log_fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

