    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", LED_GPIO);
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioPWM(LED_GPIO, 0);   /* start with LED off */

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioPWM(LED_GPIO, 0);
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_line("Program started");

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_line("Program started");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t mag;
        if (lsm303_read_z_magnitude(g_i2c_fd, &mag) != 0) {
            log_line("I2C read error, skipping sample");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int pwm = mag_to_pwm(mag);
        gpioPWM(LED_GPIO, pwm);

        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Z-axis: %d, PWM: %d", mag, pwm);
        log_line(msg);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    log_line("Shutting down");
    gpioPWM(LED_GPIO, 0);
    if (g_i2c_fd >= 0)
        i2cClose(g_i2c_fd);
    if (g_log_fp)
        fclose(g_log_fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

