/*
 * HMC5883L magnetometer reader with hard-iron offset compensation.
 *
 * Wiring (Raspberry Pi Zero W, I2C bus 1):
 *   HMC5883L SDA  -> GPIO2 (pin 3)
 *   HMC5883L SCL  -> GPIO3 (pin 5)
 *   HMC5883L VDD  -> 3.3 V
 *   HMC5883L GND  -> GND
 *
 * The HMC5883L is a 4-component (X, Y, Z, temp) magnetometer.
 * This program reads raw 14-bit signed data and applies a running
 * average of the last 100 samples to compute a hard-iron-compensated
 * offset.  The offset is subtracted from each raw sample before
 * printing.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hmc5883l_comp hmc5883l_comp.c -lpigpio -lrt
 * Run:    sudo ./hmc5883l_comp
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- HMC5883L register map (datasheet) ---- */
#define HMC5883L_ADDR        0x40
#define HMC5883L_CTRL_REG1   0x2A
#define HMC5883L_CTRL_REG2   0x2B
#define HMC5883L_OUT_X_L     0x2C
#define HMC5883L_OUT_X_H     0x2D
#define HMC5883L_OUT_Y_L     0x2E
#define HMC5883L_OUT_Y_H     0x2F
#define HMC5883L_OUT_Z_L     0x30
#define HMC5883L_OUT_Z_H     0x31

#define HMC5883L_CTRL_REG1_VAL 0x03  /* 4-component mode, 14-bit, continuous */
#define HMC5883L_CTRL_REG2_VAL 0x00  /* 100 Hz output data rate */

#define SAMPLE_RATE_MS        500
#define HARD_IRON_WINDOW      100
#define I2C_BUS               1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, pigpio_error(rc));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Hard-iron offset computation                                       */
/* ------------------------------------------------------------------ */
static void compute_hard_iron_offset(
    int16_t *x_offset, int16_t *y_offset, int16_t *z_offset,
    int16_t *x_buf, int16_t *y_buf, int16_t *z_buf,
    int n)
{
    if (n <= 1) {
        *x_offset = 0;
        *y_offset = 0;
        *z_offset = 0;
        return;
    }

    double x_sum = 0.0;
    double y_sum = 0.0;
    double z_sum = 0.0;

    for (int i = 0; i < n; i++) {
        x_sum += x_buf[i];
        y_sum += y_buf[i];
        z_sum += z_buf[i];
    }

    *x_offset = (int16_t)(x_sum / n);
    *y_offset = (int16_t)(y_sum / n);
    *z_offset = (int16_t)(z_sum / n);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, HMC5883L_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure HMC5883L ---- */
    if (i2c_write_reg(g_i2c_handle, HMC5883L_CTRL_REG1,
                      HMC5883L_CTRL_REG1_VAL) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_reg(g_i2c_handle, HMC5883L_CTRL_REG2,
                      HMC5883L_CTRL_REG2_VAL) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- buffers ---- */
    int16_t x_buf[HARD_IRON_WINDOW];
    int16_t y_buf[HARD_IRON_WINDOW];
    int16_t z_buf[HARD_IRON_WINDOW];
    int idx = 0;
    int n = 0;

    /* ---- main loop ---- */
    while (g_running) {
        uint8_t x_l, x_h, y_l, y_h, z_l, z_h;

        if (i2c_read_reg(g_i2c_handle, HMC5883L_OUT_X_L, &x_l) < 0 ||
            i2c_read_reg(g_i2c_handle, HMC5883L_OUT_X_H, &x_h) < 0 ||
            i2c_read_reg(g_i2c_handle, HMC5883L_OUT_Y_L, &y_l) < 0 ||
            i2c_read_reg(g_i2c_handle, HMC5883L_OUT_Y_H, &y_h) < 0 ||
            i2c_read_reg(g_i2c_handle, HMC5883L_OUT_Z_L, &z_l) < 0 ||
            i2c_read_reg(g_i2c_handle, HMC5883L_OUT_Z_H, &z_h) < 0) {
            fprintf(stderr, "I2C read error — continuing\n");
            gpioDelay(SAMPLE_RATE_MS * 1000);
            continue;
        }

        int16_t raw_x = (int16_t)((x_h << 8) | x_l);
        int16_t raw_y = (int16_t)((y_h << 8) | y_l);
        int16_t raw_z = (int16_t)((z_h << 8) | z_l);

        x_buf[idx] = raw_x;
        y_buf[idx] = raw_y;
        z_buf[idx] = raw_z;
        idx = (idx + 1) % HARD_IRON_WINDOW;
        n++;

        compute_hard_iron_offset(&x_buf[0], &y_buf[0], &z_buf[0],
                                  x_buf, y_buf, z_buf, n);

        int16_t x_corr = raw_x - x_buf[0];
        int16_t y_corr = raw_y - y_buf[0];
        int16_t z_corr = raw_z - z_buf[0];

        printf("X: %6d  Y: %6d  Z: %6d  (raw_x: %6d  raw_y: %6d  raw_z: %6d)\n",
               x_corr, y_corr, z_corr,
               raw_x, raw_y, raw_z);
        fflush(stdout);

        gpioDelay(SAMPLE_RATE_MS * 1000);
    }

    /* ---- graceful shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

