/*
 * LSM303D tri-axial accelerometer monitor for Raspberry Pi Zero W.
 *
 * Wiring:
 *   LSM303D SDA  -> GPIO 2  (I2C bus 1, pin 3)
 *   LSM303D SCL  -> GPIO 3  (I2C bus 1, pin 5)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *   LSM303D INT1 -> GPIO 23 (BCM, pin 16)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 *
 * Run:
 *   ./lsm303d_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D constants (from datasheet) ---- */
#define LSM303D_ADDR          0x19
#define LSM303D_WHO_AM_I      0x0F
#define LSM303D_WHO_AM_I_VAL  0x33
#define LSM303D_CTRL_REG1     0x20
#define LSM303D_CTRL_REG2     0x21
#define LSM303D_CTRL_REG3     0x22
#define LSM303D_OUT_X_L       0x28
#define LSM303D_OUT_X_H       0x29
#define LSM303D_OUT_Y_L       0x2A
#define LSM303D_OUT_Y_H       0x2B
#define LSM303D_OUT_Z_L       0x2C
#define LSM303D_OUT_Z_H       0x2D

#define ACCEL_SENSITIVITY     0.061f   /* mg per LSB */
#define INT1_THRESHOLD_MG     2000.0f  /* 2000 mg */
#define INT1_DURATION_MS     100      /* 100 ms */
#define BUFFER_SIZE           64
#define SAMPLE_PERIOD_MS      10
#define I2C_DEV               "/dev/i2c-1"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int_line = NULL;

/* ---- Circular buffer ---- */
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int   head;
    int   count;
} circular_buffer_t;

static circular_buffer_t g_buffer;

/* ---- Prototypes ---- */
static int  i2c_write_reg(uint8_t reg, uint8_t val);
static int  i2c_read_reg(uint8_t reg, uint8_t *val);
static int  init_lsm303d(void);
static int  read_accel(float *x, float *y, float *z);
static void buffer_add(float x, float y, float z);
static void dump_buffer(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_lsm303d(void)
{
    uint8_t who;
    if (i2c_read_reg(LSM303D_WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (who != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby first so configuration changes take effect */
    if (i2c_write_reg(LSM303D_CTRL_REG1, 0x00) != 0) return -1;

    /* CTRL_REG2: accelerometer enable, 12-bit mode, no self-test */
    if (i2c_write_reg(LSM303D_CTRL_REG2, 0x00) != 0) return -1;

    /* CTRL_REG3: accelerometer full-scale range 2g, 100 Hz ODR */
    if (i2c_write_reg(LSM303D_CTRL_REG3, 0x00) != 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_accel(float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg(LSM303D_OUT_X_L, &xl) != 0) return -1;
    if (i2c_read_reg(LSM303D_OUT_X_H, &xh) != 0) return -1;
    if (i2c_read_reg(LSM303D_OUT_Y_L, &yl) != 0) return -1;
    if (i2c_read_reg(LSM303D_OUT_Y_H, &yh) != 0) return -1;
    if (i2c_read_reg(LSM303D_OUT_Z_L, &zl) != 0) return -1;
    if (i2c_read_reg(LSM303D_OUT_Z_H, &zh) != 0) return -1;

    int16_t rx = (int16_t)((xh << 8) | xl);
    int16_t ry = (int16_t)((yh << 8) | yl);
    int16_t rz = (int16_t)((zh << 8) | zl);

    *x = (float)rx * ACCEL_SENSITIVITY;
    *y = (float)ry * ACCEL_SENSITIVITY;
    *z = (float)rz * ACCEL_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
static void buffer_add(float x, float y, float z)
{
    g_buffer.x[g_buffer.head] = x;
    g_buffer.y[g_buffer.head] = y;
    g_buffer.z[g_buffer.head] = z;
    g_buffer.head = (g_buffer.head + 1) % BUFFER_SIZE;
    if (g_buffer.count < BUFFER_SIZE) g_buffer.count++;
}

/* ------------------------------------------------------------------ */
static void dump_buffer(void)
{
    printf("\n--- Last %d Samples ---\n", g_buffer.count);
    for (int i = 0; i < g_buffer.count; i++) {
        int idx = (g_buffer.head - g_buffer.count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct timespec ts_now;
        clock_gettime(CLOCK_REALTIME, &ts_now);
        struct tm tm_info;
        localtime_r(&ts_now.tv_sec, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s.%03ld] X: %.2f mg, Y: %.2f mg, Z: %.2f mg\n",
               ts, ts_now.tv_nsec / 1000000L,
               g_buffer.x[idx], g_buffer.y[idx], g_buffer.z[idx]);
    }
    printf("--------------------------\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_int_line) {
        gpiod_line_release(g_int_line);
        g_int_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Put LSM303D into standby before closing */
        (void)i2c_write_reg(LSM303D_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize LSM303D */
    if (init_lsm303d() != 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
