#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define ACTIVATION_DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed: %s\n",
                pin, mode, strerror(errno));
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed: %s\n",
                pin, level, strerror(errno));
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned pin, unsigned pull_type)
{
    if (gpioSetPullUpDown(pin, pull_type) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed: %s\n",
                pin, pull_type, strerror(errno));
        return -1;
    }
    return 0;
}

static int safe_sleep(unsigned seconds)
{
    struct timespec req = { .tv_sec = seconds, .tv_nsec = 0 };
    struct timespec rem;

    while (nanosleep(&req, &rem) != 0) {
        if (errno != EINTR) {
            perror("nanosleep");
            return -1;
        }
        req = rem;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    if (safe_set_mode(SOLENOID_1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_pull(SOLENOID_1_PIN, PI_PUD_OFF) != 0 ||
        safe_set_pull(SOLENOID_2_PIN, PI_PUD_OFF) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure both solenoids are de-energized at startup */
    if (safe_write(SOLENOID_1_PIN, 0) != 0 ||
        safe_write(SOLENOID_2_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int active_pin = SOLENOID_1_PIN;

    while (g_running) {
        if (safe_write(active_pin, 1) != 0) {
            break;
        }
        if (safe_sleep(ACTIVATION_DELAY_MS / 1000) != 0) {
            break;
        }
        if (safe_write(active_pin, 0) != 0) {
            break;
        }
        if (safe_sleep(ACTIVATION_DELAY_MS / 1000) != 0) {
            break;
        }
        active_pin = (active_pin == SOLENOID_1_PIN) ? SOLENOID_2_PIN : SOLENOID_1_PIN;
    }

    /* Clean shutdown: ensure both solenoids are de-energized */
    safe_write(SOLENOID_1_PIN, 0);
    safe_write(SOLENOID_2_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

