#define READ_TIMEOUT_SEC 5
#define LOCK_DURATION_SEC 2

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_uart(const char *port, int *fd_out) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1; /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int read_uart_line(int fd, char *buf, size_t buf_size, int timeout_sec) {
    size_t total = 0;
    struct timeval tv;
    tv.tv_sec = timeout_sec;
    tv.tv_usec = 0;

    while (total < buf_size - 1) {
        int n = read(fd, buf + total, buf_size - 1 - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART timeout: no data within %d seconds\n", timeout_sec);
            return -1;
        }
        total += n;
        tv.tv_sec = timeout_sec;
        tv.tv_usec = 0;
        if (select(fd + 1, &tv, NULL, NULL, &tv) == 0) {
            break;
        }
    }

    buf[total] = '\0';
    return (total > 0) ? 0 : -1;
}

static int validate_code(const char *code) {
    if (strcmp(code, EXPECTED_CODE) != 0) {
        fprintf(stderr, "Code validation failed: expected '%s', got '%s'\n",
                EXPECTED_CODE, code);
        return 0;
    }
    return 1;
}

static int unlock_door(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", gpio_pin);
        return -1;
    }
    gpioDelay(LOCK_DURATION_SEC * 1000000);
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int fd_primary = -1, fd_secondary = -1;
    char primary_code[CODE_LENGTH + 1] = {0};
    char secondary_code[CODE_LENGTH + 1] = {0};

    if (initialize_uart(PRIMARY_UART_PORT, &fd_primary) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (initialize_uart(SECONDARY_UART_PORT, &fd_secondary) != 0) {
        close(fd_primary);
        gpioTerminate();
        return EXIT_FAILURE;
    }

