        if (n == 0) {
            fprintf(stderr, "Primary UART timeout\n");
            continue;
        }
        if (n < 0) {
            continue;
        }

        /* Parse first code from line */
        char *saveptr = NULL;
        char *token = strtok_r(buf, " \r\n", &saveptr);
        if (token == NULL) {
            fprintf(stderr, "Primary UART: no code found\n");
            continue;
        }
        strncpy(primary_code, token, CODE_LENGTH);
        primary_code[CODE_LENGTH] = '\0';

        /* Parse second code from line */
        token = strtok_r(buf, " \r\n", &saveptr);
        if (token == NULL) {
            fprintf(stderr, "Secondary UART: no code found\n");
            continue;
        }
        strncpy(secondary_code, token, CODE_LENGTH);
        secondary_code[CODE_LENGTH] = '\0';

        if (validate_code(primary_code) == 0 && validate_code(secondary_code) == 0) {
            if (unlock_door(PRIMARY_GPIO) != 0 || unlock_door(SECONDARY_GPIO) != 0) {
                fprintf(stderr, "Failed to unlock doors\n");
            } else {
                fprintf(stderr, "Doors unlocked successfully.\n");
            }
        } else {
            fprintf(stderr, "Authentication failed: primary='%s', secondary='%s'\n",
                    primary_code, secondary_code);
        }

        /* Reset input buffers on any non-digit character */
        char *last_non_digit = NULL;
        for (char *p = buf; *p; p++) {
            if (*p != ' ' && *p != '\t' && *p != '\n' && *p != '\r') {
                last_non_digit = p;
                break;
            }
        }
        if (last_non_digit) {
            memmove(buf, last_non_digit, strlen(last_non_digit) + 1);
            buf[strlen(last_non_digit) + 1] = '\0';
        }
    }

    /* Clean shutdown: lock doors and release resources */
    fprintf(stderr, "Shutting down...\n");
    gpioWrite(PRIMARY_GPIO, 0);
    gpioWrite(SECONDARY_GPIO, 0);
    close(fd_primary);
    close(fd_secondary);
    gpioTerminate();
    return EXIT_SUCCESS;
