#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL_US 50000
#define RELAY_ON_DURATION_US 1000000
#define PIR_HIGH_THRESHOLD_S 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int priority, const char *message) {
    char buffer[256];
    int len = snprintf(buffer, sizeof(buffer), "%s", message);
    if (len > 0) {
        syslog(priority, "%s", buffer);
    }
}

static void log_relay_state(int relay_state) {
    char message[128];
    snprintf(message, sizeof(message), "Relay %s", relay_state ? "ON" : "OFF");
    log_event(LOG_INFO, message);
}

static void log_warning(const char *message) {
    char message_with_timestamp[256];
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t) {
        strftime(message_with_timestamp, sizeof(message_with_timestamp), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(message_with_timestamp, sizeof(message_with_timestamp), "UNKNOWN");
    }
    log_event(LOG_WARNING, message_with_timestamp);
}

static void cleanup_gpio(void) {
    if (gpioInitialise() >= 0) {
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
    }
}

int main(void) {
    openlog("pir_door_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_event(LOG_ERR, "Failed to register SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_event(LOG_ERR, "Failed to register SIGTERM handler");
    }

    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        log_event(LOG_ERR, "Failed to set PIR pin mode");
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        log_event(LOG_ERR, "Failed to set relay pin mode");
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        log_event(LOG_ERR, "Failed to initialize relay to OFF state");
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    log_event(LOG_INFO, "Door monitor started");

    int relay_state = 0;
    int relay_on = 0;
    time_t relay_on_start_time = 0;

    while (running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            log_event(LOG_ERR, "Failed to read PIR sensor");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (pir_value == 1) {
            time_t now = time(NULL);
            if (now - relay_on_start_time >= PIR_HIGH_THRESHOLD_S) {
                log_warning("PIR HIGH threshold exceeded - potential malfunction");
                relay_state = 0;
                relay_on = 0;
                relay_on_start_time = now;
                log_event(LOG_WARNING, "PIR HIGH threshold exceeded - potential malfunction");
            } else {
                if (relay_state == 0) {
                    if (gpioWrite(RELAY_PIN, 1) == 0) {
                        relay_state = 1;
                        relay_on = 1;
                        relay_on_start_time = now;
                        log_relay_state(1);
                    } else {
                        log_event(LOG_ERR, "Failed to activate relay");
                    }
                }
            }
        } else {
            if (relay_on) {
                if (gpioWrite(RELAY_PIN, 0) == 0) {
                    relay_state = 0;
                    relay_on = 0;
                    log_relay_state(0);
                } else {
                    log_event(LOG_ERR, "Failed to deactivate relay");
                }
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    log_event(LOG_INFO, "Shutting down door monitor");
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

