#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/timerfd.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define MPU6050_REG_WHO_AM_I 0x75
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_WHO_AM_I_VAL 0x68
#define SAMPLE_RATE_HZ 100
#define BUFFER_SIZE 100
#define TIMER_PATH "/sys/kernel/mpu6050_accel/latest"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read burst from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    uint8_t who;
    if (i2c_read_burst(fd, MPU6050_REG_WHO_AM_I, &who, 1) < 0) {
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "MPU6050 WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_byte(fd, 0x8D, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x8E, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x91, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, 0x92, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x93, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x94, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x95, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x96, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x97, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x98, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x99, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0xA1, 0x0F) < 0) return -1;
    if (i2c_write_byte(fd, 0xAC, 0x06) < 0) return -1;
    if (i2c_write_byte(fd, 0xAD, 0x03) < 0) return -1;
    if (i2c_write_byte(fd, 0xAE, 0x02) < 0) return -1;
    if (i2c_write_byte(fd, 0xAF, 0x01) < 0) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_REG_ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void timer_callback(int fd, struct timespec *ts, int timerid) {
    (void)timerid;
    int16_t x, y, z;
    if (read_accel(fd, &x, &y, &z) < 0) {
        fprintf(stderr, "Accel read failed; skipping sample\n");
        return;
    }
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    double dt = (now.tv_sec - ts->tv_sec) + (now.tv_nsec - ts->tv_nsec) / 1e9;
    if (dt <= 0.0) dt = 1e-9;
    char buf[BUFFER_SIZE * 4];
    int idx = (timerid % BUFFER_SIZE) + 1;
    int n = snprintf(buf + (idx * 4), BUFFER_SIZE - (idx * 4), "%.6f,%.6f,%.6f,%.6f\n", dt, x, y, z);
    if (n < 0 || (size_t)n >= BUFFER_SIZE) {
        fprintf(stderr, "Buffer overflow; dropping sample\n");
        return;
    }
    if (write(TIMER_PATH, buf, (size_t)n) != (ssize_t)n) {
        fprintf(stderr, "write to %s failed: %s\n", TIMER_PATH, strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU6050 init failed; sensor may be absent or bus error\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct timespec ts = {0, 1e6};
    struct itimerspec its = {0};
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 1e6;
    its.it_value = ts;
    if (timerfd_create(CLOCK_MONOTONIC, &its) < 0) {
        fprintf(stderr, "timerfd_create failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    int timerid = timerfd_get_fd(its.it_value.tv_sec);
    if (timerid < 0) {
        fprintf(stderr, "timerfd_get_fd failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    if (timerfd_settime(timerid, 0, &its, NULL) < 0) {
        fprintf(stderr, "timerfd_settime failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU6050 sampling at %d Hz. Press Ctrl+C to stop.\n", SAMPLE_RATE_HZ);

    while (g_running) {
        struct timespec req = {0, 1e6};
        if (nanosleep(&req, NULL) < 0 && errno != EINTR) {
            fprintf(stderr, "nanosleep failed: %s\n", strerror(errno));
            break;
        }
        timer_callback(fd, NULL, timerid);
    }

    close(timerid);
    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

