#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define RELAY1_INTERVAL_SEC 2
#define RELAY2_INTERVAL_SEC 3
#define RELAY3_INTERVAL_SEC 5
#define RELAY4_INTERVAL_SEC 7

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_relay(int pin, int state)
{
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, state);
        return -1;
    }
    return 0;
}

static int toggle_relay(int pin)
{
    int current = gpioRead(pin);
    if (current < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed\n", pin);
        return -1;
    }
    if (set_relay(pin, !current) != 0)
        return -1;
    return 0;
}

static int get_interval_sec(int pin)
{
    static const int intervals[] = {
        RELAY1_INTERVAL_SEC,
        RELAY2_INTERVAL_SEC,
        RELAY3_INTERVAL_SEC,
        RELAY4_INTERVAL_SEC
    };
    return intervals[pin - RELAY1_PIN];
}

static int all_relays_off(void)
{
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (set_relay(pins[i], 0) != 0)
            return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", pins[i]);
            all_relays_off();
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Relay control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            int interval = get_interval_sec(pins[i] + RELAY1_PIN);
            struct timespec ts;
            if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
                perror("clock_gettime");
                all_relays_off();
                break;
            }
            if (toggle_relay(pins[i]) != 0) {
                all_relays_off();
                break;
            }
            if (interval > 0) {
                struct timespec sleep_ts = {
                    .tv_sec  = interval,
                    .tv_nsec = 0
                };
                nanosleep(&sleep_ts, NULL);
            }
        }
    }

    all_relays_off();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

