#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define LOG_FILE "alarm_log.txt"
#define POLL_INTERVAL_US 100000
#define RELAY_ACTIVATION_US 3000000
#define DEBOUNCE_US 500000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d: Alarm triggered\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec);
    } else {
        fprintf(fp, "Timestamp error: %s\n", filename);
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static int activate_relay(int pin, int duration_us) {
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "gpioWrite(on) failed on pin %d\n", pin);
        return -1;
    }
    gpioDelay(duration_us);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "gpioWrite(off) failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(input) failed on pin %d\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(output) failed on pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(off) initial failed on pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d. Relay on GPIO%d. Press Ctrl+C to exit.\n",
           SOUND_SENSOR_PIN, RELAY_PIN);

    uint32_t last_activation_tick = 0;

    while (program_running) {
        int level = gpioRead(SOUND_SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on pin %d\n", SOUND_SENSOR_PIN);
            break;
        }

        if (level == 1) {
            uint32_t now = gpioTick();
            if (now - last_activation_tick >= DEBOUNCE_US) {
                printf("Sound detected! Activating relay for 3 seconds...\n");
                if (activate_relay(RELAY_PIN, RELAY_ACTIVATION_US) == 0) {
                    if (log_event(LOG_FILE) == 0) {
                        printf("Alarm event logged.\n");
                    } else {
                        fprintf(stderr, "Failed to log event.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to activate relay.\n");
                }
                last_activation_tick = now;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

