#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <math.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define REG_GYRO_XOUT_H 0x43
#define REG_PWR_MGMT_1 0x6B
#define REG_GYRO_CONFIG 0x1B
#define BUFFER_SIZE 100
#define THRESHOLD 50.0f

typedef struct {
    float x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg(fd, REG_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg(fd, REG_GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_regs(fd, REG_GYRO_XOUT_H, buf, 6) < 0) return -1;

    int16_t x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z = (int16_t)((buf[4] << 8) | buf[5]);

    data->x = (float)x / 131.0f;
    data->y = (float)y / 131.0f;
    data->z = (float)z / 131.0f;
    return 0;
}

static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) buffer->count++;
}

static float calculate_angular_velocity(gyro_data_t data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

static void callback_function(float angular_velocity) {
    printf("Angular velocity threshold exceeded! Velocity: %.2f degrees/second\n", angular_velocity);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    gyro_data_t gyro_data;
    while (running) {
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            gyro_data.x = -gyro_data.x;
            gyro_data.y = -gyro_data.y;
            gyro_data.z = -gyro_data.z;
            add_to_buffer(&gyro_buffer, gyro_data);
            float angular_velocity = calculate_angular_velocity(gyro_data);
            if (fabsf(angular_velocity) > THRESHOLD) {
                callback_function(angular_velocity);
            }
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }
        usleep(10000);
    }

    close(i2c_fd);
    return 0;
}

