/*
 * co2_monitor.c — Raspberry Pi 3 Model B+
 *
 * Reads CO2 concentration from an MH-Z19B sensor over UART using the
 * pigpio driver library.  The sensor TXD is mapped to BCM GPIO14 (TXD)
 * and the RXD is mapped to BCM GPIO15 (RXD).  The 9-byte command
 * sequence is sent, then 9 bytes of response are read.  Each reading
 * is written to co2_log.json as a JSON object and printed to stdout.
 *
 * Build:  gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lpigpio -lrt
 * Run:    sudo ./co2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"

#define MH_Z19B_CMD_LEN  9
#define MH_Z19B_READ_LEN 9
#define MH_Z19B_CRC_LEN  2
#define MH_Z19B_TIMEOUT_US 1000000   /* 1 s */
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_err_fp)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_err_fp, "%s: %s\n", ts, msg);
    fflush(g_err_fp);
}

static void log_data(uint32_t ppm, int error)
{
    if (!g_log_fp)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp,
            "{\"timestamp\":\"%s\",\"ppm\":%u,\"error\":%d}\n",
            ts, ppm, error);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* MH-Z19B checksum (polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte CO2 measurement from the MH-Z19B sensor            */
/* ------------------------------------------------------------------ */
static int read_mh_z19b(int uart_fd, uint32_t *ppm_out)
{
    uint8_t cmd[MH_Z19B_CMD_LEN] = {
        0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09
    };
    uint8_t rx[MH_Z19B_READ_LEN];

    /* Send the 9-byte command */
    if (serWrite(uart_fd, (char *)cmd, MH_Z19B_CMD_LEN) != MH_Z19B_CMD_LEN) {
        log_error("Failed to write MH-Z19B command");
        return -1;
    }

    /* Wait for the sensor to respond (max ~100 ms) */
    uint32_t waited = 0;
    while (g_running && waited < MH_Z19B_TIMEOUT_US) {
        gpioDelay(1000);   /* 1 ms */
        waited += 1000;
    }
    if (!g_running)
        return -1;

    /* Read the 9-byte response */
    int n = serRead(uart_fd, (char *)rx, MH_Z19B_READ_LEN);
    if (n != MH_Z19B_READ_LEN) {
        log_error("Failed to read MH-Z19B response");
        return -1;
    }

    /* Verify CRC */
    if (crc8(rx, 2) != rx[2]) {
        log_error("CRC mismatch on MH-Z19B response");
        return -1;
    }
    if (crc8(rx + 3, 2) != rx[5]) {
        log_error("CRC mismatch on MH-Z19B response (continued)");
        return -1;
    }
    if (crc8(rx + 6, 2) != rx[8]) {
        log_error("CRC mismatch on MH-Z19B response (continued)");
        return -1;
    }

    /* Parse the 16-bit big-endian ppm value */
    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];
    *ppm_out = (uint32_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open log files */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen(" ERROR_LOG_FILE ")");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        fclose(g_log_fp);
        g_log_fp = NULL;
        fclose(g_err_fp);
        g_err_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Open UART */
    int uart_fd = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_fd < 0) {
        log_error("Failed to open UART device");
        gpioTerminate();
        fclose(g_log_fp);
        g_log_fp = NULL;
        fclose(g_err_fp);
        g_err_fp = NULL;
        return EXIT_FAILURE;
    }

    printf("CO2 monitoring started on %s @ %d baud.  Press Ctrl+C to exit.\n",
           UART_DEVICE, BAUD_RATE);

    while (g_running) {
        uint32_t ppm = 0;
        int rc = read_mh_z19b(uart_fd, &ppm);

        if (rc == 0) {
            log_data(ppm, 0);
            printf("CO2: %u ppm\n", ppm);
        } else {
            log_data(0, 1);
            log_error("Failed to read CO2 measurement");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* Clean shutdown */
    serClose(uart_fd);
    gpioTerminate();
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }

    printf("\nCO2 monitoring stopped.\n");
    return EXIT_SUCCESS;
}

