static float get_average_heading(void);
static void control_led(float heading);
static void signal_handler(int signal);
static void cleanup(void);

/* Initialize the HMC5883L magnetometer */
static int initialize_hmc5883l(void) {
    /*
     * Config A: 0x00 = 0x00, 0x00, 0x00, 0x00
     * Config B: 0x00 = 0x00, 0x00, 0x00, 0x00
     * Enable X, Y, Z axes, 10 Hz data rate, 14-bit resolution.
     */
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x00) < 0) {
        fprintf(stderr, "Error writing Config A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x00) < 0) {
        fprintf(stderr, "Error writing Config B\n");
        return -1;
    }
    return 0;
}

/* Read raw magnetometer data and convert to compensated heading */
static int read_magnetometer_data(float *x, float *y, float *z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    int16_t x_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t z_raw = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t y_raw = (int16_t)((buf[4] << 8) | buf[5]);

    /* Apply hard-iron compensation */
    *x = (float)x_raw - X_OFFSET;
    *y = (float)y_raw - Y_OFFSET;
    *z = (float)z_raw;

    /* Convert to degrees (0 to 360) */
    *x = (*x / 131.0f) * 360.0f;
    *y = (*y / 131.0f) * 360.0f;
    *z = (*z / 131.0f) * 360.0f;

    return 0;
}

