#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x44
#define BH1750_CMD_CONV 0x10
#define BH1750_CONV_MS 120
#define LOG_FILE       "lighting_log.txt"
#define RED_PIN        17
#define GREEN_PIN      27
#define BLUE_PIN       22
#define LUX_THRESHOLD_RED 50.0f
#define LUX_THRESHOLD_GREEN 150.0f
#define LUX_THRESHOLD_BLUE 300.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *out) {
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_lux(int fd, float *lux_out) {
    if (i2c_write_byte(fd, BH1750_CMD_CONV) < 0)
        return -1;

    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_byte(fd, &buf[0]) < 0)
        return -1;
    if (i2c_read_byte(fd, &buf[1]) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(float lux, int red, int green, int blue) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s, Lux: %.2f, RED: %d, GREEN: %d, BLUE: %d\n",
            ts, lux, red, green, blue);
    fflush(g_log_fp);
}

static void control_relays(float lux) {
    int red = 0, green = 0, blue = 0;

    if (lux < LUX_THRESHOLD_RED) {
        if (!red) {
            if (gpioWrite(RED_PIN, 1) == 0) {
                red = 1;
            }
        }
    } else if (lux < LUX_THRESHOLD_GREEN) {
        if (!green) {
            if (gpioWrite(GREEN_PIN, 1) == 0) {
                green = 1;
            }
        }
    } else if (lux < LUX_THRESHOLD_BLUE) {
        if (!blue) {
            if (gpioWrite(BLUE_PIN, 1) == 0) {
                blue = 1;
            }
        }
    }

    if (red && !green && !blue) {
        if (gpioWrite(GREEN_PIN, 0) == 0) {
            green = 0;
        }
    } else if (!red && green && !blue) {
        if (gpioWrite(RED_PIN, 0) == 0) {
            red = 0;
        }
    } else if (!red && !green && blue) {
        if (gpioWrite(BLUE_PIN, 0) == 0) {
            blue = 0;
        }
    }

    if (red && green && blue) {
        if (gpioWrite(RED_PIN, 1) == 0 && gpioWrite(GREEN_PIN, 1) == 0 &&
            gpioWrite(BLUE_PIN, 1) == 0) {
            red = green = blue = 1;
        }
    }
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        i2c_write_byte(g_i2c_fd, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return 1;
    }

    if (gpioWrite(RED_PIN, 0) < 0 || gpioWrite(GREEN_PIN, 0) < 0 ||
        gpioWrite(BLUE_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise GPIO states\n");
        cleanup();
        return 1;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("BH1750 light sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        if (read_lux(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed; skipping cycle.\n");
        } else {
            log_data(lux, 0, 0, 0);
            control_relays(lux);
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

