/*
 * Dual-motor control via L298N using proportional PWM on distance readings.
 * Board:  Raspberry Pi 3 Model B+
 * Driver: L298N (dual H-bridge)
 * Pins:   Motor A IN1=GPIO17, IN2=GPIO18 (PWM on IN2)
 *          Motor B IN3=GPIO22, IN4=GPIO23 (PWM on IN4)
 * Build:  gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:    sudo ./motor_control 10 100
 */
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define LOOP_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Drive a motor in the direction specified by *dir.
 * dir == 1 -> forward, dir == 0 -> backward.
 * Returns 0 on success, -1 on GPIO error.
 */
static int motor_drive(int in1, int in2, int in3, int in4, int dir)
{
    if (gpioWrite(in1, dir ? 1 : 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(IN1=%d) failed\n", in1);
        return -1;
    }
    if (gpioWrite(in2, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(IN2) failed\n");
        return -1;
    }
    if (gpioWrite(in3, 0) < 0) {
