/*
 * 28BYJ-48 stepper door lock control via L293D H-bridge driver.
 *
 * Button mapping (BCM):
 *   GPIO17  -> LOCK button (active-low)
 *   GPIO18  -> UNLOCK button (active-low)
 *   GPIO27  -> IN1 (stepper coil 1)
 *   GPIO22  -> IN2 (stepper coil 2)
 *   GPIO24  -> LOCK button (internal pull-up, active-low)
 *   GPIO23  -> UNLOCK button (internal pull-up, active-low)
 *
 * Full-step two-phase drive with 2 ms inter-step delay.
 * Rotates 512 steps clockwise on LOCK press, 512 steps counter-clockwise
 * on UNLOCK press (a quarter turn).
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define IN1 27
#define IN2 22
#define LOCK_BUTTON 17
#define UNLOCK_BUTTON 18
#define LOCK_BUTTON_INT 24
#define UNLOCK_BUTTON_INT 23

#define STEPS_PER_REVOLUTION 512
#define STEP_DELAY_US 2000   /* 2 ms between steps */
#define DEBOUNCE_US 50000    /* 50 ms debounce for buttons */

static volatile sig_atomic_t g_running = 1;

static const int button_pins[4] = { LOCK_BUTTON, UNLOCK_BUTTON, LOCK_BUTTON_INT, UNLOCK_BUTTON_INT };
static const int motor_pins[4]   = { IN1, IN2, IN1, IN2 };

/* Full-step two-phase drive sequence (4 steps per phase) */
static const int step_sequence[4][4] = {
    {1, 0, 0, 0},
    {1, 1, 0, 0},
    {0, 1, 0, 0},
    {0, 1, 1, 0}
};

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void motor_step(int phase)
{
    for (int i = 0; i < 4; i++) {
        if (gpioWrite(motor_pins[i], step_sequence[phase][i]) < 0) {
            fprintf(stderr, "Error: gpioWrite failed on pin %d\n", motor_pins[i]);
            return;
        }
    }
}

static void motor_stop(void)
{
    for (int i = 0; i < 4; i++) {
        gpioWrite(motor_pins[i], 0);
    }
}

static void motor_rotate(int steps, int direction)
{
    for (int i = 0; i < steps; i++) {
        int phase = (direction > 0) ? (i % 4) : (3 - (i % 4));
        motor_step(phase);
        gpioDelay(STEP_DELAY_US);
    }
}

static void lock_door(void)
{
    printf("Locking door...\n");
    fflush(stdout);
    motor_stop();
    motor_rotate(STEPS_PER_REVOLUTION, 1);
    printf("Door locked.\n");
    fflush(stdout);
}

static void unlock_door(void)
{
    printf("Unlocking door...\n");
    fflush(stdout);
    motor_stop();
    motor_rotate(STEPS_PER_REVOLUTION, -1);
    printf("Door unlocked.\n");
    fflush(stdout);
}

static void cleanup(void)
{
    motor_stop();
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-up resistors */
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(button_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for button pin %d\n", button_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(button_pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for button pin %d\n", button_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Configure motor pins as outputs */
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(motor_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for motor pin %d\n", motor_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Ensure motor coils are de-energized at startup */
    motor_stop();

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Door lock control ready. Press LOCK (GPIO17) or UNLOCK (GPIO18) to rotate the door.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    bool button_pressed[4] = { false, false, false, false };

    while (g_running) {
        for (int i = 0; i < 4; i++) {
            if (gpioRead(button_pins[i]) == 0) {
                /* Button pressed: debounce and re-read */
                gpioDelay(DEBOUNCE_US);
                if (gpioRead(button_pins[i]) == 0) {
                    button_pressed[i] = true;
                }
            } else {
                button_pressed[i] = false;
            }
        }

        if (button_pressed[0] && !button_pressed[1]) {
            lock_door();
        } else if (button_pressed[2] && !button_pressed[3]) {
            unlock_door();
        } else if (button_pressed[0] && button_pressed[2]) {
            fprintf(stderr, "Error: Both LOCK and UNLOCK buttons pressed simultaneously.\n");
        }

        gpioDelay(10000); /* 10 ms idle sleep */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

