#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to an 8-bit register (big-endian on the bus) */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf))
        return -1;
    return 0;
}

/* Read a 16-bit value from an 8-bit register (big-endian on the bus) */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, buf, 2) != 2)
        return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Initialise the MPU-6050: wake up, set accel/gyro ranges, enable I2C.
 * Returns 0 on success, -1 on failure.
 */
static int init_mpu6050(int fd)
{
    /* Wake up: clear SLEEP bit (bit 6) in PWR_MGMT_1 */
    if (i2c_write_reg16(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to wake MPU-6050: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);  /* 100 ms settle */

    /* Gyro: +/- 250 deg/s (0x00) */
    if (i2c_write_reg16(fd, MPU6050_GYRO_XOUT_H, 0x00) < 0)
        return -1;
    /* Accel: +/- 2 g (0x00) */
    if (i2c_write_reg16(fd, MPU6050_ACCEL_XOUT_H, 0x00) < 0)
        return -1;

    return 0;
}

/*
 * Read 6 bytes of accel data (X, Y, Z) in one burst.
 * Returns 0 on success, -1 on failure.
 */
static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (write(fd, (uint8_t[]){MPU6050_ACCEL_XOUT_H}, 1) != 1)
        return -1;
    if (read(fd, buf, 6) != 6)
        return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/*
 * Compute pitch (Y) and roll (X) from accelerometer data.
 * Returns 0 on success, -1 on failure.
 */
static int compute_pitch_roll(int16_t ax, int16_t ay, int16_t az,
                               float *pitch, float *roll)
{
    float fx = (float)ax;
    float fy = (float)ay;
    float fz = (float)az;
    *pitch = atan2f(fy, fz) * 180.0f / (float)M_PI;
    *roll  = atan2f(-fx, fy) * 180.0f / (float)M_PI;
    return 0;
}

/*
 * Drive the servo via sysfs PWM.
 * Returns 0 on success, -1 on failure.
 */
static int set_servo_position(int position)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip2/pwm%d/duty_cycle",
             PWM_CHANNEL);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, &position, 1) != 1) {
        fprintf(stderr, "Error: write duty cycle %d: %s\n",
                position, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

/*
 * Log a measurement to the CSV file.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(float pitch, float roll, int position)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                pitch, roll, position);
    }
    fclose(fp);
    return 0;
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6050 slave address */
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error: ioctl I2C_SLAVE 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure PWM */
    if (mkfifo("/sys/class/pwm/pwmchip2/pwm0", 0666) < 0 && errno != EEXIST) {
        fprintf(stderr, "Error: mkfifo: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (set_servo_position(0) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Solar tracker started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        int16_t ax, ay, az;
        float pitch, roll;

        if (read_accel(i2c_fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Warning: accel read failed, retrying...\n");
            usleep(SAMPLE_US);
            continue;
        }

        if (compute_pitch_roll(ax, ay, az, &pitch, &roll) < 0) {
            fprintf(stderr, "Warning: pitch/roll compute failed\n");
            usleep(SAMPLE_US);
            continue;
        }

        /* Drive servo to a position that places the solar panel at the
         * calculated pitch/roll angle.  A simple linear mapping is used
         * for demonstration; a more sophisticated PID controller is
         * recommended for production. */
        int position = (int)(pitch * 1000.0f / 180.0f);
        if (set_servo_position(position) < 0) {
            fprintf(stderr, "Warning: servo set failed\n");
        }

        if (log_data(pitch, roll, position) < 0) {
            fprintf(stderr, "Warning: log failed\n");
        }

        usleep(SAMPLE_US);
    }

    /* Clean shutdown */
    set_servo_position(0);
    close(i2c_fd);
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

