#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MAX_RELAYS 4
#define PWM_FREQUENCY 100
#define FADE_DURATION_SEC 30
#define FADE_STEP_US 1000000 / FADE_DURATION_SEC
#define SLEEP_INTERVAL_SEC 1

#define RELAY_PIN_1 4
#define RELAY_PIN_2 17
#define RELAY_PIN_3 27
#define RELAY_PIN_4 22

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on;
} ScheduleEntry;

static const int relay_pins[MAX_RELAYS] = {RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int parse_schedule(const char *filename, ScheduleEntry *schedule, int max_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open schedule file '%s': %m\n", filename);
        return -1;
    }

    char line[256];
    int entry_count = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (entry_count >= max_entries) {
            fprintf(stderr, "Warning: schedule file exceeds %d entries, skipping extra lines\n", max_entries);
            break;
        }

        char *start = line;
        while (*start && (*start == ':' || *start == ' ' || *start == '\t')) start++;

        char *end = start + strlen(start) - 1;
        while (end > start && (*end == ':' || *end == ' ' || *end == '\t')) end--;
        end--;

        char *colon = strchr(start, ':');
        if (!colon) {
            fprintf(stderr, "Error: invalid schedule entry format: '%s'\n", line);
            fclose(fp);
            return -1;
        }

        char *time_str = colon + 1;
        char *relay_str = end;

        char *tok;
        tok = strtok(time_str, ",");
        if (!tok) {
            fprintf(stderr, "Error: missing time component in entry\n");
            fclose(fp);
            return -1;
        }
        char *time_str_val = tok;

        tok = strtok(NULL, ",");
        if (!tok) {
            fprintf(stderr, "Error: missing relay number in entry\n");
            fclose(fp);
            return -1;
        }
        char *relay_str_val = tok;

        tok = strtok(NULL, ",");
        if (!tok) {
            fprintf(stderr, "Error: missing on/off flag in entry\n");
            fclose(fp);
            return -1;
        }
        char *flag_str = tok;

        if (sscanf(flag_str, "%d", &schedule[entry_count].on) != 1) {
            fprintf(stderr, "Error: invalid on/off flag '%s'\n", flag_str);
            fclose(fp);
            return -1;
        }

        if (sscanf(relay_str_val, "%d", &schedule[entry_count].relay_number) != 1) {
            fprintf(stderr, "Error: invalid relay number '%s'\n", relay_str_val);
            fclose(fp);
            return -1;
        }

        if (sscanf(time_str_val, "%d:%d:%d", &schedule[entry_count].hour, &schedule[entry_count].minute, &schedule[entry_count].second) != 3) {
            fprintf(stderr, "Error: invalid time '%s'\n", time_str_val);
            fclose(fp);
            return -1;
        }

        if (schedule[entry_count].hour < 0 || schedule[entry_count].hour > 23 ||
            schedule[entry_count].minute < 0 || schedule[entry_count].minute > 59 ||
            schedule[entry_count].second < 0 || schedule[entry_count].second > 59) {
            fprintf(stderr, "Error: invalid time '%s'\n", time_str_val);
            fclose(fp);
            return -1;
        }

        entry_count++;
    }

    fclose(fp);
    return entry_count;
}

static void fade_lamp(int relay_pin, int duration_sec) {
    if (duration_sec <= 0) return;

    int duty_cycle = 0;
    int step = 0;
    int elapsed = 0;

    while (program_running && elapsed < duration_sec) {
        duty_cycle = (duty_cycle + step) % 101;
        if (gpioPWM(relay_pin, duty_cycle) < 0) {
            fprintf(stderr, "Error: gpioPWM failed for relay %d\n", relay_pin);
            return;
        }
        gpioDelay(FADE_STEP_US);
        step = (step + 1) % 101;
        elapsed += FADE_STEP_US / 1000000;
    }

    gpioPWM(relay_pin, 0);
}

static void control_lamp(int relay_pin, int on) {
    if (gpioWrite(relay_pin, on ? 1 : 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed for relay %d\n", relay_pin);
        return;
    }
}

static void update_lamps(const ScheduleEntry *schedule, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        int current_time = time(NULL);
        if (current_time == (time_t)-1) {
            fprintf(stderr, "Error: time() failed\n");
            continue;
        }

        int target_time = schedule[i].hour * 3600 + schedule[i].minute * 60 + schedule[i].second;
        int target_relay = schedule[i].relay_number;
        int target_state = schedule[i].on ? 1 : 0;

        if (current_time >= target_time) {
            if (current_time < target_time) {
                current_time = target_time;
            }
            if (current_time == target_time && target_relay != 0) {
                control_lamp(relay_pins[target_relay - 1], target_state);
            }
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: cannot install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int num_relays = MAX_RELAYS;
    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for relay %d\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(relay_pins[i], 0) < 0) {
            fprintf(stderr, "Error: gpioPWM initial set failed for relay %d\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    ScheduleEntry schedule[100];
    int num_schedule_entries = parse_schedule("lighting_schedule.txt", schedule, num_relays);
    if (num_schedule_entries < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        update_lamps(schedule, num_schedule_entries);
        sleep(SLEEP_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < num_relays; i++) {
        gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
    printf("GPIO resources released. Exiting.\n");
    return EXIT_SUCCESS;
}

