/*
 * Theremin for Raspberry Pi Zero W
 * Sensor : HC-SR04 ultrasonic distance sensor
 * Trigger: GPIO23 (BCM)
 * Echo   : GPIO24 (BCM)
 * Buzzer : GPIO18 (BCM) PWM
 *
 * Build  : gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run    : sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* 30 ms max echo wait */
#define MIN_FREQ_HZ      200
#define MAX_FREQ_HZ      2000
#define LOOP_DELAY_US    50000   /* 50 Hz */
#define MIN_MEAS_GAP_US  60000   /* 60 ms between measurements */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read distance (cm) from an HC-SR04.
 * Returns >= 0 on success, -1.0 on timeout, -2.0 on sensor-absent.
 */
static float read_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* --- Issue 10 µs trigger pulse --- */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* --- Wait for echo rising edge --- */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo pin stuck low (sensor absent?)\n");
            return -2.0f;
        }
    }
    start_tick = gpioTick();

    /* --- Wait for echo falling edge --- */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo pin stuck high (timeout)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff / 2.0f / 1000000.0f;   /* µs -> cm */
    return distance;
}

/*
 * Map distance (cm) to PWM frequency (Hz).
 * Clamps to [MIN_FREQ, MAX_FREQ].
 */
static int distance_to_frequency(float distance)
{
    if (distance < 0.0f)
        return MIN_FREQ_HZ;
    if (distance > 100.0f)
        return MAX_FREQ_HZ;
    return MIN_FREQ_HZ + (int)(distance / 100.0f * (MAX_FREQ_HZ - MIN_FREQ_HZ));
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO modes --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure trigger starts low --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);  /* 100 ms settle */

    /* --- Install SIGINT handler --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    uint32_t last_measure_tick = 0;

    while (g_running) {
        uint32_t now = gpioTick();

        /* --- Enforce minimum 60 ms measurement gap --- */
        if ((int32_t)(now - last_measure_tick) < 0) {
            gpioDelay(MIN_MEAS_GAP_US);
            last_measure_tick = now;
        }

        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: Distance read failed (sensor absent or timeout)\n");
        } else {
            int frequency = distance_to_frequency(distance);
            if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
                fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency);
            }
            if (gpioPWM(BUZZER_PIN, 128) < 0) {  /* 50 % duty cycle */
                fprintf(stderr, "Error: gpioPWM(%d) failed\n", 128);
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Cleanup --- */
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

