/*
 * RGB common-anode LED with hardware PWM on Raspberry Pi 3 Model B+
 *
 * Wiring (BCM numbering):
 *   Red   -> GPIO17 (hardware PWM0)
 *   Green -> GPIO22 (hardware PWM1)
 *   Blue  -> GPIO27 (hardware PWM2)
 *
 * Common anode: all three LED cathodes tied together and driven low.
 * PWM frequency: 1 kHz (hardware PWM0-2, 250 Hz base, 4 × 250 = 1 kHz).
 *
 * Behavior:
 *   A smooth color transition is generated from (0,0,0) to (255,255,255)
 *   over a 10-second sine wave.  The sine amplitude is scaled by a
 *   proximity factor (0.0 → 0.0, 1.0 → 1.0) so that the LED appears
 *   brighter when the simulated object is closer.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rgb_pwm rgb_pwm.c -lpigpio -lrt
 *   (run as root, or with appropriate gpio permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_FREQ   1000          /* 1 kHz hardware PWM frequency */
#define PWM_RANGE  255           /* 8-bit resolution */
#define PWM_DUTY   128           /* 50% duty cycle */

#define SAMPLE_US 100000         /* 100 ms per iteration */
#define TOTAL_US  10000000       /* 10 s total */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* PWM helpers                                                         */
/* ------------------------------------------------------------------ */
static int safe_pwm_start(unsigned pin, unsigned freq, unsigned range)
{
    if (gpioSetPWMfrequency(pin, freq) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%u, %u) failed\n", pin, freq);
        return -1;
    }
    if (gpioSetPWMrange(pin, range) < 0) {
        fprintf(stderr, "gpioSetPWMrange(%u, %u) failed\n", pin, range);
        return -1;
    }
    if (gpioPWM(pin, 0) < 0) {
        fprintf(stderr, "gpioPWM(%u, 0) failed\n", pin);
        return -1;
    }
    return 0;
}

static int safe_pwm_stop(unsigned pin)
{
    if (gpioPWM(pin, 0) < 0) {
        fprintf(stderr, "gpioPWM(%u, 0) failed\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Color helpers                                                         */
/* ------------------------------------------------------------------ */
typedef struct {
    unsigned r;
    unsigned g;
    unsigned b;
} Color;

static Color smooth_sine(float t, float amplitude, float phase)
{
    float s = sinf(2.0f * M_PI * t);
    return (Color){
        (unsigned)(amplitude * s + 128.0f),
        (unsigned)(amplitude * s * s - 1.0f) * 128.0f,
        (unsigned)(amplitude * s * s * s - 1.0f) * 128.0f
    };
}

static Color proximity_to_color(float proximity)
{
    if (proximity < 0.0f) proximity = 0.0f;
    if (proximity > 1.0f) proximity = 1.0f;

    float scaled = proximity * 1.0f;
    Color c = (Color){0, 0, 0};
    c.r = (unsigned)(255.0f * scaled);
    c.g = (unsigned)(255.0f * scaled);
    c.b = (unsigned)(255.0f * scaled);
    return c;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins as outputs --- */
    if (safe_set_mode(RED_PIN, PI_OUTPUT)  < 0 ||
        safe_set_mode(GREEN_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(BLUE_PIN, PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Start hardware PWM on all three pins --- */
    if (safe_pwm_start(RED_PIN, PWM_FREQ, PWM_RANGE)  < 0 ||
        safe_pwm_start(GREEN_PIN, PWM_FREQ, PWM_RANGE) < 0 ||
        safe_pwm_start(BLUE_PIN, PWM_FREQ, PWM_RANGE) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop: smooth color transition --- */
    float t = 0.0f;
    Color target;
    int   iteration = 0;

    while (g_running && t < (float)TOTAL_US) {
        float amplitude = 1.0f;
        float phase     = 0.0f;

        /* Simulated proximity: sine wave over 10 s */
        amplitude = 1.0f - (t / (float)TOTAL_US) * 1.0f;
        phase     = (t / (float)TOTAL_US) * 2.0f * M_PI;

        target = proximity_to_color(amplitude);

        /* --- Red --- */
        if (safe_pwm_write(RED_PIN, target.r) < 0) {
            gpioPWM(RED_PIN, 0);
            safe_pwm_stop(RED_PIN);
            break;
        }

        /* --- Green --- */
        if (safe_pwm_write(GREEN_PIN, target.g) < 0) {
            gpioPWM(GREEN_PIN, 0);
            safe_pwm_stop(GREEN_PIN);
            break;
        }

        /* --- Blue --- */
        if (safe_pwm_write(BLUE_PIN, target.b) < 0) {
            gpioPWM(BLUE_PIN, 0);
            safe_pwm_stop(BLUE_PIN);
            break;
        }

        t += SAMPLE_US;
        iteration++;
    }

    /* --- Clean shutdown: turn LED off and release PWM --- */
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    safe_pwm_stop(RED_PIN);
    safe_pwm_stop(GREEN_PIN);
    safe_pwm_stop(BLUE_PIN);
    gpioTerminate();

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

