/*
 * Raspberry Pi 4 Model B - Doorbell with Button and Piezo Buzzer
 *
 * Hardware:
 *   - Button: GPIO17 (BCM), internal pull-up, active-low
 *   - Piezo buzzer: GPIO18 (BCM), hardware PWM0
 *
 * Behavior:
 *   - Press button (active-low) to play a melody.
 *   - Press again to stop the melody.
 *   - On a third press, stop the melody and exit cleanly.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o doorbell doorbell.c -lpigpio -lrt
 *   sudo ./doorbell
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18

#define MELODY_SIZE 8
#define DUTY_CYCLE_PERCENT 50
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */
#define LOOP_DELAY_US 10000      /* 10 ms */

/* Musical melody (8 tones, 50% duty cycle) */
static const int melody[MELODY_SIZE] = {
    0x00000000, /* tone 0: 0 ms */
    0x00000001, /* tone 1: 1 ms */
    0x00000002, /* tone 2: 2 ms */
    0x00000004, /* tone 3: 4 ms */
    0x00000008, /* tone 4: 8 ms */
    0x00000010, /* tone 5: 10 ms */
    0x00000020, /* tone 6: 20 ms */
    0x00000040  /* tone 7: 40 ms */
};

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t melody_playing = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Play a melody on the buzzer                                          */
/* ------------------------------------------------------------------ */
static int play_melody(void)
{
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM(0) failed\n");
        return -1;
    }

    for (int i = 0; i < MELODY_SIZE && running; i++) {
        if (gpioPWM(BUZZER_PIN, melody[i]) < 0) {
            fprintf(stderr, "Error: gpioPWM(%d) failed\n", i);
            return -1;
        }
        gpioDelay(DUTY_CYCLE_PERCENT * 1000); /* 50% of 1 ms = 500 us */
    }

    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM(0) failed\n");
        return -1;
    }

    melody_playing = 1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* ISR: non-blocking button press detection                            */
/* ------------------------------------------------------------------ */
static void button_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 0) {
        /* Active-low button pressed */
        if (melody_playing) {
            /* Second press: stop melody */
            if (play_melody() < 0) {
                fprintf(stderr, "Error: melody stop failed\n");
            }
            melody_playing = 0;
        } else {
            /* First press: start melody */
            if (play_melody() < 0) {
                fprintf(stderr, "Error: melody start failed\n");
            } else {
                melody_playing = 1;
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pin as input with pull-up */
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure buzzer pin as output */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure buzzer is off at start */
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: initial gpioPWM(BUZZER_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR with debounce */
    if (gpioSetISRFuncEx(BUTTON_PIN, EITHER_EDGE, DEBOUNCE_DELAY_US,
                         button_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed\n");
        gpioPWM(BUZZER_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Doorbell ready. Press the button (GPIO17) to play. Ctrl+C to exit.\n");

    /* Main loop: sleep until signal received */
    while (running) {
        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup */
    gpioSetISRFuncEx(BUTTON_PIN, EITHER_EDGE, 0, NULL, NULL); /* unregister ISR */
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

