#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/file.h>
#include <pigpio.h>

#define GPIO_PIN          17
#define WINDOW_SIZE       5
#define DEFAULT_POLL_MS   1000
#define LOG_FILE          "vibration_events.log"
#define POLL_TIMEOUT_MS   DEFAULT_POLL_MS

static volatile sig_atomic_t g_running = 1;
static int  g_log_fd   = -1;
static int  g_poll_ms  = DEFAULT_POLL_MS;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(int value)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *tm = localtime_r(&now, &tm_buf);
    if (tm == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    char entry[128];
    int n = snprintf(entry, sizeof(entry), "%s  GPIO%d  %d\n",
                     ts, GPIO_PIN, value);
    if (n < 0 || (size_t)n >= sizeof(entry)) {
        fprintf(stderr, "Entry too long\n");
        return -1;
    }

    if (fsync(g_log_fd) == -1) {
        fprintf(stderr, "fsync() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fwrite(entry, 1, (size_t)n, g_log_fd) == -1) {
        fprintf(stderr, "fwrite() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sliding-window earthquake detection                                 */
/* ------------------------------------------------------------------ */
static int is_earthquake(const int *window, int size, int count)
{
    if (count < WINDOW_SIZE)
        return 0;

    for (int i = 0; i < size; i++)
        if (window[i] == 1)
            return 1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* pigpio edge event callback (rising + falling)                       */
/* ------------------------------------------------------------------ */
static void edge_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;

    if (level == 1) {
        /* Rising edge: add to window */
        if (window_count(window, size) < size) {
            window[window_index(window, size)] = level;
            window_index(window, size) = (window_index(window, size) + 1) % size;
            if (window_count(window, size) < size)
                return;
        }
    } else if (level == 0) {
        /* Falling edge: check window */
        if (window_count(window, size) >= WINDOW_SIZE) {
            if (is_earthquake(window, size, window_count(window, size))) {
                printf("EARTHQUAKE ALERT: %d events in %d ms\n",
                       window_count(window, size), POLL_TIMEOUT_MS);
                fflush(stdout);
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "t:p:")) != -1) {
        switch (opt) {
        case 't':
            g_poll_ms = atoi(optarg);
            if (g_poll_ms <= 0) {
                fprintf(stderr, "Invalid poll timeout: %s\n", optarg);
                return EXIT_FAILURE;
            }
            break;
        case 'p':
            LOG_FILE = optarg;
            break;
        default:
            fprintf(stderr, "Usage: %s [-t poll_ms] [-p log_file]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Enable internal pull-down so the line is defined when the
     * sensor is disconnected (SW-420 DO is open-collector).
     */
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (g_log_fd == -1) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        close(g_log_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        close(g_log_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register edge callbacks (rising + falling) ---- */
    if (gpioSetAlertFuncEx(GPIO_PIN, edge_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(%d) failed\n", GPIO_PIN);
        close(g_log_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring SW-420 on GPIO%d (poll %d ms). Press Ctrl+C to exit.\n",
           GPIO_PIN, POLL_TIMEOUT_MS);
    fflush(stdout);

    /* ---- Main loop ---- */
    while (g_running) {
        sleep(1);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);   /* unregister callback */
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF);    /* release pull-down */
    if (g_log_fd != -1) {
        if (close(g_log_fd) == -1)
            fprintf(stderr, "close(log) failed: %s\n", strerror(errno));
        g_log_fd = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

