#define LSM303DLHC_CTRL_REG4 0x23
#define LSM303DLHC_CTRL_REG5 0x24
#define LSM303DLHC_CTRL_REG6 0x25
#define LSM303DLHC_OUT_X_L 0x28
#define LSM303DLHC_OUT_X_H 0x29
#define LSM303DLHC_OUT_Y_L 0x2A
#define LSM303DLHC_OUT_Y_H 0x2B
#define LSM303DLHC_OUT_Z_L 0x2C
#define LSM303DLHC_OUT_Z_H 0x2D

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "mag_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_l, uint8_t reg_h, int16_t *value) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_l, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg_h, &hi) < 0) return -1;
    *value = (int16_t)((hi << 8) | lo);
    return 0;
}

static int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LSM303DLHC_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", LSM303DLHC_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    if (i2c_write_reg8(fd, LSM303DLHC_CTRL_REG1, 0x00) < 0) {
        close(fd);
        return -1;
    }
    if (i2c_write_reg8(fd, LSM303DLHC_CTRL_REG4, 0x00) < 0) {
        close(fd);
        return -1;
    }
    if (i2c_write_reg8(fd, LSM303DLHC_CTRL_REG5, 0x00) < 0) {
        close(fd);
        return -1;
    }
    if (i2c_write_reg8(fd, LSM303DLHC_CTRL_REG6, 0x00) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    if (i2c_read_reg16(fd, LSM303DLHC_OUT_X_L, LSM303DLHC_OUT_X_H, x) < 0) return -1;
    if (i2c_read_reg16(fd, LSM303DLHC_OUT_Y_L, LSM303DLHC_OUT_Y_H, y) < 0) return -1;
    if (i2c_read_reg16(fd, LSM303DLHC_OUT_Z_L, LSM303DLHC_OUT_Z_H, z) < 0) return -1;
    return 0;
}

static void calibrate_magnetometer(int16_t *x, int16_t *y, int16_t *z, int offset_x, int offset_y, int offset_z) {
    *x -= offset_x;
    *y -= offset_y;
    *z -= offset_z;
}

static int calculate_heading(int16_t x, int16_t y, int16_t z, float *heading) {
    float h = atan2f((float)y, (float)z) * 180.0f / M_PI;
    if (h < 0.0f) h += 360.0f;
    if (h > 360.0f) h -= 360.0f;
    *heading = h;
    return 0;
}

static const char *get_compass_direction(float heading) {
    if (heading >= 337.5f && heading <= 45.0f) return "N";
    if (heading >= 45.0f && heading <= 135.0f) return "NE";
    if (heading >= 135.0f && heading <= 225.0f) return "E";
    if (heading >= 225.0f && heading <= 315.0f) return "SE";
    if (heading >= 315.0f && heading <= 45.0f) return "SW";
    if (heading >= 45.0f && heading <= 135.0f) return "NW";
    if (heading >= 135.0f && heading <= 225.0f) return "W";
