/*
 * Raspberry Pi 4 Model B – TTP223 capacitive touch sensor → relay toggle
 *
 * Wiring
 *   TTP223 VCC  → 3V3 (pin 1)
 *   TTP223 GND  → GND (pin 6)
 *   TTP223 SIG  → GPIO4  (pin 7, BCM 4)  [pull-down enabled]
 *   Relay IN    → GPIO17 (pin 11)
 *   Relay VCC   → 5V (pin 2 or 4)
 *   Relay GND   → GND (pin 6)
 *
 * Build
 *   gcc -O2 -Wall -Wextra -o relay_touch relay_touch.c -lpigpio -lrt
 *   (run as root, or ensure pigpio daemon is running)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN      4
#define RELAY_PIN      17
#define DEBOUNCE_MS    200
#define LOG_FILE       "relay_log.json"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_state_change(const char *state)
{
    FILE *fp = fopen(LOG_FILE, "r");
    int   was_off = 0;

    if (fp == NULL) {
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            perror("fopen(LOG_FILE)");
            return -1;
        }
        fprintf(fp, "[]");
        fclose(fp);
    } else {
        /* Read current entry; if empty, record "OFF" */
        fseek(fp, 0, SEEK_END);
        long sz = ftell(fp);
        if (sz < 0) {
            perror("ftell");
            fclose(fp);
            return -1;
        }
        if (sz == 0) {
            was_off = 1;
        }
        fclose(fp);
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(LOG_FILE, 'a')");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "  {\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n",
            ts, was_off ? "OFF" : "ON");
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                           */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_PIN) failed\n");
        return -1;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH_PIN) failed\n");
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN) failed\n");
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* ISR: toggle relay on touch, enforce debounce                      */
/* ------------------------------------------------------------------ */
static void touch_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level != 1) {
        return; /* only act on rising edge */
    }

    static uint32_t last_tick = 0;
    static int      last_state = 0;

    uint32_t now = gpioTick();
    uint32_t elapsed = now - last_tick;

    if (elapsed < DEBOUNCE_MS * 1000) {
        return; /* within debounce window – ignore */
    }

    last_tick = now;

    /* Toggle relay */
    if (gpioWrite(RELAY_PIN, !last_state) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, %d) failed\n", last_state);
        return;
    }
    last_state = !last_state;

    /* Log state change */
    if (log_state_change(last_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Failed to log state change\n");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_sigint_handler() < 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, touch_isr, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control started. Touch GPIO%d to toggle relay on GPIO%d.\n",
           TOUCH_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        sleep(1);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    log_state_change(0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

