/*
 * Automated plant watering system for Raspberry Pi Zero W.
 *
 * Servos:
 *   Valve  : GPIO17 (physical pin 11, BCM)
 *   Nozzle  : GPIO18 (physical pin 12, BCM)
 *
 * Library: the driver library (e.g. pigpio) provides the following API
 *   call signature:
 *       int servo_write(int gpio, int pulse_width_us);
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o watering watering.c -lthe_driver -lrt
 *
 * Run:
 *   sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <stdbool.h>
#include <the_driver.h>

#define VALVE_PIN    17
#define NOZZLE_PIN   18
#define MOISTURE_LOW  50
#define MOISTURE_CYCLE_1 20
#define MOISTURE_CYCLE_2 40
#define MOISTURE_CYCLE_3 60
#define MOISTURE_CYCLE_4 80
#define MOISTURE_CYCLE_5 100
#define NOZZLE_ANGLE_0  0
#define NOZZLE_ANGLE_45 45
#define NOZZLE_ANGLE_90  90
#define NOZZLE_ANGLE_135 135
#define NOZZLE_ANGLE_180 180
#define NOZZLE_PULSE_0   500
#define NOZZLE_PULSE_45  1000
#define NOZZLE_PULSE_90  1500
#define NOZZLE_PULSE_135 2000
#define NOZZLE_PULSE_180 2500
#define NOZZLE_SWEEP_DELAY_S 2
#define SPRAY_DURATION_S 5
#define VALVE_OPEN_PULSE_US 1500
#define VALVE_CLOSE_PULSE_US 500
#define MAX_RETRIES 3
#define RETRY_DELAY_US 100000
#define LOOP_DELAY_US 1000000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts;
    ts.tv_sec  = us / 1000000U;
    ts.tv_nsec = (long)(us % 1000000U) * 1000L;
    nanosleep(&ts, NULL);
}

static int set_servo_angle(int gpio, int angle)
{
    int pulse_width;
    switch (angle) {
        case 0:   pulse_width = NOZZLE_PULSE_0;   break;
        case 45:  pulse_width = NOZZLE_PULSE_45;  break;
        case 90:  pulse_width = NOZZLE_PULSE_90;  break;
        case 135: pulse_width = NOZZLE_PULSE_135; break;
        case 180: pulse_width = NOZZLE_PULSE_180; break;
        default: return -1;
    }
    return servo_write(gpio, pulse_width);
}

static int water_plant(int moisture_level)
{
    if (moisture_level < MOISTURE_LOW) {
        if (servo_write(VALVE_PIN, VALVE_OPEN_PULSE_US) != 0) {
            fprintf(stderr, "Error: failed to open valve (GPIO%d).\n", VALVE_PIN);
            return -1;
        }
        sleep_us(100000);

        for (int angle = NOZZLE_ANGLE_0; angle <= NOZZLE_ANGLE_180 && g_running; angle++) {
            if (set_servo_angle(NOZZLE_PIN, angle) != 0) {
                fprintf(stderr, "Error: failed to set nozzle angle %d.\n", angle);
                return -1;
            }
            sleep_us(NOZZLE_SWEEP_DELAY_S * 1000000U);
        }

        sleep_us(SPRAY_DURATION_S * 1000000U);

        if (servo_write(NOZZLE_PIN, NOZZLE_PULSE_0) != 0) {
            fprintf(stderr, "Error: failed to close nozzle (GPIO%d).\n", NOZZLE_PIN);
            return -1;
        }
        sleep_us(100000);

        if (!g_running) return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (the_driver_init() < 0) {
        fprintf(stderr, "Error: the_driver_init() failed.\n");
        return EXIT_FAILURE;
    }

    if (the_driver_set_mode(VALVE_PIN, THE_DRIVER_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set mode for valve pin (GPIO%d).\n", VALVE_PIN);
        the_driver_cleanup();
        return EXIT_FAILURE;
    }
    if (the_driver_set_mode(NOZZLE_PIN, THE_DRIVER_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set mode for nozzle pin (GPIO%d).\n", NOZZLE_PIN);
        the_driver_cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int moisture_level = MOISTURE_CYCLE_1;
        for (int i = 0; i < 5 && g_running; i++) {
            sleep_us(LOOP_DELAY_US);
            if (!g_running) break;
            moisture_level = (moisture_level + 10) % 10;
        }

        if (moisture_level < MOISTURE_LOW) {
            if (water_plant(moisture_level) != 0) {
                fprintf(stderr, "Critical: watering cycle aborted due to unrecoverable error.\n");
            }
        }

        for (int i = 0; i < 5 && g_running; i++) {
            sleep_us(LOOP_DELAY_US);
        }
    }

    /* Graceful shutdown: stop servos and release driver */
    the_driver_servo_stop(VALVE_PIN);
    the_driver_servo_stop(NOZZLE_PIN);
    the_driver_cleanup();
    return EXIT_SUCCESS;
}

