/*
 * MPU-6050 Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (BCM)
 *   MPU-6050 SCL -> GPIO3 (BCM)
 *   MPU-6050 VCC -> 3.3V
 *   MPU-6050 GND -> GND
 *
 * I2C bus: /dev/i2c-1
 *
 * Build: gcc -O2 -Wall -o gyro_logger gyro_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_HZ      10
#define SAMPLE_US      (1000000 / SAMPLE_HZ)

/* MPU-6050 registers */
#define REG_SMPLRT_DIV  0x19
#define REG_CONFIG      0x1A
#define REG_GYRO_XOUT_H 0x43
#define REG_GYRO_YOUT_H 0x45
#define REG_GYRO_ZOUT_H 0x47

/* Sensitivity: 131 LSB/°/s at ±250 °/s */
#define GYRO_SCALE      131.0f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian register pair */
static int i2c_read_reg16(int fd, uint8_t reg_high, uint16_t *out)
{
    uint8_t buf[2];
