#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000
#define DEBOUNCE_DELAY_US 50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_gpio_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_gpio_read(unsigned gpio) {
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", gpio);
    }
    return v;
}

static int deenergize_all(void) {
    if (safe_gpio_write(IN1, 0) < 0) return -1;
    if (safe_gpio_write(IN2, 0) < 0) return -1;
    if (safe_gpio_write(IN3, 0) < 0) return -1;
    if (safe_gpio_write(IN4, 0) < 0) return -1;
    return 0;
}

static int step_motor(int direction) {
    if (direction != 1 && direction != -1) {
        fprintf(stderr, "Error: invalid step direction %d\n", direction);
        return -1;
    }

    for (int i = 0; i < STEPS_PER_ROTATION; i++) {
        if (!g_running) return -1;

        int coil_states[4] = {0, 0, 0, 0};
        coil_states[0] = direction;

        if (safe_gpio_write(IN1, coil_states[0]) < 0) return -1;
        if (safe_gpio_write(IN2, coil_states[1]) < 0) return -1;
        if (safe_gpio_write(IN3, coil_states[2]) < 0) return -1;
        if (safe_gpio_write(IN4, coil_states[3]) < 0) return -1;

        gpioDelay(STEP_DELAY_US);
    }

    if (deenergize_all() < 0) return -1;
    return 0;
}

static int lock_door(void) {
    printf("Locking door...\n");
    fflush(stdout);
    if (step_motor(1) < 0) return -1;
    if (deenergize_all() < 0) return -1;
    return 0;
}

static int unlock_door(void) {
    printf("Unlocking door...\n");
    fflush(stdout);
    if (step_motor(-1) < 0) return -1;
    if (deenergize_all() < 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for IN pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (deenergize_all() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock system started. Press LOCK (GPIO24) or UNLOCK (GPIO23) to rotate the door.\n");
    fflush(stdout);

    while (g_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            if (lock_door() == 0) {
                printf("Door locked.\n");
                fflush(stdout);
            } else {
                fprintf(stderr, "Error: failed to lock door\n");
            }
        } else if (gpioRead(UNLOCK_BUTTON) == 0) {
            if (unlock_door() == 0) {
                printf("Door unlocked.\n");
                fflush(stdout);
            } else {
                fprintf(stderr, "Error: failed to unlock door\n");
            }
        }
        gpioDelay(DEBOUNCE_DELAY_US);
    }

    printf("\nShutting down...\n");
    deenergize_all();
    gpioTerminate();
    return EXIT_SUCCESS;
}

