/*
 * VL53L1X distance reader with relay control on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Relay IN    -> GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_relay vl53l1x_relay.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L1X constants (verified against ST datasheet) ---- */
#define VL53L1X_ADDR        0x80
#define VL53L1X_REG_SOFT_RESET      0x0003
#define VL53L1X_REG_SYSTEM_MODE    0x0004
#define VL53L1X_REG_SYSTEM_THRESH  0x0005
#define VL53L1X_REG_SYSTEM_RANGE   0x0006
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_RESULT_TIMING_ERROR 0x0089
#define VL53L1X_REG_RESULT_SIGNAL_DETECTED 0x008A
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x008B
#define VL53L1X_REG_RESULT_FIFO_WR_PTR 0x0088
#define VL53L1X_REG_RESULT_FIFO_RD_PTR 0x008A

#define VL53L1X_SOFT_RESET_VAL 0x00
#define VL53L1X_SYSTEM_MODE_CONTINUOUS 0x01
#define VL53L1X_RANGE_STATUS_READY 0x01
#define VL53L1X_RANGE_STATUS_TIMEOUT 0x02
#define VL53L1X_RANGE_STATUS_SIGNAL_DETECTED 0x04
#define VL53L1X_RANGE_STATUS_INTER_RANGE_OBJ 0x08
#define VL53L1X_RANGE_STATUS_OBJ_DETECTED 0x10
#define VL53L1X_RANGE_STATUS_RANGE_ERROR 0x20

#define I2C_BUS              1
#define RELAY_GPIO           18
#define DISTANCE_THRESHOLD   50   /* cm */
#define POLL_DELAY_US        100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint16_t reg, uint8_t val)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)val;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *out)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)out, 1) != 1)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                        */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t id;
    if (i2c_read_reg8(handle, 0x010F, &id) < 0) {
        fprintf(stderr, "Error: failed to read device ID (sensor absent or bus error)\n");
        return -1;
    }
    if (id != 0xEA) {
        fprintf(stderr, "Error: unexpected device ID 0x%02X (expected 0xEA)\n", id);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg8(handle, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_VAL) < 0) {
        fprintf(stderr, "Error: soft reset write failed\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms */

    /* Set continuous mode */
    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_MODE, VL53L1X_SYSTEM_MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Error: failed to set continuous mode\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms */

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status;
    uint8_t dist_raw;
    uint8_t int_status;

    /* Check if data is ready */
    if (i2c_read_reg8(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) {
        fprintf(stderr, "Error: failed to read range status\n");
        return -1;
    }
    if ((status & VL53L1X_RANGE_STATUS_TIMEOUT) != 0) {
        fprintf(stderr, "Warning: range timeout (status=0x%02X)\n", status);
        return -1;
    }
    if ((status & VL53L1X_RANGE_STATUS_SIGNAL_DETECTED) != 0) {
        /* Signal detected — read distance */
        if (i2c_read_reg8(handle, VL53L1X_REG_RESULT_DISTANCE, &dist_raw) < 0) {
            fprintf(stderr, "Error: failed to read distance\n");
            return -1;
        }
        /* Clear signal-detected bit so next measurement can be ready */
        if (i2c_write_reg8(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, 0x01) < 0) {
            fprintf(stderr, "Warning: failed to clear interrupt\n");
        }
        *distance_mm = dist_raw;
        return 0;
    }

    /* Check for interrupt status */
    if (i2c_read_reg8(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &int_status) < 0) {
        fprintf(stderr, "Error: failed to read interrupt status\n");
        return -1;
    }
    if (int_status & VL53L1X_RANGE_STATUS_INTER_RANGE_OBJ) {
        /* Object detected — read distance */
        if (i2c_read_reg8(handle, VL53L1X_REG_RESULT_DISTANCE, &dist_raw) < 0) {
            fprintf(stderr, "Error: failed to read distance\n");
            return -1;
        }
        /* Clear interrupt */
        if (i2c_write_reg8(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, 0x01) < 0) {
            fprintf(stderr, "Warning: failed to clear interrupt\n");
        }
        *distance_mm = dist_raw;
        return 0;
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                         */
/* ------------------------------------------------------------------ */
static int relay_set(int gpio, int state)
{
    if (gpioWrite(gpio, state) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", gpio, state);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t distance_mm;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VL53L1X default address */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay pin */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance reader started.  Threshold = %d cm.  Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD);

    while (g_running) {
        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) < 0) {
            fprintf(stderr, "Warning: distance read failed, retrying next cycle\n");
        } else {
            uint16_t distance_cm = distance_mm / 10;
            printf("Distance: %u cm\n", distance_cm);

            int relay_state = (distance_cm <= DISTANCE_THRESHOLD) ? 1 : 0;
            if (relay_set(RELAY_GPIO, relay_state) < 0) {
                fprintf(stderr, "Warning: relay write failed\n");
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

