           DISTANCE_THRESHOLD);

    while (g_running) {
        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) < 0) {
            fprintf(stderr, "Warning: distance read failed, retrying next cycle\n");
        } else {
            uint16_t distance_cm = distance_mm / 10;
            printf("Distance: %u cm\n", distance_cm);

            int relay_state = (distance_cm <= DISTANCE_THRESHOLD) ? 1 : 0;
            if (relay_set(RELAY_GPIO, relay_state) < 0) {
                fprintf(stderr, "Warning: relay write failed\n");
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

