/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 * Uses the standard Linux I2C character-device interface (/dev/i2c-1).
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (BCM pin 3)
 *   MPU-6050 SCL -> GPIO3 (BCM pin 5)
 *   MPU-6050 VCC -> 3.3V
 *   MPU-6050 GND -> GND
 *
 * Build:  gcc -O2 -Wall -o mpu6050_gyro mpu6050_gyro.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 register addresses ---- */
#define MPU6050_ADDR        0x68
#define PWR_MGMT_1          0x6B
#define GYRO_XOUT_H         0x43
#define GYRO_YOUT_H         0x45
#define GYRO_ZOUT_H         0x47

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs.     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers using the Linux I2C character-device interface.        */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X): write failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    /* Send the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read one byte back */
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — close the I2C device and close any open file descriptors. */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open the I2C bus ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire the MPU-6050 device ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify the device is present by reading the device ID ---- */
    uint8_t id;
    if (i2c_read_reg8(g_i2c_fd, 0x75, &id) < 0) {
        fprintf(stderr, "MPU-6050 not detected at 0x%02X\n", MPU6050_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }
    if (id != 0x68) {
        fprintf(stderr, "MPU-6050 ID mismatch: got 0x%02X, expected 0x68\n", id);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Wake up the MPU-6050 (clear sleep bit) ---- */
    if (i2c_write_reg8(g_i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(100000);  /* allow oscillator to stabilize */

    /* ---- Main acquisition loop ---- */
    while (g_running) {
        uint8_t raw[6];
        int16_t gyro_x, gyro_y, gyro_z;

        /* Read all six gyroscope axes in one burst */
        if (i2c_read_reg8(g_i2c_fd, GYRO_XOUT_H, &raw[0]) < 0) {
            fprintf(stderr, "Failed to read gyro data\n");
            break;
        }
        if (i2c_read_reg8(g_i2c_fd, GYRO_YOUT_H, &raw[1]) < 0) {
            fprintf(stderr, "Failed to read gyro data\n");
            break;
        }
        if (i2c_read_reg8(g_i2c_fd, GYRO_ZOUT_H, &raw[2]) < 0) {
            fprintf(stderr, "Failed to read gyro data\n");
            break;
        }

        /* Assemble 16-bit little-endian values */
        gyro_x = (int16_t)((raw[0] << 8) | raw[1]);
        gyro_y = (int16_t)((raw[2] << 8) | raw[3]);
        gyro_z = (int16_t)((raw[4] << 8) | raw[5]);

        /* Print the values */
        printf("Gyroscope: X=%6d  Y=%6d  Z=%6d  ", gyro_x, gyro_y, gyro_z);
        fflush(stdout);

        usleep(10000);  /* 10 ms sampling interval */
    }

    /* ---- Clean shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

