#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_17   17
#define GPIO_PIN_18   18
#define GPIO_PIN_27   27
#define GPIO_PIN_22   22
#define LOG_FILE      "watering_log.txt"
#define CYCLE_SECONDS 86400
#define WATERING_SEC  5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_start_time(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm timeinfo;
    if (!localtime_r(&rawtime, &timeinfo)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_relay(struct gpiod_line *line, int pin, int duration_sec)
{
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW: %s\n",
                pin, strerror(errno));
        return -1;
    }

    struct timespec ts = { .tv_sec = duration_sec, .tv_nsec = 0 };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        if (!g_running) {
            fprintf(stderr, "Interrupted during watering cycle.\n");
            return -1;
        }
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH: %s\n",
                pin, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int pins[4] = {GPIO_PIN_17, GPIO_PIN_18, GPIO_PIN_27, GPIO_PIN_22};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], "plant-watering", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    if (log_start_time(LOG_FILE) != 0) {
        fprintf(stderr, "Failed to log start time.\n");
        goto cleanup;
    }

    int cycle_start = 0;
    while (g_running) {
        for (int i = 0; i < 4 && g_running; i++) {
            if (activate_relay(lines[i], pins[i], WATERING_SEC) != 0) {
                fprintf(stderr, "Watering cycle failed for GPIO %d.\n", pins[i]);
                goto cleanup;
            }
        }

        if (g_running) {
            if (log_start_time(LOG_FILE) != 0) {
                fprintf(stderr, "Failed to log start time for next cycle.\n");
                goto cleanup;
            }
            cycle_start += CYCLE_SECONDS;
        } else {
            break;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Watering cycle complete.\n");
    }
    return ret;
}

