#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sampling period in microseconds (20 Hz) */
#define SAMPLE_PERIOD_US 50000

/* Threshold for angular velocity (deg/s) */
#define THRESHOLD 250.0f

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Circular buffer structure */
typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* Function prototypes */
static int init_i2c(void);
static int read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(float x, float y, float z);
static bool check_threshold(float x, float y, float z);
static void control_led(float x, float y, float z);
static void signal_handler(int sig);
static void cleanup(void);

/* Initialize I2C communication */
static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Read gyroscope data from MPU-6050 */
static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];

    /* Read 6 bytes starting at GYRO_XOUT_H */
    int bytes_read = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: I2C read failed (read %d bytes)\n", bytes_read);
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    int16_t gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* Convert to degrees per second (sensitivity 131 LSB/deg/s) */
    *x = (float)gyro_x / 131.0f;
    *y = (float)gyro_y / 131.0f;
    *z = (float)gyro_z / 131.0f;

    return 0;
}

/* Add data to the circular buffer */
static void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = time(NULL);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Check if any axis exceeds the threshold */
static bool check_threshold(float x, float y, float z) {
    return (fabsf(x) > THRESHOLD || fabsf(y) > THRESHOLD || fabsf(z) > THRESHOLD);
}

/* Control the LED based on the threshold check */
static void control_led(float x, float y, float z) {
    if (check_threshold(x, y, z)) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize I2C */
    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    printf("MPU-6050 Gyroscope Reader (20 Hz)\n");
    printf("Threshold: %.1f deg/s\n", THRESHOLD);
    printf("Press Ctrl+C to exit\n\n");

    /* Main loop */
    while (!terminate) {
        float x, y, z;

        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            if (init_i2c() != 0) {
                fprintf(stderr, "Error: I2C re-initialization failed. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful cleanup */
    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

