#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_USECS 0
#define LOG_FILE "gyro_log.txt"
#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 8
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t lsb_first = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &lsb_first) < 0) {
        fprintf(stderr, "Error setting SPI lsb first: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250_cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
