#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   3900000  /* 3.9 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* MPU-6050 register addresses */
#define MPU6050_REG_SMPLRT_DIV 0x19
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_PWR_MGMT_1 0x6B

/* GPIO pin definitions */
#define LED_PIN 17
#define BUFFER_SIZE 64

/* Thresholds */
#define GYRO_THRESHOLD_X  200.0f
#define GYRO_THRESHOLD_Y  200.0f
#define GYRO_THRESHOLD_Z  200.0f

/* SPI handle */
static int spi_handle = -1;

/* Circular buffer */
static float gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

/* Flag to indicate program termination */
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_spi(void);
static int read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(float x, float y, float z);
static void blink_led(int duration_ms);
static void print_buffer(void);
static void signal_handler(int signal);

/*
 * Initializes the SPI interface.
 * Returns 0 on success, -1 on failure.
 */
static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

/*
 * Reads the raw gyroscope data from the MPU-6050.
 * Returns 0 on success, -1 on failure.
 */
static int read_gyro_data(float *x, float *y, float *z) {
    char tx_buf[6];
    char rx_buf[6];
    int16_t raw_x, raw_y, raw_z;

    /*
     * MPU-6050 SPI read sequence (3 bytes):
     *   Byte 0: 0x80 | (SMPLRT_DIV << 5)  -> Sample rate divider
     *   Byte 1: 0x00
     *   Byte 2: 0x00
     * The device responds with 6 bytes:
     *   Byte 0: X MSB (0x00)
     *   Byte 1: X LSB (0x00)
     *   Byte 2: X H H-half (0x00)
     *   Byte 3: X L L (0x00)
     *   Byte 4: X H F (0x00)
     *   Byte 5: X L F (0x00)
     */
    tx_buf[0] = 0x80 | (MPU6050_REG_SMPLRT_DIV << 5);
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    tx_buf[3] = 0x00;
    tx_buf[4] = 0x00;
    tx_buf[5] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 6) != 6) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    raw_x = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
    raw_y = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);
    raw_z = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    /* Convert to degrees per second (16-bit signed, 1/20000 s/LSB) */
    *x = (float)raw_x / 20000.0f;
    *y = (float)raw_y / 20000.0f;
    *z = (float)raw_z / 20000.0f;

    return 0;
}

/*
 * Adds the current timestamp and gyroscope data to the circular buffer.
 */
static void add_to_buffer(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    gyro_buffer[buffer_index] = x;
    gyro_buffer[buffer_index + 1] = y;
    gyro_buffer[buffer_index + 2] = z;
    buffer_index = (buffer_index + 3) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/*
 * Blinks the LED with a 500ms on/off cycle.
 */
static void blink_led(int duration_ms) {
    gpioWrite(LED_PIN, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(LED_PIN, 0);
    gpioDelay(duration_ms * 1000);
}

/*
 * Prints the contents of the circular buffer to the console as a CSV.
 */
static void print_buffer(void) {
    printf("\n--- Gyroscope Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char timestamp[20];
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s,%.2f,%.2f,%.2f\n", timestamp, gyro_buffer[index], gyro_buffer[index + 1], gyro_buffer[index + 2]);
    }
    printf("--- End of Log ---\n\n");
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Initialize SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Configure LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        float x, y, z;

        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);

            if (x > GYRO_THRESHOLD_X || x < -GYRO_THRESHOLD_X ||
                y > GYRO_THRESHOLD_Y || y < -GYRO_THRESHOLD_Y ||
                z > GYRO_THRESHOLD_Z || z < -GYRO_THRESHOLD_Z) {
                blink_led(500);
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        gpioDelay(10000); /* 10 ms delay */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    print_buffer();

    return 0;
}

