 * Adds the current timestamp and gyroscope data to the circular buffer.
 */
static void add_to_buffer(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    gyro_buffer[buffer_index] = x;
    gyro_buffer[buffer_index + 1] = y;
    gyro_buffer[buffer_index + 2] = z;
    buffer_index = (buffer_index + 3) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/*
 * Blinks the LED with a 500ms on/off cycle.
 */
static void blink_led(int duration_ms) {
    gpioWrite(LED_PIN, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(LED_PIN, 0);
    gpioDelay(duration_ms * 1000);
}

/*
 * Prints the contents of the circular buffer to the console as a CSV.
 */
static void print_buffer(void) {
    printf("\n--- Gyroscope Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char timestamp[20];
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s,%.2f,%.2f,%.2f\n", timestamp, gyro_buffer[index], gyro_buffer[index + 1], gyro_buffer[index + 2]);
    }
    printf("--- End of Log ---\n\n");
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Initialize SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Configure LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        float x, y, z;

        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);

            if (x > GYRO_THRESHOLD_X || x < -GYRO_THRESHOLD_X ||
                y > GYRO_THRESHOLD_Y || y < -GYRO_THRESHOLD_Y ||
                z > GYRO_THRESHOLD_Z || z < -GYRO_THRESHOLD_Z) {
                blink_led(500);
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        gpioDelay(10000); /* 10 ms delay */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    print_buffer();

    return 0;
}

