#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 21

/* Tilt threshold (degrees) */
#define TILT_THRESHOLD 45.0

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int  init_mpu6050(void);
static int  read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);
static void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z,
                                  float *roll, float *pitch);
static void log_tilt_data(float roll, float pitch);
static void control_led(float roll, float pitch);
static void signal_handler(int sig);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initialize MPU-6050: standby, set sample rate divider, enable gyro and accel */
static int init_mpu6050(void) {
    /* Standby mode */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 (standby)\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Sample rate divider = 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV\n");
        return -1;
    }
    gpioDelay(10000);

    /* Enable gyro and accel */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x01) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 (active)\n");
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

/* Read accelerometer data (6 bytes starting at ACCEL_XOUT_H) */
static int read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, MPU6050_ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read accelerometer data\n");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* Calculate roll and pitch from accelerometer data */
static void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z,
                                 float *roll, float *pitch) {
    float fx = (float)accel_x;
    float fy = (float)accel_y;
    float fz = (float)accel_z;

    *roll  = atan2f(fy, sqrtf(fx * fx + fz * fz)) * 180.0f / (float)M_PI;
    *pitch = atan2f(-fx, sqrtf(fy * fy + fz * fz)) * 180.0f / (float)M_PI;
}

/* Log tilt data to file */
static void log_tilt_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open tilt_log.txt for appending\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

/* Control LED based on tilt thresholds */
static void control_led(float roll, float pitch) {
    if (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at address 0x%02X (code %d)\n",
                MPU6050_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler\n");
    }

    printf("MPU-6050 tilt monitor started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        int16_t accel_x, accel_y, accel_z;

        if (read_mpu6050(&accel_x, &accel_y, &accel_z) == 0) {
            float roll, pitch;
            calculate_roll_pitch(accel_x, accel_y, accel_z, &roll, &pitch);
            log_tilt_data(roll, pitch);
            control_led(roll, pitch);
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Warning: read_mpu6050 failed, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    cleanup();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

