#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXRS290 register addresses (from datasheet) */
#define ADXRS290_REG_XGYRO_OUT_L  0x00
#define ADXRS290_REG_YGYRO_OUT_L  0x02
#define ADXRS290_REG_TEMP_OUT_L   0x04
#define ADXRS290_REG_STATUS       0x06
#define ADXRS290_REG_CTRL_REG1    0x07
#define ADXRS290_REG_CTRL_REG2    0x08

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0
#define SPI_FLAGS   0

/* Sampling parameters */
#define SAMPLE_PERIOD_US 10000  /* 10 ms -> 100 Hz */
#define MAX_RETRIES       3

/* Global state for signal handler cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single 16-bit register from the ADXRS290                    */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* ADXRS290 returns data in the second byte of the response */
    *out = (int16_t)(((uint8_t)rx[1] << 8) | (uint8_t)rx[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register with retry logic                           */
/* ------------------------------------------------------------------ */
static int read_register_retry(uint8_t reg, int16_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read_register(reg, out) == 0)
            return 0;
        fprintf(stderr, "SPI read attempt %d/%d failed for 0x%02X\n",
                attempt + 1, MAX_RETRIES, reg);
        gpioDelay(1000);  /* 1 ms backoff */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read both gyro axes and temperature in one transfer               */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int16_t *x_rate, int16_t *y_rate, int16_t *temp)
{
    char tx[7] = { (char)(ADXRS290_REG_XGYRO_OUT_L | 0x80),
                   (char)(ADXRS290_REG_XGYRO_OUT_L | 0x80),
                   (char)(ADXRS290_REG_XGYRO_OUT_L | 0x80),
                   (char)(ADXRS290_REG_XGYRO_OUT_L | 0x80),
                   (char)(ADXRS290_REG_XGYRO_OUT_L | 0x80),
                   (char)(ADXRS290_REG_XGYRO_OUT_L | 0x80),
                   0x00 };
    char rx[7] = { 0, 0, 0, 0, 0, 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 7) != 7) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    /* Data is returned in the second byte of the response */
    *x_rate = (int16_t)(((uint8_t)rx[2] << 8) | (uint8_t)rx[1]);
    *y_rate = (int16_t)(((uint8_t)rx[4] << 8) | (uint8_t)rx[3]);
    *temp   = (int16_t)(((uint8_t)rx[6] << 8) | (uint8_t)rx[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the CSV file                                     */
/* ------------------------------------------------------------------ */
static int log_data(int16_t x_rate, int16_t y_rate, int16_t temp)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%ld.%09ld,%d,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec,
                x_rate, y_rate, temp) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file for appending */
    fp = fopen("gyro_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,x_rate,y_rate,temp\n");
        fflush(fp);
    }

    /* Install signal handler for SIGINT (Ctrl+C) */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXRS290 gyro data logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        int16_t x_rate = 0, y_rate = 0, temp = 0;

        if (read_gyro_data(&x_rate, &y_rate, &temp) != 0) {
            fprintf(stderr, "Gyro read failed — re-initialising SPI.\n");
            spiClose(spi_handle);
            spi_handle = -1;
            gpioDelay(100000);  /* 100 ms before retry */
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
            if (spi_handle < 0) {
                fprintf(stderr, "spiOpen retry failed: %s\n", strerror(errno));
                break;
            }
            continue;
        }

        if (log_data(x_rate, y_rate, temp) != 0) {
            fprintf(stderr, "Logging failed — continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

