#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17
#define ALERT_DURATION_MS 2000
#define SEISMIC_THRESHOLD_MS 500
#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_seismic_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

static void tilt_callback(int gpio, int level, uint32_t tick) {
    (void)tick;

    if (gpio == SENSOR_1_PIN) {
        if (level == 1) {
            static uint32_t last_tick = 0;
            uint32_t diff = tick - last_tick;
            if (diff >= SEISMIC_THRESHOLD_MS * 1000) {
                log_seismic_event();
                gpioWrite(ALERT_PIN, 1);
                gpioDelay(ALERT_DURATION_MS * 1000);
                gpioWrite(ALERT_PIN, 0);
                last_tick = tick;
            }
        }
    } else if (gpio == SENSOR_2_PIN) {
        if (level == 1) {
            static uint32_t last_tick = 0;
            uint32_t diff = tick - last_tick;
            if (diff >= SEISMIC_THRESHOLD_MS * 1000) {
                log_seismic_event();
                gpioWrite(ALERT_PIN, 1);
                gpioDelay(ALERT_DURATION_MS * 1000);
                gpioWrite(ALERT_PIN, 0);
                last_tick = tick;
            }
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize alert pin LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install signal handlers\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_1_PIN, tilt_callback) != 0 ||
        gpioSetAlertFunc(SENSOR_2_PIN, tilt_callback) != 0) {
        fprintf(stderr, "Error: Failed to register alert callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring tilt sensors on GPIO%d and GPIO%d. Alert on GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_1_PIN, SENSOR_2_PIN, ALERT_PIN);

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");

    gpioSetAlertFunc(SENSOR_1_PIN, NULL);
    gpioSetAlertFunc(SENSOR_2_PIN, NULL);
    gpioWrite(ALERT_PIN, 0);

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

