#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

/* ADXRS290 register addresses (16-bit, big-endian on the bus) */
#define ADXRS290_REG_XGYRO_OUT 0x00
#define ADXRS290_REG_XGYRO_CONFIG 0x01
#define ADXRS290_REG_XGYRO_RATE 0x02
#define ADXRS290_REG_XGYRO_STATUS 0x03

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

/* GPIO pin assignments (BCM numbering) */
#define LED_PIN 17
#define SPI_CE0_PIN 8

/* Threshold and buffer parameters */
#define GYRO_THRESHOLD 20.0f
#define BUFFER_SIZE 100

/* Global state */
static int spi_fd = -1;
static volatile sig_atomic_t terminate = 0;
static double gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* SPI transfer helper: write a single byte, then read `len` bytes     */
/* ------------------------------------------------------------------ */
static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (big-endian) from the ADXRS290               */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, uint16_t *out)
{
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    *out = (uint16_t)((rx[1] << 8) | rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read X-axis angular rate (deg/s)                                    */
/* ------------------------------------------------------------------ */
static int read_gyro_rate(float *rate_out)
{
    uint16_t raw;
    if (read_register(ADXRS290_REG_XGYRO_RATE, &raw) < 0)
        return -1;

    *rate_out = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the circular buffer                 */
/* ------------------------------------------------------------------ */
static void buffer_add(float rate)
{
    pthread_mutex_lock(&buffer_mutex);
    gyro_buffer[buffer_index] = rate;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

/* ------------------------------------------------------------------ */
/* Check whether the rate exceeds the threshold and control the LED    */
/* ------------------------------------------------------------------ */
static void check_threshold(float rate)
{
    static bool led_on = false;

    if (rate > GYRO_THRESHOLD) {
        if (!led_on) {
            if (gpioWrite(LED_PIN, 1) == 0) {
                led_on = true;
                printf("WARNING: Gyro rate %.2f deg/s exceeds threshold %.2f "
                       "deg/s. LED ON\n", rate, GYRO_THRESHOLD);
            } else {
                fprintf(stderr, "Failed to turn on LED\n");
            }
        }
    } else {
        if (led_on) {
            if (gpioWrite(LED_PIN, 0) == 0) {
                led_on = false;
                printf("Gyro rate %.2f deg/s within threshold %.2f "
                       "deg/s. LED OFF\n", rate, GYRO_THRESHOLD);
            } else {
                fprintf(stderr, "Failed to turn off LED\n");
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    pthread_mutex_destroy(&buffer_mutex);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts OFF */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Configure SPI0 CE0 as output, default to inactive (high) */
    if (gpioSetMode(SPI_CE0_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set SPI CE0 pin %d as output\n", SPI_CE0_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SPI_CE0_PIN, 1);

    /* Open SPI device: mode 0, 1 MHz, 8 bits */
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXRS290 gyroscope monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        float rate;
        if (read_gyro_rate(&rate) < 0) {
            fprintf(stderr, "SPI read error\n");
            break;
        }

        buffer_add(rate);
        check_threshold(rate);

        printf("Rate: %.2f deg/s\n", rate);

        time_sleep(0.1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

