    if (duration_sec <= 0) {
        set_lamp_brightness(pin, 0);
        return;
    }

    int step_size = duration_sec / FADE_STEPS;
    int current_duty = 0;
    for (int i = 0; i <= FADE_STEPS && g_running; i++) {
        current_duty = (current_duty + (step_size / FADE_STEPS)) % (MAX_DUTY + 1);
        set_lamp_brightness(pin, current_duty);
        gpioDelay(1000000 / PWM_FREQUENCY);
    }

    set_lamp_brightness(pin, 0);
}

static void run_sunset_simulation(int duration_sec) {
    if (duration_sec <= 0) {
        all_lamps_off();
        return;
    }

    printf("Starting sunset simulation for %d seconds...\n", duration_sec);
    printf("Lamps: GPIO%d, GPIO%d, GPIO%d\n", LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);

    for (int i = 0; i < 3 && g_running; i++) {
        printf("Fading lamp %d (GPIO%d)...\n", i + 1, LAMP1_PIN);
        fade_lamp(LAMP1_PIN, duration_sec);

        if (!g_running) break;

        for (int j = 0; j < 3 && g_running; j++) {
            printf("Fading lamp %d (GPIO%d)...\n", j + 2, LAMP2_PIN);
            fade_lamp(LAMP2_PIN, duration_sec);

            if (!g_running) break;

            for (int k = 0; k < 3 && g_running; k++) {
                printf("Fading lamp %d (GPIO%d)...\n", k + 3, LAMP3_PIN);
                fade_lamp(LAMP3_PIN, duration_sec);

                if (!g_running) break;
            }
        }
    }

    all_lamps_off();
    printf("Sunset simulation complete.\n");
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        fprintf(stderr, "Duration must be an integer between 1 and 3600.\n");
        return EXIT_FAILURE;
    }

    int duration_sec = atoi(argv[1]);
    if (duration_sec <= 0 || duration_sec > 3600) {
        fprintf(stderr, "Error: duration must be an integer between 1 and 3600.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    run_sunset_simulation(duration_sec);

    all_lamps_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

