#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

#define RED_DURATION_SEC 10
#define RED_YELLOW_SEC    2
#define GREEN_DURATION_SEC 10
#define YELLOW_DURATION_SEC 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static const char *state_str(int pin, int value) {
    return (value == 0) ? "ON" : "OFF";
}

static void print_state(int pin, int value) {
    printf("GPIO%d: %s\n", pin, state_str(pin, value));
}

static void set_all_off(void) {
    gpioWrite(RED_PIN, 1);
    gpioWrite(YELLOW_PIN, 1);
    gpioWrite(GREEN_PIN, 1);
    gpioWrite(BLUE_PIN, 1);
}

static void cleanup(void) {
    set_all_off();
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    int pins[] = {RED_PIN, YELLOW_PIN, GREEN_PIN, BLUE_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as output.\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO%d HIGH.\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Traffic light simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        print_state(RED_PIN, 0);
        sleep(RED_DURATION_SEC);

        print_state(YELLOW_PIN, 0);
        sleep(RED_YELLOW_SEC);

        print_state(GREEN_PIN, 0);
        sleep(GREEN_DURATION_SEC);

        print_state(YELLOW_PIN, 0);
        sleep(YELLOW_DURATION_SEC);
    }

    printf("\nTraffic light simulation stopped.\n");
    cleanup();
    return EXIT_SUCCESS;
}

