#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define LOG_FILE "flame_log.txt"
#define POLL_DELAY_US 50000
#define CONSECUTIVE_THRESHOLD 3

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", FLAME_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", BUZZER_PIN);
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        return -1;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state.\n");
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state.\n");
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d.\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return value;
}

static void log_flame_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Flame Detected\n", timestamp);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: log file not open.\n");
    }
}

static void activate_buzzer_and_led(void) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate buzzer.\n");
        return;
    }
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate LED.\n");
        gpioWrite(BUZZER_PIN, 0);
    }
}

static void deactivate_buzzer_and_led(void) {
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate buzzer.\n");
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate LED.\n");
    }
}

static void cleanup(void) {
    deactivate_buzzer_and_led();
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_INPUT);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    int consecutive_low = 0;
    int first_read = 1;

    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (first_read) {
            first_read = 0;
            consecutive_low = 0;
        } else {
            if (sensor_value == 0) {
                consecutive_low++;
            } else {
                consecutive_low = 0;
            }
        }

        if (consecutive_low >= CONSECUTIVE_THRESHOLD) {
            log_flame_detection();
            activate_buzzer_and_led();

            while (program_running) {
                int val = read_flame_sensor();
                if (val < 0) {
                    break;
                }
                if (val != 0) {
                    break;
                }
                gpioDelay(POLL_DELAY_US);
            }

            deactivate_buzzer_and_led();
            consecutive_low = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

