#define SOLENOID1_PIN 17
#define SOLENOID2_PIN 27
#define DISPENSE_INTERVAL_MS 1000
#define HALF_INTERVAL_MS 500
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_dispense(int s1_pin, int s2_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Solenoid1: GPIO%d, Solenoid2: GPIO%d, Duration: %d ms\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
