    if (activate_solenoid(s1_pin) < 0) return -1;
    gpioDelay(HALF_INTERVAL_MS * 1000);
    if (activate_solenoid(s2_pin) < 0) return -1;
    gpioDelay(HALF_INTERVAL_MS * 1000);
    deactivate_solenoid(s1_pin);
    deactivate_solenoid(s2_pin);
    return 0;
}

