#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25

#define OBSTACLE_THRESHOLD 20.0
#define OBSTACLE_REVERSE_SPEED 50
#define OBSTACLE_REVERSE_PWM 255
#define TILT_ERROR_MIN -10.0
#define TILT_ERROR_MAX 10.0
#define TILT_ERROR_RANGE (TILT_ERROR_MAX - TILT_ERROR_MIN)
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(ENA, PI_OUTPUT) < 0 ||
        gpioSetMode(ENB, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(ENA, 1000) < 0 || gpioSetPWMfrequency(ENB, 1000) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(ENA, 0) < 0 || gpioPWM(ENB, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialize PWM to 0\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(MOTOR_A_FORWARD, 0) < 0 || gpioWrite(MOTOR_A_BACKWARD, 0) < 0 ||
        gpioWrite(MOTOR_B_FORWARD, 0) < 0 || gpioWrite(MOTOR_B_BACKWARD, 0)) {
        fprintf(stderr, "Error: Failed to initialize motor pins to LOW\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

static void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        gpioWrite(MOTOR_A_FORWARD, speed > 0 ? 1 : 0);
        gpioWrite(MOTOR_A_BACKWARD, speed > 0 ? 0 : 1);
    } else if (motor == 2) {
        gpioWrite(MOTOR_B_FORWARD, speed > 0 ? 1 : 0);
        gpioWrite(MOTOR_B_BACKWARD, speed > 0 ? 0 : 1);
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
    }
}

static void stop_all_motors(void) {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

static void cleanup(void) {
    stop_all_motors();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int read_distance(void) {
    return (rand() % 380) + 2;
}

static int read_tilt_error(void) {
    return (rand() % (TILT_ERROR_MAX - TILT_ERROR_MIN + 1)) + TILT_ERROR_MIN;
}

static int calculate_motor_speeds(float tilt_error, float distance) {
    float error_norm = tilt_error / 10.0;
    float speed_a = (float)OBSTACLE_REVERSE_SPEED * (1.0 + error_norm) * (1.0 - distance / OBSTACLE_THRESHOLD);
    float speed_b = (float)OBSTACLE_REVERSE_SPEED * (1.0 - error_norm) * (1.0 - distance / OBSTACLE_THRESHOLD);

    if (speed_a < 0) speed_a = 0;
    if (speed_a > 255) speed_a = 255;
    if (speed_b < 0) speed_b = 0;
    if (speed_b > 255) speed_b = 255;

    return (int)speed_a + (int)speed_b;
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    srand(time(NULL));

    while (running) {
        float tilt_error = read_tilt_error();
        float distance = read_distance();

        int motor_a_speed = calculate_motor_speeds(tilt_error, distance);
        int motor_b_speed = calculate_motor_speeds(tilt_error, distance);

        set_motor_speed(1, (motor_a_speed < 0) ? -motor_a_speed : motor_a_speed);
        set_motor_speed(2, (motor_b_speed < 0) ? -motor_b_speed : motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        if (distance < OBSTACLE_THRESHOLD) {
            stop_all_motors();
            set_motor_speed(1, OBSTACLE_REVERSE_PWM);
            set_motor_speed(2, OBSTACLE_REVERSE_PWM);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

