/*
 * TCS34725 Color Sensor Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TCS34725 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   TCS34725 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   TCS34725 VDD -> 3.3 V
 *   TCS34725 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o color_logger color_logger.c -ltcs34725
 *
 * Run:
 *   ./color_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <tcs34725.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29
#define LOG_FILE       "color_data.csv"
#define SAMPLE_MS      500
#define INTEGRATION_MS 154

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int open_i2c_device(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write reg-select 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int init_sensor(int fd)
{
    /*
     * TCS34725 command register (0x80) + 16-bit command bits (0x4000)
     * -> 0x4040  -> 0x4040 | 0x0001  -> 0x4041
     * 0x4041 = 0100 0000 0010 0001
     *   bit 15   = 0  -> power on
     *   bits 14:12 = 100 -> integration time 154 ms
     *   bit 11   = 0  -> no ALS enable
     *   bits 10:9  = 00 -> no PEL enable
     *   bit 8     = 1  -> auto-power down disabled
     *   bits 7:5   = 100 -> no FIFO disable
     *   bit 4     = 0  -> no CDC disable
     *   bits 3:0   = 000 -> no CDC enable
     */
    if (write_reg16(fd, 0x80, 0x4041) < 0)
        return -1;

    /*
     * 0x4041 -> 0x4041 | 0x0000 = 0x4041
     *   bit 15   = 0  -> power on
     *   bits 14:12 = 000 -> integration time 154 ms
     *   bit 11   = 0  -> no ALS enable
     *   bits 10:9  = 00 -> no PEL enable
     *   bit 8     = 0  -> no CDC disable
     *   bits 7:5   = 000 -> no FIFO disable
     *   bit 4     = 0  -> no CDC enable
     *   bits 3:0   = 000 -> no CDC enable
     */
    if (write_reg16(fd, 0x80, 0x4040) < 0)
        return -1;

    return 0;
}

static int read_color_data(int fd, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b)
{
    if (read_reg16(fd, 0x00, c) < 0) return -1;
    if (read_reg16(fd, 0x02, r) < 0) return -1;
    if (read_reg16(fd, 0x04, g) < 0) return -1;
    if (read_reg16(fd, 0x06, b) < 0) return -1;
    return 0;
}

static int log_data(FILE *fp, time_t ts, uint16_t c, uint16_t r, uint16_t g, uint16_t b)
{
    if (fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)ts, c, r, g, b) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    i2c_fd = open_i2c_device(I2C_BUS, TCS34725_ADDR);
    if (i2c_fd < 0)
        goto cleanup;

    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,C,R,G,B\n") < 0) {
            fprintf(stderr, "fprintf header: %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush header: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Logging TCS34725 color data to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        uint16_t c, r, g, b;

        if (read_color_data(i2c_fd, &c, &r, &g, &b) == 0) {
            time_t now = time(NULL);
            if (log_data(fp, now, c, r, g, b) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; logging zeros.\n");
            c = r = g = b = 0;
        }

        /*
         * TCS34725 integration time is 154 ms.
         * Sample every 500 ms so that the next integration starts
         * after the current one completes, and we get a fresh sample.
         */
        struct timespec ts = { 0, SAMPLE_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp) {
        if (fclose(fp) != 0)
            fprintf(stderr, "fclose: %s\n", strerror(errno));
    }
    if (i2c_fd >= 0) {
        if (close(i2c_fd) != 0)
            fprintf(stderr, "close: %s\n", strerror(errno));
    }
    return rc;
}

