#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1 17
#define RELAY2 27
#define RELAY3 22
#define RELAY4 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 6000
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 14400

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void all_relays_off(void) {
    gpioWrite(RELAY1, 1);
    gpioWrite(RELAY2, 1);
    gpioWrite(RELAY3, 1);
    gpioWrite(RELAY4, 1);
}

static void sunrise(void) {
    for (int i = 0; i < SUNRISE_DURATION && running; i++) {
        int duty = (i * 100) / SUNRISE_DURATION;
        gpioWrite(RELAY1, duty > 0 ? 0 : 1);
        gpioWrite(RELAY2, duty > 0 ? 0 : 1);
        gpioWrite(RELAY3, duty > 0 ? 0 : 1);
        gpioWrite(RELAY4, duty > 0 ? 0 : 1);
        gpioDelay(1000000);
    }
}

static void daytime(void) {
    for (int i = 0; i < DAYTIME_DURATION && running; i++) {
        int duty = (i * 100) / DAYTIME_DURATION;
        gpioWrite(RELAY1, duty > 0 ? 0 : 1);
        gpioWrite(RELAY2, duty > 0 ? 0 : 1);
        gpioWrite(RELAY3, duty > 0 ? 0 : 1);
        gpioWrite(RELAY4, duty > 0 ? 0 : 1);
        gpioDelay(1000000);
    }
}

static void sunset(void) {
    for (int i = 0; i < SUNSET_DURATION && running; i++) {
        int duty = (SUNSET_DURATION - i * 100) / SUNSET_DURATION;
        gpioWrite(RELAY1, duty > 0 ? 0 : 1);
        gpioWrite(RELAY2, duty > 0 ? 0 : 1);
        gpioWrite(RELAY3, duty > 0 ? 0 : 1);
        gpioWrite(RELAY4, duty > 0 ? 0 : 1);
        gpioDelay(1000000);
    }
}

static void nighttime(void) {
    for (int i = 0; i < NIGHTTIME_DURATION && running; i++) {
        int duty = (i * 100) / NIGHTTIME_DURATION;
        gpioWrite(RELAY1, duty > 0 ? 0 : 1);
        gpioWrite(RELAY2, duty > 0 ? 0 : 1);
        gpioWrite(RELAY3, duty > 0 ? 0 : 1);
        gpioWrite(RELAY4, duty > 0 ? 0 : 1);
