#include <sys/wait.h>
#include <pigpio.h>

#define IR_SENSOR_GPIO 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_SEC 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define TIMESTAMP_LEN 32

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }
    if (fprintf(log_file, "%s Motion detected\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("Error flushing log file");
        return -1;
    }
    return 0;
}

static int capture_video(void) {
    char timestamp[TIMESTAMP_LEN];
    if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Error getting timestamp for video filename\n");
        return -1;
    }

    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s%s.h264", VIDEO_DIR, timestamp);

    char command[512];
    snprintf(command, sizeof(command),
             "raspivid -o %s -t %d -o /dev/null 2>>/home/pi/logs/raspivid.log",
             filepath, VIDEO_DURATION_SEC);

    int status = system(command);
    if (status == -1) {
        perror("Error executing raspivid");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(IR_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", IR_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(IR_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", IR_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", IR_SENSOR_GPIO);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int level = gpioRead(IR_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", IR_SENSOR_GPIO);
            break;
        }

        if (level == 0) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick > DEBOUNCE_MS * 1000) {
                char timestamp[TIMESTAMP_LEN];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    printf("Motion detected at %s\n", timestamp);
                    if (capture_video() != 0) {
                        fprintf(stderr, "Failed to capture video\n");
                    }
                    if (log_motion_event(timestamp) != 0) {
                        fprintf(stderr, "Failed to log motion event\n");
                    }
                } else {
                    fprintf(stderr, "Failed to get timestamp for log entry\n");
                }
                last_trigger_tick = now;
            }
        }

        gpioDelay(10000);
    }

    printf("\nCleaning up...\n");
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    return 0;
}

