#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47
#define GYRO_CONFIG  0x1B

/* Sensitivity scale factor for gyro data (counts per second per g) */
#define GYRO_SCALE  131.0f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Maximum re-initialization attempts before giving up */
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPU-6050: wake up, set gyro full-scale range, and     */
/* verify the device is responding.                                     */
/* Returns 0 on success, -1 on failure.                                 */
/* ------------------------------------------------------------------ */
static int init_mpu6050(void)
{
    /* Wake up the MPU-6050: clear SLEEP bit in PWR_MGMT_1 */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 (0x%02X): %s\n",
                PWR_MGMT_1, strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time after wake-up */

    /* Set gyro full-scale range to +/- 250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG (0x%02X): %s\n",
                GYRO_CONFIG, strerror(errno));
        return -1;
    }

    /* Verify the device is responding by reading GYRO_XOUT_H */
    int raw = i2cReadByteData(i2c_handle, GYRO_XOUT_H);
    if (raw < 0) {
        fprintf(stderr, "Error: failed to read GYRO_XOUT_H (0x%02X): %s\n",
                GYRO_XOUT_H, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read gyroscope data from the MPU-6050.                               */
/* Returns 0 on success, -1 on failure.                                 */
/* ------------------------------------------------------------------ */
static int read_gyro_data(float *x, float *y, float *z)
{
    char buf[6];

    /* Read 6 bytes starting at GYRO_XOUT_H (0x43) */
    int bytes_read = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: I2C block read failed (expected 6 bytes, got %d): %s\n",
                bytes_read, strerror(errno));
        return -1;
    }

    /* Assemble big-endian signed 16-bit values */
    int16_t raw_x = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)(((uint16_t)buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)(((uint16_t)buf[4] << 8) | (uint8_t)buf[5]);

    /* Convert to degrees per second */
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped gyroscope reading to the CSV log file.         */
/* ------------------------------------------------------------------ */
static int log_gyro_data(float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    long long timestamp_us = (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000;

    if (fprintf(log_file, "%lld,%.3f,%.3f,%.3f\n",
                timestamp_us, x, y, z) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Re-initialize the MPU-6050: wake up, re-configure gyro range,        */
/* and verify the device is responding.                                 */
/* ------------------------------------------------------------------ */
static int reinit_mpu6050(void)
{
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C handle invalid during re-init.\n");
        return -1;
    }

    /* Wake up the MPU-6050 */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 during re-init: %s\n",
                strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time after wake-up */

    /* Set gyro full-scale range to +/- 250 deg/s */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG during re-init: %s\n",
                strerror(errno));
        return -1;
    }

    /* Verify the device is responding by reading GYRO_XOUT_H */
    int raw = i2cReadByteData(i2c_handle, GYRO_XOUT_H);
    if (raw < 0) {
        fprintf(stderr, "Error: failed to read GYRO_XOUT_H during re-init: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources on exit.                                           */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, MPU6050_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open gyro_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x_degps,y_degps,z_degps\n");
        fflush(log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("MPU-6050 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        float x, y, z;

        if (read_gyro_data(&x, &y, &z) == 0) {
            if (log_gyro_data(x, y, z) != 0) {
                fprintf(stderr, "Warning: logging failed for this sample.\n");
            }
        } else {
            fprintf(stderr, "Warning: gyro data read failed. Attempting re-initialization...\n");

            for (int attempt = 1; attempt <= MAX_REINIT_ATTEMPTS && running; attempt++) {
                if (reinit_mpu6050() == 0) {
                    break;
                }
                fprintf(stderr, "Re-initialization attempt %d/%d failed.\n",
                        attempt, MAX_REINIT_ATTEMPTS);
                gpioDelay(1000000); /* 1 s between re-init attempts */
            }

            if (attempt > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Error: all %d re-initialization attempts failed. "
                                "Logging skipped and exiting.\n", MAX_REINIT_ATTEMPTS);
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

