#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define LOOP_DELAY_US 5000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d HIGH.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioWrite(pins[i], 1);
    }
}

static void log_data(int moisture, int relay1, int relay2, int relay3, int relay4) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            moisture,
            relay1 ? "ON" : "OFF",
            relay2 ? "ON" : "OFF",
            relay3 ? "ON" : "OFF",
            relay4 ? "ON" : "OFF");

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing signal handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int moisture = rand() % 101;
        int relay1 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay2 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay3 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay4 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;

        if (gpioWrite(RELAY1_PIN, relay1) != 0 ||
            gpioWrite(RELAY2_PIN, relay2) != 0 ||
            gpioWrite(RELAY3_PIN, relay3) != 0 ||
            gpioWrite(RELAY4_PIN, relay4) != 0) {
            fprintf(stderr, "Error: failed to write relay states.\n");
            deactivate_all_relays();
            gpioTerminate();
            return 1;
        }

        log_data(moisture, relay1, relay2, relay3, relay4);
        gpioDelay(LOOP_DELAY_US);
    }

    deactivate_all_relays();
    gpioTerminate();
    return 0;
}

