/*
 * ADXL345 Free-Fall Detector for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   ADXL345 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   ADXL345 VDD -> 3.3 V
 *   ADXL345 GND -> GND
 *   Alarm LED/buzzer on GPIO27 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall freefall.c -lpigpio -lrt
 *   sudo ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDR          0x50
#define ADXL345_REG_DEVID     0x00
#define ADXL345_REG_THRESH_FF 0x28
#define ADXL345_REG_TIME_FF   0x29
#define ADXL345_REG_DATA_X_L  0x32
#define ADXL345_REG_POWER_CTL 0x2D

#define ADXL345_DEVID         0xE5
#define ADXL345_THRESH_FF_VAL 0x0F
#define ADXL345_TIME_FF_VAL   0x0A

/* ---- Application constants ---- */
#define ALARM_GPIO            27
#define FREEFALL_THRESHOLD    0.2f   /* g */
#define FREEFALL_DURATION_MS  500    /* 0.5 s */
#define POLL_INTERVAL_US      100000 /* 100 ms */
#define ALARM_HOLD_US         5000000 /* 5 s */
#define LOG_FILE              "freefall.log"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_alarm_active = false;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %d\n", reg, rc);
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL345 driver                                                       */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    if (i2c_read_reg(handle, ADXL345_REG_DEVID, &devid) < 0)
        return -1;

    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "[ADXL345] Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID);
        return -1;
    }

    /* Standby mode to allow configuration */
    if (i2c_write_reg(handle, ADXL345_REG_POWER_CTL, 0x00) < 0)
        return -1;

    /* Free-fall threshold: 0.2 g */
    if (i2c_write_reg(handle, ADXL345_REG_THRESH_FF, ADXL345_THRESH_FF_VAL) < 0)
        return -1;

    /* Free-fall time: 0.5 s */
    if (i2c_write_reg(handle, ADXL345_REG_TIME_FF, ADXL345_TIME_FF_VAL) < 0)
        return -1;

    /* Enable measurement mode */
    if (i2c_write_reg(handle, ADXL345_REG_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

static int adxl345_read_axis(int handle, uint8_t reg, float *out)
{
    uint8_t lo = 0, hi = 0;

    if (i2c_read_reg(handle, reg, &lo) < 0)
        return -1;
    if (i2c_read_reg(handle, reg + 1, &hi) < 0)
        return -1;

    int16_t raw = (int16_t)((hi << 8) | lo);
    *out = (float)raw / 16384.0f;   /* 14-bit left-justified, divide by 16384 */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Free-fall detection                                                  */
/* ------------------------------------------------------------------ */
static bool detect_freefall(float x, float y, float z)
{
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

static bool confirm_freefall(float x, float y, float z)
{
    static uint32_t start_tick = 0;
    static bool      confirmed = false;

    if (confirmed)
        return false;

    start_tick = gpioTick();
    confirmed = true;

    /* Poll every 100 ms; break early if alarm is triggered */
    for (uint32_t elapsed = 0; elapsed < FREEFALL_DURATION_MS * 1000 && g_running; elapsed += 100000) {
        uint32_t now = gpioTick();
        if ((now - start_tick) >= FREEFALL_DURATION_MS * 1000)
            return false;
        gpioDelay(POLL_INTERVAL_US);
    }
    return false;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[LOG] fopen");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    } else {
        fprintf(fp, "(time-error),%.3f,%.3f,%.3f\n", x, y, z);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_alarm_active) {
        gpioWrite(ALARM_GPIO, 0);
        g_alarm_active = false;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Alarm GPIO setup --- */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d) failed\n", ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(1, 0x%02X) failed: %d\n", ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- ADXL345 init --- */
    if (adxl345_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[FATAL] sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started.  Threshold: %.2f g.  Ctrl+C to exit.\n",
           FREEFALL_THRESHOLD);

    /* --- Main loop --- */
    while (g_running) {
