/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * TRIG  -> GPIO4  (BCM)
 * ECHO  -> GPIO18 (BCM)
 *
 * 10 µs trigger pulse, 200 ms between trigger cycles,
 * 23 200 µs max range (4 m), 100 ms timeout for echo.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define TRIG_PIN          4
#define ECHO_PIN          18
#define TRIG_PULSE_US     10
#define TRIG_INTERVAL_US  200000   /* 200 ms between trigger pulses */
#define MAX_RANGE_US      23200    /* ~4 m HC-SR04 maximum range */
#define ECHO_TIMEOUT_US   100000   /* 100 ms max echo wait */
#define TIMESTAMP_NS_SEC  31
#define TIMESTAMP_NS_US   3174398571L  /* 71.6 min */

static volatile uint32_t g_rise_tick = 0;
static volatile uint32_t g_fall_tick = 0;
static volatile bool     g_echo_seen = false;
static volatile bool     g_echo_valid = false;
static volatile bool     g_running = true;
static pthread_mutex_t   g_mutex = PTHREAD_MUTEX_INITIALIZER;

static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* Echo interrupt callback — captures the echo pulse width           */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_rise_tick = tick;
    } else if (level == 0) {
        g_fall_tick = tick;
        g_echo_seen = true;
        g_echo_valid = true;
    }
}

/* ------------------------------------------------------------------ */
/* Trigger pulse — fires a 10 µs high pulse on TRIG                   */
/* ------------------------------------------------------------------ */
static void trigger_pulse(void)
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIG_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Compute elapsed microseconds between two 32-bit tick values       */
/* ------------------------------------------------------------------ */
static uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;
}

/* ------------------------------------------------------------------ */
/* Log one CSV row: timestamp_ns,distance_cm                         */
/* ------------------------------------------------------------------ */
static void log_distance(uint32_t timestamp_ns, float distance_cm)
{
    if (g_log_file) {
        fprintf(g_log_file, "%llu,%.2f\n", (unsigned long long)timestamp_ns, distance_cm);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — cancel callbacks, close file, terminate pigpio    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetISRFuncEx(TRIG_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(TRIG_PIN, FALLING_EDGE, 0, NULL, NULL);

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
    pthread_mutex_destroy(&g_mutex);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIG_PIN %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIG_PIN, 0);

    /* ---- Open log file ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error installing SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register echo interrupt ---- */
    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register echo ISR on GPIO%d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register falling-edge ISR on GPIO%d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        /* Reset state */
        g_echo_seen = false;
        g_echo_valid = false;
        g_running = false;

        /* Fire trigger pulse */
        trigger_pulse();

        /* Wait for echo (with timeout) */
        uint32_t start_tick = gpioTick();
        while (!g_echo_seen && g_running) {
            if (tick_diff(start_tick, gpioTick()) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);  /* poll every 100 µs */
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Error: echo timeout — no echo received within %d µs.\n",
                    ECHO_TIMEOUT_US);
            log_distance(0, -1.0f);
            continue;
        }

        if (!g_echo_valid) {
            /*
             * g_fall_tick is the falling-edge tick;
             * gpioTick() returns a 32-bit tick that wraps every ~71.6 min.
             * To get a 32-bit delta, subtract the rising-edge tick.
             */
            uint32_t pulse_us = tick_diff(g_rise_tick, g_fall_tick);
            if (pulse_us > MAX_RANGE_US) {
                fprintf(stderr, "Error: pulse width %u µs exceeds max range "
                                "(%d m). Discarding.\n", pulse_us, MAX_RANGE_US / 1000.0f);
                log_distance(0, -1.0f);
            } else {
                float distance_cm = (float)pulse_us / 58.0f;
                log_distance(g_rise_tick, distance_cm);
            }
            continue;
        }

        /* Compute timestamp in nanoseconds (pigpio tick is µs) */
        uint32_t timestamp_ns = (uint32_t)g_rise_tick * TIMESTAMP_NS_SEC;

        /* ---- Normal measurement ---- */
        log_distance(timestamp_ns, (float)pulse_us / 58.0f);

        /* ---- Sensor timeout / out-of-range ---- */
        /*
         * If we reached this point, the echo pulse was valid but
         * the distance exceeds the sensor's 4-m range.
         */
        if ((float)pulse_us > MAX_RANGE_US) {
            fprintf(stderr, "Warning: distance %.2f m exceeds sensor "
                            "maximum range (%.0f m).\n",
                    (float)pulse_us / 58.0f, MAX_RANGE_US / 1000.0f);
        }
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

