        /* ---- Normal measurement ---- */
        log_distance(timestamp_ns, (float)pulse_us / 58.0f);

        /* ---- Sensor timeout / out-of-range ---- */
        /*
         * If we reached this point, the echo pulse was valid but
         * the distance exceeds the sensor's 4-m range.
         */
        if ((float)pulse_us > MAX_RANGE_US) {
            fprintf(stderr, "Warning: distance %.2f m exceeds sensor "
                            "maximum range (%.0f m).\n",
                    (float)pulse_us / 58.0f, MAX_RANGE_US / 1000.0f);
        }
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

