#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LIS3DH I2C address (SA0 tied to GND) */
#define LIS3DH_ADDR 0x19

/* LIS3DH register addresses */
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L   0x28
#define LIS3DH_OUT_X_H   0x29
#define LIS3DH_OUT_Y_L   0x2A
#define LIS3DH_OUT_Y_H   0x2B
#define LIS3DH_OUT_Z_L   0x2C
#define LIS3DH_OUT_Z_H   0x2D

/* LIS3DH sensitivity: 1 mg/digit at +/-2g, 16-bit resolution */
#define LIS3DH_SENSITIVITY 0.001f

/* Impact detection thresholds (in g) */
#define IMPACT_THRESHOLD_G 1.5f
#define FREE_FALL_THRESHOLD_G 0.2f

/* Buzzer GPIO pin (BCM numbering) */
#define BUZZER_PIN 17

/* I2C bus on Raspberry Pi 5 */
#define I2C_BUS 1

/* Retry parameters */
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 10000

/* Global flag for graceful shutdown */
static volatile sig_atomic_t program_running = 1;

/* Signal handler for SIGINT (Ctrl+C) */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Initialize the LIS3DH accelerometer */
static int init_lis3dh(int i2c_handle) {
    /*
     * CTRL_REG1: 0x70 = 0111 0000
     *   ODR = 000 (1 Hz)
     *   LPen = 0 (active low)
     *   Zen = 0 (accelerometer enabled)
     *   BDU = 0 (block data update)
     *   Simultaneously enable the accelerometer and set ODR to 1 Hz.
     */
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, 0x70) < 0) {
        fprintf(stderr, "Error writing to LIS3DH CTRL_REG1\n");
        return -1;
    }

    /*
     * CTRL_REG4: 0x80 = 1000 0000
     *   ULPen = 0 (active low)
     *   Zen = 0 (accelerometer enabled)
     *   Simultaneously enable the accelerometer and set ULPen to 0.
     */
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG4, 0x80) < 0) {
        fprintf(stderr, "Error writing to LIS3DH CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* Read 6 bytes of accelerometer data (X, Y, Z) from the LIS3DH */
static int read_accelerometer(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    /*
     * Read 6 bytes starting at OUT_X_L (0x28).
     * pigpio's i2cReadI2CBlockData returns the number of bytes read,
     * or a negative value on error.
     */
    int bytes_read = i2cReadI2CBlockData(i2c_handle, LIS3DH_OUT_X_L, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading accelerometer data: expected 6 bytes, got %d\n", bytes_read);
        return -1;
    }

    /* Combine low and high bytes for each axis */
    *x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    return 0;
}

/* Calculate the magnitude of the acceleration vector */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x * LIS3DH_SENSITIVITY;
    float y_g = (float)y * LIS3DH_SENSITIVITY;
    float z_g = (float)z * LIS3DH_SENSITIVITY;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

/* Cleanup resources */
static void cleanup(int i2c_handle) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int i2c_handle = -1;
    int impact_threshold_g = IMPACT_THRESHOLD_G;
    int free_fall_threshold_g = FREE_FALL_THRESHOLD_G;

    /* Parse command-line arguments */
    if (argc > 1) {
        impact_threshold_g = (int)strtof(argv[1], NULL);
        if (impact_threshold_g < 0) {
            fprintf(stderr, "Invalid impact threshold. Using default: %.2f g\n", IMPACT_THRESHOLD_G);
            impact_threshold_g = IMPACT_THRESHOLD_G;
        }
    }
    if (argc > 2) {
        free_fall_threshold_g = (int)strtof(argv[2], NULL);
        if (free_fall_threshold_g < 0) {
            fprintf(stderr, "Invalid free-fall threshold. Using default: %.2f g\n", FREE_FALL_THRESHOLD_G);
            free_fall_threshold_g = FREE_FALL_THRESHOLD_G;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO17 as an output and ensure the buzzer is off */
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the LIS3DH */
    if (init_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing LIS3DH\n");
        cleanup(i2c_handle);
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler\n");
        cleanup(i2c_handle);
        return EXIT_FAILURE;
    }

    printf("Free-fall and impact detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        int16_t x, y, z;
        float magnitude;

        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude < free_fall_threshold_g) {
                printf("Free-fall detected! Magnitude: %.2f g\n", magnitude);
            } else if (magnitude > impact_threshold_g) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                gpioWrite(BUZZER_PIN, 1);
                gpioDelay(1000000); /* 1 second */
                gpioWrite(BUZZER_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup(i2c_handle);
    return EXIT_SUCCESS;
}

