    int motor2_steps = side_steps;

    /* Motor 1 traces the top horizontal line */
    motor_move(1, motor1_steps, 0);
    gpioDelay(100000); /* 100 ms gap between sides */

    /* Motor 2 traces the bottom horizontal line */
    motor_move(2, motor2_steps, 0);
    gpioDelay(100000);

    /* Motor 1 traces the left vertical line */
    motor_move(1, motor1_steps, 1);
    gpioDelay(100000);

    /* Motor 2 traces the right vertical line */
    motor_move(2, motor2_steps, 1);
    gpioDelay(100000);
}

static void cleanup(void)
{
    motor_stop(1);
    motor_stop(2);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(motor1_pins[i], PI_OUTPUT) < 0 ||
            gpioSetMode(motor2_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode for pin %d\n", motor1_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Ensure all motors start stopped */
    motor_stop(1);
    motor_stop(2);

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting 50 mm square trace...\n");
    printf("Press Ctrl+C to stop early.\n");

    move_square(100);

    printf("\nStopping and cleaning up...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

