#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define LIS3DH_REG_CTRL1   0x20
#define LIS3DH_REG_CTRL4   0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

#define LIS3DH_CTRL1_VAL  0x70  /* ODR=100Hz, all axes enabled, normal mode */
#define LIS3DH_CTRL4_VAL  0x00  /* ±2g, high-resolution, 12-bit, left-justified */
#define LIS3DH_ADDR_MIN   0x14  /* LIS3DH_ADDR_1 low byte */
#define LIS3DH_ADDR_MAX   0x17  /* LIS3DH_ADDR_1 high byte */
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_data(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f, Y: %.3f, Z: %.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    }
    fclose(fp);
}

static int configure_lis3dh(int handle, int address) {
    if (address < LIS3DH_ADDR_MIN || address > LIS3DH_ADDR_MAX) {
        fprintf(stderr, "Invalid I2C address: 0x%02X (must be 0x%02X-%02X)\n",
                address, LIS3DH_ADDR_MIN, LIS3DH_ADDR_MAX);
        return -1;
    }

    /* CTRL1: ODR=100Hz (0x70), all axes enabled, normal mode */
    if (i2cWriteByteData(handle, LIS3DH_REG_CTRL1, LIS3DH_CTRL1_VAL) < 0) {
        fprintf(stderr, "Failed to write CTRL1 register: %s\n", strerror(errno));
        return -1;
    }

    /* CTRL4: ±2g, high-resolution, 12-bit, left-justified */
    if (i2cWriteByteData(handle, LIS3DH_REG_CTRL4, LIS3DH_CTRL4_VAL) < 0) {
        fprintf(stderr, "Failed to write CTRL4 register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(handle, LIS3DH_REG_OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    /* Convert to g: 12-bit left-justified, ±2g range => 1 LSB = 1 mg */
    *x = (float)x_raw / 1000.0f;
    *y = (float)y_raw / 1000.0f;
    *z = (float)z_raw / 1000.0f;

    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int address = -1;
    float threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        char *endptr;
        address = strtol(argv[1], &endptr, 16);
        if (*endptr != '\0' || address < LIS3DH_ADDR_MIN || address > LIS3DH_ADDR_MAX) {
            fprintf(stderr, "Invalid I2C address: 0x%02X\n", address);
            return 1;
        }
    }

    if (argc > 2) {
        char *endptr;
        threshold = strtof(argv[2], &endptr);
        if (*endptr != '\0' || threshold <= 0.0f) {
            fprintf(stderr, "Invalid threshold: %.2f g\n", threshold);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, 0, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (configure_lis3dh(g_i2c_handle, address) < 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("LIS3DH monitoring started. Threshold: %.2f g, Address: 0x%02X\n",
           threshold, address);

    while (g_running) {
        float x, y, z;
        if (read_accelerometer(g_i2c_handle, &x, &y, &z) == 0) {
            if (x > threshold || y > threshold || z > threshold) {
                log_data(x, y, z);
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

