#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

#define BUFFER_SIZE 5
#define POLL_DELAY_US 10000
#define ALERT_DURATION_US 2000000
#define LINE_DETECTED_COUNT 5

typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

typedef struct {
    SensorReadings readings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer sensor_buffer;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void buffer_init(CircularBuffer *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(CircularBuffer *buf, int left, int center, int right) {
    buf->readings[buf->head].left = left;
    buf->readings[buf->head].center = center;
    buf->readings[buf->head].right = right;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) {
        buf->count++;
    }
}

static int buffer_get_left(const CircularBuffer *buf) {
    if (buf->count == 0) return -1;
    return buf->readings[(buf->head - 1 + BUFFER_SIZE) % BUFFER_SIZE].left;
}

static int buffer_get_center(const CircularBuffer *buf) {
    if (buf->count == 0) return -1;
    return buf->readings[(buf->head - 1 + BUFFER_SIZE) % BUFFER_SIZE].center;
}

static int buffer_get_right(const CircularBuffer *buf) {
    if (buf->count == 0) return -1;
    return buf->readings[(buf->head - 1 + BUFFER_SIZE) % BUFFER_SIZE].right;
}

static void motor_forward(void) {
    printf("Moving forward\n");
    fflush(stdout);
}

static void motor_backward(void) {
    printf("Moving backward\n");
    fflush(stdout);
}

static void motor_left(void) {
    printf("Turning left\n");
    fflush(stdout);
}

static void motor_right(void) {
    printf("Turning right\n");
    fflush(stdout);
}

static void check_line_and_alert(void) {
    int center_count = 0;
    for (int i = 0; i < LINE_DETECTED_COUNT; i++) {
        int center_val = gpioRead(CENTER_SENSOR_PIN);
        if (center_val == 0) {
            center_count++;
        } else {
            break;
        }
    }

    if (center_val == 0) {
        if (center_count >= LINE_DETECTED_COUNT) {
            motor_forward();
            gpioDelay(ALERT_DURATION_US);
            gpioWrite(ALERT_PIN, 0);
        }
    } else {
        gpioWrite(ALERT_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    buffer_init(&sensor_buffer);

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set left sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set center sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set right sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set alert pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(ALERT_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int left = gpioRead(LEFT_SENSOR_PIN);
        int center = gpioRead(CENTER_SENSOR_PIN);
        int right = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error reading sensor values\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        buffer_add(&sensor_buffer, left, center, right);

        if (center == 0) {
            check_line_and_alert();
        } else if (left == 0) {
            motor_left();
        } else if (right == 0) {
            motor_right();
        } else {
            motor_forward();
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

