#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x30
#define SENSOR2_ADDR   0x31
#define RELAY_GPIO     18
#define FLOW_THRESHOLD 5.0f
#define LOG_FILE       "flow_log.txt"
#define POLL_DELAY_US  100000

/* Sensirion SLF3S-1300F: start continuous measurement command (two-byte sequence) */
static const uint8_t CMD_START_MEAS[2] = {0x36, 0x00};

static volatile sig_atomic_t g_running = 1;
static int g_i2c1 = -1;
static int g_i2c2 = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF, no final XOR)          */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c1 >= 0) {
        i2cClose(g_i2c1);
        g_i2c1 = -1;
    }
    if (g_i2c2 >= 0) {
        i2cClose(g_i2c2);
        g_i2c2 = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Initialize GPIO and relay                                        */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(RELAY_GPIO) failed: %s\n", strerror(errno));
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_GPIO, 0) failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize I2C for a single sensor                                 */
/* ------------------------------------------------------------------ */
static int init_i2c(int bus, int addr)
{
    int h = i2cOpen(bus, addr, 0);
    if (h < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                bus, addr, strerror(errno));
        return -1;
    }
    return h;
}

/* ------------------------------------------------------------------ */
/* Read flow rate from one sensor                                      */
/* ------------------------------------------------------------------ */
static int read_flow_rate(int handle, float *flow_out)
{
    uint8_t buf[3];
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "I2C read failed (handle=%d): got %d bytes, expected 3\n",
                handle, n);
        return -1;
    }

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data (handle=%d)\n", handle);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 1000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log flow data with millisecond timestamp                           */
/* ------------------------------------------------------------------ */
static void log_flow_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Safety relay control                                              */
/* ------------------------------------------------------------------ */
static void control_relay(float f1, float f2)
{
    int target = (f1 >= FLOW_THRESHOLD && f2 >= FLOW_THRESHOLD) ? 1 : 0;
    if (gpioWrite(RELAY_GPIO, target) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_GPIO, %d) failed: %s\n",
                target, strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (g_i2c1 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_i2c2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (g_i2c2 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement on both sensors */
    if (i2cWriteDevice(g_i2c1, (char *)CMD_START_MEAS, 2) < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 1: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2cWriteDevice(g_i2c2, (char *)CMD_START_MEAS, 2) < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 2: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow first measurement to complete (max ~45 ms) */
    gpioDelay(50000);

    if (init_i2c(I2C_BUS, SENSOR1_ADDR) < 0 ||
        init_i2c(I2C_BUS, SENSOR2_ADDR) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring flow sensors (threshold %.1f ml/min). Press Ctrl+C to exit.\n",
           FLOW_THRESHOLD);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_flow_rate(g_i2c1, &f1) == 0);
        int ok2 = (read_flow_rate(g_i2c2, &f2) == 0);

        if (!ok1 || !ok2) {
            fprintf(stderr, "Sensor read error; skipping cycle.\n");
        } else {
            log_flow_data(f1, f2);
            control_relay(f1, f2);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

