    g_i2c2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (g_i2c2 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement on both sensors */
    if (i2cWriteDevice(g_i2c1, (char *)CMD_START_MEAS, 2) < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 1: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2cWriteDevice(g_i2c2, (char *)CMD_START_MEAS, 2) < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 2: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow first measurement to complete (max ~45 ms) */
    gpioDelay(50000);

    if (init_i2c(I2C_BUS, SENSOR1_ADDR) < 0 ||
        init_i2c(I2C_BUS, SENSOR2_ADDR) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring flow sensors (threshold %.1f ml/min). Press Ctrl+C to exit.\n",
           FLOW_THRESHOLD);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_flow_rate(g_i2c1, &f1) == 0);
        int ok2 = (read_flow_rate(g_i2c2, &f2) == 0);

        if (!ok1 || !ok2) {
            fprintf(stderr, "Sensor read error; skipping cycle.\n");
        } else {
            log_flow_data(f1, f2);
            control_relay(f1, f2);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

