#define MOTOR_IN2_PIN   24

#define MOTOR_RUN_TIME_US 5000000   /* 5 seconds in microseconds */
#define POLL_INTERVAL_US  200000    /* 200 ms */
#define DRY_THRESHOLD     3         /* consecutive dry polls before re-trigger */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    syslog(LOG_INFO, "%s", msg);
}

static void log_err(const char *msg)
{
    syslog(LOG_ERR, "%s", msg);
}

static void log_warn(const char *msg)
{
    syslog(LOG_WARNING, "%s", msg);
}

static int safe_gpio_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioWrite(%u, %u) failed", pin, level);
        log_err(buf);
        return -1;
    }
    return 0;
}

static int safe_gpio_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioRead(%u) failed", pin);
        log_err(buf);
        return -1;
    }
    return v;
}

static int motor_start(void)
{
    if (safe_gpio_write(MOTOR_ENA_PIN, 1) < 0) return -1;
    if (safe_gpio_write(MOTOR_IN1_PIN, 1) < 0) return -1;
    if (safe_gpio_write(MOTOR_IN2_PIN, 0) < 0) return -1;
    return 0;
}

static int motor_stop(void)
{
    if (safe_gpio_write(MOTOR_ENA_PIN, 0) < 0) return -1;
    if (safe_gpio_write(MOTOR_IN1_PIN, 0) < 0) return -1;
    if (safe_gpio_write(MOTOR_IN2_PIN, 0) < 0) return -1;
    return 0;
}

static int motor_run(void)
{
    if (motor_start() < 0) return -1;
    usleep(MOTOR_RUN_TIME_US);
    if (motor_stop() < 0) return -1;
    return 0;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_err("pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        log_err("gpioSetMode(RAIN_SENSOR_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        log_err("gpioSetMode(MOTOR_ENA_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        log_err("gpioSetMode(MOTOR_IN1_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        log_err("gpioSetMode(MOTOR_IN2_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        log_err("gpioSetPullUpDown(RAIN_SENSOR_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        log_err("gpioWrite(MOTOR_ENA_PIN, 0) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        log_err("gpioWrite(MOTOR_IN1_PIN, 0) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        log_err("gpioWrite(MOTOR_IN2_PIN, 0) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_err("sigaction(SIGINT) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_err("sigaction(SIGTERM) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Rain sensor monitoring started");

    int dry_count = 0;
    int rain_active = 0;

    while (g_running) {
        int rain_val = safe_gpio_read(RAIN_SENSOR_PIN);
        if (rain_val < 0) {
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (rain_val == 0) {
            dry_count++;
            if (dry_count >= DRY_THRESHOLD) {
                if (!rain_active) {
                    log_event("Rain sensor: dry for >= 3 polls, no rain detected");
                    rain_active = 1;
                }
            } else {
                dry_count = 0;
            }
        } else {
            dry_count = 0;
            rain_active = 0;
        }

        if (rain_active) {
            log_event("Rain detected (DO low)");
            if (motor_start() < 0) {
                log_err("motor_start() failed");
