#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US    50000
#define POLL_DELAY_US  10000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_servo_pulse(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "gpioServo failed for pulse %d us\n", pulse_us);
        return -1;
    }
    return 0;
}

static int lock_door(void)
{
    if (set_servo_pulse(LOCK_PULSE_US) != 0)
        return -1;
    printf("Door locked\n");
    return 0;
}

static int unlock_door(void)
{
    if (set_servo_pulse(UNLOCK_PULSE_US) != 0)
        return -1;
    printf("Door unlocked\n");
    return 0;
}

static int shutdown_door(void)
{
    if (set_servo_pulse(0) != 0)
        return -1;
    printf("Door locked (shutdown)\n");
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for SERVO_PIN %d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for LOCK_BUTTON %d\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for UNLOCK_BUTTON %d\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for LOCK_BUTTON %d\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for UNLOCK_BUTTON %d\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(LOCK_BUTTON, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFunc failed for LOCK_BUTTON %d\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(UNLOCK_BUTTON, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFunc failed for UNLOCK_BUTTON %d\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control ready. Press LOCK (GPIO %d) or UNLOCK (GPIO %d) to actuate.\n",
           LOCK_BUTTON, UNLOCK_BUTTON);
    printf("Press Ctrl+C to exit.\n");

    int last_lock_state = 0;
    int last_unlock_state = 0;
    uint32_t last_lock_press_tick = 0;
    uint32_t last_unlock_press_tick = 0;

    while (g_running) {
        uint32_t now = gpioTick();

        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        if (lock_state < 0 || unlock_state < 0) {
            fprintf(stderr, "gpioRead failed (lock=%d unlock=%d)\n", lock_state, unlock_state);
            break;
        }

        if (lock_state == 1 && last_lock_state == 0) {
            if (lock_state == 1 && last_lock_state == 0) {
                if (last_lock_press_tick == 0) {
                    last_lock_press_tick = now;
                } else if ((now - last_lock_press_tick) > DEBOUNCE_US) {
                    if (lock_door() != 0) {
                        break;
                    }
                    last_lock_press_tick = 0;
                }
            }
        } else if (lock_state == 0 && last_lock_state == 1) {
            last_lock_state = 0;
        }

        if (unlock_state == 1 && last_unlock_state == 0) {
            if (unlock_state == 1 && last_unlock_state == 0) {
                if (last_unlock_press_tick == 0) {
                    last_unlock_press_tick = now;
                } else if ((now - last_unlock_press_tick) > DEBOUNCE_US) {
                    if (unlock_door() != 0) {
                        break;
                    }
                    last_unlock_press_tick = 0;
                }
            }
        } else if (unlock_state == 0 && last_unlock_state == 1) {
            last_unlock_state = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    if (g_running == 0) {
        printf("\nShutting down...\n");
    }

    if (gpioServo(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "gpioServo failed during shutdown\n");
        return EXIT_FAILURE;
    }

    if (shutdown_door() != 0) {
        fprintf(stderr, "shutdown_door failed\n");
        return EXIT_FAILURE;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

