#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL_US 100000  /* 100 ms */
#define FLOODLIGHT_ON_DURATION_SEC 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, long long duration_sec)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (duration_sec >= 0) {
        fprintf(fp, "%s - %s - Duration: %lld seconds\n",
                timestamp, event_type, duration_sec);
    } else {
        fprintf(fp, "%s - %s\n", timestamp, event_type);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_floodlight(int duration_sec)
{
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Error setting relay pin %d HIGH\n", RELAY_PIN);
        return -1;
    }

    if (log_event("Floodlight ON", duration_sec) != 0) {
        fprintf(stderr, "Error logging floodlight activation\n");
        return -1;
    }

    /*
     * gpioDelay blocks for the given microseconds.
     * gpioDelay returns the actual elapsed time, or < 0 on error.
     */
    int elapsed = 0;
    while (elapsed < duration_sec && g_running) {
        gpioDelay(POLL_INTERVAL_US);
        elapsed += POLL_INTERVAL_US;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error setting relay pin %d LOW\n", RELAY_PIN);
        return -1;
    }

    if (log_event("Floodlight OFF", duration_sec) != 0) {
        fprintf(stderr, "Error logging floodlight deactivation\n");
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PIR pin as input */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting PIR pin %d as input\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure floodlight is OFF at startup */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing relay pin %d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security system started. Monitoring PIR on GPIO%d, relay on GPIO%d.\n",
           PIR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int floodlight_state = 0;  /* 0 = off, 1 = on */

    while (g_running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "Error reading PIR pin %d\n", PIR_PIN);
            break;
        }

        if (pir_state == 1 && floodlight_state == 0) {
            printf("Motion detected! Activating floodlight for %d seconds...\n",
                   FLOODLIGHT_ON_DURATION_SEC);

            if (activate_floodlight(FLOODLIGHT_ON_DURATION_SEC) != 0) {
                fprintf(stderr, "Error activating floodlight\n");
                break;
            }

            floodlight_state = 1;
        }

        /*
         * gpioDelay returns the actual elapsed time, or < 0 on error.
         * We use a short sleep to avoid busy-waiting.
         */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    if (floodlight_state == 1) {
        if (gpioWrite(RELAY_PIN, 0) != 0) {
            fprintf(stderr, "Error turning off floodlight during shutdown\n");
        }
    }

    gpioTerminate();
    printf("Security system stopped.\n");
    return EXIT_SUCCESS;
}

