/*
 * MPR121 Capacitive Touch Sensor - Relay Toggle
 * Board:  Raspberry Pi 5
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Relay:  GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:    sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define MPR121_ADDR          0x5B          /* MPR121 default I2C address */
#define RELAY_GPIO           17            /* BCM 17 */
#define DEBOUNCE_MS          200           /* Relay hold-off after a touch */
#define POLL_DELAY_US        10000         /* 10 ms main-loop sleep */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS   0x00
#define MPR121_ELECONFIG     0x5E
#define MPR121_SOFTRESET     0x80
#define MPR121_MHD           0x2B
#define MPR121_NHD           0x2C
#define MPR121_NCL           0x2D
#define MPR121_FDL           0x2E
#define MPR121_E0TTH         0x41
#define MPR121_E0RTH         0x42
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_AUTO_CONFIG1  0x7B
#define MPR121_AUTO_CONFIG2  0x7C
#define MPR121_AUTO_CONFIG3  0x7D
#define MPR121_AUTO_CONFIG4  0x7E
#define MPR121_AUTO_CONFIG5  0x7F
#define MPR121_AUTO_CONFIG6  0x80
#define MPR121_AUTO_CONFIG7  0x81
#define MPR121_AUTO_CONFIG8  0x82
#define MPR121_AUTO_CONFIG9  0x83
#define MPR121_AUTO_CONFIG10 0x84
#define MPR121_AUTO_CONFIG11 0x85
#define MPR121_AUTO_CONFIG12 0x86
#define MPR121_AUTO_CONFIG13 0x87
#define MPR121_AUTO_CONFIG14 0x88
#define MPR121_AUTO_CONFIG15 0x89
#define MPR121_AUTO_CONFIG16 0x8A
#define MPR121_AUTO_CONFIG17 0x8B
#define MPR121_AUTO_CONFIG18 0x8C
#define MPR121_AUTO_CONFIG19 0x8D
#define MPR121_AUTO_CONFIG20 0x8E
#define MPR121_AUTO_CONFIG21 0x8F
#define MPR121_AUTO_CONFIG22 0x90
#define MPR121_AUTO_CONFIG23 0x91
#define MPR121_AUTO_CONFIG24 0x92
#define MPR121_AUTO_CONFIG25 0x93
#define MPR121_AUTO_CONFIG26 0x94
#define MPR121_AUTO_CONFIG27 0x95
#define MPR121_AUTO_CONFIG28 0x96
#define MPR121_AUTO_CONFIG29 0x97
#define MPR121_AUTO_CONFIG30 0x98
#define MPR121_AUTO_CONFIG31 0x99
#define MPR121_ELECONFIG_12  0x80

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  mpr121_write_reg(uint8_t reg, uint8_t val);
static int  mpr121_read_reg(uint8_t reg, uint8_t *val);
static int  mpr121_init(void);
static int  mpr121_read_touch(uint16_t *touch_data);
static void relay_set(bool on);
static void cleanup(void);

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C Helpers ------------------------------- */
static int mpr121_write_reg(uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(g_i2c_handle, reg, val) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, val);
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *val)
{
    int v = i2cReadByteData(g_i2c_handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, v);
        return -1;
    }
    *val = (uint8_t)v;
    return 0;
}

/* ----------------------------- MPR121 Init ------------------------------- */
static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(10000);  /* 10 ms settle */

    /* Baseline filtering (MHD..FDL) - MPR121 datasheet defaults */
    if (mpr121_write_reg(MPR121_MHD, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL, 0x01) < 0) return -1;

    /* Touch / release thresholds for electrode 0 */
    if (mpr121_write_reg(MPR121_E0TTH, 0x0F) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0RTH, 0x0A) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* Auto-config: range 0x00, FFI=0x00, SFI=0x00, CDT=0x00 */
    if (mpr121_write_reg(MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG2, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG3, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG4, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG5, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG6, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG7, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG8, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG9, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG10, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG11, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG12, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG13, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG14, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG15, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG16, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG17, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG18, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG19, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG20, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG21, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG22, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG23, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG24, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG25, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG26, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG27, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG28, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG29, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG30, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG31, 0x00) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, no auto-config */
    if (mpr121_write_reg(MPR121_ELECONFIG, MPR121_ELECONFIG_12) < 0)
        return -1;

    /* Verify configuration by reading back */
    uint8_t cfg;
    if (mpr121_read_reg(MPR121_ELECONFIG, &cfg) < 0)
        return -1;
    if (cfg != MPR121_ELECONFIG_12) {
        fprintf(stderr, "[ERROR] ELECONFIG mismatch: got 0x%02X, expected 0x%02X\n",
                cfg, MPR121_ELECONFIG_12);
        return -1;
    }

    return 0;
}

/* ----------------------------- Touch Read --------------------------------- */
static int mpr121_read_touch(uint16_t *touch_data)
{
    char buf[2];
    if (i2cReadI2CBlockData(g_i2c_handle, MPR121_TOUCHSTATUS, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(TOUCHSTATUS) failed\n");
        return -1;
    }
    *touch_data = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

/* ----------------------------- Relay Control ----------------------------- */
static void relay_set(bool on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) < 0)
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed\n", RELAY_GPIO, on ? 1 : 0);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    /* Ensure relay is OFF */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
