#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <gpiod.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define BUFFER_SIZE 1024
#define PWM_FREQ 50
#define PWM_PERIOD_US (1000000 / PWM_FREQ)
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define LOG_FILE "security.log"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_message(const char *level, const char *msg, ...) {
    va_list args;
    va_start(args, msg);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(stderr, "[%s] [%s] ", ts, level);
    vfprintf(stderr, msg, args);
    fprintf(stderr, "\n");
    va_end(args);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line %d: %s", SERVO_PIN, strerror(errno));
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_socket(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }
    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        close(fd);
        return -1;
    }
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return -1;
    }
    setvbuf(log_file, NULL, _IOLBF, 0);
    return 0;
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (servo_line) {
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid servo angle %d", angle);
        return -1;
    }
    int pulse = SERVO_MIN_PULSE + (int)((float)angle / 180.0f * (float)(SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_message(LOG_ERR, "Failed to set servo high: %s", strerror(errno));
        return -1;
    }
    usleep(pulse);
    if (gpiod_line_set_value(servo_line, 0) < 0) {
        log_message(LOG_ERR, "Failed to set servo low: %s", strerror(errno));
        return -1;
    }
    usleep(PWM_PERIOD_US - pulse);
    return 0;
}

static int read_pir(void) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        log_message(LOG_ERR, "Failed to read PIR: %s", strerror(errno));
        return -1;
    }
    return val;
}

static void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t n = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
    if (n <= 0) {
        close(client_fd);
        return;
    }
    buffer[n] = '\0';
    char *token = strtok(buffer, " \r\n");
    if (!token) {
        send(client_fd, "Invalid command\n", 14, 0);
        close(client_fd);
        return;
    }
    if (strcmp(token, "the library's api call") == 0) {
        token = strtok(NULL, " \r\n");
        if (!token) {
            send(client_fd, "Invalid argument\n", 16, 0);
            close(client_fd);
            return;
        }
        int angle = atoi(token);
        if (angle < 0 || angle > 180) {
            send(client_fd, "Angle must be 0-180\n", 20, 0);
            close(client_fd);
            return;
        }
        if (set_servo_angle(angle) < 0) {
            send(client_fd, "Servo set failed\n", 15, 0);
            close(client_fd);
            return;
        }
        char resp[64];
        snprintf(resp, sizeof(resp), "Servo set to %d\n", angle);
        send(client_fd, resp, strlen(resp), 0);
    } else if (strcmp(token, "PIR") == 0) {
        int val = read_pir();
        if (val < 0) {
            send(client_fd, "PIR read failed\n", 15, 0);
            close(client_fd);
            return;
        }
        char resp[32];
        snprintf(resp, sizeof(resp), "PIR: %d\n", val);
        send(client_fd, resp, strlen(resp), 0);
    } else {
        send(client_fd, "Unknown command\n", 17, 0);
    }
    close(client_fd);
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (init_gpio() < 0) {
        log_message(LOG_ERR, "GPIO init failed, exiting");
        closelog();
        return 1;
    }
    if (init_socket() < 0) {
        log_message(LOG_ERR, "Socket init failed, exiting");
        cleanup();
        closelog();
        return 1;
    }
    if (init_log() < 0) {
        log_message(LOG_ERR, "Log init failed, exiting");
        cleanup();
        closelog();
        return 1;
    }
    server_fd = accept(server_fd, NULL, NULL);
    if (server_fd < 0) {
        log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
        cleanup();
        closelog();
        return 1;
    }
    log_message(LOG_INFO, "Server started on port %d\n", PORT);
    while (running) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            break;
        }
        handle_client(client_fd);
    }
    log_message(LOG_INFO, "Server shutting down\n");
    cleanup();
    closelog();
    return 0;
}

