#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x54
#define BH1750_CMD_TRIG 0x10
#define BH1750_CMD_READ 0x24
#define BH1750_CONV_MS 120
#define LUX_THRESHOLD  150
#define RELAY_GPIO     23
#define LOG_FILE       "grow_log.txt"
#define SAMPLE_PERIOD  2
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise relay GPIO %d low\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out)
{
    char cmd = BH1750_CMD_TRIG;
    char buf[2];

    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) < 0) {
        fprintf(stderr, "Error: I2C write trigger failed\n");
        return -1;
    }

    gpioDelay(BH1750_CONV_MS * 1000);

    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C read conversion failed\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int control_relay(int on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "Error: failed to write relay GPIO %d\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static void log_data(float lux)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, Lux: %.2f\n", ts, lux) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    control_relay(0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BH1750 grow-light controller started. Logging to %s\n", LOG_FILE);
    printf("Threshold: %.0f lux, Relay GPIO: %d\n", LUX_THRESHOLD, RELAY_GPIO);

    while (g_running) {
        float lux = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_lux(&lux) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(100000);
        }

        if (ok) {
            int relay_state = (lux < LUX_THRESHOLD) ? 1 : 0;
            if (control_relay(relay_state) == 0) {
                log_data(lux);
            } else {
                fprintf(stderr, "Warning: relay control failed, continuing\n");
            }
        } else {
            fprintf(stderr, "Error: BH1750 read failed after %d attempts\n", MAX_RETRIES);
        }

        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

