#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN  24
#define SOLENOID_PIN   25

#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE     1.0f
#define DEFAULT_DURATION  200
#define HX711_TIMEOUT_US  1000000
#define NUM_READINGS      5
#define MAX_RETRIES       3
#define POLL_INTERVAL_US  500000
#define SCALE_FACTOR      1.0f
#define SOLENOID_ON_US    200000
#define SCALE_FACTOR_ARG  2
#define DURATION_ARG     300

static volatile sig_atomic_t g_running = 1;
static int g_scale_factor = 1.0f;
static int g_duration = DEFAULT_DURATION;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    closelog();
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(HX711_DOUT_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set HX711 DOUT pin %d as input", HX711_DOUT_PIN);
        return -1;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set HX711 SCK pin %d as output", HX711_SCK_PIN);
        return -1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid pin %d as output", SOLENOID_PIN);
        return -1;
    }

    gpioWrite(HX711_SCK_PIN, 0);
    gpioWrite(SOLENOID_PIN, 0);
    return 0;
}

static int read_hx711(int32_t *out) {
    int i;
    int timeout = HX711_TIMEOUT_US;

    /* Wait for DOUT to go LOW (data ready) */
    while (gpioRead(HX711_DOUT_PIN) == 1) {
        if (timeout <= 0) {
            syslog(LOG_ERR, "HX711 timeout: DOUT stuck HIGH");
            return -1;
        }
        gpioDelay(100);
        timeout--;
    }

    uint32_t data = 0;
    for (i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK high");
            return -1;
        }
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DOUT_PIN) == 1) {
            data |= 1;
        }
        if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK low");
            return -1;
        }
        gpioDelay(1);
    }

    /* 25th clock pulse: select Channel A, gain 128 */
    if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set SCK high (25th pulse)");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SCK low (25th pulse)");
        return -1;
    }
    gpioDelay(1);

    /* Convert 24-bit two's complement to int32_t */
    if (data & 0x800000) {
        data |= 0xFF000000;
    }
    *out = (int32_t)data;
    return 0;
}

static float calculate_weight(int32_t raw, float scale_factor) {
    return (float)raw * scale_factor;
}

static void control_solenoid(int duration_ms) {
    gpioWrite(SOLENOID_PIN, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(SOLENOID_PIN, 0);
}

static void perform_tare(int32_t *raw_sum, int num_readings) {
    int i, sum = 0;
    for (i = 0; i < num_readings; i++) {
        int32_t raw;
        if (read_hx711(&raw) != 0) {
            syslog(LOG_ERR, "Tare read failed, retrying...");
            gpioDelay(100000);
            continue;
        }
        sum += raw;
        gpioDelay(100000);
    }
    *raw_sum = sum / num_readings;
}

static void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s [options]\n", prog);
    fprintf(stderr, "  --threshold <grams>  Threshold weight in grams (default: %d)\n", DEFAULT_THRESHOLD);
    fprintf(stderr, "  --scale <factor>    Scale factor for weight conversion (default: %f)\n", g_scale_factor);
    fprintf(stderr, "  --duration <ms>     Duration to hold solenoid lock (default: %d)\n", g_duration);
    fprintf(stderr, "  --help              Show this help message\n");
}

int main(int argc, char *argv[]) {
    int opt;
    int32_t raw_sum = 0;
    int i;
    int32_t raw;
    float weight;
    int tare_ok = 0;

