        cleanup();
        return 1;
    }

    if (perform_tare(&raw_sum, NUM_READINGS) != 0) {
        syslog(LOG_ERR, "Tare failed, exiting");
        cleanup();
        return 1;
    }
    tare_ok = 1;

    syslog(LOG_INFO, "Tare complete, starting monitoring loop");

    while (g_running) {
        int32_t raw_reading = 0;
