#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_KEEP_ALIVE_INTERVAL 60
#define MQTT_RECONNECT_DELAY 5
#define MQTT_QOS 0

#define GPIO_PIN 17
#define GPIO_PIN_ACTIVE_HIGH 0

static volatile sig_atomic_t g_running = 1;
static int g_mqtt_client_id = -1;
static int g_mqtt_client_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO17 as output");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GPIO_PIN, PI_LOW) != 0) {
        log_error("Failed to initialise GPIO17 to LOW");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int mqtt_connect(void) {
    int rc;

    if (g_mqtt_client_id < 0) {
        g_mqtt_client_id = gpioCreateClientHandle(0);
        if (g_mqtt_client_id < 0) {
            log_error("Failed to create MQTT client handle");
            return -1;
        }
    }

    rc = mqtt_connect(g_mqtt_client_id, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_CLIENT_ID, MQTT_QOS);
    if (rc != 0) {
        log_error("Failed to connect to MQTT broker");
        return -1;
    }

    log_message(LOG_INFO, "Connected to MQTT broker");
    return 0;
}

static int mqtt_subscribe(void) {
    int rc;

    rc = mqtt_subscribe(g_mqtt_client_id, MQTT_TOPIC);
    if (rc != 0) {
        log_error("Failed to subscribe to MQTT topic");
        return -1;
    }

    log_message(LOG_INFO, "Subscribed to MQTT topic");
    return 0;
}

static void mqtt_callback(void *context, char *topic, int topicLen, char *payload, int payloadLen) {
    (void)context;
    (void)topicLen;

    if (payloadLen > 0) {
        if (payload[0] == '\0') {
            log_error("MQTT payload is empty");
            return;
        }

        if (strcmp(payload, "ON") == 0) {
            if (gpioWrite(GPIO_PIN, PI_HIGH) != 0) {
                log_error("Failed to set GPIO17 HIGH");
            } else {
                log_message(LOG_INFO, "Relay ON");
            }
        } else if (strcmp(payload, "OFF") == 0) {
            if (gpioWrite(GPIO_PIN, PI_LOW) != 0) {
                log_error("Failed to set GPIO17 LOW");
            } else {
                log_message(LOG_INFO, "Relay OFF");
            }
        } else {
            log_error("Invalid MQTT payload received");
        }
    } else {
        log_error("MQTT payload is empty");
    }
}

static void mqtt_disconnect(void) {
    log_message(LOG_INFO, "Received MQTT disconnect");
    if (g_mqtt_client_handle >= 0) {
        mqtt_disconnect(g_mqtt_client_handle);
        g_mqtt_client_handle = -1;
    }
}

static void mqtt_reconnect(void) {
    log_message(LOG_INFO, "Attempting MQTT reconnection...");
    if (g_mqtt_client_handle >= 0) {
        mqtt_disconnect(g_mqtt_client_handle);
        g_mqtt_client_handle = -1;
    }

    sleep(MQTT_RECONNECT_DELAY);

    if (initialize_gpio() != 0) {
        log_error("GPIO initialisation failed during reconnect");
        return;
    }

    if (mqtt_connect() != 0) {
        log_error("MQTT connect failed during reconnect");
        return;
    }

    if (mqtt_subscribe() != 0) {
        log_error("MQTT subscribe failed during reconnect");
        return;
    }
}

static void cleanup(void) {
    log_message(LOG_INFO, "Cleaning up...");

    if (g_mqtt_client_handle >= 0) {
        mqtt_disconnect(g_mqtt_client_handle);
        g_mqtt_client_handle = -1;
    }

    if (g_mqtt_client_id >= 0) {
        mqtt_destroy(g_mqtt_client_id);
        g_mqtt_client_id = -1;
    }

    gpioWrite(GPIO_PIN, PI_LOW);
    gpioTerminate();

    log_message(LOG_INFO, "Cleanup complete");
    closelog();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_error("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to register SIGTERM handler");
        return 1;
    }

    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    if (initialize_gpio() != 0) {
        log_error("GPIO initialisation failed");
        closelog();
        return 1;
    }

    if (mqtt_connect() != 0) {
        log_error("MQTT connect failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    if (mqtt_subscribe() != 0) {
        log_error("MQTT subscribe failed");
        mqtt_disconnect();
        gpioTerminate();
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Relay controller started");

    while (g_running) {
        int rc = mqtt_loop(g_mqtt_client_handle, -1, 0);
        if (rc == 0) {
            sleep(1);
        } else {
            log_error("MQTT loop error");
            mqtt_disconnect();
            sleep(MQTT_RECONNECT_DELAY);
            mqtt_reconnect();
        }
    }

    cleanup();
    return 0;
}

