#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define SERVO1 7
#define SERVO2 8
#define SERVO3 9
#define SERVO4 10
#define SERVO5 11

#define PWM_FREQUENCY 50
#define PWM_RANGE 1000000
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_STOP_PULSE_WIDTH 1500
#define SERVO_SETTLE_TIME_MS 3000

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int servos[] = {SERVO1, SERVO2, SERVO3, SERVO4, SERVO5};
    int pulse_widths[] = {SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH,
                          SERVO_MAX_PULSE_WIDTH, SERVO_MIN_PULSE_WIDTH,
                          SERVO_MAX_PULSE_WIDTH};
    int num_servos = 5;

    for (int i = 0; i < num_servos; i++) {
        if (gpioServo(servos[i], pulse_widths[i]) < 0) {
            fprintf(stderr, "Error: gpioServo failed for servo %d (PWM_RANGE=%d, pulse=%d)\n",
                    i, PWM_RANGE, pulse_widths[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Servo positions set. Holding for %d ms...\n", SERVO_SETTLE_TIME_MS);
    gpioDelay(SERVO_SETTLE_TIME_MS * 1000);

    for (int i = 0; i < num_servos; i++) {
        gpioServo(servos[i], SERVO_STOP_PULSE_WIDTH);
    }

    gpioTerminate();
    printf("Servo PWM stopped. Exiting.\n");
    return EXIT_SUCCESS;
}

