#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN    27
#define DEBOUNCE_US     1000000  /* 1 second debounce window */
#define SAMPLE_US       1000000  /* 1 second sampling interval */
#define LOG_FILE        "water_flow.log"

/* Hysteresis thresholds (LPM) */
#define HYSTERESIS_LOW   4.5f
#define HYSTERESIS_HIGH  5.0f

/* Global state */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; defer cleanup to main()            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped line to the log file                           */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");

    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure pins                                */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set FLOW_SENSOR_PIN %d as input.\n",
                FLOW_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SOLENOID_PIN %d as output.\n",
                SOLENOID_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start with solenoid open (HIGH) */
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to initialise SOLENOID_PIN %d HIGH.\n",
                SOLENOID_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* ISR callback — counts rising edges (flow pulses)                   */
/* ------------------------------------------------------------------ */
static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    pthread_mutex_lock(&pulse_mutex);
    int *count = (int *)userdata;
    (*count)++;
    pthread_mutex_unlock(&pulse_mutex);
}

/* ------------------------------------------------------------------ */
/* Read the current pulse count                                    */
/* ------------------------------------------------------------------ */
static int read_pulse_count(void)
{
    int count = 0;
    pthread_mutex_lock(&pulse_mutex);
    count = *(int *)userdata;
    pthread_mutex_unlock(&pulse_mutex);
    return count;
}

/* ------------------------------------------------------------------ */
/* Calculate LPM from the pulse count                                */
/* ------------------------------------------------------------------ */
static float calculate_lpm(int pulses, int interval_us)
{
    if (interval_us <= 0)
        return 0.0f;

    float liters = (float)pulses * (interval_us / 1000000.0f) / 60.0f;
    return liters / 1000.0f;
}

/* ------------------------------------------------------------------ */
/* Control the solenoid valve                                         */
/* ------------------------------------------------------------------ */
static void control_solenoid(float lpm)
{
    int desired = (lpm > HYSTERESIS_HIGH) ? 0 : 1; /* 0 = off, 1 = on */

    if (gpioWrite(SOLENOID_PIN, desired) < 0) {
        fprintf(stderr, "Warning: failed to write SOLENOID_PIN %d.\n",
                SOLENOID_PIN);
        return;
    }

    char msg[128];
    snprintf(msg, sizeof(msg),
             "Solenoid %s (LPM: %.2f) — GPIO %d",
             desired ? "ON" : "OFF", lpm, SOLENOID_PIN);
    log_event(msg);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure solenoid is off before releasing resources */
    if (gpioWrite(SOLENOID_PIN, 0) < 0)
        fprintf(stderr, "Warning: failed to reset SOLENOID_PIN %d.\n",
                SOLENOID_PIN);

    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&pulse_mutex);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
