/*
 * TTP223 capacitive touch sensor → 5 V relay toggle
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (GPIO bus only)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay [-d ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN      4
#define RELAY_PIN      17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_DELAY_US  10000   /* 10 ms  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void log_timestamp(void)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("%s Relay: %s\n", ts,
               (gpioRead(RELAY_PIN) == 1) ? "OFF" : "ON");
    } else {
        printf("UNKNOWN Relay: %s\n",
               (gpioRead(RELAY_PIN) == 1) ? "OFF" : "ON");
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int debounce_ms = DEFAULT_DEBOUNCE_MS;

    /* ---- Parse command-line argument -------------------------------- */
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            int v = atoi(argv[++i]);
            if (v > 0)
                debounce_ms = v;
            else {
                fprintf(stderr,
                        "Invalid debounce value: %s\n", argv[i]);
                return EXIT_FAILURE;
            }
        } else {
            fprintf(stderr,
                    "Usage: %s [-d ms]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* ---- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure pins --------------------------------------------- */
    if (safe_set_mode(TOUCH_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts in the OFF state */
    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ------------------------------------ */
    install_signal_handlers();

    printf("Touch sensor monitoring started.\n");
    printf("  Touch: GPIO%d (rising edge = relay ON)\n", TOUCH_PIN);
    printf("  Relay: GPIO%d\n", RELAY_PIN);
    printf("  Debounce: %d ms\n", debounce_ms);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop -------------------------------------------------- */
    int relay_state = 0;   /* 0 = OFF, 1 = ON */

    while (g_running) {
        int touch = gpioRead(TOUCH_PIN);
        if (touch < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", TOUCH_PIN);
            break;
        }

        if (touch == 1) {
            /* Rising edge: touch detected → toggle relay */
            relay_state = !relay_state;
            if (safe_write(RELAY_PIN, relay_state) != 0)
                break;
            log_timestamp();
            gpioDelay(debounce_ms * 1000);   /* debounce */
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---------------------------------------------------- */
    gpioWrite(RELAY_PIN, 0);   /* best-effort */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

