 *
 * Hardware PWM: 50 Hz, 20 ms period.
 *
 * Build:  gcc -O2 -Wall -Wextra -o servo_angle servo_angle.c -lpigpio -lrt
 * Run:    sudo ./servo_angle
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18          /* BCM 18, physical pin 12 */
#define PWM_FREQ_HZ    50          /* 50 Hz hardware PWM */
#define PWM_RANGE_US   20000       /* 20 ms period -> 50 Hz */
#define MIN_PULSE_US   500         /* SG90 minimum pulse width */
#define MAX_PULSE_US   2500        /* SG90 maximum pulse width */
#define ANGLE_MIN      0
#define ANGLE_MAX      180
#define STEP_SIZE      10

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and pigpio is clean-up'd */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Restore pigpio state on exit so the library is not left in an
 * inconsistent state.
 *
 * pigpio's API calls are async-signal-safe, so we only need to
 * restore the library state and let the callback return.
 * ------------------------------------------------------------------ */
static void cleanup_pigpio(void)
{
    /* Stop PWM pulses on the servo pin */
    gpioPWM(SERVO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Compute the pulse width (µs) for the given angle.
 *
 * SG90:  0°  -> 1500 µs,  90° -> 2500 µs,  180° -> 1500 µs
 * ------------------------------------------------------------------ */
static int angle_to_pulse_us(int angle)
{
    if (angle < ANGLE_MIN) angle = ANGLE_MIN;
    if (angle > ANGLE_MAX) angle = ANGLE_MAX;

    int pw = MIN_PULSE_US +
             (int)((long)angle * (MAX_PULSE_US - MIN_PULSE_US) /
                  (ANGLE_MAX - ANGLE_MIN));

    if (pw < MIN_PULSE_US) pw = MIN_PULSE_US;
    if (pw > MAX_PULSE_US) pw = MAX_PULSE_US;
    return pw;
}

/* ------------------------------------------------------------------ */
/* Set the servo pulse width and print the angle.
 *
 * gpioPWM() returns 0 on success, non-zero on failure.
 * ------------------------------------------------------------------ */
static void set_servo_angle(int angle)
{
    int pw = angle_to_pulse_us(angle);

    if (gpioPWM(SERVO_PIN, pw) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for angle %d° (pw=%d µs)\n",
                angle, pw);
        cleanup_pigpio();
        exit(EXIT_FAILURE);
    }

    printf("Servo angle: %d°  (pulse width: %d µs)\n", angle, pw);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO18 for hardware PWM --- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SERVO_PIN);
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n",
                SERVO_PIN);
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE_US) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n",
                SERVO_PIN);
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    /* Start with the servo at 90° */
    set_servo_angle(90);

    /* --- Main loop --- */
    int angle = 90;
    char key;

    while (g_running) {
        key = getchar();

        if (key == EOF) {
            /* EOF on stdin means the terminal is closed */
            break;
        }

        if (key == 'q' || key == 'Q') {
            g_running = 0;
            break;
        }

        if (key == '+' || key == '+') {
            angle += STEP_SIZE;
            if (angle > ANGLE_MAX) angle = ANGLE_MAX;
            set_servo_angle(angle);
        } else if (key == '-' || key == '-') {
            angle -= STEP_SIZE;
            if (angle < ANGLE_MIN) angle = ANGLE_MIN;
            set_servo_angle(angle);
        }
    }

    /* --- Clean shutdown --- */
    cleanup_pigpio();
    return EXIT_SUCCESS;
}

