#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define HALL_SENSOR_PIN 17
#define DEBOUNCE_US     2000   /* 2 ms debounce window */
#define LOG_INTERVAL_S  5
#define LOG_FILE        "motor_rpm.log"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_rpm(FILE *fp, double rpm)
{
    char ts[32];
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_buf;
    if (localtime_r(&now, &tm_buf) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_buf) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                           */
/* ------------------------------------------------------------------ */
static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(HALL_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", HALL_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    /* Internal pull-up bias so the line is defined when the magnet
       is absent (idle state). */
    if (gpioSetPullUpDown(HALL_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", HALL_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    /* Edge-triggered event detection on rising edges. */
    if (gpioSetAlertFuncEx(HALL_SENSOR_PIN,
                           (gpioAlertFuncEx_t)hall_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed for pin %d\n", HALL_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Hall-sensor callback (runs in pigpio callback thread)                */
/* ------------------------------------------------------------------ */
static void hall_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;

    if (level != 1) {
        return;  /* only rising edges */
    }

    static uint64_t last_tick = 0;
    uint64_t now_tick = (uint64_t)tick;
    uint64_t elapsed;

    if (now_tick >= last_tick) {
        elapsed = now_tick - last_tick;
    } else {
        elapsed = (0xFFFFFFFFu - last_tick) + now_tick + 1u;
    }

    if (elapsed < DEBOUNCE_US) {
        return;  /* within debounce window */
    }

    last_tick = now_tick;

    /*
     * RPM = (pulses / interval) * (60 s/min) / (pulses per revolution)
     *
     * For a two-pole magnet the sensor idles (magnet absent) and
     * switches to the opposite polarity when the magnet rotates
     * one revolution.  The sensor idles for the first DEBOUNCE_US
     * and then pulses once per revolution.  Hence:
     *
     *   pulses = (last_tick - first_tick) / (DEBOUNCE_US + interval_us)
     *             + 1
     *
     * where first_tick is the tick of the first rising edge after
     * the debounce window.  The first edge is discarded; the count
     * is the number of edges that occurred during the log interval.
     */
    double rpm = 0.0;
    if (last_tick != 0) {
        double interval_s = (double)(LOG_INTERVAL_S * 1000000.0);
        double pulses = (double)(last_tick - 0) / interval_s;
        rpm = pulses * 60.0 / (pulses + 1.0);
    }

    if (log_rpm(g_log_fp, rpm) != 0) {
        fprintf(stderr, "Failed to log RPM value\n");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring conveyor-belt RPM on GPIO %d. Press Ctrl+C to exit.\n",
           HALL_SENSOR_PIN);

    while (g_running) {
        gpioDelay(LOG_INTERVAL_S * 1000000);  /* 5 s */
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(HALL_SENSOR_PIN, NULL, NULL);  /* unregister callback */
    gpioTerminate();

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    return EXIT_SUCCESS;
}

