#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000
#define CONTINUOUS_TIMEOUT_S 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch pin %d as input\n", TOUCH_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay pin %d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_touch_sensor(void) {
    return gpioRead(TOUCH_PIN);
}

static int set_relay_state(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write relay pin %d to %d\n", RELAY_PIN, state);
        return -1;
    }
    return 0;
}

static int toggle_relay(void) {
    int current = gpioRead(RELAY_PIN);
    if (current < 0) {
        fprintf(stderr, "Failed to read relay pin %d\n", RELAY_PIN);
        return -1;
    }
    if (set_relay_state(current ? 0 : 1) != 0) {
        return -1;
    }
    return 0;
}

static int continuous_touch_detected(void) {
    int touch_state = read_touch_sensor();
    if (touch_state < 0) {
        fprintf(stderr, "Error reading touch sensor\n");
        return 0;
    }
    if (touch_state == 1) {
        return 1;
    }
    return 0;
}

static int force_relay_off(void) {
    if (set_relay_state(0) != 0) {
        fprintf(stderr, "Failed to force relay OFF\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int continuous_touch_active = 0;
    int last_touch_state = 0;
    uint32_t continuous_touch_start_tick = 0;

    while (running) {
        int touch_state = read_touch_sensor();
        if (touch_state < 0) {
            fprintf(stderr, "Error reading touch sensor\n");
            break;
        }

        if (touch_state == 1 && !continuous_touch_active) {
            if (toggle_relay() != 0) {
                break;
            }
            if (continuous_touch_detected()) {
                if (continuous_touch_active) {
                    if (force_relay_off() != 0) {
                        break;
                    }
                    continuous_touch_active = 0;
                }
            } else {
                continuous_touch_active = 1;
                continuous_touch_start_tick = gpioTick();
            }
        }

        if (continuous_touch_active) {
            uint32_t current_tick = gpioTick();
            if (current_tick - continuous_touch_start_tick > (uint32_t)(CONTINUOUS_TIMEOUT_S * 1000000)) {
                if (relay_state == 1) {
                    if (force_relay_off() != 0) {
                        break;
                    }
                    relay_state = 0;
                }
            }
        }

        usleep(POLL_DELAY_US);
    }

    if (relay_state == 1) {
        if (set_relay_state(0) != 0) {
            fprintf(stderr, "Failed to set relay OFF during cleanup\n");
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

