/*
 * Closed-loop proportional solenoid valve flow control
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (hardware PWM + ISR on GPIO 24)
 *
 * Wiring:
 *   GPIO 18 (BCM)  -> ASCO RedHat 8210 PWM in
 *   GPIO 23 (BCM)  -> ASCO RedHat 8210 valve control
 *   GPIO 24 (BCM)  -> YF-S201 flow sensor
 *
 * Build:  gcc -O2 -Wall -o flow_control flow_control.c -lpigpio -lrt
 * Run:    ./flow_control -t 0.5
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_ENABLE_PIN    23
#define FLOW_SENSOR_PIN     24
#define PWM_PIN             18

#define PWM_FREQUENCY       1000          /* Hz */
#define PWM_RANGE           255           /* duty 0..255 */
#define SAMPLE_PERIOD_US    100000        /* 100 ms */
#define KP                  1.0

#define LOG_FILE_NAME       "flow_log.csv"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR: count rising edges on FLOW_SENSOR_PIN                          */
/* ------------------------------------------------------------------ */
static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    static uint32_t last_tick = 0;
    uint32_t now = gpioTick();
    if (now - last_tick < SAMPLE_PERIOD_US)
        return;
    last_tick = now;

    /* YF-S201: 0 V = 0 L/min, 3.3 V = 1000 L/min */
    float flow_rate = (float)(now - last_tick) / (float)SAMPLE_PERIOD_US * 1000.0f;

    /* Clamp to valid range */
    if (flow_rate < 0.0f) flow_rate = 0.0f;
    if (flow_rate > 1000.0f) flow_rate = 1000.0f;

    /* Log with timestamp */
    time_t now_ts = time(NULL);
    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now_ts, &tm_buf);
    char ts_str[32];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(g_log_fp, "%s,%.2f,%.2f\n", ts_str, flow_rate, 0.0f);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure valve is off */
    if (gpioInitialise() >= 0) {
        gpioWrite(VALVE_ENABLE_PIN, 0);
        gpioTerminate();
    }

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <flow_rate_L/min>\n", argv[0]);
        return EXIT_FAILURE;
    }

    float target_flow_rate = atof(argv[1]);
    if (target_flow_rate <= 0.0f) {
        fprintf(stderr, "Invalid flow rate: %.2f L/min\n", target_flow_rate);
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_ENABLE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable valve at startup */
    if (gpioWrite(VALVE_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", VALVE_ENABLE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* PWM: frequency 1 kHz, range 0..255 */
    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- ISR registration ---- */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on GPIO %d\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE_NAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target: %.2f L/min\n", target_flow_rate);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        /* Read current flow rate */
        float flow_rate = (float)gpioRead(FLOW_SENSOR_PIN);
        if (flow_rate < 0.0f) {
            fprintf(stderr, "Warning: failed to read flow sensor\n");
            flow_rate = 0.0f;
        }

        /* Proportional control */
        float error = target_flow_rate - flow_rate;
        float duty = KP * error;

        /* Clamp to valid range */
        if (duty < 0.0f) duty = 0.0f;
        if (duty > PWM_RANGE) duty = PWM_RANGE;

        /* Set PWM duty cycle */
        if (gpioPWM(PWM_PIN, (int)duty) != 0) {
            fprintf(stderr, "gpioPWM failed on GPIO %d\n", PWM_PIN);
            break;
        }

        /* Log with timestamp */
        time_t now_ts = time(NULL);
        struct tm tm_buf;
        struct tm *tm_info = localtime_r(&now_ts, &tm_buf);
        char ts_str[32];
        strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(g_log_fp, "%s,%.2f,%.2f\n", ts_str, flow_rate, duty);
        fflush(g_log_fp);

        printf("Flow: %.2f L/min  Valve: %.2f  Duty: %.2f\n",
               flow_rate, duty, (duty / PWM_RANGE) * 100.0f);

        /* Sleep for the remainder of the sample period */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    cleanup();
    return EXIT_SUCCESS;
}

