#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define BUTTON_GPIO 22
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 100000
#define LOG_FILE "/var/log/door_access.log"
#define DEBOUNCE_MS 50
#define ENGAGE_DELAY_S 5
#define POLL_DELAY_US 100000
#define MAX_SPI_RETRIES 4

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (log_fp) {
        fprintf(log_fp, "%s %s\n", ts, msg);
        fflush(log_fp);
    }
    fprintf(stderr, "%s %s\n", ts, msg);
}

static int spi_read_rfid(uint8_t *data, int len) {
    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (data && (len > 0)) {
            memset(data, 0, len);
        }
        int ret = call(spi_fd, SPI_READ, len, data);
        if (ret == len) return 0;
        if (ret < 0) {
            log_event("SPI read error");
        } else {
            log_event("SPI read short read");
        }
        usleep(10000);
    }
    return -1;
}

static int rfid_valid(const uint8_t *data) {
    if (data[0] != 0x42 || data[1] != 0x4D) {
        return 0;
    }
    for (int i = 2; i < 10; i++) {
        if (data[i] != 0x30 && data[i] != 0x31) return 0;
    }
    return 1;
}

static int engage_locks(void) {
    if (gpioWrite(LOCK1_GPIO, 0) < 0) return -1;
    if (gpioWrite(LOCK2_GPIO, 0) < 0) return -1;
    log_event("Locks engaged");
    return 0;
}

static int disengage_locks(void) {
    if (gpioWrite(LOCK1_GPIO, 1) < 0) return -1;
    if (gpioWrite(LOCK2_GPIO, 1) < 0) return -1;
    log_event("Locks disengaged");
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        call(spi_fd, SPI_CLOSE, 0);
        spi_fd = -1;
    }
    if (gpioWrite(LOCK1_GPIO, 1) < 0) {
        log_event("Failed to force lock1 engaged");
    }
    if (gpioWrite(LOCK2_GPIO, 1) < 0) {
        log_event("Failed to force lock2 engaged");
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK2_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "GPIO mode set failed\n");
        cleanup();
        return 1;
    }
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI mode set failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI bits per word failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI speed set failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_event("Door access control system started");

    while (running) {
        uint8_t data[10];
        if (spi_read_rfid(data, sizeof(data)) != 0) {
            log_event("RFID read timeout");
            usleep(POLL_DELAY_US);
            continue;
        }
        if (rfid_valid(data)) {
            log_event("RFID tag read");
            if (gpioRead(BUTTON_GPIO) == 0) {
                if (engage_locks() == 0) {
                    usleep(ENGAGE_DELAY_S * 1000000);
                    disengage_locks();
                }
            }
        } else {
            log_event("Invalid RFID tag");
        }
        usleep(POLL_DELAY_US);
    }

    log_event("Shutting down");
    cleanup();
    return 0;
}

