#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

/* Motor 1 */
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

/* Motor 2 */
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

/* Encoders */
#define ENC1_A 5
#define ENC1_B 6
#define ENC2_A 26
#define ENC2_B 19

/* PID parameters */
#define KP 1.0
#define KI 0.01
#define KD 0.1
#define TARGET_RPM 60.0
#define SAMPLE_TIME_US 100000  /* 100 ms */
#define PWM_FREQ_HZ 100
#define PWM_RANGE 1000

/* Global state */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

/* Encoder state */
static volatile int enc1_count = 0;
static volatile int enc2_count = 0;
static volatile bool enc1_dir = true;
static volatile bool enc2_dir = true;

/* PID state */
static double pid_p = 0.0, pid_i = 0.0, pid_d = 0.0;
static double pid_prev_error = 0.0;

/* Function prototypes */
static void signal_handler(int sig);
static void cleanup(void);
static void *encoder_thread(void *arg);
static void *pid_thread(void *arg);
static void motor_stop(void);
static void motor_forward(int speed);
static void motor_backward(int speed);
static void motor_stop_all(void);
static void set_motor_speed(int motor, int speed);
static void update_pid(double current_speed, double target_speed);
static void log_data(double motor1_speed, double motor2_speed,
                     double pid_p, double pid_i, double pid_d, double pid_output);

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    motor_stop_all();
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&log_mutex);
}

/* Encoder thread: reads quadrature encoder A and B lines, updates count */
static void *encoder_thread(void *arg) {
    (void)arg;
    while (running) {
        int a = gpioRead(ENC1_A);
        int b = gpioRead(ENC1_B);
        if (a < 0 || b < 0) {
            fprintf(stderr, "Encoder read error (ENC1): a=%d b=%d\n", a, b);
            gpioDelay(SAMPLE_TIME_US);
            continue;
        }
        if (a && !b) enc1_count++;
        else if (!a && b) enc1_count--;
        else if (a && b) enc1_count += 2;
        else {
            fprintf(stderr, "Encoder invalid state (ENC1): a=%d b=%d\n", a, b);
            gpioDelay(SAMPLE_TIME_US);
            continue;
        }
        if (enc1_count > 100000) enc1_count = 0;
        else if (enc1_count < -100000) enc1_count = 0;
        gpioDelay(SAMPLE_TIME_US);
    }
    return NULL;
}

/* PID thread: computes PID output */
static void *pid_thread(void *arg) {
    (void)arg;
    while (running) {
        double current_speed = 0.0;
        double target_speed = TARGET_RPM;
        double error = target_speed - current_speed;

        pid_p = KP * error;
        pid_i += KI * error * (double)time_sleep(0.1);
        double derivative = (error - pid_prev_error) / (double)time_sleep(0.1);
        pid_d = KD * derivative;
        pid_output = pid_p + pid_i + pid_d;

        pid_prev_error = error;
        update_pid(current_speed, target_speed);
        gpioDelay(SAMPLE_TIME_US);
    }
    return NULL;
}

/* Stop all motors */
static void motor_stop_all(void) {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
}

/* Forward motion for a motor */
static void motor_forward(int speed) {
    if (speed > 0) {
        gpioWrite(MOTOR1_IN1, 1);
        gpioWrite(MOTOR1_IN2, 0);
        gpioWrite(MOTOR2_IN3, 1);
        gpioWrite(MOTOR2_IN4, 0);
        set_motor_speed(1, speed);
    } else if (speed < 0) {
        motor_backward(-speed);
    }
}

/* Backward motion for a motor */
static void motor_backward(int speed) {
    if (speed > 0) {
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 1);
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 1);
        set_motor_speed(2, speed);
    } else if (speed < 0) {
        motor_forward(-speed);
    }
}

/* Stop all motors */
static void motor_stop(void) {
    motor_forward(0);
    motor_backward(0);
}

/* Set motor speed (0 = stop, 1 = forward, 2 = backward) */
static void set_motor_speed(int motor, int speed) {
    int in1, in2;
    if (motor == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
    } else {
        in1 = MOTOR2_IN3;
        in2 = MOTOR2_IN4;
    }
    if (speed > 0) {
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
    } else if (speed < 0) {
        gpioWrite(in1, 0);
        gpioWrite(in2, 1);
    } else {
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
    }
}

/* Update PID state */
static void update_pid(double current_speed, double target_speed) {
    double error = target_speed - current_speed;
    pid_p = KP * error;
    pid_i += KI * error * (double)time_sleep(0.1);
    double derivative = (error - pid_prev_error) / (double)time_sleep(0.1);
    pid_d = KD * derivative;
    pid_output = pid_p + pid_i + pid_d;
    pid_prev_error = error;
}

/* Log data to CSV file */
static void log_data(double motor1_speed, double motor2_speed,
                     double pid_p, double pid_i, double pid_d, double pid_output) {
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                motor1_speed, motor2_speed, pid_p, pid_i, pid_d, pid_output);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open log file */
    log_file = fopen("motor_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,PID_P,PID_I,PID_D,PID_Output\n");
        fflush(log_file);
    }

    /* Configure GPIO pins */
    if (gpioSetMode(MOTOR1_ENA, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENB, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return 1;
    }

    /* Configure encoder pins as inputs with pull-down */
    if (gpioSetMode(ENC1_A, PI_INPUT) < 0 ||
        gpioSetMode(ENC1_B, PI_INPUT) < 0 ||
        gpioSetMode(ENC2_A, PI_INPUT) < 0 ||
        gpioSetMode(ENC2_B, PI_INPUT)) {
        fprintf(stderr, "Failed to set encoder pin modes\n");
        cleanup();
        return 1;
    }
    gpioSetPullUpDown(ENC1_A, PI_PUD_DOWN);
    gpioSetPullUpDown(ENC1_B, PI_PUD_DOWN);
    gpioSetPullUpDown(ENC2_A, PI_PUD_DOWN);
    gpioSetPullUpDown(ENC2_B, PI_PUD_DOWN);

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQ_HZ) < 0 ||
        gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }
    if (gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return 1;
    }

    /* Initialize encoder counters */
    enc1_count = 0;
    enc2_count = 0;
    enc1_dir = true;
    enc2_dir = true;

    /* Create encoder thread */
    pthread_t encoder_tid;
    if (pthread_create(&encoder_tid, NULL, encoder_thread, NULL) != 0) {
        perror("Failed to create encoder thread");
        cleanup();
        return 1;
    }

    /* Create PID thread */
    pthread_t pid_tid;
    if (pthread_create(&pid_tid, NULL, pid_thread, NULL) != 0) {
        perror("Failed to create PID thread");
        running = 0;
        pthread_join(encoder_tid, NULL);
        cleanup();
        return 1;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Main loop */
    while (running) {
        double current_speed1 = 0.0, current_speed2 = 0.0;
        double target_speed = TARGET_RPM;

        /* Read encoder counts */
        int enc1_val = gpioRead(ENC1_A);
        int enc2_val = gpioRead(ENC2_A);
        if (enc1_val < 0 || enc2_val < 0) {
            fprintf(stderr, "Encoder read error: enc1=%d enc2=%d\n", enc1_val, enc2_val);
            gpioDelay(SAMPLE_TIME_US);
            continue;
        }
        enc1_count = enc1_val;
        enc2_count = enc2_val;

        /* Compute motor speeds */
        current_speed1 = (double)enc1_count / 100000.0 * TARGET_RPM;
        current_speed2 = (double)enc2_count / 100000.0 * TARGET_RPM;

        /* Update PID */
        update_pid(current_speed1, target_speed);
        update_pid(current_speed2, target_speed);

        /* Set motor speeds */
        set_motor_speed(1, (int)pid_output);
        set_motor_speed(2, (int)pid_output);

        /* Log data */
        log_data(current_speed1, current_speed2, pid_p, pid_i, pid_d, pid_output);

        gpioDelay(SAMPLE_TIME_US);
    }

    /* Graceful shutdown */
    running = 0;
    pthread_join(pid_tid, NULL);
    pthread_join(encoder_tid, NULL);
    motor_stop_all();
    cleanup();
    return 0;
}

