#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* GPIO pin definitions (BCM numbering) */
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

/* Timing constants (milliseconds) */
#define VALVE1_ON_MS  500
#define VALVE1_PAUSE_MS 5000
#define VALVE2_ON_MS  1000
#define VALVE2_PAUSE_MS 10000

/* Log file name */
#define LOG_FILE "valve_log.txt"

/* Global flag for graceful shutdown */
static volatile sig_atomic_t program_running = 1;

/* Signal handler for SIGINT and SIGTERM */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Generate an ISO-8601 timestamp string */
static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
}

/* Activate a valve for a given duration, logging the event */
static void activate_valve(int gpio_pin, int duration_ms) {
    char timestamp[32];
    get_timestamp(timestamp, sizeof(timestamp));

    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d HIGH (valve ON).\n", gpio_pin);
        return;
    }
    printf("[%s] Valve on GPIO %d activated for %d ms\n", timestamp, gpio_pin, duration_ms);

    gpioDelay(duration_ms * 1000); /* gpioDelay takes microseconds */

    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d LOW (valve OFF).\n", gpio_pin);
        return;
    }
    printf("[%s] Valve on GPIO %d deactivated\n", timestamp, gpio_pin);
}

/* Log an activation event to the log file */
static void log_activation(int gpio_pin, int duration_ms) {
    char timestamp[32];
    get_timestamp(timestamp, sizeof(timestamp));

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    if (fprintf(fp, "%s, GPIO %d, ON for %d ms\n", timestamp, gpio_pin, duration_ms) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: Error closing log file: %s\n", strerror(errno));
    }
}

/* Cleanup GPIO resources and close log file */
static void cleanup(void) {
    /* Ensure valves are OFF before releasing GPIO */
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);

    gpioTerminate();
}

int main(void) {
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs */
    if (gpioSetMode(VALVE1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", VALVE1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", VALVE2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure valves start in OFF state */
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);

    printf("Water distribution schedule started. Press Ctrl+C to exit.\n");

    /* Main schedule loop */
    while (program_running) {
        /* Activate Valve 1 */
        activate_valve(VALVE1_GPIO, VALVE1_ON_MS);
        log_activation(VALVE1_GPIO, VALVE1_ON_MS);

        /* Pause between Valve 1 and Valve 2 activations */
        gpioDelay(VALVE1_PAUSE_MS * 1000);

        /* Activate Valve 2 */
        activate_valve(VALVE2_GPIO, VALVE2_ON_MS);
        log_activation(VALVE2_GPIO, VALVE2_ON_MS);

        /* Pause between Valve 2 and Valve 1 activation */
        gpioDelay(VALVE2_PAUSE_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

