/*
 * MPR121 Capacitive Touch Sensor - Relay Toggle
 * Board: Raspberry Pi Zero W
 * Bus: I2C-1 (SDA=GPIO2, SCL=GPIO3)
 * Relay: GPIO17 (BCM)
 *
 * Build: gcc -O2 -Wall -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:   sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define MPR121_ADDR          0x5B
#define RELAY_GPIO           17
#define POLL_DELAY_US        100000   /* 100 ms */
#define STABILIZE_DELAY_US   100000   /* 100 ms stabilization after init */

/* MPR121 Register Map */
#define MPR121_TOUCHSTATUS   0x00
#define MPR121_ELECONFIG     0x5E
#define MPR121_MHD_R         0x2B
#define MPR121_NHD_R         0x2C
#define MPR121_NCL_R         0x2D
#define MPR121_FDL_R         0x2E
#define MPR121_E0TTH         0x41
#define MPR121_E0RTH         0x42
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_ECR           0x5E

/* ----------------------------- Globals ----------------------------------- */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static int  mpr121_write_reg(uint8_t reg, uint8_t value);
static int  mpr121_read_reg(uint8_t reg, uint8_t *value);
static int  mpr121_init(void);
static int  mpr121_read_touch_status(uint16_t *touch_status);
static void relay_toggle(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers ------------------------------- */

/* Write a single byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int mpr121_write_reg(uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(i2c_handle, reg, value) < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int mpr121_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ----------------------------- MPR121 init ------------------------------- */
static int mpr121_init(void)
{
    /* 1. Stop mode */
    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000); /* 1 ms settle */

    /* 2. Electrode configuration: 12 electrodes, baseline tracking */
    if (mpr121_write_reg(MPR121_ELECONFIG, 0x0C) < 0) return -1;

    /* 3. Touch and release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_E0TTH + 2 * i, 0x0F) < 0) return -1; /* touch */
        if (mpr121_write_reg(MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1; /* release */
    }

    /* 4. Debounce: 3 samples for both touch and release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* 5. Filter configuration (default) */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* 6. Enable 12 electrodes, baseline tracking, 16 µA electrode current */
    if (mpr121_write_reg(MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

/* ----------------------------- Touch status ------------------------------- */
static int mpr121_read_touch_status(uint16_t *touch_status)
{
    uint8_t lo = 0, hi = 0;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS, &lo) < 0) return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS + 1, &hi) < 0) return -1;
    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ----------------------------- Relay control ------------------------------- */
static void relay_toggle(void)
{
    int current = gpioRead(RELAY_GPIO);
    if (current < 0) {
        fprintf(stderr, "gpioRead failed on relay GPIO %d: %s\n",
                RELAY_GPIO, pigpio_error(current));
        return;
    }
    current = !current;
    if (gpioWrite(RELAY_GPIO, current) < 0) {
        fprintf(stderr, "gpioWrite failed on relay GPIO %d: %s\n",
                RELAY_GPIO, pigpio_error(current));
    }
    printf("Relay toggled: %s\n", current ? "ON" : "OFF");
}

/* ----------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPR121_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0); /* Relay OFF at startup */

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle into stop mode */
    gpioDelay(STABILIZE_DELAY_US);

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay controller running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status; retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch_status > 0) {
            relay_toggle();
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

