#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define LOG_FILE "door_events.log"
#define POLL_INTERVAL_US 50000
#define UNLOCK_DURATION_US 500000
#define RATE_LIMIT_US 2000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld - %s\n", time_buf, ts.tv_nsec / 1000000, event_type);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on PIR pin\n");
        cleanup();
        return 1;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay to off\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return 1;
    }

    printf("Door strike system started. Press Ctrl+C to exit.\n");

    int last_state = 0;
    uint32_t last_unlock_tick = 0;
    uint32_t last_rate_tick = 0;

    while (running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "gpioRead failed on PIR pin\n");
            break;
        }

        if (pir_state == 1 && last_state == 0) {
            uint32_t now = gpioTick();
            if (now - last_unlock_tick >= RATE_LIMIT_US) {
                if (gpioWrite(RELAY_PIN, 1) != 0) {
                    fprintf(stderr, "Failed to activate relay\n");
                    break;
                }
                last_unlock_tick = now;
                log_event("Motion Detected - Door Unlocked");
                printf("Door unlocked.\n");
            }
        }

        if (pir_state == 1 && last_state == 0) {
            if (now - last_rate_tick >= RATE_LIMIT_US) {
                last_rate_tick = now;
                log_event("Motion Detected - Rate Limiting Enforced");
                printf("Motion detected, rate-limiting enforced.\n");
            }
        }

        last_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

