#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define READ_TIMEOUT_US 500000
#define NUM_CALIBRATION_READINGS 100
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, int *out_value) {
    int data = 0;
    int i;

    if (gpioSetMode(data_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) return -1;

    gpioWrite(clock_pin, 0);
    gpioDelay(10);

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(data_pin)) {
            data |= 1;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    if (gpioWrite(clock_pin, 1) < 0) return -1;
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    *out_value = data;
    return 0;
}

static double calculate_weight(int raw_value) {
    return (double)(raw_value - offset) / scale_factor;
}

static int load_calibration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s. Using defaults.\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    scale_factor = 1.0;
    offset = 0.0;

    while (fgets(line, sizeof(line), fp)) {
        char *endptr;
        scale_factor = strtod(line, &endptr);
        if (endptr != line) {
            offset = strtod(line, &endptr);
            break;
        }
    }

    fclose(fp);
    if (scale_factor == 0.0) {
        fprintf(stderr, "Warning: calibration file contains only whitespace. Using defaults.\n");
        return -1;
    }
    return 0;
}

static int save_calibration(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s for writing: %s\n",
                filename, strerror(errno));
        return -1;
    }
    fprintf(fp, "%.6f %.6f\n", scale_factor, offset);
    fclose(fp);
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin, int num_readings) {
    int raw_sum = 0;
    int valid_readings = 0;

    printf("Calibrating HX711 for %d readings...\n", num_readings);
    for (int i = 0; i < num_readings; i++) {
        if (running) {
            int raw;
            if (read_hx711(data_pin, clock_pin, &raw) == 0) {
                raw_sum += raw;
                valid_readings++;
            } else {
                fprintf(stderr, "Error reading HX711 during calibration.\n");
                return -1;
            }
        }
        gpioDelay(100000);
    }

    if (valid_readings == 0) {
        fprintf(stderr, "Error: no valid HX711 readings during calibration.\n");
        return -1;
    }

    double avg_raw = (double)raw_sum / valid_readings;
    scale_factor = (double)(avg_raw - offset) / (double)valid_readings;
    offset = avg_raw - (scale_factor * valid_readings) / 2.0;

    printf("Calibration complete. scale_factor=%.6f, offset=%.6f\n",
           scale_factor, offset);
    return 0;
}

static int engage_solenoid(int pin) {
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d high.\n", pin);
        return -1;
    }
    gpioDelay(500000);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d low.\n", pin);
        return -1;
    }
    gpioDelay(500000);
    return 0;
}

static void log_data(double weight) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", SOLENOID_PIN);
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    if (load_calibration(CALIBRATION_FILE) < 0) {
        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, NUM_CALIBRATION_READINGS) < 0) {
            fprintf(stderr, "Error: calibration failed.\n");
            gpioTerminate();
            return 1;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Starting weight monitoring. Threshold: %.1f kg\n", WEIGHT_THRESHOLD);

    while (running) {
        int raw_value;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) < 0) {
            fprintf(stderr, "Error: HX711 read timeout.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double weight = calculate_weight(raw_value);
        printf("Raw: %d, Weight: %.2f kg\n", raw_value, weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Engaging solenoid.\n");
            if (engage_solenoid(SOLENOID_PIN) < 0) {
                fprintf(stderr, "Error: failed to engage solenoid.\n");
            }
            log_data(weight);
        }

        log_data(weight);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
    return 0;
}

