#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define RAIN_THRESHOLD 3
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define MOTOR_RUN_TIME_US 5000000
#define SENSOR_CHECK_INTERVAL_S 60
#define POST_CLOSE_WAIT_S 60

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_buffer[256];
    snprintf(log_buffer, sizeof(log_buffer), "%s: %s\n", timestamp, message);

    FILE *fp = fopen("/var/log/window_control.log", "a");
    if (fp != NULL) {
        fputs(log_buffer, fp);
        fclose(fp);
    } else {
        syslog(LOG_ERR, "Failed to open log file: %s", log_buffer);
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        return -1;
    }

    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 pin mode");
        return -1;
    }

    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 pin mode");
        return -1;
    }

    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor PWM pin mode");
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_PWM_PIN, 255) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
        return -1;
    }

    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set initial PWM duty cycle");
        return -1;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set pull-up on rain sensor pin");
        return -1;
