#include <string.h>
#include <errno.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD_GRAMS 100.0
#define LOCK_DURATION_SEC 5
#define LOG_FILE "stock_events.txt"
#define READ_TIMEOUT_US 1000000
#define LOOP_DELAY_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int read_hx711(int dt_pin, int sck_pin, int *out_value) {
    if (gpioSetMode(dt_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(sck_pin, PI_OUTPUT) < 0) return -1;

    int timeout = 0;
    while (gpioRead(dt_pin) == 1) {
        gpioDelay(100);
        timeout += 100;
        if (timeout > READ_TIMEOUT_US) return -2;
    }

    int data = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(dt_pin)) data |= 1;
        gpioWrite(sck_pin, 0);
        gpioDelay(1);
    }

    if (data & 0x800000) data |= ~0xffffff;
    *out_value = data;
    return 0;
}

static int activate_solenoid(int pin, int duration_sec) {
    if (gpioWrite(pin, 1) < 0) return -1;
    gpioDelay(duration_sec * 1000000);
    if (gpioWrite(pin, 0) < 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize solenoid pin state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (running) {
        int weight = 0;
        int rc = read_hx711(HX711_DT_PIN, HX711_SCK_PIN, &weight);
        if (rc != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "HX711 read error: %d", rc);
            log_event(msg);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (weight == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "HX711 returned zero, skipping weight check");
            log_event(msg);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight_g = (double)weight / 16.0;
        char msg[128];
        snprintf(msg, sizeof(msg), "Weight: %.2f g", weight_g);
        log_event(msg);

        if (weight_g < WEIGHT_THRESHOLD_GRAMS) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Weight below threshold, activating solenoid");
            log_event(msg);
            if (activate_solenoid(SOLENOID_PIN, LOCK_DURATION_SEC) < 0) {
                log_event("Failed to activate solenoid");
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    log_event("Program exiting");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

