#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0
#define CALIBRATION_TIMEOUT_MS 100
#define SOLENOID_HOLD_MS 5
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, int *raw_out) {
    int i;
    int value = 0;
    int timeout = 0;

    /* Wait for data line to go low (data ready) */
    while (gpioRead(data_pin) == 1) {
        gpioDelay(1);
        if (++timeout > CALIBRATION_TIMEOUT_MS) {
            return -1;
        }
    }

    /* Read 24 bits MSB first */
    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(data_pin)) {
            value |= 1;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    /* 25th clock pulse: set gain to 128 for next reading */
    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    /* Sign-extend 24-bit value to 32-bit */
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *raw_out = value;
    return 0;
}

static double calibrate_hx711(int data_pin, int clock_pin) {
    int raw;
    double weight;
    double known_weight;

    printf("Place a known weight on the load cell and press Enter...\n");
    fflush(stdout);
    getchar();

    if (read_hx711(data_pin, clock_pin, &raw) != 0) {
        fprintf(stderr, "Error: HX711 communication timeout during calibration.\n");
        return -1.0;
    }

    printf("Known weight: %d\n", raw);
    fflush(stdout);

    known_weight = (double)raw / calibration_factor;
    if (known_weight <= 0.0) {
        fprintf(stderr, "Error: Calibration factor is zero or negative.\n");
        return -1.0;
    }

    calibration_factor = 1.0 / known_weight;
    printf("Calibration factor updated: %.6f\n", calibration_factor);
    fflush(stdout);

    return known_weight;
}

static void unlock_solenoid(int solenoid_pin) {
    if (gpioWrite(solenoid_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin high.\n");
        return;
    }
    gpioDelay(SOLENOID_HOLD_MS * 1000);
    if (gpioWrite(solenoid_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin low.\n");
    }
}

static void log_event(double weight) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Weight: %.2f kg\n", timestamp, weight);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
}

int main(void) {
    int raw;
    double weight;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(DATA_PIN, PI_INPUT) != 0 ||
        gpioSetMode(CLOCK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialise solenoid pin low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        if (read_hx711(DATA_PIN, CLOCK_PIN, &raw) != 0) {
            fprintf(stderr, "Error: HX711 read failed. Retrying in 1 second.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        weight = (double)raw / calibration_factor;
        printf("Weight: %.2f kg\n", weight);
        fflush(stdout);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Unlocking solenoid.\n");
            fflush(stdout);
            unlock_solenoid(SOLENOID_PIN);
            log_event(weight);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

