#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Relay: %s\n", timestamp, state) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_PIN (GPIO%d) as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN (GPIO%d) as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise RELAY_PIN to LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    int relay_state = 0;
    int last_sensor_value = -1;

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading SENSOR_PIN (GPIO%d)\n", SENSOR_PIN);
            gpioDelay(100000);
            continue;
        }

        if (sensor_value != last_sensor_value) {
            if (sensor_value == 0) {
                /* Obstacle detected (active-low) */
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error writing to RELAY_PIN (GPIO%d)\n", RELAY_PIN);
                } else {
                    if (log_event(relay_state ? "ON" : "OFF") != 0) {
                        fprintf(stderr, "Warning: failed to log relay state change\n");
                    }
                }
            } else {
                /* No obstacle */
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error writing to RELAY_PIN (GPIO%d)\n", RELAY_PIN);
                }
            }

            last_sensor_value = sensor_value;
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

