#include <string.h>
#include <errno.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define BUZZER_DURATION_US 2000000  /* 2 seconds in microseconds */
#define LOG_FILE "motion_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_motion(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[64];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_buzzer(int duration_us) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(BUZZER_PIN, 1) failed\n");
        return -1;
    }

    usleep(duration_us);

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(BUZZER_PIN, 0) failed\n");
        return -1;
    }

    return 0;
}

