#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define VALVE_GPIO 18
#define CONFIG_FILE "watering.conf"
#define MIN_DURATION 1
#define MAX_DURATION 3600
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_watering_duration(const char *filename, int *duration_out) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *eq = strchr(line, '=');
    if (!eq) {
        fprintf(stderr, "Error: missing duration in %s\n", filename);
        return -1;
    }
    *eq = '\0';

    char *endptr;
    long val = strtol(line, &endptr, 10);
    if (endptr == line || *endptr != '\0') {
        fprintf(stderr, "Error: malformed duration in %s\n", filename);
        return -1;
    }
    if (val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Error: duration %ld out of range [%d, %d]\n", val, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration_out = (int)val;
    return 0;
}

static int activate_valve(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error writing GPIO %d high: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    printf("Valve activated on GPIO %d\n", gpio_pin);
    return 0;
}

static int deactivate_valve(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error writing GPIO %d low: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    printf("Valve deactivated on GPIO %d\n", gpio_pin);
    return 0;
