/*
 * Line-following robot for Raspberry Pi Zero W
 * Sensor : Keywish 3-Way IR Tracking Sensor (active-low digital)
 * Driver : L298N dual H-bridge (via pigpio)
 *
 * Wiring (BCM numbering):
 *   Left sensor  -> GPIO4
 *   Middle sensor -> GPIO17
 *   Right sensor  -> GPIO27
 *   Motor A       -> GPIO22 (PWM)
 *   Motor B       -> GPIO23 (PWM)
 *   Motor C       -> GPIO24 (PWM)
 *   Motor D       -> GPIO25 (PWM)
 *
 * Control law:
 *   - Middle sensor low  -> straight ahead  (base speed 150)
 *   - Left sensor low    -> turn right  (left speed 50, right speed 100)
 *   - Right sensor low   -> turn left  (left speed 100, right speed 50)
 *   - All sensors high  -> stop motors
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define MOTOR_A_PIN    22
#define MOTOR_B_PIN    23
#define MOTOR_C_PIN    24
#define MOTOR_D_PIN    25

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define SAMPLE_DELAY_US 10000   /* 10 ms */
#define LOOP_DELAY_US  10000    /* 10 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop all motor PWM outputs */
    gpioPWM(MOTOR_A_PIN, 0);
    gpioPWM(MOTOR_B_PIN, 0);
    gpioPWM(MOTOR_C_PIN, 0);
    gpioPWM(MOTOR_D_PIN, 0);

    /* Release pigpio resources */
    gpioTerminate();

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Log a control cycle with timestamp                                    */
/* ------------------------------------------------------------------ */
static void log_control_cycle(int left, int mid, int right,
                              int left_speed, int right_speed)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file,
            "%s, Left: %d, Middle: %d, Right: %d, Left Motor: %d, Right Motor: %d\n",
            timestamp, left, mid, right, left_speed, right_speed);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Control logic                                                          */
/* ------------------------------------------------------------------ */
static void control_robot(int left, int mid, int right)
{
    int left_speed, right_speed;

    if (mid == 0) {
        /* Middle sensor low: straight ahead */
        left_speed = 150;
        right_speed = 150;
    } else if (left == 0) {
        /* Left sensor low: turn right */
        left_speed = 50;
        right_speed = 100;
    } else if (right == 0) {
        /* Right sensor low: turn left */
        left_speed = 100;
        right_speed = 50;
    } else {
        /* All sensors high: stop */
        left_speed = 0;
        right_speed = 0;
    }

    gpioPWM(MOTOR_A_PIN,  left_speed);
    gpioPWM(MOTOR_B_PIN,  right_speed);
    gpioPWM(MOTOR_C_PIN,  left_speed);
    gpioPWM(MOTOR_D_PIN,  right_speed);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int left, mid, right;
    int ret;

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure motor pins as outputs --- */
    ret = gpioSetMode(MOTOR_A_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(MOTOR_A_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetMode(MOTOR_B_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(MOTOR_B_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetMode(MOTOR_C_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(MOTOR_C_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetMode(MOTOR_D_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(MOTOR_D_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    ret = gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(LEFT_SENSOR_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(MIDDLE_SENSOR_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(RIGHT_SENSOR_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Set PWM frequency and range --- */
    ret = gpioSetPWMfrequency(MOTOR_A_PIN, PWM_FREQUENCY);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(MOTOR_A_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMfrequency(MOTOR_B_PIN, PWM_FREQUENCY);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(MOTOR_B_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMfrequency(MOTOR_C_PIN, PWM_FREQUENCY);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(MOTOR_C_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMfrequency(MOTOR_D_PIN, PWM_FREQUENCY);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(MOTOR_D_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMrange(MOTOR_A_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(MOTOR_A_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMrange(MOTOR_B_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(MOTOR_B_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMrange(MOTOR_C_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(MOTOR_C_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMrange(MOTOR_D_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(MOTOR_D_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen("trace_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    /* --- Main control loop --- */
    while (g_running) {
        left  = gpioRead(LEFT_SENSOR_PIN);
        mid   = gpioRead(MIDDLE_SENSOR_PIN);
        right = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || mid < 0 || right < 0) {
            fprintf(stderr, "Error: gpioRead failed (L=%d M=%d R=%d).\n", left, mid, right);
            break;
        }

        control_robot(left, mid, right);
        log_control_cycle(left, mid, right,
                          gpioGetPWMdutycycle(MOTOR_A_PIN),
                          gpioGetPWMdutycycle(MOTOR_B_PIN));

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

