    ret = gpioSetPWMrange(MOTOR_C_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(MOTOR_C_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWMrange(MOTOR_D_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(MOTOR_D_PIN) failed (code %d).\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen("trace_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    /* --- Main control loop --- */
    while (g_running) {
        left  = gpioRead(LEFT_SENSOR_PIN);
        mid   = gpioRead(MIDDLE_SENSOR_PIN);
        right = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || mid < 0 || right < 0) {
            fprintf(stderr, "Error: gpioRead failed (L=%d M=%d R=%d).\n", left, mid, right);
            break;
        }

        control_robot(left, mid, right);
        log_control_cycle(left, mid, right,
                          gpioGetPWMdutycycle(MOTOR_A_PIN),
                          gpioGetPWMdutycycle(MOTOR_B_PIN));

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

