#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x54
#define RELAY_GPIO     23
#define LUX_THRESHOLD  150.0f
#define LOG_FILE       "grow_log.txt"
#define MEASUREMENT_MS 180
#define POLL_DELAY_US  1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_pigpio_ready = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int read_lux(float *lux_out) {
    uint8_t cmd = 0x10;
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        log_message("Error: BH1750 measurement command failed");
        return -1;
    }
    usleep(MEASUREMENT_MS * 1000);

    uint8_t buf[2];
    if (read(g_i2c_fd, buf, 2) != 2) {
        log_message("Error: BH1750 data read failed");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int on) {
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) < 0) {
        log_message("Error: Failed to write relay GPIO");
    }
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_pigpio_ready) {
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        g_pigpio_ready = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }
    g_pigpio_ready = 1;

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return 1;
    }
    control_relay(0);

    log_message("Program started");

    while (g_running) {
        float lux;
        if (read_lux(&lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_message(msg);

            if (lux < LUX_THRESHOLD) {
                control_relay(1);
                snprintf(msg, sizeof(msg), "Lux below threshold, relay ON");
                log_message(msg);
            } else {
                control_relay(0);
                snprintf(msg, sizeof(msg), "Lux above threshold, relay OFF");
                log_message(msg);
            }
        } else {
            log_message("Sensor read failed, retrying");
        }
        usleep(POLL_DELAY_US);
    }

    log_message("Program shutting down");
    cleanup();
    return 0;
}

