#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define DEBOUNCE_DELAY_US 100000
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_PULSE_WIDTH_LOCK 1000
#define SERVO_PULSE_WIDTH_UNLOCK 2000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_PULSE_WIDTH) angle = SERVO_MIN_PULSE_WIDTH;
    if (angle > SERVO_MAX_PULSE_WIDTH) angle = SERVO_MAX_PULSE_WIDTH;
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 100);
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse width %d\n", pulse_width);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", LOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", LOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(LOCK_BUTTON_PIN, signal_handler) < 0) {
        fprintf(stderr, "Error: failed to set alert function for lock button\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(UNLOCK_BUTTON_PIN, signal_handler) < 0) {
        fprintf(stderr, "Error: failed to set alert function for unlock button\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            printf("Lock button pressed. Setting servo to lock position.\n");
            if (set_servo_angle(SERVO_PULSE_WIDTH_LOCK) == 0) {
                gpioDelay(1000000);
            }
        }
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            printf("Unlock button pressed. Setting servo to unlock position.\n");
            if (set_servo_angle(SERVO_PULSE_WIDTH_UNLOCK) == 0) {
                gpioDelay(1000000);
            }
        }
        gpioDelay(100000);
    }

    printf("\nExiting gracefully...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

