/*
 * Haptic feedback system for Raspberry Pi 4 Model B
 *
 * Two Precision Microdrives 310-101 vibration motors are pulsed sequentially
 * via external driver circuits (NPN transistor + flyback diode) on GPIO17 and
 * GPIO27.  The motors are driven for 200 ms and 300 ms, respectively, in a
 * repeated loop.  Error handling is robust: every driver library call is
 * checked for failure, and the GPIO lines are released on every exit path.
 *
 * Build:  gcc -O2 -Wall -Wextra -o haptic_pulse haptic_pulse.c -lpigpio -lrt
 * Run:    sudo ./haptic_pulse
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

#define MOTOR1_PULSE_US 200000   /* 200 ms */
#define MOTOR2_PULSE_US 300000   /* 300 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_pulse(unsigned pin, unsigned duration_us)
{
    if (safe_write(pin, 1) != 0)
        return -1;
    if (gpioDelay(duration_us) < 0) {
        fprintf(stderr, "Error: gpioDelay(%u) failed\n", duration_us);
        return -1;
    }
    if (safe_write(pin, 0) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure motors are stopped before releasing GPIO */
    safe_write(MOTOR1_PIN, 0);
    safe_write(MOTOR2_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (safe_set_mode(MOTOR1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Start with motors off --- */
    if (safe_write(MOTOR1_PIN, 0) != 0 ||
        safe_write(MOTOR2_PIN, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        /* Motor 1 pulse */
        if (safe_pulse(MOTOR1_PIN, MOTOR1_PULSE_US) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        /* Motor 2 pulse */
        if (safe_pulse(MOTOR2_PIN, MOTOR2_PULSE_US) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* --- Graceful shutdown --- */
    cleanup();
    return EXIT_SUCCESS;
}

