        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure motors are stopped before releasing GPIO */
    safe_write(MOTOR1_PIN, 0);
    safe_write(MOTOR2_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (safe_set_mode(MOTOR1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Start with motors off --- */
    if (safe_write(MOTOR1_PIN, 0) != 0 ||
        safe_write(MOTOR2_PIN, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        /* Motor 1 pulse */
        if (safe_pulse(MOTOR1_PIN, MOTOR1_PULSE_US) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        /* Motor 2 pulse */
        if (safe_pulse(MOTOR2_PIN, MOTOR2_PULSE_US) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* --- Graceful shutdown --- */
    cleanup();
    return EXIT_SUCCESS;
}

