#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"
#define SOUND_POLL_INTERVAL_US 10000
#define ALARM_DURATION_SEC 1
#define ZMQ_SOCKET_PORT 5555

static volatile sig_atomic_t g_running = 1;
static int g_zmq_socket = -1;
static int g_zmq_context = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d to LOW\n", ALARM_LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int init_zmq(void) {
    g_zmq_context = zmq_ctx_new();
    if (g_zmq_context < 0) {
        fprintf(stderr, "Failed to create ZeroMQ context\n");
        return -1;
    }

    g_zmq_socket = zmq_socket(g_zmq_context, ZMQ_PUB);
    if (g_zmq_socket < 0) {
        fprintf(stderr, "Failed to create ZeroMQ socket\n");
        zmq_ctx_destroy(g_zmq_context);
        g_zmq_context = -1;
        return -1;
    }

    int rc = zmq_bind(g_zmq_socket, "tcp://*:5555");
    if (rc != 0) {
        fprintf(stderr, "Failed to bind ZeroMQ socket: %s\n", strerror(rc));
        zmq_close(g_zmq_socket);
        g_zmq_socket = -1;
        zmq_ctx_destroy(g_zmq_context);
        g_zmq_context = -1;
        return -1;
    }

    return 0;
}

static int publish_sound_alert(void) {
    char message[128];
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    if (strftime(message, sizeof(message), "Sound detected at %Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        return -1;
    }

    if (zmq_send(g_zmq_socket, message, strlen(message), 0) < 0) {
        fprintf(stderr, "Failed to send ZeroMQ message: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int alarm_node(void) {
    int rc = zmq_connect(g_zmq_socket, "tcp://localhost:5555");
    if (rc != 0) {
        fprintf(stderr, "Failed to connect to ZeroMQ socket: %s\n", strerror(rc));
        return -1;
    }

    printf("Alarm node: Subscribed to %s\n", SOUND_ALERTS_TOPIC);

    char message[128];
    while (g_running) {
        if (zmq_recv(g_zmq_socket, message, sizeof(message) - 1, 0) < 0) {
            fprintf(stderr, "Failed to receive ZeroMQ message: %s\n", strerror(errno));
            break;
        }

        printf("Received alert: %s\n", message);

        if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
            fprintf(stderr, "Failed to turn on alarm LED\n");
            break;
        }

        sleep(ALARM_DURATION_SEC);

        if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
            fprintf(stderr, "Failed to turn off alarm LED\n");
            break;
        }
    }

    zmq_close(g_zmq_socket);
    g_zmq_socket = -1;
    g_zmq_context = -1;
    return 0;
}

static int sound_sensor_mode(void) {
    printf("Sound sensor mode: Polling GPIO%d every %d ms for sound events...\n",
           SOUND_SENSOR_PIN, SOUND_POLL_INTERVAL_US / 1000);

    while (g_running) {
        int level = gpioRead(SOUND_SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", SOUND_SENSOR_PIN);
            break;
        }

        if (level == 0) {
            if (publish_sound_alert() != 0) {
                fprintf(stderr, "Failed to publish sound alert\n");
            }
        }

        usleep(SOUND_POLL_INTERVAL_US);
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int mode = -1;

    if (argc > 1) {
        if (strcmp(argv[1], "sound_sensor") == 0) {
            mode = SOUND_SENSOR_MODE;
        } else if (strcmp(argv[1], "alarm_node") == 0) {
            mode = ALARM_NODE_MODE;
        } else {
            fprintf(stderr, "Invalid mode: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_zmq() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mode == SOUND_SENSOR_MODE) {
        if (sound_sensor_mode() != 0) {
            zmq_close(g_zmq_socket);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    } else if (mode == ALARM_NODE_MODE) {
        if (alarm_node() != 0) {
            zmq_close(g_zmq_socket);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    zmq_close(g_zmq_socket);
    g_zmq_socket = -1;
    g_zmq_context = -1;
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

