#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x44
#define BH1750_CMD_START_CONVERSION 0x10
#define BH1750_CONV_WAIT_MS 180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed (sensor 0x%02X): %s\n",
                byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *out) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed (sensor 0x%02X): %s\n",
                n < 0 ? n : 0, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float read_lux(int fd) {
    if (i2c_write_byte(fd, BH1750_CMD_START_CONVERSION) < 0)
        return NAN;
    usleep(BH1750_CONV_WAIT_MS * 1000);
    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0)
        return NAN;
    return (float)raw;
}

static int send_multicast(int sock, const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sock, data, strlen(data), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int i2c_fds[NUM_SENSORS];
    int sockfd = -1;
    int i;

    for (i = 0; i < NUM_SENSORS; i++)
        i2c_fds[i] = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = open(I2C_BUS, O_RDWR);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
            for (int j = 0; j < i; j++) close(i2c_fds[j]);
            return 1;
        }
        if (ioctl(i2c_fds[i], I2C_SLAVE, BH1750_ADDR) < 0) {
            fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                    BH1750_ADDR, strerror(errno));
            close(i2c_fds[i]);
            for (int j = 0; j < i; j++) close(i2c_fds[j]);
            return 1;
        }
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket failed: %s\n", strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] >= 0) close(i2c_fds[i]);
        }
        return 1;
    }

    unsigned char multicast_addr[4];
    multicast_addr[0] = (unsigned char)(sizeof(struct in6_addr) - 1);
    multicast_addr[1] = (unsigned char)(sizeof(struct in6_addr) - 2);
    multicast_addr[2] = (unsigned char)(sizeof(struct in6_addr) - 3);
    multicast_addr[3] = 1;
    memcpy(&multicast_addr[4], MULTICAST_ADDR, 4);
    multicast_addr[4] = htonl(htons(MULTICAST_PORT));

    while (!terminate) {
        char data[128];
        int ok = 1;
        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux = read_lux(i2c_fds[i]);
            if (isnan(lux)) {
                snprintf(data + i * 4, 4, "0,");
            } else {
                snprintf(data + i * 4, 4, "%d,%.2f", i + 1, lux);
            }
        }
        data[NUM_SENSORS * 4] = '\0';

        if (send_multicast(sockfd, data) < 0) {
            fprintf(stderr, "Failed to send multicast packet\n");
        } else {
            printf("Sent: %s\n", data);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) close(i2c_fds[i]);
    }
    if (sockfd >= 0) close(sockfd);
    printf("\nTerminated cleanly.\n");
    return 0;
}

