#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x48
#define LOG_FILE       "airflow_log.txt"
#define READ_RETRIES   3
#define RETRY_DELAY_MS 100
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_zero_length(int fd)
{
    if (write(fd, NULL, 0) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) {
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_rate)
{
    uint8_t data[2];
    int retries = 0;

    while (retries < READ_RETRIES) {
        if (i2c_write_zero_length(fd) < 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n",
                    retries + 1, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (i2c_read_bytes(fd, data, sizeof(data)) < 0) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n",
                    retries + 1, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
        uint16_t flow = raw & 0x3FFF;
        *flow_rate = (float)flow / 10.0f;
        return 0;
    }

    fprintf(stderr, "Failed to read flow rate after %d retries.\n", READ_RETRIES);
    return -1;
}

static void log_data(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed.\n");
        return;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                AWM7300V_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n",
                LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("AWM7300V airflow logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow_rate;
        if (read_flow_rate(g_i2c_fd, &flow_rate) == 0) {
            log_data(g_log_fp, flow_rate);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) != 0) {
            fprintf(stderr, "close I2C fd failed: %s\n", strerror(errno));
        }
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

