#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 512
#define READ_TIMEOUT_SEC 2
#define LINE_TIMEOUT_SEC 0.5
#define MAX_RANGE 100.0f

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud_rate);
    cfsetospeed(&tty, baud_rate);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10; /* 1 second inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart_line(int fd, char *line_buf, size_t buf_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = READ_TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int ret = select(fd + 1, &readfds, NULL, NULL, &timeout);
    if (ret < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "Error from select: %s\n", strerror(errno));
        return -1;
    }
    if (ret == 0) return 0; /* timeout */

    ssize_t n = read(fd, line_buf, buf_size - 1);
    if (n < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "Error from read: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) return 0; /* EOF */

    line_buf[n] = '\0';
    return 1;
}

static int parse_line(const char *line, float *range) {
    char *endptr = NULL;
    errno = 0;
    long val = strtol(line, &endptr, 10);

    if (errno != 0 || endptr == line) return -1;

    if (val < 0 || val > MAX_RANGE) return -1;

    *range = (float)val;
    return 0;
}

static void print_detection(float range) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error from localtime_r\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error from sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error from sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    float range;

    while (g_running) {
        int ret = read_uart_line(g_uart_fd, line_buf, sizeof(line_buf));
        if (ret < 0) {
            fprintf(stderr, "UART read error, exiting\n");
            break;
        }
        if (ret == 0) {
            continue; /* timeout, no data */
        }

        if (strchr(line_buf, '\n') == NULL) {
            fprintf(stderr, "No newline found, skipping line\n");
            continue;
        }

        if (parse_line(line_buf, &range) == 0) {
            print_detection(range);
        } else {
            fprintf(stderr, "Invalid data: %s\n", line_buf);
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    return 0;
}

