#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(val));
        return -1;
    }
    return val;
}

static int log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    return 0;
}

static int send_emergency_stop(void) {
    char message[64];
    snprintf(message, sizeof(message), "EMERGENCY STOP!\n");

    if (uart_fd < 0) {
        fprintf(stderr, "UART not initialized\n");
        return -1;
    }

    size_t total = strlen(message);
    size_t written = 0;
    while (written < total) {
        ssize_t n = write(uart_fd, message + written, total - written);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "UART write error: %s\n", strerror(errno));
            return -1;
        }
        written += (size_t)n;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set LEFT_SENSOR_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MIDDLE_SENSOR_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set RIGHT_SENSOR_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on LEFT_SENSOR_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on MIDDLE_SENSOR_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on RIGHT_SENSOR_PIN\n");
        gpioTerminate();
        return 1;
    }

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        fprintf(stderr, "Error opening UART device %s: %s\n", UART_DEVICE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (fcntl(uart_fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NDELAY: %s\n", strerror(errno));
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    if (fcntl(uart_fd, F_SETFL, F_WRTOBJ) < 0) {
        fprintf(stderr, "Error setting O_NONBLOCK: %s\n", strerror(errno));
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    if (fcntl(uart_fd, F_SETFL, F_UNBLOCK) < 0) {
        fprintf(stderr, "Error unblocking UART: %s\n", strerror(errno));
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(uart_fd, B9200, 1) < 0) {
        fprintf(stderr, "Error setting baud rate: %s\n", strerror(errno));
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    printf("KY-033 3-Way Tracking Sensor Monitor\n");
    printf("Left: GPIO%d, Middle: GPIO%d, Right: GPIO%d\n", LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("UART: %s @ 115200 baud, 8N1\n", UART_DEVICE);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
        } else {
            log_sensor_data(left, middle, right);
            if (left == 0 && middle == 0 && right == 0) {
                send_emergency_stop();
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    gpioTerminate();
    return 0;
}

